INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('0015c9ea-2aa2-4fcb-9d7e-e3530f233e06', 'Clean con Kettlebell doble', 29, 6, 281, 1, 'Intermedio', 'Lleva dos Kettlebells desde el suelo hasta la posición de rack en el pecho en un movimiento explosivo de cadera.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double Kettlebell Clean', 'Bring two kettlebells from the floor to the chest rack position in an explosive hip movement.', 'external'),
('0036af74-b2f1-4aa4-8b85-cc3a2143686d', 'Parada de manos cara a la pared', 6, 2, 1, 1, 'Avanzado', 'Camina con los pies por la pared hacia arriba mientras acercas las manos a la pared hasta quedar en posición vertical invertida.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Handstand facing the wall', 'Walk your feet up the wall while bringing your hands closer to the wall until you are in an inverted vertical position.', 'bodyweight'),
('0058dd3e-f93e-49b1-9155-17c0baf06ae3', 'Dead Clean a Press Overhead con Kettlebell a una mano Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'Lleva la pesa invertida desde el suelo hasta el hombro y presionala sobre la cabeza, desafiando el agarre en cada fase del movimiento.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Dead Clean a Press Overhead with One-Handed Kettlebell Bottoms Up', 'Bring the dumbbell inverted from the floor to your shoulder and press it overhead, challenging your grip in each phase of the movement.', 'external'),
('007dfc37-a855-491b-a295-166525cb73c4', 'Press militar sentado en máquina Smith', 6, 2, 186, 1, 'Principiante', 'Sentado, empuja la barra guiada de la Smith sobre la cabeza. Objetivo: deltoides con trayectoria controlada. Cue: espalda plana contra el banco. Error común: arquear la lumbar al final del recorrido.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Smith Machine Seated Military Press', 'Sitting, push the Smith''s guided bar overhead. Target: deltoids with controlled trajectory. Cue: back flat against the bench. Common mistake: arching the lower back at the end of the stroke.', 'external'),
('008f9175-b9dc-4ce5-a59c-fc773720ef77', 'Peso muerto sumo mancuernas', 29, 28, 81, 1, 'Intermedio', 'Adopta una postura amplia con los pies apuntando hacia afuera. Sujeta una mancuerna con ambas manos entre las piernas. Desciende manteniendo el pecho erguido y las rodillas alineadas con los pies. Esta variación enfatiza más glúteos y aductores.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell sumo deadlift', 'Take a wide stance with your feet pointing outward. Hold a dumbbell with both hands between your legs. Descend, keeping your chest up and your knees in line with your feet. This variation emphasizes more glutes and adductors.', 'external'),
('00b278c0-12c7-436d-bfd9-fe6d8888b27c', 'Sentadilla búlgara con barra', 28, 29, 116, 1, 'Avanzado', 'Sentadilla búlgara (split squat) con barra en la espalda. Aumenta significativamente la intensidad. Requiere gran equilibrio y estabilización. Comienza con peso ligero. Excelente para corregir desequilibrios musculares.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bulgarian barbell squat', 'Bulgarian squat (split squat) with a bar on the back. Significantly increases intensity. It requires great balance and stabilization. Start with light weight. Excellent for correcting muscle imbalances.', 'external'),
('00bb8e11-aa0c-418c-80cc-9de008dc5814', 'Rotación externa de cadera a una pierna con banda', 29, 37, 61, 1, 'Principiante', 'De pie sobre una pierna con la rodilla flexionada y una banda anclada, rota la cadera hacia afuera resistiendo la banda.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-leg hip external rotation with band', 'Standing on one leg with your knee bent and a band anchored, rotate your hip outward resisting the band.', 'external'),
('00e93873-2ea5-463b-96da-4a7c5fd8c315', 'Burpee slam', 13, NULL, 240, 1, 'Avanzado', 'Combina un burpee completo con un slam ball. Realiza el slam, coloca las manos en el balón, salta a plancha, flexión opcional, vuelve a los pies y repite. Ejercicio metabólico extremadamente demandante.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Burpee Slam', 'Combine a full burpee with a slam ball. Perform the slam, place your hands on the ball, jump plank, optional push-up, return to your feet and repeat. Extremely demanding metabolic exercise.', 'external'),
('00fd4b17-81e5-409c-a9c5-83b628d91ed1', 'Swing con Kettlebell a una mano', 29, 55, 281, 1, 'Principiante', 'Balancéa la Kettlebell entre las piernas y empújala explosivamente con la cadera hasta la altura de los hombros usando un solo brazo.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Single-Arm Kettlebell Swing', 'Swing the kettlebell between your legs and drive it explosively with your hips to shoulder height using one arm.', 'external'),
('014ae459-ef96-4e08-8c69-948f62b177ec', 'Desplazamiento lateral battle ropes', 28, 6, 256, 24, 'Avanzado', 'Desplazamiento lateral rápido mientras creas ondas intensas. Trabaja agilidad, coordinación y resistencia. Mantén posición atlética baja. Cambia dirección cada 5-10 pasos. Las ondas no deben interrumpirse.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Ropes Lateral Shuffle', 'Shuffle laterally while keeping the waves going. This works lateral agility, coordination, and endurance. Maintain a low athletic stance and change direction periodically. Keep your core stable.', 'external'),
('015066cb-b761-4cc4-bdbf-5c5ff7efb7e4', 'Levantamiento turco con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'Levántate desde el suelo hasta quedar de pie manteniendo una Kettlebell bloqueada sobre la cabeza en todo momento.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Handed Kettlebell Turkish Lift', 'Lift yourself from the floor to a standing position, keeping a kettlebell locked overhead at all times.', 'external'),
('0171e99a-1485-482b-9459-da45a163fff0', 'Press kettlebell invertida', 6, 100, 281, 1, 'Avanzado', 'Press con la kettlebell boca abajo (bottom-up). Requiere tremendo control y fuerza de agarre. Mejora estabilización del hombro. Comienza con peso ligero. La kettlebell no debe tambalearse durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Inverted kettlebell press', 'Press with the kettlebell upside down (bottom-up). Requires tremendous control and grip strength. Improves shoulder stabilization. Start with light weight. The kettlebell should not wobble during the movement.', 'external'),
('01740541-4d83-4fb5-b952-f09f4a619c61', 'Mountain Climber con pies en pared', 25, 6, 1, 1, 'Avanzado', 'Colócate en posición de plancha con los pies apoyados en una pared a la altura de las caderas. Lleva las rodillas alternativamente hacia el pecho manteniendo la estabilidad del core y la presión contra la pared.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Mountain Climber with feet on wall', 'Get into a plank position with your feet resting on a wall at hip height. Bring your knees alternately toward your chest, maintaining core stability and pressure against the wall.', 'bodyweight'),
('01779fa7-f4ad-4f7d-bc30-aea391427a00', 'Drag Curl con barra', 17, 6, 116, 1, 'Intermedio', 'Realiza un curl de bíceps rozando la barra contra el torso mientras llevas los codos hacia atrás. Objetivo: cabeza larga del bíceps. Cue: mantén la barra siempre en contacto con el cuerpo. Error: encoger los hombros hacia las orejas.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Drag Curl with Barbell', 'Perform a biceps curl by rubbing the bar against your torso while bringing your elbows back. Target: long head of the biceps. Cue: always keep the bar in contact with the body. Common mistake: Shrugging your shoulders towards your ears.', 'external'),
('017e7077-9540-4061-a3e5-17145b20f008', 'Encogimiento de hombros a una mano en Landmine', 71, 6, 116, 1, 'Principiante', 'De pie junto al extremo de la barra Landmine, sujeta la barra con una mano y eleva el hombro hacia la oreja para trabajar el trapecio de forma unilateral.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'One Hand Shrug in Landmine', 'Standing next to the end of the Landmine bar, hold the bar with one hand and raise your shoulder toward your ear to work the trapezius unilaterally.', 'external'),
('019869be-7042-46d1-912a-736da36b6847', 'Plank a una mano en paralelas', 25, 6, 1, 24, 'Avanzado', 'Mantén la posición de plancha sobre las paralelas pero apoyado solo en una mano, lo que exige una estabilización extrema del hombro y core.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-hand parallel plank', 'Maintain the plank position on the parallel bars but supported only by one hand, which requires extreme stabilization of the shoulder and core.', 'bodyweight'),
('01b1aabe-7fc3-4a77-a9e5-ced29c147903', 'Puente de glúteo con pies en TRX', 29, 55, 216, 1, 'Intermedio', 'Acuéstate boca arriba con los talones en los estribos del TRX. Eleva las caderas del suelo presionando hacia abajo y manteniendo la estabilidad.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Glute bridge with feet in TRX', 'Lie on your back with your heels in the footpegs of the TRX. Raise your hips off the ground by pressing down and maintaining stability.', 'mixed'),
('01bb9dae-2be8-487d-b767-86de372704d9', 'Zancadas saltando', 28, 29, 1, 1, 'Intermedio', 'Desde la posición de zancada, salta explosivamente intercambiando la posición de las piernas en el aire. Aterriza suavemente en posición de zancada con la pierna opuesta adelante. Continúa alternando con saltos explosivos. Desarrolla potencia, coordinación y resistencia muscular en las piernas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Jumping Lunges', 'From a lunge position, jump explosively and switch your leg position in the air. Land softly in a lunge with the opposite leg forward. Continue alternating with explosive jumps. This develops power, coordination, and muscular endurance in the legs.', 'mixed'),
('01f09b4f-1a6f-4470-891f-06e9b0d35f74', 'TRX Curl de bíceps', 17, 25, 216, 1, 'Principiante', 'Cuerpo inclinado atrás, brazos extendidos. Flexiona codos llevando manos a las sienes. Mantén cuerpo recto. No balancees la cadera.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Biceps Curl', 'Lean back with your body straight and your arms extended. Bend your elbows and bring your hands toward your temples. Keep your body rigid and avoid swinging your hips.', 'bodyweight'),
('026b9beb-932f-46d5-b2fd-ff58064d5c4f', 'Zancada lateral (peso corporal)', 29, 313, 1, 1, 'Principiante', 'Paso lateral amplio bajando la cadera y volviendo al centro. Objetivo: aductores y glúteo. Cue: pecho alto siempre. Error común: dejar que el talón del pie móvil se levante.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Side Stride (body Weight)', 'Wide lateral step lowering the hip and returning to the center. Target: Adductors and glutes. Cue: always chest up. Common mistake: Let the heel of the moving foot rise.', 'bodyweight'),
('02700dc1-8c21-4f60-8a8b-ba8ba3bf191b', 'Caminata oso lateral rodillas bajas', 13, 6, 1, 24, 'Intermedio', 'Desplázate a gatas de lado. Cue: rodillas casi tocan suelo. Error: subir cadera.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Side Bear Walk Low Knees', 'Move sideways on all fours. Cue: knees almost touching the ground. Common mistake: raise hips.', 'bodyweight'),
('02dab88f-f109-451f-975a-481b5b64dad0', 'Escaladores lentos rodilla a codo', 25, 6, 1, 24, 'Principiante', 'Lleva rodilla a codo manteniendo 2s. Cue: no muevas cadera. Error: elevar glúteo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Knee-to-elbow Slow Climbers', 'Bring knee to elbow, maintaining 2s. Cue: don''t move your hips. Common mistake: raise glutes.', 'bodyweight'),
('02fdac7d-339c-4006-8acd-d2e834f2d2e0', 'Plank sobre Fitball', 25, 6, 290, 24, 'Principiante', 'Realiza una plancha apoyando los antebrazos sobre el Fitball, manteniendo el cuerpo recto y resistiendo la inestabilidad del balon.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Plank on Stability Ball', 'Perform a plank resting your forearms on the stability ball, keeping your body straight and resisting the instability of the ball.', 'bodyweight'),
('0308962c-606d-4b3c-b287-930c97924520', 'Rolling Squat Burpee', 13, 25, 1, 1, 'Avanzado', 'Haz un burpee, pero al bajar, rueda sobre tu espalda hacia atrás, toma impulso para volver a la sentadilla y salta.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Rolling Squat Burpee', 'Do a burpee, but when you lower yourself, roll backwards on your back, push yourself back into the squat and jump.', 'mixed'),
('030be619-3fbd-4fc3-8936-3b285596555f', 'TRX Remo alto hombro', 71, 6, 216, 1, 'Intermedio', 'Tira codos fuera altura hombro TRX. Objetivo: espalda alta. Cue: retrae escápulas. Error: subir hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX High Row', 'Pull with your elbows flared at shoulder height while using the TRX straps. Target: upper back. Cue: retract your shoulder blades. Common mistake: shrugging your shoulders.', 'bodyweight'),
('030e0ce1-5dc8-456a-9df0-605b7c21eac1', 'Remo al cuello con kettlebell', 6, 71, 281, 1, 'Principiante', 'Eleva la pesa rusa hacia el mentón manteniendo los codos por encima de las muñecas. Objetivo: deltoides y espalda alta. Cues: espalda recta y mirada al frente. Error común: realizar tirones bruscos con la espalda lumbar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Kettlebell Neck Row', 'Raise the kettlebell toward your chin, keeping your elbows above your wrists. Target: deltoids and upper back. Cue: straight back and look forward. Common mistake: making sudden jerks with the lumbar back.', 'external'),
('031ef73b-a0fd-4b61-b20b-43aef688be78', 'Abducción de cadera de pie con Miniband', 37, 29, 61, 1, 'Principiante', 'De pie con la banda en los tobillos. Levanta una pierna hacia el lado manteniendo el cuerpo recto, trabajando el glúteo medio.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Standing Hip Abduction with Mini Band', 'Standing with the band on your ankles. Raise one leg to the side, keeping your body straight, working the glute medius.', 'external'),
('03289c31-1fe2-4431-8f1c-26c19c1ccc49', 'Sentadilla Búlgara Overhead contralateral con Kettlebell', 28, 6, 281, 1, 'Avanzado', 'Con un pie elevado, sostén una Kettlebell sobre la cabeza en el lado opuesto a la pierna delantera y realiza la sentadilla split.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Contralateral Overhead Bulgarian Split Squat with Kettlebell', 'With one foot raised, hold a kettlebell overhead on the opposite side of your front leg and perform the split squat.', 'external'),
('032e98d5-de9a-4758-be81-b9e288770fe2', 'Sentadilla Cosaca alterna Front Rack con Kettlebell doble Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Realiza sentadillas laterales profundas sosteniendo dos Kettlebells invertidas en posición rack, el reto definitivo de estabilidad motor.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Alternating Cossack Squat Front Rack with Double kettlebell Bottoms Up', 'Perform deep lateral squats holding two inverted kettlebells in a rack position, the ultimate motor stability challenge.', 'external'),
('033fe3c6-aec6-4702-b70a-6269e8a58ab6', 'Levantamiento turco balón medicinal', 13, NULL, 240, 1, 'Avanzado', 'Turkish get up sosteniendo balón medicinal. La forma esférica añade inestabilidad comparado con pesa. Requiere mayor control y activación de estabilizadores. Progresa desde versión sin peso.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Turkish Lift Medicine Ball', 'Turkish get up holding medicine ball. The spherical shape adds instability compared to dumbbells. Requires greater control and activation of stabilizers. Progress from weightless version.', 'external'),
('03499f4c-ba25-49ca-b9ef-7638a2ae6b8b', 'Butt kicks', 55, NULL, 1, 24, 'Principiante', 'Corre en el sitio llevando los talones hacia los glúteos alternadamente, intentando tocarlos con cada patada. Mantén el torso erguido y los muslos relativamente quietos. El movimiento debe venir principalmente de la flexión de rodillas. Excelente para calentar isquiotibiales y mejorar la flexibilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Butt Kicks', 'Run in place, bringing your heels alternately toward your glutes, trying to touch them on each rep. Keep your torso upright and your thighs relatively still. The movement should come mainly from knee flexion. Excellent for warming up the hamstrings and improving mobility.', 'bodyweight'),
('0373ee7d-4160-48f0-9969-3ec237264911', 'Plancha lateral estática', 25, 37, 1, 24, 'Principiante', 'Apoyado en un antebrazo de lado, mantén cadera elevada. Cue: cuerpo alineado como una flecha. Error: dejar caer la cadera hacia el suelo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Static Side Plank', 'Support yourself on one forearm from the side and keep your hips raised. Cue: keep your body aligned like an arrow. Common mistake: letting your hips drop toward the floor.', 'bodyweight'),
('037ea5b5-9cf2-4290-a4e8-b6666b014c61', 'Preacher curl barra', 17, NULL, 116, 1, 'Intermedio', 'Usando un banco predicador, apoya los brazos en el soporte inclinado. Realiza el curl desde la extensión casi completa hasta la flexión máxima. Esta posición elimina el impulso y aísla efectivamente el bíceps. Ten cuidado de no hiperextender los codos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Preacher curl bar', 'Using a preacher bench, rest your arms on the inclined support. Perform the curl from almost full extension to maximum flexion. This position eliminates momentum and effectively isolates the biceps. Be careful not to hyperextend your elbows.', 'external'),
('0389ba82-138e-4a2c-a107-1b2474c9cece', 'Side plank TRX', 25, NULL, 216, 24, 'Intermedio', 'Plancha lateral con pies en las correas del TRX. Trabaja intensamente los oblicuos y estabilizadores laterales. Puedes elevar el brazo libre para aumentar la dificultad. Mantén las caderas elevadas y alineadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Side Plank', 'Side plank with feet on the TRX straps. Work the obliques and lateral stabilizers intensely. You can raise your free arm to increase the difficulty. Keep your hips raised and aligned.', 'bodyweight'),
('03bf9e78-dcbf-48ca-b8ae-3be0b0f27907', 'Swing alternado', 29, 55, 281, 1, 'Avanzado', 'Cambia de mano en cada swing en el punto más alto. Requiere timing y coordinación precisos. El cambio debe ser suave sin interrumpir el ritmo. Excelente para deportes que requieren coordinación mano-ojo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Alternating Swing', 'Change hands at the top of each swing. This requires precise timing and coordination. The hand change should be smooth and controlled.', 'external'),
('03c4be64-5713-4680-bceb-c3c9328ab080', 'Russian Twist con Kettlebell y pies elevados', 25, NULL, 281, 1, 'Intermedio', 'Sentado con los pies en el aire, rota el torso de lado a lado desplazando la pesa rusa a traves de la linea media del cuerpo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Russian Twist with Kettlebell and Feet Elevated', 'Sitting with your feet in the air, rotate your torso from side to side, moving the kettlebell across the midline of your body.', 'external'),
('03e59c2f-9af8-4213-9ca9-53ec3ccd3ef3', 'Tríceps press francés', 2, NULL, 116, 1, 'Intermedio', 'Extensión de tríceps (press francés) para enfatizar la cabeza larga, manteniendo codos estables y bajada controlada.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'French Press Triceps Extension', 'Perform a triceps extension to emphasize the long head, keeping your elbows steady and the lowering phase controlled.', 'external'),
('03f52fed-5dc6-45c4-a38b-7c571f345495', 'Remo renegado a Flexión con mancuernas', 71, 1, 81, 1, 'Intermedio', 'Realiza una flexion sobre dos mancuernas e inmediatamente después rema una pesa hacia tu cadera, alternando el brazo en cada repeticion.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Renegade Row to Dumbbell Curl', 'Perform a push-up over two dumbbells and immediately afterwards row a weight towards your hip, alternating your arm with each repetition.', 'external'),
('041d965f-9785-4345-933f-dcf9bed13fa0', 'Sentadilla Ciclista con Kettlebell (Horn)', 28, 29, 281, 1, 'Principiante', 'Con los talones en alto, sujeta la pesa rusa por los cuernos frente al pecho y baja en sentadilla profunda.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Kettlebell Cycle Squat (horn)', 'With your heels up, hold the kettlebell by the horns in front of your chest and lower yourself into a deep squat.', 'external'),
('0425357d-bb8e-4262-91d3-7364b762c09c', 'Bent over reverse fly barra', 6, 71, 116, 1, 'Intermedio', 'Inclinado hacia adelante con agarre muy amplio en la barra, eleva la barra realizando una abducción posterior. Este movimiento poco común trabaja intensamente el deltoides posterior y los músculos de la espalda alta. Mantén una ligera flexión en los codos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bent over reverse fly bar', 'Leaning forward with a very wide grip on the bar, raise the bar by performing a posterior abduction. This unusual move intensely works the posterior deltoid and upper back muscles. Maintain a slight bend in your elbows.', 'external'),
('042cb66e-e1ff-47b1-9813-c0caa9b49934', 'Dominadas supinas', 17, 16, 1, 1, 'Intermedio', 'Agarra la barra con las palmas mirando hacia ti, separadas al ancho de los hombros. Esta posición permite mayor participación del bíceps en el movimiento. Eleva el cuerpo hasta que la barbilla supere la barra y desciende de forma controlada. Es generalmente más fácil que las dominadas pronadas debido a la mayor implicación del bíceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Supine pull-ups', 'Grip the bar with your palms facing you, shoulder-width apart. This position allows greater participation of the biceps in the movement. Raise your body until your chin clears the bar and lower yourself in a controlled manner. It is generally easier than pronated pull-ups due to the greater involvement of the biceps.', 'mixed'),
('043e581a-3577-43cd-87d0-79fd667bc61e', 'Remo inclinado agarre inverso con maza (Offset)', 71, 17, 81, 1, 'Intermedio', 'Similar al remo offset pero con las palmas hacia arriba, incrementando el trabajo de los biceps y antebrazos.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Reverse grip bent over row with mallet (Offset)', 'Similar to the offset row but with the palms facing up, increasing the work of the biceps and forearms.', 'external'),
('04435260-58ab-44c3-996f-b1f1982f7a4a', 'Lanzamiento de balón de rodillas', 1, 6, 240, 1, 'Intermedio', 'Arrodillado, lanza el balón hacia adelante con un empuje de pecho explosivo. Aísla el torso. Cue: no te sientes sobre los talones. Error común: usar el balanceo del tronco excesivamente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Kneeling Ball Throw', 'Kneeling, throw the ball forward with an explosive chest thrust. Isolate the torso. Cue: don''t sit on your heels. Common mistake: using torso swing excessively.', 'external'),
('0455b33f-7881-4b10-9e27-03d74b9f0d93', 'Skipping reactivo', 13, 64, 1, 1, 'Intermedio', 'Realiza skipping reactivo buscando contactos rápidos y elásticos con el suelo. Mantén el tronco erguido, la cadencia alta y una buena coordinación de brazos y piernas.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Reactive Skipping', 'Perform reactive skipping with quick and elastic ground contacts. Keep the torso upright, cadence high, and good arm-leg coordination.', 'bodyweight'),
('047bb16c-c267-4e21-9d37-88a8bc53ceb2', 'Sentadilla Ciclista con Kettlebell doble (Maleta)', 28, 29, 281, 1, 'Principiante', 'Con talones elevados, realiza una sentadilla profunda sosteniendo una pesa rusa en cada mano a los costados del cuerpo.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Cycling Squat with Double Kettlebell (suitcase)', 'With heels raised, perform a deep squat holding a kettlebell in each hand at your sides.', 'external'),
('0481a7a9-12ef-4fc4-bc05-a7b135cbaff7', 'Bandera dragón', 25, NULL, 1, 1, 'Avanzado', 'Tumbado sujetando algo detrás de la cabeza, eleva todo el cuerpo recto excepto hombros. Popularizado por Bruce Lee. Desciende controladamente sin que el cuerpo toque el suelo. Uno de los mejores ejercicios para core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dragon Flag', 'Lie on your back while holding onto a support behind your head. Raise your whole body in a straight line, with only your shoulders on the bench. Lower under control without letting your body touch the ground. It is one of the best core exercises.', 'bodyweight'),
('04a46c6d-cb64-44ed-a3b1-bed221f1bc2d', 'Windmill medio arrodillado con Kettlebell Bottoms Up', 25, 6, 281, 1, 'Avanzado', 'En posicion de caballero con una Kettlebell invertida bloqueada arriba, inclina el torso hasta tocar el suelo, exigiendo maxima estabilidad escapular.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Half-Kneeling Bottoms-Up Kettlebell Windmill', 'In a half-kneeling position with an inverted kettlebell locked overhead, hinge your torso until you touch the floor, demanding maximum scapular stability.', 'external'),
('04eda32b-8e01-4e36-9a90-1329cdb56ba3', 'Sentadilla Búlgara con barra tras nuca rodilla sobre punta del pie', 28, 29, 116, 1, 'Intermedio', 'Sujeta una barra sobre los trapecios y realiza una sentadilla split con el pie trasero elevado, permitiendo que la rodilla delantera avance sobre los dedos del pie.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bulgarian Squat with Barbell Behind the Neck Knee on Toe', 'Hold a barbell over your traps and perform a split squat with your back foot raised, allowing your front knee to come over your toes.', 'external'),
('04fcec50-1969-4c08-919e-e93a17d3f5ad', 'Saltos laterales sobre línea unilateral', 37, 64, 1, 1, 'Intermedio', 'Salta de lado a lado sobre una línea con un solo pie lo más rápido posible. Estabilidad lateral. Rodilla alineada. No apoyes el talón.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Lateral jumps on unilateral line', 'Jump from side to side over a line on one foot as quickly as possible. Lateral stability. Aligned knee. Don''t put your heel down.', 'bodyweight'),
('0500ef24-e637-4893-82d4-f82a31076f3d', 'Pulsos bandera humana', 25, 16, 1, 1, 'Avanzado', 'Desde la posición de bandera humana, realiza pequeños movimientos de subida y bajada controlados. Aumenta enormemente la dificultad de la bandera estática. Solo posible tras dominar la bandera humana completa por varios segundos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Human flag pulses', 'From the human flag position, make small controlled up and down movements. Greatly increases the difficulty of the static flag. Only possible after mastering the entire human flag for several seconds.', 'bodyweight'),
('050502d4-89b5-4ed9-97c6-b89f09c723b9', 'Remo en polea alta con barra recta', 16, 2, 151, 1, 'Principiante', 'Tira de la barra hacia tus muslos manteniendo los brazos rectos en todo momento. Objetivo: dorsal y serrato. Cue: core firme y espalda neutra. Error: flexionar los codos para ayudar al tirón.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'High Cable Row with Straight Bar', 'Pull the bar toward your thighs, keeping your arms straight at all times. Target: dorsal and serratus. Cue: firm core and neutral back. Common mistake: bending the elbows to help the pull.', 'external'),
('055a966f-b2d1-4997-b678-6adca7ec173a', 'Iron Cross en anillas', 71, 1, 1, 24, 'Avanzado', 'Manten los brazos extendidos lateralmente de forma horizontal sosteniendo el cuerpo en las anillas, formando una cruz perfecta.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Iron Cross in Rings', 'Keep your arms extended laterally horizontally, holding your body in the rings, forming a perfect cross.', 'bodyweight'),
('058851ee-e570-46c8-8577-a1d3170a230f', 'Sentadilla Búlgara contralateral Front Rack con Kettlebell', 28, 29, 281, 1, 'Intermedio', 'Sentadilla split con pie elevado sosteniendo la Kettlebell en el hombro opuesto a la pierna que trabaja, manteniendo el core firme para evitar la rotacion.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Contralateral Front Rack Bulgarian Split Squat with Kettlebell', 'Split squat with raised foot holding the kettlebell on the shoulder opposite the working leg, keeping the core firm to prevent rotation.', 'external'),
('05a14a23-ddd9-4939-a1ad-483b38d58cb7', 'Peso muerto rumano agarre Crush con mancuernas', 55, 29, 81, 1, 'Principiante', 'Pisa las mancuernas uniendolas y realiza un peso muerto rumano manteniendo la tension al apretarlas durante el movimiento.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Romanian Deadlift Grip Dumbbell Crush', 'Step on the dumbbells together and perform a Romanian deadlift, maintaining tension by squeezing them during the movement.', 'external'),
('05a792eb-9771-4473-a937-cfac19ae079b', 'Remo Pendlay', 71, 16, 116, 1, 'Avanzado', 'Remo con barra desde el suelo en cada repetición para desarrollar espalda con potencia y técnica estricta de bisagra.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Pendlay Rowing', 'Barbell row from the floor in each repetition to develop back with power and strict hinge technique.', 'external'),
('05af56d8-a07c-4f69-bb88-bb45bf987d05', 'Zancada lateral barra tras nuca', 29, 313, 116, 1, 'Intermedio', 'Paso lateral con barra en hombros. Cue: cadera atrás al bajar. Error: rodilla sobrepasa pie.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Side Stride Bar After Nape', 'Side step with bar on shoulders. Cue: hip back when going down. Common mistake: knee exceeds foot.', 'external'),
('05af5ac8-208e-4420-b8ac-de5c93b6582e', 'Press Z con Kettlebell a una mano', 6, 2, 281, 1, 'Intermedio', 'Sentado en el suelo con piernas estiradas, presiona la Kettlebell sobre la cabeza sin apoyo dorsal para aislar el hombro y core.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Z Press with One-Handed kettlebell', 'Sitting on the floor with straight legs, press the kettlebell overhead without dorsal support to isolate the shoulder and core.', 'external'),
('05eda6ce-65ea-47b0-b6c9-1aeb35bbc2b7', 'Abducción de cadera en máquina', 37, 29, 186, 1, 'Principiante', 'Sentado, empuja las almohadillas hacia afuera con los muslos. Cue: movimiento controlado. Error: usar el impulso del tronco para despegar el peso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Machine Hip Abduction', 'Sitting, push the pads outward with your thighs. Cue: controlled movement. Common mistake: using the momentum of the torso to lift the weight.', 'external'),
('060aa295-0ce4-43d2-947b-624c2e0ad896', 'Sentadilla patinadora Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Avanzado', 'Realiza una sentadilla patinadora sosteniendo dos Kettlebells en posicion rack, exigiendo un equilibrio extremo de la pierna de apoyo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double kettlebell Front Rack Skate Squat', 'Perform a skater squat holding two kettlebells in a rack position, requiring extreme balance of the supporting leg.', 'external'),
('061295db-986a-40ae-bc77-4b4500e52773', 'Círculos de brazos Overhead con Indian Club doble', 6, 71, 81, 1, 'Principiante', 'Realiza círculos controlados por encima de la cabeza con ambos Indian Clubs para mejorar la estabilidad escapular y la movilidad torácica.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Overhead Arm Circles with Double Indian Club', 'Perform controlled overhead circles with both Indian Clubs to improve scapular stability and thoracic mobility.', 'external'),
('061645d0-5e65-4d09-b959-6f2317916106', 'Thruster Ciclista con Kettlebell doble', 28, 6, 281, 1, 'Intermedio', 'Realiza una sentadilla ciclista con talones elevados sosteniendo dos Kettlebells. Sube con potencia y presiona ambas pesas sobre la cabeza en un movimiento fluido.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Cyclist Double Kettlebell Thruster', 'Perform a cyclist squat with your heels elevated while holding two kettlebells. Drive up powerfully and press both weights overhead in one fluid movement.', 'external'),
('0675465f-36aa-4355-8296-86d4cacbc2c1', 'Patada glúteo cable', 29, NULL, 151, 1, 'Principiante', 'Con tobillera conectada a polea baja, realiza extensiones de cadera hacia atrás manteniendo la pierna relativamente recta. Inclínate ligeramente hacia adelante para estabilidad. Enfócate en contraer el glúteo sin arquear excesivamente la espalda.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable glute kick', 'With an ankle cuff connected to a low cable, perform backward hip extensions while keeping your leg relatively straight. Lean forward slightly for stability. Focus on contracting your glutes without excessively arching your back.', 'external'),
('068fa480-9dff-4f2f-80ef-f834d8298a32', 'Rotational throw', 25, 6, 240, 1, 'Intermedio', 'De lado a la pared, rota el torso y lanza el balón lateralmente con fuerza. Recibe el rebote y repite. Excelente para desarrollar potencia rotacional útil en deportes. Mantén las caderas estables y rota desde el core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rotational throw', 'With your side facing the wall, rotate your torso and throw the ball laterally with force. Receive the rebound and repeat. Excellent for developing rotational power useful in sports. Keep your hips stable and rotate from your core.', 'external'),
('069ef703-85ee-412a-aa44-23d0ac48bfe8', 'Remo inclinado con barra supinado', 71, 17, 116, 1, 'Intermedio', 'Torso a 45 grados, agarra la barra con palmas hacia arriba y tira hacia el ombligo. Objetivo: dorsal inferior y bíceps. Cue: codos pegados a los costados al tirar. Error común: erguir el torso durante la serie para facilitar el movimiento.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Supinated Barbell Bent-over Row', 'torso at 45 degrees, grab the bar with palms facing up and pull towards the navel. Target: lower dorsal and biceps. Cue: elbows close to your sides when pulling. Common mistake: straightening your torso during the set to facilitate movement.', 'external'),
('06be8aef-e358-41dd-8598-10da00b8af12', 'Jalón lateral unilateral máquina dorsal', 16, 17, 186, 1, 'Intermedio', 'Tira palanca a un brazo. Cue: aprieta dorsal. Error: inclinarse mucho.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Unilateral Lat Pulldown Lat Machine', 'Pull leverage on one arm. Cue: back squeeze. Common mistake: leaning too much.', 'external'),
('06de1c67-c22b-4f3d-bcb5-531724ad31d0', 'Zancada lateral con mancuerna al pecho', 29, 313, 81, 1, 'Principiante', 'Sujeta una mancuerna estilo Goblet y realiza pasos laterales bajando la cadera. Objetivo: aductores y glúteo. Cues: talón siempre apoyado. Error común: dejar que el torso caiga hacia adelante.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Side Dumbbell Chest Lunge', 'Hold a Goblet-style dumbbell and take side steps by lowering your hip. Target: Adductors and glutes. Cue: heel always supported. Common mistake: Letting your torso drop forward.', 'external'),
('06f90fda-e1d3-4c7a-a8d5-dc6e4ee817b5', 'Shrimp squats', 28, 29, 1, 1, 'Avanzado', 'De pie sobre una pierna, lleva la pierna libre hacia atrás sujetando el tobillo con la mano del mismo lado. Desciende en sentadilla hasta que la rodilla de la pierna trasera toque el suelo. Empuja para volver arriba. Requiere fuerza, equilibrio y flexibilidad en cuádriceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Shrimp squats', 'Standing on one leg, bring your free leg back, holding your ankle with the hand on the same side. Lower yourself into a squat until the knee of your back leg touches the ground. Push to go back up. Requires strength, balance and flexibility in the quadriceps.', 'mixed'),
('070868e8-6bef-4619-bfb2-a1709c4f5828', 'Fondos para pecho en paralelas', 1, 2, 1, 1, 'Intermedio', 'Realiza fondos en paralelas con énfasis en pecho. Inclina ligeramente el torso hacia delante, baja de forma controlada y empuja hasta extender los brazos.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Chest Dips', 'Perform parallel bar dips with a chest emphasis. Lean the torso slightly forward, lower under control, and press up until the arms are extended.', 'bodyweight'),
('071734ec-cdef-44f7-9ada-a9bf797e5717', 'Sentadilla búlgara mancuernas', 28, 29, 81, 1, 'Intermedio', 'Con el pie trasero elevado en un banco y una mancuerna en cada mano, realiza una sentadilla unilateral descendiendo hasta que la rodilla delantera forme 90 grados. Mantén el torso erguido y el peso principalmente en el talón delantero. Excelente para fuerza unilateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bulgarian Dumbbell Squat', 'With your back foot raised on a bench and a dumbbell in each hand, perform a unilateral squat, lowering yourself until your front knee is at 90 degrees. Keep your torso upright and your weight primarily on your front heel. Excellent for unilateral force.', 'external'),
('0739688a-865f-42fe-84ad-91af88587d9e', 'Peso muerto maleta', 55, 71, 116, 1, 'Avanzado', 'Peso muerto con barra al lado del cuerpo como una maleta. Tremendo desafío de estabilización lateral. Trabaja intensamente el core anti-flexión lateral. Usa menos peso que peso muerto regular. Alterna lados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Suitcase Deadlift', 'Deadlift with bar next to the body like a suitcase. Tremendous lateral stabilization challenge. Work the anti-lateral flexion core intensely. Use less weight than regular deadlifts. Alternate sides.', 'external'),
('07696a43-8968-48ba-b678-36cc2fa9329f', 'Extensión tras nuca cuerda polea', 2, NULL, 151, 1, 'Intermedio', 'Extiende brazos sobre cabeza con cuerda. Objetivo: cabeza larga tríceps. Cue: estira total. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Extension Behind the Neck Cable Rope', 'Extend arms overhead with rope. Target: long head triceps. Cue: full stretch. Common mistake: arching your lower back.', 'external'),
('077dd018-c38c-472a-8795-61bab428598e', 'Clock press TRX', 6, 25, 216, 1, 'Avanzado', 'Press en diferentes ángulos simulando las posiciones de un reloj. Trabaja los hombros desde múltiples ángulos mientras desafía la estabilidad del core. Requiere control excepcional y fuerza en hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Clock press TRX', 'Press at different angles simulating the positions of a clock. Works the shoulders from multiple angles while challenging core stability. Requires exceptional control and shoulder strength.', 'bodyweight'),
('07c2bf48-5235-495f-a61b-7997c1f924b9', 'Flexiones de pino', 6, 2, 1, 1, 'Avanzado', 'Boca abajo contra la pared, flexiona y extiende brazos. Cue: core muy firme. Error: arquear la espalda como un arco.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Handstand Push-ups', 'Face down against the wall, flex and extend your arms. Cue: very firm core. Common mistake: arching your back like a bow.', 'mixed'),
('07c60932-4073-4982-bd04-b46e0e80382c', 'Extensión tríceps máquina empuje', 2, NULL, 186, 1, 'Principiante', 'Empuja agarres abajo sentado. Cue: codos fijos. Error: usar peso cuerpo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Triceps Extension Machine Push', 'Seated push down grips. Cue: keep your elbows fixed. Common mistake: using body weight.', 'external'),
('08038803-49dd-4088-849e-169253263a44', 'Sentadilla salto 180 grados', 28, 29, 1, 1, 'Avanzado', 'Sentadilla con salto incorporando un giro completo de 180 grados en el aire. Requiere potencia, coordinación y control espacial. Aterriza suavemente y continúa el movimiento. Excelente para deportes que requieren agilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat jump 180 degrees', 'Jump squat incorporating a complete 180 degree turn in the air. Requires power, coordination and spatial control. Land softly and continue the movement. Excellent for sports that require agility.', 'mixed'),
('080be644-8a87-4dcf-92d4-d2b5379bbc25', 'Sentadilla Cosaca alterna con barra frontal', 28, 29, 116, 1, 'Avanzado', 'Realiza una sentadilla lateral profunda con la barra en posición de rack frontal, exigiendo máxima movilidad de cadera y estabilidad del torso.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Cossack alternating squat with front bar', 'Perform a deep lateral squat with the bar in a front rack position, demanding maximum hip mobility and torso stability.', 'external'),
('080eba09-63ab-44d4-9059-8eb3c3a0d86b', 'Sentadilla frontal agarre cruzado barra', 28, 25, 116, 1, 'Intermedio', 'Sentadilla frontal con brazos en X sobre la barra. Cue: codos altos. Error: barra rueda al cuello.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Barbell Cross Grip Front Squat', 'Front squat with arms in X on the bar. Cue: high elbows. Common mistake: bar rolls to the neck.', 'external'),
('0811187b-348a-4383-8126-031b2e604512', 'Sentadilla Jefferson', 28, 29, 116, 1, 'Avanzado', 'Ponte a horcajadas sobre la barra, un pie delante y otro detrás, sujeta la barra y baja en sentadilla. Objetivo: potencia de piernas y core. Cue: mantén el torso vertical. Error: dejar que la barra toque el suelo de forma brusca.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Jefferson Squat', 'Straddle the bar, one foot in front and one behind, hold the bar and lower yourself into a squat. Target: leg and core power. Cue: keep your torso vertical. Common mistake: letting the bar touch the ground abruptly.', 'external'),
('081fcd2e-ca61-487a-ba7e-e90e55bacf72', 'Push Press con mancuernas', 6, 2, 81, 1, 'Principiante', 'Sostén mancuernas en los hombros, haz una pequeña flexion de rodillas y utiliza el impulso para empujar las pesas sobre la cabeza.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Dumbbell Push Press', 'Hold dumbbells on your shoulders, do a small bend on your knees and use momentum to push the weights overhead.', 'external'),
('0845d596-cb54-4576-ba1a-4a1a3a902fc3', 'Zancada en polea baja cable estricta', 28, 29, 151, 1, 'Intermedio', 'Zancada con cable tirando pierna atrás. Cue: torso erguido. Error: perder estabilidad.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Low Cable Lunge', 'Perform a lunge with the cable pulling the leg backward. Cue: keep your torso upright. Common mistake: losing stability.', 'external'),
('085cc2da-bfed-4bf4-aa76-2f1696868fb2', 'Turkish Sit Up con mancuernas', 25, 6, 81, 1, 'Intermedio', 'Realiza un sit up manteniendo dos mancuernas extendidas verticalmente sobre el pecho, exigiendo un control abdominal superior.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Double Dumbbell Turkish Sit-Up', 'Perform a sit-up while holding two dumbbells vertically over your chest, requiring strong abdominal control.', 'external'),
('08725c52-a28f-41fa-8402-57b01193c2a3', 'Zancada caminando Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza zancadas manteniendo dos pesas rusas invertidas sobre la cabeza con brazos bloqueados, exigiendo un equilibrio y fuerza total.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Walking Overhead Double Bottoms-Up Kettlebell Lunge', 'Perform walking lunges while holding two upside-down kettlebells overhead with locked arms, demanding total-body balance and strength.', 'external'),
('0873ec86-5908-44fc-b938-1720af58d951', 'Curl bíceps polea alta unilateral oreja', 17, NULL, 151, 1, 'Intermedio', 'De lado a polea alta, flexiona a oreja. Cue: codo alto. Error: bajar codo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Single-Arm High Cable Biceps Curl to Ear', 'Standing sideways to a high cable, curl toward your ear. Cue: keep your elbow high. Common mistake: letting your elbow drop.', 'external'),
('089bd617-f41f-40da-8ae8-fa4e66c6d22f', 'Elevación de tibial a una pierna con banda', 64, NULL, 61, 1, 'Principiante', 'Sentado con la banda anclada al pie, flexiona el tobillo llevando los dedos hacia la espinilla contra la resistencia para fortalecer el tibial.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'One leg tibial raise with band', 'Sitting with the band anchored to your foot, flex your ankle by bringing your toes toward your shin against resistance to strengthen your tibialis.', 'external'),
('08ad06fb-f21a-4d4e-9059-c5df4859383b', 'Remo en máquina sentado neutro', 71, 17, 186, 1, 'Principiante', 'Tira de los agarres en máquina de remo. Cue: junta escápulas atrás. Error: encoger hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Neutral Seated Machine Row', 'Pull the grips on the rowing machine. Cue: bring scapulae together back. Common mistake: shrugging your shoulders.', 'external'),
('08c36a43-4a9c-4f3c-8179-e18535d35b6a', 'Curl guillotina con cable', 17, NULL, 151, 1, 'Intermedio', 'Acuéstate en un banco plano debajo de una polea alta. Realiza un curl llevando la barra hacia tu cuello (con cuidado), manteniendo los codos altos y fijos.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable guillotine curl', 'Lie on a flat bench under a high cable. Perform a curl by bringing the bar towards your neck (carefully), keeping your elbows high and fixed.', 'external'),
('091f3beb-4843-490f-8511-c7d00f55e6d1', 'Remo con mancuerna al pecho (Spider Row)', 71, 6, 81, 1, 'Intermedio', 'Tumbado boca abajo en un banco inclinado, deja colgar las mancuernas y rema hacia el pecho. Objetivo: espalda media y retractores. Cue: aprieta las escápulas al final. Error: separar el pecho del banco.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Dumbbell Chest Row (spider Row)', 'Lying face down on an incline bench, let the dumbbells hang and row toward your chest. Target: mid back and retractors. Cue: squeeze your scapulae at the end. Common mistake: separating your chest from the bench.', 'external'),
('09275a9c-be70-4ac4-882c-700aa799251c', 'Dominadas tras nuca', 16, 17, 1, 1, 'Avanzado', 'Dominadas llevando la nuca hacia la barra en lugar de la barbilla. Trabaja los dorsales desde un ángulo diferente. Requiere buena movilidad de hombros. Algunos expertos desaconsejan por riesgo de lesión. Usa con precaución.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pull-ups behind the neck', 'Pull-ups by bringing the neck towards the bar instead of the chin. Work your lats from a different angle. Requires good shoulder mobility. Some experts advise against it due to risk of injury. Use with caution.', 'mixed'),
('0941737b-d37d-417b-a49c-b9d4a279743f', 'Zancada lateral con salto', 37, 28, 1, 1, 'Intermedio', 'Realiza una zancada lateral y empuja explosivamente para saltar hacia el otro lado. Potencia en el plano lateral. Cue: empuja con toda la planta del pie. Error común: no bajar lo suficiente antes del salto.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Stride with Jump', 'He makes a lateral stride and pushes explosively to jump to the other side. Power in the lateral plane. Cue: push with the entire sole of the foot. Common mistake: Not getting low enough before the jump.', 'bodyweight'),
('0955e938-65b1-4f57-ba45-e294557d1fce', 'Press pecho', 1, 2, 81, 1, 'Intermedio', 'Realiza un press de pecho con mancuernas. Baja las mancuernas de forma controlada hasta la altura del pecho y empuja hacia arriba manteniendo estabilidad en hombros y escápulas.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Dumbbell Chest Press', 'Perform a dumbbell chest press. Lower the dumbbells under control to chest level and press upward while maintaining shoulder and scapular stability.', 'external'),
('0967baba-b3fe-44a6-977a-22bbdcc34483', 'Zancada caminando Overhead con Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Camina realizando zancadas mientras sostienes dos Kettlebells bloqueadas sobre la cabeza, exigiendo un control total del equilibrio y la movilidad.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Walking Overhead Double Kettlebell Lunge', 'Walk forward performing lunges while holding two kettlebells locked out overhead, demanding total balance and mobility control.', 'external'),
('097ab32c-544d-42b3-b425-e8a39751a834', 'Extensión tríceps cable', 2, NULL, 151, 1, 'Principiante', 'Con polea alta y barra recta o cuerda, realiza extensiones de codo manteniendo los brazos superiores pegados al cuerpo. Extiende completamente los codos en la parte inferior del movimiento. Es uno de los mejores ejercicios para aislar el tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable triceps extension', 'Using a high cable and a straight bar or rope, perform elbow extensions while keeping your upper arms close to your body. Fully extend your elbows at the bottom of the movement. It is one of the best exercises to isolate the triceps.', 'external'),
('098c8ab9-d39a-48b8-a436-c143c7610cd6', 'Aperturas de pecho con banda', 1, 6, 61, 1, 'Principiante', 'Banda tras la espalda, junta manos al frente. Cue: mantén codos semiflexionados. Error: encoger hombros.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Banded Chest Fly', 'Place the band behind your back and bring your hands together in front of you. Cue: keep a slight bend in your elbows. Common mistake: shrugging your shoulders.', 'external'),
('09a5b3df-37e8-458b-8125-d9588a31a962', 'Bosu plancha plana', 25, 6, 298, 24, 'Principiante', 'Mantén plancha con manos en la plataforma plana del bosu. Estabilidad de hombros. Cuerpo recto. No dejes que el bosu tiemble demasiado.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'BOSU Plank', 'Hold a plank with your hands on the flat side of the BOSU. Target: shoulder stability. Keep your body straight. Do not let the BOSU wobble excessively.', 'bodyweight'),
('09afcadd-7707-4c51-a76a-49306c6c4bc3', 'Press Pallof arrodillado con cable alto', 25, 6, 151, 1, 'Principiante', 'Arrodillado sobre ambas piernas de lado a una polea alta, sujeta el mando y extiendelo frente a ti, resistiendo la traccion diagonal hacia arriba.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'High Cable Kneeling Pallof Press', 'Kneeling on both legs sideways to a high pulley, hold the controller and extend it in front of you, resisting the diagonal upward pull.', 'external'),
('09c14bdd-16ab-48f9-8513-69214c34e659', 'Handstand Push Up en anillas', 6, 2, 1, 1, 'Avanzado', 'El ejercicio máximo de empuje vertical: realiza flexiones en parada de manos directamente sobre las anillas inestables.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Handstand Push Up on rings', 'The Ultimate Vertical Push Exercise: Perform handstand push-ups directly on the unstable rings.', 'mixed'),
('0a1562e7-1daa-4d5c-af93-5c989a267e2f', 'Zancada con rotación de tronco', 28, 25, 1, 1, 'Intermedio', 'Realiza una zancada y, en la posición baja, gira el torso hacia el lado de la pierna adelantada. Objetivo: estabilidad y movilidad. Cue: mantén la rodilla alineada al rotar. Error: perder el equilibrio lateral.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Lunge with Torso Rotation', 'Perform a lunge and, in the bottom position, rotate your torso toward the side of the front leg. Target: stability and mobility. Cue: keep the knee aligned during the rotation. Common mistake: losing lateral balance.', 'mixed'),
('0a2237ed-5455-43b7-a424-15add66c3394', 'Lanzamiento rotacional balón', 25, 6, 240, 1, 'Avanzado', 'Lanzamiento lateral explosivo contra pared. Genera máxima potencia rotacional desde las caderas. Útil para deportes de lanzamiento. Recibe el rebote con control y repite fluidamente. Alterna direcciones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rotational ball throw', 'Explosive lateral throw against the wall. Generates maximum rotational power from the hips. Useful for throwing sports. Receive the rebound with control and repeat fluidly. Alternate directions.', 'external'),
('0a945cee-f82c-4f0c-910c-25abce4432d2', 'TRX Chest Press (enfocado pectoral)', 1, 2, 216, 1, 'Intermedio', 'De espaldas al anclaje, realiza flexiones sujetando los agarres. Objetivo: pectoral con inestabilidad. Cue: cuerpo recto como tabla. Error común: dejar que las correas rocen los brazos.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'TRX Chest Press (Chest Focus)', 'Face away from the anchor and perform a press while holding the handles. Target: chest under instability. Cue: keep your body straight like a plank. Common mistake: letting the straps rub against your arms.', 'bodyweight'),
('0b15b377-94ec-4038-af70-0e0801cc8c7b', 'Press de hombros en máquina', 6, 2, 186, 1, 'Principiante', 'Sentado en la máquina, empuja los agarres hacia arriba hasta extender los brazos por completo. Objetivo: deltoides. Cue: controla el descenso del peso. Error: bloquear los codos bruscamente arriba.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Machine Shoulder Press', 'Sitting on the machine, push the grips up until your arms are fully extended. Target: deltoid. Cue: controls the decrease in weight. Common mistake: locking the elbows sharply above.', 'external'),
('0b2645f5-2e12-4e20-b509-7557354e7b3b', 'Ring Straight Arm Pike Press Handstand', 6, 2, 1, 1, 'Avanzado', 'Desde posicion de pica en anillas, presiona con los brazos bloqueados y rectos hasta alcanzar la vertical de la parada de manos.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Ring Straight Arm Pike Press Handstand', 'From the ring pike position, press with your arms locked and straight until you reach the vertical position of the handstand.', 'bodyweight'),
('0b3a1aed-862f-45b7-8a17-1459bcd257af', 'Zancadas caminadas', 28, 29, 81, 1, 'Principiante', 'Avanza dando pasos largos y bajando la rodilla trasera hacia el suelo. Cue: torso erguido. Error: paso demasiado corto que levanta el talón delantero.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Walking Strides', 'Move forward by taking long steps and lowering your back knee to the floor. Cue: erect torso. Common mistake: step too short that lifts the front heel.', 'external'),
('0b60f99f-758c-4aff-88ef-dedd3dc7a855', 'Dragon squats', 28, 29, 1, 1, 'Avanzado', 'Variación extrema de sentadilla a una pierna donde la pierna libre se mantiene extendida detrás del cuerpo durante todo el movimiento. Desciende hasta la posición más baja posible manteniendo el control total. Requiere fuerza y movilidad excepcionales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dragon squats', 'Extreme single-leg squat variation where the free leg remains extended behind the body throughout the movement. Descend to the lowest possible position while maintaining complete control. Requires exceptional strength and mobility.', 'mixed'),
('0b6d2484-6b2a-4ed3-9fbb-f5932552ff51', 'Giro ruso con balón medicinal', 25, 71, 240, 1, 'Principiante', 'Sentado, gira el balón de lado a lado tocando el suelo. Objetivo: oblicuos dinámicos. Cue: mantén los talones elevados. Error común: mover solo el balón sin rotar los hombros.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Russian Twist with Medicine Ball', 'Sitting, turn the ball from side to side touching the ground. Target: dynamic obliques. Cue: keep your heels raised. Common mistake: moving only the ball without rotating the shoulders.', 'external'),
('0ba9e9da-5944-4405-b6f0-35fb53974f0d', 'Single Arm Dumbbell Windmill', 25, 6, 81, 1, 'Avanzado', 'Con una mancuerna sobre la cabeza y pies anchos, inclina el torso hacia el pie opuesto manteniendo la pierna trasera recta y la mirada en la pesa.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Single Arm Dumbbell Windmill', 'With a dumbbell over your head and feet wide, lean your torso toward the opposite foot, keeping your back leg straight and your eyes on the weight.', 'external'),
('0bda9d32-ce04-4b6a-b7f7-1f153e0208fc', 'Flexiones de brazos (Push-ups)', 1, 2, 1, 1, 'Principiante', 'En posición de plancha, baja el pecho al suelo y empuja. Cue: codos a 45 grados del cuerpo. Error: dejar que la cadera se hunda o suba demasiado.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Push-ups', 'In a plank position, lower your chest to the floor and push. Cue: elbows at 45 degrees from the body. Common mistake: letting the hip withoutk or rise too much.', 'mixed'),
('0be406e4-78c3-40db-a3b8-52c2afc65d68', 'Face Pull', 6, 71, 151, 1, 'Principiante', 'Tira de la cuerda hacia la cara abriendo los extremos. Objetivo: salud del hombro y retractores. Cue: pulgares hacia atrás al final. Error común: adelantar el cuello al tirar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Face Pull', 'Pull the rope towards the face, opening the ends. Target: shoulder health and retractors. Cue: thumbs back at the end. Common mistake: putting the neck forward when pulling.', 'external'),
('0c3b5550-518a-4b31-9581-c778d132104e', 'Remo arquero en anillas con pies elevados', 71, 17, 1, 1, 'Intermedio', 'Con los pies elevados, tira del cuerpo hacia arriba mientras extiendes un brazo lateralmente, alternando el brazo que tracciona en cada repeticion.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ring Archer Row with Elevated Feet', 'With your feet raised, pull your body up while extending one arm laterally, alternating the pulling arm with each repetition.', 'bodyweight'),
('0c3fb19a-b641-4d1a-88c9-90ecb63125c4', 'Salto vertical unilateral max', 28, 29, 1, 1, 'Avanzado', 'Salta hacia arriba con una sola pierna buscando tocar un punto alto. Potencia pura unilateral. Cue: impulsa con el brazo contrario. Error común: valgo de rodilla al despegar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Max Unilateral Vertical Jump', 'Jump up with one leg looking to touch a high point. Pure unilateral power. Cue: push with the opposite arm. Common mistake: knee valgus when taking off.', 'bodyweight'),
('0c41ba23-35d8-423c-aeed-d66bc8221d1e', 'Press hombros en máquina unilateral', 6, 2, 186, 1, 'Principiante', 'Empuja una sola palanca de la máquina de hombro para corregir asimetrías. Objetivo: deltoides aislado. Cues: espalda firme contra el respaldo. Error común: arquear la lumbar al empujar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Unilateral Machine Shoulder Press', 'Push a single lever on the shoulder machine to correct asymmetries. Target: isolated deltoid. Cue: firm back against the backrest. Common mistake: arching the lower back when pushing.', 'external'),
('0c4f196d-537e-4b43-bf8b-4e03fcf96f09', 'Sentadilla Split Búlgara con déficit y mancuernas', 28, 29, 81, 1, 'Intermedio', 'Con el pie delantero sobre una plataforma pequeña y el trasero elevado en un banco, baja la cadera para lograr un rango de movimiento mas profundo.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Bulgarian Split Squat with Deficit and Dumbbells', 'With your front foot on a small platform and your butt raised on a bench, lower your hips for a deeper range of motion.', 'external'),
('0c6be42f-a9ec-48fd-aa86-a624a4c6ce22', 'Press de banca declinado con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'En un banco declinado, presiona dos Kettlebells invertidas hacia el techo, exigiendo un control extremo de la estabilidad del hombro y agarre.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Bottoms Up Double kettlebell Decline Bench Press', 'On a decline bench, press two inverted kettlebells toward the ceiling, demanding extreme control of shoulder stability and grip.', 'external'),
('0c6e2fb1-4da8-447c-912a-9a324a6c1752', 'Fitball pase manos pies', 25, 28, 290, 1, 'Avanzado', 'Tumbado, pasa la bola de tus manos a tus pies y viceversa sin tocar suelo. Coordinación abdominal. Lumbar apoyada. No arquees la espalda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Stability Ball pass hands feet', 'Lying down, pass the ball from your hands to your feet and vice versa without touching the ground. Abdominal coordination. Lumbar supported. Don''t arch your back.', 'bodyweight'),
('0c872bcd-ed07-41cf-8026-7de9804a932d', 'Jalón tras nuca en máquina', 16, 71, 186, 1, 'Intermedio', 'Tira de la barra por detrás de la cabeza hasta la base del cuello. Cue: pecho fuera. Error: inclinar la cabeza demasiado adelante.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Neck Pull on Machine', 'Pull the bar behind your head to the base of your neck. Cue: chest out. Common mistake: tilting your head too far forward.', 'external'),
('0c89492b-2f40-490f-87c4-602d96107841', 'Curl de bíceps en banco predicador con barra Z', 17, NULL, 116, 1, 'Intermedio', 'Apoya los brazos en el banco predicador y flexiona la barra Z. Objetivo: aislamiento total del bíceps. Cue: estira el brazo por completo en la bajada. Error común: levantar el codo de la almohadilla al subir.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Z-bar Preacher Bench Biceps Curl', 'Rest your arms on the preacher bench and flex the Z bar. Target: total isolation of the biceps. Cue: fully extend your arm on the downswing. Common mistake: lifting your elbow off the pad when going up.', 'external'),
('0ca17aa3-8f6d-4fb7-bc1a-a8257f73f367', 'Flexiones declinadas', 1, 6, 1, 1, 'Intermedio', 'Coloca los pies sobre una superficie elevada como un banco o step, manteniendo las manos en el suelo. Esta posición aumenta la carga sobre el pectoral superior y los hombros. Desciende controladamente manteniendo el cuerpo recto y empuja con fuerza para volver a la posición inicial. La altura de los pies determinará la dificultad del ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Decline Push-ups', 'Place your feet on an raised surface such as a bench or step, keeping your hands on the floor. This position increases the load on the upper chests and shoulders. Descend controlledly, keeping your body straight and push hard to return to the starting position. The height of your feet will determine the difficulty of the exercise.', 'mixed'),
('0caf8ec4-b785-479c-8b72-a5be57dc46b4', 'Salto al cajón desde split squat', 28, 29, 1, 1, 'Avanzado', 'Inicia en posición de zancada profunda y salta explosivamente sobre un cajón. Fuerza desde posición desfavorable. Cue: empuje vertical máximo. Error común: perder estabilidad antes del salto.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Box Jump From Split Squat', 'Start in a deep lunge position and jump explosively onto a box. Strength from an unfavorable position. Cue: maximum vertical thrust. Common mistake: losing stability before the jump.', 'mixed'),
('0cc8214b-49f5-497b-82b7-71a699363ac1', 'Sentadilla Búlgara rodilla sobre punta del pie', 28, 29, 1, 1, 'Intermedio', 'Con un pie elevado detras de ti, realiza una sentadilla split permitiendo que la rodilla delantera sobrepase los dedos del pie para enfatizar el trabajo del cuadriceps y la movilidad del tobillo.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Knee-on-toe Bulgarian Squat', 'With one foot raised behind you, perform a split squat allowing your front knee to extend over your toes to emphasize quadriceps work and ankle mobility.', 'mixed'),
('0cf05856-b865-4f99-bc27-2bfdbecae5cf', 'Sentadilla Dragón', 28, 29, 1, 1, 'Avanzado', 'Realiza una sentadilla profunda a una pierna cruzando la pierna libre por detrás de la pierna de apoyo, sin que esta toque el suelo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Dragon Squat', 'Perform a deep squat on one leg, crossing the free leg behind the supporting leg, without it touching the ground.', 'mixed'),
('0cf9ebf7-0167-4e76-9550-a3459196e399', 'Remo prono en banco inclinado a una mano con Kettlebell', 71, 17, 281, 1, 'Principiante', 'Apoya el pecho en un banco inclinado y rema una Kettlebell hacia tu costado con un solo brazo, aislando la musculatura de la espalda.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-handed Incline Bench Prone Row with Kettlebell', 'Rest your chest on an incline bench and row a kettlebell to your side with one arm, isolating your back muscles.', 'external'),
('0cfb9c77-f630-4d06-916e-783b3ebe908a', 'Fondos pecho banco bajo 45 grados', 1, 2, 1, 1, 'Principiante', 'Manos en banco, baja pecho. Cue: codos a 45. Error: hundir hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Chest Dips Low Bench 45 Degrees', 'Hands on bench, lower chest. Cue: elbows at 45. Common mistake: sinking shoulders.', 'mixed'),
('0cfeb7b9-0e49-4a92-8d69-dc152bd8b454', 'Copenhagen Plank con rodilla doblada y elevación lateral', 313, 25, 1, 1, 'Intermedio', 'En plancha lateral con la rodilla superior apoyada en banco, eleva la cadera trabajando los aductores y realiza una elevacion con la pierna libre.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Copenhagen Plank with Bent Knee and Lateral Raise', 'In a side plank with the upper knee supported on the bench, raise the hips working the adductors and perform a lift with the free leg.', 'bodyweight'),
('0d1c5e39-95df-4b03-9c38-ec74388572b4', 'Battle ropes side shuffle', 28, 6, 256, 24, 'Intermedio', 'Desplázate lateralmente mientras mantienes las ondas. Trabaja la agilidad lateral y la coordinación. Mantén una posición atlética baja y cambia de dirección periódicamente. El core debe permanecer estable.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Side Shuffle', 'Shuffle laterally while keeping the waves going. This works lateral agility and coordination. Maintain a low athletic stance and change direction periodically. Keep your core stable.', 'external'),
('0d2f06b7-43c1-4cb5-8c28-c04cca981208', 'Rompecráneos con barra Z (Skullcrusher)', 2, NULL, 116, 1, 'Intermedio', 'Acuéstate en un banco. Baja la barra Z hacia tu frente flexionando los codos, manteniendo los brazos perpendiculares al suelo. Extiende de nuevo.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Skullcrusher with Z Bar', 'Lie down on a bench. Lower the Z bar toward your forehead by bending your elbows, keeping your arms perpendicular to the floor. Extend again.', 'external'),
('0d3657f5-1468-4705-abe5-da4e38025cf5', 'Clean a Sots Press con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Realiza una cargada y, manteniéndote en la parte baja de la sentadilla, ejecuta un press militar completo sobre la cabeza.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Clean a Sots Press with Double Kettlebell', 'Perform a clean and, staying at the bottom of the squat, perform a full overhead military press.', 'external'),
('0d3e0e77-b601-42ec-bb28-c799d1bc652c', 'Snatch doble a sentadilla Overhead con Kettlebell', 28, 6, 281, 1, 'Avanzado', 'Ejecuta un snatch con dos Kettlebells y baja inmediatamente a una sentadilla profunda manteniendo el peso bloqueado sobre la cabeza.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Double Snatch to Overhead Squat with kettlebell', 'Perform a snatch with two kettlebells and immediately lower into a deep squat keeping the weight locked overhead.', 'external'),
('0d58180f-76e6-4624-9110-0a5689d60289', 'Face Pull con cuerda', 6, 71, 151, 1, 'Principiante', 'Tira de la cuerda hacia la cara separando los extremos. Salud de hombro. Retracción escapular. No adelantes la cabeza.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Face Pull with rope', 'Pull the rope toward your face, separating the ends. Shoulder health. Scapular retraction. Don''t put your head forward.', 'external'),
('0d80fe43-a6cc-47d7-8ee2-9a17bb570417', 'Curl de bíceps invertido con barra', 100, 17, 116, 1, 'Intermedio', 'Flexiona los codos con agarre prono (palmas hacia abajo). Objetivo: braquiorradial y antebrazos. Cue: mantén las muñecas rectas. Error común: usar excesivo peso que comprometa el agarre.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Barbell Inverted Biceps Curl', 'Bend your elbows with a prone grip (palms facing down). Target: brachioradialis and forearms. Cue: keep your wrists straight. Common mistake: using excessive weight that compromises grip.', 'external'),
('0d9aa86b-8747-4f49-93b4-99382528369c', 'Clamshells con banda', 29, 37, 61, 1, 'Principiante', 'Túmbate de lado con las rodillas flexionadas y una banda alrededor de las rodillas. Mantén los pies juntos y abre la rodilla superior como una almeja, resistiendo la tensión de la banda. Evita rotar la cadera hacia atrás. Excelente para activar el glúteo medio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Banded Clamshells', 'Lie on your side with your knees bent and a band around your knees. Keep your feet together and open your top knee like a clam, resisting the tension of the band. Avoid rotating your hips backwards. Excellent for activating the glutes medius.', 'external'),
('0d9d8764-c4af-43b6-9ea0-a24940632419', 'Press desde suelo', 1, 2, 116, 1, 'Avanzado', 'Press iniciando con la barra en el suelo, eliminando la fase excéntrica. Desarrolla fuerza concéntrica pura. Requiere flexibilidad para posicionarse. Usa bloques si es necesario. Popular en powerlifting para trabajar puntos débiles.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Press from the floor', 'Press starting with the bar on the floor, eliminating the eccentric phase. Develops pure concentric strength. Requires flexibility to position yourself. Use blocks if necessary. Popular in powerlifting to work on weak points.', 'external'),
('0db8dae9-f267-4eed-b7ad-74edbde33ef7', 'Turkish Sit Up con disco', 25, 6, 81, 1, 'Intermedio', 'Sit up manteniendo un disco extendido con ambos brazos hacia el techo, enfocando el esfuerzo en el core y hombros estables.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Turkish Sit-Up with Weight Plate', 'Perform a sit-up while holding a weight plate straight overhead with both arms, emphasizing core strength and shoulder stability.', 'external'),
('0dc804ef-2c06-402d-80a2-a1101931ae48', 'Extensión de tríceps Overhead arrodillado con barra Z', 2, NULL, 116, 1, 'Principiante', 'De rodillas sobre ambas piernas, baja la barra Z por detras de tu cabeza flexionando los codos y extiende de nuevo al techo.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Z-Bar Kneeling Overhead Triceps Extension', 'Kneeling on both legs, lower the Z bar behind your head by bending your elbows and extend it back to the ceiling.', 'external'),
('0ddbbd3b-a706-49d0-bc5b-18b8eea4927b', 'V-roll out', 25, NULL, 271, 1, 'Avanzado', 'Rueda formando un patrón en V, alternando diagonales. Trabaja el core desde múltiples ángulos. Requiere control excepcional y fuerza en los oblicuos. Mantén movimientos simétricos en ambos lados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'V-roll Out', 'Roll out in a V pattern, alternating diagonals. It works the core from multiple angles. It requires exceptional control and oblique strength. Keep the movement symmetrical on both sides.', 'external'),
('0df52446-40fe-495d-ba33-c90acaeaa926', 'Sentadilla Búlgara con mancuernas en Fitball', 28, 29, 81, 1, 'Avanzado', 'Realiza una sentadilla búlgara apoyando el pie trasero sobre un Fitball inestable mientras sostienes mancuernas a los costados.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Bulgarian squat with dumbbells on Stability Ball', 'Perform a Bulgarian squat by resting your back foot on an unstable stability ball while holding dumbbells at your sides.', 'external'),
('0df750b4-2729-462f-a642-fa4cae98759b', 'Renegade row mancuernas', 16, 25, 81, 1, 'Avanzado', 'En posición de plancha con las manos sobre mancuernas, realiza un remo alternando brazos mientras mantienes la estabilidad del core. Evita la rotación de caderas. Requiere fuerza significativa en core y espalda, además de excelente estabilización.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Renegade row dumbbells', 'In a plank position with your hands on dumbbells, perform a row alternating arms while maintaining core stability. Avoid hip rotation. Requires significant core and back strength, as well as excellent stabilization.', 'external'),
('0df9b2b6-b48d-452c-b15a-13d6e200c65c', 'Flexiones', 1, 2, 1, 1, 'Principiante', 'Realiza una flexión manteniendo el cuerpo alineado desde la cabeza hasta los pies. Baja el pecho de forma controlada y empuja el suelo hasta extender los brazos.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Push-Up', 'Perform a push-up while keeping the body aligned from head to heels. Lower the chest under control and push the floor away until the arms are extended.', 'bodyweight'),
('0dfe54ed-0712-4095-8c5c-5102f1373d6b', 'Puente glúteo fitball', 29, 55, 290, 1, 'Intermedio', 'Eleva cadera con pies en fitball. Objetivo: glúteo/isquios. Cue: aprieta core. Error: bola ruede.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Stability Ball Glute Bridge', 'Raise your hips with your feet on a stability ball. Target: glutes and hamstrings. Cue: brace your core. Common mistake: letting the ball roll out of control.', 'bodyweight'),
('0e007610-750f-40cb-b6a8-e5cc8b063242', 'Step Up con barra tras nuca', 28, 29, 116, 1, 'Intermedio', 'Sube a un banco con la barra sobre los trapecios, empujando con la pierna delantera hasta la extension completa de cadera.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Back Rack Barbell Step-up', 'Step onto a bench with the barbell resting across your upper back, driving through the lead leg until your hip is fully extended.', 'external'),
('0e2aff42-e79b-4c7f-b571-ac9f4b754742', 'Stability Ball Knee Tuck', 25, 6, 290, 1, 'Intermedio', 'En posición de plancha con las espinillas sobre el Fitball, rueda el balón hacia adelante llevando las rodillas al pecho. Extiende las piernas para volver a la plancha.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball Knee Tuck', 'In a plank position with your shins on the stability ball, roll the ball forward, bringing your knees to your chest. Extend your legs to return to the plank.', 'bodyweight'),
('0e519696-19c0-4d71-a4c0-7be4425d928c', 'Remo arquero en anillas', 71, 6, 1, 1, 'Avanzado', 'Tira del cuerpo hacia arriba mientras extiendes un brazo lateralmente emulando a un arquero, rotando la tensión hacia un solo brazo.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Ring archer row', 'Pull your body up while extending one arm laterally emulating an archer, rotating the tension toward a single arm.', 'bodyweight'),
('0e62bf7c-80c9-4520-87f4-a3b76ff780ad', 'Curl de bíceps a una mano con cable', 17, NULL, 151, 1, 'Principiante', 'De pie frente a la polea baja. Realiza un curl con un solo brazo manteniendo el codo fijo al costado.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-Handed Cable Biceps Curl', 'Standing facing the low cable. Perform a one-arm curl while keeping your elbow fixed to your side.', 'external'),
('0e7e9f25-efef-4dfb-943e-803972994de3', 'Sentadilla isométrica en pared (Wall Sit)', 28, 29, 1, 24, 'Principiante', 'Apoya la espalda en la pared y baja hasta que tus muslos estén paralelos al suelo y las rodillas a 90 grados. Mantén la posición.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Isometric wall squat (Wall Sit)', 'Lean your back against the wall and lower yourself until your thighs are parallel to the floor and your knees are at 90 degrees. Hold the position.', 'mixed'),
('0e9c6dd2-1b2e-4f04-8a7a-dafcee6db107', 'Sentadilla sumo barra nuca', 29, 313, 116, 1, 'Intermedio', 'Pies anchos barra hombros. Objetivo: aductor/glúteo. Cue: rodillas fuera. Error: talones aire.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Neck Bar Sumo Squat', 'Wide feet bar shoulders. Target: adductor and glute. Cue: knees out. Common mistake: air heels.', 'external'),
('0ec90d63-beb8-443b-85cf-4be09e898b35', 'Flexiones bosu', 1, 2, 298, 1, 'Intermedio', 'Flexiones con manos sobre el lado plano o redondo del bosu. La superficie inestable aumenta la activación de estabilizadores del hombro y core. Comienza con el lado plano hacia arriba para menor dificultad. Mantén control total.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'BOSU Push Ups', 'Push-ups with hands on the flat or round side of the bosu. The unstable surface increases the activation of shoulder and core stabilizers. Start with the flat side up for less difficulty. Maintain full control.', 'bodyweight'),
('0ecb99ec-5165-4fcf-b67a-8bde8132becb', 'Peso muerto Sumo a una mano con Kettlebell', 71, 29, 281, 1, 'Principiante', 'Con postura ancha, levanta la Kettlebell del suelo con una sola mano manteniendo la espalda neutra y el core activado.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'One-handed Sumo Deadlift with Kettlebell', 'With a wide stance, lift the kettlebell off the floor with one hand, keeping your back neutral and core activated.', 'external'),
('0fa7fe39-4da1-4c26-ad8d-76a6c11b41e4', 'Archer Push Up', 1, 2, 1, 1, 'Intermedio', 'Baja el cuerpo hacia un lado mientras estiras el brazo opuesto lateralmente, imitando la apertura de un arco para mayor carga unilateral.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Archer Push Up', 'Lower your body to one side while stretching the opposite arm laterally, imitating the opening of a bow for greater unilateral loading.', 'mixed'),
('0ff89d39-d509-461d-82f3-7c50adb30cdd', 'Dominada a un brazo negativa', 16, 17, 1, 1, 'Avanzado', 'Fase excéntrica controlada de dominada usando un solo brazo. Excelente progresión hacia dominada completa a un brazo. Comienza desde arriba y desciende lo más lento posible. Usa asistencia para volver arriba. Alterna brazos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Negative one arm pull-up', 'Controlled eccentric pull-up phase using one arm. Excellent progression towards full one-arm pull-up. Start from the top and descend as slowly as possible. Use assist to get back up. Alternate arms.', 'mixed'),
('0ffdf7d4-7798-49bc-82a6-64f03e7aa2f3', 'Ring Hanging Knee Raise', 25, 100, 1, 1, 'Intermedio', 'Cuélgate de las anillas con los brazos estirados. Contrae el abdomen y levanta las rodillas hacia el pecho de forma controlada. Baja las piernas lentamente evitando balancearte.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Hanging Knee Raise', 'Hang from the rings with your arms outstretched. Contract your abs and raise your knees toward your chest in a controlled manner. Lower your legs slowly, avoiding swinging.', 'bodyweight'),
('1007a5b7-f088-496b-bf2c-b99ec783e4a8', 'Thruster Ciclista con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sujeta dos Kettlebells invertidas en posicion rack, baja en sentadilla ciclista y empuja ambas hacia el techo, manteniendo el equilibrio del peso.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Cyclist Double Bottoms-Up Kettlebell Thruster', 'Hold two upside-down kettlebells in the rack position, lower into a cyclist squat, and press both toward the ceiling while maintaining balance and control.', 'external'),
('1009949c-12c6-4081-a5dd-229c510e428a', 'Cable crossover', 1, NULL, 151, 1, 'Intermedio', 'Ejercicio clásico de cruces de cables desde poleas altas. Inclínate ligeramente hacia adelante y junta las manos frente al pecho o abdomen con un movimiento de abrazo. La tensión constante del cable maximiza el trabajo del pectoral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Crossover Cable', 'Classic cable crossover exercise from high cables. Lean forward slightly and bring your hands together in front of your chest or abs in a hugging motion. The constant tension of the cable maximizes the work of your chest.', 'external'),
('102ae941-ade5-420e-8630-615e5ed431dc', 'Sentadilla sumo mancuernas manos abajo', 313, 29, 81, 1, 'Principiante', 'Pies anchos, sujeta dos pesas abajo. Cue: pecho alto. Error: redondear lumbar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Sumo Squat Dumbbell Hands Down', 'Feet wide, hold two dumbbells below. Cue: chest up. Common mistake: lumbar rounding.', 'external'),
('1038df6a-f4f3-47cb-8e70-01860d9d49e9', 'Curl bíceps máquina', 17, NULL, 186, 1, 'Principiante', 'Sentado con los brazos apoyados, realiza flexiones de codo. La máquina estabiliza el movimiento permitiendo máximo aislamiento del bíceps. Algunas versiones permiten trabajo unilateral. Controla especialmente la fase negativa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Biceps Curl Machine', 'Sitting with your arms supported, perform elbow curls. The machine stabilizes the movement allowing maximum isolation of the biceps. Some versions allow unilateral work. Especially control the negative phase.', 'external'),
('103ef22a-2063-45ae-b93e-5258908e36ef', 'Salto de potencia con mancuernas', 28, 6, 81, 1, 'Intermedio', 'Salta verticalmente sosteniendo mancuernas a los lados. Aumenta la carga en el ciclo de estiramiento. Cue: aterriza con rodillas flexionadas. Error común: balancear las pesas en exceso.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Dumbbell Power Jump', 'Jump vertically holding dumbbells at your sides. Increase the load in the stretching cycle. Cue: land with bent knees. Common mistake: swinging the weights too much.', 'external'),
('10620311-a9c3-46c1-8940-52a4b2da45b8', 'Salto de rana continuo', 29, 64, 1, 1, 'Avanzado', 'Encadena saltos de rana sin pausa, minimizando el tiempo en el suelo. Resistencia pliométrica. Cue: mantén el ritmo fluido. Error común: detenerse por completo entre saltos.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Continuous Frog Jump', 'Chain frog jumps without pause, minimizing time on the ground. Plyometric resistance. Cue: keep the rhythm flowing. Common mistake: stopping completely between jumps.', 'bodyweight'),
('10686e87-54b2-43dc-98b2-3ef17a23ad41', 'Aperturas inclinadas con mancuernas', 1, 6, 81, 1, 'Intermedio', 'Banco a 30-45 grados, abre brazos lateralmente y cierra buscando el estímulo superior. Cue: codos semiflexionados. Error: bajar demasiado estirando el hombro.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Incline Dumbbell Flyes', 'Bench at 30-45 degrees, open your arms laterally and close looking for the upper stimulus. Cue: slightly bent elbows. Common mistake: going down too much by stretching the shoulder.', 'external'),
('10703ccc-1202-4fee-9027-4cd34cd8ec18', 'Wall Squat fitball', 28, 29, 290, 1, 'Principiante', 'Sentadilla con bola en pared. Objetivo: técnica cuádriceps. Cue: rodilla-pie alineados. Error: despegar talón.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Wall Squat Stability Ball', 'Perform a squat against a wall with a stability ball behind your back. Target: quadriceps technique. Cue: keep your knees aligned with your feet. Common mistake: lifting your heels.', 'bodyweight'),
('10b2caf5-50b1-4b4f-8480-a87c2b068a30', 'Curl martillo inclinado', 17, 100, 81, 1, 'Intermedio', 'Sentado en banco inclinado, realiza curl martillo. Objetivo: braquial y cabeza larga. Cue: codos hacia el suelo siempre. Error común: balancear el hombro para ayudar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Incline Hammer Curl', 'Sitting on an incline bench, perform hammer curls. Target: brachialis and long head. Cue: elbows towards the floor always. Common mistake: swinging your shoulder to help.', 'external'),
('10b9cf7e-f3ae-44c0-ab6d-54c14058bbbf', 'Remo bajo a una mano de rodillas', 71, 17, 151, 1, 'Principiante', 'En posición de caballero frente a una polea baja, tira del cable hacia la cadera manteniendo la espalda recta y el core activo.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Kneeling one-handed low row', 'In a half-kneeling position facing a low pulley, pull the cable toward your hips, keeping your back straight and your core active.', 'external'),
('10ba1ef7-10bd-4c22-8ca7-b8c6f2478cd2', 'TRX Remo a una mano', 71, 25, 216, 1, 'Avanzado', 'Realiza remo inclinado usando solo un agarre. Evita la rotación del tronco. Core muy firme. Espalda neutra. No des tirones con el hombro.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Single-Arm Row', 'Perform an angled row using only one handle. Avoid rotating your torso, keep your core braced, maintain a neutral spine, and do not yank with the shoulder.', 'bodyweight'),
('10c1996f-056a-4e2b-ba1b-154f93f5737f', 'Overhead slam', 25, 6, 240, 1, 'Intermedio', 'Similar al slam ball pero enfatizando la extensión completa sobre la cabeza antes del golpe. Involucra más los dorsales y proporciona mayor rango de movimiento. Usa todo el cuerpo para generar máxima potencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Overhead Slam', 'Similar to the slam ball but emphasizing full extension overhead before the hit. It engages the lats more and provides greater range of motion. Use your entire body to generate maximum power.', 'external'),
('10d7f6a5-37c5-400b-b2ef-09edc9885138', 'Bosu sentadilla inestable', 28, 37, 298, 1, 'Intermedio', 'Realiza sentadillas sobre la parte semiesférica del bosu. Estabilidad de tobillo. Rodillas alineadas. No mires al suelo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'BOSU Squat', 'Perform squats on the hemispherical part of the bosu. Ankle stability. Knees aligned. Don''t look at the ground.', 'bodyweight'),
('10f0d2aa-5f5a-40ad-a810-1f5b01303406', 'Extensión de cadera en cuadrupedia', 29, NULL, 1, 1, 'Principiante', 'En posición de cuatro puntos, patea una pierna hacia el techo manteniendo la rodilla doblada a 90 grados. Aprieta el glúteo en el tope.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Quadruped hip extension', 'In a four-point stance, kick one leg toward the ceiling, keeping your knee bent at 90 degrees. Squeeze your glute at the top.', 'bodyweight'),
('1116c039-12f4-4943-802a-03200c4b1c1f', 'Upright row barra', 6, 71, 116, 1, 'Intermedio', 'Con la barra frente a los muslos y agarre cerrado o medio, tira verticalmente llevando los codos hacia arriba y afuera hasta que la barra llegue al nivel del pecho. Mantén la barra cerca del cuerpo. Ten cuidado con este ejercicio si tienes problemas de hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Upright Row', 'With the bar in front of your thighs and a narrow to medium grip, pull it vertically by driving your elbows up and out until the bar reaches chest height. Keep the bar close to your body. Be cautious with this exercise if you have shoulder issues.', 'external'),
('11257b14-1e6f-444b-b96d-e05f28022ef3', 'Curl de bíceps con barra recta', 17, 100, 116, 1, 'Principiante', 'Flexiona los codos sujetando la barra con palmas arriba. Objetivo: masa general del bíceps. Cues: codos fijos al torso. Error común: mover los hombros hacia adelante al subir.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Straight Bar Biceps Curl', 'Bend your elbows while holding the bar with your palms up. Target: general biceps mass. Cue: elbows fixed to the torso. Common mistake: moving your shoulders forward when going up.', 'external'),
('114b9e2e-9a4a-48df-9143-f932d44f7032', 'Flexión pliométrica lateral', 1, 25, 1, 1, 'Avanzado', 'Salta lateralmente con las manos en cada flexión para avanzar de lado. Cue: coordinación manos-core. Error común: que la cadera se hunda durante el desplazamiento.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Plyometric Bend', 'Jump laterally with your hands on each push-up to move sideways. Cue: hands-core coordination. Common mistake: the hip withoutks during movement.', 'mixed'),
('114bb31c-9bd3-499a-91fb-677828361bc7', 'Remo prono alterno en banco inclinado con mancuernas', 71, 17, 81, 1, 'Principiante', 'Tumbado boca abajo en banco inclinado, rema las mancuernas alternativamente hacia tu cadera para aislar el trabajo dorsal.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Incline Bench Alternating Prone Row with Dumbbells', 'Lying face down on an incline bench, row the dumbbells alternately toward your hips to isolate the back work.', 'external'),
('1164c727-b755-4879-b114-1912e7e8ffd7', 'Patada tríceps mancuernas ambas', 2, NULL, 81, 1, 'Intermedio', 'Extiende ambos brazos atrás inclinado. Cue: codos altos. Error: balancear pesas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Triceps Kick Dumbbells Both', 'Extend both arms behind you at an angle. Cue: high elbows. Common mistake: swinging weights.', 'external'),
('117adcd1-08b2-47e8-aafa-8b7b1146725f', 'Snatch doble a Zancada inversa alterna Overhead con Kettlebell', 28, 29, 281, 1, 'Avanzado', 'Lanza dos Kettlebells sobre la cabeza y realiza zancadas alternas manteniendo los brazos bloqueados en todo momento.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double Snatch to Alternate Reverse Lunge Overhead with kettlebell', 'Throw two kettlebells overhead and perform alternating lunges, keeping your arms locked at all times.', 'external'),
('117d9e0e-0b9d-4f5f-8170-470654fe3d55', 'Extensión de tríceps con barra V', 2, NULL, 151, 1, 'Principiante', 'Empuja la barra hacia abajo bloqueando codos. Estabilidad. Espalda recta. No separes los codos del cuerpo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'V-Bar Triceps Extension', 'Push the bar down while locking your elbows. Stability. Straight back. Do not separate your elbows from your body.', 'external'),
('11868777-afbb-4b25-ac2d-f5163c4f4d66', 'Flexiones lalanne', 2, 6, 1, 1, 'Avanzado', 'Flexiones con brazos extendidos muy por delante del cuerpo. Nombradas por Jack LaLanne. El brazo de palanca extremo las hace increíblemente difíciles. Progresa aumentando gradualmente la distancia de las manos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'LaLanne Push-Ups', 'Push-ups with arms extended well in front of the body. Named by Jack LaLanne. The extreme lever arm makes them incredibly difficult. Progress by gradually increasing the distance of your hands.', 'mixed'),
('12026ad3-4717-4d6f-bf3d-96dc0c315e9c', 'Caminata en parada de manos', 6, 25, 1, 1, 'Avanzado', 'Camina sobre las manos manteniendo el equilibrio invertido. Requiere fuerza en hombros, control del core y coordinación excepcional. Comienza con pasos pequeños cerca de una pared. Progresa aumentando distancia y velocidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Handstand walk', 'Walk on your hands while maintaining inverted balance. Requires shoulder strength, core control and exceptional coordination. Start with small steps near a wall. Progress by increasing distance and speed.', 'bodyweight'),
('124249bd-29bb-48aa-8416-0556d576e454', 'Sentadilla Pistola a cajón', 28, 29, 1, 1, 'Principiante', 'Realiza una sentadilla a una pierna bajando de forma controlada hasta sentarte ligeramente en un cajón o banco, y vuelve a subir con la misma pierna.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Box Pistol Squat', 'Perform a one-leg squat, lowering yourself down in a controlled manner until you sit lightly on a box or bench, and return back up with the same leg.', 'mixed'),
('1245502f-1417-40f1-8d37-117abc7d197d', 'Saltos de potencia (Bounds)', 29, 28, 1, 1, 'Avanzado', 'Salta hacia adelante buscando el máximo tiempo de vuelo en cada zancada. Impulso explosivo de cadera. Brazos coordinados. No aterrices con la pierna rígida.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Power Jumps (Bounds)', 'Jump forward seeking maximum flight time with each stride. Explosive hip thrust. Coordinated arms. Don''t land with a stiff leg.', 'mixed'),
('128ad98b-9ef6-4eb9-9c33-442b42e6c7a5', 'Buenos días sentado con barra', 71, 29, 116, 1, 'Intermedio', 'Sentado en un banco con la barra en los hombros, inclina el torso hacia adelante manteniendo la espalda recta hasta quedar paralelo al suelo.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Seated Barbell Good Morning', 'Sitting on a bench with the bar on your shoulders, lean your torso forward, keeping your back straight until you are parallel to the floor.', 'external'),
('12908de9-6fa9-4abf-8c73-82755dd20d3e', 'Zancada caminando con mancuernas (Maleta)', 28, 29, 81, 1, 'Principiante', 'Camina dando pasos largos mientras sostienes una mancuerna en cada mano a los costados del cuerpo, manteniendo el torso erguido y las rodillas a 90 grados.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Walking Suitcase Dumbbell Lunge', 'Walk forward with long steps while holding a dumbbell in each hand at your sides, keeping your torso upright and both knees close to 90 degrees.', 'external'),
('1298c0e1-8732-4af0-9877-f786680b6fe7', 'Zancada caminando Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Sostén dos Kettlebells en posición de rack sobre el pecho y camina realizando zancadas, manteniendo los codos arriba y el core muy estable.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Walking Front Rack Double Kettlebell Lunge', 'Hold two kettlebells in the rack position over your chest and walk forward into lunges, keeping your elbows high and your core very stable.', 'external'),
('129ffc3a-9198-4cc9-9049-286e5939e8a9', 'Flexiones pseudo planche', 6, 2, 1, 1, 'Avanzado', 'Flexiones con manos posicionadas más atrás, cerca de las caderas, inclinando el cuerpo hacia adelante. Simula la posición del planche. Excelente progresión hacia el planche completo. Aumenta gradualmente la inclinación hacia adelante.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pseudo planche push-ups', 'Push-ups with hands positioned further back, close to the hips, leaning the body forward. Simulates the position of the plank. Excellent progression towards the complete planche. Gradually increase your forward lean.', 'mixed'),
('12a24c7d-f7b3-4970-89cc-d4274ce53fa1', 'Empuje cadera una pierna', 29, NULL, 116, 1, 'Avanzado', 'Hip thrust unilateral con barra. Extremadamente desafiante para el glúteo y la estabilización. Comienza con peso corporal y progresa. Mantén la pelvis nivelada durante todo el movimiento. Alterna piernas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One leg hip thrust', 'Unilateral hip thrust with barbell. Extremely challenging for the glute and stabilization. Start with body weight and progress. Keep your pelvis level throughout the movement. Alternate legs.', 'external'),
('130ab53a-f0e6-43e4-b097-0812346f932d', 'Hip Thrust con barra', 29, 55, 116, 1, 'Intermedio', 'Espalda en banco, barra en cadera, eleva pelvis hasta quedar paralelo al suelo. Cue: barbilla al pecho, aprieta glúteo. Error: arquear lumbar arriba.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Hip Thrust', 'Back on the bench, bar on the hips, raise the pelvis until it is parallel to the floor. Cue: chin to chest, glute squeeze. Common mistake: arching your lower back upwards.', 'external'),
('130dfd53-8627-4d94-8dcf-d7ac87b1be95', 'Flexiones diamante con rodillas', 2, 1, 1, 1, 'Principiante', 'Flexión con manos formando un diamante bajo el pecho y rodillas apoyadas. Objetivo: iniciación fuerza tríceps. Cue: codos pegados al cuerpo. Error común: arquear la espalda lumbar.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Diamond Push-ups with Knees', 'Perform a push-up with your hands forming a diamond under your chest and your knees on the floor. Target: introductory triceps strength. Cue: keep your elbows close to the body. Common mistake: arching the lower back.', 'mixed'),
('132b44dc-a452-474f-99e0-40bbbbbb5740', 'Bird dog', 71, 29, 1, 1, 'Principiante', 'En posición de cuadrupedia, extiende simultáneamente el brazo derecho al frente y la pierna izquierda hacia atrás, formando una línea recta. Mantén la posición sin rotar las caderas y vuelve controladamente. Alterna con el otro lado. Excelente para la estabilidad del core y coordinación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bird Dog', 'In a quadruped position, simultaneously extend your right arm in front and your left leg backwards, forming a straight line. Maintain the position without rotating your hips and return under control. Alternate with the other side. Excellent for core stability and coordination.', 'bodyweight'),
('1347f6e3-5bff-4cfc-9cd7-59f62e9b13e7', 'Sentadilla trasera a cajón con barra', 28, 29, 116, 1, 'Principiante', 'Baja en sentadilla con la barra tras la nuca hasta que los glúteos toquen el cajón, haz una pausa mínima y vuelve a subir.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Barbell box back squat', 'Squat down with the bar behind your neck until your glutes touch the box, pause briefly and go back up.', 'external'),
('13639b4a-b636-40d8-9a32-77eb1dd2b043', 'Sentadilla Ciclista con barra baja', 28, 29, 116, 1, 'Intermedio', 'Ejecuta una sentadilla con talones elevados apoyando la barra sobre los deltoides posteriores para enfatizar el empuje vertical de los cuádriceps.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Cycling Squat with Low Bar', 'Perform a squat with raised heels, resting the bar on the rear deltoids to emphasize the vertical push of the quadriceps.', 'external'),
('136e573d-dc95-4b81-98bb-9bff98fdcdc6', 'Press Pallof arrodillado con banda elástica', 25, 6, 61, 1, 'Principiante', 'Arrodillado sobre ambas rodillas, sujeta la banda frente al pecho y extiendela hacia adelante resistiendo la traccion lateral de la banda.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Kneeling Pallof Press with Elastic Band', 'Kneeling on both knees, hold the band in front of your chest and extend it forward, resisting the lateral pull of the band.', 'external'),
('13d05b40-641e-4a1e-bfb3-e41bc8853082', 'Curl de muñeca sentado agarre inverso con barra', 100, NULL, 116, 1, 'Intermedio', 'Apoya los antebrazos en los muslos con las palmas hacia arriba y flexiona las muñecas para elevar la barra cargada hacia ti.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Seated Reverse Grip Barbell Wrist Curl', 'Rest your forearms on your thighs with your palms facing up and flex your wrists to raise the loaded bar toward you.', 'external'),
('140bda7e-0f85-4064-b86e-edcd61382b92', 'RDL máquina Smith isquios', 55, 29, 186, 1, 'Intermedio', 'Peso muerto rumano guiado. Cue: cadera atrás. Error: curvar espalda.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Smith Machine Romanian Deadlift for Hamstrings', 'Romanian deadlift on the Smith machine. Cue: push your hips back. Common mistake: rounding your back.', 'external'),
('144676aa-94da-4bca-b28a-c8d7b519186a', 'Fondos en paralelas (Pecho)', 1, 2, 1, 1, 'Intermedio', 'Baja inclinando el torso adelante. Objetivo: pectoral inferior. Cues: hombros estables. Error común: encoger hombros.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Parallel Dips (chest)', 'Go down by leaning your torso forward. Target: lower chest. Cue: stable shoulders. Common mistake: shrugging shoulders.', 'mixed'),
('144844dd-7852-4680-a4b5-0f19a79ce00a', 'Crunch oblicuo invertido colgado', 25, NULL, 1, 1, 'Avanzado', 'Colgado boca abajo, realiza una flexión abdominal llevando un hombro hacia la cadera opuesta para enfatizar el trabajo de los oblicuos.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Hanging Inverted Oblique Crunch', 'Hanging upside down, perform an abdominal flexion by bringing one shoulder towards the opposite hip to emphasize the work of the obliques.', 'bodyweight'),
('14a70633-eb2b-4e18-91dc-511da0abf65b', 'Press anti-rotación cable', 25, NULL, 151, 1, 'Avanzado', 'De lado al cable, extiende los brazos al frente resistiendo la rotación. Variación avanzada del Pallof press. Puedes añadir movimientos: caminar, sentadillas, etc., manteniendo la resistencia anti-rotación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Anti-Rotation Press', 'Standing sideways to the cable, extend your arms in front of you resisting rotation. Advanced variation of the Pallof press. You can add movements: walking, squats, etc., maintaining anti-rotation resistance.', 'external'),
('14bdcdc0-6a6a-4b73-9ddd-9dcfb1a36cd9', 'Press banca', 1, 2, 116, 1, 'Intermedio', 'Realiza un press de banca plano con barra. Baja la barra hasta el pecho de forma controlada y empuja hacia arriba manteniendo una técnica estable.', FALSE, NULL, '2026-04-21T15:25:53.603328+00:00', 'Bench Press', 'Perform a flat barbell bench press. Lower the bar to the chest under control and press upward while maintaining stable technique.', 'external'),
('14d06d40-d2af-45bd-9ec6-6614087b725a', 'Elevación W con mancuernas en Fitball', 6, 71, 81, 1, 'Intermedio', 'Boca abajo sobre el Fitball, levanta los brazos doblados formando una W, apretando los omóplatos y rotadores externos.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Dumbbell W Raise on Stability Ball', 'Face down on the Stability Ball, raise your bent arms forming a W, squeezing your shoulder blades and external rotators.', 'external'),
('14f9a69f-13ab-476f-ada3-fee060f9b8fa', 'Plank con arrastre de Kettlebell alterno', 25, 6, 281, 1, 'Intermedio', 'En posición de plancha alta, arrastra una Kettlebell por debajo del torso de un lado al otro alternando el brazo que tracciona.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Plank with Alternating kettlebell Drag', 'In a high plank position, drag a kettlebell under your torso from one side to the other, alternating the pulling arm.', 'external'),
('15189672-c417-44c1-a700-cdec3a95067d', 'Miniband Fire Hydrant', 29, 37, 61, 1, 'Principiante', 'En cuadrupedia con una banda sobre las rodillas, levanta una pierna lateralmente manteniendo la rodilla doblada, como un perro. Baja controlando la resistencia.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Mini Band Fire Hydrant', 'On all fours with a band over your knees, lift one leg laterally while keeping your knee bent, like a dog. Lower by controlling the resistance.', 'external'),
('151e08e3-7971-4ae1-b069-86cb3e92d270', 'Turkish Sit Up con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'Acuéstate boca arriba con un brazo extendido sosteniendo una Kettlebell y realiza un sit up manteniendo la carga vertical en todo momento.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Turkish Sit Up with Kettlebell Single-arm', 'Lie on your back with one arm extended while holding a kettlebell and perform a sit-up, keeping the weight vertical throughout the movement.', 'external'),
('15362bd7-d794-44b2-82ae-e683aa53ecb7', 'Zancada inversa Goblet con Kettlebell y Slider', 28, 29, 281, 1, 'Intermedio', 'Sostén la pesa rusa en copa (frente al pecho) y desliza una pierna hacia atrás en un slider hasta que la rodilla casi toque el suelo.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Goblet Reverse Stride with Kettlebell and Slider', 'Hold the kettlebell in a cup (in front of your chest) and slide one leg back on a slider until your knee almost touches the ground.', 'external'),
('154f3687-0373-48a4-9e8b-f60537e3e8b0', 'Sentadilla Overhead en equilibrio sobre dedos con barra', 28, 64, 116, 1, 'Avanzado', 'Realiza una sentadilla profunda manteniendo el equilibrio sobre las puntas de los pies y la barra cargada sobre la cabeza.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Overhead squat balanced on fingers with barbell', 'Perform a deep squat, balancing on the balls of your feet and the loaded bar overhead.', 'external'),
('156693e3-0854-4ccb-9cef-33f4aa2d50c2', 'Hip Thrust a una pierna con barra', 29, NULL, 116, 1, 'Avanzado', 'Realiza un Hip Thrust con barra pero usando solo una pierna de apoyo, manteniendo la barra equilibrada y la cadera nivelada.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'One-Leg Barbell Hip Thrust', 'Perform a Hip Thrust with a barbell but using only one supporting leg, keeping the bar balanced and your hips level.', 'external'),
('156ffa33-d47f-4e05-85ee-548db1749ed0', 'Sentadilla Búlgara Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Realiza una sentadilla split con el pie trasero elevado en un banco y dos Kettlebells en posición de rack sobre el pecho.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Bulgarian Front Rack Squat with Double Kettlebell', 'Perform a split squat with your back foot raised on a bench and two kettlebells in a rack position on your chest.', 'external'),
('157dd472-27bc-45c2-9a08-867fe97ae65b', 'Saltos de tijera rápidos', 64, 55, 1, 1, 'Principiante', 'Cambia la posición de los pies adelante y atrás con saltos pequeños y veloces. Mejora la frecuencia de zancada. Espalda recta. No te inclines hacia adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Quick jumping jacks', 'Change the position of your feet back and forth with small, fast jumps. Improves stride frequency. Straight back. Don''t lean forward.', 'bodyweight'),
('15caca70-b07d-47a3-962e-bc9d02bb228c', 'Sentadilla frontal agarre Clean', 28, 25, 116, 1, 'Avanzado', 'Barra sobre deltoides frontales, codos altos y paralelos al suelo, baja en sentadilla. Objetivo: cuádriceps con torso vertical. Cues: empuja codos hacia arriba. Error común: dejar caer los codos, haciendo que la barra ruede.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Clean Grip Front Squat', 'Barbell on front deltoids, elbows high and parallel to the floor, lower into a squat. Target: quadriceps with vertical torso. Cue: push elbows up. Common mistake: dropping your elbows, causing the bar to roll.', 'external'),
('15ce37f0-4b41-4c24-9108-babe751033b6', 'Press Cubano de rodillas con banda a una mano', 6, 2, 61, 1, 'Intermedio', 'De rodillas, usa una banda elástica para realizar la secuencia: remo vertical, rotación externa y press sobre la cabeza.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Kneeling Cuban Press with one-hand band', 'On your knees, use an elastic band to perform the sequence: upright row, external rotation, and overhead press.', 'external'),
('15e5a8b0-583a-4ff5-9eed-b5f763b5a308', 'Puente de glúteo isométrica', 29, 55, 1, 24, 'Principiante', 'Eleva la cadera y mantén la posición máxima arriba apretando los glúteos. Objetivo: resistencia posterior. Cue: empuja fuerte con los talones. Error: hiperextender la zona lumbar en lugar de usar glúteo.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Isometric Glute Bridge', 'Raise your hips and maintain the maximum position up by squeezing your glutes. Target: posterior resistance. Cue: push hard with your heels. Common mistake: hyperextending the lower back instead of using the glute.', 'mixed'),
('15ec8464-fff7-4865-941c-e1d6c5c13811', 'Press Overhead arrodillado a una mano con mancuerna', 6, 2, 81, 1, 'Intermedio', 'De rodillas sobre ambas piernas, realiza un press de hombro con un solo brazo, resistiendo la tendencia del torso a inclinarse.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Kneeling Dumbbell Overhead Press', 'Kneeling on both legs, perform a one-arm shoulder press, resisting the torso''s tendency to tilt.', 'external'),
('1613d81b-58ba-4820-87cb-9b0a016f627f', 'Press banca mancuernas giro neutro-prono', 1, 2, 81, 1, 'Intermedio', 'Gira pesas al subir de neutro a prono. Cue: control total. Error: inestabilidad arriba.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Dumbbell Bench Press Neutral-prone Twist', 'Twist weights when going from neutral to prone. Cue: full control. Common mistake: instability above.', 'external'),
('1633ee9d-5025-47fe-a98a-7dd375b0e198', 'Rollout de rodillas con Fitball', 25, 16, 290, 1, 'Intermedio', 'De rodillas, coloca los antebrazos sobre el Fitball. Rueda el balón hacia adelante extendiendo el cuerpo sin dejar caer la cadera, y usa el abdomen para regresar.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Knee Rollout with Stability Ball', 'On your knees, place your forearms on the stability ball. Roll the ball forward by extending your body without dropping your hips, and use your abs to return.', 'bodyweight'),
('1635b7f2-f4a1-45d4-b09b-4e0c50502f3c', 'Abducción de cadera lateral con Miniband (Tobillos)', 37, 29, 61, 1, 'Principiante', 'Acuéstate de lado con una banda en los tobillos y piernas rectas. Levanta la pierna superior lateralmente contra la resistencia de la banda.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Lateral hip abduction with Mini Band (Ankles)', 'Lie on your side with a band around your ankles and legs straight. Raise your top leg laterally against the resistance of the band.', 'external'),
('164d6ab5-e866-4b50-aa41-555839d598cc', 'Full Front Lever Pull Up en barra', 71, 17, 1, 1, 'Avanzado', 'Realiza dominadas manteniendo el cuerpo completamente estirado y paralelo al suelo boca arriba colgado de la barra fija.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Full Front Lever Pull Up on Bar', 'Perform pull-ups keeping your body completely stretched and parallel to the floor face up hanging from the fixed bar.', 'mixed'),
('16630d19-b61b-4526-9dbd-7be685a68675', 'Sentadilla lateral (Cossack)', 28, 313, 1, 1, 'Intermedio', 'Baja hacia un lado estirando la pierna opuesta con el talón apoyado. Cue: pecho alto, baja hasta donde puedas. Error: levantar el talón del pie de apoyo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Side Squat (cossack)', 'Lower yourself to one side by stretching your opposite leg with your heel supported. Cue: chest high, go down as far as you can. Common mistake: lifting the heel of the supporting foot.', 'mixed'),
('168c9a6d-9b5c-4556-8f10-3dce4a8ea6ca', 'Lanzamiento frontal balón', 25, 1, 240, 1, 'Principiante', 'Lanza balón al suelo frente a ti. Objetivo: potencia core. Cue: usa todo cuerpo. Error: arquear espalda.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Front Ball Throw', 'Throw the ball on the ground in front of you. Target: core power. Cue: use all body. Common mistake: arching your back.', 'external'),
('16b3eab5-5935-4010-95ff-8f288e1af007', 'Búlgara', 28, 29, 81, 1, 'Intermedio', 'Realiza una sentadilla búlgara colocando el pie trasero elevado en un banco. Baja de forma controlada manteniendo el tronco estable y empuja con la pierna delantera para volver a la posición inicial.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Bulgarian Split Squat', 'Perform a Bulgarian split squat with the rear foot elevated on a bench. Lower under control while keeping the torso stable and push through the front leg to return to the starting position.', 'mixed'),
('16e6c4d9-6031-4050-990b-a6c648daf12f', 'Curl de isquiotibiales en Fitball', 55, 29, 290, 1, 'Intermedio', 'Tumbado boca arriba con los talones sobre el Fitball, eleva la cadera y flexiona las rodillas para acercar el balón hacia tus glúteos.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Hamstring Curl on Stability Ball', 'Lying face up with your heels on the Stability Ball, raise your hips and bend your knees to bring the ball closer to your buttocks.', 'bodyweight'),
('16fda8b8-0dd9-4ccb-8af4-8f9b1acc5fed', 'Jalón invertido máquina', 16, 17, 186, 1, 'Principiante', 'Tira barra palmas hacia ti. Objetivo: dorsal/bíceps. Cue: codos abajo. Error: balanceo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Inverted Machine Pulldown', 'Throw bar claps towards you. Target: dorsal and biceps. Cue: elbows down. Common mistake: swinging.', 'external'),
('1705fc00-2ee9-4940-bd51-8a83fb04a26e', 'Extensión tríceps barra', 2, NULL, 116, 1, 'Intermedio', 'De pie o sentado, sostén la barra sobre la cabeza con agarre cerrado. Desciende la barra por detrás de la cabeza flexionando solo los codos, manteniendo los brazos superiores verticales e inmóviles. Extiende hasta la posición inicial contrayendo los tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Triceps Bar Extension', 'Standing or sitting, hold the bar overhead with a close grip. Lower the bar behind your head, bending only your elbows, keeping your upper arms vertical and motionless. Extend to the starting position by contracting the triceps.', 'external'),
('171bd587-8d9e-4aba-a205-f68516ee8d1f', 'Face Pull sentado con cable', 6, 71, 151, 1, 'Principiante', 'Siéntate frente a una polea. Tira de la cuerda hacia tu frente, llevando los codos hacia atrás y rotando externamente los hombros para trabajar el deltoides posterior.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Seated Face Pull', 'Sit in front of a cable. Pull the rope toward your front, bringing your elbows back and externally rotating your shoulders to work the rear deltoid.', 'external'),
('17207ac2-f9c8-4b21-a1fc-6b6181672e11', 'Peso muerto con agarre Snatch', 71, 55, 116, 1, 'Avanzado', 'Peso muerto con manos muy separadas. Mayor demanda de espalda alta. Espalda neutra. No redondees la zona lumbar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Snatch Grip Deadlift', 'Deadlift with hands wide apart. Greater demand for upper back. Neutral back. Do not round your lower back.', 'external'),
('1730b4b2-8e90-4468-92e1-868012e3a5f3', 'Leñador media rodilla cable', 25, NULL, 151, 1, 'Avanzado', 'Woodchopper desde posición de media rodilla. Elimina contribución de piernas enfocando el trabajo en core. Mayor rango de movimiento que versión arrodillada. Alterna rodilla adelantada.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lumberjack Half Knee Cable', 'Woodchopper from half knee position. Eliminates contribution from legs by focusing work on core. Greater range of motion than kneeling version. Alternate forward knee.', 'external'),
('17391cff-0178-48f7-a854-2b6379e9fba4', 'Pallof Press en polea', 25, 6, 151, 1, 'Intermedio', 'De lado a la polea, empuja el agarre al frente y resiste la rotación. Cue: pies clavados al suelo. Error: girar el torso hacia la polea.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Pallof Pulley Press', 'Side to the cable, push your grip forward and resist rotation. Cue: feet nailed to the ground. Common mistake: turning the torso towards the cable.', 'external'),
('173ad880-67af-4457-9201-89d6cd36968c', 'Sentadilla en cajón', 28, 29, 116, 1, 'Avanzado', 'Sentadilla con pausa sentándose completamente en un cajón o banco. Elimina el reflejo de estiramiento. Enseña a generar fuerza desde posición muerta. Popular en powerlifting. La altura del cajón debe permitir muslos paralelos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Box squat', 'Squat with pause sitting completely on a box or bench. Eliminates the stretch reflex. Teaches how to generate force from a dead position. Popular in powerlifting. The height of the drawer should allow for parallel thighs.', 'external'),
('1768a049-4c76-4ff6-bda0-33d75e3965c6', 'Salto de longitud con manos tras nuca', 29, 28, 1, 1, 'Avanzado', 'Realiza un salto largo sin usar el impulso de los brazos. Potencia pura de piernas. Core firme. No tires del cuello al saltar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Long Jump with Hands Behind the Neck', 'Perform a long jump without using the momentum of your arms. Pure leg power. Firm core. Don''t pull your neck when jumping.', 'bodyweight'),
('176a49f0-fa39-46a8-a991-8be4cb8795a0', 'L-Sit', 25, 28, 1, 24, 'Avanzado', 'Apoyado en paralelas o suelo, mantén piernas estiradas al frente formando una L. Cue: hombros abajo y lejos de orejas. Error: encoger el pecho.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'L-sit', 'Supported on parallel bars or the floor, keep your legs stretched out in front forming an L. Cue: shoulders down and away from your ears. Common mistake: shrinking your chest.', 'bodyweight'),
('178165f2-5271-4f57-b298-6f17774932fc', 'Press Z con mancuernas', 6, 25, 81, 1, 'Avanzado', 'Siéntate en el suelo con las piernas extendidas en V. Realiza un press de hombros con mancuernas manteniendo el torso totalmente vertical sin apoyo trasero.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Dumbbell Z Press', 'Sit on the floor with your legs extended in a V. Perform a shoulder press with dumbbells, keeping your torso completely vertical without back support.', 'external'),
('1791c440-572a-486e-bea6-73dc3ae831a9', 'Rack Pull con barra', 71, 29, 116, 1, 'Principiante', 'Inicia el peso muerto con la barra apoyada en los soportes del rack por encima de las rodillas para enfocar el trabajo en la espalda superior.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Rack Pull with bar', 'Start the deadlift with the bar resting on the rack supports above your knees to focus the work on your upper back.', 'external'),
('179f7ecf-923e-42c4-842b-84426e664a13', 'Salto al cajón invertido', 13, 29, 1, 1, 'Avanzado', 'De espaldas al cajón, salta girando 180 grados para aterrizar sobre él. Coordinación aérea máxima. Cue: inicia el giro temprano. Error común: caer fuera del borde del cajón.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Inverted Box Jump', 'With your back to the box, jump turning 180 degrees to land on it. Maximum aerial coordination. Cue: start the turn early. Common mistake: falling off the edge of the drawer.', 'bodyweight'),
('17dcf651-c852-4a79-b067-e39d4030f527', 'Curl femoral con banda elástica', 55, 29, 61, 1, 'Principiante', 'Boca abajo con la banda anclada, flexiona las rodillas llevando los talones hacia el glúteo. Objetivo: aislamiento de isquiotibiales. Cues: mantén la cadera pegada al suelo. Error común: levantar la pelvis para facilitar el movimiento.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Femoral Curl with Elastic Band', 'Face down with the band anchored, bend your knees, bringing your heels toward your glutes. Target: hamstring isolation. Cue: keep your hips close to the ground. Common mistake: raising the pelvis to facilitate movement.', 'external'),
('17f0d72a-48bd-4e72-b38e-37e38eb4d70f', 'Zancada inversa ipsilateral con Slider y Kettlebell (Maleta)', 28, 29, 281, 1, 'Intermedio', 'Sostén una pesa rusa en un lado (posición maleta) y desliza hacia atrás la pierna del mismo lado usando un slider, manteniendo el equilibrio del torso.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Reverse ipsilateral stride with Slider and Kettlebell (Suitcase)', 'Hold a kettlebell on one side (suitcase position) and slide back the leg on the same side using a slider, keeping your torso balanced.', 'external'),
('17f675f9-9cdb-47a0-8fd6-114e4e88cb20', 'Thrusters con kettlebell', 13, 6, 281, 1, 'Intermedio', 'Realiza una sentadilla profunda y aprovecha el impulso para empujar la pesa sobre la cabeza al subir. Objetivo: potencia total y cardio. Cues: movimiento fluido y explosivo. Error común: separar la sentadilla del press.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Kettlebell Thrusters', 'Perform a deep squat and use the upward drive to press the kettlebell overhead as you stand up. Target: total-body power and cardio. Cue: keep the movement fluid and explosive. Common mistake: separating the squat from the press.', 'external'),
('17fc2020-7601-436a-a879-a09f1222436f', 'Abdominales polea alta', 25, NULL, 151, 1, 'Intermedio', 'Flexiona torso de rodillas con cuerda. Objetivo: abdomen carga. Cue: exhala al bajar. Error: tirar con brazos.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'High Pulley Crunches', 'Flex your torso from a kneeling position using the rope. Target: loaded abs. Cue: exhale on the way down. Common mistake: pulling with your arms.', 'external'),
('17fe0bc1-b524-4251-ac01-01f3d1377a87', 'Press hombros con banda', 6, 2, 61, 1, 'Principiante', 'Pisa el centro de la banda y sujeta los extremos a la altura de los hombros. Presiona hacia arriba extendiendo completamente los brazos sobre la cabeza. La resistencia progresiva de la banda hace el ejercicio más desafiante en la parte final del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Shoulder press with band', 'Step on the center of the band and hold the ends at shoulder height. Press up by fully extending your arms overhead. The progressive resistance of the band makes the exercise more challenging in the final part of the movement.', 'external'),
('18623e44-ca76-4996-a5f7-994c344ef626', 'Woodchop bajo a alto medio arrodillado con Kettlebell', 25, 6, 281, 1, 'Intermedio', 'En posición de caballero, sujeta la Kettlebell y llévala desde la cadera de la rodilla apoyada hacia el hombro opuesto en diagonal.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Half-Kneeling Low-to-High Kettlebell Woodchop', 'In a half-kneeling position, hold the kettlebell and move it diagonally from the hip of the knee on the floor toward the opposite shoulder.', 'external'),
('1864c04f-6f4b-4aeb-a975-a38ccb29123a', 'Dominadas pronadas', 16, 17, 1, 1, 'Intermedio', 'Cuelga de una barra con las palmas mirando hacia adelante y las manos separadas ligeramente más que el ancho de los hombros. Eleva el cuerpo tirando con los dorsales hasta que la barbilla supere la barra. Desciende controladamente hasta la extensión completa de los brazos. Mantén el core activado para evitar el balanceo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pronated pull-ups', 'Hang from a bar with your palms facing forward and your hands slightly wider than shoulder-width apart. Raise your body by pulling with your lats until your chin clears the bar. Descend controlledly until the arms are fully extended. Keep your core engaged to avoid rocking.', 'mixed'),
('188cf4ae-31c0-4846-ac16-040ddf2ad7e5', 'Sentadilla Split contralateral Front Rack con Kettlebell', 28, 29, 281, 1, 'Intermedio', 'Con un pie adelantado, sostén la pesa rusa en el hombro opuesto a la pierna delantera. Baja la rodilla trasera hacia el suelo manteniendo la estabilidad del core ante la carga asimétrica.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Contralateral Front Rack Split Squat with Kettlebell', 'With one foot forward, hold the kettlebell on the shoulder opposite your front leg. Lower your back knee toward the ground, maintaining core stability under the asymmetrical load.', 'external'),
('188eacb0-8a57-45b4-ba3f-02615ddecda4', 'Pullover con maza doble', 71, 6, 81, 1, 'Intermedio', 'Sujeta la maza con ambas manos y llévala desde detrás de la cabeza hacia el pecho en un arco controlado para trabajar el dorsal y la movilidad de hombros.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Double Mace Pullover', 'Hold the club with both hands and bring it from behind your head toward your chest in a controlled arc to work your lats and shoulder mobility.', 'external'),
('18c5ee15-78c9-4107-8ae2-064e14f79101', 'Remo cable polea baja agarre amplio', 71, 16, 151, 1, 'Intermedio', 'Realiza un remo en polea baja con agarre amplio. Tira del agarre hacia el torso manteniendo la espalda estable y juntando las escápulas.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Wide-Grip Seated Cable Row', 'Perform a wide-grip seated cable row. Pull the handle toward the torso while keeping the back stable and squeezing the shoulder blades together.', 'external'),
('18e3cd94-e37c-4ba8-b5c1-0a63de4b9c70', 'Kettlebell Figure 8', 29, 25, 281, 1, 'Principiante', 'Pasa la pesa entre las piernas dibujando un ocho mientras mantienes sentadilla parcial. Coordinación. Pecho alto. No encorves la espalda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Figure 8 Kettlebell', 'Pass the weight between your legs, drawing a figure eight while maintaining a partial squat. Coordination. High chest. Don''t hunch your back.', 'external'),
('18fd3305-05fb-41b5-a099-49319b554150', 'Cruces de poleas para pecho', 1, 6, 151, 1, 'Intermedio', 'De pie, junta las manos frente a ti con codos semiflexionados. Cue: imagina que abrazas un barril. Error: transformar el ejercicio en un press.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Pulley Crosses for Chest', 'Standing, join your hands in front of you with elbows semi-bent. Cue: imagine you''re hugging a barrel. Common mistake: transforming the exercise into a press.', 'external'),
('1904ee25-9ab9-46d9-a279-ea09dc8d466e', 'Caminata lateral con banda', 37, 29, 61, 1, 'Principiante', 'Coloca la banda alrededor de los tobillos o por encima de las rodillas. Adopta una posición de media sentadilla y da pasos laterales manteniendo la tensión constante en la banda. Mantén los pies paralelos y no permitas que las rodillas se junten. Activa glúteo medio y menor.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lateral walk with band', 'Place the band around your ankles or above your knees. Assume a half squat position and take lateral steps while maintaining constant tension on the band. Keep your feet parallel and do not allow your knees to come together. Activates glutes medius and minimus.', 'external'),
('1921d221-714e-458c-94f8-83de53be4f8a', 'Sentadilla sobre Bosu', 28, 25, 298, 1, 'Intermedio', 'Realiza una sentadilla sobre la parte inestable del bosu. Mejora la propiocepción. Cue: pies paralelos. Error: mirar al suelo.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'BOSU Squat', 'Perform a squat on the unstable part of the bosu. Improves proprioception. Cue: feet parallel. Common mistake: looking at the ground.', 'bodyweight'),
('1922828f-14b2-4482-a342-b5c055d1bded', 'Plancha con caminata lateral', 25, 6, 1, 24, 'Intermedio', 'En posición de plancha, desplázate lateralmente moviendo manos y pies a la vez. Objetivo: estabilidad total y hombros. Cues: cadera quieta y core firme. Error común: elevar demasiado el glúteo.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Plank with Lateral Walk', 'From a plank position, move laterally by stepping your hands and feet at the same time. Target: full-body stability and shoulders. Cue: keep your hips still and your core firm. Common mistake: raising your glutes too much.', 'bodyweight'),
('192f277f-1afa-4ba3-a8b2-42be649aec67', 'Kettlebell Deadlift unilateral', 55, 29, 281, 1, 'Intermedio', 'Sujeta la pesa y baja el torso mientras extiendes una pierna atrás. Equilibrio y fuerza. Espalda neutra. No gires la cadera hacia afuera.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Unilateral Kettlebell Deadlift', 'Hold the dumbbell and lower your torso while extending one leg behind you. Balance and strength. Neutral back. Don''t turn your hips outward.', 'external'),
('19305a46-83d2-4243-8cb8-a4ce8556c6e0', 'Caminata del granjero mancuernas', 100, 6, 81, 1, 'Intermedio', 'Sujeta mancuernas pesadas en cada mano y camina manteniendo una postura erguida perfecta. Los hombros deben estar hacia atrás y abajo, el core activado. Este ejercicio funcional fortalece el agarre, trapecios, core y mejora la estabilidad general.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Farmer''s Walk', 'Hold heavy dumbbells in each hand and walk while maintaining a perfect upright posture. Shoulders should be back and down, core activated. This functional exercise strengthens the grip, trapezius, core and improves general stability.', 'external'),
('19523379-c1fb-478a-a1d2-84b2bcd8cc41', 'Aperturas de espalda (Band Pull-Apart)', 71, 6, 61, 1, 'Principiante', 'Sujeta la banda frente a ti con brazos estirados y sepáralos hacia los lados hasta que la banda toque tu pecho. Objetivo: deltoides posterior y postura. Cue: mantén los brazos rectos. Error: doblar los codos para facilitar el rango.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Band Pull-Aparts', 'Hold the band in front of you with your arms straight and pull it apart until it reaches your chest. Target: rear delts and posture. Cue: keep your arms straight. Common mistake: bending your elbows to increase the range.', 'external'),
('19be9978-7e51-41f5-a1cd-fd76b8fee27c', 'Zancada cruzada (Curtsy) Zercher en Landmine', 28, 29, 116, 1, 'Intermedio', 'Sujeta la barra Landmine en el pliegue de tus codos y realiza una zancada cruzando una pierna por detrás de la otra (reverencia).', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Landmine Zercher Curtsy Lunge', 'Hold the landmine bar in the crook of your elbows and perform a curtsy lunge by crossing one leg behind the other.', 'external'),
('1a7cdfa7-8512-4ea6-8be1-1d57d3d18023', 'Máquina abductores espalda apoyada', 37, 29, 186, 1, 'Principiante', 'Abre piernas sentado. Cue: espalda pegada. Error: inclinarse.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Supported-Back Hip Abductor Machine', 'Spread your legs while seated. Cue: keep your back firmly against the pad. Common mistake: leaning your torso.', 'external'),
('1a88841c-708c-4701-a2f7-c79e0a9935c0', 'Press de banca agarre inverso con mancuernas', 1, 2, 81, 1, 'Intermedio', 'Acuéstate en el banco y sostén las mancuernas con las palmas mirando hacia tu cara (supino). Presiona hacia arriba enfocando el pectoral superior.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Dumbbell Reverse Grip Bench Press', 'Lie on the bench and hold the dumbbells with your palms facing your face (supine). Press up focusing on the upper pectoral.', 'external'),
('1a93c5b6-d801-49e2-93cc-1b42cd5593b3', 'Press Pallof con rotación', 25, 6, 151, 1, 'Intermedio', 'Extiende el cable al frente y realiza una rotación lenta controlada lejos del anclaje, volviendo despacio. Objetivo: fuerza rotacional del core. Cues: pies clavados al suelo y brazos estirados. Error común: mover las caderas junto con el torso.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Pallof Press with Rotation', 'Extend the cable in front and perform a slow controlled rotation away from the anchor, returning slowly. Target: core rotational strength. Cue: feet planted firmly and arms stretched. Common mistake: moving your hips along with your torso.', 'external'),
('1ae4d9fe-25ac-40a9-956f-267c709ecf69', 'Caminata Overhead con mancuerna a una mano', 6, 25, 81, 1, 'Intermedio', 'Camina sosteniendo una mancuerna bloqueada sobre la cabeza con el brazo recto, manteniendo el core tenso y evitando arquear la espalda.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Overhead walk with one-handed dumbbell', 'Walk holding a dumbbell locked overhead with your arm straight, keeping your core tight and avoiding arching your back.', 'external'),
('1aeb6a4c-21d9-40ef-bb7c-839b3ae8a852', 'Peso muerto rumano con mancuernas', 55, 29, 81, 1, 'Intermedio', 'Baja las pesas pegadas a las piernas con rodillas semi-rígidas. Estiramiento de isquios. Espalda plana. No bajes más allá de tu flexibilidad.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Romanian Dumbbell Deadlift', 'Lower the weights against your legs with semi-rigid knees. Hamstring stretch. Flat back. Don''t go below your flexibility.', 'external'),
('1b77e09c-b9e8-4c86-9257-3a272780761e', 'Stability Ball V Up Pass', 25, 28, 290, 1, 'Intermedio', 'Acuéstate boca arriba sosteniendo el Fitball con las manos. Levanta piernas y brazos simultáneamente para pasar el balón de las manos a los pies. Baja el cuerpo y repite pasando el balón de los pies a las manos.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball V-Up Pass', 'Lie on your back holding the stability ball in your hands. Raise your legs and arms at the same time to pass the ball from your hands to your feet, then lower under control.', 'bodyweight'),
('1b9996ee-191c-42ed-8bf2-3674543d9f6b', 'Press francés cable', 2, NULL, 151, 1, 'Intermedio', 'Tumbado en banco con la cabeza hacia la polea baja, realiza extensiones de tríceps llevando la barra desde detrás de la cabeza hasta brazos extendidos verticalmente. El cable mantiene tensión constante en todo el recorrido a diferencia de la barra libre.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable French Press', 'Lying on a bench with your head toward the low pulley, perform triceps extensions by bringing the bar from behind your head to vertically extended arms. The cable maintains constant tension throughout the entire length unlike the free bar.', 'external'),
('1bbdbce9-2e64-4618-81b5-9768938da26e', 'Kettlebell Snatch explosivo', 13, 6, 281, 1, 'Avanzado', 'Un solo movimiento desde el suelo hasta bloquear sobre la cabeza. Objetivo: potencia total. Cue: transición suave del asa en la mano. Error común: golpear el antebrazo con la pesa.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Explosive Kettlebell Snatch', 'A single movement from the ground to blocking overhead. Target: total power. Cue: smooth transition of the handle into the hand. Common mistake: hitting the forearm with the weight.', 'external');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('1bc63a89-d890-4330-8494-2a188f2df0e8', 'Hollow hold', 25, 13, 1, 24, 'Intermedio', 'Mantén una posición hollow tumbado boca arriba, con la zona lumbar pegada al suelo, piernas extendidas y brazos por encima de la cabeza. Sostén la tensión abdominal durante todo el tiempo indicado.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Hollow Hold', 'Hold a hollow body position lying on your back, keeping the lower back pressed into the floor, legs extended, and arms overhead. Maintain abdominal tension for the prescribed time.', 'bodyweight'),
('1bd5bf73-c98a-4e59-a7cb-1856af42f5bb', 'Salto vertical con despegue de dedos', 64, 309, 1, 1, 'Principiante', 'Salta buscando máxima extensión de tobillo y dedos al final del despegue. Fuerza reactiva. Aterrizaje suave. No bloquees las rodillas al caer.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Vertical jump with toe take-off', 'Jump looking for maximum extension of the ankle and fingers at the end of the take-off. Reactive force. Soft landing. Don''t lock your knees when you fall.', 'bodyweight'),
('1c09d6cb-9279-4644-bf2b-8934fc2a1e9e', 'Patada tríceps cable', 2, NULL, 151, 1, 'Intermedio', 'Inclinado hacia adelante con polea baja, realiza extensiones hacia atrás manteniendo el brazo superior paralelo al suelo. El cable proporciona resistencia constante a diferencia de las mancuernas. Excelente para la contracción máxima del tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable triceps kick', 'Leaning forward with a low cable, perform backward extensions keeping your upper arm parallel to the ground. The cable provides constant resistance unlike dumbbells. Excellent for maximum contraction of the triceps.', 'external'),
('1c104156-705b-438b-9fc3-c160ab15610f', 'Jalón neutro estrecho', 16, 17, 186, 1, 'Principiante', 'Tira agarre V al pecho. Objetivo: amplitud dorsal. Cue: pecho fuera. Error: encorvarse.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Narrow Neutral Pull', 'Pull V grip to your chest. Target: dorsal width. Cue: chest out. Common mistake: slouching.', 'external'),
('1c13fa4f-1e78-46f9-80d1-0bffa400836b', 'Power Clean con barra', 13, 29, 116, 1, 'Avanzado', 'Lleva la barra desde el suelo hasta los hombros en un movimiento explosivo, recibiéndola en una posición de media sentadilla.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Power Clean with bar', 'Bring the bar from the floor to your shoulders in an explosive movement, receiving it in a half-squat position.', 'external'),
('1c4ae5a3-b88f-4d08-a413-10611c064a63', 'Planche', 6, 2, 1, 24, 'Avanzado', 'Mantén el cuerpo horizontal paralelo al suelo sostenido únicamente por las manos. Una de las habilidades más difíciles de calistenia. Requiere años de preparación específica. Progresa con lean planche, tuck, advanced tuck y straddle.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Planche', 'Keep your body horizontal and parallel to the floor, supported only by your hands. It is one of the hardest calisthenics skills. It requires years of specific preparation. Progress through lean planche, tuck, advanced tuck, and straddle.', 'bodyweight'),
('1c83611f-9414-48fc-990a-ee7f73705f78', 'Plancha frontal isométrica', 25, NULL, 1, 24, 'Principiante', 'Mantén el cuerpo recto apoyado en antebrazos. Cue: ombligo adentro. Error: hundir la cadera.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Isometric Front Plank', 'Keep your body straight while supported on your forearms. Cue: draw your navel in. Common mistake: letting your hips sag.', 'bodyweight'),
('1ca8d902-cbca-43e3-ad19-f3d375faf9dc', 'Salto longitud triple', 29, 28, 1, 1, 'Avanzado', 'Tres saltos de longitud seguidos sin detenerse. Objetivo: reactividad horizontal. Cue: aprovecha el rebote de cada aterrizaje. Error común: paradas entre saltos.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Triple Long Jump', 'Three long jumps in a row without stopping. Target: horizontal reactivity. Cue: take advantage of the bounce of each landing. Common mistake: stops between jumps.', 'bodyweight'),
('1cbdf502-9629-498d-b3a8-de1682c23cf3', 'Rotación externa con cables', 6, 71, 151, 1, 'Principiante', 'Realiza una rotación externa de hombro con cable. Mantén el codo cerca del cuerpo y rota el antebrazo hacia fuera de forma controlada sin compensar con el tronco.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Cable External Rotation', 'Perform a cable shoulder external rotation. Keep the elbow close to the body and rotate the forearm outward under control without compensating with the torso.', 'external'),
('1ccbb504-3c84-4352-b82a-722685f10e6b', 'Potencia rotacional TRX', 25, 6, 216, 1, 'Avanzado', 'Movimiento explosivo rotacional usando TRX. Simula patrones deportivos de lanzamiento. Genera potencia desde las caderas a través del core. Mantén brazos relativamente extendidos durante la rotación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Rotational Power', 'Explosive rotational movement using TRX. Simulates sports throwing patterns. Generate power from the hips through the core. Keep your arms relatively extended during the rotation.', 'bodyweight'),
('1ccce816-8961-462a-a0fa-9fdd714f41ae', 'Elevación de gemelos con pies elevados y Kettlebell doble (Maleta)', 64, 309, 281, 1, 'Principiante', 'De pie sobre un escalón con Kettlebells a los lados, eleva los talones al máximo y baja lentamente para trabajar los gemelos.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Calf Raise with Elevated Feet and Double Kettlebell (suitcase)', 'Standing on a step with kettlebells at your sides, raise your heels as high as possible and lower yourself slowly to work your calves.', 'external'),
('1cd057ab-1001-4265-afd0-41c31ec7f632', 'High knees', 28, NULL, 1, 24, 'Principiante', 'Corre en el sitio elevando las rodillas lo más alto posible, idealmente hasta la altura de las caderas. Mantén el torso erguido y balancea los brazos de forma natural. Aterriza en las puntas de los pies para mayor agilidad. Es un excelente ejercicio cardiovascular que también fortalece el core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'High knees', 'Run in place, raising your knees as high as possible, ideally up to hip height. Keep your torso upright and swing your arms naturally. Land on the balls of your feet for greater agility. It is an excellent cardiovascular exercise that also strengthens the core.', 'bodyweight'),
('1d1eb6d3-82db-4f55-8b5a-8ae5976209c1', 'Upright row mancuernas', 6, 71, 81, 1, 'Intermedio', 'Con las mancuernas frente a los muslos, tira hacia arriba llevando los codos por encima de las manos hasta que las mancuernas lleguen a la altura del pecho. Mantén las mancuernas cerca del cuerpo durante todo el movimiento. Cuidado con la posición de las muñecas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Upright Row', 'With the dumbbells in front of your thighs, pull upward by leading with your elbows until the dumbbells reach chest height. Keep the dumbbells close to your body throughout the movement. Be careful with your wrist position.', 'external'),
('1d2e2369-8bc0-4968-966a-ea8ae6f71a7b', 'Spider Curl alterno con Kettlebell doble', 17, 100, 281, 1, 'Principiante', 'Apoyado boca abajo en banco inclinado, realiza el curl con pesas rusas alternando brazos para un estimulo de agarre unico.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Alternating Double kettlebell Spider Curl', 'Lying face down on an incline bench, perform the kettlebell curl, alternating arms for a unique grip stimulus.', 'external'),
('1dae8e68-453b-4da4-91db-2c4bafc8eb31', 'Sentadilla Cosaca alterna Goblet con mancuerna', 28, 29, 81, 1, 'Intermedio', 'Sostén una mancuerna frente al pecho y realiza desplazamientos laterales profundos, alternando entre piernas para trabajar aductores y glúteos.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Goblet Alternating Cossack Squat with Dumbbell', 'Hold a dumbbell in front of your chest and perform deep lateral movements, alternating between legs to work adductors and glutes.', 'external'),
('1e2aef89-eb11-439a-bace-0c88dd786753', 'Slider Double Kettlebell Bottoms Up Front Rack Lateral Lunge', 28, 29, 281, 1, 'Avanzado', 'Sostén Kettlebells invertidas en posición de rack. Desliza una pierna lateralmente en un slider, baja en zancada y regresa con potencia.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Slider Double kettlebell Bottoms Up Front Rack Lateral Lunge', 'Hold inverted kettlebells in a rack position. Slide one leg laterally into a slider, lunge down and return with power.', 'external'),
('1e5bd445-6532-4cc2-be39-d4668e14dbcf', 'Press de hombros alterno con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Presiona las pesas rusas sobre la cabeza de forma alterna, manteniendo una pesa en posicion rack mientras la otra sube.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Double kettlebell Alternating Shoulder Press', 'Press the kettlebells overhead alternately, keeping one weight in a rack position while the other rises.', 'external'),
('1e5c39d6-cac0-432f-9ef2-75e953ea5159', 'Bent Press con Kettlebell a una mano', 6, 2, 281, 1, 'Avanzado', 'Un movimiento de fuerza tradicional donde te inclinas alejandote de la carga mientras mantienes el brazo bloqueado hasta quedar erguido.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Single-Arm Kettlebell Bent Press', 'A traditional strength movement where you lean away from the load while keeping your arm locked upright.', 'external'),
('1e6d8537-5df2-4a59-bf34-af6548967abb', 'Tirón alto agarre arranque', 6, 71, 116, 1, 'Avanzado', 'Tirón explosivo con agarre amplio de arranque. Desarrolla potencia para levantamientos olímpicos. La barra debe subir al menos hasta el pecho. Enfócate en la velocidad y extensión triple. No es un remo alto lento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Snatch-Grip High Pull', 'Perform an explosive high pull with a wide snatch grip. It develops power for Olympic lifts. The bar should rise at least to chest height. Focus on speed and triple extension. This is not a slow upright row.', 'external'),
('1ea40f1e-7249-41da-bdfa-f68668ed8476', 'Sentadilla salto una pierna', 28, 29, 1, 1, 'Avanzado', 'Sentadilla pistol con salto explosivo al subir. Combina fuerza unilateral máxima con potencia. Extremadamente demandante. Aterriza en la misma pierna y mantén el control. Solo tras dominar sentadilla pistol regular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One leg jump squat', 'Pistol squat with explosive jump when going up. Combines maximum unilateral force with power. Extremely demanding. Land on the same leg and maintain control. Only after mastering the regular pistol squat.', 'mixed'),
('1f17f7ef-fa69-4b2a-b2ee-8391c56aa322', 'Thruster con mancuernas', 28, 6, 81, 1, 'Intermedio', 'Sostén mancuernas a la altura de los hombros. Haz una sentadilla y usa el impulso de subida para empujar las pesas sobre la cabeza.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Dumbbell Thruster', 'Hold the dumbbells at shoulder height, perform a squat, and use the upward drive to press the weights overhead.', 'external'),
('1f2a012e-f780-4510-8574-d026fa2feadb', 'Sentadilla Hack inversa glúteo', 29, 28, 186, 1, 'Avanzado', 'Empuja con hombros de frente a máquina. Cue: cadera atrás. Error: rodillas dentro.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Reverse Glute Hack Squat', 'Machine front shoulder push. Cue: hip back. Common mistake: knees inside.', 'external'),
('1f2f983c-3dab-4e26-b3fa-bc77fd00ca36', 'Sentadilla Búlgara Overhead contralateral Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sujeta la pesa invertida arriba con el brazo opuesto a la pierna delantera mientras realizas una sentadilla búlgara profunda.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Contralateral Overhead Bottoms-Up Bulgarian Split Squat', 'Hold the inverted dumbbell overhead with the arm opposite your front leg while performing a deep Bulgarian squat.', 'external'),
('1f3786c5-628c-4dcd-8961-19191dc031e7', 'Curl bíceps invertido mancuerna', 100, 17, 81, 1, 'Principiante', 'Flexiona mancuernas palmas abajo. Objetivo: antebrazo. Cue: agarre firme. Error: mover codos.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Dumbbell Inverted Biceps Curl', 'Flex dumbbells palms down. Target: forearm. Cue: firm grip. Common mistake: moving elbows.', 'external'),
('1fa91d6a-892e-4a55-ae88-15fe3c3a7382', 'Zancada atrás con mancuernas', 28, 29, 81, 1, 'Principiante', 'Da un paso atrás con mancuernas a los lados y baja. Objetivo: cuádriceps y glúteo. Cues: rodilla a 90 grados. Error común: perder el equilibrio lateral.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Reverse Lunge with Dumbbells', 'Step back with dumbbells at your sides and lower down. Target: quads and glutes. Cue: front knee at 90 degrees. Common mistake: losing lateral balance.', 'external'),
('1ffe14ed-4905-45ea-acda-17df07039f3c', 'Curl de bíceps 21', 17, 100, 116, 1, 'Intermedio', 'Realiza 7 repeticiones desde abajo hasta la mitad, 7 desde la mitad hasta arriba, y 7 repeticiones completas sin descanso. Objetivo: máxima fatiga muscular y bombeo. Cues: codos fijos a los costados y sin balanceos. Error común: acortar el rango de movimiento en las últimas 7 repeticiones.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Bicep Curl 21', 'Perform 7 reps from the bottom to the middle, 7 from the middle to the top, and 7 full reps without rest. Goal: maximum muscle fatigue and pump. Cue: elbows fixed at the sides and without swinging. Common mistake: shortening the range of motion in the last 7 repetitions.', 'external'),
('200948e0-4dcd-468d-bf46-7fde893a9f86', 'Press de banca plano con barra', 1, 2, 116, 1, 'Principiante', 'Baja la barra al pecho y empuja hacia arriba en banco plano. Cue: retrae escápulas. Error: rebotar en el pecho.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Flat Barbell Bench Press', 'Lower the bar to your chest and push up on a flat bench. Cue: retract scapulae. Common mistake: bouncing on your chest.', 'external'),
('200a64da-0d96-45e8-bb9e-3a975a1acd0f', 'Press Sots Seesaw con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'En posicion de sentadilla profunda, realiza un press alterno continuo con Kettlebells en un movimiento rítmico de balancín.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Press Sots Seesaw with Double kettlebell', 'In a deep squat position, perform a continuous alternating kettlebell press in a rhythmic rocking movement.', 'external'),
('206dfae1-c623-420a-8344-d36c135a4f30', 'Remo renegado a Flexión con Kettlebell doble', 71, 1, 281, 1, 'Intermedio', 'Ejecuta una flexion apoyado en las Kettlebells seguido inmediatamente por un remo unilateral, alternando los brazos en cada ciclo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Renegade Row to Double kettlebell Curl', 'Perform a push-up supported by the kettlebells followed immediately by a unilateral row, alternating arms in each cycle.', 'external'),
('2079e221-d565-4e2b-b5df-1b9702e0744b', 'Sentadilla Goblet en Landmine', 28, 29, 116, 1, 'Principiante', 'Sujeta el extremo de la barra frente al pecho y realiza una sentadilla, aprovechando la trayectoria de la barra para mantener el torso erguido.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Landmine Goblet Squat', 'Hold the end of the bar in front of your chest and perform a squat, taking advantage of the trajectory of the bar to keep your torso upright.', 'external'),
('20e1d0b5-ee6e-4aed-a45d-73b50205eb1b', 'Hollow Body Flutter Kicks agarre Crush con mancuernas', 25, 1, 81, 1, 'Intermedio', 'Realiza patadas de aleteo en Hollow Body mientras presionas dos mancuernas una contra la otra sobre tu pecho para activar el core.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Hollow Body Flutter Kicks Grip Crush Dumbbell', 'Perform Hollow Body flutter kicks while pressing two dumbbells against each other on your chest to activate your core.', 'external'),
('20e34a9f-30bb-4c53-819f-40a90b54d75a', 'Zancada lateral cable', 29, 37, 151, 1, 'Avanzado', 'Zancadas laterales con resistencia de cable. Puede ser con cable al lado (resistiendo) o al frente (asistiendo). Trabaja plano frontal de movimiento a menudo descuidado. Mantén pie de apoyo firmemente plantado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable side stride', 'Side strides with cable resistance. It can be wired to the side (resisting) or to the front (assisting). Works often sloppy frontal plane of motion. Keep your support foot firmly planted.', 'external'),
('2155f0eb-71ed-45b0-99f6-f553aa09db75', 'Remo en polea baja', 71, 17, 151, 1, 'Principiante', 'Sentado frente a la polea, tira del agarre hacia el abdomen manteniendo la espalda recta. Objetivo: densidad de la espalda media. Cue: tira de los codos hacia atrás. Error común: balancear el tronco excesivamente.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Low Pulley Row', 'Sitting in front of the pulley, pull the grip towards your abs, keeping your back straight. Target: mid back density. Cue: pull your elbows back. Common mistake: swinging the torso excessively.', 'external'),
('21842524-21cb-4934-8d13-0a8b92985a29', 'Zancadas posteriores', 28, 29, 1, 1, 'Principiante', 'Da un paso hacia atrás y desciende flexionando ambas rodillas hasta que la rodilla trasera casi toque el suelo. Mantén el torso erguido y el peso distribuido principalmente en la pierna delantera. Esta variación es más estable que la zancada frontal y permite mejor control del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Reverse Lunges', 'Step back and lower by bending both knees until the back knee almost touches the floor. Keep your torso upright and your weight mostly on the front leg. This variation is more stable than the forward lunge and allows better control of the movement.', 'mixed'),
('21af0ffa-3757-4a92-9ef7-bd2297871c83', 'Press Overhead alterno medio arrodillado con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'En posición de caballero, presiona las Kettlebells alternativamente sobre la cabeza, desafiando el equilibrio en la base de apoyo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Half Kneeling Alternating Overhead Press with Double kettlebell', 'In a half-kneeling position, press the kettlebells alternately overhead, challenging the balance on the base of support.', 'external'),
('21cf146b-a422-4384-88c0-432a49cbe6e1', 'Bent Arm Bent Body Press Handstand en anillas', 6, 2, 1, 1, 'Avanzado', 'En las anillas, presiona el cuerpo desde una posición flexionada hasta la parada de manos vertical con los brazos doblados al inicio.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Bent Arm Bent Body Press Handstand on Rings', 'On the rings, press your body from a flexed position to a vertical handstand with your arms bent at the start.', 'bodyweight'),
('21d8fe64-48d7-44db-a058-202870d05930', 'Sentadilla Split Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Con Kettlebells en posición rack, realiza una sentadilla dividida bajando la rodilla trasera verticalmente, desafiando la estabilidad del torso.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Split Front Rack Squat with Double kettlebell', 'With kettlebells in a rack position, perform a split squat by lowering your back knee vertically, challenging core stability.', 'external'),
('21e84bed-cbe9-40c5-834b-ac8b9bdb6fdb', 'Sentadilla patinadora Zercher en Landmine', 28, 29, 116, 1, 'Avanzado', 'Sujeta la barra Landmine en el pliegue de los codos (Zercher) y realiza una sentadilla patinadora, bajando la rodilla trasera hacia el suelo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Zercher Skater Squat in Landmine', 'Hold the Landmine bar in the bend of your elbows (Zercher) and perform a skating squat, lowering your back knee toward the floor.', 'external'),
('22403a43-8ffd-4cb9-af6b-2edc7bd9196a', 'Ab Wheel Kneeling Rollout', 25, 16, 271, 1, 'Intermedio', 'De rodillas, sujeta la rueda frente a ti. Rueda hacia adelante extendiendo el cuerpo tanto como puedas sin arquear la espalda baja, luego usa el abdomen para regresar.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ab Wheel Kneeling Rollout', 'On your knees, hold the wheel in front of you. Roll forward, extending your body as much as you can without arching your lower back, then use your abs to return.', 'external'),
('2255347b-b5c2-42bc-b7e2-d8fa80fb47d9', 'Ab rollout desde rodillas estricto', 25, 71, 271, 1, 'Intermedio', 'Desliza la rueda abdominal adelante manteniendo core firme y vuelve. Objetivo: recto abdominal. Cue: no dejes caer la cadera. Error común: arquear la espalda lumbar al estirar.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Strict Kneeling Ab Rollout', 'Slide the ab wheel forward, keeping your core firm, and return. Target: rectus abdominis. Cue: don''t drop your hips. Common mistake: arching the lower back when stretching.', 'external'),
('226e29cd-ea25-4008-9db0-c61ec6625dd0', 'TRX Sierra abdominal', 25, 6, 216, 1, 'Intermedio', 'En plancha con pies en agarres, desliza el cuerpo atrás y adelante moviendo solo hombros. Core bloqueado. Espalda neutra. No eleves el glúteo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Body Saw', 'Start in a plank with your feet in the straps and glide your body backward and forward by moving only through the shoulders. Keep your core braced, your spine neutral, and avoid lifting your glutes.', 'bodyweight'),
('22af6770-5bb1-42d5-a5f9-dc8d813836ef', 'Colgado invertido en anillas', 25, 6, 1, 1, 'Intermedio', 'Manten el cuerpo vertical boca abajo colgado de las anillas, estabilizando la posicion con los brazos bloqueados y el core activo.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Inverted hanging on rings', 'Keep your body vertical face down hanging from the rings, stabilizing the position with your arms locked and your core active.', 'bodyweight'),
('22b292d9-8307-4e1e-b199-b1b28fb56fa0', 'Sentadilla Smith pies adelantados cuádriceps', 28, 29, 186, 1, 'Principiante', 'Sentadilla guiada con pies adelante. Cue: espalda contra barra. Error: pies muy atrás.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Smith Squat Feet Forward Quads', 'Guided squat with feet forward. Cue: back to bar. Common mistake: feet too far back.', 'external'),
('22bfbcec-8e47-45ba-a9d9-2eea62433733', 'Battle Ropes Golpes dobles', 13, 25, 256, 1, 'Intermedio', 'Lleva ambas cuerdas arriba y golpéalas contra el suelo con fuerza usando todo el cuerpo. Potencia explosiva. Espalda neutra. No dobles la espalda baja.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Battle Ropes Double Hits', 'Bring both ropes up and hit them hard against the ground using your entire body. Explosive power. Neutral back. Don''t bend your lower back.', 'external'),
('22cd7a43-3737-4e56-8e86-5f9aef5bb070', 'Russian Twist con pies elevados en Landmine', 25, NULL, 116, 1, 'Intermedio', 'Sentado con los pies en el aire, sujeta la barra y gírala de lado a lado cruzando el torso para un reto abdominal avanzado.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Russian Twist with Feet Elevated in Landmine', 'Sitting with your feet in the air, hold the bar and rotate it from side to side across your torso for an advanced abdominal challenge.', 'external'),
('235f02cc-1884-4d90-9a7f-eaf61937f666', 'Bodyweight Side Plank', 25, 6, 1, 24, 'Principiante', 'Acuéstate de lado apoyado en un antebrazo. Levanta las caderas hasta que el cuerpo forme una línea recta y mantén la posición activando los oblicuos.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Side Plank', 'Lie on your side supported by one forearm. Raise your hips until your body forms a straight line and maintain the position by activating your obliques.', 'bodyweight'),
('2383fa64-7332-4dd0-a5b4-a8211e949670', 'Elevación frontal con barra recta en cable', 6, NULL, 151, 1, 'Principiante', 'De espaldas a la polea baja con el cable entre las piernas. Levanta la barra recta hacia adelante hasta la altura de los hombros.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Cable Straight Bar Front Raise', 'With your back to the low cable with the cable between your legs. Raise the bar straight forward to shoulder height.', 'external'),
('2393be28-bed0-4705-b5f4-654681651ca8', 'Curl bíceps mancuernas', 17, NULL, 81, 1, 'Principiante', 'De pie o sentado, con una mancuerna en cada mano y los brazos extendidos, flexiona los codos llevando las mancuernas hacia los hombros. Puedes realizar el movimiento alternando brazos, simultáneamente, o con rotación de muñeca (curl supinador). Mantén los codos fijos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell biceps curl', 'Standing or sitting, with a dumbbell in each hand and arms extended, bend your elbows, bringing the dumbbells toward your shoulders. You can perform the movement by alternating arms, simultaneously, or with wrist rotation (supinator curl). Keep your elbows fixed.', 'external'),
('23976a67-ed2a-4ff5-938c-d7c58432856f', 'Side Plank con rotación en TRX', 25, 6, 216, 1, 'Avanzado', 'En posicion de plancha lateral con los pies en el TRX, lleva el brazo libre por debajo del torso rotando la cintura y vuelve a extenderlo hacia arriba.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Side Plank with rotation on TRX', 'In a side plank position with your feet on the TRX, bring your free arm under your torso, rotating at the waist, and extend it upward again.', 'bodyweight'),
('23c7da08-d53c-4d5a-9d47-db86a4e672d5', 'Encogimiento de hombros con barra', 71, 100, 116, 1, 'Principiante', 'De pie sosteniendo una barra con los brazos estirados, eleva los hombros hacia las orejas contrayendo los trapecios y baja controladamente.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Barbell Shrug', 'Standing holding a bar with outstretched arms, raise your shoulders toward your ears by contracting your traps and lower yourself under control.', 'external'),
('23d6b994-067a-4311-af5d-9cbaf9313568', 'Press de pecho con mancuerna a una mano en Fitball', 1, 25, 81, 1, 'Intermedio', 'Apoya la espalda en el Fitball sosteniendo una sola mancuerna. Realiza el press de pecho manteniendo las caderas altas y el core estable para evitar girar.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'One-hand dumbbell chest press on Stability Ball', 'Rest your back on the stability ball holding a single dumbbell. Perform the chest press while keeping your hips high and core stable to avoid twisting.', 'external'),
('23ee0621-5b4c-46e0-90e4-ce13e49c2c6d', 'Curl Nórdico de isquiotibiales', 55, NULL, 1, 1, 'Avanzado', 'De rodillas con los tobillos anclados, baja el torso hacia el suelo de forma lenta y controlada usando solo tus isquiotibiales.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Nordic Hamstring Curl', 'Kneeling with your ankles anchored, lower your torso toward the floor in a slow and controlled manner using only your hamstrings.', 'bodyweight'),
('240a151d-051b-4bbb-b245-3317c49975c1', 'Curl de bíceps en polea con barra recta', 17, 100, 151, 1, 'Principiante', 'Flexiona la barra conectada a polea baja manteniendo tensión. Objetivo: hipertrofia de bíceps. Cue: no muevas los codos. Error común: impulsarse con la espalda atrás.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Straight Bar Cable Biceps Curl', 'Flex the bar connected to the low cable while maintaining tension. Target: biceps hypertrophy. Cue: don''t move your elbows. Common mistake: pushing with your back behind you.', 'external'),
('2424c046-7f4a-45ec-ad1d-742ce0337dc9', 'Floor Press mancuernas simultáneo', 1, 2, 81, 1, 'Principiante', 'Press en suelo con pesas. Cue: lumbar apoyada. Error: despegar espalda.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Simultaneous Dumbbell Floor Press', 'Floor press with weights. Cue: lumbar supported. Common mistake: take off back.', 'external'),
('2449179e-bea3-4f2c-a5a5-2c0db7f6a2e4', 'Elevaciones laterales sentado', 6, NULL, 81, 1, 'Principiante', 'Eleva pesas a los lados sentado. Objetivo: deltoides lateral. Cue: hombros bajos. Error: balanceo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Side Raises', 'Raise weights to the sides while sitting. Target: lateral deltoid. Cue: lowered shoulders. Common mistake: swinging.', 'external'),
('244d3b1a-e083-40e7-8ccf-9cc68ca161d0', 'Hollow Body Flutter Kicks con Kettlebell doble', 25, NULL, 281, 1, 'Intermedio', 'En posición de Hollow Body, sostén dos Kettlebells sobre tu pecho y realiza patadas de aleteo controladas con las piernas.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Hollow Body Flutter Kicks with Double Kettlebell', 'In Hollow Body position, hold two kettlebells on your chest and perform controlled flutter kicks with your legs.', 'external'),
('245130b7-1619-4bad-b7dd-fd7cbafffdbc', 'Zancada inversa Slider Kettlebell Bottoms Up Front Rack', 28, 6, 281, 1, 'Avanzado', 'Con dos pesas rusas invertidas en el pecho, desliza un pie hacia atrás en un slider en una zancada inversa controlada.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse Stride Slider Kettlebell Bottoms Up Front Rack', 'With two inverted kettlebells on your chest, slide one foot back on a slider in a controlled reverse stride.', 'external'),
('24571e7f-85c9-491f-8703-e003a4aec53d', 'Remo a una mano mancuernas', 16, 17, 81, 1, 'Principiante', 'Apoya una mano y rodilla en un banco, manteniendo la espalda paralela al suelo. Con la mano libre, rema la mancuerna hacia la cadera manteniendo el codo cerca del cuerpo. Evita rotar el torso. Este ejercicio unilateral permite mayor concentración en cada lado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One-hand dumbbell row', 'Place one hand and knee on a bench, keeping your back parallel to the floor. With your free hand, row the dumbbell toward your hip, keeping your elbow close to your body. Avoid rotating your torso. This unilateral exercise allows greater concentration on each side.', 'external'),
('2472e46d-4e5b-485a-957a-a1bd13a9273b', 'Flexiones pliométricas con placa', 1, 2, 1, 1, 'Intermedio', 'Realiza una flexion explosiva empujando el cuerpo hacia arriba para que las manos aterricen sobre discos elevados situados a los lados, trabajando la potencia pectoral.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Plyometric Push-ups with Plate', 'Perform an explosive push-up by pushing your body up so that your hands land on raised discs located on your sides, working on your chest power.', 'mixed'),
('24809f67-b54b-42a6-b949-f99c8284f455', 'Sentadilla Búlgara con barra tras nuca', 28, 29, 116, 1, 'Intermedio', 'Realiza una sentadilla split con el pie trasero elevado sosteniendo la barra sobre los trapecios, manteniendo el torso erguido.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Squat with Bar Behind the Neck', 'Perform a split squat with your back foot raised holding the bar over your traps, keeping your torso upright.', 'external'),
('24e51369-c1dd-4dee-acc7-8db3e5ba81c0', 'Press Pallof con banda', 25, 6, 61, 1, 'Principiante', 'De pie y de lado al anclaje, sujeta la banda al pecho y extiéndela al frente resistiendo que la banda te gire. Objetivo: anti-rotación del core. Cue: pies bien anclados al suelo. Error: girar el torso hacia el anclaje.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Banded Pallof Press', 'Standing sideways to the anchor, hold the band to your chest and extend it in front of you, resisting the band from turning you. Target: anti-core rotation. Cue: feet firmly anchored to the ground. Common mistake: turning the torso towards the anchor.', 'external'),
('24eb3623-97e9-40db-b7e3-f81ea33f3f52', 'Sentadilla Cosaca alterna Overhead con Kettlebell doble Bottoms Up', 28, 313, 281, 1, 'Avanzado', 'Sostén dos Kettlebells invertidas bloqueadas sobre la cabeza. Realiza una sentadilla lateral profunda alternando lados, lo que exige un control motor y movilidad excepcionales.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Alternate Cossack Squat Overhead with Double kettlebell Bottoms Up', 'Hold two inverted kettlebells locked overhead. Perform a deep lateral squat alternating sides, which requires exceptional motor control and mobility.', 'external'),
('255118ae-52e1-4d65-ba52-650d8b710973', 'Remo bajo agarre ancho', 71, 17, 151, 1, 'Intermedio', 'Tira barra ancha al abdomen sentado. Objetivo: espalda alta. Cue: codos atrás. Error: subir hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Wide Grip Low Row', 'Pull a wide bar to the seated abs. Target: upper back. Cue: elbows back. Common mistake: raising shoulders.', 'external'),
('255a9da6-43b4-447f-95da-d5a0aa827e92', 'Zancada lateral mancuernas brazos abajo', 37, 28, 81, 1, 'Intermedio', 'Paso lateral con pesas a los lados. Cue: cadera atrás. Error: inclinar torso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Side Stride Dumbbells Arms Down', 'Side step with weights on the sides. Cue: hip back. Common mistake: lean torso.', 'external'),
('255b9a32-64e0-4ed0-b790-387d50b9e14e', 'Sit Up con Fitball', 25, NULL, 290, 1, 'Principiante', 'Realiza una flexión abdominal completa sentado sobre el Fitball o con las piernas apoyadas en él, enfocando el trabajo en el recto abdominal.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Sit Up with Stability Ball', 'Perform a complete abdominal flexion sitting on the stability ball or with your legs resting on it, focusing the work on the rectus abdominis.', 'bodyweight'),
('2566ef8c-3699-4473-aca3-f6e974fb8124', 'Press francés barra', 2, NULL, 116, 1, 'Intermedio', 'Tumbado en banco, sostén la barra con brazos extendidos verticalmente. Desciende la barra hacia la frente o detrás de la cabeza flexionando solo los codos. Mantén los codos apuntando hacia adelante y relativamente juntos durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar French Press', 'Lying on a bench, hold the bar with arms extended vertically. Lower the bar toward your forehead or behind your head, bending only your elbows. Keep your elbows pointed forward and relatively close together throughout the movement.', 'external'),
('257c23f1-194f-400a-b623-e234070865f3', 'Curl 21s barra', 17, NULL, 116, 1, 'Intermedio', 'Técnica avanzada que consiste en 7 repeticiones desde la posición inicial hasta la mitad, 7 desde la mitad hasta arriba, y 7 completas, totalizando 21 repeticiones sin descanso. Proporciona un estímulo único y una congestión intensa en el bíceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Curl 21s bar', 'Advanced technique that consists of 7 repetitions from the starting position to the middle, 7 from the middle to the top, and 7 complete, totaling 21 repetitions without rest. Provides a unique stimulus and intense pumping of the biceps.', 'external'),
('25c05b88-7c63-4fdd-916e-2853471549f1', 'Elevaciones laterales máquina', 6, NULL, 186, 1, 'Principiante', 'Sentado o de pie según el diseño, eleva los brazos lateralmente contra las almohadillas. La máquina proporciona resistencia constante y elimina el impulso. Excelente para aislar el deltoides medio de forma controlada.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Machine lateral raises', 'Sitting or standing depending on the design, raise your arms laterally against the pads. The machine provides constant resistance and eliminates momentum. Excellent for isolating the middle deltoid in a controlled manner.', 'external'),
('25d45d3b-0365-427e-8bd3-3ff67ccb7278', 'Peso muerto rumano a una pierna con Kettlebell doble', 55, 29, 281, 1, 'Intermedio', 'Baja el torso hacia adelante mientras elevas una pierna atrás, sosteniendo una Kettlebell en cada mano para trabajar el equilibrio y la cadena posterior.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Romanian Single Leg Double Kettlebell Deadlift', 'Lower your torso forward as you raise one leg behind you, holding a kettlebell in each hand to work on balance and the posterior chain.', 'external'),
('25f39a79-e4da-433b-8ab3-81d81524bd23', 'Shrugs barra', 71, NULL, 116, 1, 'Principiante', 'Con la barra colgando frente a los muslos, eleva los hombros directamente hacia las orejas lo más alto posible. Mantén la contracción por un segundo y desciende controladamente. No rotes los hombros; el movimiento es puramente vertical. Desarrolla los trapecios superiores.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar Shrugs', 'With the bar hanging in front of your thighs, raise your shoulders directly toward your ears as high as possible. Hold the contraction for a second and lower yourself under control. Don''t rotate your shoulders; the movement is purely vertical. Develops the upper trapezius.', 'external'),
('2674e3d0-8a57-43af-a9d9-be3f37bc881a', 'Rueda abdominal (Ab Wheel Rollout)', 25, 71, 271, 1, 'Intermedio', 'Desliza la rueda hacia adelante desde rodillas manteniendo el abdomen contraído. Objetivo: fuerza del core. Cue: no dejes que la cadera se hunda. Error común: arquear la espalda lumbar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Ab Wheel Rollout', 'Slide the wheel forward from your knees, keeping your abs contracted. Target: core strength. Cue: don''t let the hips withoutk. Common mistake: arching the lower back.', 'bodyweight'),
('2698f490-35a7-49fa-a265-137d8c6bee05', 'Aperturas máquina sentado pectoral', 1, 6, 186, 1, 'Principiante', 'Junta brazos en Peck Deck. Cue: pecho fuera. Error: encoger hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Seated Pec Deck Fly', 'Bring your arms together on the Pec Deck. Cue: keep your chest up. Common mistake: shrugging your shoulders.', 'external'),
('26d75dfe-dc0a-4fff-bf35-8f687f33164c', 'Sentadilla con pausa (barra)', 28, 29, 116, 1, 'Intermedio', 'Baja en sentadilla y mantén la posición fondo 2 segundos antes de subir. Objetivo: potencia de salida. Cue: tensión constante. Error común: relajarse y perder la postura abajo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Squat with Pause (bar)', 'Lower yourself into a squat and hold the bottom position for 2 seconds before rising. Target: power output. Cue: constant tension. Common mistake: relaxing and losing posture down.', 'external'),
('26e35ad0-e399-4be5-86f1-7a6baed1deb4', 'Rotación externa de cadera con rodilla doblada en cable', 29, NULL, 151, 1, 'Intermedio', 'De pie con una pierna enganchada al cable y rodilla doblada a 90 grados. Rota la pierna hacia afuera contra la resistencia.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Hip external rotation with cable bent knee', 'Stand with one leg hooked to the cable and knee bent at 90 degrees. Rotate your leg outward against resistance.', 'external'),
('26ea7a6a-2b95-4cfd-8f70-f261eca0311d', 'Extensión cadera banco 45 grados', 29, 55, 1, 1, 'Principiante', 'Baja y sube el torso bloqueando la zona lumbar para usar solo glúteos e isquios. Cue: aprieta glúteos arriba. Error: hiperextender la espalda.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', '45-Degree Back Extension', 'Lower and raise your torso on the 45-degree bench while keeping your lower back neutral so the glutes and hamstrings do the work. Cue: squeeze your glutes at the top. Common mistake: hyperextending your back.', 'bodyweight'),
('26eb5af3-91df-4ae0-81dd-98a0e901ae9f', 'Slider Double Kettlebell Front Rack Lateral Lunge', 28, 29, 281, 1, 'Intermedio', 'Sostén dos Kettlebells en el pecho (Front Rack). Usa un slider bajo un pie para deslizarte en una zancada lateral y volver a subir.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Slider Double kettlebell Front Rack Lateral Lunge', 'Hold two kettlebells on your chest (Front Rack). Use a slider under one foot to slide into a lateral lunge and come back up.', 'external'),
('26fc4f7e-f1d1-416d-82dc-fffe3cc1a5f2', 'Press de hombro con banda elástica', 6, 2, 61, 1, 'Principiante', 'Pisa la banda y empuja los extremos sobre tu cabeza hasta extender los brazos. Objetivo: deltoides. Cue: brazos totalmente estirados arriba. Error: arquear la zona lumbar para compensar.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Shoulder Press with Elastic Band', 'Step on the band and push the ends over your head until your arms are extended. Target: deltoid. Cue: arms fully stretched up. Common mistake: arching your lower back to compensate.', 'external'),
('26ff931d-0709-4373-9dfa-d7842162c259', 'Zancada inversa contralateral a Press de hombro en Landmine', 28, 6, 116, 1, 'Avanzado', 'Realiza una zancada inversa cargando la barra en el hombro opuesto a la pierna que retrocede, y al subir completa un press de hombro.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Reverse Stride contralateral to Shoulder Press on Landmine', 'Perform a reverse stride by loading the bar on the shoulder opposite the retreating leg, and when climbing complete a shoulder press.', 'external'),
('27010114-eec4-488b-a23c-5faeb6e0dfce', 'Extensión Overhead de tríceps arrodillado con cuerda', 2, 6, 151, 1, 'Principiante', 'De rodillas de espaldas a la polea, extiende los brazos hacia arriba y adelante usando la cuerda, aislando el movimiento en el triceps.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Rope Kneeling Triceps Overhead Extension', 'Kneeling with your back to the cable, extend your arms up and forward using the rope, isolating the movement in the triceps.', 'external'),
('274d6ddb-210d-4e14-863d-04f7fe0274b3', 'Sentadilla Búlgara rodilla sobre punta del pie (Pies elevados)', 28, 29, 1, 1, 'Intermedio', 'Con el pie trasero en banco, baja en zancada profunda llevando la rodilla delantera sobre los dedos para cargar el cuadriceps.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Knee-on-toe Bulgarian Squat (feet Elevated)', 'With your back foot on the bench, lower yourself into a deep lunge, bringing your front knee over your toes to load your quadriceps.', 'mixed'),
('27509cdf-5a6b-422b-acb0-7cd5017c42a2', 'Fitball Curl de isquios', 55, 29, 290, 1, 'Intermedio', 'Tumbado, pies en la bola, eleva cadera y flexiona rodillas trayendo la bola. Cadena posterior. Cadera alta. No apoyes el glúteo al bajar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Stability Ball Hamstring Curl', 'Lying down, feet on the ball, raise your hips and bend your knees bringing the ball. Posterior chain. High hip. Do not support your glutes when going down.', 'bodyweight'),
('276ede27-9467-49c0-ae00-1f724a45011c', 'Elevaciones de tibiales', 64, NULL, 186, 1, 'Intermedio', 'Elevación del tibial anterior (dorsiflexión) para equilibrar el tobillo y ayudar a prevención de periostitis/lesiones.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Tibial Raises', 'Tibialis anterior raisetion (dorsiflexion) to balance the ankle and help prevent periostitis/injuries.', 'external'),
('27824fea-c6be-42b6-aa31-b32f0007b8af', 'Flexiones a un brazo y pierna', 1, 2, 1, 1, 'Avanzado', 'Flexión apoyado solo en una mano y el pie opuesto. Máximo desafío de estabilización y fuerza. Requiere control excepcional del core para evitar rotación. Solo posible tras dominar flexiones a un brazo tradicionales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One-Arm One-Leg Push-Up', 'Perform a push-up supported only by one hand and the opposite foot. This is a maximum challenge for strength and stabilization and requires exceptional core control to resist rotation.', 'mixed'),
('279b1957-988b-4c0c-a335-988f99aafe4a', 'Alrededor del mundo con captura para sentadilla', 25, 28, 281, 1, 'Intermedio', 'Pasa la pesa alrededor de la cintura, capturala con ambas manos frente al pecho y realiza una sentadilla profunda inmediatamente.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Around the World to Squat Catch', 'Pass the weight around your waist, capture it with both hands in front of your chest and immediately perform a deep squat.', 'external'),
('27cbc96a-0434-4e40-ac76-c94379e84b5e', 'Ring L-Sit Straddle Press a parada de manos', 6, 25, 1, 1, 'Avanzado', 'Desde un L-Sit en anillas, abre las piernas en V y presiona con los brazos rectos hasta alcanzar la posicion vertical invertida.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Ring L-Sit Straddle Press to Handstand', 'From an L-Sit on rings, open your legs in a V and press with straight arms until you reach the inverted vertical position.', 'bodyweight'),
('284681da-fd83-4cb1-9e4e-4cbb857d69d0', 'Flexiones hindu', 13, NULL, 1, 1, 'Avanzado', 'Comienza en posición de perro boca abajo, desciende el pecho hacia el suelo en un movimiento fluido hacia adelante, luego arquea la espalda elevando el pecho mientras los brazos se extienden. Invierte el movimiento para volver al inicio. Este ejercicio combina fuerza, flexibilidad y coordinación en un patrón ondulatorio continuo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hindu Push-Ups', 'Starting in a downward dog position, lower your chest toward the floor in a fluid forward motion, then arch your back, raising your chest as your arms extend. Reverse the movement to return to the beginning. This exercise combines strength, flexibility and coordination in a continuous wave pattern.', 'mixed'),
('2847c1b6-27df-42ec-9baa-2b2831b57846', 'Step Up Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza un step up manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, el reto máximo de estabilidad y fuerza.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Bottoms-Up Overhead Step-up', 'Perform a step-up while holding two upside-down kettlebells locked out overhead, the ultimate challenge for stability and strength.', 'external'),
('2852515f-4829-4015-af16-764d4337233c', 'Press de banca con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Intermedio', 'Tumbado en el banco, presiona dos Kettlebells invertidas hacia el techo, enfocándote en el control del agarre y estabilidad del hombro.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Bottoms Up Double kettlebell Bench Press', 'Lying on the bench, press two inverted kettlebells toward the ceiling, focusing on grip control and shoulder stability.', 'external'),
('28795b71-5318-47ab-8ea5-9185e9906f67', 'Crunch fitball', 25, NULL, 290, 1, 'Principiante', 'Tumbado sobre la fitball con la espalda baja apoyada, realiza flexiones de tronco. La pelota permite mayor rango de movimiento que el suelo. Mantén los pies firmes para estabilidad. No tires del cuello, usa los abdominales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stability Ball Crunch', 'Lying on the stability ball with your lower back supported, perform torso flexions. The ball allows a greater range of motion than the ground. Keep your feet steady for stability. Don''t pull on your neck, use your abs.', 'bodyweight'),
('287ffea5-2140-40fd-bd7f-d522497b495a', 'Abdominales tipo bicicleta', 25, 28, 1, 1, 'Principiante', 'Tumbado, lleva el codo hacia la rodilla opuesta mientras estiras la otra pierna. Objetivo: oblicuos y recto abdominal. Cues: movimiento fluido y rítmico. Error común: tirar del cuello con las manos.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Bicycle Crunches', 'Lying down, bring your elbow toward the opposite knee while you straighten your other leg. Target: obliques and rectus abdominis. Cue: fluid and rhythmic movement. Common mistake: pulling on your neck with your hands.', 'bodyweight'),
('2899bdf9-49ac-48e8-876f-402562ef4956', 'Sentadilla Split Búlgara con mancuernas', 28, 29, 81, 1, 'Principiante', 'Realiza una sentadilla split con el pie trasero elevado en un banco, sosteniendo dos mancuernas a los lados para mayor resistencia.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Bulgarian Split Squat with Dumbbells', 'Perform a split squat with your back foot raised on a bench, holding two dumbbells at your sides for added resistance.', 'external'),
('28a176bc-0ad6-4281-9f59-624895e6fa26', 'Aperturas pectoral polea media estricto', 1, 6, 151, 1, 'Intermedio', 'Junta manos al frente en polea. Cue: codos semiflexionados. Error: encoger hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Mid-Pulley Chest Fly', 'Bring the handles together in front of you using a mid pulley. Cue: keep a slight bend in your elbows. Common mistake: shrugging your shoulders.', 'external'),
('28bcdd2e-4d88-4604-9be2-d07949937811', 'Tuck Planche en anillas', 25, 6, 1, 24, 'Avanzado', 'Sostén tu peso en las anillas con brazos bloqueados y las rodillas encogidas hacia el pecho, manteniendo la espalda paralela al suelo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Tuck Planche En Rings', 'Hold your body weight on the rings with your arms locked out y las knees encogidas hacia el chest, keeping la back paralela al floor.', 'bodyweight'),
('28be0175-4955-4b9b-861f-be31675d6f13', 'Remo un brazo explosivo', 16, 17, 81, 1, 'Avanzado', 'Remo unilateral con aceleración máxima. Permite usar más peso que remo estricto. La mancuerna debe subir explosivamente pero controlada en el descenso. No dejes que el impulso comprometa la forma.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I row an explosive arm', 'Unilateral rowing with maximum acceleration. Allows you to use more weight than strict rowing. The dumbbell should rise explosively but controlled on the way down. Don''t let momentum compromise form.', 'external'),
('28febd34-5c28-4804-adb6-f3ccf82a9e5f', 'Hiperextensión sobre Fitball', 71, 29, 290, 1, 'Principiante', 'Apoya el abdomen en el Fitball con los pies anclados. Eleva el torso extendiendo la espalda baja y aprieta los glúteos en la parte superior.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Hyperextension on Stability Ball', 'Support your abs on the Stability Ball with your feet anchored. Raise your torso by extending your lower back and squeeze your glutes at the top.', 'bodyweight'),
('2902fcaf-ded0-4d6f-bf01-70371946680a', 'Turkish Get Up con Kettlebell doble', 25, 6, 281, 1, 'Avanzado', 'Realiza el levantamiento turco completo manteniendo dos pesas rusas bloqueadas sobre la cabeza, un reto extremo de coordinacion y fuerza.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Double Kettlebell Turkish Get-Up', 'Perform the full Turkish get-up while keeping two kettlebells locked out overhead, creating an extreme coordination and strength challenge.', 'external'),
('29031d9c-3000-4682-bb1c-03e76b6735a9', 'Zancada inversa Overhead ipsilateral con Slider y Kettlebell', 28, 29, 281, 1, 'Avanzado', 'Sostén una pesa rusa sobre la cabeza y desliza hacia atrás la pierna del mismo lado en un slider. Requiere un gran control del core.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse ipsilateral Overhead stride with Slider and Kettlebell', 'Hold a kettlebell over your head and slide your leg back on the same side in a slider. Requires great core control.', 'external'),
('291bfc9d-c893-453d-a79c-1c657aac095b', 'Flexiones TRX', 1, 2, 216, 1, 'Intermedio', 'Con los pies en las correas del TRX, realiza flexiones. La inestabilidad aumenta la activación del core y la dificultad del ejercicio. Mantén el cuerpo completamente recto y controla el balanceo de las correas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX push-ups', 'With your feet in the TRX straps, perform push-ups. Instability increases core activation and the difficulty of the exercise. Keep your body completely straight and control the swing of the straps.', 'mixed'),
('294c8ea9-4c25-4eb9-9bcb-97aac3824164', 'Elevación de talones de pie', 64, 309, 1, 1, 'Principiante', 'Eleva los talones buscando la máxima altura posible y baja controladamente. Objetivo: fuerza del gemelo. Cue: rodillas estiradas pero no bloqueadas. Error común: balancear el torso para subir.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Standing Heel Raise', 'Raise your heels seeking the maximum possible height and lower yourself under control. Target: calf strength. Cue: knees straight but not locked. Common mistake: swinging your torso to go up.', 'mixed'),
('296f56c6-5b16-4cc2-ba96-081afd16c3c4', 'Flexiones azteca', 1, 2, 1, 1, 'Avanzado', 'Flexión explosiva donde tocas los pies con las manos en el aire. Requiere potencia explosiva extrema y coordinación perfecta. Una de las variaciones más difíciles de flexiones. Progresa con flexiones explosivas más simples primero.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Aztec push-ups', 'Explosive push-up where you touch your feet with your hands in the air. It requires extreme explosive power and perfect coordination. One of the most difficult push-up variations. Progress to simpler explosive push-ups first.', 'mixed'),
('2973645b-9cbb-403a-9483-a59db125e6ac', 'Double Dumbbell Seated Cuban Rotation', 6, NULL, 81, 1, 'Intermedio', 'Sentado, levanta los codos a la altura de los hombros (brazos en L). Rota las mancuernas hacia arriba hasta que los antebrazos queden verticales, luego baja rotando.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Double Dumbbell Seated Cuban Rotation', 'Sitting, raise your elbows to shoulder height (L-arms). Rotate the dumbbells up until your forearms are vertical, then rotate back down.', 'external'),
('298f2962-d130-4bd4-850d-aa07cde45c77', 'Press Overhead arrodillado alterno con mancuernas', 6, 2, 81, 1, 'Intermedio', 'Arrodillado sobre ambas piernas, presiona las mancuernas alternativamente sobre la cabeza, manteniendo el tronco perfectamente vertical.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Alternating Kneeling Overhead Press with Dumbbells', 'Kneeling on both legs, press the dumbbells alternately overhead, keeping your torso perfectly vertical.', 'external'),
('29c141d3-c74b-466d-91a7-5fa130b599ab', 'Flexiones pliométricas balón', 1, 2, 240, 1, 'Avanzado', 'Flexiones explosivas con manos alternando sobre el balón. Desarrolla potencia y coordinación. Una mano en balón, otra en suelo, explota para cambiar. Requiere fuerza explosiva y control.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plyometric ball push-ups', 'Explosive push-ups with hands alternating on the ball. Develops power and coordination. One hand on the ball, another on the ground, explode to change. Requires explosive strength and control.', 'external'),
('29e39d6f-11ee-497c-aa86-b210a10a3a5f', 'Volante (Steering Wheel) con disco', 6, 100, 81, 1, 'Principiante', 'Sostén un disco frente a ti con brazos estirados. Gíralo de lado a lado simulando un volante para trabajar hombros y antebrazos.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Steering Wheel with Plate', 'Hold a weight plate in front of you with your arms extended. Rotate it from side to side as if you were turning a steering wheel to work your shoulders and forearms.', 'external'),
('2a0ef8a8-5b10-4b5a-9b04-fbd9b85e4738', 'Press Z a una mano con Kettlebell Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'Sentado en el suelo, presiona una Kettlebell invertida sobre la cabeza, eliminando el impulso de las piernas y desafiando el agarre.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'One-handed Z Press with Bottoms-Up Kettlebell', 'Sitting on the floor, press an inverted kettlebell overhead, removing momentum from your legs and challenging your grip.', 'external'),
('2a1132df-78af-4b9c-83a2-0d121183ac2b', 'Reverse fly máquina', 6, 71, 186, 1, 'Principiante', 'Sentado de frente a la máquina, abre los brazos hacia atrás trabajando deltoides posterior. También conocido como rear delt fly. Mantén una ligera flexión en los codos y enfócate en juntar los omóplatos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Reverse fly machine', 'Sitting facing the machine, open your arms backwards working your posterior deltoids. Also known as rear delt fly. Maintain a slight bend in your elbows and focus on bringing your shoulder blades together.', 'external'),
('2a2528a2-1e5e-4772-9f54-a8192d30fad4', 'Dominadas L-sit', 16, 25, 1, 1, 'Avanzado', 'Cuelga de la barra y eleva las piernas hasta formar un ángulo de 90 grados con el torso, manteniéndolas paralelas al suelo. Realiza dominadas manteniendo esta posición de L durante todo el movimiento. Requiere fuerza excepcional en el core y flexibilidad en los isquiotibiales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'L-sit pull-ups', 'Hang from the bar and raise your legs until they form a 90-degree angle with your torso, keeping them parallel to the floor. Perform pull-ups while maintaining this L position throughout the movement. Requires exceptional core strength and hamstring flexibility.', 'mixed'),
('2a4a8d2b-b31a-4f1d-a247-7a6c89400a91', 'Press inclinado agarre inverso barra', 1, 2, 116, 1, 'Avanzado', 'Press en banco inclinado con palmas hacia ti. Cue: requiere ayudante. Error: perder control barra.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Incline Barbell Reverse Grip Press', 'Incline bench press with palms facing you. Cue: helper required. Common mistake: losing bar control.', 'external'),
('2a4ab764-db08-4193-948e-c35a74b37552', 'Jalón brazos rectos', 16, 71, 151, 1, 'Intermedio', 'Realiza un jalón con brazos rectos en polea. Mantén los codos ligeramente flexionados y lleva la barra o cuerda hacia los muslos activando el dorsal.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Straight-Arm Pulldown', 'Perform a straight-arm pulldown on a cable machine. Keep the elbows slightly bent and pull the bar or rope toward the thighs while engaging the lats.', 'external'),
('2aafdae1-62e6-45e8-bac1-7c8bc2d67253', 'Sentadilla Ciclista con Kettlebell a una mano (Front Rack)', 28, 29, 281, 1, 'Principiante', 'Con talones elevados, sujeta una Kettlebell en un solo hombro y realiza una sentadilla, trabajando la estabilidad asimetrica.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'One-handed Kettlebell Cycle Squat (front Rack)', 'With heels raised, hold a kettlebell on one shoulder and perform a squat, working on asymmetrical stability.', 'external'),
('2ad3fd19-0b36-4d3b-9fdf-45ddfe9aa655', 'Push Up en anillas a una mano', 1, 2, 1, 1, 'Avanzado', 'Realiza una flexión apoyado en una sola anilla con un brazo, manteniendo el cuerpo recto y equilibrando la inestabilidad extrema.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Push Up in one hand rings', 'Perform a push-up supported on a single ring with one arm, keeping your body straight and balancing extreme instability.', 'mixed'),
('2ae25e37-2439-46aa-9e5f-bb58a8568971', 'Sit Up Mariposa', 25, NULL, 1, 1, 'Principiante', 'Siéntate con las plantas de los pies juntas y las rodillas hacia afuera (mariposa). Acuéstate y luego usa el impulso de los brazos y fuerza abdominal para sentarte y tocar los pies.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Sit Up Butterfly', 'Sit with the soles of your feet together and your knees outward (butterfly). Lie down and then use the momentum of your arms and abdominal strength to sit up and touch your feet.', 'mixed'),
('2aedb0e6-a0ba-49e0-89e0-04696cdec3f2', 'Fondos búlgaro en anillas', 2, 1, 1, 1, 'Avanzado', 'Fondos en anillas llevando los codos hacia atrás en lugar de a los lados. Extremadamente desafiante para los tríceps. Requiere movilidad de hombros. Progresa desde fondos regulares en anillas. Cuidado con la posición de hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bulgarian Ring Dips', 'Perform ring dips while keeping your elbows tracking back instead of out to the sides. This is extremely demanding on the triceps and requires good shoulder mobility. Progress from regular ring dips and watch your shoulder position carefully.', 'mixed'),
('2b04d86c-d153-4138-b4b1-1c5847e717fe', 'Giros rusos balón', 25, NULL, 240, 1, 'Principiante', 'Sentado con rodillas flexionadas y pies elevados o en el suelo, rota el torso de lado a lado sosteniendo el balón. Toca el suelo con el balón en cada lado. Mantén el pecho elevado y el core contraído durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Russian Ball Twists', 'Sitting with knees bent and feet raised or on the floor, rotate your torso from side to side holding the ball. Touch the ball to the ground on each side. Keep your chest raised and core tight throughout the movement.', 'external'),
('2b08f192-1b98-4819-b66d-84daac425635', 'Elevación de talones de pie estricta', 64, 309, 1, 1, 'Principiante', 'Eleva talones buscando máxima altura de pie. Cue: controla el descenso. Error: balancear el cuerpo.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Strict Foot Heel Raise', 'Raise heels seeking maximum foot height. Cue: controls the descent. Common mistake: swinging the body.', 'mixed'),
('2b0b8d9a-9108-4a58-95c7-83ab051290e8', 'Sentadilla dragon avanzada', 28, 29, 1, 1, 'Avanzado', 'Sentadilla unilateral profunda con la pierna libre extendida completamente detrás. Versión más extrema que requiere fuerza, equilibrio y movilidad excepcionales. La pierna trasera no debe tocar el suelo. Solo para atletas muy avanzados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Advanced dragon squat', 'Deep unilateral squat with the free leg extended completely behind. More extreme version that requires exceptional strength, balance and mobility. The back leg should not touch the ground. Only for very advanced athletes.', 'mixed'),
('2b0f5348-a37e-4e08-af19-b65489127536', 'One arm row cable', 16, 17, 151, 1, 'Intermedio', 'Remo unilateral con cable que permite mayor rango de movimiento y concentración en cada lado. Puedes rotar ligeramente el torso al final para mayor contracción. Mantén el core activado para estabilizar la posición.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm row cable', 'Unilateral cable row that allows greater range of motion and concentration on each side. You can rotate your torso slightly at the end for more contraction. Keep your core engaged to stabilize the position.', 'external'),
('2b13df73-1df0-40d0-b423-fa9d282b755b', 'Plancha fitball', 25, 6, 290, 24, 'Intermedio', 'Realiza plancha con antebrazos o pies sobre la fitball. La superficie inestable aumenta drásticamente la activación del core. Mantén el cuerpo completamente recto resistiendo el movimiento de la pelota. Comienza con intervalos cortos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank Stability Ball', 'Perform the plank with your forearms or feet on the stability ball. The unstable surface greatly increases core activation. Keep your body completely straight while resisting the ball’s movement. Start with tervalos cortos.', 'bodyweight'),
('2b4be1f9-26ea-4180-af5b-6a6faed03435', 'Dominadas commando', 16, 17, 1, 1, 'Avanzado', 'Colócate perpendicular a la barra con una mano delante de la otra. Eleva el cuerpo llevando la cabeza alternativamente a cada lado de la barra. Este ejercicio requiere mayor estabilización del core y trabaja los músculos de forma asimétrica, mejorando el control y la fuerza unilateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Commando pull-ups', 'Stand perpendicular to the bar with one hand in front of the other. Raise your body by taking your head alternately on each side of the bar. This exercise requires greater core stabilization and works the muscles asymmetrically, improving control and unilateral strength.', 'mixed'),
('2b6237d4-b9e3-4d93-b183-fdea5e207854', 'Press bradford', 6, 2, 116, 1, 'Avanzado', 'Press alternando la barra delante y detrás de la cabeza sin bajarla completamente. Mantiene tensión constante en deltoides. Nombrado por Jim Bradford. Requiere buena movilidad de hombros. No recomendado para todos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Press Bradford', 'Press alternating the bar in front of and behind your head without lowering it completely. Maintains constant tension in deltoids. Named for Jim Bradford. Requires good shoulder mobility. Not recommended for everyone.', 'external'),
('2b717f49-a98e-4a92-b6a7-bcad5ed4a1ed', 'Remo prono en banco inclinado con mancuerna a una mano', 71, 17, 81, 1, 'Principiante', 'Acuéstate boca abajo en el banco y rema una sola mancuerna hacia la cadera, aislando el trabajo en un lado de la espalda.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Prone Incline Bench Row with One-Handed Dumbbell', 'Lie face down on the bench and row a single dumbbell toward your hip, isolating the work on one side of your back.', 'external'),
('2b83f4b8-aad8-4222-b34b-fa4c048f6ea9', 'Caminata lateral con Miniband (Tobillos)', 29, 37, 61, 1, 'Intermedio', 'Coloca la banda alrededor de los tobillos. En posición atlética, camina lateralmente arrastrando los pies o dando pasos controlados, manteniendo tensión.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Lateral walk with Mini Band (Ankles)', 'Place the band around your ankles. In an athletic position, walk laterally by shuffling or taking controlled steps, maintaining tension.', 'external'),
('2b881d15-0ec5-401a-89cf-109845e052c6', 'Bird Dog Row con mancuerna', 71, 25, 81, 1, 'Intermedio', 'En posicion de cuadrupedia, extiende la pierna opuesta al brazo que realiza el remo con mancuerna, trabajando la espalda y el core antirotacional.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Bird Dog Row with Dumbbell', 'In a quadruped position, extend the leg opposite the arm that performs the dumbbell row, working the back and anti-rotational core.', 'external'),
('2bf6184a-bd05-42b0-b939-109d023f2424', 'Salto vertical giro 180', 13, 25, 1, 1, 'Avanzado', 'Salta verticalmente y gira media vuelta, aterrizando estable de frente al punto de inicio. Cue: mirada al frente al caer. Error común: caer con pies desalineados.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump Turn 180', 'Jump vertically and spin half a turn, landing stable facing the starting point. Cue: look forward as you fall. Common mistake: falling with misaligned feet.', 'bodyweight'),
('2c278f2c-2804-45b7-825f-5b924c545918', 'Press de hombro sentado', 6, 2, 81, 1, 'Principiante', 'Sentado con respaldo, empuja mancuernas sobre la cabeza. Cue: baja hasta que los codos formen 90 grados. Error: chocar las pesas arriba.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Seated Shoulder Press', 'Sitting with a backrest, press dumbbells overhead. Cue: lower until your elbows are at 90 degrees. Common mistake: crashing the weights above.', 'external'),
('2c585288-f929-4dd9-b680-7c3401e25e14', 'Flexiones clásicas', 1, 2, 1, 1, 'Principiante', 'Coloca las manos en el suelo a la anchura de los hombros con los dedos apuntando hacia adelante. Mantén el cuerpo completamente recto desde la cabeza hasta los talones. Desciende controladamente flexionando los codos hasta que el pecho casi toque el suelo, luego empuja con fuerza para volver a la posición inicial. Mantén el core activado durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Classic push-ups', 'Place your hands shoulder-width apart on the floor with your fingers pointing forward. Keep your body completely straight from head to heels. Descend under control by bending your elbows until your chest almost touches the floor, then push hard to return to the starting position. Keep your core engaged throughout the movement.', 'mixed'),
('2c6fd3cf-25f7-436d-9c0a-2a7c29c69042', 'Man makers mancuernas', 13, NULL, 81, 1, 'Avanzado', 'Ejercicio complejo que combina burpee, remo y press. Desde posición de pie con mancuernas, realiza un burpee manteniendo las manos en las mancuernas, añade un remo con cada brazo en posición de plancha, salta los pies hacia las manos y finaliza con un clean y press.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Man makers dumbbells', 'Complex exercise that combines burpee, rowing and press. From a standing position with dumbbells, perform a burpee keeping your hands on the dumbbells, add a row with each arm in a plank position, jump your feet towards your hands and finish with a clean and press.', 'external'),
('2c92c059-bcea-491f-9cf4-2d13906dd417', 'Remo Gironda en polea baja', 71, 17, 151, 1, 'Intermedio', 'Remo sentado con agarre estrecho enfatizando retracción. Cue: pecho alto. Error: doblar la espalda.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Gironde Low Cable Row', 'Close grip seated row emphasizing retraction. Cue: chest up. Common mistake: bending your back.', 'external'),
('2cc75ccb-e3b4-41ee-a602-d7876ef752ec', 'TRX Zancada suspendida', 28, 37, 216, 1, 'Intermedio', 'Un pie en el agarre, realiza una zancada con la otra pierna. Gran desafío de estabilidad. Rodilla delantera alineada. No pierdas la verticalidad.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Suspended Lunge', 'Place one foot in the strap and perform a lunge with the other leg. This creates a major stability challenge. Keep your front knee aligned and do not lose your upright posture.', 'mixed'),
('2ce1c6c1-abd7-4332-8d98-2596ad2f1872', 'TRX Aperturas T', 71, 6, 216, 1, 'Intermedio', 'Abre brazos lateral en TRX. Objetivo: espalda alta. Cue: codos rectos. Error: encoger hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX T Fly', 'Open your arms out to the sides in a T shape while leaning back on the TRX straps. Target: upper back. Cue: keep your elbows straight. Common mistake: shrugging your shoulders.', 'bodyweight'),
('2cf0e2aa-4e70-4b28-83d8-9349acd4ef53', 'Remo Pendlay alterno a una mano con Kettlebell', 71, 17, 281, 1, 'Intermedio', 'Con el torso paralelo al suelo, rema una pesa rusa desde el suelo mientras la otra descansa, alternando brazos en cada repeticion.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Pendlay Alternate One-Hand kettlebell Row', 'With your torso parallel to the floor, row one kettlebell off the floor while the other rests, alternating arms with each repetition.', 'external'),
('2d09a632-35cd-4810-af35-7aad230fcf8c', 'Curl concentrado cable', 17, NULL, 151, 1, 'Intermedio', 'Con polea baja, realiza curls unilaterales concentrándote en el aislamiento del bíceps. Puedes hacerlo de pie o sentado, manteniendo el brazo que trabaja ligeramente adelantado. La tensión constante del cable intensifica el trabajo muscular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Concentrated cable curl', 'Using a low cable, perform unilateral curls focusing on bicep isolation. You can do it standing or sitting, keeping your working arm slightly forward. The constant tension of the cable intensifies muscle work.', 'external'),
('2d17d0ae-8d2f-488c-8373-d430888ddc22', 'Straddle L-Sit en anillas', 25, 2, 1, 24, 'Avanzado', 'Sostén tu cuerpo en las anillas con las piernas abiertas en forma de V y levantadas paralelas al suelo, manteniendo los brazos bloqueados.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Straddle L-Sit on Rings', 'Support yourself on the rings with your legs raised straight out in a straddle, keeping your body stable and your arms locked.', 'bodyweight'),
('2d2a5ead-2a2e-402b-a912-b63705b4e6d3', 'Press banca con pausa', 1, 2, 116, 1, 'Avanzado', 'Press banca con pausa de 2-3 segundos con la barra en el pecho. Elimina rebote y stretch reflex. Estándar en competición de powerlifting. Mantén tensión durante la pausa. Desarrolla fuerza desde posición muerta.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bench press with pause', 'Bench press with a pause of 2-3 seconds with the bar on the chest. Eliminates bounce and stretch reflex. Standard in powerlifting competition. Maintain tension during the pause. Build strength from dead position.', 'external'),
('2d4083a8-680c-40a2-82f5-a38a6038321f', 'Swing a una mano en postura escalonada', 29, 55, 281, 1, 'Intermedio', 'Realiza un swing con un brazo manteniendo un pie ligeramente retrasado (postura split), aumentando el reto de estabilidad en la pierna delantera.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Single-Arm Swing in Split Stance', 'Perform a single-arm swing while keeping one foot slightly behind the other in a split stance, increasing the demand for stability.', 'external'),
('2d7f88db-aba9-4484-99b0-64a884eefae0', 'Press banca cerrado', 2, 1, 116, 1, 'Avanzado', 'Press con agarre cerrado para enfatizar tríceps manteniendo el control del recorrido y la estabilidad del hombro.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Closed bench press', 'Close grip press to emphasize triceps while maintaining travel control and shoulder stability.', 'external'),
('2d8334eb-579d-4af1-a858-36f48feecad6', 'Press Z Seesaw con mancuernas', 6, 2, 81, 1, 'Avanzado', 'Sentado en el suelo con piernas en V, realiza un press alterno continuo con mancuernas, exigiendo máxima rectitud lumbar.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Dumbbell Z Seesaw Press', 'Sitting on the floor with legs in a V, perform a continuous alternating press with dumbbells, demanding maximum lumbar straightness.', 'external'),
('2d879e98-29f0-4335-8f6c-3f379168f38e', 'Sentadilla patinadora (Skater Squat)', 28, 29, 1, 1, 'Intermedio', 'Baja en sentadilla con una pierna mientras llevas la rodilla de la otra pierna hacia el suelo por detrás, manteniendo el torso ligeramente inclinado.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Skater Squat', 'Lower yourself into a squat with one leg while bringing the knee of the other leg toward the floor behind you, keeping your torso slightly inclined.', 'mixed'),
('2da13872-5938-44ff-ae03-051cf1c6d592', 'Zancada de patinador explosiva', 29, 37, 1, 1, 'Intermedio', 'Versión más potente del salto de patinador buscando máxima altura y distancia. Cue: empuje agresivo desde el lateral del pie. Error común: falta de control en el aterrizaje.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Explosive Skater Lunge', 'A more powerful version of the skater jump focused on maximum height and distance. Cue: push aggressively off the outer edge of the foot. Common mistake: losing control on landing.', 'mixed'),
('2daeaf64-ea87-462f-b57e-c4a627335f4e', 'Hip press TRX', 29, 55, 216, 1, 'Intermedio', 'Tumbado con talones en las correas, realiza elevaciones de cadera. Similar al puente de glúteo pero con la inestabilidad añadida. Aprieta fuertemente los glúteos en la parte superior y mantén la posición.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip press TRX', 'Lying down with heels on the straps, perform hip lifts. Similar to the glute bridge but with added instability. Squeeze your glutes hard at the top and hold the position.', 'mixed'),
('2dcf2ee8-cec7-4310-afff-bfdaf087bf96', 'Suspension Archer Row', 71, 6, 216, 1, 'Avanzado', 'Sostén el TRX con una mano. Tira del cuerpo hacia arriba mientras el otro brazo se extiende hacia el lado (como un arquero). Regresa y cambia de brazo.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Suspension Archer Row', 'Hold the TRX with one hand and pull your body upward while the other arm extends out to the side, like an archer.', 'bodyweight'),
('2e14390a-a7d2-4962-be01-5520ce77d701', 'Muscle up en anillas', 16, 1, 1, 1, 'Avanzado', 'Muscle up en anillas gimnásticas. Mucho más difícil que en barra debido a la inestabilidad. Requiere transición de falso agarre y gran control. La técnica es crucial. Progresa con muscle ups asistidos y transiciones lentas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Muscle up on rings', 'Muscle up on gymnastic rings. Much more difficult than on bar due to instability. Requires false grip transition and great control. Technique is crucial. Progress with assisted muscle ups and slow transitions.', 'mixed'),
('2e1acaac-5b02-4d74-bec8-ad43656dae4f', 'Equilibrio de rodillas sobre Fitball', 25, NULL, 290, 1, 'Intermedio', 'Mantente en posicion de rodillas sobre el Fitball buscando el equilibrio constante, activando todos los musculos estabilizadores del core.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Kneeling balance on Stability Ball', 'Stay in a kneeling position on the Stability Ball seeking constant balance, activating all the stabilizing muscles of the core.', 'bodyweight'),
('2e40f498-780f-4360-b7b5-f2e6db2c7164', 'Curl de bíceps sentado con banda', 17, NULL, 61, 1, 'Principiante', 'Sentado, pisa la banda y flexiona los brazos manteniendo tensión constante. Objetivo: bombeo de bíceps. Cues: codos fijos y espalda recta. Error común: encoger los hombros al subir.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Band Seated Biceps Curl', 'Sitting, step on the band and flex your arms, maintaining constant tension. Goal: biceps pump. Cue: keep your elbows fixed and straight back. Common mistake: shrugging your shoulders when climbing.', 'external'),
('2e41dcad-859b-4308-9bd8-eb699b194e59', 'Curl de isquiotibiales a una pierna en polea', 55, NULL, 151, 1, 'Principiante', 'Tumbado boca abajo, flexiona la pierna enganchada al cable llevando el talón hacia el glúteo para aislar el isquiotibial.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'One-leg cable hamstring curl', 'Lying face down, bend the leg hooked to the cable, bringing the heel towards the glutes to isolate the hamstring.', 'external'),
('2e423632-7331-47de-8dd0-d98dc129bc12', 'Full Front Lever Pull Up en anillas', 71, 17, 1, 1, 'Avanzado', 'Manten el cuerpo estirado en Front Lever y tira de las anillas hacia la cadera elevando el torso paralelo al suelo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Full Front Lever Pull Up on rings', 'Keep your body stretched in Front Lever and pull the rings towards your hips, raising your torso parallel to the ground.', 'mixed'),
('2e831f74-7d0c-4bc7-8614-8c7ea4d18a41', 'Dominadas mariposa', 16, 17, 1, 1, 'Avanzado', 'Versión más avanzada y eficiente del kipping con movimiento circular continuo. Permite máxima velocidad y volumen. Requiere excelente técnica y acondicionamiento. Alto riesgo de lesión si se ejecuta incorrectamente. Domina kipping primero.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Butterfly pull-ups', 'More advanced and efficient version of kipping with continuous circular movement. Allows maximum speed and volume. Requires excellent technique and conditioning. High risk of injury if executed incorrectly. Master kipping first.', 'mixed'),
('2eb5caee-cb71-4e49-9c36-572157e41b8c', 'Flexiones en L', 6, 2, 1, 1, 'Avanzado', 'Flexiones manteniendo el cuerpo en posición de L (piernas horizontales). Combina la dificultad del L-sit con flexiones verticales. Requiere fuerza excepcional en hombros y flexibilidad. Progresa con versiones asistidas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'L-Pushups', 'Push-ups keeping the body in an L position (legs horizontal). Combine the difficulty of the L-sit with vertical push-ups. Requires exceptional shoulder strength and flexibility. Progress with assisted versions.', 'mixed'),
('2ecfb758-7832-457d-990b-1b06e012b0bb', 'Roll out rueda abdominal', 25, NULL, 271, 1, 'Intermedio', 'Desde rodillas, rueda hacia adelante extendiendo el cuerpo lo más posible sin tocar el suelo. Mantén la espalda neutra y el core contraído. Vuelve a la posición inicial con control. Uno de los mejores ejercicios para el core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Roll out ab wheel', 'From your knees, roll forward, extending your body as much as possible without touching the ground. Keep your back neutral and core contracted. Return to the starting position with control. One of the best exercises for the core.', 'external'),
('2ecfce7f-5084-48de-a5f5-75ffb79b3d8a', 'Flexiones escalonadas', 1, 2, 1, 1, 'Avanzado', 'Flexiones con una mano elevada en una superficie mientras la otra está en el suelo. Crea un trabajo asimétrico desafiante. Alterna la posición de las manos o realiza series por lado. Buena progresión hacia flexiones a un brazo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Staggered Push-ups', 'Push-ups with one hand raised on a surface while the other is on the floor. Create challenging asymmetrical work. Alternate hand position or perform sets per side. Good progression towards one arm push-ups.', 'mixed'),
('2ed6ab66-447c-4d41-b429-77232e74d472', 'Flexión pliométrica a hombros', 1, 6, 1, 1, 'Avanzado', 'Realiza una flexión explosiva y toca tus hombros con las manos en el aire antes de caer. Desarrolla potencia en el tren superior. Cue: bloquea el abdomen para no serpentear. Error común: no empujar lo suficiente para dar tiempo al toque.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-Up with Shoulder Tap', 'Perform an explosive push-up and tap your shoulders in the air before landing. This develops upper-body power. Cue: brace your abs to stay stable. Common mistake: not pushing hard enough to make time for the tap.', 'mixed'),
('2ef70db1-030a-4d5f-9e6c-888180d35f8c', 'Remo unilateral polea baja dorsal', 16, 17, 151, 1, 'Principiante', 'Rema a un brazo sentado. Cue: estira total. Error: rotar torso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Dorsal Low Cable Unilateral Row', 'Seated one-arm row. Cue: full stretch. Common mistake: rotate torso.', 'external'),
('2f0ba226-e03c-4f53-9d65-8caf7b2ca6c1', 'Tuck Ups', 25, 28, 1, 1, 'Intermedio', 'Siéntate en el suelo y encoge rodillas hacia el pecho mientras elevas el torso. Objetivo: abdominales y flexores de cadera. Cues: equilibrio sobre el glúteo. Error común: apoyar las manos para ayudarse excesivamente.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Tuck Ups', 'Sit on the floor and tuck your knees toward your chest while lifting your torso. Target: abs and hip flexors. Cue: balance on your glutes. Common mistake: using your hands too much for assistance.', 'bodyweight'),
('2f196e0d-1e1a-431f-b091-42757a650917', 'Extensión de tríceps unilateral con mancuerna', 2, NULL, 81, 1, 'Principiante', 'Eleva una mancuerna tras la nuca con un brazo y extiende. Objetivo: cabeza larga tríceps. Cues: codo al techo. Error común: mover el brazo lateralmente.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Unilateral Dumbbell Triceps Extension', 'Raise a dumbbell behind the neck with one arm and extend. Target: long head triceps. Cues: elbow to the ceiling. Common mistake: moving your arm laterally.', 'external'),
('2f776183-e4b0-4805-85d4-b08e4f6fab4a', 'Sentadilla overhead un brazo', 28, 6, 81, 1, 'Avanzado', 'Sentadilla manteniendo una mancuerna overhead con un brazo. Desafío de estabilización y movilidad. Requiere core fuerte para resistir flexión lateral. Alterna brazos. Excelente para identificar y corregir desequilibrios.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm overhead squat', 'Squat holding a dumbbell overhead with one arm. Stabilization and mobility challenge. Requires strong core to resist lateral flexion. Alternate arms. Excellent for identifying and correcting imbalances.', 'external'),
('2f882300-5a8c-4de8-907c-22092b5bb090', 'Sentadilla Goblet con mancuerna', 28, 29, 81, 1, 'Principiante', 'Sostén una mancuerna verticalmente frente al pecho con ambas manos. Realiza una sentadilla profunda manteniendo los codos por dentro de las rodillas.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Dumbbell Goblet Squat', 'Hold a dumbbell vertically in front of your chest with both hands. Perform a deep squat, keeping your elbows inside your knees.', 'external'),
('30082f11-1315-4816-9065-119644e47837', 'Slider Double Kettlebell Bottoms Up Overhead Lateral Lunge', 28, 6, 281, 1, 'Avanzado', 'Sostén dos Kettlebells invertidas (Bottoms Up) sobre la cabeza. Desliza una pierna lateralmente usando un slider, baja la cadera y regresa.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Slider Double kettlebell Bottoms Up Overhead Lateral Lunge', 'Hold two inverted kettlebells (Bottoms Up) above your head. Slide one leg laterally using a slider, lower your hips and return.', 'external'),
('302f112a-8fbd-43fc-aca2-81e40a7e0ccf', 'Flexiones tiger bend', 2, 6, 1, 1, 'Avanzado', 'Desde flexión con antebrazos en el suelo, extiende a posición de flexión normal. Trabaja intensamente los tríceps con un patrón de movimiento único. Requiere fuerza y control excepcionales. También llamadas flexiones hindu.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Tiger Bend Push-Up', 'Start with your forearms on the floor and press up into a standard push-up position. This unique pattern works the triceps intensely and requires exceptional strength and control.', 'mixed'),
('3030d5fa-33fc-4e07-b0c1-0f502770ab64', 'Sóleo máquina sentado', 309, NULL, 186, 1, 'Principiante', 'Eleva talones máquina sentado. Objetivo: sóleo. Cue: máxima contracción. Error: rebotar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Soleus Machine', 'Seated machine heel raises. Target: soleus. Cue: maximum contraction. Common mistake: bounce.', 'external'),
('3049d49a-8a6e-4ea9-b058-64efa95cf77f', 'Press doble kettlebell', 6, 2, 281, 1, 'Avanzado', 'Press con dos kettlebells simultáneamente. Mayor carga total y desafío de estabilización. Requiere técnica de clean doble primero. Las kettlebells pueden presionarse juntas o con rotación. Desarrolla fuerza simétrica.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Double kettlebell press', 'Press with two kettlebells simultaneously. Greater total load and stabilization challenge. Requires double clean technique first. The kettlebells can be pressed together or with rotation. Develops symmetrical strength.', 'external'),
('305b61d7-0601-4ab8-bb8f-96d4b7e04bc6', 'Sentadilla Búlgara Front Rack con Kettlebell doble rodilla sobre dedos', 28, 29, 281, 1, 'Intermedio', 'Con Kettlebells en rack frontal, baja en sentadilla split permitiendo que la rodilla delantera sobrepase la punta del pie.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Bulgarian Front Rack Squat with kettlebell Double Knee on Toes', 'With kettlebells in a front rack, lower yourself into a split squat allowing your front knee to go over the ball of your foot.', 'external'),
('3063ebe9-d92d-4ef1-ac67-f7ba93125723', 'Peso muerto piernas semi-rígidas con barra', 55, 71, 116, 1, 'Intermedio', 'Baja la barra rozando las piernas con rodillas fijas (mínima flexión). Objetivo: estiramiento máximo de isquios. Cue: cadera hacia atrás. Error común: curvar la zona lumbar al descender.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Semi-rigid Leg Deadlift with Barbell', 'Lower the bar, rubbing your legs with fixed knees (minimal flexion). Target: maximum hamstring stretch. Cue: hip back. Common mistake: curving the lower back when descending.', 'external'),
('3067ee34-0e6b-492c-bc5e-41d54db0499d', 'Double Dumbbell Cuban Rotation', 6, NULL, 81, 1, 'Intermedio', 'De pie, realiza un remo alto y luego rota externamente los hombros para llevar las mancuernas por encima de la cabeza. Invierte el movimiento.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Double Dumbbell Cuban Rotation', 'Standing, perform a high row and then externally rotate your shoulders to bring the dumbbells overhead. Reverse the movement.', 'external'),
('307545af-fe47-44db-9c05-af71f4d1d7b8', 'Sentadilla isométrica con fitball', 28, 313, 290, 24, 'Principiante', 'Mantén la sentadilla contra la pared con la bola en la espalda y aprieta las rodillas. Objetivo: resistencia de cuádriceps y aductores. Cues: rodillas a 90 grados. Error común: despegar los talones del suelo.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Isometric Squat with Stability Ball', 'Hold the squat against the wall with the ball on your back and squeeze your knees. Target: resistance of quadriceps and adductors. Cue: knees at 90 degrees. Common mistake: taking your heels off the ground.', 'bodyweight'),
('3086853b-85eb-4817-81b2-7d4833fe68bc', 'Tríceps Overhead con cable', 2, NULL, 151, 1, 'Intermedio', 'De espaldas a la polea, extiende los brazos sobre la cabeza. Objetivo: cabeza larga del tríceps. Cue: estira los brazos por completo. Error común: arquear la zona lumbar excesivamente.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Overhead Cable Triceps Extension', 'Stand with your back to the pulley and extend your arms overhead. Target: the long head of the triceps. Cue: fully straighten your arms. Common mistake: excessively arching the lower back.', 'external'),
('308aaada-35e9-4dda-8726-fb4f3b85a7e3', 'Burpee lateral sobre barra', 13, 1, 116, 1, 'Intermedio', 'Realiza un burpee paralelo a una barra y salta lateralmente sobre ella para repetir. Combina cardio y agilidad. Cue: salta con pies juntos. Error común: pisar la barra al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Bar Burpee', 'Perform a burpee parallel to a bar and jump laterally on it to repeat. Combine cardio and agility. Cue: jump with feet together. Common mistake: stepping on the bar when jumping.', 'external'),
('309506b4-3b2b-4fa5-81ea-cd72106707eb', 'Shrugs máquina', 71, NULL, 186, 1, 'Principiante', 'De pie o sentado según el diseño, eleva los hombros contra la resistencia. La máquina proporciona estabilidad y permite usar cargas pesadas de forma segura. Mantén la contracción superior y evita rotar los hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Shrugs machine', 'Standing or sitting depending on the design, raise your shoulders against the resistance. The machine provides stability and allows heavy loads to be used safely. Maintain the upper contraction and avoid rotating your shoulders.', 'external'),
('30a88ab2-a850-4d82-a6ae-863ab182e1d3', 'Good morning barra', 55, 71, 116, 1, 'Avanzado', 'Con la barra sobre los trapecios como en sentadilla, inclínate hacia adelante desde las caderas manteniendo las rodillas ligeramente flexionadas. Desciende hasta que el torso esté casi paralelo al suelo. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales. Requiere técnica perfecta.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Good Morning', 'With the barbell across your upper back as in a squat, hinge forward at the hips with a slight knee bend. Lower until your torso is almost parallel to the floor, then return by contracting your glutes and hamstrings. This exercise requires precise technique.', 'external'),
('30da3eab-f4c8-4083-a9ae-49ea1e45059f', 'Curl de piernas acostado', 55, 29, 186, 1, 'Principiante', 'Boca abajo, flexiona rodillas llevando el rodillo a los glúteos. Cue: mantén la cadera pegada al banco. Error: levantar la pelvis al flexionar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Lying Leg Curl', 'Face down, bend your knees, bringing the roller to your buttocks. Cue: keep your hips glued to the bench. Common mistake: raising the pelvis when flexing.', 'external'),
('31104a16-0524-49f7-b8de-e7b512ec52a2', 'Curl de bíceps estricto agarre ancho con barra Z', 17, NULL, 116, 1, 'Principiante', 'Con las manos en la parte ancha de la barra Z y la espalda contra la pared, realiza el curl sin usar impulso del cuerpo.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Wide Grip Strict Biceps Curl with Z Bar', 'With your hands on the wide part of the Z-bar and your back against the wall, perform the curl without using body momentum.', 'external'),
('31126017-f194-4999-9fc4-d3cdab15ab84', 'Aperturas inclinadas en cable', 1, 6, 151, 1, 'Intermedio', 'Aperturas en poleas en banco inclinado para aislar pectoral con tensión continua durante todo el recorrido.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Incline Cable Fly', 'Openings in pulleys on an inclined bench to isolate the pectoral with continuous tension throughout the entire journey.', 'external'),
('3142943b-1fd0-45e8-9ba9-b4e1b579d488', 'Colgado pasivo a una mano en anilla', 100, 71, 1, 1, 'Avanzado', 'Cuélgate de una sola anilla con un brazo completamente extendido. Mantén la posición para trabajar la fuerza de agarre y la estabilidad escapular.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Passive hanging to one hand in a ring', 'Hang from a single ring with one arm fully extended. Hold the position to work on grip strength and scapular stability.', 'bodyweight'),
('316c4535-ccc6-44e0-9736-bb10fac43887', 'Press Overhead con barra Trap', 6, 2, 116, 1, 'Principiante', 'De pie dentro de la barra Trap, sujeta las asas laterales y presiona la barra sobre la cabeza hasta bloquear los codos, manteniendo el core firme.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Overhead Press with Trap Bar', 'Standing inside the trap bar, hold the side handles and press the bar overhead until your elbows are locked, keeping your core firm.', 'external'),
('318ae0bf-37a8-4027-bc37-7a30160e4e03', 'Flexiones diamante', 2, 1, 1, 1, 'Avanzado', 'Coloca las manos juntas bajo el pecho formando un diamante con los dedos índices y pulgares unidos. Mantén los codos cerca del cuerpo durante el descenso para maximizar la activación del tríceps. Baja controladamente hasta que el pecho toque las manos y empuja con fuerza para volver arriba. Este ejercicio requiere mayor fuerza en los tríceps que las flexiones tradicionales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Diamond push-ups', 'Place your hands together under your chest forming a diamond with your index fingers and thumbs together. Keep your elbows close to your body during the descent to maximize triceps activation. Lower yourself down under control until your chest touches your hands and push hard to return up. This exercise requires greater strength in the triceps than traditional push-ups.', 'mixed'),
('31a8b19d-0f2f-458b-9476-fdad149c558e', 'Broad jumps', 28, 29, 1, 1, 'Intermedio', 'Colócate con los pies al ancho de las caderas, desciende a media sentadilla y balancea los brazos hacia atrás. Explota hacia adelante saltando lo más lejos posible. Aterriza con ambos pies simultáneamente amortiguando con las rodillas. Excelente para desarrollar potencia horizontal.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Broad jumps', 'Stand with your feet hip-width apart, lower yourself into a half-squat, and swing your arms back. Explode forward jumping as far as possible. Land with both feet simultaneously, cushioning with your knees. Excellent for developing horizontal power.', 'mixed'),
('31b73e40-c4ad-4e5b-be3a-fce7a5898336', 'Archer Push Up en paralelas', 1, 2, 1, 1, 'Intermedio', 'Variante de la flexion de arquero sobre las barras paralelas, permitiendo un mayor rango de movimiento y profundidad en el descenso.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Archer Push Up on parallel bars', 'Variant of the archer push-up on the parallel bars, allowing a greater range of motion and depth in the descent.', 'mixed'),
('31c60b86-d58c-4b4c-8208-0d41eb7b2793', 'Salto de patinador con parada', 29, 37, 1, 1, 'Intermedio', 'Realiza un salto lateral y mantén el equilibrio sobre la pierna de aterrizaje durante 2 segundos antes de volver. Enfocado en la propiocepción. Cue: clava el aterrizaje sin mover el pie. Error común: bajar el pecho demasiado al suelo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Skater Jump with Stop', 'Perform a side jump and balance on your landing leg for 2 seconds before returning. Focused on proprioception. Cue: stick the landing without moving your foot. Common mistake: lowering your chest too much toward the floor.', 'bodyweight'),
('31e92e1d-56e4-4f01-b05b-fdaa6ac10b15', 'Kettlebell Windmill coordinado', 25, 6, 281, 1, 'Avanzado', 'Pesa arriba, desciende lateralmente para tocar el suelo con la mano libre mirando la pesa. Objetivo: estabilidad de hombro y oblicuos. Cue: pierna superior estirada. Error común: doblar la rodilla del lado de la carga.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Coordinated Kettlebell Windmill', 'Dumbbell up, lower down laterally to touch the floor with your free hand facing the dumbbell. Target: shoulder and oblique stability. Cue: top leg stretched. Common mistake: bending the knee on the side of the load.', 'external'),
('324e0921-d508-4cc4-9114-7b621fba0e74', 'Swing alterno en postura escalonada', 29, 25, 281, 1, 'Intermedio', 'Ejecuta un swing alternando el brazo y la posicion de los pies en cada repeticion, coordinando el cambio de peso en postura split.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Alternating Swing in Staggered Stance', 'Perform a swing while alternating the working arm and the foot position on each repetition, coordinating the hand switch in a split stance.', 'external'),
('3293bcef-2b74-4c07-9d4c-4955ed64e503', 'Remo Pendlay estricto', 71, 17, 116, 1, 'Avanzado', 'Rema barra desde el suelo cada repetición con torso paralelo. Cue: sin impulso. Error: tirones lumbares.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Pendlay Row', 'Row the bar from the floor on each rep with your torso parallel to the ground. Cue: avoid using momentum. Common mistake: straining your lower back.', 'external'),
('32a22877-789d-4b55-95e5-c5aefa093845', 'Flexiones en T estables', 1, 6, 1, 1, 'Intermedio', 'Flexión y rota a lateral elevando brazo. Cue: cuerpo recto. Error: perder equilibrio.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict T Push-Up', 'Perform a push-up and rotate to one side while raising your arm. Cue: keep your body straight. Common mistake: losing balance during the rotation.', 'mixed'),
('32a7c301-9f0e-47a8-8fd9-a45f7803b151', 'Cable Reverse Crunch', 25, NULL, 151, 1, 'Principiante', 'Acuéstate boca arriba con los pies enganchados a la polea baja. Lleva las rodillas hacia el pecho levantando la cadera del suelo contra la resistencia.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Cable Reverse Crunch', 'Lie on your back with your feet hooked to the low cable. Bring your knees toward your chest, lifting your hips off the ground against the resistance.', 'external'),
('32b46b32-069d-452a-90ea-18eba87c6979', 'Elevación frontal agarre inverso con barra', 6, 100, 116, 1, 'Principiante', 'Sujeta la barra con las palmas hacia arriba (supino) y elévala frente a ti hasta la altura de los hombros con los brazos rectos.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Barbell Reverse Grip Front Raise', 'Hold the bar with your palms facing up (supine) and raise it in front of you to shoulder height with your arms straight.', 'external'),
('32e19ab6-fe17-4c54-8f2d-07a47f4e5c6f', 'Kettlebell Windmill estático', 25, 6, 281, 1, 'Avanzado', 'Pesa arriba, inclina el torso para tocar el pie opuesto mirando la pesa. Objetivo: estabilidad de hombro y core. Cue: pierna superior recta. Error común: doblar la rodilla del lado de la pesa.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Static Kettlebell Windmill', 'Dumbbell up, tilt your torso to touch the opposite foot looking at the dumbbell. Target: shoulder and core stability. Cue: straight upper leg. Common mistake: bending your knee on the side of the dumbbell.', 'external'),
('3372f96a-f0c1-4221-8c1a-84125a37a34d', 'Pull-over en polea alta', 16, 71, 151, 1, 'Intermedio', 'Pullover en cable para aislar dorsal con brazos casi extendidos, enfatizando depresión escapular y control del tronco.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'High pulley pull-over', 'Cable pullover to isolate the back with almost extended arms, emphasizing scapular depression and torso control.', 'external'),
('338c25cf-136f-4ef2-8b9f-8432b9f998e6', 'Press de hombros arrodillado con barra Landmine', 6, 2, 116, 1, 'Intermedio', 'Arrodillado sobre ambas piernas, presiona el extremo de la barra hacia arriba en arco, trabajando hombros y core de forma estable.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Landmine Kneeling Barbell Shoulder Press', 'Kneeling on both legs, press the end of the bar up in an arc, working shoulders and core in a stable manner.', 'external'),
('33b76dbd-ad2e-45e9-a531-455c39f20579', 'Push press barra', 6, 28, 116, 1, 'Intermedio', 'Press de hombros asistido con impulso de piernas. Realiza un pequeño dip (flexión de rodillas) y usa la extensión explosiva de piernas para ayudar a presionar la barra sobre la cabeza. Permite usar más peso que el press estricto y desarrolla potencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Push press bar', 'Assisted shoulder press with leg drive. Perform a small dip (knee bend) and use explosive leg extension to help press the bar overhead. It allows you to use more weight than the strict press and develops power.', 'external'),
('33c7b455-0870-4e1b-8d97-fce1ad4fbb01', 'Full Front Lever en anillas', 25, 16, 1, 24, 'Avanzado', 'Manten el cuerpo totalmente estirado y paralelo al suelo de cara al techo, colgado de las anillas con los brazos bloqueados.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Full Front Lever on rings', 'Keep your body fully stretched and parallel to the floor facing the ceiling, hanging from the rings with your arms locked.', 'bodyweight'),
('33ddae5a-f60b-4ded-94fd-f5a38ba39dd9', 'Elevaciones posteriores cable', 6, NULL, 151, 1, 'Intermedio', 'Inclinado hacia adelante o de pie con el torso paralelo al suelo, realiza elevaciones posteriores con cable. Puedes hacerlo unilateral o bilateral. Enfócate en el deltoides posterior y evita usar impulso. Mantén una ligera flexión en el codo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Posterior Raises', 'Leaning forward or standing with your torso parallel to the floor, perform cable rear raises. You can do it unilateral or bilateral. Focus on the rear deltoid and avoid using momentum. Maintain a slight bend in the elbow.', 'external'),
('33fcada7-fb00-4997-a101-422ed9d32f5d', 'Elevación Lu con discos', 6, NULL, 81, 1, 'Intermedio', 'Sostén un disco o mancuerna ligera en cada mano. Realiza una elevación lateral completa hasta que las pesas se toquen por encima de la cabeza.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Lu lift with discs', 'Hold a plate or light dumbbell in each hand. Perform a full lateral raise until the dumbbells touch overhead.', 'external'),
('33fe9899-6ead-421e-b428-b9183f47550e', 'Sentadilla Pistola contralateral en TRX a una mano', 28, 29, 216, 1, 'Avanzado', 'Sujeta una sola correa de TRX con el brazo opuesto a la pierna de apoyo mientras realizas una sentadilla profunda a una pierna.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Contralateral Single-Arm TRX Pistol Squat', 'Hold a single TRX strap with the arm opposite your supporting leg while performing a deep one-leg squat.', 'assisted'),
('3413c11e-8280-42d5-80c2-8c2de1a60629', 'Kettlebell Snatch', 29, 6, 281, 1, 'Avanzado', 'Lleva la pesa desde el suelo hasta encima de la cabeza en un solo movimiento explosivo. Golpe de cadera. Brazo pegado a la oreja. No golpees tu antebrazo con la pesa.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Snatch', 'Bring the weight from the floor to overhead in a single explosive movement. Hip bump. Arm pressed to the ear. Don''t hit your forearm with the weight.', 'external'),
('341cf7ae-5949-4cfc-b178-b0c851b59f39', 'Curl de bíceps polea baja cuerda', 17, 100, 151, 1, 'Principiante', 'Flexiona el bíceps con cuerda en polea baja. Cue: abre extremos arriba. Error: balancear brazos.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Low Rope Cable Biceps Curl', 'Flex your biceps with a low cable rope. Cue: open ends up. Common mistake: swinging arms.', 'external'),
('347e571c-a9fd-4b51-ae25-4b3d863c56f3', 'Lanzamiento de balón a una mano', 6, 1, 240, 1, 'Intermedio', 'Empuja el balón medicinal desde el hombro con un solo brazo lo más fuerte posible. Potencia unilateral. Cue: usa el core para estabilizar. Error común: inclinar el cuerpo hacia un lado al lanzar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'One-handed Ball Throw', 'Push the medicine ball from your shoulder with one arm as hard as possible. Unilateral power. Cue: use your core to stabilize. Common mistake: leaning your body to one side when throwing.', 'external'),
('349bb768-ae6f-46d5-ba3e-80aef5be1cf1', 'Paseo del granjero', 13, 100, 81, 24, 'Principiante', 'Camina una distancia cargando mancuernas pesadas a los lados. Cue: hombros atrás y abajo, pasos cortos. Error: dejar que el peso balancee tus brazos.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Farmer''s Walk', 'Walk a distance carrying heavy dumbbells at your sides. Cue: shoulders back and down, short steps. Common mistake: letting the weight swing your arms.', 'external'),
('34d9f966-784e-4666-8d5f-d881e783b175', 'Elevación de rodillas colgado', 25, 37, 1, 1, 'Intermedio', 'Colgado de barra, eleva las rodillas hacia el pecho de forma controlada. Objetivo: abdominal inferior. Cue: no te balancees. Error común: usar el impulso de las piernas para subir.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Hanging Knee Raise', 'Hanging from a bar, raise your knees toward your chest in a controlled manner. Target: lower abdominal. Cue: don''t swing. Common mistake: using the momentum of your legs to go up.', 'bodyweight'),
('34f71bab-7793-4536-8183-23e3961f8ed4', 'Stability Ball Feet Elevated Crunch', 25, NULL, 290, 1, 'Principiante', 'Acuéstate boca arriba y coloca las pantorrillas sobre el Fitball. Con las manos detrás de la cabeza, contrae el abdomen para levantar los hombros del suelo. Baja lentamente sin tirar del cuello.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball Feet Elevated Crunch', 'Lie on your back and place your calves on the stability ball. With your hands behind your head, contract your abs to lift your shoulders off the floor. Go down slowly without pulling on the neck.', 'bodyweight'),
('34fbec39-5777-405d-b108-c8954fb96f50', 'Sentadilla frontal a una mano con Kettlebell', 28, 29, 281, 1, 'Principiante', 'Sostén una pesa rusa en posición de rack sobre un hombro. Realiza una sentadilla profunda manteniendo el torso erguido y el codo de la carga elevado para estabilizar el peso.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-hand Kettlebell Front Squat', 'Hold a kettlebell in a rack position over one shoulder. Perform a deep squat, keeping your torso upright and the elbow of the load raised to stabilize the weight.', 'external'),
('350290d8-5d35-49e0-80e1-5d74a17603b5', 'Roll out lateral', 25, NULL, 271, 1, 'Avanzado', 'Rueda en ángulo diagonal hacia los lados en lugar de recto. Enfatiza los oblicuos. Alterna los lados o completa series por lado. Mantén el control durante todo el movimiento evitando la rotación excesiva.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Side roll out', 'It rolls at a diagonal angle to the sides instead of straight. Emphasize the obliques. Alternate sides or complete sets per side. Maintain control throughout the movement by avoiding excessive rotation.', 'external'),
('351aee73-333f-4f36-abfa-ee2f7427e7da', 'Cruces inferiores cable', 1, NULL, 151, 1, 'Intermedio', 'Con las poleas en posición baja, realiza el movimiento llevando las manos hacia arriba y al centro. Esta variación trabaja más la porción superior del pectoral. Mantén el core activado para evitar arquear excesivamente la espalda.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lower Cable Crossovers', 'With the cables in a low position, perform the movement by bringing your hands up and to the center. This variation works the upper portion of your chest more. Keep your core engaged to avoid arching your back excessively.', 'external'),
('354eeebc-1742-4455-8c00-7ec61edde651', 'Curl femoral tumbado', 55, NULL, 186, 1, 'Principiante', 'Tumbado boca abajo, flexiona las rodillas llevando los talones hacia los glúteos. Mantén las caderas pegadas al banco para evitar arquear la espalda. Controla el movimiento en ambas fases y aprieta al máximo en la contracción.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lying Femoral Curl', 'Lying face down, bend your knees, bringing your heels towards your buttocks. Keep your hips close to the bench to avoid arching your back. Control the movement in both phases and tighten as much as possible during the contraction.', 'external'),
('3550e2e3-b086-4309-b2bf-21a71b71ba4e', 'Step Up Overhead con Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Sube al banco manteniendo dos Kettlebells bloqueadas sobre la cabeza, exigiendo máxima estabilidad de hombros y control del core.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Overhead Step-up', 'Step onto the bench while holding two kettlebells locked out overhead, demanding maximum shoulder stability and full-body control.', 'external'),
('3551d26f-51ad-40b3-aa6d-eeea43af951f', 'Curl araña barra Z', 17, NULL, 116, 1, 'Intermedio', 'Pecho en banco inclinado, flexiona brazos colgando. Objetivo: bíceps aislado. Cue: codos fijos. Error: balanceo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Z Bar Spider Curl', 'Chest on inclined bench, flex arms while hanging. Target: isolated biceps. Cue: keep your elbows fixed. Common mistake: swinging.', 'external'),
('3552a917-6230-4db8-a22e-be3a9acf1ab2', 'Sentadilla Split con barra trasera', 28, 29, 116, 1, 'Principiante', 'Con la barra sobre los hombros y un pie adelantado, baja la rodilla trasera hacia el suelo manteniendo el torso erguido y sube controladamente.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Split Squat with Back Bar', 'With the bar on your shoulders and one foot forward, lower your back knee toward the floor, keeping your torso upright, and raise yourself up under control.', 'external'),
('3554fc00-3874-4b53-af15-62e5c248ec7b', 'Power Snatch alterno a una mano con mancuerna', 29, 6, 81, 1, 'Intermedio', 'Realiza el movimiento de Snatch con una mano, baja la mancuerna de forma segura y repite alternando el brazo en cada repeticion.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Power Snatch Alternate to One Hand Dumbbell', 'Perform the Snatch movement with one hand, lower the dumbbell safely and repeat, alternating the arm with each repetition.', 'external'),
('35629ce0-d38e-478e-ab1c-e3558b7da433', 'Press Overhead de rodillas con barra Trap', 6, 2, 116, 1, 'Principiante', 'Arrodillado sobre ambas piernas (Tall Kneeling), sujeta la barra Trap por las asas y presionala verticalmente sobre la cabeza.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Kneeling Overhead Press with Trap Bar', 'Kneeling on both legs (Tall Kneeling), hold the Trap Bar by the handles and press it vertically overhead.', 'external'),
('358320d7-bc4e-4219-8737-89c2f62f8b19', 'Sentadilla Búlgara Overhead contralateral con Kettlebell Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Con un pie elevado, sostén la pesa rusa invertida sobre la cabeza con el brazo opuesto a la pierna delantera y realiza la sentadilla.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Contralateral Overhead Bottoms-Up Bulgarian Split Squat with Kettlebell', 'With one foot raised, hold the inverted kettlebell overhead with the arm opposite your front leg and perform the squat.', 'external'),
('3598a045-72f1-4546-b5c2-d730200f0eaa', 'Advanced Tuck Front Lever en anillas', 25, 16, 1, 24, 'Avanzado', 'Mantén la posicion de Front Lever con los brazos rectos y la espalda plana, pero con las rodillas separadas del pecho formando un angulo de 90 grados.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Advanced Tuck Front Lever on rings', 'Maintain the Front Lever position with your arms straight and your back flat, but with your knees separated from your chest at a 90-degree angle.', 'bodyweight'),
('360693dc-74d1-4cc4-be8c-cd2b19836ba4', 'Salto pogo diagonal', 64, 309, 1, 1, 'Intermedio', 'Saltos rápidos sobre puntas de pies en trayectoria de zigzag diagonal. Mejora la agilidad lateral y frontal. Cue: contactos eléctricos en el suelo. Error común: perder la línea de movimiento.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Diagonal Pogo Jump', 'Quick pogo jumps on the balls of your feet in a diagonal zigzag path. Improves lateral and forward agility. Cue: make quick, light contacts with the ground. Common mistake: losing the movement line.', 'bodyweight'),
('362e733c-b23d-4643-adb1-00f44c367ff9', 'Elevaciones pantorrilla mancuernas', 64, NULL, 81, 1, 'Principiante', 'De pie con una mancuerna en cada mano a los lados, elévate sobre las puntas de los pies lo más alto posible. Mantén la contracción máxima por un segundo y desciende lentamente. Puedes realizar el ejercicio en un step para mayor rango de movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Calf Raises', 'Standing with a dumbbell in each hand at your sides, rise on the balls of your feet as high as possible. Hold the maximum contraction for one second and lower yourself slowly. You can perform the exercise in one step for greater range of motion.', 'external'),
('36796f2e-a615-4ab3-99f7-9f608a1f4af9', 'Zancada caminando Front Rack con Kettlebell a una mano Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Camina realizando zancadas con una Kettlebell invertida en un hombro, lo que genera una gran demanda de estabilización lateral y de agarre.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Walking Front Rack Single-Arm Bottoms-Up Kettlebell Lunge', 'Walk forward performing lunges with an upside-down kettlebell on one shoulder, creating a strong demand for lateral stability and grip strength.', 'external'),
('3681c7e5-aa97-4540-940e-9503d1df8dff', 'Planche push ups', 6, 2, 1, 1, 'Avanzado', 'Desde la posición de planche (cuerpo horizontal sostenido solo por las manos), realiza flexiones manteniendo el cuerpo paralelo al suelo sin apoyo de los pies. Es uno de los ejercicios de peso corporal más difíciles, requiriendo años de entrenamiento progresivo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Planche push ups', 'From the planche position (horizontal body supported only by the hands), perform push-ups keeping the body parallel to the floor without support from the feet. It is one of the most difficult bodyweight exercises, requiring years of progressive training.', 'mixed'),
('3689d89a-fb3d-4c8f-bcda-3118cca90c04', 'Remo prono con mancuerna a una mano', 71, 17, 81, 1, 'Principiante', 'Tumbado boca abajo sobre un banco, rima una sola mancuerna hacia tu costado, enfocándote en el aislamiento del dorsal ancho.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-Handed Prone Dumbbell Row', 'Lying face down on a bench, curl a single dumbbell out to your side, focusing on latissimus dorsi isolation.', 'external'),
('36a7c074-c2a0-427e-87fb-8f50a44833fc', 'Slam con maza en postura escalonada', 25, 6, 1, 1, 'Principiante', 'Golpea un neumatico utilizando una maza (macebell) desde una postura escalonada, enfocando el esfuerzo en la rotacion y potencia del core.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Mace slam in staggered stance', 'Hit a tire using a macebell from a staggered stance, focusing effort on core rotation and power.', 'bodyweight'),
('36e1c561-ade8-4ce5-b30e-b8394fbf7dbe', 'Sentadilla con salto vertical', 28, 29, 1, 1, 'Intermedio', 'Sentadilla explosiva terminando en salto máximo. Cue: aterriza con las puntas. Error: aterrizaje con piernas rígidas.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Squat with Vertical Jump', 'Explosive squat ending in maximum jump. Cue: land on your toes. Common mistake: landing with stiff legs.', 'mixed'),
('36fda61c-c995-4c20-9cf8-be9c7499aa8d', 'Peso muerto velocidad', 55, 29, 116, 1, 'Avanzado', 'Peso muerto con 50-70% del máximo enfocándose en velocidad explosiva. Desarrolla potencia. Mantén técnica perfecta a pesar de la velocidad. Útil para romper mesetas. Descansa completamente entre series.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Peso muerto velocidad', 'Perform the deadlift with 50-70% of your max, focusing on explosive speed. It develops power. Keep your technique perfect despite the speed. Useful for breaking plateaus. Rest fully between sets.', 'external'),
('37064e38-6523-4201-8461-46040b60e8ca', 'Extensión de cadera en cuadrupedia con Miniband', 29, NULL, 61, 1, 'Principiante', 'En cuatro puntos con la banda en las rodillas, patea hacia arriba con una pierna para aislar el glúteo contra la resistencia.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Quadruped Hip Extension with Mini Band', 'On four points with the band on your knees, kick up with one leg to isolate the glute against the resistance.', 'external'),
('37163481-1acf-4b6f-b6a3-6c8504ec21eb', 'Sit Up', 25, NULL, 1, 1, 'Principiante', 'Acuéstate boca arriba con las rodillas dobladas. Levanta el torso completo del suelo usando los abdominales hasta quedar sentado, luego baja controlando el movimiento.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Sit Up', 'Lie on your back with your knees bent. Raise your entire torso off the floor using your abs until you are sitting, then lower yourself down, controlling the movement.', 'mixed'),
('3718dc21-31c5-48b3-b706-6f0927a0bbe3', 'Battle ropes mountain climber', 25, 6, 256, 24, 'Avanzado', 'Alterna entre mountain climbers y ondas con las cuerdas. Realiza varias repeticiones de climbers, luego incorpora las cuerdas. Requiere coordinación excepcional y resistencia. Mantén las transiciones fluidas entre movimientos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle ropes mountain climber', 'Alternate between mountain climbers and rope waves. Perform several repetitions of climbers, then incorporate the ropes. Requires exceptional coordination and stamina. Keep transitions between movements fluid.', 'external'),
('37468db5-467a-4968-baab-a2833395cc5d', 'Cuerda para triceps de espaldas a polea alta', 2, 6, 151, 1, 'Intermedio', 'Realiza una extensión de tríceps con cuerda de espaldas a una polea alta. Lleva la cuerda por encima de la cabeza y extiende los codos manteniendo los brazos estables.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Overhead Rope Cable Triceps Extension', 'Perform an overhead rope cable triceps extension facing away from a high pulley. Bring the rope overhead and extend the elbows while keeping the upper arms stable.', 'external'),
('374924cc-c39d-4758-88ca-c0848f3acf00', 'Clean con barra', 13, 71, 116, 1, 'Avanzado', 'Lleva la barra del suelo a los hombros en un movimiento explosivo. Cue: extensión total de cadera, codos rápidos. Error: tirar solo con los brazos.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Clean with Bar', 'Bring the bar from the floor to your shoulders in an explosive movement. Cue: full hip extension, quick elbows. Common mistake: pulling only with your arms.', 'external'),
('37543c6d-b3e4-45e3-a7b4-084e8c2af009', 'Gorilla Row con Kettlebell doble', 71, 17, 281, 1, 'Intermedio', 'De pie con piernas separadas y dos pesas rusas en el suelo. Inclínate y rema una pesa mientras empujas la otra contra el suelo, alternando lados.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double Kettlebell Gorilla Row', 'Stand with legs apart and two kettlebells on the floor. Bend over and row one dumbbell while pushing the other into the floor, alternating sides.', 'external'),
('37b86011-9862-42ee-bcb2-10c0ec36c6a2', 'Full Planche en anillas', 25, 6, 1, 24, 'Avanzado', 'Posicion estatica extrema donde el cuerpo se mantiene horizontal apoyado solo en las manos en las anillas con brazos bloqueados.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Full Planche in Rings', 'Extreme static position where the body remains horizontal supported only by the hands on the rings with locked arms.', 'bodyweight'),
('37dd543c-5d70-4cad-80e9-0f07ad80f56f', 'Step-up con barra nuca', 28, 29, 116, 1, 'Intermedio', 'Sube cajón con barra. Objetivo: fuerza unilateral. Cue: empuja pierna arriba. Error: saltar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Back Rack Step-up', 'Step onto the box with the barbell on your upper back. Target: unilateral strength. Cue: drive through the lead leg. Common mistake: jumping.', 'external'),
('37e23814-ab7d-4712-9bfe-a1c969191302', 'Floor Press barra', 1, 2, 116, 1, 'Principiante', 'Press en suelo con barra. Objetivo: fuerza de bloqueo. Cue: tríceps tocan suelo suave. Error: rebotar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Barbell Floor Press', 'Perform a barbell floor press. Target: lockout strength. Cue: let your triceps touch the floor lightly. Common mistake: bouncing off the floor.', 'external'),
('37ea5f10-beb2-48c5-903c-976397c7a3c9', 'Pike a una pierna sobre Fitball', 25, 6, 290, 1, 'Avanzado', 'En plancha con un pie sobre el Fitball y el otro extendido arriba. Eleva las caderas hacia el techo manteniendo la pierna de apoyo recta, formando una V invertida.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Single-Leg Pike on Stability Ball', 'In a plank position with one foot on the stability ball and the other leg extended upward, lift your hips toward the ceiling while keeping the supporting leg as straight as possible. Return under control.', 'bodyweight'),
('37fbe299-ef85-4df2-af34-84d92e283729', 'Sentadilla Pistola Overhead con Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Sentadilla profunda a una pierna manteniendo dos Kettlebells bloqueadas sobre la cabeza, el nivel mas alto de equilibrio con peso.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Double kettlebell Overhead Pistol Squat', 'Deep squat on one leg while keeping two kettlebells locked overhead, the highest level of weighted balance.', 'external'),
('380112c2-ec6e-499f-aadb-5d7c940e2ac9', 'Volante sentado con disco', 6, 100, 81, 1, 'Principiante', 'Sentado con la espalda recta, sujeta un disco frente a ti con los brazos estirados y gíralo de lado a lado como si fuera un volante.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Seated Steering Wheel with Plate', 'Sit with your back straight, hold a weight plate in front of you with your arms extended, and rotate it side to side as if it were a steering wheel.', 'external'),
('3804d33b-5a05-4cab-aef7-1b15f7252464', 'Remo Gironda', 16, 17, 186, 1, 'Intermedio', 'Remo estilo Gironda para énfasis en dorsal/espalda, buscando recorrido y contracción escapular con técnica limpia.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Gironde rowing', 'Gironda style row to emphasize the dorsal/back, seeking scapular travel and contraction with clean technique.', 'external'),
('381004c5-7421-4e41-9706-abe256101e71', 'Woodchopper con mancuerna', 25, 6, 81, 1, 'Intermedio', 'Sujeta una mancuerna con ambas manos. Inicia el movimiento desde un lado de la cadera y eleva la pesa en diagonal hacia el hombro contrario, girando el torso. Controla el descenso. Objetivo: fuerza rotacional del core y oblicuos. Cue: pivota sobre el pie trasero para proteger la rodilla. Error común: mover solo los brazos sin rotar el tronco.', FALSE, NULL, '2026-01-16T11:22:19.199676+00:00', 'Dumbbell Woodchopper', 'Hold a dumbbell with both hands. Start the movement from one side of your hip and lift the weight diagonally toward the opposite shoulder while rotating your torso. Control the descent. Target: rotational core and oblique strength. Cue: pivot on the rear foot to protect the knee. Common mistake: moving only the arms without rotating the trunk.', 'external'),
('381fbf9f-77e7-40c8-a1bc-166cd55859b5', 'Zancada atrás con elevación de rodilla', 28, 29, 1, 1, 'Principiante', 'Realiza una zancada hacia atrás y sube la rodilla al pecho al volver a la posición de pie. Objetivo: equilibrio dinámico y piernas. Cues: clava el pie de apoyo. Error común: realizar el movimiento con prisa perdiendo el control.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Reverse Lunge with Knee Drive', 'Perform a reverse lunge and drive the knee up toward your chest as you return to standing. Target: dynamic balance and leg strength. Cue: plant the support foot firmly. Common mistake: rushing the movement and losing control.', 'mixed'),
('383712ef-e856-4a95-a6df-f0b420d4856d', 'Saltos de tobillo con rotación de cadera', 64, 25, 1, 1, 'Intermedio', 'Saltos cortos de puntera girando la cadera 90 grados en cada salto. Agilidad. Cuerpo erguido. No apoyes el pie plano.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Ankle hops with hip rotation', 'Short toe jumps, rotating the hips 90 degrees in each jump. Agility. Upright body. Do not rest your feet flat.', 'bodyweight'),
('383b660a-f4b4-43bf-af90-5945bd6d57e1', 'Peso muerto rumano a una pierna en Landmine', 55, 29, 116, 1, 'Intermedio', 'Realiza un peso muerto rumano sobre una sola pierna sujetando la barra Landmine con el brazo opuesto, mejorando equilibrio y estabilidad lateral.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Romanian Single Leg Deadlift in Landmine', 'Perform a single-leg Romanian deadlift holding the Landmine bar with the opposite arm, improving balance and lateral stability.', 'external'),
('383e202c-4373-4356-9ea1-f17e40e5105c', 'Press de banca con mancuernas', 1, 2, 81, 1, 'Principiante', 'Tumbado en banco plano, empuja las mancuernas desde el pecho. Objetivo: fuerza de empuje y estabilidad pectoral. Cue: controla el descenso. Error común: chocar las pesas ruidosamente arriba.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Dumbbell Bench Press', 'Lying on a flat bench, push the dumbbells from your chest. Target: push strength and chest stability. Cue: controls the descent. Common mistake: crashing the weights loudly overhead.', 'external'),
('38535754-39b2-4bd0-89d8-71bcf7745848', 'Press de banca alterno con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado, alterna el press de dos Kettlebells invertidas, manteniendo una en alto mientras la otra baja, desafiando el control motor.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Bottoms Up Double kettlebell Alternating Bench Press', 'Lying down, alternate pressing two inverted kettlebells, keeping one high while the other goes down, challenging motor control.', 'external'),
('38556616-33c5-47f0-a4b3-22488ab7957b', 'Ring Support Hold', 25, 2, 1, 24, 'Avanzado', 'Mantente en posicion vertical sobre las anillas con los brazos estirados y bloqueados, estabilizando el cuerpo contra el temblor.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Ring Support Hold', 'Stay upright on the rings with your arms straight and locked, stabilizing your body against shaking.', 'bodyweight'),
('388d28b2-b73a-432b-84fc-51c62d3b8c89', 'Patada de glúteo en polea', 29, 55, 151, 1, 'Principiante', 'De frente a la polea, extiende la pierna hacia atrás. Cue: no arquees la espalda baja al patear. Error: girar la cadera hacia un lado.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Pulley Glute Kick', 'Facing the cable, extend your leg backwards. Cue: don''t arch your lower back when kicking. Common mistake: turning your hips to one side.', 'external'),
('38a86f34-d757-4035-8cc5-09eef1291d86', 'Lanzamiento de balón medicinal en V', 25, 6, 240, 1, 'Intermedio', 'Sentado en V, lanza el balón lateralmente. Potencia de oblicuos. Piernas elevadas. No toques el suelo con los pies.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'V Medicine Ball Throw', 'Sitting in V, throw the ball laterally. Oblique power. raised legs. Don''t touch the ground with your feet.', 'external'),
('38fbcd38-14b0-4e10-8dd2-7c5ffbb95e4c', 'Rollout de rodillas con barra', 25, 16, 116, 1, 'Intermedio', 'De rodillas, sujeta una barra cargada con discos pequeños. Desliza la barra hacia adelante extendiendo el cuerpo sin arquear la espalda y regresa usando el abdomen.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Kneeling Barbell Rollout', 'On your knees, hold a barbell loaded with small plates. Slide the bar forward by extending your body without arching your back and return using your abs.', 'external'),
('390a015a-9090-4438-af06-1ae1a1f1cbe7', 'Salto profundidad aterrizaje unilateral', 29, 28, 1, 1, 'Avanzado', 'Cae de un cajón y aterriza sobre una sola pierna clavando el equilibrio. Cue: amortigua suave con la rodilla alineada. Error común: caída pesada con el talón.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Unilateral Landing Depth Jump', 'He falls off a box and lands on one leg, keeping his balance. Cue: soft cushion with knee aligned. Common mistake: heavy heel landing.', 'bodyweight'),
('3916e712-b610-4e86-938f-c47af2b162cf', 'Plancha up-down', 25, 6, 1, 1, 'Intermedio', 'Comienza en plancha sobre antebrazos y transiciona a plancha alta extendiendo un brazo a la vez hasta apoyarte en las manos. Luego regresa a la posición de antebrazos. Alterna el brazo que inicia el movimiento. Mantén las caderas estables evitando la rotación durante las transiciones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank Up-Down', 'Start in a forearm plank and transition to a high plank by extending one arm at a time until both hands are on the floor. Return to the forearm plank under control.', 'bodyweight'),
('3919b162-ec0e-43dc-86f5-baed6fbb33d3', 'Dead hang', 71, 100, 1, 1, 'Intermedio', 'Colgarse de la barra para descomprimir hombros y activar agarre, dorsal y musculatura escapular.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Dead Hang', 'Hang from the bar to decompress shoulders and activate grip, dorsal and scapular muscles.', 'bodyweight'),
('3927f0ec-f495-434c-8d8e-ac14d03861c2', 'Curl de bíceps martillo mancuernas', 17, 100, 81, 1, 'Principiante', 'Flexiona pesas con agarre neutro (palmas enfrentadas). Cue: codos pegados. Error: balancear cuerpo.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Dumbbell Hammer Biceps Curl', 'Flex dumbbells with a neutral grip (palms facing each other). Cue: elbows stuck together. Common mistake: balance body.', 'external'),
('393c069f-bda1-4d39-b122-6228c6ba6e4c', 'Progresiones palanca', 25, 16, 1, 24, 'Avanzado', 'Serie de ejercicios progresivos hacia palanca frontal y posterior: tuck, advanced tuck, straddle, half lay, full. Cada progresión requiere semanas o meses de trabajo. Paciencia y consistencia son clave. Trabaja negativos y estáticos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lever progressions', 'Series of progressive exercises towards front and rear lever: tuck, advanced tuck, straddle, half lay, full. Each progression requires weeks or months of work. Patience and consistency are key. Work negatives and statics.', 'bodyweight'),
('3982c4a4-5bc2-46d7-883d-9a19e498f7a9', 'Battle ropes saltos potencia', 13, 6, 256, 1, 'Avanzado', 'Salta y golpea cuerdas. Objetivo: potencia total. Cue: salto alto. Error: aterrizaje rígido.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Battle Ropes Power Jumps', 'Jump and hit ropes. Target: total power. Cue: high jump. Common mistake: hard landing.', 'external'),
('3993991e-0cc2-4118-b658-e47ee058039f', 'Sentadilla Búlgara Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sentadilla split con pie elevado manteniendo dos pesas rusas invertidas bloqueadas sobre la cabeza, el reto maximo de estabilidad de piernas.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Bulgarian Overhead Squat with Double Bottoms-Up Kettlebell', 'Split squat with raised foot keeping two inverted kettlebells locked overhead, the ultimate leg stability challenge.', 'external'),
('39eeda8b-3815-447c-940e-a747b9c5ba24', 'Sentadilla Pistola (Pistol Squat)', 28, 29, 1, 1, 'Avanzado', 'Realiza una sentadilla profunda sobre una sola pierna mientras mantienes la otra pierna extendida hacia adelante sin tocar el suelo.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Pistol Squat', 'Perform a deep squat on one leg while keeping the other leg extended forward without touching the ground.', 'mixed'),
('3a0140b6-51e2-4d8f-977b-7f5cdccd76c3', 'Suspension Knee Tuck', 25, 6, 216, 1, 'Intermedio', 'Coloca los pies en los estribos del TRX y ponte en posición de plancha. Lleva ambas rodillas hacia el pecho simultáneamente y luego extiéndelas de nuevo a la posición inicial.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Suspension Knee Tuck', 'Place your feet in the TRX straps and get into a plank position. Bring both knees toward your chest at the same time and return under control.', 'bodyweight'),
('3a0353ba-55bf-4d34-bbae-0326e5362e1c', 'Curl de bíceps con barra', 17, NULL, 116, 1, 'Principiante', 'De pie, sostén una barra con agarre supino (palmas arriba). Flexiona los codos para levantar la barra hacia el pecho y baja controlado.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Barbell biceps curl', 'Standing, hold a barbell with an underhand grip (palms up). Bend your elbows to lift the bar toward your chest and lower it under control.', 'external'),
('3a293767-95cc-4ca9-9bf2-f14f29aefbf0', 'Extensión de tríceps Overhead sentado con barra Z', 2, NULL, 116, 1, 'Principiante', 'Siéntate sosteniendo una barra Z sobre la cabeza. Baja la barra por detrás de la nuca flexionando los codos y extiende de nuevo hacia arriba.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Z-Bar Seated Overhead Triceps Extension', 'Sit holding a Z bar above your head. Lower the bar behind your neck by bending your elbows and extend it upwards again.', 'external');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('3a7df41a-0ce3-477e-b72f-1e2e1d7285b1', 'Thruster Ciclista a una mano con Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza un thruster ciclista sosteniendo la Kettlebell invertida (fondo arriba), lo que exige un control extremo de la estabilidad del hombro y del core.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Cyclist Single-Arm Bottoms-Up Kettlebell Thruster', 'Perform a cyclist thruster while holding the kettlebell upside down, which demands exceptional shoulder and core stability.', 'external'),
('3a88303c-a4d2-47fa-89d1-e5f78f5fd342', 'Remo Yates supinado con barra', 71, 17, 116, 1, 'Intermedio', 'Remo inclinado con palmas hacia arriba a 45 grados. Objetivo: dorsal inferior y bíceps. Cue: tira hacia el ombligo. Error común: usar balanceo de piernas para subir.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Supinated Yachting Row with Bar', 'Bent-over row with palms facing up at 45 degrees. Target: lower dorsal and biceps. Cue: pull towards the navel. Common mistake: using leg swing to climb.', 'external'),
('3a8a5928-efdf-4071-844d-685aa0f009a9', 'Peso muerto rumano', 55, 29, 116, 1, 'Intermedio', 'Realiza un peso muerto rumano llevando la cadera hacia atrás con una ligera flexión de rodillas. Baja la carga de forma controlada manteniendo la espalda neutra y vuelve extendiendo la cadera.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Romanian Deadlift', 'Perform a Romanian deadlift by pushing the hips back with a slight knee bend. Lower the load under control while keeping the back neutral and return by extending the hips.', 'external'),
('3a9713f8-65fb-4560-b114-99ff2a12941b', 'Abducción de cadera sentado con Miniband', 37, 29, 61, 1, 'Principiante', 'Siéntate en el borde de un banco con una banda sobre las rodillas. Separa las rodillas hacia afuera contra la banda manteniendo los pies plantados.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Seated Hip Abduction with Mini Band', 'Sit on the edge of a bench with a band over your knees. Spread your knees outward against the band, keeping your feet planted.', 'external'),
('3aaada73-a02e-4b53-9d86-4a3c17ee40b1', 'Jalones frontales', 16, 17, 151, 1, 'Intermedio', 'Realiza un jalón frontal al pecho en polea. Tira de la barra hacia la parte alta del pecho juntando las escápulas y controla la fase de subida.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Front Lat Pulldown', 'Perform a front lat pulldown on a cable machine. Pull the bar toward the upper chest by bringing the shoulder blades together and control the return phase.', 'external'),
('3aaff64e-d282-427f-8f3d-036240f19530', 'Remo inclinado barra', 16, 17, 116, 1, 'Intermedio', 'Inclínate hacia adelante con las rodillas ligeramente flexionadas y la espalda recta. Tira de la barra hacia el abdomen inferior manteniendo los codos cerca del cuerpo. Aprieta los omóplatos en la parte superior. Mantén la posición del torso estable durante todo el ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Bent Over Row', 'Lean forward with your knees slightly bent and your back straight. Pull the bar toward your lower abs, keeping your elbows close to your body. Squeeze your shoulder blades at the top. Maintain a stable torso position throughout the exercise.', 'external'),
('3abc1e3b-1de6-406e-a73d-4713d495a65c', 'Sentadilla Pistola Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza una sentadilla pistola manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, el ejercicio de estabilidad mas dificil.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Overhead Pistol Squat with Double kettlebell Bottoms Up', 'Perform a pistol squat while keeping two inverted kettlebells locked overhead, the most difficult stability exercise.', 'external'),
('3abfff53-f4ea-4e53-a232-a9915516098c', 'Skull Crusher en banco declinado con barra Z', 2, NULL, 116, 1, 'Intermedio', 'En un banco declinado, realiza la extension de codos llevando la barra Z hacia la frente, proporcionando un angulo diferente de tension para el triceps.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Skull Crusher on Decline Bench with Z Bar', 'On a decline bench, perform the elbow extension by bringing the Z bar toward your forehead, providing a different angle of tension for the triceps.', 'external'),
('3b13d84c-832f-473e-982c-feed30fa6d63', 'Giros rusos fitball', 25, NULL, 290, 1, 'Intermedio', 'Sentado sobre la fitball o con la espalda apoyada en ella, realiza rotaciones de torso. La inestabilidad aumenta el desafío del core. Puedes sostener peso adicional para mayor intensidad. Mantén el equilibrio durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Russian stability ball twists', 'Sitting on the stability ball or with your back resting on it, perform torso rotations. Instability increases the core challenge. You can hold additional weight for greater intensity. Maintain balance during movement.', 'bodyweight'),
('3b7a9c3a-0ccd-4f45-b30a-3dda6695f413', 'Curl martillo sentado inclinado neutro', 17, 100, 81, 1, 'Principiante', 'Curl martillo en banco a 45 grados. Cue: codos atrás. Error: mover hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Neutral Incline Seated Hammer Curl', 'Bench hammer curl at 45 degrees. Cue: elbows back. Common mistake: move shoulders.', 'external'),
('3b97cd47-c9c2-41b9-99e6-243058adbcf3', 'Press pecho declinado máquina trayectoria', 1, 2, 186, 1, 'Intermedio', 'Press sentado hacia abajo. Cue: retrae escápulas. Error: despegar hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Decline Machine Chest Press', 'Seated decline press on the machine. Cue: keep your shoulder blades retracted. Common mistake: letting your shoulders come off the pad.', 'external'),
('3bafbe8d-c781-44d3-8754-1f282e0c54ee', 'Molino de viento kettlebell', 25, 6, 281, 1, 'Avanzado', 'Con kettlebell extendida sobre la cabeza, realiza una flexión lateral controlada tocando el suelo con la mano libre. Mantén la vista en la kettlebell. Requiere flexibilidad, movilidad y estabilidad del hombro. Excelente para el core y cadenas laterales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Windmill', 'With kettlebell extended overhead, perform a controlled lateral flexion by touching the floor with your free hand. Keep your eyes on the kettlebell. Requires flexibility, mobility and stability of the shoulder. Excellent for the core and side chains.', 'external'),
('3bb65159-bbe7-44a3-9e9c-43c45c33f240', 'Russian Twist con cuerdas de batalla', 25, 6, 256, 1, 'Intermedio', 'Sentado con rodillas flexionadas, mueve los extremos de las cuerdas de batalla de un lado a otro cruzando el abdomen con potencia.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Russian Twist with Battle Ropes', 'Sitting with knees bent, move the ends of the battle ropes from side to side, crossing your abs with power.', 'external'),
('3bd0e4f8-9cef-4c70-b0d3-29fa46b5380a', 'Press hombros cable', 6, 2, 151, 1, 'Intermedio', 'Con poleas bajas a ambos lados o una sola polea, realiza press de hombros. El cable proporciona una resistencia única que desafía la estabilización. Puedes hacerlo sentado o de pie, unilateral o bilateral según tu objetivo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable shoulder press', 'Using low pulleys on both sides or a single pulley, perform shoulder presses. The cable provides a unique resistance that defies stabilization. You can do it sitting or standing, unilateral or bilateral depending on your objective.', 'external'),
('3be4c796-5ca9-4dd1-904b-85ef1f88d36a', 'Zancada inversa Overhead contralateral con Slider y Kettlebell', 28, 6, 281, 1, 'Avanzado', 'Sostén una pesa rusa sobre la cabeza. Desliza hacia atrás la pierna del lado opuesto usando un slider, manteniendo el brazo bloqueado.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse Overhead contralateral stride with Slider and Kettlebell', 'Hold a kettlebell over your head. Slide back the leg on the opposite side using a slider, keeping your arm locked.', 'external'),
('3bf01985-3f13-41ea-a354-60ebe086590d', 'Ring Dead Hang a Front Lever Pull Up', 71, 17, 1, 1, 'Avanzado', 'Cuelgate de las anillas y eleva el cuerpo hasta posicion horizontal (Front Lever) para luego realizar una dominada manteniendo la horizontalidad.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Ring Dead Hang a Front Lever Pull Up', 'Hang from the rings and raise your body to a horizontal position (Front Lever) and then perform a pull-up while maintaining horizontality.', 'mixed'),
('3c13aec4-c2b2-48b0-830f-ad910eea22a8', 'Zancadas frontales', 28, 29, 1, 1, 'Principiante', 'Da un paso amplio hacia adelante y desciende verticalmente flexionando ambas rodillas hasta formar ángulos de 90 grados. La rodilla delantera no debe sobrepasar la punta del pie. Empuja con el talón delantero para volver a la posición inicial. Alterna las piernas o completa todas las repeticiones con una pierna.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Forward Lunges', 'Take a wide step forward and lower straight down by bending both knees until they form 90-degree angles. Your front knee should not travel past your toes. Push through the front heel to return to the starting position. Alternate legs or complete all repetitions on one side.', 'mixed'),
('3c45089e-ff21-42bf-b1e9-085332eef1a2', 'Curl predicador con barra Z', 17, 100, 116, 1, 'Intermedio', 'Brazo apoyado en banco, flexiona la barra Z para proteger muñecas. Objetivo: bíceps braquial. Cue: estira el brazo totalmente abajo. Error común: levantar el codo del apoyo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Z-bar Preacher Curl', 'Arm supported on bench, flex the Z bar to protect wrists. Target: biceps brachii. Cue: stretch your arm all the way down. Common mistake: lifting the elbow off the support.', 'external'),
('3c4734d5-fc14-48fe-b028-387377ee18fd', 'Curl balístico con maza', 17, 100, 81, 1, 'Intermedio', 'Realiza un curl dinámico pasando el peso de la maza de una mano a otra con un movimiento de balanceo controlado para trabajar bíceps y estabilidad.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Ballistic mace curl', 'Perform a dynamic curl by transferring the weight of the club from one hand to the other with a controlled swinging motion to work biceps and stability.', 'external'),
('3ca76d30-76ca-41b6-ba21-c3eb91586981', 'Press francés con barra Z', 2, NULL, 116, 1, 'Intermedio', 'Tumbado, baja la barra hacia la frente flexionando solo codos. Aislamiento tríceps. Codos cerrados. No muevas los brazos desde el hombro.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'French Press with Z Bar', 'Lying down, lower the bar towards your forehead, bending only your elbows. Triceps isolation. Elbows closed. Do not move your arms from the shoulder.', 'external'),
('3d2d5bc0-f3f7-49a3-8038-0aadfffa6c65', 'Rodamiento de pie', 25, NULL, 271, 1, 'Avanzado', 'La progresión más difícil del ab wheel. Desde posición de pie, inclínate y rueda hacia adelante hasta extensión completa, luego vuelve a ponerte de pie. Requiere fuerza de core excepcional y años de progresión. Comienza con rangos parciales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Foot Bearing', 'The most difficult ab wheel progression. From a standing position, bend and roll forward to full extension, then return to standing. It requires exceptional core strength and years of progression. Start with partial ranges.', 'external'),
('3d56857f-3707-4fa4-b227-449a3db2ef0f', 'Monster walks', 29, 37, 61, 1, 'Principiante', 'Coloca una minibanda alrededor de las piernas y camina con pasos controlados manteniendo tensión constante en la banda. Mantén las rodillas alineadas y la cadera estable.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Monster Walks', 'Place a miniband around the legs and walk with controlled steps while keeping constant tension on the band. Keep the knees aligned and the hips stable.', 'external'),
('3d69344f-4335-412e-9112-a231732e8678', 'Kettlebell Goblet Lunge', 28, 29, 281, 1, 'Principiante', 'Sostén la pesa al pecho y realiza zancadas alternas. Estabilidad central. Rodilla delantera alineada. No inclines el torso adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Goblet Lunge', 'Hold the weight at your chest and take alternating strides. Core stability. Front knee aligned. Do not lean your torso forward.', 'external'),
('3d696dad-940a-4356-99b2-b4b8741a5510', 'Extensión cuádriceps máquina', 28, NULL, 186, 1, 'Principiante', 'Sentado en la máquina, extiende las rodillas hasta la extensión completa. Ajusta el respaldo para que las rodillas estén alineadas con el eje de rotación. Controla especialmente la fase excéntrica. Excelente para aislar el cuádriceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Quadriceps extension machine', 'Sitting on the machine, extend your knees to full extension. Adjust the backrest so that your knees are aligned with the axis of rotation. Especially control the eccentric phase. Excellent for isolating the quadriceps.', 'external'),
('3da5d349-4b50-416a-9f9d-3e6d4633b760', 'Press Overhead contralateral medio arrodillado con Kettlebell Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'En posicion de caballero, presiona una Kettlebell invertida con el brazo opuesto a la rodilla adelantada, estabilizando la carga inestable.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Contralateral Half-Kneeling Bottoms-Up Kettlebell Overhead Press', 'In a half-kneeling position, press an inverted kettlebell with the arm opposite the front knee, stabilizing the unstable load.', 'external'),
('3e81b502-802c-407f-a839-2d4bc511aac9', 'Squat Snatch con barra', 28, 29, 116, 1, 'Avanzado', 'Lleva la barra desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, recibiendola en una sentadilla profunda.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Barbell Squat Snatch', 'Bring the bar from the floor to overhead in a single explosive movement, receiving it into a deep squat.', 'external'),
('3eaa6d7f-146a-46b8-b8b1-b93e7cb1d617', 'Gemelo de pie', 64, 309, 186, 1, 'Principiante', 'Realiza una elevación de gemelos de pie. Eleva los talones hasta ponerte de puntillas, mantén una breve contracción arriba y baja de forma controlada.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Standing Calf Raise', 'Perform a standing calf raise. Lift the heels until standing on the toes, briefly hold the contraction at the top, and lower under control.', 'external'),
('3ebe3055-5430-470a-9838-a43f73cac5e3', 'Dominada agarre supino', 16, 71, 116, 1, 'Intermedio', 'Cuelgate de una barra con agarre supino (palmas hacia ti). Tira del cuerpo hacia arriba hasta que la barbilla supere la barra y baja de forma controlada.', FALSE, NULL, '2026-04-03T11:32:12.076534+00:00', 'Chin Up', 'Hang from a bar with a supinated grip (palms facing you). Pull your body up until your chin passes the bar, then lower yourself under control.', 'bodyweight'),
('3edde710-508c-45e8-a93a-02dd12cfc266', 'Círculo exterior alterno con cuerda de batalla', 6, 25, 256, 1, 'Principiante', 'Mueve ambos extremos de la cuerda realizando círculos hacia afuera de forma alterna, manteniendo una base de piernas sólida.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Alternating Outer Circle with Battle Rope', 'Move both ends of the rope in alternating outward circles, maintaining a solid leg base.', 'external'),
('3ee140cb-2ee5-4829-a269-6f11b833986e', 'Battle ropes alternating', 6, 25, 256, 24, 'Principiante', 'Ondas alternadas básicas subiendo y bajando cada brazo. Es el movimiento fundamental con battle ropes. Mantén un ritmo constante y respira regularmente. Comienza con intervalos cortos y progresa gradualmente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Alternating Battle Rope Waves', 'Basic alternating waves raising and lowering each arm. It is the fundamental movement with battle ropes. Maintain a steady rhythm and breathe regularly. Start with short intervals and progress gradually.', 'external'),
('3ee884ef-6204-4870-817f-f9ccb87b585d', 'Press de hombros alterno en Landmine', 6, 2, 116, 1, 'Intermedio', 'Alterna el press vertical de hombro pasando la barra de una mano a otra frente al pecho en cada repeticion sobre la barra Landmine.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Landmine Alternating Shoulder Press', 'Alternate the vertical shoulder press by passing the bar from one hand to the other in front of the chest on each repetition on the Landmine bar.', 'external'),
('3f32da2a-2eae-4d52-b003-dc8764b12c2d', 'Rodamiento con pausa', 25, NULL, 271, 1, 'Avanzado', 'Roll out con pausa de 2-5 segundos en la posición más extendida. Aumenta dramáticamente el tiempo bajo tensión. Mantén respiración controlada durante la pausa. La espalda debe permanecer neutra.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bearing with pause', 'Roll out with a pause of 2-5 seconds in the most extended position. Dramatically increases time under tension. Maintain controlled breathing during the pause. The back should remain neutral.', 'external'),
('3f39fbcc-03dc-4eeb-9917-a7d43323cabb', 'Elevaciones posteriores mancuernas', 6, NULL, 81, 1, 'Principiante', 'Inclínate hacia adelante desde las caderas con las rodillas ligeramente flexionadas. Con los brazos colgando, eleva las mancuernas lateralmente hasta la altura de los hombros. Enfócate en juntar los omóplatos al final del movimiento. Trabaja el deltoides posterior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Posterior Raises', 'Lean forward from the hips with your knees slightly bent. With your arms hanging, raise the dumbbells laterally to shoulder height. Focus on bringing your shoulder blades together at the end of the movement. Work the posterior deltoid.', 'external'),
('3fa391e3-80ea-499a-89dd-d84942b7dc49', 'Extensión tríceps unilateral invertido cable', 2, NULL, 151, 1, 'Intermedio', 'Extensión polea alta palmas arriba. Cue: aísla tríceps. Error: mover hombro.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Unilateral Inverted Cable Triceps Extension', 'Palms up high cable extension. Cue: isolate triceps. Common mistake: move shoulder.', 'external'),
('3fd968fb-4ca8-4b4a-925b-fe4b945bebbf', 'Remo con banda', 16, 17, 61, 1, 'Principiante', 'Ancla la banda frente a ti o pisa el centro. Inclínate ligeramente hacia adelante y tira de los extremos hacia tu abdomen, apretando los omóplatos al final. Mantén los codos cerca del cuerpo durante el movimiento para maximizar la activación de la espalda.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rowing with Band', 'Anchor the band in front of you or step in the center. Lean forward slightly and pull the ends toward your abs, squeezing your shoulder blades together at the end. Keep your elbows close to your body throughout the movement to maximize back activation.', 'external'),
('403ffdfa-7070-452e-8ce9-4beb09e361e2', 'Squat Clean con Kettlebell a una mano', 28, 29, 281, 1, 'Intermedio', 'Lleva la Kettlebell desde el suelo hasta el hombro de forma explosiva y recíbela bajando inmediatamente a una sentadilla profunda antes de ponerte de pie.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Squat Clean with One-Handed kettlebell', 'Bring the kettlebell from the floor to your shoulder explosively and meet it by immediately lowering yourself into a deep squat before standing up.', 'external'),
('407fae2b-7b55-4791-908f-eab611e1737d', 'Push Press alterno con mancuernas', 6, 2, 81, 1, 'Principiante', 'Genera potencia con las piernas para presionar las mancuernas alternativamente sobre la cabeza, manteniendo el ritmo y control del core.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Alternating Dumbbell Push Press', 'Generate power with your legs to press the dumbbells alternately overhead, maintaining rhythm and core control.', 'external'),
('40a6b04b-1078-4037-9341-4e5a4d672976', 'Copenhagen corto', 313, 25, 1, 24, 'Intermedio', 'Realiza una plancha Copenhagen de palanca corta apoyando la rodilla o la parte baja de la pierna sobre un banco. Mantén la cadera elevada y el tronco alineado mientras activas los aductores.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Short Lever Copenhagen Plank', 'Perform a short lever Copenhagen plank with the knee or lower leg supported on a bench. Keep the hips lifted and the trunk aligned while engaging the adductors.', 'bodyweight'),
('40aeb84b-094e-40a5-a963-6d2e8f2ab304', 'Sentadilla Ciclista Overhead con Kettlebell a una mano Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sentadilla ciclista manteniendo una sola Kettlebell invertida sobre la cabeza, desafiando el equilibrio del core y el hombro.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Cycling Overhead Squat with One-Handed kettlebell Bottoms Up', 'Cycle squat holding a single inverted kettlebell overhead, challenging core and shoulder balance.', 'external'),
('40d09188-ef1b-4266-9602-ee179f6771d4', 'Thruster a una mano en Landmine', 28, 6, 116, 1, 'Avanzado', 'Realiza una sentadilla profunda y, al subir, presiona explosivamente la barra Landmine con un solo brazo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Single-Arm Landmine Thruster', 'Perform a deep squat and, as you stand up, press the landmine bar explosively overhead with one arm.', 'external'),
('4101ef04-85b9-4f51-9e4a-9fd8c5b52328', 'Peso muerto rumano con Miniband', 55, 29, 61, 1, 'Principiante', 'Pisa la banda y sujeta los extremos. Inclina el torso hacia adelante empujando la cadera atrás y manteniendo la espalda recta.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Romanian Deadlift with Mini Band', 'Step on the band and hold the ends. Lean your torso forward by pushing your hips back and keeping your back straight.', 'external'),
('411219ed-6ec6-4dcb-87af-ce6ce231f1d2', 'Swing con Kettlebell doble', 29, 55, 281, 1, 'Intermedio', 'Sujeta una Kettlebell en cada mano y balancéalas explosivamente entre las piernas y hasta la altura del pecho usando la cadera.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Swing', 'Hold one kettlebell in each hand and swing them explosively between your legs and up to chest height using your hips.', 'external'),
('4155ac5e-59c9-43ec-bc75-eaa21862138b', 'Spider Curl alterno con mancuernas', 17, NULL, 81, 1, 'Principiante', 'Boca abajo en banco inclinado, realiza el curl de biceps alternando los brazos de forma controlada sin mover los hombros.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Alternating Dumbbell Spider Curl', 'Face down on an inclined bench, perform the biceps curl, alternating your arms in a controlled manner without moving your shoulders.', 'external'),
('4168aeed-6bfb-4a3c-930f-4338b7c027f3', 'Sentadilla Búlgara Overhead con barra', 28, 6, 116, 1, 'Avanzado', 'Realiza una sentadilla split con el pie elevado y la barra bloqueada sobre la cabeza, requiriendo maxima estabilidad y movilidad.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Bulgarian Barbell Overhead Squat', 'Perform a split squat with your foot raised and the bar locked overhead, requiring maximum stability and mobility.', 'external'),
('41816208-ea67-49f5-a60d-ff3b4a45f330', 'Barbell Climb', 25, 17, 116, 1, 'Avanzado', 'Utilizando una barra vertical o simulada, realiza un movimiento de escalada desde el suelo usando la fuerza del core y los brazos para elevar el torso.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Barbell Climb', 'Using a vertical bar or a simulated setup, perform a climbing motion from the floor using your core and arms to raise your torso.', 'external'),
('41ac82e8-83d2-409c-9961-1f6dcb2bdd7f', 'Flexión Atómica en TRX', 1, 25, 216, 1, 'Intermedio', 'Realiza una flexion con los pies en los estribos del TRX y, inmediatamente después, encoge las rodillas hacia el pecho de forma explosiva.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Atomic Bending in TRX', 'Perform a push-up with your feet in the footboards of the TRX and, immediately afterwards, draw your knees towards your chest explosively.', 'mixed'),
('41da9b82-43db-40d0-8e6a-221bfafd6074', 'Remo renegado con Kettlebell doble', 71, 25, 281, 1, 'Intermedio', 'En posicion de plancha sobre dos Kettlebells, rima una pesa hacia tu cadera mientras estabilizas el cuerpo con el otro brazo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Double kettlebell Renegade Row', 'In a plank position on two kettlebells, swing a weight toward your hip while stabilizing your body with the other arm.', 'external'),
('420a265d-6059-4390-8e33-fceefc8510f8', 'Remo sentado máquina', 16, 17, 186, 1, 'Principiante', 'Sentado con el pecho apoyado, tira de los agarres hacia atrás. El soporte del pecho elimina el impulso y protege la espalda baja. Enfócate en juntar los omóplatos al final del movimiento. Varias posiciones de agarre disponibles.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Seated Rowing Machine', 'Sitting with your chest supported, pull your grips back. Chest support eliminates momentum and protects your lower back. Focus on bringing your shoulder blades together at the end of the movement. Various grip positions available.', 'external'),
('421418b6-3e6d-431a-8d6c-41916055234b', 'Back Lever Pullout en anillas', 25, 71, 1, 1, 'Avanzado', 'Desde la posicion horizontal de Back Lever, tira de las anillas para elevar el cuerpo hasta quedar en posicion invertida vertical.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Back Lever Pullout on rings', 'From the horizontal Back Lever position, pull the rings to raise the body until it is in an inverted vertical position.', 'bodyweight'),
('42548bd5-e040-44fb-8703-dfbfe2d35c74', 'Press Overhead agarre inverso con barra', 6, 2, 116, 1, 'Intermedio', 'Sujeta la barra con las palmas hacia ti (supino). Presiona el peso sobre la cabeza manteniendo los codos hacia adelante para un mayor enfoque en el deltoides frontal.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Press Overhead Reverse Barbell Grip', 'Hold the bar with your palms facing you (supine). Press the weight overhead while keeping your elbows forward for greater focus on the front deltoids.', 'external'),
('426d5fe4-c8b3-434b-ac2c-dfc293afc75c', 'Flexiones explosivas a perro boca abajo', 1, 6, 1, 1, 'Avanzado', 'Flexión explosiva que termina saltando a posición de perro boca abajo (V invertida). Combina potencia de empuje con movilidad dinámica. Requiere coordinación y explosividad. Excelente para atletas que necesitan transiciones rápidas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Explosive downward dog push-ups', 'Explosive push-up that ends with jumping to a downward facing dog position (inverted V). Combines pushing power with dynamic mobility. Requires coordination and explosiveness. Excellent for athletes who need quick transitions.', 'mixed'),
('428d58c8-0328-4983-bdb8-8393305ee3d6', 'Zancada cruzada Front Rack con barra', 28, 29, 116, 1, 'Intermedio', 'Con la barra en posicion de rack frontal, realiza una zancada cruzando una pierna por detras de la otra (reverencia), alternando lados.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Front Rack Barbell Curtsy Lunge', 'With the barbell in the front rack position, perform a curtsy lunge by crossing one leg behind the other and alternating sides.', 'external'),
('42baefcf-621c-45bf-8aca-bf7b073e0bfa', 'Salto de potencia con kettlebell', 28, 29, 281, 1, 'Intermedio', 'Sostén la kettlebell con ambas manos y realiza un salto vertical explosivo. Potencia lastrada. Cue: espalda neutra, pecho alto. Error común: redondear hombros por el peso.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Kettlebell Power Jump', 'Hold the kettlebell with both hands and perform an explosive vertical jump. Ballasted power. Cue: neutral back, chest up. Common mistake: rounding shoulders due to weight.', 'external'),
('42bc61c8-95d9-4134-ae7c-91120a98b466', 'Superman isométrico', 71, 29, 1, 24, 'Principiante', 'Eleva pecho y piernas boca abajo. Objetivo: lumbar. Cues: mira al suelo. Error común: tirones de cuello.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Isometric Superman', 'Lift your chest and legs while lying face down and hold the position. Target: lower back. Cue: look at the floor. Common mistake: straining the neck.', 'bodyweight'),
('42f76106-c09e-4fd0-8a22-ce6d127bec50', 'Zancada inversa contralateral con Slider y Kettlebell', 28, 29, 281, 1, 'Avanzado', 'Sostén una pesa rusa en una mano (maleta). Desliza hacia atrás la pierna contraria al brazo que carga el peso (contralateral) en una zancada.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Reverse contralateral stride with Slider and Kettlebell', 'Hold a kettlebell in one hand (suitcase). Slide back the leg away from the weight-bearing arm (contralateral) in one stride.', 'external'),
('43064c22-7b48-4c86-b36e-9a89a7aa8d78', 'Advanced Tuck Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Manten la posicion de back lever con la espalda plana y las rodillas separadas del pecho formando un angulo de 90 grados.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Advanced Tuck Back Lever on rings', 'Maintain the back lever position with your back flat and your knees separated from your chest at a 90-degree angle.', 'bodyweight'),
('430b7250-e263-41e4-8a65-3c56c3ac3eb9', 'Dominadas', 16, 17, 1, 1, 'Intermedio', 'Tira de tu propio cuerpo hacia la barra hasta que la barbilla la pase. Objetivo: fuerza de tracción dorsal. Cue: pecho hacia la barra. Error común: usar balanceo de piernas (kipping) sin control.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Pull-ups', 'Pull your own body toward the bar until your chin passes it. Target: dorsal traction force. Cue: chest towards the bar. Common mistake: using uncontrolled leg swings (kipping).', 'mixed'),
('431d98fa-0838-44fe-8ecd-6f804bb145a5', 'Peso muerto con piernas rígidas', 55, 71, 116, 1, 'Intermedio', 'Con la barra frente a los muslos, baja la carga manteniendo las piernas casi estiradas y la espalda neutra, enfocando el estiramiento en los isquiotibiales.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Stiff-Leg Deadlift', 'With the bar in front of your thighs, lower the load while keeping your legs almost straight and your back neutral, focusing the stretch on the hamstrings.', 'external'),
('432574f9-fa2f-4906-b38a-4766b27c2c44', 'Press de hombros medio arrodillado con mancuernas', 6, 2, 81, 1, 'Intermedio', 'En posicion de caballero, realiza un press de hombros con ambas mancuernas simultaneamente, desafiando la estabilidad de la pelvis.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Half Kneeling Dumbbell Shoulder Press', 'In a half-kneeling position, perform a shoulder press with both dumbbells simultaneously, challenging the stability of the pelvis.', 'external'),
('4335c304-8b9f-4cfe-8cbd-58865bc651a4', 'Rollout de pie en anillas', 25, 6, 1, 1, 'Avanzado', 'Desde posicion de pie, inclinate y extiende los brazos en las anillas hasta que el cuerpo quede paralelo al suelo, volviendo a subir con fuerza abdominal.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Standing ring rollout', 'From a standing position, bend over and extend your arms on the rings until your body is parallel to the floor, rising again with abdominal strength.', 'bodyweight'),
('436612f2-8807-437b-887c-491ba5186333', 'Flexión pliométrica escalonada', 1, 6, 1, 1, 'Avanzado', 'Flexión explosiva cambiando la posición de las manos (una adelantada y otra retrasada) en cada salto. Cue: cambia manos rápido. Error común: perder la alineación del torso.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Stepped Plyometric Push-up', 'Perform an explosive push-up while switching your hand position on each rep, with one hand forward and the other back. Cue: switch quickly. Common mistake: losing torso alignment.', 'mixed'),
('4371cfe0-7dbb-47de-9d15-47690194a165', 'Prensa pies parte inferior', 28, NULL, 186, 1, 'Intermedio', 'Pies abajo en plataforma. Cue: rodillas fuera. Error: talones aire.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Bottom Foot Press', 'Feet down on platform. Cue: knees out. Common mistake: air heels.', 'external'),
('4379c473-2954-4d08-973b-502a0fb070b3', 'TRX Curl de isquiotibiales', 55, 29, 216, 1, 'Avanzado', 'Tumbado, talones en TRX, eleva cadera y flexiona rodillas trayendo pies al glúteo. Objetivo: potencia posterior. Cue: cadera siempre alta. Error común: bajar el glúteo al suelo al flexionar.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'TRX Hamstring Curl', 'Lie down with your heels in the TRX straps, raise your hips, and bend your knees to pull your feet toward your glutes. Target: posterior-chain strength. Cue: keep your hips high. Common mistake: dropping your hips to the floor during the curl.', 'bodyweight'),
('4379dcfb-7a21-4bc4-888d-e6bb9174683a', 'Press Z con Kettlebell doble Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'Realiza el press militar sentado en el suelo sosteniendo dos Kettlebells invertidas, maximizando el trabajo de estabilidad y fuerza.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Z Press with Double kettlebell Bottoms Up', 'Perform the military press seated on the floor holding two inverted kettlebells, maximizing stability and strength work.', 'external'),
('43867f08-fff5-4889-9f25-341ebe212485', 'Arranque un brazo', 6, 29, 81, 1, 'Avanzado', 'Lleva la mancuerna del suelo a overhead en un movimiento explosivo. Versión unilateral del arranque olímpico. Requiere potencia y coordinación. El movimiento debe ser fluido y continuo. Alterna brazos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Arm Snatch', 'Bring the dumbbell from the floor to overhead in an explosive movement. It is the unilateral version of the Olympic snatch. It requires power and coordination. The movement should be fluid and continuous. Alternate arms.', 'external'),
('43882d91-ff34-4eb2-941a-db0c6c5c82be', 'Wall Squat unilateral 90 grados', 28, 29, 1, 24, 'Avanzado', 'Mantén sentadilla pared a un pie. Cue: rodilla a 90. Error: apoyar manos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Single-Leg 90-Degree Wall Squat', 'Hold a single-leg wall squat. Cue: keep your knee at 90 degrees. Common mistake: using your hands for support.', 'mixed'),
('438c474b-ac94-41ef-a855-cb258b1c7477', 'Curl bíceps supinación sentado', 17, NULL, 81, 1, 'Principiante', 'Inicia neutro y gira palma arriba al subir. Cue: máximo giro arriba. Error: balanceo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Seated Supination Biceps Curl', 'Start neutral and turn palm up when going up. Cue: maximum turn up. Common mistake: swinging.', 'external'),
('43a1192e-3132-44cd-a9e8-063c68c5be8f', 'Saltos A (A-Skips)', 29, 64, 1, 1, 'Intermedio', 'Salta rítmicamente elevando una rodilla al pecho y coordinando con el brazo contrario. Enfoque en el contacto rápido del metatarso. Mantén el torso erguido. No dejes caer el talón.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'A-Skips', 'Jump rhythmically, raising one knee toward the chest and coordinating with the opposite arm. Focus on quick metatarsal contact. Keep your torso upright. Don''t drop your heel.', 'bodyweight'),
('43d76e9f-c0f6-4d7d-a4a1-7403a057d1b3', 'Remo inclinado con una sola pierna y dos mancuernas', 71, 17, 81, 1, 'Intermedio', 'Realiza un remo inclinado sosteniendo dos mancuernas mientras te mantienes sobre una sola pierna, desafiando el equilibrio y la cadena posterior.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Double Dumbbell Single Leg Bent Over Row', 'Perform a bent-over row holding two dumbbells while standing on one leg, challenging your balance and posterior chain.', 'external'),
('43e5f5a0-2189-4ac5-8d8e-9b794869ca91', 'Cable Seated Crunch', 25, NULL, 151, 1, 'Principiante', 'Siéntate en un banco o en el suelo frente a la polea alta. Sostén la cuerda detrás del cuello y flexiona la columna hacia abajo contrayendo los abdominales.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Cable Seated Crunch', 'Sit on a bench or on the floor in front of the high cable. Hold the rope behind your neck and flex your spine downward by contracting your abs.', 'external'),
('43f8bf66-0b56-42fc-9ab2-7b50c2c7e2d6', 'Flexión bíceps martillo banda', 17, 100, 61, 1, 'Principiante', 'Pisa la banda y sujeta los extremos con agarre neutro (palmas enfrentadas). Realiza flexiones de codo manteniendo esta posición de las manos. Este agarre enfatiza el braquial y braquiorradial además del bíceps, desarrollando grosor en el brazo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hammer Band Bicep Curl', 'Step on the band and hold the ends with a neutral grip (palms facing each other). Perform elbow curls maintaining this hand position. This grip emphasizes the brachialis and brachioradialis in addition to the biceps, developing thickness in the arm.', 'external'),
('441fda2c-4887-4feb-866e-4b9b54a75ad7', 'Ring Straight Arm L-Sit Straddle Press Handstand', 6, 25, 1, 1, 'Avanzado', 'Desde un L-sit en anillas, abre las piernas en V y presiona con los brazos bloqueados hasta alcanzar la parada de manos vertical.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Ring Straight Arm L-Sit Straddle Press Handstand', 'From a ring L-sit, open your legs in a V and press with locked arms until you reach a vertical handstand.', 'bodyweight'),
('4423fa72-a0f3-4ff8-bb50-a62e2f34d690', 'Curl de bíceps offset con maza', 17, 100, 81, 1, 'Principiante', 'Sujeta la maza con una mano mas cerca del peso que la otra. Realiza el curl controlando la palanca asimétrica para trabajar bíceps y antebrazos.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Mace Offset Biceps Curl', 'Hold the club with one hand closer to the weight than the other. Perform the curl controlling the asymmetrical lever to work biceps and forearms.', 'external'),
('44322b28-4bcc-423e-b090-8753ed30942c', 'Remo al mentón con barra', 6, 71, 116, 1, 'Intermedio', 'Sube la barra pegada al cuerpo hasta el pecho elevando codos. Hombros y espalda alta. Cabeza recta. No des tirones bruscos.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Barbell chin-up row', 'Raise the bar close to your body to your chest, raising your elbows. Shoulders and upper back. Straight head. Don''t give sudden jerks.', 'external'),
('44c11fc1-00e6-43fb-b983-e3fa41ed7c88', 'Lower back máquina', 71, NULL, 186, 1, 'Principiante', 'Extensión de espalda en máquina específica. Fortalece los erectores espinales de forma segura y controlada. Importante para la salud de la espalda baja. Evita hiperextender y mantén el movimiento controlado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lower back machine', 'Back extension on a specific machine. Strengthens the spinal erectors in a safe and controlled way. Important for lower back health. Avoid hyperextending and keep the movement controlled.', 'external'),
('44d2fc47-a0c5-4041-8d3f-7ea3a966a0e3', 'Peso muerto agarre arranque', 55, 71, 116, 1, 'Avanzado', 'Peso muerto con agarre muy amplio como en arranque olímpico. Aumenta el rango de movimiento y la activación de espalda alta. Requiere mayor movilidad. Usa straps si el agarre limita. Excelente para desarrollo de trapecios.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Deadlift grip snatch', 'Deadlift with a very wide grip as in the Olympic snatch. Increases range of motion and upper back activation. Requires greater mobility. Use straps if the grip is limited. Excellent for trapezius development.', 'external'),
('44e235d0-a2e7-4a4d-b136-1909fb66183e', 'Salto en cruz', 64, 25, 1, 1, 'Principiante', 'Salta formando una cruz: centro, adelante, centro, atrás, centro, derecha, centro, izquierda. Agilidad. Cue: pies juntos siempre. Error común: perder la secuencia de saltos.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Cross Jump', 'Jump forming a cross: center, forward, center, back, center, right, center, left. Agility. Cue: feet together always. Common mistake: missing the jump sequence.', 'bodyweight'),
('44e35bc6-6d7b-40ec-b15d-0f92ef3c8044', 'Clean a Press Overhead con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Realiza una cargada con dos Kettlebells al pecho y presionalas simultaneamente sobre la cabeza en un movimiento de potencia.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Clean a Press Overhead with Double Kettlebell', 'Perform a clean with two kettlebells on your chest and press them simultaneously overhead in a power movement.', 'external'),
('44ec3e73-16ca-4baa-9588-1c6dc985e7a4', 'Flexión con pies elevados sobre Kettlebells', 1, 2, 281, 1, 'Intermedio', 'Coloca los pies elevados en un banco y las manos sobre dos Kettlebells. Realiza una flexion profunda aprovechando el espacio extra entre las pesas.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Push-up with Feet Elevated on Kettlebells', 'Place your feet raised on a bench and your hands on two kettlebells. Perform a deep push-up taking advantage of the extra space between the weights.', 'external'),
('44f479a8-b886-4c6a-9259-71ef0eea4f11', 'Caminata de isquiotibiales', 55, 29, 1, 1, 'Principiante', 'Desde la posición de puente de glúteo, camina con los talones hacia adelante hasta estirar casi por completo las piernas y regresa dando pasos cortos.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Hamstring walk', 'From the glute bridge position, walk with your heels forward until your legs are almost completely extended and return taking short steps.', 'mixed'),
('451e120f-4fa1-4706-ab86-0c258d611399', 'Crunch invertido colgado en barra', 25, NULL, 116, 1, 'Avanzado', 'Cuélgate boca abajo de una barra con las rodillas enganchadas (o usando botas de gravedad). Contrae el abdomen para elevar el torso hacia las rodillas.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Bar Hanging Inverted Crunch', 'Hang upside down from a bar with your knees hooked (or wearing gravity boots). Contract your abs to raise your torso toward your knees.', 'external'),
('4559a64f-2746-4ce8-a50d-9090ee9a2cc3', 'Rodamiento rodillas a pie', 25, NULL, 271, 1, 'Avanzado', 'Transición dinámica desde rodillas a posición de pie durante el roll out. Comienza desde rodillas, extiende completamente, luego lleva los pies hacia la rueda para terminar de pie. Progresión hacia roll out completo de pie.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rolling knees to foot', 'Dynamic transition from knees to standing position during the roll out. Start from your knees, extend fully, then bring your feet toward the wheel to finish standing. Progression to full standing roll out.', 'external'),
('455a8548-412a-4889-8338-cc46a7ea1d66', 'Press Arnold sentado', 6, 2, 81, 1, 'Intermedio', 'Sentado con mancuernas frente a los hombros y palmas hacia ti. Rota las muñecas mientras empujas hacia arriba hasta que las palmas miren al frente. Objetivo: deltoides completo. Cue: movimiento fluido sin tirones. Error: arquear la espalda baja excesivamente.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Seated Arnold Press', 'Sitting with dumbbells in front of your shoulders and palms facing you. Rotate your wrists as you push up until your palms are facing forward. Target: full deltoid. Cue: fluid movement without jerks. Common mistake: arching the lower back excessively.', 'external'),
('459d0f70-f2b0-48c5-9d91-ee6ad244d3b5', 'L-Sit en paralelas', 25, 28, 1, 24, 'Avanzado', 'Apoyado en barras paralelas, mantén las piernas estiradas al frente formando una L. Objetivo: fuerza de core y estabilidad de hombros. Cues: hombros abajo y lejos de orejas. Error común: encoger el pecho y doblar rodillas.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'L-sit in Parallel', 'Supported by parallel bars, keep your legs stretched in front forming an L. Target: core strength and shoulder stability. Cue: shoulders down and away from ears. Common mistake: shrinking your chest and bending the knees.', 'bodyweight'),
('45a14af9-f213-453e-b909-e5e1bd51b5c4', 'Puente de glúteo estricto', 29, 55, 1, 1, 'Principiante', 'Eleva cadera con pies en suelo. Cue: talones cerca del glúteo. Error: apoyar solo la parte alta de la espalda.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Strict Glute Bridge', 'Raise hips with feet on the ground. Cue: heels close to the glute. Common mistake: supporting only the upper part of the back.', 'mixed'),
('45fdbaa6-4379-4da5-a4ef-3086887b8323', 'Step Up Overhead ipsilateral con Kettlebell a una mano', 28, 6, 281, 1, 'Avanzado', 'Mantén una Kettlebell en alto sobre la cabeza y sube al banco con la pierna del mismo lado, desafiando el equilibrio del core.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Ipsilateral Single-Kettlebell Overhead Step-up', 'Hold one kettlebell overhead and step onto the bench with the leg on the same side, challenging your balance and shoulder stability.', 'external'),
('4621886f-e93a-4c1d-9edd-d8ad869e7f61', 'Press de banca agarre cerrado con barra', 2, 1, 116, 1, 'Intermedio', 'Acuéstate en el banco y agarra la barra con las manos a la anchura de los hombros. Baja la barra al pecho manteniendo los codos pegados al torso.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Close grip bench press with barbell', 'Lie on the bench and grab the bar with your hands shoulder-width apart. Lower the bar to your chest, keeping your elbows close to your torso.', 'external'),
('46227deb-5fa5-493c-8a90-3f99f25ff7fc', 'Press frontal alterno', 6, 2, 81, 1, 'Intermedio', 'Realiza un press frontal alterno con mancuernas. Empuja una mancuerna por encima de la cabeza mientras la otra se mantiene estable, alternando ambos brazos.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Alternating Dumbbell Shoulder Press', 'Perform an alternating dumbbell shoulder press. Press one dumbbell overhead while the other remains stable, alternating arms each repetition.', 'external'),
('4649d14a-9e9f-4cab-b0b2-dac9e36abb6a', 'TRX Press de tríceps', 2, 25, 216, 1, 'Intermedio', 'De espaldas al anclaje, brazos estirados frente a la frente. Flexiona codos bajando el cuerpo y extiende. Codos cerrados. No arquees la espalda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Triceps Press', 'Face away from the anchor with your arms extended in front of your forehead. Bend your elbows to lower your body, then extend back up. Keep your elbows tucked in and avoid arching your back.', 'bodyweight'),
('46e5a2ca-c3cb-458f-9884-55c7ffc44b09', 'Sentadilla Búlgara contralateral Maleta con Kettlebell a una mano', 28, 29, 281, 1, 'Intermedio', 'Realiza la sentadilla split con el pie elevado sosteniendo la Kettlebell en un lateral con el brazo opuesto a la pierna de apoyo.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Contralateral Single-Arm Suitcase Bulgarian Split Squat with Kettlebell', 'Perform the split squat with your foot raised, holding the kettlebell at your side with the arm opposite the supporting leg.', 'external'),
('470ef360-6cfd-48f4-a80c-e2203009e069', 'Extensiones fitball lumbares', 71, 29, 290, 1, 'Principiante', 'Eleva torso con abdomen en bola. Objetivo: erectores. Cue: mira suelo. Error: hiperextender.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Lumbar Stability Ball Extensions', 'Raises torso with balled abs. Target: estraightrs. Cue: look at ground. Common mistake: hyperextend.', 'bodyweight'),
('471df754-7d97-4fb1-ba54-303c1199ea37', 'Remo inclinado a una pierna contralateral con mancuerna', 71, 17, 81, 1, 'Intermedio', 'Manten el equilibrio sobre una pierna mientras remas con el brazo del lado opuesto, fortaleciendo la espalda y la estabilidad cruzada del core.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Single-Leg Contralateral Dumbbell Bent-Over Row', 'Balance on one leg while rowing with the opposite arm, strengthening your back and cross-core stability.', 'external'),
('4729b2f3-444b-43a3-9da8-6a2019e1a435', 'Face Pull con polea', 6, 71, 151, 1, 'Principiante', 'Tira de la cuerda hacia la cara abriendo codos. Cue: pulgares atrás. Error: adelantar cuello.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Face Pull with Cable', 'Pull the rope towards your face by opening your elbows. Cue: thumbs back. Common mistake: forward neck.', 'external'),
('4743c985-491f-4242-9ea1-9fa920a0dde4', 'Caminata camarero', 6, 25, 81, 1, 'Avanzado', 'Camina con mancuerna sostenida overhead con un brazo como camarero con bandeja. Requiere estabilidad de hombro y core excepcionales. Mantén el brazo completamente vertical. Alterna brazos. Excelente para salud del hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Waiter walk', 'Walk with dumbbell held overhead with one arm like a waiter with a tray. Requires exceptional shoulder and core stability. Keep your arm completely vertical. Alternate arms. Excellent for shoulder health.', 'external'),
('47521034-2fda-478d-9276-4ff45e37ab05', 'Remo Seal con barra', 71, 16, 116, 1, 'Avanzado', 'Rema tumbado boca abajo en banco elevado. Objetivo: espalda aislada. Cue: sin impulso. Error: tirones cuello.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seal Barbell Row', 'Row while lying face down on a raised bench. Target: isolated back. Cue: no momentum. Common mistake: neck pulling.', 'external'),
('475f9ba5-f3b0-4450-a921-d27a1ab6e3c2', 'Jalón al pecho agarre ancho', 16, 17, 186, 1, 'Principiante', 'Tira de la barra hacia la parte superior del pecho. Cue: imagina que tiras de los codos hacia abajo. Error: balancear el cuerpo hacia atrás.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Wide Grip Chest Pull', 'Pull the bar toward your upper chest. Cue: imagine pulling your elbows down. Common mistake: swinging the body backwards.', 'external'),
('4761197e-6e4d-49df-b0dc-6e1a194016c5', 'Swing kettlebell', 29, 55, 281, 1, 'Intermedio', 'Balancea la kettlebell entre las piernas y elévala hasta la altura de los hombros con un movimiento explosivo de caderas. El impulso debe venir de las caderas, no de los brazos. Mantén la espalda recta y el core activado. Fundamento del entrenamiento con kettlebell.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Swing', 'Swing the kettlebell between your legs and raise it to shoulder height with an explosive hip drive. The power should come from your hips, not your arms. Keep your back straight and your core engaged. This is a fundamental kettlebell exercise.', 'external'),
('476cb441-47d8-446c-a63d-576f38d895c3', 'Flexión con alcance de rodillas sobre Slider', 1, 2, 1, 1, 'Intermedio', 'De rodillas, realiza una flexion mientras deslizas una mano hacia adelante sobre un slider, alternando brazos para desafiar el core.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Kneeling Reach Pushup on Slider', 'From your knees, perform a push-up while sliding one hand forward on a slider, alternating arms to challenge your core.', 'bodyweight'),
('48013afa-f182-4913-8c89-c4e83cc01651', 'Rollout de rodillas en anillas a una mano', 25, 6, 1, 1, 'Avanzado', 'Variante extrema del rollout utilizando solo un brazo para estabilizar y desplazar la anilla, minimizando la ayuda del core lateral.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'One-Handed Ring Knee Rollout', 'Extreme variant of the rollout using only one arm to stabilize and move the ring, minimizing the help of the lateral core.', 'bodyweight'),
('4803f93c-ba58-4973-856b-b27bbeead329', 'Chest Roll a Straight Body Press Handstand', 6, 2, 1, 1, 'Avanzado', 'Rueda sobre el pecho desde el suelo y utiliza la inercia y fuerza para presionar el cuerpo recto hasta la parada de manos vertical.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Chest Roll to Straight Body Press Handstand', 'Roll on your chest from the floor and use inertia and strength to press your body straight into a vertical handstand.', 'bodyweight'),
('4823caec-0bb1-42c5-817f-778c73e0e5d6', 'Battle ropes waves', 6, 25, 256, 24, 'Intermedio', 'Crea ondas alternadas o simultáneas con las cuerdas. Mantén una posición atlética con rodillas ligeramente flexionadas. El movimiento debe venir de los hombros, no de los brazos. Mantén el core activado para estabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Waves', 'Create alternating or simultaneous waves with the ropes. Maintain an athletic position with your knees slightly bent. The movement should come from the shoulders, not the arms. Keep your core engaged for stability.', 'external'),
('484d29bf-7a0f-48a7-8c3e-cb0d87f9a682', 'Press de banca declinado Seesaw con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Desde una posición declinada, alterna el press de Kettlebells invertidas, trabajando la parte inferior del pecho y la estabilidad del manguito rotador.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Seesaw Decline Bench Press with Double kettlebell Bottoms Up', 'From a decline position, alternate the inverted kettlebell press, working the lower chest and rotator cuff stability.', 'external'),
('48546596-4f0e-4403-a12e-880771367b0c', 'Hollow body hold estático', 25, NULL, 1, 24, 'Avanzado', 'Mantén piernas y hombros elevados del suelo formando una curva con el cuerpo. Objetivo: fuerza isométrica del core. Cue: aprieta glúteos y abdomen. Error común: arquear la espalda lumbar durante la espera.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Static Hollow Body Hold', 'Keep your legs and shoulders raised off the ground, forming a curve with your body. Target: isometric core strength. Cue: tighten glutes and abs. Common mistake: arching the lower back while waiting.', 'bodyweight'),
('4876ac82-cfbb-4eff-8aeb-64834c14db60', 'Círculos laterales de brazos con Indian Club doble', 6, 100, 81, 1, 'Principiante', 'Realiza movimientos circulares laterales controlados con ambos Indian Clubs para mejorar la movilidad y la salud articular del hombro.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Side Arm Circles with Double Indian Club', 'Perform controlled lateral circular movements with both Indian Clubs to improve shoulder mobility and joint health.', 'external'),
('4884c799-7d50-4cec-a9e7-ffa43f4bef3e', 'Sentadilla Ciclista Front Rack con barra', 28, 29, 116, 1, 'Intermedio', 'Eleva los talones y realiza una sentadilla con la barra en posición de rack frontal, enfocando el estímulo en los cuádriceps debido a la verticalidad.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Barbell Front Rack Cycling Squat', 'Raise your heels and perform a squat with the bar in a front rack position, focusing the stimulus on the quadriceps due to the verticality.', 'external'),
('48afdddd-11cc-4e56-b0b2-bbf2c140d503', 'Full Planche', 25, 6, 1, 24, 'Avanzado', 'Sostén el cuerpo estirado y horizontal paralelo al suelo apoyado solo en las manos con codos bloqueados y core en maxima tension.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Full Planche', 'Hold your body stretched and horizontal, parallel to the floor, supported only by your hands with your elbows locked and your core at maximum tension.', 'bodyweight'),
('48bd90e9-9981-4240-938e-03183b2a0190', 'Sentadilla Overhead con Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Baja en sentadilla profunda manteniendo dos Kettlebells bloqueadas sobre la cabeza, lo que requiere movilidad extrema y estabilidad escapular.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Double kettlebell Overhead Squat', 'Lower yourself into a deep squat while keeping two kettlebells locked overhead, requiring extreme mobility and scapular stability.', 'external'),
('48ff20ba-8069-4fe1-a983-b16d720fe3ee', 'Zancada frontal corporal', 28, 29, 1, 1, 'Principiante', 'Da un paso al frente bajando la cadera y empuja para volver. Objetivo: potencia de piernas. Cue: mantén el torso erguido. Error común: permitir que el talón delantero se levante del suelo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Bodyweight Forward Lunge', 'Step forward, lower your hips, and push back to the starting position. Target: leg power. Cue: keep your torso upright. Common mistake: letting the front heel lift off the floor.', 'mixed'),
('49074aef-3fad-410a-a30e-307f278fa0eb', 'Press de hombros con barra medio arrodillado', 6, 2, 116, 1, 'Intermedio', 'En posición de caballero con una rodilla en el suelo, presiona la barra sobre la cabeza manteniendo el torso vertical y el abdomen contraído para estabilizar el movimiento.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Half Kneeling Barbell Shoulder Press', 'In a half-kneeling position with one knee on the ground, press the bar overhead, keeping your torso vertical and your abs contracted to stabilize the movement.', 'external'),
('49080d43-523c-4d2c-8967-6b407e0c365a', 'Pallof press anti-rotación', 25, 13, 151, 1, 'Intermedio', 'Empuje anti-rotacional para core, resistiendo la torsión del cable y manteniendo pelvis y costillas estables.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Pallof press anti-rotation', 'Anti-rotational thrust for core, resisting cable twisting and keeping pelvis and ribs stable.', 'external'),
('499126a6-994b-43cd-89a3-b1fcbbe047d2', 'Remo prono con Kettlebell doble', 71, 17, 281, 1, 'Principiante', 'Tumbado boca abajo en un banco elevado, rema ambas pesas rusas hacia los costados apretando las escápulas y manteniendo los codos cerca del torso.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double kettlebell Prone Row', 'Lying face down on a raised bench, row both kettlebells to your sides by squeezing your shoulder blades and keeping your elbows close to your torso.', 'external'),
('49d25cd8-9777-4acf-aa20-9a7c05e40018', 'Stability Ball Dead Bug', 25, NULL, 290, 1, 'Principiante', 'Acuéstate boca arriba sosteniendo un Fitball entre las manos y las rodillas. Extiende el brazo y la pierna opuestos hacia el suelo mientras mantienes la presión sobre el balón con las extremidades restantes. Regresa a la posición inicial y alterna.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball Dead Bug', 'Lie on your back holding a stability ball between your hands and knees. Extend your opposite arm and leg toward the ground while maintaining pressure on the ball with your remaining limbs. Return to the starting position and alternate.', 'bodyweight'),
('49d933df-9925-4995-83a3-1982d262851b', 'Plancha lateral con Hip Dips', 25, 6, 1, 1, 'Intermedio', 'En plancha lateral, baja la cadera al suelo y elévala de nuevo. Objetivo: fuerza de los oblicuos. Cue: mantén el hombro estable y alineado. Error común: rotar el tronco hacia adelante.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Side Plank with Hip Dips', 'In a side plank, lower your hip toward the floor and raise it again. Target: oblique strength. Cue: keep your shoulder stable and aligned. Common mistake: rotating your torso forward.', 'mixed'),
('49e1ceb5-e2f8-4437-be84-fa2bf559a365', 'Press de hombros unilateral con mancuerna', 6, 25, 81, 1, 'Intermedio', 'Empuja una sola mancuerna sobre la cabeza mientras el otro brazo está libre o estabilizando. Objetivo: fuerza de hombros y estabilidad del core. Cue: no permitas que el cuerpo se incline lateralmente. Error: bloquear el codo bruscamente.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Unilateral Dumbbell Shoulder Press', 'Push a single dumbbell overhead while the other arm is free or stabilizing. Target: shoulder strength and core stability. Cue: don''t allow the body to lean sideways. Common mistake: blocking the elbow abruptly.', 'external'),
('4a045fcc-6090-498b-b9de-1e6d1ef94f0b', 'Press pecho cable', 1, 2, 151, 1, 'Principiante', 'De pie entre dos poleas ajustadas a la altura del pecho, empuja los agarres hacia adelante hasta que se junten frente al pecho. Mantén una ligera inclinación hacia adelante y los codos ligeramente flexionados. Proporciona tensión constante en los pectorales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Chest Press', 'Standing between two pulleys set at chest height, push the grips forward until they meet in front of your chest. Maintain a slight lean forward and your elbows slightly bent. Provides constant tension on the pectorals.', 'external'),
('4a2068a4-dbcf-46b5-af41-e161a27b8319', 'Slam de balón con salto', 13, 25, 240, 1, 'Avanzado', 'Realiza un salto vertical máximo y golpea el balón contra el suelo justo al aterrizar. Potencia total sincronizada. Cue: máxima altura de salto. Error común: descoordinación entre aterrizaje y golpe.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Jump Ball Slam', 'Perform a maximum vertical jump and hit the ball on the ground just as it lands. Synchronized total power. Cue: maximum jump height. Common mistake: lack of coordination between landing and hitting.', 'external'),
('4a27f194-2219-42ef-afb4-7fbd7939558a', 'Salto al cajón con rotación', 13, 29, 1, 1, 'Avanzado', 'Salta a un cajón girando 90 o 180 grados en el aire. Mejora la agilidad y el control del aterrizaje. Cue: brazos coordinados con el giro. Error común: aterrizar ruidosamente sobre el cajón.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Box Jump with Rotation', 'Jump onto a box turning 90 or 180 degrees in the air. Improves agility and landing control. Cue: arms coordinated with the turn. Common mistake: landing loudly on the box.', 'bodyweight'),
('4a4d6b0c-6c39-4339-914b-d803b5028117', 'Press Cubano en TRX', 6, 71, 216, 1, 'Intermedio', 'En TRX: remo alto, rotación externa de hombros hasta manos arriba, y press overhead manteniendo tensión en las correas.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Cuban Press on TRX', 'In TRX: high row, external rotation of the shoulders to hands up, and overhead press maintaining tension in the straps.', 'bodyweight'),
('4a53cd78-a559-4ba1-8fa5-e7a8b2d3525c', 'Lanzamiento rotacional una pierna', 25, 29, 240, 1, 'Avanzado', 'Lanzamiento lateral de balón medicinal manteniendo el equilibrio sobre una sola pierna. Cue: fija la cadera. Error común: rotar solo con los brazos por inestabilidad.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'One Leg Rotational Throw', 'Lateral medicine ball throw while balancing on one leg. Cue: fix the hip. Common mistake: rotating only with your arms due to instability.', 'external'),
('4a88eef3-bad0-4461-8b89-20f6be037b86', 'Salto vertical 360 grados', 13, 25, 1, 1, 'Avanzado', 'Salta verticalmente y realiza un giro completo en el aire antes de aterrizar estable. Coordinación espacial extrema. Cue: inicia el giro con los brazos. Error común: perder el equilibrio al aterrizar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', '360 Degree Vertical Jump', 'Jump vertically and perform a complete spin in the air before landing stable. Extreme spatial coordination. Cue: start the twist with your arms. Common mistake: losing balance when landing.', 'bodyweight'),
('4b080ebd-d7f7-4fd0-b8bc-fda0fc25517d', 'Elevaciones laterales cable', 6, NULL, 151, 1, 'Principiante', 'Con polea baja, realiza elevaciones laterales con el cable cruzando por delante o detrás del cuerpo. La resistencia constante del cable mantiene tensión en el deltoides medio durante todo el movimiento. Controla especialmente la fase excéntrica.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Lateral Raises', 'With a low cable, perform lateral raises with the cable crossing in front or behind the body. The constant resistance of the cable maintains tension on the middle deltoid throughout the movement. Especially control the eccentric phase.', 'external'),
('4b235a22-99a7-45d4-8980-178b2c677c62', 'Pull Up excéntrico en barra', 71, 17, 1, 1, 'Principiante', 'Salta a la posición alta de la dominada prono y controla el descenso bajando lo más lento posible para ganar fuerza de tracción.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Eccentric Pull Up on bar', 'Jump to the high position of the prone pull-up and control the descent by going down as slowly as possible to gain pulling power.', 'mixed'),
('4b3f6afa-1e1e-4595-9938-234f88a36567', 'Sentadilla con barra frontal', 28, 25, 116, 1, 'Avanzado', 'Apoya la barra sobre tus deltoides frontales y baja en sentadilla manteniendo el torso vertical. Objetivo: énfasis en cuádriceps y estabilidad del core. Cues: codos siempre altos y paralelos al suelo. Error común: dejar que los codos caigan, haciendo que la barra ruede hacia adelante.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Front Bar Squat', 'Rest the bar on your front deltoids and lower yourself into a squat, keeping your torso vertical. Target: emphasis on quadriceps and core stability. Cue: elbows always high and parallel toward the floor. Common mistake: letting the elbows drop, causing the bar to roll forward.', 'external'),
('4b6c17ff-95a3-44eb-b293-ede1fca4aec1', 'Pike en TRX', 25, 6, 216, 1, 'Intermedio', 'Con los pies en los estribos del TRX y las manos en el suelo, eleva la cadera hacia el techo manteniendo las piernas rectas para formar una V invertida.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'TRX Pike', 'With your feet in the TRX straps and your hands on the floor, lift your hips toward the ceiling while keeping your legs straight and your core tight. Return slowly to the plank position.', 'bodyweight'),
('4b6c7a98-1748-4d0c-a3f0-d89347f73d85', 'Remo Landmine unilateral barra', 16, 17, 116, 1, 'Intermedio', 'Rema a un brazo en barra anclada. Objetivo: dorsal. Cue: espalda plana. Error: rotar torso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Landmine Unilateral Bar Row', 'One arm row on anchored bar. Target: dorsal. Cue: flat back. Common mistake: rotate torso.', 'external'),
('4b945881-9c22-4917-9ae6-a03b3ebab51d', 'Sentadilla Búlgara ipsilateral Front Rack con Kettlebell Bottoms Up', 28, 29, 281, 1, 'Intermedio', 'Con un pie elevado, sujeta la Kettlebell invertida en el hombro del mismo lado que la pierna delantera, exigiendo maxima estabilidad unilateral.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ipsilateral Front Rack Bottoms-Up Bulgarian Split Squat with Kettlebell', 'With one foot raised, hold the inverted kettlebell on the shoulder on the same side as the front leg, demanding maximum unilateral stability.', 'external'),
('4b9d3b67-5c45-48c8-98e3-d8b9ccb8647c', 'Press inclinado con mancuernas', 1, 2, 81, 1, 'Intermedio', 'Press inclinado con mancuernas para pectoral superior, priorizando rango y estabilidad con control de muñecas y escápulas.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Incline Dumbbell Press', 'Incline dumbbell press for upper pectoral, prioritizing range and stability with control of the wrists and scapulae.', 'external'),
('4ba76616-1df9-41ca-a9c3-ac00b1009be5', 'Fondos en paralelas', 2, 1, 1, 1, 'Intermedio', 'Sujétate en barras paralelas con los brazos extendidos y el cuerpo vertical. Desciende flexionando los codos hasta que los hombros estén al nivel o ligeramente por debajo de los codos. Empuja con fuerza para volver arriba. Inclínate ligeramente hacia adelante para mayor énfasis en pectorales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Parallel funds', 'Hold on to parallel bars with your arms extended and your body vertical. Lower yourself by bending your elbows until your shoulders are level with or slightly below your elbows. Push hard to get back up. Lean forward slightly for greater emphasis on your pectorals.', 'bodyweight'),
('4bd0491c-56e7-4ea7-980a-176808548aeb', 'Zancada inversa Goblet con mancuerna y Slider', 28, 29, 81, 1, 'Intermedio', 'Sostén una mancuerna en posición de copa y desliza un pie hacia atrás en un slider bajando en zancada, manteniendo el torso vertical.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Goblet reverse stride with dumbbell and slider', 'Hold a dumbbell in a cup position and slide one foot back on a slider while striding down, keeping your torso vertical.', 'external'),
('4bdb4129-fc4a-4c52-857d-cda1ea02f781', 'Flexión (Push Up)', 1, 2, 1, 1, 'Principiante', 'En posicion de plancha, baja el pecho hacia el suelo flexionando los codos y vuelve a la posicion inicial extendiéndolos por completo.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Push-Up', 'In a plank position, lower your chest toward the floor by bending your elbows and return to the starting position by fully extending them.', 'mixed'),
('4c48f2cc-cd30-4c7e-8395-46716414b3b0', 'Salto de valla a una pierna lateral', 29, 64, 1, 1, 'Avanzado', 'Salta una valla lateralmente apoyándote y aterrizando con la misma pierna. Estabilidad unilateral crítica. Cue: mantén la rodilla alineada con el segundo dedo del pie. Error común: tambaleo excesivo al aterrizar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side-leg Hurdle Jump', 'Jump over a fence laterally, supporting yourself and landing on the same leg. Critical unilateral stability. Cue: keep your knee in line with your second toe. Common mistake: excessive wobble when landing.', 'bodyweight'),
('4c566809-f819-4c13-88d3-600f428ca8db', 'Thruster alterno con Kettlebell doble', 28, 6, 281, 1, 'Intermedio', 'Realiza una sentadilla y alterna el brazo que realiza el press vertical al subir, manteniendo la otra pesa estable en posicion rack.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Alternating Double Kettlebell Thruster', 'Perform a squat and alternate the arm that presses overhead as you stand up, keeping the other kettlebell stable in the rack position.', 'external'),
('4c58602c-e0f5-48d7-9e4c-d16266a3d40b', 'Turkish Sit Up a Press Z con Kettlebell doble', 25, 6, 281, 1, 'Avanzado', 'Ejecuta un Turkish Sit Up con dos Kettlebells y, una vez sentado, realiza un Press Z sobre la cabeza manteniendo el torso vertical.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Turkish Sit-Up to Z Press', 'Perform a Turkish sit-up with two kettlebells and, once seated, perform a Z press overhead while keeping your torso upright.', 'external'),
('4c5c6719-7fc7-4d59-a1dc-facea2f6d449', 'Rueda abdominal', 25, 13, 271, 1, 'Avanzado', 'Realiza un rollout con rueda abdominal. Desde rodillas o de pie, desplaza la rueda hacia delante manteniendo el abdomen activo y vuelve sin perder la posición lumbar.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Ab Wheel Rollout', 'Perform an ab wheel rollout. From the knees or standing, roll the wheel forward while keeping the core engaged and return without losing lower-back position.', 'external'),
('4c663c7f-48ac-4bb5-875a-b7967fd728eb', 'Devil Press con mancuernas', 13, 6, 81, 1, 'Avanzado', 'Realiza un Burpee con las manos sobre mancuernas. Al subir, usa el impulso de la cadera para llevar ambas pesas sobre la cabeza (swing/snatch).', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Dumbbell Devil Press', 'Perform a Burpee with your hands on dumbbells. When going up, use hip momentum to bring both weights overhead (swing/snatch).', 'external'),
('4c850905-e896-4640-941c-672185f17398', 'Escaladores sobre balón medicinal', 25, 6, 240, 1, 'Intermedio', 'Manos sobre el balón, realiza el movimiento de escalador. Desafío de estabilidad. Core firme. No dejes que el balón ruede lejos.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Climbers on Medicine Ball', 'Hands on the ball, perform the climber movement. Stability challenge. Firm core. Don''t let the ball roll away.', 'external'),
('4cbbab21-5699-4fb9-ac58-05efda2824d6', 'Remo alto en polea con cuerda (Face Pull)', 6, 71, 151, 1, 'Principiante', 'Tira de la cuerda hacia tu frente separando los extremos y llevando los pulgares hacia atrás. Objetivo: salud de hombro. Cue: abre los codos hacia los lados. Error: adelantar el cuello al tirar.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'High Rope Pulley Row (face Pull)', 'Pull the rope towards your forehead by separating the ends and bringing your thumbs back. Target: shoulder health. Cue: spread your elbows out to the sides. Common mistake: bringing the neck forward when pulling.', 'external'),
('4ccb1e9f-8877-4f3a-a24a-37f315c1d634', 'Step Up Overhead ipsilateral con Kettlebell a una mano Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Mantén una Kettlebell invertida bloqueada arriba y sube al banco con la pierna del mismo lado, desafiando el equilibrio asimétrico.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Ipsilateral Single-Kettlebell Bottoms-Up Overhead Step-up', 'Hold an upside-down kettlebell overhead and step onto the bench with the leg on the same side, challenging your balance and upper-body stability.', 'external'),
('4ce3fdcf-b651-4462-a8d1-047faad7c7e9', 'Outside Half Snatch con Kettlebell doble', 29, 6, 281, 1, 'Intermedio', 'Lleva dos pesas por fuera de las piernas hasta por encima de la cabeza y bajalas a la posicion rack antes del siguiente balanceo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Outside Half Snatch with Double Kettlebell', 'Bring two dumbbells outside your legs to above your head and lower them to the rack position before the next swing.', 'external'),
('4cef48e5-85af-4cbc-9872-45b007a082aa', 'Press Overhead Seesaw arrodillado con mancuernas', 6, 2, 81, 1, 'Intermedio', 'De rodillas sobre ambas piernas, presiona las mancuernas alternativamente sobre la cabeza en un movimiento fluido y constante.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Kneeling Dumbbell Overhead Seesaw Press', 'Kneeling on both legs, press the dumbbells alternately overhead in a fluid, steady motion.', 'external'),
('4cfadf8f-87ea-48b0-b3f7-50f4c3c2d0d7', 'Sentadilla Sissy con mancuerna', 28, NULL, 81, 1, 'Avanzado', 'Inclínate hacia atrás flexionando rodillas mientras mantienes la cadera extendida. Objetivo: aislamiento de cuádriceps. Cue: cuerpo recto de hombro a rodilla. Error común: flexionar la cadera al bajar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Dumbbell Sissy Squat', 'Lean back by bending your knees while keeping your hips extended. Target: quadriceps isolation. Cue: body straight from shoulder to knee. Common mistake: flexing the hips when lowering.', 'external'),
('4d15872d-f06a-4901-84a9-e4b06a529a61', 'Salto de rana con despegue rápido', 29, 28, 1, 1, 'Intermedio', 'Desde sentadilla, realiza un salto corto y sal inmediatamente hacia el siguiente. Mínimo tiempo en suelo. Talones apoyados al caer. No redondees la espalda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Frog jump with fast takeoff', 'From a squat, perform a short jump and immediately jump to the next one. Minimal time on the ground. Heels supported when landing. Don''t round your back.', 'mixed'),
('4d4848b3-7d25-4c8a-91c0-5e721fcb4f17', 'Halo alterno de rodillas (Half Kneeling) con Kettlebell', 6, 25, 281, 1, 'Principiante', 'En posición de caballero, realiza halos alrededor de la cabeza con la pesa rusa, resistiendo el movimiento del torso.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternating Kneeling Halo (half Kneeling) with Kettlebell', 'In a knight''s position, make halos around your head with the kettlebell, resisting the movement of your torso.', 'external'),
('4dd67613-3345-4562-b527-c8f0f649f064', 'Sentadilla Split Búlgara', 28, 29, 1, 1, 'Principiante', 'Apoya un pie atras en un banco y realiza una sentadilla profunda con la pierna delantera, manteniendo el torso erguido.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Bulgarian Split Squat', 'Place one foot back on a bench and perform a deep squat with your front leg, keeping your torso upright.', 'mixed'),
('4dd976c2-3cfb-46cb-aa32-dbd56c09f3ce', 'Dips en banco para tríceps', 2, 1, 1, 1, 'Principiante', 'Manos en borde de banco, baja la cadera flexionando codos. Cue: espalda pegada al banco. Error: alejar demasiado el cuerpo del banco.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Bench Dips for Triceps', 'Hands on the edge of the bench, lower your hips by bending your elbows. Cue: back pressed to the bench. Common mistake: moving your body too far from the bench.', 'mixed'),
('4dd9c263-582a-4114-9beb-8bdd6f39df45', 'Monster walk con banda', 29, 37, 61, 1, 'Principiante', 'Con la banda alrededor de los tobillos, adopta una posición de cuarto de sentadilla. Camina hacia adelante dando pasos amplios en diagonal, manteniendo la tensión constante. El movimiento debe parecer el caminar de un monstruo. Mantén el torso erguido y las rodillas alineadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Monster walk with band', 'With the band around your ankles, assume a quarter squat position. Walk forward taking wide diagonal steps, maintaining constant tension. The movement should look like the walk of a monster. Keep your torso upright and your knees aligned.', 'external'),
('4dda3874-db65-443a-a5d4-66711024287b', 'Salto de longitud lateral', 29, 37, 1, 1, 'Intermedio', 'Salta de lado lo más lejos posible aterrizando con ambos pies. Potencia lateral explosiva. Cue: usa los brazos para el impulso lateral. Error común: aterrizar con las rodillas juntas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Long Jump', 'Jump sideways as far as possible landing on both feet. Explosive lateral power. Cue: use your arms for lateral momentum. Common mistake: landing with your knees together.', 'bodyweight'),
('4ded2a0a-3e93-428c-89f2-06ca70bb6544', 'Thruster con Kettlebell a una mano', 28, 6, 281, 1, 'Intermedio', 'Ejecuta una sentadilla profunda con una pesa en rack y utiliza el impulso de subida para lanzarla sobre la cabeza en un press vertical.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Single-Arm Kettlebell Thruster', 'Perform a deep squat with one kettlebell in the rack position and use the upward drive to launch it into an overhead press.', 'external'),
('4e1a1c4e-8703-476c-9d63-8564b294d150', 'Clean a Sots Press con Kettlebell doble Bottoms Up', 6, 100, 281, 1, 'Avanzado', 'Ejecuta un press militar desde la posicion baja de la sentadilla sosteniendo las Kettlebells invertidas, el reto maximo de movilidad y agarre.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Clean a Sots Press with Double Kettlebell Bottoms Up', 'Perform a military press from the low squat position holding the kettlebells inverted, the ultimate mobility and grip challenge.', 'external'),
('4e211af1-cacb-453d-9888-b52690686129', 'Thruster Ciclista a una mano con mancuerna', 28, 6, 81, 1, 'Intermedio', 'Con talones elevados, ejecuta una sentadilla profunda con una mancuerna en el hombro y termina presionándola sobre la cabeza en la subida.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Cyclist Single-Arm Dumbbell Thruster', 'With your heels elevated, perform a deep squat with a dumbbell at your shoulder and finish by pressing it overhead as you stand up.', 'external'),
('4e348580-50b3-4b92-adf3-0e20f70887d7', 'Full Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Mantén el cuerpo totalmente estirado y paralelo al suelo boca abajo colgado de las anillas.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Full Back Lever on rings', 'Keep your body fully stretched and parallel to the floor face down hanging from the rings.', 'bodyweight'),
('4e6f9c6f-c35a-4441-a59c-e54b453a4be9', 'Elevaciones frontales con barra', 6, NULL, 116, 1, 'Principiante', 'Eleva la barra al frente con brazos rectos hasta la altura de los ojos. Objetivo: deltoides anterior. Cue: no uses el impulso de la cadera. Error común: balancear el torso hacia atrás para subir el peso.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Barbell Front Raises', 'Raise the bar in front of you with straight arms to eye level. Target: anterior deltoid. Cue: don''t use hip thrust. Common mistake: swinging your torso back to raise the weight.', 'external'),
('4e81adf7-3cdc-476f-a04f-93128c9a2dad', 'Tuck L-Sit', 25, 2, 1, 24, 'Avanzado', 'Apoya las manos en el suelo o paralelas y levanta las rodillas hacia el pecho manteniendo los brazos bloqueados y la cadera en el aire.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Tuck L-sit', 'Place your hands on the floor or on parallettes and lift your knees toward your chest while keeping your arms locked out and your hips off the ground.', 'bodyweight'),
('4e8f8abe-b784-4c5a-8557-7daf1666a614', 'Push Up a una mano alterno en paralelas', 1, 2, 1, 1, 'Intermedio', 'Realiza flexiones sobre las paralelas alternando el apoyo de un solo brazo en cada descenso para maximizar la intensidad.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Push Up with one hand alternating parallel bars', 'Perform push-ups on the parallel bars, alternating the support of a single arm on each descent to maximize intensity.', 'mixed'),
('4ec0bb04-373a-4cbf-a71a-82a5680e5d87', 'Parallette L Sit', 25, 2, 1, 1, 'Avanzado', 'Sostente sobre las paralelas con los brazos estirados. Levanta las piernas rectas frente a ti hasta formar un ángulo de 90 grados y mantén la posición.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Parallette L Sit', 'Hold on the parallel bars with your arms stretched. Raise your legs straight in front of you until they form a 90-degree angle and hold the position.', 'bodyweight'),
('4ee95eaa-488f-4d44-86a5-45feba1e6cf6', 'Pike TRX', 6, 25, 216, 1, 'Intermedio', 'En plancha con pies en las correas, eleva las caderas llevando el cuerpo a posición de V invertida. Trabaja intensamente hombros y core. Mantén las piernas rectas y controla el movimiento en ambas direcciones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pike TRX', 'Start in a plank with your feet in the straps and raise your hips until your body forms an inverted V. It heavily works the shoulders and core. Keep your legs straight and control the movement in both directions.', 'bodyweight'),
('4ee98f68-07c8-4a7d-831e-c3687db82b94', 'Peso muerto rumano a una pierna con cable a una mano', 55, 29, 151, 1, 'Intermedio', 'Realiza un peso muerto rumano sobre una pierna mientras sujetas el mango de la polea baja con el brazo opuesto, estabilizando la cadera.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Romanian One-Leg Cable One-Handed Deadlift', 'Perform a Romanian deadlift on one leg while holding the handle of the low cable with the opposite arm, stabilizing the hip.', 'external'),
('4eea648e-0f1d-4675-a0aa-b0e7fefcb26d', 'Roll out de pie', 25, NULL, 271, 1, 'Avanzado', 'Desde posición de pie, inclínate y rueda hacia adelante hasta extensión completa, luego vuelve a ponerte de pie. Requiere fuerza excepcional del core y flexibilidad. Es la progresión más difícil del ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Standing roll out', 'From a standing position, bend and roll forward to full extension, then return to standing. Requires exceptional core strength and flexibility. It is the most difficult progression of the exercise.', 'external'),
('4f1ce2bf-e764-4281-8c6c-21b6b8ef3234', 'Salto pogo pies juntos rígidos', 64, 309, 1, 1, 'Intermedio', 'Saltos pogo manteniendo las rodillas bloqueadas (piernas rectas) para aislar el tobillo. Cue: rebota como un muelle. Error común: flexionar las rodillas por fatiga.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Pogo Jump Feet Together Stiff', 'Pogo jumps keeping your knees locked (legs straight) to isolate the ankle. Cue: bounces like a spring. Common mistake: bending the knees due to fatigue.', 'bodyweight'),
('4f662146-7070-4252-84ad-2ca2a9574cdf', 'Elevación frontal a una mano con cable', 6, NULL, 151, 1, 'Principiante', 'De espaldas a la polea baja, agarra el mango con una mano. Levanta el brazo recto hacia adelante hasta la altura del hombro.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Cable One-Hand Front Raise', 'With your back to the low cable, grip the handle with one hand. Raise your arm straight forward to shoulder height.', 'external'),
('4f6677ea-6cae-4c12-a5be-5b33a58d9eae', 'Plank lateral de rodillas', 25, 6, 1, 24, 'Principiante', 'Apoya un antebrazo y la rodilla del mismo lado en el suelo. Eleva la cadera manteniendo una linea recta desde la cabeza a las rodillas.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Kneeling Side Plank', 'Place one forearm and the knee on the same side on the floor. Raise your hips, maintaining a straight line from head to knees.', 'bodyweight'),
('4f770740-6ab9-4682-ae75-bae4e1eb4438', 'Chin Up excéntrico en barra', 17, 71, 1, 1, 'Principiante', 'Salta a la posición superior de la dominada supina y baja de forma extremadamente lenta hasta que los brazos estén completamente estirados.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Eccentric Chin Up on bar', 'Jump to the top position of the supine pull-up and lower yourself extremely slowly until your arms are fully extended.', 'mixed'),
('4f9b1ae7-2a4d-4435-a494-07301371a8fa', 'Kettlebell Renegade Row', 71, 25, 281, 1, 'Avanzado', 'En posición de flexión sobre las pesas, realiza un remo alterno. Estabilidad de core. Cuerpo en bloque. No rotes la cadera al remar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Renegade Row', 'In a push-up position on the weights, perform an alternating row. Core stability. Block body. Don''t rotate your hips when rowing.', 'external'),
('4fb46d99-4612-4598-94e7-08663b402b6d', 'Colgado pasivo en barra dominadas', 100, 71, 1, 24, 'Principiante', 'Sujeta la barra y mantén el peso muerto por tiempo. Cue: agarre firme. Error: encoger los hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Passive Hanging on Pull-up Bar', 'Hold the bar and hold the deadlift for time. Cue: firm grip. Common mistake: Shrugging your shoulders.', 'mixed'),
('4fc2f28b-4bdd-4517-96b2-c481bfa6a403', 'Curl de bíceps agarre inverso a una mano con cable', 17, 100, 151, 1, 'Principiante', 'Realiza un curl a un solo brazo en polea baja con el agarre prono (palma abajo) para aislar el trabajo del antebrazo y bíceps.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Cable One-Handed Reverse Grip Bicep Curl', 'Perform a single-arm low cable curl with a prone grip (palm down) to isolate the work of the forearm and biceps.', 'external'),
('50130e19-add3-4ffa-91a0-8609182f0188', 'Russian Twist sobre Fitball con cable', 25, 6, 151, 1, 'Intermedio', 'Apoya la espalda en el Fitball y gira el torso de lado a lado tirando del cable, manteniendo las caderas estables.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Russian Twist on Stability Ball with cable', 'Rest your back on the stability ball and turn your torso from side to side pulling the cable, keeping your hips stable.', 'external'),
('5024a46c-b8e9-4e62-94a2-b105b629a6bc', 'Fire Hydrant en cuadrupedia con rodilla flotante y Miniband', 29, 37, 61, 1, 'Avanzado', 'En cuadrupedia con banda, levanta una rodilla lateralmente mientras la otra rodilla permanece sin tocar el suelo para tension constante.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Fire Hydrant on Quadruped with Floating Knee and Mini Band', 'On quadruped with band, raise one knee laterally while the other knee remains off the ground for constant tension.', 'external'),
('50485213-d2d8-48a3-a70b-58b15406c813', 'Copa de tríceps a dos manos', 2, NULL, 81, 1, 'Principiante', 'Sujeta una mancuerna sobre la cabeza y bájala por detrás de la nuca. Cue: codos cerrados hacia adelante. Error: arquear la espalda lumbar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Two-handed Triceps Cup', 'Hold a dumbbell above your head and lower it behind your neck. Cue: keep your elbows close in forward. Common mistake: arching the lumbar back.', 'external'),
('505c8bc3-6a03-4dc4-bac1-5466ecf0ab00', 'Giro oblicuo de rodillas en Landmine', 25, 6, 116, 1, 'Intermedio', 'En posición de caballero, gira la barra Landmine desde el hombro del lado de la rodilla apoyada hacia la cadera opuesta de forma explosiva.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Oblique Knee Twist in Landmine', 'In a knight''s position, rotate the Landmine bar from the knee-side shoulder to the opposite hip explosively.', 'external'),
('5089c8b3-194d-4027-adb6-acc848fb7244', 'Zancada inversa alterna con mancuernas', 28, 29, 81, 1, 'Principiante', 'Desde de pie con mancuernas, da un paso largo hacia atrás bajando la cadera. Mantén el torso erguido y regresa al centro.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Alternating Reverse Lunge with Dumbbells', 'Stand tall with dumbbells in your hands, step back into a long reverse lunge, lower your hips, keep your torso upright, and return to the center.', 'external'),
('50cd7040-fb8f-4541-85cb-02fc9eeaa890', 'Plancha RKC', 25, 13, 1, 1, 'Avanzado', 'Plancha isométrica intensa estilo RKC, creando máxima tensión en core y glúteos para estabilidad total.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Plank Rkc', 'An intense RKC-style isometric plank that creates maximum tension in the core and glutes for total stability.', 'bodyweight'),
('50e47853-cc6d-48b0-91b9-785d2638fe19', 'Colgado pasivo en barra', 100, 71, 1, 24, 'Principiante', 'Sujeta la barra de dominadas y mantente suspendido por tiempo. Objetivo: fuerza de agarre y descompresión espinal. Cue: agarre firme y relajación total. Error común: encoger los hombros hacia las orejas.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Passive Hanging on a Bar', 'Hold the pull-up bar and stay suspended for time. Target: grip strength and spinal decompression. Cue: firm grip and total relaxation. Common mistake: shrugging your shoulders towards your ears.', 'mixed'),
('51026931-39c2-4468-8966-e5c0b5856c4b', 'Copenhagen Plank', 313, 25, 1, 24, 'Intermedio', 'En plancha lateral con el pie superior en banco y el inferior libre, mantén la cadera elevada trabajando intensamente los aductores.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Copenhagen Plank', 'In a side plank with the upper foot on the bench and the lower foot free, keep your hips raised by working the adductors intensely.', 'bodyweight'),
('511bb99a-f2b6-4aed-b96d-208559c6c364', 'Curl concentrado de pie con mancuerna', 17, NULL, 81, 1, 'Principiante', 'De pie, inclínate hacia adelante apoyando una mano en algo estable. Con el otro brazo colgando libremente, realiza un curl concentrándote en el bíceps.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Standing Concentrated Dumbbell Curl', 'Standing, lean forward with one hand on something stable. With your other arm hanging freely, perform a curl, focusing on your biceps.', 'external'),
('5158de68-07b4-4419-aa6a-678ae09932b0', 'Press Pallof estático cable', 25, 6, 151, 24, 'Principiante', 'Resiste la rotación del cable extendiendo brazos al frente. Cue: pies clavados. Error: girar el torso.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Static Cable Pallof Press', 'Resist the rotation of the cable by extending your arms in front of you. Cue: feet nailed. Common mistake: twisting the torso.', 'external'),
('5175bece-30f4-4143-8a83-313272a91770', 'Press de hombros ipsilateral medio arrodillado con mancuerna', 6, 2, 81, 1, 'Intermedio', 'En posicion de caballero, presiona la mancuerna sobre la cabeza con el brazo del mismo lado que la rodilla apoyada (ipsilateral).', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Half-Kneeling Ipsilateral Dumbbell Shoulder Press', 'In a half-kneeling position, press the dumbbell overhead with the arm on the same side as the knee on the floor. Keep your torso upright and your core braced.', 'external'),
('518ef945-a940-479d-9470-18dbb4d0b4d0', 'Push Press con barra', 6, 13, 116, 1, 'Intermedio', 'Press de hombro usando un pequeño impulso de piernas para superar el punto crítico. Cue: dip corto y explosivo. Error: bajar la barra golpeando clavículas.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Push Press', 'Shoulder press using a small leg drive to get over the critical point. Cue: short, explosive dip. Common mistake: lowering the bar hitting the collarbones.', 'external'),
('51a2ce48-9acd-4b9b-a59c-dd690790d7d8', 'Salto vertical apertura brazos', 13, 6, 1, 1, 'Principiante', 'Salta y abre los brazos lateralmente en el aire antes de volver a bajarlos. Mejora la movilidad escapular dinámica. Cue: estira los brazos por completo. Error común: falta de altura en el salto.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump Opening Arms', 'Jump and open your arms laterally in the air before lowering them back down. Improves dynamic scapular mobility. Cue: stretch your arms fully. Common mistake: lack of height in the jump.', 'bodyweight'),
('51b4201c-cf7d-403a-966b-6f35e49147ab', 'Salto al cajón pausa superior', 28, 29, 1, 1, 'Intermedio', 'Salta al cajón y mantén la posición de aterrizaje 3 segundos con control absoluto. Cue: aterrizaje silencioso. Error común: estirarse inmediatamente al caer.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Jump to the Top Pause Box', 'Jump onto the box and hold the landing position for 3 seconds with absolute control. Cue: silent landing. Common mistake: stretching immediately when falling.', 'bodyweight'),
('51f484a7-6fd4-4a7a-8922-29306a3d748a', 'Sentadilla cosaca con cambio bajo Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Avanzado', 'Realiza el cambio de lado en la sentadilla cosaca manteniéndote lo mas cerca del suelo posible con las pesas en rack frontal.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Front Rack Low Shift Cossack Squat with Double kettlebell', 'Perform the side change in the Cossack squat, staying as close to the ground as possible with the weights in a front rack.', 'external'),
('52007bc7-174c-4251-b0f2-14cccfe47089', 'Sit ups con disco', 25, NULL, 81, 1, 'Intermedio', 'Incorporación abdominal con peso al pecho. Objetivo: fuerza core. Cue: baja lento. Error: despegar pies.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Sit Ups with Disc', 'Abdominal incorporation with weight on your chest. Target: core strength. Cue: slow down. Common mistake: take off feet.', 'external'),
('529e4e8e-df93-438c-b352-e6bae02d4c7f', 'Curl de bíceps alto con barra en cable', 17, NULL, 151, 1, 'Principiante', 'De pie frente a una polea alta, agarra la barra recta. Manteniendo los codos en alto, flexiona los brazos para llevar la barra hacia la frente.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Bar High Biceps Curl', 'Standing in front of a high cable, grab the bar straight. Keeping your elbows high, bend your arms to bring the bar toward your forehead.', 'external'),
('52b89ce8-bd74-4736-ad41-1f29732fb3a4', 'Curl femoral en máquina', 55, 29, 186, 1, 'Principiante', 'Tumbado o sentado, flexiona las rodillas contra el rodillo de la máquina. Objetivo: aislamiento del isquiotibial. Cue: mantén la cadera fija al banco. Error común: realizar tirones con la espalda baja.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Machine Femoral Curl', 'Lying down or sitting, bend your knees against the roller of the machine. Target: isolation of the hamstring. Cue: keep your hips fixed to the bench. Common mistake: performing pulls with the lower back.', 'external'),
('52b96c88-1b02-4347-b3d4-51ca7f32b9a5', 'Peso muerto Snatch Grip con déficit con barra', 71, 55, 116, 1, 'Avanzado', 'Realiza un peso muerto con agarre ancho sobre una plataforma elevada, aumentando significativamente el recorrido y demanda de la espalda.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Barbell Deficit Snatch Grip Deadlift', 'Perform a wide-grip deadlift on a raised platform, significantly increasing the range and demand on your back.', 'external'),
('52c26109-05be-4330-8d61-c6f9bf2a8ddf', 'Sentadilla sumo con mancuerna', 313, 29, 81, 1, 'Principiante', 'Pies anchos, punta hacia afuera, sujeta la pesa abajo. Enfoque aductores. Espalda recta. Rodillas alineadas con los pies.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Sumo squat with dumbbell', 'Feet wide, toes out, hold the weight down. Adductors focus. Straight back. Knees aligned with feet.', 'external'),
('52db2bf3-3f51-4145-ae35-da28fd853ece', 'Bosu Escaladores dinámicos', 25, 6, 298, 24, 'Intermedio', 'Manos en lado plano del bosu, lleva rodillas al pecho rápidamente. Objetivo: cardio y core inestable. Cue: core muy apretado. Error común: que el bosu tiemble fuera de control.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'BOSU Dynamic Climbers', 'Hands on the flat side of the bosu, bring your knees to your chest quickly. Target: cardio and unstable core. Cue: very tight core. Common mistake: the bosu shakes out of control.', 'bodyweight'),
('5323a9df-095d-4a4a-a3a8-6bbc2a2f068e', 'Press militar mancuernas pie', 6, 2, 81, 1, 'Intermedio', 'Press hombros de pie. Objetivo: hombro y core. Cue: no inclinar atrás. Error: usar piernas.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Military Standing Dumbbell Press', 'Standing shoulder press. Target: shoulder and core. Cue: no lean back. Common mistake: using legs.', 'external'),
('53390d02-3393-4179-96b3-207f7a305f31', 'Sentadilla cosaca alterna', 28, 313, 1, 1, 'Principiante', 'Desde una posicion de pie con las piernas muy abiertas, desplaza el peso hacia un lado flexionando una rodilla mientras mantienes la otra pierna completamente estirada y el torso erguido.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Alternate Cossack Squat', 'From a standing position with your legs wide open, shift your weight to one side by bending one knee while keeping the other leg fully extended and your torso upright.', 'mixed'),
('5369016c-24f0-4259-8848-6fc557512de9', 'Sentadilla Búlgara ipsilateral Front Rack con Kettlebell', 28, 29, 281, 1, 'Intermedio', 'Realiza una sentadilla búlgara con el pie elevado sosteniendo la Kettlebell en posicion rack en el mismo lado de la pierna delantera.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ipsilateral Front Rack Bulgarian Split Squat with Kettlebell', 'Perform a Bulgarian squat with your foot raised, holding the kettlebell in a rack position on the same side as your front leg.', 'external'),
('53a2b9e5-62c9-4184-8d0f-07050e760d69', 'Mountain Climber con Slider', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha con los pies sobre sliders, desliza las rodillas alternativamente hacia el pecho de forma fluida y rápida sin levantar las caderas.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Mountain Climber with Slider', 'In a plank position with your feet on sliders, slide your knees alternately toward your chest fluidly and quickly without lifting your hips.', 'bodyweight'),
('53b819b0-0402-4f84-8f17-c4845d4d8c2d', 'Floor Press con barra Trap', 1, 2, 116, 1, 'Principiante', 'Tumbado en el suelo dentro de la barra Trap, presiona el peso hacia arriba partiendo de una posicion con los codos apoyados.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Floor Press with Trap Bar', 'Lying on the floor inside the Trap bar, press the weight upward starting from a position with your elbows supported.', 'external'),
('53c2109d-2b2a-4f92-a961-843a3e820d4a', 'Peso muerto Trap Bar (agarre alto)', 29, 71, 116, 1, 'Principiante', 'Levanta la barra hexagonal usando las asas superiores para reducir el rango de movimiento. Objetivo: fuerza general con menor estrés lumbar. Cue: saca pecho y espalda plana. Error común: rodillas hacia adentro al subir.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Peso muerto Trap Bar (agarre alto)', 'Lift the hex bar using the high handles to reduce the range of motion. Target: overall strength with less lower-back stress. Cue: keep your chest up and your back flat. Common mistake: letting your knees cave inward on the way up.', 'external'),
('5440b510-b8b6-41df-907e-b233510cb07d', 'Círculo hacia adentro alterno con cuerda de batalla', 6, 25, 256, 1, 'Principiante', 'Realiza círculos hacia adentro de forma alterna con los extremos de la cuerda de batalla, activando hombros y core.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Alternating Inward Circle with Battle Rope', 'Perform alternating inward circles with the ends of the battle rope, activating shoulders and core.', 'external'),
('544e9c3b-c572-4e19-9783-d735069bb8ee', 'Press sots kettlebell', 6, 28, 281, 1, 'Avanzado', 'Press desde la posición más baja de sentadilla. Requiere movilidad excepcional en hombros, caderas y tobillos. Nombrado por Viktor Sots. Comienza con peso muy ligero. Construye fuerza en posiciones extremas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Press Sots', 'Press from the lowest squat position. Requires exceptional mobility in shoulders, hips and ankles. Named by Viktor Sots. Start with very light weight. Build strength in extreme positions.', 'external'),
('54697f58-6c3a-47b3-a9d0-7bfdee394809', 'Buenos días sentado barra estricto', 71, 55, 116, 1, 'Intermedio', 'Sentado, inclina torso adelante con barra en hombros. Cue: espalda plana. Error: bajar muy rápido.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Seated Barbell Good Morning', 'Sitting, lean torso forward with bar on shoulders. Cue: flat back. Common mistake: go down too fast.', 'external'),
('547269f1-ec6e-4058-8094-bb84a4836a29', 'Dead Bug estricto', 25, NULL, 1, 1, 'Principiante', 'Boca arriba, baja brazo y pierna contraria manteniendo lumbar pegada. Cue: movimiento muy lento. Error: despegar la espalda del suelo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dead Bug Strict', 'Face up, lower arm and opposite leg, keeping lumbar close. Cue: very slow movement. Common mistake: taking your back off the ground.', 'bodyweight'),
('54880b1f-49ce-475e-b1a1-ff57fc80ad08', 'Abductor máquina', 37, NULL, 186, 1, 'Principiante', 'Sentado en la máquina, separa las piernas contra la resistencia trabajando los abductores de cadera. Mantén la espalda apoyada y evita usar impulso. Controla tanto la fase concéntrica como la excéntrica del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Seated Hip Abductor Machine', 'Sitting on the machine, spread your legs against resistance by working your hip abductors. Keep your back supported and avoid using momentum. Control both the concentric and eccentric phases of the movement.', 'external'),
('549b4716-2fbc-4b79-8657-21aad1dfc2ef', 'Zancada búlgara con salto', 28, 29, 1, 1, 'Avanzado', 'Con el pie trasero en banco, realiza un salto vertical con la pierna delantera. Potencia unilateral máxima. Cue: mantén el equilibrio al caer. Error común: que la rodilla pase excesivamente la punta del pie.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Bulgarian Jump Lunge', 'With your rear foot on a bench, perform a vertical jump using the front leg. Target: maximal unilateral power. Cue: regain your balance on landing. Common mistake: letting the front knee travel too far past the toes.', 'mixed'),
('54c2e1e5-4b31-42d1-9fde-01e5ab1102d2', 'Chest pass', 1, 2, 240, 1, 'Principiante', 'Pase de pecho explosivo como en baloncesto. Puede hacerse contra pared o con compañero. Desarrolla potencia horizontal en el tren superior. Mantén los codos hacia afuera y empuja con todo el cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Chest Pass', 'Explosive chest pass like in basketball. It can be done against a wall or with a partner. Develops horizontal power in the upper body. Keep your elbows out and push with your whole body.', 'external'),
('54ebca98-6bf6-4e9e-b047-52405de0198a', 'Plancha TRX', 25, 6, 216, 24, 'Intermedio', 'Plancha con pies o antebrazos en las correas del TRX. La inestabilidad aumenta drásticamente la activación del core. Mantén el cuerpo completamente recto resistiendo el balanceo de las correas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank TRX', 'Perform the plank with your feet or forearms in the TRX straps. The instability greatly increases core activation. Keep your body completely straight while resisting the sway of the straps.', 'bodyweight'),
('54f81747-4f20-4cec-9c09-a5507639b6e8', 'Preacher curl máquina', 17, NULL, 186, 1, 'Principiante', 'Con los brazos apoyados en el soporte inclinado, realiza curls. La posición elimina completamente el impulso y proporciona máximo aislamiento. Ten cuidado de no hiperextender los codos en la posición inferior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Preacher Curl Machine', 'With your arms resting on the inclined support, perform curls. The position completely eliminates momentum and provides maximum isolation. Be careful not to hyperextend your elbows in the bottom position.', 'external'),
('54fe3d35-556b-41d3-a7e0-c9e545f40656', 'Caminata Front Rack con Kettlebell a una mano Bottoms Up', 25, 100, 281, 1, 'Intermedio', 'Camina sosteniendo una pesa rusa invertida en posición de rack, lo que multiplica el desafío sobre el agarre y los estabilizadores del hombro.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Front Rack Walk with One-Handed Kettlebell Bottoms Up', 'Walk holding an inverted kettlebell in a rack position, which multiplies the challenge on your grip and shoulder stabilizers.', 'external'),
('5506a6d5-c823-4697-9037-8f7b5b75d3db', 'Salto de longitud a una pierna', 29, 55, 1, 1, 'Avanzado', 'Salta hacia adelante lo más lejos posible con una sola pierna y aterriza con la misma pierna. Control unilateral extremo. Cue: mantén el equilibrio al caer. Error común: dejar que la rodilla colapse hacia adentro.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'One Leg Long Jump', 'Jump forward as far as possible on one leg and land on the same leg. Extreme unilateral control. Cue: keep your balance when falling. Common mistake: letting the knee collapse inward.', 'bodyweight'),
('5532e282-0a58-4511-b626-b18e0346f394', 'Salto vertical con toque de puntas', 25, 55, 1, 1, 'Avanzado', 'Salta y extiende las piernas al frente para tocar las puntas de los pies con las manos. Cue: explosión abdominal rápida. Error común: no elevar las piernas lo suficiente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump with Toe Touch', 'Jump and extend your legs in front of you to touch the tips of your feet with your hands. Cue: quick abdominal explosion. Common mistake: not raising your legs enough.', 'bodyweight'),
('5538935c-60d2-4bc5-bd0f-dc3f8ba54266', 'Sentadilla con banda', 28, 29, 61, 1, 'Principiante', 'Pisa el centro de la banda con ambos pies y sujeta los extremos a la altura de los hombros. Realiza una sentadilla normal con la resistencia adicional de la banda que aumenta progresivamente al subir. Mantén la tensión constante en la banda durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat with band', 'Step on the center of the band with both feet and hold the ends at shoulder height. Perform a normal squat with the additional resistance of the band that increases progressively as you go up. Maintain constant tension on the band throughout the movement.', 'external'),
('55460653-2250-45fe-89fe-5a922a184700', 'Chin Up a una mano en anillas', 17, 71, 1, 1, 'Avanzado', 'Realiza una dominada supina utilizando solo un brazo colgado de la anilla, el nivel mas alto de fuerza de traccion unilateral.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'One-Handed Chin Up on Rings', 'Perform a supine pull-up using only one arm hanging from the ring, the highest level of unilateral pulling force.', 'mixed'),
('5553d449-3632-4642-96aa-801b91c72c5b', 'Plancha lateral', 25, NULL, 1, 24, 'Intermedio', 'Apóyate lateralmente sobre un antebrazo y el lateral del pie, manteniendo el cuerpo completamente alineado. Eleva las caderas para formar una línea recta desde la cabeza hasta los pies. Puedes elevar el brazo libre hacia el techo para mayor dificultad. Trabaja los oblicuos y mejora la estabilidad lateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Side Plank', 'Support yourself on one forearm and the side of one foot, keeping your body aligned. Lift your hips and hold the position without letting them drop.', 'bodyweight'),
('5556c737-ef66-4e8a-92f7-c203930a2322', 'Buenos días sentado con mancuernas', 71, 29, 81, 1, 'Intermedio', 'Sentado en el borde de un banco con mancuernas sobre los hombros, inclina el torso hacia adelante manteniendo la espalda recta y sube con los lumbares.', FALSE, NULL, '2026-02-02T15:31:11.08111+00:00', 'Seated Dumbbell Good Morning', 'Sit on the edge of a bench with dumbbells on your shoulders, hinge your torso forward while keeping your back straight, and return to the starting position using your glutes and hamstrings.', 'external'),
('556f7604-66f9-4073-bcd1-736a605f0d7c', 'Spider Curl con mancuerna a una mano', 17, NULL, 81, 1, 'Principiante', 'Boca abajo en banco inclinado, realiza un curl de biceps con un solo brazo dejandolo colgar verticalmente para eliminar el impulso.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Dumbbell Spider Curl', 'Face down on an incline bench, perform a one-arm biceps curl, letting it hang vertically to eliminate momentum.', 'external'),
('5583b4d8-7170-46b7-a341-5e28a635c6a2', 'Encogimientos de hombros (Shrugs)', 71, 6, 81, 1, 'Principiante', 'Eleva los hombros hacia las orejas manteniendo los brazos rectos. Objetivo: hipertrofia del trapecio. Cue: no rotes los hombros en círculos. Error común: doblar los codos para subir el peso.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Shrugs', 'Raise your shoulders towards your ears, keeping your arms straight. Target: hypertrophy of the trapezius. Cue: don''t rotate your shoulders in circles. Common mistake: bending your elbows to lift the weight.', 'external'),
('55aecc8b-8d86-4a44-8c48-a0b07122c357', 'Zancada alternada con salto', 28, 29, 1, 1, 'Intermedio', 'Salta desde una posición de zancada y cambia de pierna en el aire repetidamente. Objetivo: potencia y resistencia de piernas. Cue: torso erguido siempre. Error común: golpear la rodilla trasera contra el suelo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Alternating Jump Lunge', 'Jump from a lunge position and switch legs in the air repeatedly. Target: leg power and endurance. Cue: keep your torso upright at all times. Common mistake: hitting your back knee against the floor.', 'mixed'),
('55b23e51-ab1c-499f-b529-39be35130e42', 'Battle ropes in and out', 6, 25, 256, 24, 'Intermedio', 'Mueve las cuerdas horizontalmente juntándolas y separándolas. Trabaja los hombros en el plano horizontal. Mantén los brazos paralelos al suelo. Varía la velocidad para diferentes estímulos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope In-and-Out Waves', 'Move the ropes horizontally, bringing them together and separating them. Work your shoulders in the horizontal plane. Keep your arms parallel to the floor. Vary the speed for different stimuli.', 'external'),
('55c2cb94-37b3-4e44-8eb4-2cd0252d3ee5', 'Hip thrust fitball', 29, 55, 290, 1, 'Intermedio', 'Con la espalda alta apoyada en la fitball o los pies sobre ella, realiza empujes de cadera. La inestabilidad aumenta la activación muscular. Aprieta fuertemente los glúteos en la parte superior. Controla el movimiento en ambas fases.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip Thrust Stability Ball', 'With your upper back supported by the stability ball or your feet on it, perform hip thrusts. Instability increases muscle activation. Tightly squeeze your glutes at the top. control movement in both phases.', 'bodyweight'),
('55dd7508-7838-4d6f-9c4a-2a303d7c83b1', 'Face Pull de rodillas con cable', 6, 71, 151, 1, 'Intermedio', 'En posición de caballero (una rodilla abajo), tira de la cuerda hacia la cara separando las manos y rotando hombros externamente.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Cable Kneeling Face Pull', 'In a knight''s position (one knee down), pull the rope towards your face by separating your hands and externally rotating your shoulders.', 'external'),
('55e561dd-e84f-4210-839b-f195b0f782c6', 'Flexiones diamante estricto', 2, 1, 1, 1, 'Intermedio', 'Manos juntas formando un diamante bajo el pecho. Enfoque tríceps. Cuerpo recto. No abras los codos hacia afuera.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Strict Diamond Push-ups', 'Hands together forming a diamond under your chest. Triceps focus. Straight body. Do not open your elbows outwards.', 'mixed'),
('55ed3cc4-4dc2-431f-96de-3e3d40cd8d56', 'Press Overhead alterno de rodillas con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'De rodillas sobre ambas piernas, presiona las pesas rusas alternativamente sobre la cabeza manteniendo el core firme.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Double kettlebell Alternating Kneeling Overhead Press', 'Kneeling on both legs, press the kettlebells alternately overhead while keeping your core tight.', 'external'),
('560e5281-f504-4c49-9998-bacd9552d686', 'L-Sit a una pierna en paralelas', 25, NULL, 1, 24, 'Intermedio', 'Sostente en las paralelas y levanta una pierna estirada frente a ti mientras la otra permanece doblada o apoyada, alternando para trabajar el core.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'L-Sit on one leg in parallel', 'Hold on parallel bars and raise one leg straight in front of you while the other remains bent or supported, alternating to work the core.', 'bodyweight'),
('562aca0e-49c6-4b47-b1e8-5f44b4c74c5a', 'Sentadilla desde pines', 28, 29, 116, 1, 'Avanzado', 'Comienza el movimiento desde la posición baja con la barra en los seguros del rack. Elimina la fase excéntrica y el reflejo elástico. Fortalece puntos débiles. Ajusta la altura según tu punto de estancamiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat from pins', 'Begin the movement from the low position with the bar in the rack locks. Eliminates the eccentric phase and the elastic reflex. Strengthens weak points. Adjust the height based on your sticking point.', 'external'),
('56acd050-e450-4a46-904a-b3b9004e57c5', 'Press de hombros contralateral de rodillas con mancuerna', 6, 25, 81, 1, 'Intermedio', 'En posición de caballero (una rodilla apoyada), realiza un press de hombro con el brazo opuesto a la rodilla delantera (contralateral) para aumentar la demanda de estabilidad del core.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Contralateral Kneeling Dumbbell Shoulder Press', 'In a half-kneeling position, perform a shoulder press with the arm opposite the front knee to increase the stability demand on the core.', 'external'),
('56b3ee48-a1b5-48b5-9798-3224e4f7e897', 'Peso muerto una pierna TRX', 55, 29, 216, 1, 'Avanzado', 'RDL unilateral con TRX para asistencia de equilibrio. Permite enfocarse en el patrón de movimiento sin preocuparse tanto por el balance. Mantén la pierna trasera alineada con el torso durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Leg TRX Deadlift', 'Single-leg RDL using the TRX for balance assistance. It lets you focus on the movement pattern without worrying as much about balance. Keep your rear leg aligned with your torso throughout the movement.', 'assisted'),
('56f7ecba-bf7e-4a96-9975-8ea31dbf7809', 'Zancada inversa Overhead ipsilateral Slider Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sostén una pesa rusa invertida sobre la cabeza y desliza la pierna del mismo lado en un slider. El ejercicio de estabilidad mas exigente.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse stride Overhead ipsilateral Slider Kettlebell Bottoms Up', 'Hold an inverted kettlebell over your head and slide your leg on the same side in a slider. The most demanding stability exercise.', 'external'),
('57226dc9-94e8-49eb-9c6f-3fa8ddf73370', 'Press de hombros sentado agarre inverso con barra', 6, 2, 116, 1, 'Intermedio', 'Sentado en un banco, realiza un press militar con agarre supino, bajando la barra hasta la parte superior del pecho y extendiendo completamente los brazos.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Reverse Grip Seated Barbell Shoulder Press', 'Sitting on a bench, perform a military press with an underhand grip, lowering the bar to the top of your chest and fully extending your arms.', 'external'),
('572e7775-f508-452d-9576-d3093d326e83', 'Flexión pliométrica sobre banco', 1, 2, 1, 1, 'Intermedio', 'Manos en un banco, empuja con fuerza para despegar las manos y vuelve a caer suavemente. Ideal para iniciación en potencia de empuje. Cue: amortigua la caída con codos flexionados. Error común: bloquear codos bruscamente al aterrizar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-up on Bench', 'Hands on a bench, push hard to release your hands and fall back down gently. Ideal for beginners in pushing power. Cue: cushion the fall with bent elbows. Common mistake: abruptly locking elbows when landing.', 'mixed'),
('574283ab-c2e8-4ce7-9db2-4cf155eaf3f2', 'Press Overhead a una mano con Kettlebell', 6, 2, 281, 1, 'Intermedio', 'Desde la posición de rack (pesa en el antebrazo), empuja la pesa rusa verticalmente hasta bloquear el brazo y baja con control.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-handed Overhead Press with Kettlebell', 'From the rack position (weight on the forearm), push the kettlebell vertically until the arm is locked and lower with control.', 'external'),
('574889ba-f9b3-4618-9f4e-91ac36b34828', 'Parallette Mountain Climber', 25, 6, 1, 1, 'Principiante', 'Coloca las manos sobre las barras paralelas en posición de plancha. Lleva una rodilla hacia el pecho y alterna rápidamente con la otra pierna, manteniendo la espalda recta y el abdomen contraído.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Parallette Mountain Climber', 'Place your hands on the parallel bars in a plank position. Bring one knee toward your chest and quickly alternate with the other leg, keeping your back straight and abs contracted.', 'bodyweight'),
('5756b533-86be-4dbc-a08c-1f59001785b9', 'Dominadas con agarre neutro estricto', 16, 17, 1, 1, 'Intermedio', 'Sube en barras paralelas hasta pasar barbilla. Objetivo: espalda y bíceps con menor estrés muñeca. Cue: junta escápulas. Error común: no bajar del todo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Strict Neutral Grip Pull-ups', 'Go up on parallel bars until you pass chin. Target: back and biceps with less wrist stress. Cue: bring your shoulder blades together. Common mistake: not going down all the way.', 'mixed'),
('5762c0af-8ed2-4449-85ae-0e2e31ef2d6e', 'Extensiones de cuadriceps', 28, NULL, 186, 1, 'Principiante', 'Realiza extensiones de cuádriceps en máquina. Extiende las rodillas hasta contraer el cuádriceps y baja de forma controlada sin perder la posición.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Leg Extension', 'Perform leg extensions on a machine. Extend the knees until the quadriceps contract and lower under control without losing position.', 'external'),
('576eb53b-0126-4dfb-871c-26ae58dfb6c0', 'Sentadilla Hack a una mano en Landmine', 28, 29, 116, 1, 'Intermedio', 'De espaldas a la barra Landmine, apoya el extremo en un hombro y realiza una sentadilla, aprovechando el ángulo para enfatizar los cuádriceps.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'One Hand Hack Squat in Landmine', 'With your back to the Landmine bar, rest the end on one shoulder and perform a squat, taking advantage of the angle to emphasize the quads.', 'external'),
('5774af89-b666-4b4e-9483-db0950623906', 'Remo Pendlay con barra', 71, 17, 116, 1, 'Intermedio', 'Con el torso paralelo al suelo, levanta la barra explosivamente desde el suelo hasta tocar el abdomen y regrésala al suelo en cada repetición.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Pendlay Barbell Row', 'With your torso parallel to the floor, lift the bar explosively from the floor until it touches your abs and return it to the floor with each repetition.', 'external'),
('57c0056d-275e-459f-a529-2ef7eed02db9', 'Plancha frontal', 25, NULL, 1, 24, 'Principiante', 'Apoya los antebrazos y las puntas de los pies en el suelo, manteniendo el cuerpo completamente recto desde la cabeza hasta los talones. Contrae el abdomen y glúteos para mantener la posición. Evita que las caderas se eleven o desciendan. Mantén la respiración regular durante todo el ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Front Plank', 'Support yourself on your forearms and toes, keeping your body completely straight from head to heels. Brace your core and avoid letting your hips drop.', 'bodyweight'),
('57dc22ed-c32a-46bd-8ae5-529711a737d6', 'Peso muerto con pausa', 55, 29, 116, 1, 'Avanzado', 'Peso muerto con pausa de 2-3 segundos a media altura (rodillas). Elimina el reflejo de estiramiento y aumenta tiempo bajo tensión. Fortalece puntos débiles. Usa menos peso que el peso muerto regular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Deadlift with pause', 'Deadlift with pause of 2-3 seconds at mid-height (knees). Eliminates the stretch reflex and increases time under tension. Strengthens weak points. Use less weight than regular deadlifts.', 'external'),
('586e098b-da86-469c-a981-6385c2d21435', 'Salto al cajón con una pierna bajada controlada', 28, 29, 1, 1, 'Intermedio', 'Salta al cajón con dos piernas pero baja lentamente usando solo una pierna. Enfatiza el control excéntrico. Cue: rodilla estable al bajar. Error común: dejarse caer pesadamente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Box Jump with a Controlled Lowered Leg', 'Jump onto the box with two legs but slowly lower yourself down using only one leg. Emphasizes eccentric control. Cue: stable knee on the way down. Common mistake: letting yourself fall heavily.', 'bodyweight'),
('587e3719-e12a-4876-859c-5270284b713a', 'Handstand Push Up búlgaro en anillas', 6, 2, 1, 1, 'Avanzado', 'Realiza una parada de manos con las piernas apoyadas en las correas de las anillas para estabilidad y ejecuta flexiones verticales.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Bulgarian Handstand Push Up on Rings', 'Perform a handstand with your legs supported by the ring straps for stability and perform vertical push-ups.', 'mixed'),
('591a0882-7753-441c-b083-4b2c4fcd1f49', 'Push Up agarre cerrado en paralelas', 2, 1, 1, 1, 'Intermedio', 'Coloca las manos en las barras paralelas a una anchura menor que los hombros. Baja el pecho manteniendo los codos pegados al cuerpo para enfatizar los tríceps.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Push Up close grip on parallel bars', 'Place your hands on the parallel bars less than shoulder width apart. Lower your chest, keeping your elbows close to your body to emphasize your triceps.', 'mixed'),
('591f560f-8294-4572-8cf7-051e26e99531', 'Goblet squat mancuernas', 28, 29, 81, 1, 'Principiante', 'Sujeta una mancuerna verticalmente contra el pecho con ambas manos, como si sostuvieras un cáliz. Realiza la sentadilla manteniendo el torso más erguido que en la sentadilla tradicional. Excelente para aprender la técnica correcta y mejorar la movilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Goblet squat dumbbell', 'Hold a dumbbell vertically against your chest with both hands, as if holding a goblet. Perform the squat while keeping your torso more upright than in the traditional squat. Excellent for learning correct technique and improving mobility.', 'external'),
('59267759-1184-4ae4-921b-4ace3043ff65', 'Zancadas TRX', 28, 29, 216, 1, 'Intermedio', 'Con el pie trasero en la correa del TRX, realiza zancadas. La inestabilidad de la correa aumenta el trabajo de estabilización y permite mayor rango de movimiento. También conocido como sentadilla búlgara en TRX.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Lunges', 'With your rear foot in the TRX strap, perform lunges. The instability of the strap increases the stabilization demand and allows for a greater range of motion. Also known as a TRX Bulgarian split squat.', 'mixed'),
('593346cf-1688-4b40-95bf-9665c7025c04', 'Lanzamiento luchador battle ropes', 6, 25, 256, 24, 'Avanzado', 'Simula movimiento de lanzamiento de luchador con las cuerdas. Movimiento diagonal explosivo de arriba hacia abajo alternando lados. Involucra rotación del core. Mantén postura atlética baja.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Fighter launch battle ropes', 'Simulates a wrestler''s throwing movement with the ropes. Explosive diagonal movement from top to bottom alternating sides. Involves rotation of the core. Maintain a low athletic posture.', 'external'),
('5952eaec-0bf6-4e8c-8f03-89a6cfffe485', 'Peso muerto rumano kettlebell', 55, 29, 281, 1, 'Principiante', 'Baja pesa rusa pegada a piernas. Objetivo: isquios. Cue: espalda plana. Error: doblar rodillas.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Romanian Kettlebell Deadlift', 'Lower the kettlebell close to your legs. Target: hamstrings. Cue: keep your back flat. Common mistake: bending your knees too much.', 'external'),
('5964076c-94ac-4048-8d36-a1104702805b', 'Rollout de pie con barra a una mano', 25, 6, 116, 1, 'Avanzado', 'Desde posicion de pie, inclinate y desplaza la barra hacia adelante con una sola mano hasta extender el cuerpo, volviendo luego bajo control.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Standing One-Handed Barbell Rollout', 'From a standing position, lean over and move the bar forward with one hand until your body is extended, then return under control.', 'external'),
('596d1fd9-0ef0-4f81-b569-12c457dcac06', 'Sentadilla cable', 28, 29, 151, 1, 'Intermedio', 'Con un cable anclado bajo o usando una máquina específica, realiza sentadillas con la resistencia del cable. Proporciona una curva de resistencia diferente a las pesas libres. Útil para rehabilitación o como variación en el entrenamiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Squat', 'With a cable anchored low or using a specific machine, perform squats with the resistance of the cable. Provides a different resistance curve than free weights. Useful for rehabilitation or as a variation in training.', 'external'),
('597228bb-154f-451a-ba22-9a74fd234447', 'Salto lateral sobre obstáculo', 13, 64, 1, 1, 'Avanzado', 'Salta con pies juntos de lado sobre una valla o cajón bajo. Mejora la coordinación y potencia en el plano frontal. Cue: rodillas arriba para superar el objeto. Error común: aterrizar con las piernas rígidas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Jump Over Obstacle', 'Jump laterally over a hurdle or low box with both feet together. Improves coordination and power in the frontal plane. Cue: land softly and stay balanced.', 'bodyweight'),
('598cee37-48e6-4d3c-a527-c56c78b13918', 'Salto a cajón con salida unilateral', 28, 37, 1, 1, 'Avanzado', 'Salta al cajón con dos pies pero sal de él aterrizando y estabilizando sobre una sola pierna. Control de frenado. Rodilla alineada. Evita el balanceo lateral.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Box jump with unilateral exit', 'Jump onto the box with two feet but come off it landing and stabilizing on one leg. Brake control. Aligned knee. Avoid lateral sway.', 'bodyweight'),
('59a92b98-f3a0-45dc-b656-a76cb115b63c', 'Russian Twist con pies elevados y cuerdas de batalla', 25, 6, 256, 1, 'Intermedio', 'Sentado con pies en el aire, golpea los extremos de las cuerdas de batalla alternativamente a cada lado del torso.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Russian Twist with raised feet and battle ropes', 'Sitting with your feet in the air, hit the ends of the battle ropes alternately on each side of your torso.', 'external'),
('59b036bf-6734-4c4b-b3e8-0f1ee39f19b8', 'Puente de glúteo con mancuerna', 29, 55, 81, 1, 'Principiante', 'Eleva cadera con una mancuerna apoyada en la pelvis. Objetivo: glúteo mayor. Cues: aprieta arriba 2 segundos. Error común: arquear lumbar.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Dumbbell Glute Bridge', 'Raise your hips with a dumbbell resting on your pelvis. Target: glute maximus. Cues: press up for 2 seconds. Common mistake: arching the lumbar spine.', 'external'),
('59bf043b-894d-4fca-a27d-33cd7aa1d2a4', 'Straddle Planche en paralelas', 25, 6, 1, 24, 'Avanzado', 'Manten el cuerpo horizontal apoyado solo en las manos en las paralelas con las piernas abiertas en V para reducir la palanca.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Straddle Planche on Parallel Bars', 'Hold your body horizontal supported only by your hands on the parallel bars, with your legs opened in a straddle to reduce the lever length.', 'bodyweight'),
('59c33c9d-323a-4c7b-8e00-4a433dddbd96', 'Zancada caminando Overhead con barra', 28, 6, 116, 1, 'Avanzado', 'Camina realizando zancadas mientras sostienes una barra bloqueada sobre la cabeza con un agarre ancho, exigiendo estabilidad total del core.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Walking Overhead Barbell Lunge', 'Walk forward performing lunges while holding a barbell locked out overhead with a wide grip, demanding total core stability.', 'external'),
('59c656c3-a799-43ad-8c62-516bafc46e86', 'Floor Press Seesaw con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado en el suelo, presiona las Kettlebells invertidas de forma alterna, lo que limita el recorrido del codo y maximiza la tensión del tríceps.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Floor Press Seesaw with Double Kettlebell Bottoms Up', 'Lying on the floor, press the inverted kettlebells alternately, which limits elbow travel and maximizes triceps tension.', 'external'),
('59e9f6d5-fe7a-4231-8912-bd3d81cd5317', 'Curl bíceps barra agarre ancho', 17, NULL, 116, 1, 'Principiante', 'Flexiona barra manos separadas para cabeza corta. Cue: rango completo. Error: no estirar brazos abajo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Wide Grip Bar Bicep Curl', 'Barbell curls with hands apart for a short head. Cue: full range. Common mistake: not stretching your arms down.', 'external'),
('59ed1b89-4612-4bb1-9b56-8090248f3fa3', 'Cruces de polea baja pectoral', 1, 6, 151, 1, 'Intermedio', 'Desde poleas bajas, junta las manos frente a la parte superior del pecho. Objetivo: haz clavicular del pectoral. Cue: codos semiflexionados. Error común: encoger los hombros hacia arriba.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Pectoral Low Cable Crosses', 'From low cables, bring your hands together in front of your upper chest. Target: clavicular bundle of your chestis. Cue: semi-flexed elbows. Common mistake: shrugging your shoulders up.', 'external'),
('59ff6ea7-2116-41ca-9fce-57f1dcce61c4', 'Burpee desplazamiento lateral', 13, 29, 1, 1, 'Intermedio', 'Realiza un burpee y da un paso lateral rápido antes del siguiente. Aumenta la agilidad. Cue: pasos cortos y veloces. Error común: arrastrar los pies.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Shift Burpee', 'Perform a burpee and do a quick lateral step before the next. Increases agility. Cue: short, quick steps. Common mistake: dragging your feet.', 'bodyweight');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('5a05c9a6-70fa-426a-b400-f868fc6705d8', 'Pull Through con banda elástica', 29, 55, 61, 1, 'Principiante', 'Sujeta la banda entre las piernas y extiende la cadera con fuerza apretando los glúteos, emulando el movimiento de un peso muerto.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Pull Through with elastic band', 'Hold the band between your legs and extend your hips forcefully, squeezing your glutes, emulating the movement of a deadlift.', 'external'),
('5a0d509e-e580-473e-ab2c-758f83a76b92', 'Side Swing con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'Balancea la pesa rusa de lado a lado por delante del cuerpo, trabajando de forma intensa la rotacion y estabilidad del core.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Side Swing with One-Handed kettlebell', 'Swing the kettlebell from side to side in front of the body, intensely working on core rotation and stability.', 'external'),
('5a12251a-f5f1-40bf-bc3d-41ae46db2821', 'Abductores polea baja cruzados aducción', 313, 25, 151, 1, 'Intermedio', 'Cruza pierna por delante en polea. Cue: espalda recta. Error: doblar rodilla.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Low Pulley Adductors Crossed Adduction', 'Cross one leg in front of the other using a low pulley. Cue: keep your back straight. Common mistake: bending the knee.', 'external'),
('5a44d5e6-8670-41f4-bbed-5ca7b7d598f6', 'Squat Snatch alterno a una mano con mancuerna', 28, 29, 81, 1, 'Avanzado', 'Ejecuta sentadillas Snatch con un solo brazo, alternando de mano en el suelo despues de cada repeticion completa.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Alternating One-Hand Dumbbell Squat Snatch', 'Perform one-arm Snatch Squats, alternating hands on the floor after each full repetition.', 'external'),
('5a704174-049b-44ff-b944-b0ad7a25152e', 'Curl de bíceps en TRX', 17, 25, 216, 1, 'Intermedio', 'Inclinado hacia atrás, flexiona los codos llevando las manos hacia tus sienes mientras mantienes el cuerpo recto. Objetivo: bíceps. Cue: mantén los codos altos y fijos. Error: bajar la cadera durante el movimiento.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'TRX Biceps Curl', 'Leaning back, bend your elbows, bringing your hands towards your temples while keeping your body straight. Target: biceps. Cue: keep your elbows high and steady. Common mistake: lowering your hips during the movement.', 'bodyweight'),
('5a9091d8-ddcc-4da2-a8e1-76adac6af9cf', 'Flexión pliométrica manos juntas-separadas', 1, 2, 1, 1, 'Avanzado', 'Alterna entre flexión diamante y flexión abierta en cada salto explosivo. Cue: manos activas. Error común: falta de empuje para cambiar la posición.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-up Hands Together-apart', 'Alternate between diamond push-ups and open push-ups with each explosive jump. Cue: active hands. Common mistake: lack of push to change position.', 'mixed'),
('5a915278-4f4d-4cd2-a659-6ca66d631ad3', 'Plancha con toques de pie', 25, 55, 1, 1, 'Intermedio', 'Desde plancha frontal, eleva la cadera y toca el pie opuesto con la mano, alternando. Objetivo: estabilidad de core y flexibilidad dinámica. Cues: exhala al subir. Error común: no volver a la posición de plancha recta.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Plank with Toe Taps', 'From a front plank, raise your hips and touch the opposite foot with your hand, alternating sides. Target: core stability and dynamic flexibility. Cue: exhale as you rise. Common mistake: not returning to a straight plank position.', 'bodyweight'),
('5a958f9e-1042-4bd5-bbb9-4738cf071a9a', 'Sentadilla talones elevados', 28, NULL, 116, 1, 'Avanzado', 'Sentadilla con talones elevados en discos o cuñas. Aumenta el énfasis en cuádriceps y permite mayor profundidad si hay limitación de movilidad en tobillos. Popular entre culturistas. No sustituye trabajo de movilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'High Heels Squat', 'Squat with raised heels on discs or wedges. Increases emphasis on quadriceps and allows greater depth if there is limited mobility in the ankles. Popular among bodybuilders. It does not replace mobility work.', 'external'),
('5b681ef2-d5ea-47d0-ae97-a7e9c38d79aa', 'Flexión pliométrica desde rodillas', 1, 2, 1, 1, 'Principiante', 'Iniciación: empuja desde las rodillas para que las manos despeguen. Objetivo: potencia base. Cue: mantén línea recta cadera-hombro. Error común: dejar caer la pelvis.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-up From Knees', 'Initiation: push from the knees so that the hands take off. Target: base power. Cue: maintain a straight hip-shoulder line. Common mistake: dropping the pelvis.', 'mixed'),
('5b7161c3-e08b-442d-abf6-51679920c36e', 'Zancada inversa Overhead con Slider y Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sostén dos Kettlebells invertidas sobre la cabeza y desliza un pie hacia atrás en un slider para realizar una zancada inversa de alta inestabilidad.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Overhead reverse stride with Slider and Kettlebell Bottoms Up', 'Hold two inverted kettlebells over your head and slide one foot back on a slider for a highly unstable reverse stride.', 'external'),
('5b76c675-63c9-4dbf-90ad-ec91168eb2be', 'Snatch alterno con Kettlebell a una mano', 29, 6, 281, 1, 'Intermedio', 'Lleva la Kettlebell desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, alternando la mano en cada repeticion.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Alternate Snatch with One-Handed kettlebell', 'Bring the kettlebell from the floor to overhead in a single explosive movement, alternating your hand with each repetition.', 'external'),
('5b9c740a-df5e-46e3-9e6d-030034a3b060', 'Tríceps pushdown con cuerda polea', 2, NULL, 151, 1, 'Principiante', 'Tira de cuerda abajo abriendo extremos. Cue: hombros bajos. Error: adelantar codos.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Rope Triceps Pushdown', 'Pull the rope downward and spread the ends apart at the bottom. Cue: keep your shoulders down. Common mistake: letting your elbows drift forward.', 'external'),
('5c37d7f1-87e8-4727-8ada-3b6a24b4b0e2', 'Plancha lateral dinámica', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha lateral, baja la cadera al suelo y elévala de nuevo repetidamente. Objetivo: oblicuos y estabilidad. Cue: cuerpo alineado como un bloque. Error: dejar que el hombro se hunda.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Dynamic Side Plank', 'In a side plank position, lower your hip toward the floor and raise it again repeatedly. Target: obliques and stability. Cue: keep your body aligned like a single block. Common mistake: letting your shoulder collapse.', 'bodyweight'),
('5ca98bd4-e7fb-48ef-8d6c-24fc6b1e9dc2', 'Hiperextensión inversa con rodilla doblada sobre Fitball', 29, 71, 290, 1, 'Principiante', 'Apoya el torso sobre el Fitball y, con las rodillas dobladas, eleva las piernas hacia el techo contrayendo los gluteos y la zona lumbar.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Reverse hyperextension with bent knee on Stability Ball', 'Rest your torso on the Stability Ball and, with your knees bent, raise your legs towards the ceiling, contracting your glutes and lower back.', 'bodyweight'),
('5cab2d89-a9f0-4ea4-9c53-e628214a1e93', 'Clean a Press Overhead con Kettlebell doble Bottoms Up', 6, 2, 281, 1, 'Avanzado', 'Carga y presiona simultaneamente dos Kettlebells invertidas, el reto definitivo de coordinacion, agarre y fuerza de hombros.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Clean a Press Overhead with Double Kettlebell Bottoms Up', 'Simultaneously load and press two inverted kettlebells, the ultimate challenge of coordination, grip and shoulder strength.', 'external'),
('5cd3a76f-615c-4422-975b-fe4f0835e6f9', 'Extensión de tríceps con mancuerna a una mano', 2, NULL, 81, 1, 'Principiante', 'Eleva y baja una mancuerna tras la nuca con un solo brazo. Objetivo: aislamiento de tríceps. Cue: usa el otro brazo para estabilizar el codo. Error común: mover el brazo lateralmente perdiendo tensión.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'One-hand Dumbbell Triceps Extension', 'Raise and lower a dumbbell behind the neck with one arm. Target: triceps isolation. Cue: use the other arm to stabilize the elbow. Common mistake: moving the arm laterally, losing tension.', 'external'),
('5ceddd00-76aa-48f7-bb62-ddc9e589b0f7', 'Salto cajón una pierna', 28, 29, 1, 1, 'Avanzado', 'Salto a cajón o plataforma elevada usando solo una pierna. Requiere potencia unilateral excepcional. Comienza con alturas bajas y progresa. Aterriza con la misma pierna y mantén el equilibrio. Alto riesgo si no se domina la técnica.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One Leg Box Jump', 'Jump onto a box or raised platform using only one leg. Requires exceptional unilateral power. Start low and work your way up. Land on the same leg and maintain balance. High risk if the technique is not mastered.', 'bodyweight'),
('5d2f129d-3eaf-4954-8269-cf5ead81153b', 'Sóleo sentado', 309, 64, 186, 1, 'Principiante', 'Realiza elevaciones de sóleo sentado. Con las rodillas flexionadas, eleva los talones hasta ponerte de puntillas y baja de forma controlada.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Seated Soleus Raise', 'Perform seated soleus raises. With the knees bent, lift the heels until on the toes and lower under control.', 'external'),
('5d30bf99-52cb-4a9d-9617-7becec6e9c7d', 'Carga asimétrica', 25, 100, 81, 24, 'Avanzado', 'Camina o permanece de pie con pesos muy diferentes en cada mano. Desafía tremendamente la estabilización del core. La diferencia puede ser 2:1 o más. Mantén postura perfectamente vertical resistiendo la inclinación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Asymmetrical load', 'Walk or stand with very different weights in each hand. It tremendously challenges core stabilization. The difference can be 2:1 or more. Maintain a perfectly vertical posture, resisting tilting.', 'external'),
('5d432a93-f240-4577-bae9-2f3c2f1e6f79', 'Pec Deck (Aperturas máquina)', 1, 6, 186, 1, 'Principiante', 'Sentado, junta los agarres frente al pecho manteniendo ligera flexión de codo. Cue: aprieta al centro. Error: exagerar el estiramiento inicial.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Pec Deck (machine Openings)', 'Sitting, join your grips in front of your chest, maintaining slight elbow flexion. Cue: press to the center. Common mistake: exaggerating the initial stretch.', 'external'),
('5d47abb6-225d-4dc2-8248-83025c3f52fe', 'Plank de antebrazos con rodilla a codo alterna', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha sobre antebrazos, lleva una rodilla lateralmente hacia el codo del mismo lado y regresa, alternando piernas.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Forearm plank with alternating knee to elbow', 'In a plank position on forearms, bring one knee laterally towards the elbow on the same side and return, alternating legs.', 'bodyweight'),
('5d4a65c2-0e4d-4181-8930-403ca55613bf', 'Sentadilla cossack', 28, 37, 1, 1, 'Intermedio', 'Adopta una postura muy amplia y desciende hacia un lado flexionando completamente esa rodilla mientras la pierna opuesta permanece extendida. Alterna entre ambos lados en un movimiento fluido. Mejora la movilidad de caderas, la flexibilidad de aductores y la fuerza unilateral de las piernas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cossack squat', 'Adopt a very wide stance and lower yourself to one side, fully flexing that knee while the opposite leg remains extended. Alternate between both sides in one fluid motion. Improves hip mobility, adductor flexibility and unilateral leg strength.', 'mixed'),
('5d55aeeb-7e54-41a1-9802-7bb344178037', 'Slam Ball Russian Twist', 25, NULL, 240, 1, 'Principiante', 'Siéntate con las rodillas dobladas y el torso inclinado hacia atrás. Sostén el balón medicinal y gira el torso de lado a lado, tocando el balón en el suelo cerca de tu cadera.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Slam Ball Russian Twist', 'Sit with your knees bent and your torso leaning back. Hold the medicine ball and rotate your torso from side to side, touching the ball to the floor near your hip.', 'external'),
('5d7b96d7-48c8-4067-a27b-4e2035a2b85f', 'Bear crawl slam', 25, 6, 240, 1, 'Avanzado', 'Realiza bear crawl arrastrando el balón, detente periódicamente para realizar un slam. Combina locomoción en cuadrupedia con movimientos explosivos. Mantén la espalda plana durante el crawl.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bear Crawl Slam', 'Perform bear crawl dragging the ball, stopping periodically to perform a slam. Combines quadruped locomotion with explosive movements. Keep your back flat during the crawl.', 'external'),
('5dbacc42-8c5c-4e73-934d-e11b3886faf0', 'Kettlebell Halo sentado', 6, 25, 281, 1, 'Principiante', 'Sentado en el suelo, pasa la pesa alrededor de la cabeza. Estabilidad de core. Espalda recta. No muevas el cuello.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Seated Kettlebell Halo', 'Sitting on the floor, pass the weight around your head. Core stability. Straight back. Don''t move your neck.', 'external'),
('5dfd3197-443d-443e-b8c6-1c0b96d67ca5', 'Shoulder Taps en plancha', 25, 6, 1, 24, 'Intermedio', 'En plancha, toca el hombro opuesto con la mano sin mover la cadera. Cue: abre pies para estabilidad. Error: balanceo lateral de cadera.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Plank Shoulder Taps', 'In plank, touch the opposite shoulder with your hand without moving your hips. Cue: open feet for stability. Common mistake: lateral hip swing.', 'bodyweight'),
('5dffdf5c-8f72-40e4-8e13-03d52afab239', 'Elevación de talones sentado con mancuerna', 309, 64, 81, 1, 'Principiante', 'Sentado con una mancuerna apoyada sobre los muslos, eleva los talones lo máximo posible. Objetivo: sóleo. Cue: rango de movimiento completo. Error: dejar que la pesa resbale de los muslos.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Dumbbell Seated Calf Raise', 'Sitting with a dumbbell resting on your thighs, raise your heels as high as possible. Target: soleus. Cue: full range of motion. Common mistake: letting the weight slip off your thighs.', 'external'),
('5e108061-8675-465a-aa7d-e01c61c629e4', 'Elevación de talones sentado', 309, 64, 186, 1, 'Principiante', 'Eleva talones con rodillas flexionadas. Enfoca en el sóleo. Cue: rango completo de movimiento. Error: rebotar el peso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Seated Heel Raise', 'Raise heels with bent knees. Focus on the soleus. Cue: full range of motion. Common mistake: bouncing the weight.', 'external'),
('5e3f4ba8-d7ad-4388-bded-a63e8fd15f10', 'Remo polea baja ancho', 71, 16, 151, 1, 'Intermedio', 'Tira barra ancha al esternón sentado. Objetivo: espalda alta. Cue: saca pecho. Error: encorvarse.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Wide Low Cable Row', 'Pull wide bar to seated sternum. Target: upper back. Cue: stick out your chest. Common mistake: slouching.', 'external'),
('5e45611f-4cdd-4f29-9289-3b8a24078064', 'Salto de patinador con doble contacto', 29, 37, 1, 1, 'Avanzado', 'Realiza un salto lateral y añade un pequeño rebote en el sitio antes de saltar al otro lado. Control de impacto. Espalda neutra. No pierdas la verticalidad.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Double contact skater jump', 'Perform a side jump and add a little bounce in place before jumping to the other side. Impact control. Neutral back. Don''t lose verticality.', 'bodyweight'),
('5e845892-3737-4962-88ff-dd48fb5411ba', 'Fondos en banco', 2, 6, 1, 1, 'Principiante', 'Coloca las manos en el borde de un banco con los dedos hacia adelante y los pies en el suelo. Desciende flexionando los codos hasta 90 grados manteniendo la espalda cerca del banco. Empuja con los tríceps para volver arriba. Puedes elevar los pies en otro banco para aumentar la dificultad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bench Dips', 'Place your hands on the edge of a bench with your fingers facing forward and your feet on the floor. Lower by bending your elbows to about 90 degrees while keeping your back close to the bench, then press back up with your triceps. You can elevate your feet on another bench to increase the difficulty.', 'mixed'),
('5ea2c067-0015-417f-bbb2-d1b7216cf217', 'Puente de glúteo unilateral', 29, 55, 1, 1, 'Principiante', 'Eleva la cadera manteniendo una pierna estirada en el aire. Fuerza unilateral. Core firme. No arquees la espalda baja.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Unilateral Gluteal Bridge', 'Raise your hips, keeping one leg straight in the air. Unilateral force. Firm core. Don''t arch your lower back.', 'bodyweight'),
('5eb80ff3-ec06-46b7-8089-77cc121baf06', 'Sentadilla pistol', 28, 29, 1, 1, 'Avanzado', 'Realiza una sentadilla completa sobre una sola pierna mientras la otra se mantiene extendida al frente. Requiere fuerza excepcional, equilibrio y flexibilidad en tobillos y caderas. Desciende controladamente hasta la posición más baja posible y empuja con fuerza para volver arriba sin perder el equilibrio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pistol squat', 'Perform a full squat on one leg while the other remains extended in front. Requires exceptional strength, balance and flexibility in the ankles and hips. Descend controlledly to the lowest possible position and push hard to return to the top without losing balance.', 'mixed'),
('5ebff291-5314-46eb-afc6-17494f2a4d2c', 'Extensión cuádriceps cable', 28, NULL, 151, 1, 'Principiante', 'Sentado con tobillera conectada a polea baja, extiende la rodilla hasta la extensión completa. Similar a la máquina de extensiones pero con la resistencia variable del cable. Mantén la espalda apoyada y controla el movimiento en ambas fases.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable quadriceps extension', 'Sitting with an ankle brace connected to a low cable, extend your knee to full extension. Similar to the extension machine but with variable resistance of the cable. Keep your back supported and control the movement in both phases.', 'external'),
('5ed15c31-0c53-4638-b7e0-b8339a78e757', 'Press Overhead arrodillado con mancuernas', 6, 2, 81, 1, 'Intermedio', 'De rodillas sobre ambas piernas (Tall Kneeling), presiona ambas mancuernas sobre la cabeza manteniendo el core y gluteos contraidos.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Kneeling Overhead Press with Dumbbells', 'Kneeling on both legs (Tall Kneeling), press both dumbbells overhead, keeping your core and glutes contracted.', 'external'),
('5ee16458-a4df-4fe3-938b-79e9ae01d949', 'Press de hombros con mancuernas', 6, 2, 81, 1, 'Principiante', 'Empuja las mancuernas sobre la cabeza desde la altura de los hombros. Objetivo: fuerza de hombros. Cues: baja hasta 90 grados. Error común: chocar las pesas ruidosamente arriba.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Dumbbell Shoulder Press', 'Push the dumbbells overhead from shoulder height. Target: shoulder strength. Cue: go down to 90 degrees. Common mistake: crashing the weights loudly overhead.', 'external'),
('5ef0f729-a1ed-49d6-8539-f47f8391e193', 'Salto de estrella lateral', 37, 64, 1, 1, 'Intermedio', 'Salta lateralmente y en el aire realiza la extensión de brazos y piernas en X. Agilidad lateral. Cue: aterrizaje suave con puntas. Error común: falta de control del torso.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Star Jump', 'Jump laterally and in the air extend your arms and legs in an X. Lateral agility. Cue: soft landing with spikes. Common mistake: lack of torso control.', 'bodyweight'),
('5ef2677e-7b3f-4937-8487-ef7aea5211f5', 'Clean a Press Overhead alterno con Kettlebell a una mano Bottoms Up', 6, 2, 281, 1, 'Avanzado', 'Realiza una cargada recibiendo la pesa invertida y presiona sobre la cabeza, alternando el brazo en cada repeticion con control total.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Clean a Press Overhead alternating with One-Handed Kettlebell Bottoms Up', 'Perform a clean, receiving the weight inverted and press overhead, alternating the arm in each repetition with total control.', 'external'),
('5f028f60-ac31-4c61-82a1-c85b6238d859', 'Renegade row en T', 16, 25, 81, 1, 'Avanzado', 'Renegade row seguido de rotación a posición T (plancha lateral con brazo elevado). Combina tracción con rotación y estabilización. Alterna lados. Mantén caderas estables durante todo el movimiento complejo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Renegade row in T', 'Renegade row followed by rotation to T position (side plank with raised arm). Combines traction with rotation and stabilization. Alternate sides. Keep your hips stable throughout the complex movement.', 'external'),
('5f2f06b3-25a4-45af-96e0-bdfc2216002d', 'Sentadilla Pistola asistida con banda', 28, 29, 61, 1, 'Intermedio', 'Realiza una sentadilla pistola usando una banda elástica como soporte para reducir la carga y mejorar el equilibrio durante el movimiento.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Band Assisted Pistol Squat', 'Perform a pistol squat using an elastic band for support to reduce the load and improve balance during the movement.', 'assisted'),
('5f70bad7-015e-4f58-9ce5-130a83e9ca50', 'Remo apoyado banco unilateral', 16, 17, 81, 1, 'Principiante', 'Pecho en banco, rema con una mancuerna. Cue: estira total abajo. Error: rotar torso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Unilateral Bench Supported Row', 'Chest on bench, row with a dumbbell. Cue: full stretch down. Common mistake: rotate torso.', 'external'),
('5f76ebc3-eb9c-463b-802c-98c40a068259', 'Mountain Climber abierto con Slider', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha con sliders, desliza el pie derecho hacia el exterior de la mano derecha, regresa y repite con el lado izquierdo.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Open Mountain Climber with Slider', 'In plank position with sliders, slide your right foot to the outside of your right hand, return and repeat with the left side.', 'bodyweight'),
('5fae2b37-ff70-43a6-aaf2-85d1d144184e', 'Salto cajón pasos laterales', 28, 64, 1, 1, 'Intermedio', 'Salta al cajón, baja con pasos laterales rápidos y repite del otro lado. Agilidad. Cue: pies veloces en el suelo. Error común: saltar hacia atrás ruidosamente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Step Box Jump', 'Jump onto the box, go down with quick lateral steps and repeat on the other side. Agility. Cue: quick feet on the ground. Common mistake: jumping back loudly.', 'bodyweight'),
('603c0f5c-7a8c-4876-b903-612b83f40c3b', 'Curl martillo sentado', 17, NULL, 81, 1, 'Principiante', 'Curl martillo realizado en posición sentada. Mantén los codos pegados al cuerpo y controla la bajada.', FALSE, NULL, '2026-03-31T15:36:05.197152+00:00', 'Seated Hammer Curl', 'Hammer curl performed in a seated position. Keep your elbows close to your body and control the lowering phase.', 'external'),
('603f33ba-77fc-4488-a30c-6e85d4a903e4', 'Cargada balón medicinal', 6, 28, 240, 1, 'Avanzado', 'Lleva el balón del suelo a los hombros en movimiento explosivo. Simula cargada olímpica. El agarre del balón es más desafiante que una barra. Usa las piernas para generar potencia, no solo los brazos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Loaded medicine ball', 'Bring the ball from the ground to your shoulders in an explosive movement. Simulates Olympic clean. Gripping the ball is more challenging than a barbell. Use your legs to generate power, not just your arms.', 'external'),
('60560dc8-3e70-433b-918e-8dddfcfa8dbe', 'Floor Press alterno con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Realiza press de suelo alternando brazos con Kettlebells invertidas, desafiando continuamente el equilibrio de la carga.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Alternating Floor Press with Double Kettlebell Bottoms Up', 'Perform floor press alternating arms with inverted kettlebells, continually challenging the balance of the load.', 'external'),
('605714c3-f5ef-49d5-a953-78d705ec191f', 'Press banca agarre inverso', 1, 2, 116, 1, 'Avanzado', 'Palmas hacia ti en press de banca. Objetivo: pecho superior y tríceps. Cue: agarre seguro. Error: usar demasiado peso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Reverse Grip Bench Press', 'Palms facing you on bench press. Target: upper chest and triceps. Cue: sure grip. Common mistake: using too much weight.', 'external'),
('605a3e3e-eb8d-4332-b991-87674f79e480', 'Half Lay Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Mantén el cuerpo paralelo al suelo con la espalda y caderas rectas, pero con las rodillas flexionadas a 90 grados.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Half Lay Back Lever in Rings', 'Keep your body parallel to the ground with your back and hips straight, but with your knees bent at 90 degrees.', 'bodyweight'),
('6060a4f9-faec-4b4b-8c2e-661727c84218', 'Press de banca con mancuernas alterno', 1, 25, 81, 1, 'Intermedio', 'Tumbado en banco plano, mantén una mancuerna arriba mientras bajas la otra hacia el pecho. Alterna brazos. Objetivo: estabilidad del core y fuerza pectoral unilateral. Cue: mantén el core muy firme para evitar que el cuerpo rote. Error común: dejar que el brazo en espera descienda por fatiga.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Alternating Dumbbell Bench Press', 'Lying on a flat bench, keep one dumbbell up while lowering the other toward your chest. Alternate arms. Target: core stability and unilateral chest strength. Cue: keep your core very firm to prevent your body from rotating. Common mistake: letting the waiting arm drop due to fatigue.', 'external'),
('6075955a-d0d7-4bda-9b5b-d60d53a033e7', 'Sentadilla Cosaca alterna Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Con Kettlebells en posición rack, realiza una sentadilla lateral profunda hacia un lado manteniendo la otra pierna estirada, y alterna.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Alternating Front Rack Cossack Squat with Double kettlebell', 'With kettlebells in a rack position, perform a deep lateral squat to one side, keeping the other leg straight, and alternate.', 'external'),
('607f6bba-a07a-4ed0-b7dc-25988ef241ac', 'Abducción de cadera tumbado de lado', 37, 29, 1, 1, 'Principiante', 'Tumbado lateralmente, eleva la pierna superior sin rotar la pelvis. Objetivo: aislamiento del glúteo medio. Cue: punta del pie mirando al frente. Error común: girar la punta del pie hacia el techo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Side-Lying Hip Abduction', 'Lie on your side and raise your top leg without rotating your pelvis. Target: glute medius isolation. Cue: keep your toes pointing forward. Common mistake: turning the toes toward the ceiling.', 'bodyweight'),
('6087612f-58d6-4c94-a0c0-c7b32b859a07', 'Press declinado con barra', 1, 2, 116, 1, 'Intermedio', 'Baja la barra al pectoral inferior en banco declinado. Objetivo: pecho inferior. Cue: pies sujetos. Error: bajar al cuello.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Barbell Decline Press', 'Lower the bar to the lower chest on a decline bench. Target: lower chest. Cue: feet held. Common mistake: go down to the neck.', 'external'),
('608ad231-ea17-4c4b-9a75-788fc9dcae3a', 'Battle Ropes Círculos exteriores', 6, 71, 256, 24, 'Intermedio', 'Realiza círculos hacia afuera con las cuerdas de forma simultánea. Enfoque en hombros y estabilidad. Pies firmes. No cierres el pecho.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Battle Ropes Outer Circles', 'Make outward circles with the ropes simultaneously. Focus on shoulders and stability. Firm feet. Don''t close your chest.', 'external'),
('6090ad63-1847-4a5e-9749-44ec4261034b', 'Zancadas traseras', 28, 29, 1, 1, 'Principiante', 'Da un paso atrás y baja la rodilla trasera. Más estable que la zancada frontal. Cue: peso en el talón delantero. Error: inclinar el torso demasiado adelante.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Reverse Lunges', 'Step backward and lower your rear knee toward the floor. This is more stable than a forward lunge. Cue: keep your weight on the front heel. Common mistake: leaning your torso too far forward.', 'mixed'),
('60ed860c-19c0-4677-9b31-0edbb71d73c8', 'Floor Press a una mano con Kettlebell Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Presiona una sola pesa rusa invertida desde el suelo, aislando el trabajo en un lado del pecho y maximizando el control del hombro.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'One-handed Floor Press with Bottoms-Up Kettlebell', 'Press a single inverted kettlebell from the floor, isolating the work on one side of your chest and maximizing shoulder control.', 'external'),
('60f66581-c622-4c61-b0cb-fed87ef290c5', 'Jalón al pecho a una mano de rodillas', 71, 17, 151, 1, 'Intermedio', 'Arrodíllate frente a una polea alta. Realiza un jalón vertical con un solo brazo, manteniendo el torso estable y vertical.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Chest pull with one hand on your knees', 'Kneel in front of a high cable. Perform a vertical pull-down with one arm, keeping your torso stable and vertical.', 'external'),
('6111c4be-8b02-4f2b-a734-01f74d4c51f4', 'Cable Pull Through', 29, 55, 151, 1, 'Principiante', 'De espaldas a la polea baja, agarra la cuerda entre las piernas. Empuja la cadera hacia atrás y luego extiende con fuerza usando los glúteos.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Pull Through Cable', 'With your back to the low cable, grab the rope between your legs. Push your hips back and then extend strongly using your glutes.', 'external'),
('611f6548-b1f1-4d38-add6-8ee93c0caa44', 'Flutter kicks rítmicos', 25, 28, 1, 24, 'Principiante', 'Mueve las piernas arriba y abajo alternadamente a pocos centímetros del suelo. Objetivo: resistencia abdominal inferior. Cue: zona lumbar pegada al suelo. Error común: despegar la espalda baja del suelo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Flutter Rhythmic Kicks', 'Move your legs up and down alternately a few centimeters off the ground. Target: lower abdominal resistance. Cue: lumbar area glued to the floor. Common mistake: taking your lower back off the ground.', 'bodyweight'),
('612dcc45-0d3f-4796-81fd-851aee53a355', 'Kickbacks con banda', 29, NULL, 61, 1, 'Principiante', 'En cuadrupedia con la banda alrededor de un pie y anclada bajo las manos, extiende la pierna hacia atrás y arriba contra la resistencia. Mantén la espalda neutra y contrae el glúteo en la parte superior. Evita arquear excesivamente la espalda baja.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kickbacks with band', 'On all fours with the band around one foot and anchored under the hands, extend the leg back and up against the resistance. Keep your back neutral and contract your glutes at the top. Avoid arching your lower back excessively.', 'external'),
('612e8919-74b5-4d83-9b46-fba0db1683fe', 'Dead bug', 25, NULL, 1, 1, 'Principiante', 'Túmbate boca arriba con brazos extendidos hacia el techo y rodillas flexionadas a 90 grados. Lentamente extiende el brazo derecho hacia atrás mientras extiendes la pierna izquierda sin tocar el suelo. Vuelve al inicio y alterna. Mantén la espalda baja pegada al suelo durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dead Bug', 'Lie face up with arms extended toward the ceiling and knees bent at 90 degrees. Slowly extend your right arm back while extending your left leg without touching the floor. Go back to the beginning and alternate. Keep your lower back flat on the floor throughout the movement.', 'bodyweight'),
('614da850-b822-49f1-8c4c-a324b7a4b69d', 'Zancada inversa Front Rack con Slider y Kettlebell doble', 28, 29, 281, 1, 'Avanzado', 'Sostén dos pesas rusas en posición de Front Rack (pecho). Desliza un pie hacia atrás usando un slider para realizar una zancada inversa controlada.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Front Rack Reverse Stride with Slider and Double Kettlebell', 'Hold two kettlebells in a front rack position. Slide one foot back using a slider to perform a controlled reverse stride.', 'external'),
('615f5b9c-00a6-4169-b95e-34d53183ef4e', 'Pájaros sentado con mancuernas', 6, 71, 81, 1, 'Intermedio', 'Sentado inclinado adelante, eleva las pesas lateralmente para la espalda alta. Objetivo: deltoides posterior. Cue: codos hacia afuera. Error común: balancear el tronco para dar impulso.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Birds Sitting with Dumbbells', 'Sitting leaning forward, raise the weights laterally for your upper back. Target: posterior deltoid. Cue: elbows out. Common mistake: swinging the torso to give momentum.', 'external'),
('61800ff7-c4f2-40dc-84e2-affde813deb0', 'Remo pecho apoyado máquina', 71, 16, 186, 1, 'Intermedio', 'Realiza un remo con el pecho apoyado en máquina. Tira de los agarres hacia el torso juntando las escápulas y controla la vuelta sin perder el apoyo del pecho.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Chest-Supported Machine Row', 'Perform a chest-supported machine row. Pull the handles toward the torso by squeezing the shoulder blades together and control the return without losing chest support.', 'external'),
('6196c7f4-82da-49e8-a87a-d637a93c89fa', 'Halo alterno a Sentadilla Bottoms Up con Kettlebell', 6, 28, 281, 1, 'Intermedio', 'Realiza un halo alrededor de la cabeza y termina en una sentadilla profunda sosteniendo la Kettlebell invertida por los cuernos.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Alternate Halo to Bottoms Up Squat with Kettlebell', 'Perform a halo around your head and finish in a deep squat holding the inverted kettlebell by the horns.', 'external'),
('61bdc9d1-e0e6-4e02-8be0-3716a92930df', 'Elevación Y prono en banco inclinado con mancuernas', 6, 71, 81, 1, 'Intermedio', 'Acuéstate boca abajo en un banco inclinado. Levanta los brazos en forma de Y para trabajar el trapecio inferior y hombros.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Incline Bench Raise and Prone with Dumbbells', 'Lie face down on an incline bench. Raise your arms in a Y shape to work the lower trapezius and shoulders.', 'external'),
('61e7018f-6d7c-4759-ad52-26dd19dde72b', 'Jalón pecho cable', 16, 17, 151, 1, 'Principiante', 'Sentado en la máquina de jalón, agarra la barra con las manos más separadas que los hombros. Tira de la barra hacia el pecho superior inclinándote ligeramente hacia atrás. Controla el ascenso resistiendo el peso. Excelente para principiantes que no pueden hacer dominadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable chest pull', 'Sitting on the pull-down machine, grip the bar with your hands wider than shoulder width apart. Pull the bar toward your upper chest, leaning back slightly. Control the ascent by resisting the weight. Great for beginners who can''t do pull-ups.', 'external'),
('62548205-08ea-4f10-bcff-1d20e8866ba9', 'Side Plank con rotación en anillas', 25, 6, 1, 1, 'Avanzado', 'En posición de plancha lateral con los pies en las anillas, lleva el brazo libre por debajo del torso rotando la cintura y vuelve a la vertical.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Side Plank with ring rotation', 'In a side plank position with your feet on the rings, bring your free arm under your torso, rotating at the waist, and return to vertical.', 'bodyweight'),
('626bb054-927d-46ef-a744-564b2e2d894b', 'Abdominal crunch máquina', 25, NULL, 186, 1, 'Principiante', 'Sentado o tumbado según el diseño, flexiona el tronco contra la resistencia. La máquina proporciona resistencia progresiva a diferencia de los crunches tradicionales. Evita tirar con los brazos y enfócate en la contracción abdominal.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Abdominal crunch machine', 'Sitting or lying down depending on the design, you flex your torso against resistance. The machine provides progressive resistance unlike traditional crunches. Avoid pulling with your arms and focus on abdominal contraction.', 'external'),
('627a44ad-c66b-48e6-bb49-8e99a97a7fbb', 'Giro oblicuo de pie en Landmine', 25, 6, 116, 1, 'Intermedio', 'De pie, sujeta el extremo de la barra con ambas manos y rótala lateralmente de un lado a otro trazando un arco, activando los oblicuos.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Landmine Standing Oblique Twist', 'Standing, hold the end of the bar with both hands and rotate it laterally from side to side in an arc, activating the obliques.', 'external'),
('629d3c49-f564-4967-b136-2b7dd79cfbf7', 'L-Sit con anillas giradas', 25, 2, 1, 24, 'Avanzado', 'Realiza un L-Sit en las anillas manteniendo las palmas mirando hacia adelante, lo que incrementa notablemente la dificultad y estabilidad.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'L-Sit with rotated rings', 'Perform an L-Sit on the rings keeping your palms facing forward, which significantly increases the difficulty and stability.', 'bodyweight'),
('629f3c26-ab37-4050-a180-4a812996a090', 'Peso muerto con barra hexagonal', 29, 28, 116, 1, 'Principiante', 'Dentro de la barra hexagonal, baja cadera y levanta. Más seguro para la espalda. Cue: empuja el suelo con los pies. Error: rodillas hacia adentro.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Hex Bar Deadlift', 'Inside the hexagonal bar, lower your hips and lift. Safer for your back. Cue: push the ground with your feet. Common mistake: knees inward.', 'external'),
('62af9ece-a4ee-43c3-8eb2-454f41bc0e89', 'Remo Landmine con agarre V', 71, 17, 116, 1, 'Intermedio', 'A horcajadas sobre la barra landmine, tira hacia el abdomen con agarre estrecho. Cue: espalda plana. Error: tirones con la zona lumbar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Landmine V-grip Rower', 'Straddling the landmine bar, pull towards your abs with a close grip. Cue: flat back. Common mistake: pulling with the lower back.', 'external'),
('62b1a98e-1ff3-49c4-a188-42f61bcfd919', 'Patada de glúteo de pie con Miniband', 29, NULL, 61, 1, 'Principiante', 'De pie con la banda en los tobillos. Patea una pierna hacia atrás manteniendo la rodilla recta, usando solo el glúteo para mover la pierna.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Standing Glute Kick with Mini Band', 'Standing with the band on your ankles. Kick one leg back, keeping your knee straight, using only your glute to move your leg.', 'external'),
('62bc677f-b876-409b-a7eb-6c62c6f39bdb', 'Kettlebell Sumo Deadlift High Pull', 13, 6, 281, 1, 'Intermedio', 'Desde peso muerto sumo, eleva la pesa hacia el mentón con un movimiento explosivo. Objetivo: potencia total. Cue: codos altos arriba. Error común: usar solo los brazos en lugar de la potencia de cadera.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Kettlebell Sumo Deadlift High Pull', 'From sumo deadlifts, raise the weight toward your chin in an explosive movement. Target: total power. Cue: high elbows up. Common mistake: using only your arms instead of hip power.', 'external'),
('6313147f-0670-451f-89bc-317799ac6ffc', 'Salto vertical con toque de talones', 55, 64, 1, 1, 'Intermedio', 'Salta y flexiona las rodillas para tocar los talones con las manos detrás de los glúteos. Cue: salto alto para tener tiempo. Error común: tirar el tronco hacia adelante al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump with Heel Touch', 'Jump and bend your knees to touch your heels with your hands behind your buttocks. Cue: high jump for time. Common mistake: pulling the torso forward when jumping.', 'bodyweight'),
('63285570-fdca-42d0-b232-5999afb89c51', 'Remo inclinado con maza (Offset)', 71, 17, 81, 1, 'Intermedio', 'Sujeta la maza con una mano mas cerca del peso que la otra. Realiza un remo inclinado resistiendo la carga asimetrica de la herramienta.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Bent-over row with mallet (Offset)', 'Hold the club with one hand closer to the weight than the other. Perform an inclined row resisting the asymmetrical load of the tool.', 'external'),
('6332e158-7c6e-4804-9716-ac2deefd4818', 'Press un brazo cable', 1, 25, 151, 1, 'Avanzado', 'Press horizontal unilateral de pie. Requiere tremenda estabilización del core para resistir rotación. Más funcional que press bilateral. Permite mayor rango de movimiento. Mantén caderas cuadradas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm cable press', 'Unilateral standing horizontal press. Requires tremendous core stabilization to resist rotation. More functional than bilateral press. Allows greater range of motion. Keep hips square.', 'external'),
('6347bc1f-fc85-4b4b-bee3-fc4181ec568b', 'Spider Curl con Kettlebell a una mano', 17, 100, 281, 1, 'Principiante', 'Boca abajo en banco inclinado, realiza un curl de bíceps con una Kettlebell dejando el brazo colgar verticalmente para aislar el músculo.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Handed kettlebell Spider Curl', 'Face down on an incline bench, perform a biceps curl with a kettlebell, letting your arm hang vertically to isolate the muscle.', 'external'),
('6359bb2b-a6f2-49b8-91b0-c8280e4698e1', 'Crow Pose en paralelas', 25, 6, 1, 24, 'Intermedio', 'En las paralelas, apoya las rodillas en los tríceps e inclínate hacia adelante despegando los pies del suelo para equilibrar el cuerpo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Crow Pose in Parallels', 'On parallel bars, rest your knees on your triceps and lean forward, taking your feet off the ground to balance your body.', 'bodyweight'),
('63665876-ab73-4d93-9c92-8d7cc20b4d7d', 'Jalón tras nuca cable', 16, 17, 151, 1, 'Intermedio', 'Similar al jalón al pecho pero llevando la barra detrás de la cabeza hasta la altura de la nuca. Requiere buena movilidad de hombros. No bajes demasiado para evitar lesiones. Algunos expertos desaconsejan este ejercicio por el riesgo potencial.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pull behind cable neck', 'Similar to the chest pull but bringing the bar behind the head to the height of the neck. Requires good shoulder mobility. Don''t go too low to avoid injury. Some experts advise against this exercise due to the potential risk.', 'external'),
('6369fb53-02f0-4be0-979e-1efc1f112caf', 'Peso muerto con kettlebell', 55, 29, 281, 1, 'Principiante', 'Pesa rusa entre los pies, baja con la espalda recta, sujeta el asa y elévate extendiendo la cadera. Objetivo: glúteos e isquios. Cue: empuja el suelo con los talones. Error: redondear la espalda al inicio.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Kettlebell Deadlift', 'Place the kettlebell between your feet, lower with your back straight, grab the handle, and stand up by extending your hips. Target: glutes and hamstrings. Cue: push through your heels. Common mistake: rounding your back at the start.', 'external'),
('6391579c-b6f4-4461-8ca2-6ee716259eea', 'Thruster en Landmine', 28, 6, 116, 1, 'Intermedio', 'Sujeta el extremo de la barra con ambas manos, baja en sentadilla y empuja explosivamente la barra hacia adelante y arriba al subir.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Landmine Thruster', 'Hold the end of the bar with both hands, squat down, and drive the bar forward and upward explosively as you stand up.', 'external'),
('63957eda-5492-4526-b258-267d1f2b7c2c', 'Battle ropes plank', 25, 6, 256, 24, 'Avanzado', 'En posición de plancha, mueve una cuerda por vez manteniendo la estabilidad del core. Extremadamente desafiante para el core. Evita rotar las caderas mientras alternas los brazos. Comienza con intervalos cortos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Plank', 'In plank position, move one rope at a time while maintaining core stability. Extremely challenging for the core. Avoid rotating your hips while alternating your arms. Start with short intervals.', 'external'),
('639a618a-3a11-4f9d-a85d-96e7c15118e8', 'Leñador explosivo cable', 25, NULL, 151, 1, 'Avanzado', 'Woodchopper con máxima velocidad y potencia. El cable debe moverse explosivamente en la fase concéntrica pero controlado en la excéntrica. Desarrolla potencia rotacional para deportes. Mantén brazos relativamente extendidos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lumberjack explosive cable', 'Woodchopper with maximum speed and power. The cable must move explosively in the concentric phase but controlled in the eccentric phase. Develops rotational power for sports. Keep your arms relatively extended.', 'external'),
('63b72b29-de6a-4901-83c1-70756513a1dc', 'Sentadilla Zercher con barra', 28, 25, 116, 1, 'Avanzado', 'Barra en el pliegue de los codos, baja en sentadilla profunda. Cue: torso muy erguido. Error: dejar que la barra se aleje del cuerpo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Zercher Squat', 'Bar in the bend of the elbows, lower into a deep squat. Cue: very upright torso. Common mistake: letting the bar move away from the body.', 'external'),
('63c79ac0-9f0f-41a3-9f1b-84de9a2af590', 'Frog Pump', 29, NULL, 1, 1, 'Principiante', 'Acuéstate boca arriba con las plantas de los pies juntas y rodillas abiertas. Eleva las caderas rápidamente apretando los glúteos y baja.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Frog Pump', 'Lie on your back with the soles of your feet together and your knees open. Raise your hips quickly, squeezing your glutes, and lower yourself down.', 'bodyweight'),
('63e6895b-a245-4fe5-83d8-89246024b7d4', 'Plancha lateral con rotación', 25, 6, 1, 1, 'Intermedio', 'En plancha lateral, pasa el brazo libre por debajo del cuerpo y vuelve a extenderlo hacia el techo. Objetivo: oblicuos y estabilidad escapular. Cues: core muy firme en el giro. Error común: dejar caer la cadera hacia el suelo al rotar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Side Plank with Rotation', 'In a side plank, thread your free arm under your body and then extend it back toward the ceiling. Target: obliques and scapular stability. Cue: keep your core very tight during the rotation. Common mistake: letting your hip drop toward the floor during rotar.', 'bodyweight'),
('640686a4-ca8a-4b6b-bcf6-c08d6f4f466a', 'Salto pogo jack', 64, 309, 1, 1, 'Principiante', 'Rebotes rápidos alternando pies abiertos y cerrados (como jumping jack pero pliométrico). Cue: tiempo de contacto mínimo. Error común: apoyar talones.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Pogo Jack Jump', 'Fast rebounds alternating open and closed feet (like jumping jack but plyometric). Cue: minimum contact time. Common mistake: leaning on heels.', 'bodyweight'),
('642a6c58-eab9-4ab5-a2f7-8321ee04c3e4', 'Zancada inversa Overhead con Slider y Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Sostén dos pesas rusas bloqueadas sobre la cabeza. Desliza un pie hacia atrás en una zancada inversa usando un slider, manteniendo la estabilidad de los brazos.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Overhead Reverse Stride with Slider and Double Kettlebell', 'Hold two blocked kettlebells over your head. Slide one foot back in a reverse stride using a slider, maintaining arm stability.', 'external'),
('642ea1aa-5610-4413-bdfc-254817d3e05c', 'Deadlift con banda', 55, 29, 61, 1, 'Intermedio', 'Pisa el centro de la banda con los pies al ancho de las caderas. Sujeta los extremos e inclínate desde las caderas con la espalda recta, como en un peso muerto convencional. La banda proporciona resistencia progresiva, siendo más intensa en la parte superior del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Deadlift with band', 'Step on the center of the band with your feet hip-width apart. Hold the ends and bend from the hips with your back straight, like a conventional deadlift. The band provides progressive resistance, being more intense at the top of the movement.', 'external'),
('64d5626f-e211-493f-bc8d-42ae627356ab', 'Remo cuello polea baja barra mentón', 6, 71, 151, 1, 'Principiante', 'Tira barra al mentón polea. Cue: codos arriba. Error: tirones bruscos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Low Pulley Chin Bar Neck Row', 'Pull bar to chin pulley. Cue: elbows up. Common mistake: sudden jerks.', 'external'),
('65060417-e7d5-4fd6-9604-372275b0396e', 'Press hombros máquina', 6, 2, 186, 1, 'Principiante', 'Sentado con la espalda apoyada, presiona hacia arriba siguiendo la trayectoria de la máquina. Puede tener agarre neutro o pronado según el diseño. Ideal para principiantes o para trabajo de alto volumen con seguridad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Shoulder press machine', 'Sitting with your back supported, press up following the path of the machine. It can have a neutral or pronated grip depending on the design. Ideal for beginners or high volume work safely.', 'external'),
('65262863-5694-4d64-9753-ef2f34920e1d', 'Fire hydrant', 29, NULL, 1, 1, 'Principiante', 'En cuadrupedia, mantén la rodilla flexionada a 90 grados y eleva lateralmente la pierna hasta que el muslo esté paralelo al suelo. Evita rotar la cadera o arquear la espalda. Desciende controladamente sin tocar el suelo. Este ejercicio activa específicamente el glúteo medio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Fire Hydrant', 'On all fours, keep your knee bent at 90 degrees and raise your leg laterally until your thigh is parallel to the floor. Avoid rotating your hips or arching your back. Descend in a controlled manner without touching the ground. This exercise specifically activates the glute medius.', 'bodyweight'),
('654c9bec-1825-4a8d-9c08-8d72a1bdac8d', 'Slam de balón medicinal', 13, 25, 240, 1, 'Principiante', 'Lanza el balón contra el suelo con máxima fuerza usando todo el cuerpo. Objetivo: potencia total y core. Cue: extensión total previa al golpe. Error común: redondear la espalda al soltar el balón.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Medicine Ball Slam', 'Throw the ball against the ground with maximum force using your entire body. Objective: total power and core. Cue: total extension prior to the hit. Common mistake: rounding your back when releasing the ball.', 'external'),
('657f45b9-ce99-4d3d-88ec-115941050313', 'Bandera humana', 25, 16, 1, 24, 'Avanzado', 'Sostén el cuerpo horizontal lateralmente agarrado a una barra vertical. Requiere fuerza excepcional en core, dorsales y hombros. Una de las demostraciones más impresionantes de fuerza relativa. Progresa con negativos y posiciones escalonadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Human Flag', 'Hold your body horizontally while gripping a vertical bar. It requires exceptional core, lat, and shoulder strength. It is one of the most impressive displays of relative strength. Progress with negatives and staggered positions.', 'bodyweight'),
('6582cada-a4ca-4f8b-92e9-8e6995e72c7e', 'Zancada hacia adelante alterna con mancuernas', 28, 29, 81, 1, 'Principiante', 'Da un paso adelante con mancuernas a los lados. Baja la rodilla trasera hasta casi tocar el suelo y regresa a la posición inicial de un impulso.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Alternating Forward Lunge with Dumbbells', 'Step forward with the dumbbells at your sides, lower the back knee until it nearly touches the floor, and drive back to the starting position.', 'external'),
('6623843b-e89d-4618-be68-809f98de59cc', 'Squat throw', 28, 6, 240, 1, 'Intermedio', 'Realiza una sentadilla completa y al subir lanza el balón hacia arriba o hacia adelante explosivamente. Desarrolla potencia en todo el cuerpo. Puede hacerse contra pared o al aire libre. Coordina piernas y brazos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat throw', 'Perform a full squat and when rising throw the ball upward or forward explosively. Develops power throughout the body. It can be done against a wall or outdoors. Coordinate legs and arms.', 'external'),
('664ed498-6ac8-4a9f-adb3-857dd69370d3', 'Remo prono con Kettlebell a una mano', 71, 17, 281, 1, 'Principiante', 'Tumbado boca abajo sobre un banco, rima la pesa rusa hacia tu cadera con un solo brazo para aislar el dorsal sin involucrar la zona lumbar.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-Handed kettlebell Prone Row', 'Lying face down on a bench, swing the kettlebell toward your hip with one arm to isolate your lats without involving your lower back.', 'external'),
('66a0d31c-78de-47ec-9d0a-acb504162f75', 'Flexiones superman', 1, 2, 1, 1, 'Avanzado', 'Flexión explosiva donde el cuerpo completo despega del suelo con brazos y piernas extendidos. Requiere potencia excepcional. El cuerpo debe quedar completamente horizontal en el aire. Progresa con flexiones clap y otras variaciones explosivas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Superman Push Ups', 'Explosive push-up where the entire body takes off from the ground with arms and legs extended. Requires exceptional power. The body must be completely horizontal in the air. Progress with clap push-ups and other explosive variations.', 'mixed'),
('66a613b9-e84f-47e6-913e-1f0b6cac3476', 'Curl de bíceps inclinado mancuerna', 17, NULL, 81, 1, 'Intermedio', 'Curl sentado en banco a 45 grados para máximo estiramiento. Cue: codos fijos. Error: mover hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Incline Dumbbell Biceps Curl', 'Seated bench curl at 45 degrees for maximum stretching. Cue: keep your elbows fixed. Common mistake: move shoulders.', 'external'),
('66d6fca2-58e5-4f68-b529-bf89f2839688', 'De Bestia cargada a Kick Through alterno', 25, 6, 1, 1, 'Avanzado', 'Desde cuadrupedia con rodillas elevadas, desplaza el peso atrás y lánzate a un giro pateando por debajo del cuerpo, alternando lados.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'From Beast Loaded to Kick Through Alternate', 'From quadruped with raised knees, shift the weight back and launch into a twist kicking under the body, alternating sides.', 'bodyweight'),
('66d902a4-58da-437c-86f9-0a94c8d12937', 'Zancada lateral con Slider y Kettlebell (Horn)', 28, 29, 281, 1, 'Principiante', 'Sujeta una Kettlebell por los cuernos frente al pecho y desliza una pierna hacia el lado sobre un slider de forma controlada.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Lateral stride with Slider and Kettlebell (Horn)', 'Hold a kettlebell by the horns in front of your chest and slide one leg sideways over a slider in a controlled manner.', 'external'),
('66f3fdff-6636-4c30-b79f-f237895b25cc', 'Plank frontal a una mano sobre Fitball', 25, 6, 290, 24, 'Avanzado', 'Realiza una plancha sobre los antebrazos en un Fitball, pero levantando un brazo para quedar apoyado solo en uno, aumentando el reto de estabilidad.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'One-handed front plank on Stability Ball', 'Perform a plank on your forearms on a stability ball, but raising one arm to rest on only one, increasing the stability challenge.', 'bodyweight'),
('6763aab6-2a0a-4640-9fda-c75dc78fd57e', 'Extensión tríceps overhead polea', 2, NULL, 151, 1, 'Intermedio', 'Extiende cable sobre cabeza de espaldas a la polea. Cue: estira total. Error: arquear lumbar.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Overhead Cable Triceps Extension', 'Extend cable overhead with your back to the cable. Cue: full stretch. Common mistake: arching your lower back.', 'external'),
('676fae14-a2da-45af-a16c-261af549f9f2', 'Carrera en el sitio con resistencia', 28, 29, 61, 24, 'Intermedio', 'Simula carrera a máxima velocidad con una banda en la cintura que tira hacia atrás. Potencia de empuje. Pecho alto. No arrastres los pies.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Running in place with resistance', 'Simulates running at maximum speed with a waist band that pulls backwards. Thrust power. High chest. Don''t drag your feet.', 'external'),
('6770e326-49b4-4d8a-a1a8-582cd510b054', 'Aperturas inversas con mancuernas', 6, 71, 81, 1, 'Intermedio', 'Inclinado hacia adelante con el torso paralelo al suelo, eleva las mancuernas lateralmente. Objetivo: deltoides posterior. Cue: imagina que empujas con los codos hacia afuera. Error: balancear el torso para subir las pesas.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Reverse Dumbbell Flyes', 'Leaning forward with your torso parallel to the floor, raise the dumbbells laterally. Target: posterior deltoid. Cue: imagine pushing out with your elbows. Common mistake: swinging your torso to lift the weights.', 'external'),
('67a49860-9787-4365-a171-7a5249047624', 'Step Up ipsilateral Front Rack con Kettlebell a una mano', 28, 29, 281, 1, 'Intermedio', 'Sujeta la Kettlebell en posición rack y sube al banco con la pierna del mismo lado, resistiendo la carga asimétrica sobre el tronco.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Ipsilateral Single-Kettlebell Front Rack Step-up', 'Hold the kettlebell in the front rack position and step onto the bench with the leg on the same side, resisting the asymmetrical load.', 'external'),
('67db9f92-68fe-42e9-9fa8-f3b0cfb6055b', 'Fire Hydrant en polea', 29, 37, 151, 1, 'Principiante', 'En posicion de cuadrupedia lateral a la polea baja, sujeta el cable a tu rodilla y realiza una abduccion de cadera levantando la pierna hacia el lado.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Fire Hydrant on cable', 'In a quadruped position lateral to the low cable, hold the cable to your knee and perform hip abduction by raising your leg to the side.', 'external'),
('67dfb407-9666-4518-a22b-717c09a0a493', 'Medicine Ball V Up', 25, 28, 240, 1, 'Intermedio', 'Acuéstate sosteniendo un balón medicinal con las manos extendidas. Levanta simultáneamente el torso y las piernas rectas para tocar el balón con los pies en el punto más alto.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Medicine Ball V Up', 'Lie down holding a medicine ball with your hands outstretched. Simultaneously raise your torso and straight legs to touch the ball with your feet at the highest point.', 'external'),
('682169e4-c090-4da3-b1eb-3eb6d6969537', 'German Hang Pullout en anillas', 25, 17, 1, 1, 'Avanzado', 'Desde la posicion de German Hang (estiramiento maximo de hombro), tira del cuerpo hacia arriba hasta quedar en posicion invertida.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'German Hang Pullout on rings', 'From the German Hang position (maximum shoulder stretch), pull your body up until you are in an inverted position.', 'bodyweight'),
('688cd53a-cc69-4672-8d7d-8ec7d9dde549', 'Aperturas mancuernas', 1, NULL, 81, 1, 'Intermedio', 'Túmbate en banco con los brazos extendidos sobre el pecho y una ligera flexión en los codos. Abre los brazos en arco amplio descendiendo las mancuernas hasta sentir un estiramiento en el pecho. Vuelve a juntar las mancuernas sobre el pecho apretando los pectorales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Flyes', 'Lie on a bench with your arms extended over your chest and a slight bend in your elbows. Open your arms in a wide arc, lowering the dumbbells until you feel a stretch in your chest. Bring the dumbbells back together on your chest, squeezing your pectorals.', 'external'),
('68e37d97-ece2-4d5f-b091-5473408bb42c', 'Push Up agarre cerrado con pies elevados en paralelas', 2, 1, 1, 1, 'Intermedio', 'Con los pies en banco y manos en paralelas a la anchura de hombros, realiza flexiones bajando profundamente para enfatizar los triceps.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Push Up Close Grip with Feet Elevated Parallels', 'With your feet on the bench and hands parallel to shoulder width apart, perform push-ups going down deeply to emphasize the triceps.', 'mixed'),
('68ec9442-186d-4742-bb17-c7ba49c6e1ea', 'Press de hombros con barra arrodillado', 6, 2, 116, 1, 'Intermedio', 'Arrodillado sobre ambas piernas, presiona la barra sobre la cabeza. Esta posición elimina la ayuda de las piernas y exige un mayor control lumbar.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Kneeling Barbell Shoulder Press', 'Kneeling on both legs, press the bar overhead. This position eliminates leg support and requires greater lumbar control.', 'external'),
('68ff3708-4444-41f0-bf14-d8ceaf53b914', 'Rodamiento un brazo', 25, NULL, 271, 1, 'Avanzado', 'Roll out usando solo un brazo. Requiere fuerza anti-rotación extrema. Comienza con rangos muy cortos desde rodillas. El brazo libre puede estar en la espalda o extendido. Alterna brazos para desarrollo equilibrado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm bearing', 'Roll out using only one arm. Requires extreme anti-rotation force. Start with very short ranges from your knees. The free arm can be behind the back or extended. Alternate arms for balanced development.', 'external'),
('691d0774-d545-4f68-998a-a922edfa86e5', 'Extensión de tríceps tras nuca unilateral', 2, NULL, 81, 1, 'Principiante', 'Eleva y baja una mancuerna tras la nuca con un solo brazo. Objetivo: cabeza larga del tríceps. Cue: codo apunta al techo. Error común: mover el brazo lateralmente perdiendo tensión.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Unilateral Behind-the-neck Triceps Extension', 'Raise and lower a dumbbell behind the neck with one arm. Target: long head of the triceps. Cue: elbow points to the ceiling. Common mistake: moving the arm laterally, losing tension.', 'external'),
('6944aafc-fc99-4a40-853b-c68db5111703', 'Pike Press Handstand con brazos rectos en anillas', 6, 2, 1, 1, 'Avanzado', 'Desde la posicion de colgado invertido, baja a posicion de pica y presiona con los brazos bloqueados hasta la parada de manos vertical.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Pike Press Handstand with Straight Arms on Rings', 'From an inverted hanging position, lower into a pike position and press with straight arms until you reach a handstand.', 'bodyweight'),
('69860d20-6b10-4a61-aea2-44b1c22ba23e', 'Rotación lateral a una mano con Indian Club', 6, NULL, 81, 1, 'Principiante', 'Sostén un Indian Club con una mano y realiza rotaciones internas y externas laterales para fortalecer los manguitos rotadores.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'One-Handed Lateral Rotation with Indian Club', 'Hold an Indian Club in one hand and perform lateral internal and external rotations to strengthen the rotator cuffs.', 'external'),
('698fc5cd-9f68-4e73-b84f-66d9b29c6c15', 'Side Plank en paralelas', 25, 6, 1, 24, 'Intermedio', 'Apoya una mano en la paralela y coloca el cuerpo de lado en línea recta. Mantén la posición activando los oblicuos y el hombro estabilizador.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Parallel Side Plank', 'Place one hand on the parallel line and place your body on its side in a straight line. Maintain the position by activating the obliques and shoulder stabilizer.', 'bodyweight'),
('69a3decd-2eaf-4786-9b0f-a66aaad711c3', 'Tríceps con banda alta', 2, NULL, 61, 1, 'Principiante', 'Empuja la banda hacia abajo. Cue: codos fijos a costados. Error: separar codos al bajar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'High-Band Triceps Pushdown', 'Press the band downward. Cue: keep your elbows fixed at your sides. Common mistake: letting your elbows flare out as you press down.', 'external'),
('69af50d3-5b26-4840-9dd5-142117aa2ce1', 'Zancada con salto explosivo', 28, 29, 1, 1, 'Intermedio', 'Desde zancada, salta verticalmente buscando máxima altura y aterriza en la misma posición. Potencia de salida. Rodilla delantera estable. No golpees la rodilla trasera.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Zancada con salto explosivo', 'Desde zancada, salta verticalmente buscando máxima altura y aterriza en la misma posición. Potencia de salida. Rodilla delantera estable. No golpees la rodilla trasera.', 'bodyweight'),
('69b1e1f5-5ce1-46f6-a00a-c2ea29e6195e', 'Sentadilla frente a la pared', 28, 29, 1, 1, 'Principiante', 'Ponte frente a una pared con los pies cerca de ella. Baja en sentadilla evitando tocar la pared con el torso, lo que corrige la postura.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Wall squat', 'Face a wall with your feet close to it. Lower yourself into a squat, avoiding touching the wall with your torso, which corrects your posture.', 'mixed'),
('69b23ccf-09a7-4e45-be57-4f479e9543be', 'Snatch tactico con Kettlebell a una mano', 29, 6, 281, 1, 'Avanzado', 'Un snatch explosivo donde intercambias la Kettlebell de mano en el aire durante la fase de descenso, antes del siguiente balanceo.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Tactical Snatch with One-Handed kettlebell', 'An explosive snatch where you exchange the kettlebell hands in the air during the lowering phase, before the next swing.', 'external'),
('69bd9c4b-882c-4925-8f6b-8b04b24ebefb', 'Single Arm Dumbbell Side Plank Reach Through', 25, 6, 81, 1, 'Avanzado', 'En posición de Plank lateral, sostén una mancuerna con el brazo libre extendido hacia arriba. Baja la mancuerna cruzándola por debajo del torso y vuelve a elevarla.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Single Arm Dumbbell Side Plank Reach Through', 'In a Side Plank position, hold a dumbbell with your free arm extended upward. Lower the dumbbell crossing it under your torso and raise it again.', 'external'),
('69e57dfa-db7d-4708-9780-4ca53c3d799d', 'Salto de patinador', 29, 37, 1, 1, 'Intermedio', 'Salta lateralmente de un pie al otro imitando el movimiento de patinaje. Busca distancia y control en el aterrizaje. Objetivo: potencia lateral y estabilidad de cadera. Cue: aterriza suave con la rodilla alineada al pie. Error común: rotar el tronco excesivamente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Skater Jump', 'Jump laterally from one foot to the other imitating the skating movement. Look for distance and control when landing. Target: lateral power and hip stability. Cue: land softly with your knee aligned with your foot. Common mistake: rotating the torso excessively.', 'bodyweight'),
('69f2cd47-fffc-475f-8629-20801dfc8bc6', 'Zancada inversa contralateral con Slider y Kettlebell (Front Rack)', 28, 29, 281, 1, 'Intermedio', 'Sostén una pesa rusa en el pecho (front rack) y desliza hacia atrás la pierna del lado opuesto usando un slider para trabajar la estabilidad cruzada.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Reverse contralateral stride with Slider and Kettlebell (Front Rack)', 'Hold a kettlebell on your chest (front rack) and slide your opposite leg back using a slider to work on cross stability.', 'external'),
('6a01d020-3903-43bf-aee3-86c1c8c5b097', 'Parada de manos en anillas a Back Lever', 25, 6, 1, 1, 'Avanzado', 'Desde una posicion de parada de manos en anillas, baja el cuerpo de forma controlada manteniendo los brazos rectos hasta quedar en posicion de Back Lever.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Ring Handstand to Back Lever', 'From a ring handstand position, lower your body in a controlled manner keeping your arms straight until you are in a Back Lever position.', 'bodyweight'),
('6a0c6745-5677-437a-a134-a4cc66f7cd09', 'Push Jerk alterno con Kettlebell doble', 6, 28, 281, 1, 'Avanzado', 'Utiliza un impulso explosivo de piernas para elevar las pesas rusas alternativamente, recepcionando el peso con los brazos bloqueados.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Double kettlebell Alternating Push Jerk', 'Use an explosive leg drive to alternately raise the kettlebells, receiving the weight with your arms locked.', 'external'),
('6a62d35b-b5aa-4674-bb97-1abe5ab9cae5', 'Elevación tibial anterior', 64, NULL, 1, 1, 'Principiante', 'Eleva la punta del pie hacia la espinilla contra resistencia o pared. Cue: rango máximo. Error: mover la rodilla.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Anterior Tibialis Raise', 'Raise the ball of your foot toward your shin against resistance or a wall. Cue: maximum range. Common mistake: moving the knee.', 'bodyweight'),
('6aaff30f-694e-4bbe-9dd1-d74c814d772e', 'Clean alterno con Kettlebell a una mano desde el suelo', 29, 6, 281, 1, 'Intermedio', 'Realiza la cargada al hombro desde el suelo alternando el brazo en cada repeticion, trabajando la potencia unilateral de forma coordinada.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Alternate Clean with One-Handed Kettlebell from the Floor', 'Perform the shoulder clean from the floor, alternating your arm in each repetition, working unilateral power in a coordinated manner.', 'external'),
('6ab2b818-0bba-4bef-9c00-1fa4d7dc02d3', 'Press inclinado', 1, 6, 116, 1, 'Intermedio', 'Realiza un press en banco inclinado con barra. Baja el peso de forma controlada hasta la parte superior del pecho y empuja hacia arriba manteniendo la escápula estable y los pies apoyados.', FALSE, NULL, '2026-04-21T15:22:36.176698+00:00', 'Incline Bench Press', 'Perform a bench press on an incline bench with a barbell. Lower the weight under control to the upper chest and press upward while keeping your scapula stable and feet planted.', 'external'),
('6b09dd52-4b91-4746-9668-9732af66db91', 'Curl de bíceps agarre ancho con barra Z', 17, NULL, 116, 1, 'Principiante', 'Sostén la barra Z con las manos más separadas que el ancho de los hombros. Realiza el curl para enfatizar la cabeza corta (interna) del bíceps.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Z-Bar Wide Grip Biceps Curl', 'Hold the Z bar with your hands wider than shoulder width apart. Perform the curl to emphasize the short (inner) head of the biceps.', 'external'),
('6b113673-4a5d-4db9-9169-df31c2a10fc5', 'Press inclinado barra 30-45°', 1, 6, 116, 1, 'Principiante', 'Press de pecho en banco inclinado con barra. Objetivo: haz clavicular del pectoral. Cue: baja la barra a la parte superior del pecho. Error común: bajar la barra hacia el cuello.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Incline Bar Press 30-45°', 'Incline bench chest press with barbell. Target: clavicular bundle of your chestis. Cue: lower the bar to the upper chest. Common mistake: lowering the bar towards the neck.', 'external'),
('6b5a5550-a3e7-40f8-8502-aac2485e02a3', 'Bottoms Up con Fitball', 25, NULL, 290, 1, 'Intermedio', 'Tumbado boca arriba, sujeta el Fitball con los pies y eleva las piernas y la cadera hacia el techo despegando la zona lumbar del suelo bajo control.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bottoms Up with Stability Ball', 'Lying on your back, hold the Stability Ball with your feet and raise your legs and hips towards the ceiling, taking your lower back off the floor under control.', 'bodyweight'),
('6b5d1f69-ddd7-4580-adb1-4369449f6942', 'Rompecráneos con cuerda en polea (Skullcrusher)', 2, NULL, 151, 1, 'Intermedio', 'Acuéstate en un banco plano usando una polea baja detrás de la cabeza. Extiende los brazos hacia el techo separando la cuerda en el tope.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Skullcrusher with rope on cable (Skullcrusher)', 'Lie on a flat bench using a low cable behind your head. Extend your arms toward the ceiling, separating the rope at the top.', 'external'),
('6ba021f2-3a29-4e1e-b125-e324a3267b03', 'Prensa', 28, 29, 186, 1, 'Principiante', 'Realiza una prensa de piernas colocando los pies sobre la plataforma. Baja de forma controlada hasta una profundidad cómoda y empuja extendiendo las piernas sin bloquear agresivamente las rodillas.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Leg Press', 'Perform a leg press with the feet placed on the platform. Lower under control to a comfortable depth and push by extending the legs without aggressively locking the knees.', 'external'),
('6babda62-f8b7-43c3-aec4-cbfba722db27', 'Torch Press con maza', 6, 2, 81, 1, 'Intermedio', 'Presiona la maza verticalmente sobre la cabeza manteniéndola perfectamente equilibrada como si fuera una antorcha encendida.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Mace Torch Press', 'Press the mace vertically overhead while keeping it perfectly balanced, as if you were holding a torch.', 'external'),
('6bb27ab9-3bae-4907-9ffd-3ce5ecca1c35', 'Gorilla Row con kettlebell', 71, 25, 281, 1, 'Intermedio', 'Inclinado con dos pesas en el suelo, rema alternativamente mientras la otra pesa sirve de apoyo. Objetivo: espalda y estabilidad rotacional. Cues: espalda plana y rodillas flexionadas. Error común: mover excesivamente la cadera.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Kettlebell Gorilla Row', 'Bent over with two weights on the floor, row alternately while the other weight serves as support. Target: back and rotational stability. Cue: flat back and bent knees. Common mistake: moving the hips excessively.', 'external'),
('6bbd1c6f-8ee5-47b3-8dea-dfbe52d1d502', 'Sprints en el sitio', 13, NULL, 1, 24, 'Principiante', 'Simula carrera a máxima velocidad elevando rodillas alternadamente. Objetivo: capacidad cardiovascular. Cue: rodillas altas y brazos coordinados. Error común: aterrizar con el pie plano.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Sprints on Site', 'Simulate running at maximum speed by raising your knees alternately. Target: cardiovascular capacity. Cue: high knees and coordinated arms. Common mistake: landing with flat feet.', 'bodyweight'),
('6bcebade-4d33-46d0-9c04-fd4e21a76f69', 'Peso muerto estilo rumano con kettlebell', 55, 29, 281, 1, 'Principiante', 'Baja la pesa rusa pegada a tus piernas con rodillas semi-rígidas y cadera atrás. Objetivo: isquiotibiales. Cues: espalda plana como una tabla. Error común: doblar demasiado las rodillas convirtiéndolo en sentadilla.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Romanian Kettlebell Deadlift', 'Lower the kettlebell close to your legs with a slight knee bend and your hips pushed back. Target: hamstrings. Cue: keep your back flat. Common mistake: bending your knees too much and turning it into a squat.', 'external'),
('6be50ed3-bc62-41c5-aee0-d5410be2c932', 'Paso de valla dinámico con salto', 29, 6, 1, 1, 'Intermedio', 'Simula el paso de una valla con una pierna y añade un salto vertical al final. Movilidad y potencia. Espalda neutra. No gires el torso excesivamente.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Dynamic hurdle step with jump', 'Simulate crossing a fence with one leg and add a vertical jump at the end. Mobility and power. Neutral back. Don''t twist your torso excessively.', 'bodyweight'),
('6c4850fe-d511-44e0-b35a-1ab605711e11', 'Plancha (Plank)', 25, NULL, 1, 24, 'Principiante', 'Mantén el cuerpo recto apoyado en antebrazos y puntas de pies. Objetivo: resistencia del core. Cue: aprieta glúteos y ombligo hacia adentro. Error común: dejar caer la cadera hacia el suelo.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Plank (plank)', 'Keep your body straight while supported on your forearms and toes. Target: core endurance. Cue: brace your glutes and draw your navel inward. Common mistake: letting your hips drop toward the floor.', 'bodyweight'),
('6c7c8108-71f5-4b12-880f-31777aa56cbf', 'Sit Up invertido con botas de gravedad', 25, NULL, 1, 1, 'Avanzado', 'Colgado boca abajo con botas de gravedad, realiza una flexion abdominal completa elevando el torso hacia las rodillas.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Inverted Sit Up with Gravity Boots', 'Hanging upside down with gravity boots, perform a full abdominal flexion by raising your torso toward your knees.', 'mixed'),
('6ca749b9-7255-4d7d-b9c6-a3b5a23e87ae', 'Cruce de poleas para pecho medio', 1, 6, 151, 1, 'Intermedio', 'Realiza un cruce de poleas para pecho medio colocando las poleas a una altura media. Junta las manos delante del pecho manteniendo una ligera flexión de codos y controla la vuelta.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Cable Crossover for Mid Chest', 'Perform a cable crossover for the mid chest with the pulleys set at mid height. Bring the hands together in front of the chest while keeping a slight bend in the elbows and control the return.', 'external'),
('6cd16910-0305-4a2a-9d36-0681daa4df4b', 'Dominada asistida con banda', 71, 17, 61, 1, 'Principiante', 'Cuelga una banda elástica de la barra y coloca un pie o rodilla en ella. Realiza dominadas con la ayuda del rebote de la banda.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Band-assisted pull-up', 'Hang an elastic band from the bar and place one foot or knee on it. Perform pull-ups with the help of the band''s bounce.', 'assisted'),
('6cd2c05e-558b-431b-a010-c207f5c15e9c', 'Pallof isométrico', 25, 6, 151, 24, 'Intermedio', 'Realiza un Pallof isométrico con cable o banda. Colócate de lado al punto de anclaje, extiende los brazos delante del pecho y resiste la rotación manteniendo el tronco estable.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Isometric Pallof Hold', 'Perform an isometric Pallof hold with a cable or band. Stand sideways to the anchor point, extend the arms in front of the chest, and resist rotation while keeping the trunk stable.', 'external'),
('6cfe1d1f-d4c8-491c-ab76-c26e76af7a57', 'Cocoon Crunch', 25, NULL, 1, 1, 'Intermedio', 'Acuéstate boca arriba y, de forma simultánea, encoge las rodillas hacia el pecho y eleva el torso para abrazar tus piernas, regresando luego a la posicion extendida.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Cocoon Crunch', 'Lie on your back and simultaneously draw your knees toward your chest and raise your torso to hug your legs, then return to the extended position.', 'bodyweight'),
('6d395b4d-6621-4002-b5ce-12d84a440b0b', 'TRX Atomic Pushup', 1, 25, 216, 1, 'Avanzado', 'Flexión + rodillas pecho TRX. Objetivo: pecho y core. Cue: fluido. Error: hundir lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX Atomic Pushup', 'Perform a push-up and then drive your knees toward your chest with your feet in the TRX straps. Target: chest and core. Cue: keep the movement fluid. Common mistake: letting the lower back sag.', 'mixed'),
('6db5061c-7f9f-465c-a26f-5a363bb06578', 'Floor Press barra agarre estrecho', 2, 1, 116, 1, 'Intermedio', 'Press en suelo manos juntas. Cue: codos tocan suelo suave. Error: rebotar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Floor Press Bar Narrow Grip', 'Press on the floor hands together. Cue: elbows touch soft ground. Common mistake: bounce.', 'external'),
('6e299057-5bbb-409c-bb26-a73b3d12f48e', 'Remo Meadows', 71, 6, 116, 1, 'Avanzado', 'Uso de barra landmine de lado, agarra el extremo grueso de la barra y rema hacia el costado del torso. Objetivo: grosor de espalda alta. Cue: codo hacia afuera para enfatizar deltoides posterior. Error: rotar demasiado la espalda baja.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Meadows Row', 'using landmine bar on your side, grab the thick end of the bar and row toward the side of your torso. Target: upper back thickness. Cue: elbow out to emphasize rear deltoid. Common mistake: rotating the lower back too much.', 'external'),
('6e2bf996-c5bf-4630-9924-9d915c67ace4', 'Zancada lateral salto explosivo centro', 37, 28, 1, 1, 'Intermedio', 'Paso lateral y vuelve con salto. Cue: empuja fuerte. Error: arrastrar pie.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Side Stride Explosive Jump Center', 'Side step and jump back. Cue: push hard. Common mistake: drag foot.', 'bodyweight'),
('6e324865-6fad-4fe3-bc98-b51ef5a43efd', 'Subida al banco mancuernas', 28, 29, 81, 1, 'Intermedio', 'Con una mancuerna en cada mano, coloca un pie completo sobre un banco o step. Empuja con el talón del pie elevado para subir completamente. Desciende controladamente con la misma pierna. Completa todas las repeticiones de un lado antes de cambiar.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Step-up', 'Hold one dumbbell in each hand, place one foot fully on a bench or step, and drive through the heel of the elevated foot to stand up.', 'external'),
('6e40678e-35d6-474e-b5ef-2c1429d1d7b3', 'Press Overhead de rodillas (Half Kneeling) con Kettlebell doble', 6, 25, 281, 1, 'Intermedio', 'En posición de caballero (una rodilla apoyada), realiza un press de hombros con dos pesas rusas, desafiando el equilibrio.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Kneeling Overhead Press (Half Kneeling) with Double kettlebell', 'In a half-kneeling position (one knee supported), perform a shoulder press with two kettlebells, challenging your balance.', 'external'),
('6e79b3cf-f092-43ef-bdfc-db15e425e6bf', 'Remo prono en banco inclinado con Kettlebell doble', 71, 17, 281, 1, 'Principiante', 'Tumbado boca abajo en un banco inclinado, rema dos pesas rusas simultaneamente hacia la cintura contrayendo los dorsales.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Double kettlebell Incline Bench Prone Row', 'Lying face down on an incline bench, row two kettlebells simultaneously towards your waist, contracting your lats.', 'external'),
('6ea29050-6872-4807-8737-1bd0a07a2769', 'Thruster con barra', 28, 6, 116, 1, 'Avanzado', 'Sostén la barra en posición de rack frontal. Realiza una sentadilla profunda y, al subir, aprovecha el impulso para hacer un press de hombros.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Barbell Thruster', 'Hold the bar in the front rack position. Perform a deep squat and use the upward drive to transition into an overhead press.', 'external'),
('6ea57950-7ee9-40b4-b48d-993b669cd8bb', 'Elevaciones frontales polea baja', 6, NULL, 151, 1, 'Principiante', 'De espaldas, eleva cable al frente. Cue: brazos rectos. Error: arquear lumbar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Low Cable Front Raises', 'On your back, raise cable in front. Cue: straight arms. Common mistake: arching your lower back.', 'external'),
('6ee199cb-d5ef-4494-a2ab-06365e25baa0', 'Crunch en polea alta (de rodillas)', 25, NULL, 151, 1, 'Intermedio', 'De rodillas, sujeta la cuerda tras la nuca y flexiona el torso hacia el suelo. Objetivo: abdominales con carga. Cue: exhala fuerte al bajar. Error común: tirar con los brazos en lugar del abdomen.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'High Cable Crunch (on Your Knees)', 'On your knees, hold the rope behind your neck and bend your torso toward the floor. Target: abs under load. Cue: exhale sharply on the way down. Common mistake: pulling with your arms instead of your abs.', 'external'),
('6f12cc9a-beae-4a8a-91c0-3ceadd40d7e3', 'Remo en máquina', 71, 17, 186, 1, 'Principiante', 'Tira de los agarres de la máquina hacia el torso con el pecho apoyado. Objetivo: desarrollo de la espalda alta. Cue: junta las escápulas atrás. Error común: usar el peso del cuerpo para dar tirón.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Rowing Machine', 'Pull the machine''s grips toward your torso with your chest supported. Target: development of the upper back. Cue: bring your shoulder blades together behind you. Common mistake: using body weight to pull.', 'external'),
('6f2b1074-174b-445e-a90f-958fe0485608', 'Press pecho máquina', 1, 2, 186, 1, 'Principiante', 'Sentado o tumbado según el diseño, empuja los agarres hasta la extensión completa de brazos. La trayectoria fija de la máquina proporciona estabilidad, ideal para principiantes o para trabajar hasta el fallo de forma segura.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Chest press machine', 'Sitting or lying down depending on the design, push the grips to full arm extension. The machine''s fixed path provides stability, ideal for beginners or working to failure safely.', 'external'),
('6f5122d2-3bee-4b22-9df7-7dc2e36754fd', 'Patada de tríceps unilateral en polea alta', 2, NULL, 151, 1, 'Intermedio', 'Sin agarre (solo cable), extiende el brazo hacia atrás inclinado. Objetivo: aislamiento total tríceps. Cue: hombro bloqueado. Error común: mover el codo arriba y abajo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Unilateral High Cable Triceps Kick', 'Without grip (cable only), extend your arm backwards at an angle. Target: total triceps isolation. Cue: shoulder block. Common mistake: moving the elbow up and down.', 'external'),
('6f8e86f7-d621-4bce-abe8-78f10c4edf7d', 'Knee Tuck con Slider', 25, 6, 1, 1, 'Intermedio', 'En posicion de plancha con los pies sobre sliders, encoge las rodillas hacia el pecho deslizando los pies por el suelo y vuelve a la posicion inicial.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Knee Tuck with Slider', 'In a plank position with your feet on sliders, draw your knees toward your chest, sliding your feet along the floor, and return to the starting position.', 'bodyweight'),
('6f92eead-24f4-4e9c-ac1d-5cc915234081', 'Fire Hydrant en cuadrupedia con rodilla flotante', 29, 37, 1, 1, 'Intermedio', 'Realiza una abduccion de cadera en cuadrupedia manteniendo ambas rodillas despegadas del suelo, desafiando la estabilidad del core.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Fire Hydrant on all fours with floating knee', 'Perform a quadruped hip abduction keeping both knees off the ground, challenging core stability.', 'bodyweight'),
('6fa9504a-823c-43af-a070-3313861291ab', 'Mountain climbers', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha alta, lleva alternadamente las rodillas hacia el pecho en un movimiento rápido y continuo, como si estuvieras corriendo en posición horizontal. Mantén las caderas bajas y el core activado. Aumenta la velocidad para mayor intensidad cardiovascular y trabajo abdominal.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Mountain climbers', 'In a high plank position, alternately bring your knees toward your chest in a quick, continuous movement, as if you were running in a horizontal position. Keep your hips low and your core engaged. Increase speed for greater cardiovascular intensity and abdominal work.', 'bodyweight'),
('6fead02c-0870-4e78-98fa-56984bfddfd6', 'Remo en máquina neutro', 71, 17, 186, 1, 'Principiante', 'Tira de los agarres hacia ti con palmas enfrentadas. Cue: pecho contra el soporte. Error: usar los pies para dar impulso al peso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Neutral Rowing Machine', 'Pull the grips toward you with palms facing each other. Cue: chest against support. Common mistake: using your feet to propel your weight.', 'external'),
('6ff25618-18fd-402a-9e90-4fd89b734fc2', 'Cobra prono en Fitball', 71, 6, 290, 1, 'Principiante', 'Acuéstate boca abajo sobre el Fitball. Levanta el torso y gira los brazos hacia afuera con los pulgares hacia arriba, apretando los omóplatos.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Charge prone on Stability Ball', 'Lie face down on the Stability Ball. Raise your torso and rotate your arms outward with your thumbs up, squeezing your shoulder blades together.', 'bodyweight'),
('70017d8f-1365-456b-9a9d-8f7dd88813ad', 'Burpee golpeo battle ropes', 13, NULL, 256, 1, 'Avanzado', 'Burpee completo terminando con slams de cuerdas en lugar de salto. Mantén las cuerdas durante todo el burpee o suéltalas y retómalas. Una de las combinaciones más agotadoras. Requiere resistencia mental.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Burpee hitting battle ropes', 'Full burpee ending with rope slams instead of jumping. Hold the ropes throughout the burpee or release them and resume them. One of the most exhausting combinations. It requires mental endurance.', 'external'),
('70040fec-09f3-498f-ad55-bc3b823b27b6', 'Limpiaparabrisas con Fitball', 25, NULL, 290, 1, 'Intermedio', 'Tumbado boca arriba sujetando el Fitball con los pies, balancea las piernas de lado a lado sin tocar el suelo para trabajar los oblicuos.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Windshield wipers with Stability Ball', 'Lying on your back holding the Stability Ball with your feet, swing your legs from side to side without touching the floor to work your obliques.', 'bodyweight'),
('704ca888-3e20-450f-bee1-43be033fe608', 'Curl femoral de pie unilateral máquina', 55, NULL, 186, 1, 'Principiante', 'Flexiona pierna máquina vertical. Objetivo: isquios. Cue: cadera pegada. Error: lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Single-Leg Standing Machine Leg Curl', 'Perform single-leg curls on the standing machine. Target: hamstrings. Cue: keep your hip fixed. Common mistake: arching your lower back.', 'external'),
('7057a50f-4a04-4463-9859-8d0a6990a050', 'Wall Sit con abducción de cadera y Minibanda', 28, 37, 61, 24, 'Intermedio', 'Realiza una sentadilla isométrica apoyado en la pared (Wall Sit) con una banda sobre las rodillas. Separa las rodillas contra la resistencia de la banda y vuelve a juntarlas sin perder la postura.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Wall Sit with Hip Abduction and Mini Band', 'Perform a wall sit with a band around your knees. Push your knees apart against the band’s resistance and bring them back together without losing the position.', 'external'),
('70627e69-2bc3-49a1-ba37-f692d1226d2e', 'Knee Tuck en paralelas con Slider', 25, 6, 1, 1, 'Intermedio', 'Sostente en las paralelas y, con los pies en sliders, desliza las rodillas hacia el pecho de forma controlada usando los abdominales.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Knee Tuck in parallel bars with Slider', 'Hold on parallel bars and, with your feet on sliders, slide your knees towards your chest in a controlled manner using your abs.', 'bodyweight'),
('70767ff9-9adb-47cb-bc68-cf3ebad5c5bd', 'Dominadas agarre amplio', 16, 17, 1, 1, 'Avanzado', 'Dominadas con las manos separadas significativamente más que el ancho de hombros. Enfatiza la porción externa de los dorsales. Reduce la participación del bíceps. Más difícil que el agarre normal. Evita agarre excesivamente amplio para proteger hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Wide grip pull-ups', 'Pull-ups with hands significantly wider than shoulder width apart. Emphasizes the external portion of the lats. Reduces the participation of the biceps. More difficult than normal grip. Avoid excessively wide grip to protect shoulders.', 'mixed'),
('709ef2d3-6fcb-4b84-803f-54a1892524ca', 'Aperturas polea alta', 1, 6, 151, 1, 'Intermedio', 'Poleas altas, junta manos abajo. Objetivo: pecho inferior. Cue: codos fijos. Error: encoger hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'High Pulley Chest Fly', 'With the pulleys set high, bring your hands down and together in front of your body. Target: lower chest. Cue: keep your elbows fixed. Common mistake: shrugging your shoulders.', 'external'),
('70a32bae-e905-438e-8560-41fe6466635f', 'Remo apoyado en banco', 71, 17, 81, 1, 'Intermedio', 'Pecho apoyado en banco inclinado, rema con mancuernas. Objetivo: espalda sin carga lumbar. Cue: junta escápulas. Error: despegar el pecho del banco.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Bench Supported Row', 'Chest supported on an incline bench, row with dumbbells. Target: back without lumbar load. Cue: bring your shoulder blades together. Common mistake: removing your chest from the bench.', 'external'),
('70cdf5dc-798f-4f73-b6df-99c1b9b22d7c', 'Hip airplane asistido', 29, 55, 1, 1, 'Avanzado', 'Realiza un hip airplane asistido apoyándote en una pared o soporte. Inclínate sobre una pierna, abre y cierra la cadera de forma controlada manteniendo el equilibrio y la pelvis estable.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Assisted Hip Airplane', 'Perform an assisted hip airplane using a wall or support. Hinge on one leg, open and close the hip under control while maintaining balance and pelvic stability.', 'assisted'),
('70da069f-4f76-4745-bba0-6cd87238c901', 'Flexión pliométrica sobre bosu lateral', 1, 25, 298, 1, 'Avanzado', 'Una mano en bosu y otra en suelo, salta explosivamente para cambiar posiciones. Cue: estabiliza el hombro en el bosu. Error común: pérdida de forma por inestabilidad.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-up on Side BOSU', 'One hand on bosu and one on the ground, jump explosively to change positions. Cue: stabilize the shoulder in the bosu. Common mistake: loss of shape due to instability.', 'bodyweight'),
('70e6141b-4401-4fba-af8b-34fc10f21def', 'Outside Pullover con maza a una mano', 71, 6, 81, 1, 'Principiante', 'Lleva la maza desde el hombro del mismo lado hacia afuera y arriba describiendo un arco controlado para mejorar la estabilidad articular.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Outside Pullover with one-handed mace', 'Bring the club from the shoulder on the same side outward and up in a controlled arc to improve joint stability.', 'external'),
('70fb35c8-7e06-4f96-b647-a3fd49cdf706', 'Salto de esquí lateral', 64, 37, 1, 1, 'Principiante', 'Saltos laterales cortos y rápidos con pies juntos, imitando un esquiador. Cue: mantén el torso ligeramente inclinado. Error común: separar demasiado los pies.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Ski Jump', 'Short, quick lateral jumps with feet together, imitating a skier. Cue: keep your torso slightly tilted. Common mistake: spreading your feet too far apart.', 'bodyweight'),
('70fba0f6-2fdf-4ad0-8186-bd53e28c712d', 'Hip to Halo de rodillas con Kettlebell', 6, 25, 281, 1, 'Intermedio', 'De rodillas, mueve la pesa desde una cadera, crúzala por el cuerpo y realiza un halo alrededor de la cabeza. Repite alternando.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Hip to Halo on Your Knees with Kettlebell', 'On your knees, move the weight from one hip, cross it over your body and make a halo around your head. Repeat alternating.', 'external'),
('712b6b30-5a83-4f0e-a59f-8406c8f3639c', 'Flexiones diamante suelo', 2, 1, 1, 1, 'Intermedio', 'Manos juntas formando un diamante, codos pegados. Cue: baja hasta tocar las manos con el pecho. Error: abrir codos hacia afuera.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Diamond Floor Push-ups', 'Hands together forming a diamond, elbows together. Cue: go down until your hands touch your chest. Common mistake: open elbows outwards.', 'mixed'),
('712c0599-c83b-4d8f-9c4a-1ff63f739698', 'Salto vertical banda rodillas', 37, 29, 61, 1, 'Intermedio', 'Salta verticalmente con banda circular en rodillas para forzar la abducción. Cue: empuja las rodillas hacia afuera. Error común: que las rodillas colapsen al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Knee Band Vertical Jump', 'Jump vertically with a circular band on your knees to force abduction. Cue: push your knees out. Common mistake: knees collapsing when jumping.', 'external'),
('71360d73-7747-4cf4-bfac-5ef8cdf812bc', 'Zancada overhead balón medicinal', 28, 6, 240, 1, 'Avanzado', 'Zancadas manteniendo el balón sobre la cabeza con brazos extendidos. Desafía la estabilidad del core y hombros mientras trabajas las piernas. Puede ser estático o caminando. Mantén el balón estable.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Overhead stride medicine ball', 'Stride holding the ball overhead with arms outstretched. Challenge core and shoulder stability while working your legs. It can be static or walking. Keep the ball steady.', 'external'),
('7140a93c-4856-4583-b468-1266ea17eeda', 'Push Press con Kettlebell doble', 6, 28, 281, 1, 'Intermedio', 'Con dos pesas rusas en rack, flexiona ligeramente las rodillas y usa el impulso de las piernas para empujar las pesas sobre la cabeza.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double kettlebell Push Press', 'With two kettlebells racked, bend your knees slightly and use the momentum of your legs to push the weights overhead.', 'external'),
('71655f7f-df48-4c4f-b1ec-c992f1ed87e6', 'Woodchop alto a bajo arrodillado con cuerda', 25, 6, 151, 1, 'Intermedio', 'Arrodillado de lado a la polea alta, tira de la cuerda diagonalmente hacia la cadera opuesta rotando el torso de forma controlada.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Kneeling High-to-Low Rope Woodchop', 'Kneeling sideways to a high pulley, pull the rope diagonally toward the opposite hip while rotating your torso under control.', 'external'),
('71721b34-d770-4db1-a37a-5f57946636f8', 'Remo prono alterno con mancuernas', 71, 17, 81, 1, 'Principiante', 'Acuéstate boca abajo en un banco inclinado y rema las mancuernas alternativamente hacia tu cadera, apretando el dorsal en cada subida.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Alternating Prone Dumbbell Row', 'Lie face down on an incline bench and row the dumbbells alternately toward your hips, squeezing your lats with each lift.', 'external'),
('71b1124e-c2e8-4da7-90a6-d3455ed74d66', 'Flexión hindú', 1, 6, 1, 1, 'Intermedio', 'Inicia en posición de V invertida, baja el pecho hacia el suelo realizando un arco y termina con el torso erguido mirando al frente. Vuelve a la posición inicial revirtiendo el arco. Objetivo: fuerza de empuje y movilidad. Cues: movimientos fluidos y controlados. Error común: realizar una flexión normal sin el movimiento de arco.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Hindu Pushup', 'Start in an inverted V position, lower your chest towards the floor in an arc and finish with your torso upright looking forward. Return to the starting position by reversing the arc. Objective: push strength and mobility. Cues: fluid and controlled movements. Common mistake: performing a normal push-up without the arch movement.', 'mixed'),
('71bdfdc9-98d9-4af4-9a4b-876a66648242', 'Plancha lateral rotación bajo cuerpo', 25, 6, 1, 1, 'Intermedio', 'En plancha lateral, pasa brazo por debajo. Cue: core firme. Error: bajar cadera.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Side Plank Underbody Rotation', 'In a side plank, pass your arm underneath your torso and then rotate back open. Cue: keep your core tight. Common mistake: letting your hips drop.', 'bodyweight'),
('72604f63-086b-4215-afd6-25710e5fba45', 'Peso muerto con déficit con barra', 71, 55, 116, 1, 'Avanzado', 'Realiza un peso muerto subido a una plataforma pequeña para aumentar el rango de movimiento inicial y el estiramiento de isquiotibiales.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Barbell Deficit Deadlift', 'Perform a deadlift on a small platform to increase initial range of motion and hamstring stretch.', 'external'),
('728ec8e8-8e0a-4efd-bc2c-eb8321c9b5d4', 'Sentadilla explosiva', 28, 29, 81, 1, 'Principiante', 'Baja en sentadilla y sube lo más rápido posible sin despegar pies. Cue: empuje potente. Error: redondear espalda.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Explosive Squat', 'Go down into a squat and go up as quickly as possible without taking your feet off. Cue: powerful thrust. Common mistake: rounding back.', 'external'),
('72a8be89-f41b-4d21-be3b-d8a70e9e1b16', 'Battle ropes lunges', 28, 6, 256, 24, 'Intermedio', 'Realiza zancadas mientras mantienes las cuerdas en movimiento. Pueden ser estáticas, alternadas o caminando. El desafío de coordinación es alto. Mantén el torso erguido y las ondas consistentes.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Lunges', 'Perform lunges while keeping the ropes moving. They can be static, alternating or walking. The coordination challenge is high. Keep your torso upright and your waves consistent.', 'external'),
('72f740d2-4250-444c-8ebe-010372de6b64', 'Push Press a una mano con mancuerna', 6, 2, 81, 1, 'Principiante', 'Realiza un press explosivo sobre la cabeza con una sola mancuerna, utilizando las piernas para generar potencia inicial.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'One Hand Dumbbell Push Press', 'Perform an explosive overhead press with a single dumbbell, using your legs to generate initial power.', 'external'),
('7346da1e-a553-4885-90bb-0f08fa651d24', 'Press inclinado kettlebell', 6, 25, 281, 1, 'Avanzado', 'Press overhead mientras te inclinas lateralmente en dirección opuesta. Trabaja el core anti-flexión lateral intensamente. Mantén cadera y hombros cuadrados. Popular en entrenamiento de strongman.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Incline kettlebell Press', 'Press overhead while leaning laterally in the opposite direction. Work the anti-lateral flexion core intensely. Keep your hips and shoulders square. Popular in strongman training.', 'external'),
('738eba83-c427-4cb2-95fd-bd97293afe11', 'Hip Thrust sobre Fitball', 29, 55, 290, 1, 'Intermedio', 'Apoya la parte superior de la espalda en el Fitball. Baja las caderas hacia el suelo y empuja hacia arriba apretando los glúteos hasta alinear el cuerpo.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Hip Thrust on Stability Ball', 'Support your upper back on the Stability Ball. Lower your hips toward the floor and push up, squeezing your glutes until your body is aligned.', 'bodyweight'),
('73abfd11-93f3-438d-aaec-7b9dc444c94e', 'Pullover con mancuerna', 16, 1, 81, 1, 'Intermedio', 'Tumbado, lleva una mancuerna tras la cabeza con brazos casi rectos y vuelve. Objetivo: dorsal y serrato. Cue: codos fijos, no los dobles. Error común: arquear la espalda lumbar excesivamente.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Dumbbell Pullover', 'Lying down, carry a dumbbell behind your head with almost straight arms and return. Target: dorsal and serratus. Cue: fixed elbows, don''t bend them. Common mistake: arching the lumbar back excessively.', 'external'),
('73d8d4c1-17b4-438e-932b-1146dff01470', 'Pasos laterales con minibanda', 37, 29, 61, 1, 'Principiante', 'Coloca una minibanda alrededor de las piernas y realiza pasos laterales controlados. Mantén tensión en la banda, rodillas alineadas y cadera estable.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Miniband Lateral Walks', 'Place a miniband around the legs and perform controlled lateral steps. Keep tension on the band, knees aligned, and hips stable.', 'external'),
('73dfe53a-07a1-471b-802e-2a126376250e', 'Zancada estática pie bosu', 28, 29, 298, 1, 'Avanzado', 'Split squat con pie delantero en bosu. Objetivo: estabilidad. Cue: baja vertical. Error: tambaleo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'BOSU Front-Foot Split Squat', 'Perform a split squat with the front foot on a BOSU. Target: stability. Cue: lower straight down. Common mistake: wobbling.', 'bodyweight'),
('73f8d356-ac8d-4a13-85b5-d83d2d115e98', 'Sentadilla con deslizamiento en pared', 28, 29, 1, 1, 'Principiante', 'Realiza una sentadilla deslizando la espalda contra la pared para guiar el movimiento, asegurando que las rodillas sigan la línea de los pies.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Squat with wall slide', 'Perform a squat by sliding your back against the wall to guide the movement, ensuring that your knees follow the line of your feet.', 'mixed'),
('74010f3a-7d9c-4df9-8d57-a0423097ebdd', 'Frog Pump con pies elevados en Fitball', 29, NULL, 290, 1, 'Principiante', 'Realiza el movimiento de Frog Pump con las plantas de los pies juntas y apoyadas sobre el Fitball para aumentar la inestabilidad y el rango de movimiento.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Frog Pump with Feet Elevated on Stability Ball', 'Perform the Frog Pump movement with the soles of your feet together and resting on the Stability Ball to increase instability and range of motion.', 'bodyweight'),
('744c6d7d-f066-43f3-9243-3e97b6718959', 'Malabares kettlebell', 6, 100, 281, 1, 'Avanzado', 'Lanzamientos y recepciones controladas de kettlebell. Incluye flips, rotaciones y pases. Desarrolla coordinación, timing y fuerza de agarre. Comienza con kettlebell ligera. Requiere espacio y superficie segura.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Juggling', 'controlled kettlebell throws and receptions. Includes flips, rotations and passes. Develops coordination, timing and grip strength. Start with a light kettlebell. Requires space and safe surface.', 'external'),
('74513de3-f39b-4e31-9de1-930178d94ff4', 'Spider Curl con Kettlebell doble', 17, NULL, 281, 1, 'Principiante', 'Realiza un curl de biceps apoyado boca abajo en un banco inclinado utilizando dos pesas rusas para un estimulo de agarre diferente.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Double kettlebell Spider Curl', 'Perform a prone bicep curl on an incline bench using two kettlebells for a different grip stimulus.', 'external'),
('745b4404-e943-4ed3-9ff3-05c900d224ee', 'Máquina aductores cierre controlado', 313, NULL, 186, 1, 'Principiante', 'Cierra piernas sentado. Cue: controla apertura. Error: movimientos rápidos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Adductor Controlled Closure Machine', 'Close your legs while sitting. Cue: control the opening phase. Common mistake: rapid movements.', 'external'),
('749fbc0d-8ad2-4639-8ab2-04aba803047f', 'Squat thrust', 13, NULL, 1, 1, 'Intermedio', 'Desde posición de pie, desciende a sentadilla y coloca las manos en el suelo. Salta con ambos pies hacia atrás a posición de plancha en un movimiento explosivo. Inmediatamente salta con los pies de vuelta hacia las manos y levántate. Es similar al burpee pero sin flexión ni salto final.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat thrust', 'From a standing position, lower yourself into a squat and place your hands on the floor. Jump both feet back into a plank position in an explosive movement. Immediately jump your feet back toward your hands and stand up. It is similar to the burpee but without push-ups or final jumps.', 'mixed'),
('74ac50f3-eac2-4947-b0a3-8fda4bc64ac6', 'Zancada con salto y cambio de altura', 28, 29, 1, 1, 'Avanzado', 'Salta desde el suelo para aterrizar en zancada sobre un escalón o banco bajo. Potencia de elevación. Rodilla alineada. Evita movimientos inestables del pie.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Jump Lunge to Elevated Landing', 'Jump from the floor and land in a lunge on a low box or bench. Target: explosive elevation. Cue: keep the knee aligned. Common mistake: unstable foot movement on landing.', 'mixed'),
('74b0c425-1d99-4f7c-afbd-3dd52b2fa02e', 'Envión barra', 13, NULL, 116, 1, 'Avanzado', 'Levantamiento olímpico de dos fases: primero una cargada para llevar la barra a los hombros, seguida de un jerk (empuje) para llevarla sobre la cabeza. El jerk puede ser split (tijera) o power (pies paralelos). Requiere potencia, coordinación y técnica excepcionales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar clean', 'Two-phase Olympic lifting: first a clean to bring the bar to the shoulders, followed by a jerk (push) to bring it over the head. The jerk can be split (scissors) or power (feet parallel). Requires exceptional power, coordination and technique.', 'external'),
('74b2dde1-43b5-4ce2-8480-45aeb87b5008', 'Goblet squat', 28, 29, 1, 1, 'Principiante', 'Sentadilla con patrón goblet sin carga (o mínima) para calentar cadera/rodilla y practicar profundidad con control.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Goblet squat', 'Squat with goblet pattern without load (or minimal) to warm up hip/knee and practice depth with control.', 'mixed'),
('754a70c6-88f7-426d-bcc6-2003582e1819', 'Rollout de pie con barra', 25, 71, 116, 1, 'Avanzado', 'Desde posicion de pie, desplaza la barra hacia adelante extendiendo el cuerpo por completo hasta quedar cerca del suelo y regresa.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Standing Barbell Rollout', 'From a standing position, move the bar forward, extending your body completely until you are close toward the floor and return.', 'external'),
('758f4763-9993-4693-a881-9eadd8148b0d', 'Golpeo una pierna balón medicinal', 25, 29, 240, 1, 'Avanzado', 'Slam ball parado en una pierna. Desafío extremo de equilibrio y estabilización. Mantén la rodilla de apoyo ligeramente flexionada. Alterna piernas. El core debe trabajar intensamente para mantener estabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I hit a medicine ball leg', 'Slam ball standing on one leg. Extreme balance and stabilization challenge. Keep your supporting knee slightly bent. Alternate legs. The core must work intensely to maintain stability.', 'external'),
('75a8a86f-37a8-485e-8995-f183a603b52e', 'Zancada frontal mancuernas', 28, 29, 81, 1, 'Principiante', 'Paso adelante con pesas. Objetivo: cuádriceps. Cue: rodilla 90 grados. Error: levantar talón.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Dumbbell Forward Lunge', 'Step forward with dumbbells in your hands. Target: quadriceps. Cue: both knees near 90 degrees. Common mistake: lifting the front heel.', 'external'),
('75ae55c2-f790-4c54-9a7c-1b15c32236b0', 'Escaladores lentos controlados', 25, 6, 1, 24, 'Principiante', 'Rodilla a codo manteniendo 2 segundos. Objetivo: core estable. Cues: no muevas cadera. Error común: elevar glúteo.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Controlled Slow Climbers', 'Knee to elbow holding for 2 seconds. Target: stable core. Cue: don''t move your hips. Common mistake: raising glutes.', 'bodyweight'),
('75cb1f33-b763-4166-9e73-67d7160c0c13', 'Hollow Body Hold con banda elástica', 25, NULL, 61, 24, 'Intermedio', 'Realiza un Hollow Body mientras tiras de una banda elástica anclada detrás de ti, forzando una mayor contracción abdominal.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Hollow Body Hold with elastic band', 'Perform a Hollow Body while pulling on an elastic band anchored behind you, forcing a greater abdominal contraction.', 'external'),
('75cd62f1-1af7-4a06-bf6b-fc16f44037d4', 'Halo alterno con Kettlebell', 6, 2, 281, 1, 'Principiante', 'Sostén la pesa rusa por los cuernos boca abajo. Haz círculos controlados alrededor de tu cabeza, manteniendo el core firme.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternate Halo with Kettlebell', 'Hold the kettlebell by the horns upside down. Make controlled circles around your head, keeping your core tight.', 'external'),
('75de208a-6ded-452c-bdf0-ce4fd8a65a2e', 'Jalón al pecho sentado en suelo con cable a una mano', 71, 17, 151, 1, 'Intermedio', 'Siéntate en el suelo. Tira de la polea alta con una mano hacia el costado, maximizando el rango de movimiento y el estiramiento del dorsal.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Seated floor chest pull with one-hand cable', 'Sit on the floor. Pull the high cable with one hand to the side, maximizing range of motion and lat stretch.', 'external'),
('76001fc6-39c4-466f-afea-e699ee218671', 'Zancada atrás con déficit', 29, 28, 1, 1, 'Intermedio', 'Desde escalón hacia atrás. Objetivo: mayor rango glúteo. Cue: baja controlado. Error: desequilibrio.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Deficit Reverse Lunge', 'Step back from an elevated platform. Target: greater glute range of motion. Cue: lower under control. Common mistake: losing balance.', 'mixed'),
('7603f63f-be6c-4a58-b7f0-da2a7aa876d6', 'TRX Chest Fly', 1, 6, 216, 1, 'Avanzado', 'Inclinado adelante, abre los brazos lateralmente sujetando los agarres de TRX. Objetivo: pectoral con inestabilidad. Cue: cuerpo rígido en todo momento. Error común: flexionar demasiado los codos convirtiéndolo en un press.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'TRX Chest Fly', 'Lean forward while holding the TRX handles and open your arms out to the sides. Target: chest under instability. Cue: keep your body rigid throughout. Common mistake: bending the elbows too much and turning it into a press.', 'bodyweight'),
('7658c5d0-2587-44ae-a11f-edeacfd4efb3', 'Slam ball', 25, 6, 240, 1, 'Intermedio', 'Eleva el balón sobre la cabeza y golpéalo contra el suelo con máxima fuerza. Recógelo al rebotar y repite. Ejercicio de cuerpo completo que desarrolla potencia y es excelente para liberar estrés. Usa las piernas y el core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Slam Ball', 'Raise the ball over your head and hit it against the ground with maximum force. Pick it up as it bounces and repeat. Full body exercise that builds power and is great for releasing stress. Use your legs and core.', 'external'),
('767c497e-e210-434d-b9bd-1ec500892ec7', 'Dislocaciones de hombro prono con banda', 6, NULL, 61, 1, 'Principiante', 'Tumbado boca abajo, sujeta la banda y pasala desde tus gluteos hasta por delante de tu cabeza sin que los brazos toquen el suelo.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Banded Prone Shoulder Dislocations', 'Lying face down, hold the band and pass it from your buttocks to in front of your head without your arms touching the floor.', 'external'),
('7684725c-cbd5-43c5-8763-dbb69b39ec20', 'Kettlebell Swing unilateral', 29, 71, 281, 1, 'Intermedio', 'Swing a una mano. Objetivo: potencia y core. Cue: cambio brazo en aire. Error: rotar hombro.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Unilateral Kettlebell Swing', 'One hand swing. Target: power and core. Cue: change arm in air. Common mistake: rotate shoulder.', 'external'),
('7692f01b-eb1a-467e-ac6f-7513e87cb665', 'Curl excéntrico de isquiotibiales a una pierna con Slider', 55, 29, 1, 1, 'Intermedio', 'En posición de puente a una pierna, desliza el talón lentamente hacia adelante sobre el slider controlando el descenso hasta estirar la pierna por completo.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'One-Leg Eccentric Hamstring Curl with Slider', 'In a single-leg bridge position, slide your heel slowly forward on the slider, controlling the descent until your leg is fully extended.', 'bodyweight'),
('76a867a9-c370-40ad-9854-7b0f882702ae', 'Sentadilla Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sentadilla profunda manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, requiere un control absoluto de la estabilidad.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double kettlebell Bottoms Up Overhead Squat', 'Deep squat keeping two inverted kettlebells locked overhead requires absolute control of stability.', 'external'),
('76a991ff-9ae2-4b69-8577-b5e5db483421', 'Push Jerk con Kettlebell doble', 6, 28, 281, 1, 'Avanzado', 'Impulsa dos pesas rusas con las piernas y métete debajo flexionando las rodillas de nuevo para recibirlas con brazos bloqueados.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double kettlebell Push Jerk', 'Push two kettlebells with your legs and get under them, bending your knees again to receive them with locked arms.', 'external'),
('76aae0e2-8d2b-4785-99fe-8d2a90ac1794', 'Cruz de hierro', 6, 1, 1, 24, 'Avanzado', 'En anillas, mantén el cuerpo vertical con brazos extendidos horizontalmente formando una cruz. Elemento clásico de gimnasia en anillas. Requiere fuerza excepcional y preparación específica de tejido conectivo. Progresa con asistencias.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Iron Cross', 'In rings, keep your body vertical with arms extended horizontally forming a cross. Classic ring gymnastics element. Requires exceptional strength and specific connective tissue preparation. Progress with assists.', 'bodyweight'),
('76ea1bcb-ad23-4e1c-a0ac-a9e01b120342', 'Zancadas laterales dinámicas', 29, 313, 1, 1, 'Principiante', 'Desplázate a un lado bajando la cadera y vuelve al centro. Cue: pierna estirada firme. Error: inclinar el torso lateralmente.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dynamic Lateral Lunges', 'Move to one side by lowering your hip and return to center. Cue: keep the straight leg firm. Common mistake: leaning your torso to the side.', 'mixed'),
('770a0099-7b86-4062-a037-3639273ca2fe', 'Sentadilla cosaca alterna Front Rack con mancuernas', 28, 29, 81, 1, 'Principiante', 'Realiza sentadillas laterales alternas sosteniendo dos mancuernas en posicion de rack sobre los hombros.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Front Rack Alternating Cossack Squat with Dumbbells', 'Perform alternating side squats holding two dumbbells in a rack position on your shoulders.', 'external'),
('770a81bd-4aa7-40e2-91ac-9d8bc26859ba', 'Extensión tríceps polea barra recta', 2, NULL, 151, 1, 'Principiante', 'Empuja barra hacia abajo bloqueando codos. Cue: codos pegados al cuerpo. Error: mover hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Straight Bar Cable Triceps Extension', 'Push bar down while locking elbows. Cue: elbows close to the body. Common mistake: move shoulders.', 'external'),
('7717c59f-81fd-4871-a1aa-ad8580312ed8', 'Press hombros sentado neutro mancuernas', 6, 2, 81, 1, 'Principiante', 'Palmas enfrentadas, empuja pesas arriba. Cue: codos al frente. Error: chocar pesas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Neutral Seated Dumbbell Shoulder Press', 'Palms facing each other, push weights up. Cue: elbows forward. Common mistake: colliding weights.', 'external'),
('7752875b-baff-49f5-a847-d05703009f7b', 'Sentadilla patinadora con Kettlebell (Horn Grip)', 28, 29, 281, 1, 'Avanzado', 'Sujeta la Kettlebell por los cuernos frente al pecho y baja en sentadilla sobre una pierna, manteniendo el torso erguido y equilibrio.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Kettlebell Skate Squat (horn Grip)', 'Hold the kettlebell by the horns in front of your chest and lower yourself into a squat on one leg, keeping your torso upright and balanced.', 'external'),
('7757754c-0b0c-49d7-8e89-fd7f84ed9b79', 'Superman brazos estirados', 71, 29, 1, 1, 'Principiante', 'Boca abajo, eleva pecho y piernas del suelo simultáneamente. Objetivo: erectores espinales. Cue: mira hacia el suelo para proteger el cuello. Error común: realizar movimientos bruscos o tirones de cabeza.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Superman Arms Extended', 'Lie face down and lift your chest and legs off the floor at the same time. Target: spinal erectors. Cue: look toward the floor to keep your neck neutral.', 'bodyweight'),
('778d98af-f001-447d-9be3-0943e5287d1f', 'Thruster Ciclista alterno con Kettlebell doble', 28, 6, 281, 1, 'Intermedio', 'Ejecuta una sentadilla con talones elevados y, al subir, realiza un press vertical alternando el brazo que empuja en cada repeticion.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Alternating Cyclist Double Kettlebell Thruster', 'Perform a heels-elevated squat and, as you stand up, alternate the arm that presses overhead on each repetition.', 'external'),
('779b34a8-91d9-416f-bca6-455c5f3d5a47', 'Peso muerto deficitario barra', 55, 29, 116, 1, 'Avanzado', 'Realiza el peso muerto convencional desde una plataforma elevada de 5-10 cm. Este déficit aumenta el rango de movimiento y la dificultad del ejercicio. Requiere mayor movilidad y fuerza en la posición inicial. Excelente para mejorar la fuerza desde el suelo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Deficit Deadlift', 'Perform the conventional deadlift from a 5-10 cm raised platform. This deficit increases the range of motion and the difficulty of the exercise. Requires greater mobility and strength in the starting position. Excellent for improving strength from the ground.', 'external'),
('779dab4a-d6be-4966-b781-d73091213231', 'Thruster con mancuerna a un brazo', 28, 6, 81, 1, 'Intermedio', 'Realiza un Thruster (sentadilla + press) sosteniendo una sola mancuerna en un lado, manteniendo el equilibrio del core.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Single-Arm Dumbbell Thruster', 'Perform a thruster with a single dumbbell held on one side, maintaining balance and core stability throughout the movement.', 'external'),
('77cebf45-71b1-456f-b47b-756891e6654c', 'Swing alterno con Kettlebell a una mano', 29, 25, 281, 1, 'Intermedio', 'Realiza un swing con un solo brazo e intercambia la pesa rusa de mano en el punto mas alto del arco, frente al rostro, manteniendo el ritmo.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Alternating Single-Arm Kettlebell Swing', 'Perform a single-arm swing and switch the kettlebell from hand to hand at the highest point of the arc in front of your face, maintaining the rhythm.', 'external'),
('77d9f84c-8c1d-465e-82d7-1247d9b3bad1', 'Puente de glúteo con marcha', 29, 25, 1, 1, 'Intermedio', 'En puente de glúteo, eleva una pierna y luego la otra sin bajar la cadera. Cue: estabilidad de pelvis. Error: que la cadera caiga al levantar un pie.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Gaited Glute Bridge', 'In the gluteal bridge, raise one leg and then the other without lowering your hips. Cue: pelvic stability. Common mistake: the hip drops when lifting one foot.', 'mixed'),
('77f7bdd3-41f9-4477-8207-05183160d4ca', 'Curl bíceps barra agarre estrecho', 17, NULL, 116, 1, 'Principiante', 'Flexiona barra manos juntas para cabeza larga. Cue: codos fijos. Error: balancear el torso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Bicep Curl Bar Close Grip', 'Flex bar hands together for long head. Cue: keep your elbows fixed. Common mistake: swinging the torso.', 'external'),
('77f94dc1-be9e-411f-96d2-e3ffd4d65ead', 'Ring Eccentric Chin Up', 71, 17, 1, 1, 'Principiante', 'Con agarre supino (palmas hacia ti), salta a la posición superior. Baja lentamente controlando el descenso hasta estirar los brazos.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Eccentric Chin Up', 'With an underhand grip (palms facing you), jump to the top position. Go down slowly, controlling your descent until your arms are straight.', 'mixed'),
('782c0c6c-0b88-43e1-b4da-c9db0148db90', 'Aperturas declinadas mancuerna', 1, NULL, 81, 1, 'Intermedio', 'Abre brazos banco declinado. Objetivo: pecho inferior. Cue: controla apertura. Error: chocar pesas.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Decline Dumbbell Flyes', 'Perform the movement on a decline bench. Target: lower chest. Cue: control the opening phase. Common mistake: letting the dumbbells collide at the top.', 'external'),
('783e6de0-dd60-4e71-ac59-52a8613daf30', 'Sentadilla sumo', 29, 28, 1, 1, 'Principiante', 'Adopta una postura más amplia que el ancho de los hombros con los pies apuntando hacia afuera en un ángulo de 45 grados. Desciende manteniendo las rodillas alineadas con las puntas de los pies. Esta variación enfatiza más el trabajo de glúteos y aductores. Mantén el torso erguido durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Sumo Squat', 'Assume a shoulder-width stance with your feet pointing outward at a 45-degree angle. Descend keeping your knees aligned with the balls of your feet. This variation emphasizes more the work of the glutes and adductors. Keep your torso upright throughout the movement.', 'mixed'),
('784a57da-d944-4a67-aee6-1c980d86f8da', 'Russian Twist con Kettlebell', 25, NULL, 281, 1, 'Principiante', 'Sentado con rodillas flexionadas, gira el torso de lado a lado moviendo una Kettlebell frente al abdomen sin tocar el suelo.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Russian Twist with Kettlebell', 'Sitting with knees bent, rotate your torso from side to side moving a kettlebell in front of your abs without touching the floor.', 'external'),
('7851f266-2ae8-4fcd-8220-54d71d65323b', 'Aducción de cadera tumbado lateral', 313, 25, 1, 1, 'Principiante', 'Tumbado de lado, eleva la pierna inferior cruzando por delante de la superior. Objetivo: fuerza de aductores. Cue: mantén el cuerpo alineado. Error común: doblar la rodilla de la pierna activa.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Side Lying Hip Adduction', 'Lying on your side, raise your lower leg crossing in front of the upper leg. Target: adductor strength. Cue: keep your body aligned. Common mistake: bending the knee of the active leg.', 'bodyweight'),
('786be329-a465-4141-b887-83ab0847d181', 'Zancada inversa alterna en TRX', 28, 29, 216, 1, 'Principiante', 'Sujeta el TRX y da un paso largo hacia atrás bajando la rodilla trasera hacia el suelo. Alterna de pierna en cada repetición.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Alternate reverse stride on TRX', 'Hold the TRX and take a long step back by lowering your rear knee to the floor. Alternate legs in each repetition.', 'bodyweight'),
('789d6817-95ca-4d52-86c4-d30fb567f426', 'Escalador balón medicinal', 25, 6, 240, 1, 'Avanzado', 'Mountain climbers con manos sobre balón medicinal. La inestabilidad multiplica el trabajo del core. Mantén el balón estable mientras alternas rodillas. Velocidad controlada para mantener forma correcta.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Medicine Ball Mountain Climber', 'Mountain climbers with hands on medicine ball. Instability multiplies the core work. Keep the ball stable while alternating knees. controlled speed to maintain correct form.', 'external'),
('78a7a4d6-4b32-4376-89b3-93848de6af8f', 'Tríceps pushdown con barra', 2, NULL, 151, 1, 'Principiante', 'Empuja la barra de la polea hacia abajo bloqueando los codos. Objetivo: aislamiento del tríceps. Cue: mantén el pecho alto y hombros atrás. Error común: usar el peso del cuerpo para empujar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Bar Triceps Pushdown', 'Push the cable bar downward while keeping your elbows pinned in place. Target: triceps isolation. Cue: keep your chest up and shoulders back. Common mistake: using body weight to force the movement.', 'external'),
('78e5e76f-ff40-4113-99c5-5b6f5e54d588', 'Puente de Glúteo con pies elevados', 29, 55, 1, 1, 'Principiante', 'Acuéstate con los talones en un banco. Eleva la cadera hacia el techo apretando los glúteos y baja de forma controlada.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Glute Bridge with Elevated Feet', 'Lie with your heels on a bench. Raise your hips toward the ceiling, squeezing your glutes, and lower yourself in a controlled manner.', 'mixed'),
('78f058eb-afb0-4ef8-939d-9854340d6fdc', 'Press Overhead Seesaw medio arrodillado con mancuernas', 6, 2, 81, 1, 'Intermedio', 'En posición de caballero, alterna el press vertical con mancuernas, utilizando el core para evitar cualquier balanceo lateral del torso.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Half Kneeling Dumbbell Overhead Seesaw Press', 'In a half-kneeling position, alternate the vertical press with dumbbells, using your core to avoid any lateral swing of the torso.', 'external'),
('78f40a83-3c22-4aee-ab39-d5b4d9f7f5f5', 'Dumbbell Crush Grip Otis Up', 25, 1, 81, 1, 'Intermedio', 'Acuéstate sosteniendo una mancuerna con ambas manos contra el pecho (apretándola). Realiza un sit-up completo y presiona la mancuerna hacia arriba al final del movimiento.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Dumbbell Crush Grip Otis Up', 'Lie down holding a dumbbell with both hands against your chest (squeezing it). Perform a full sit-up and press the dumbbell up at the end of the movement.', 'external'),
('79037792-e636-42a6-b4a7-3fbc9bd486e5', 'Zancada de péndulo', 28, 29, 1, 1, 'Intermedio', 'Realiza una zancada frontal y, sin apoyar el pie al volver, pasa directamente a una zancada trasera. Objetivo: equilibrio y fuerza de piernas. Cues: torso erguido en todo el recorrido. Error común: movimientos rápidos y descontrolados.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Pendulum Lunge', 'Perform a forward lunge and, without setting the foot down when you return, flow directly into a reverse lunge. Target: balance and leg strength. Cue: keep your torso upright throughout. Common mistake: moving too fast and losing control.', 'mixed'),
('79211d39-f918-4fd0-8e45-f28e88a5c4e1', 'Remo máquina agarre supinado dorsal', 71, 17, 186, 1, 'Principiante', 'Tira hacia abdomen palmas arriba. Cue: codos pegados. Error: encoger trapecios.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Rowing Machine Supinated Dorsal Grip', 'Pull towards abs, palms up. Cue: elbows stuck together. Common mistake: shrink trapezoids.', 'external'),
('7929e200-80e7-4484-adfa-ea9097877a30', 'Puente de glúteo a una pierna', 29, 55, 1, 1, 'Intermedio', 'Acuéstate con una rodilla doblada y la otra pierna estirada en el aire. Empuja con el talón apoyado para elevar la cadera usando solo un glúteo.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'One leg glute bridge', 'Lie down with one knee bent and the other leg stretched in the air. Push with your heel supported to raise your hips using only one glute.', 'mixed'),
('793ba3a8-46dd-4742-8165-898633ae70e7', 'Zancada lateral Overhead con Slider y Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Sostén dos Kettlebells bloqueadas sobre la cabeza y desliza un pie lateralmente sobre un slider, bajando la cadera con control absoluto.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Overhead side stride with Slider and Double Kettlebell', 'Hold two locked Kettlebells over your head and slide one foot sideways over a slider, lowering your hip with absolute control.', 'external'),
('793d2816-a09d-434f-b1c7-59e800d9ae2f', 'Plank lateral con mancuerna', 25, 6, 81, 24, 'Intermedio', 'En posición de Plank lateral, sostén una mancuerna con el brazo libre extendido hacia el techo. Mantén la posición estable y las caderas elevadas.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Side Plank with Dumbbell', 'In a Side Plank position, hold a dumbbell with your free arm extended toward the ceiling. Keep your position stable and your hips raised.', 'external'),
('7998ce21-1b86-4e31-b612-5c82b8ebbc75', 'Salto vertical con lanzamiento de balón', 13, 6, 240, 1, 'Intermedio', 'Salta buscando altura y lanza el balón hacia arriba simultáneamente. Potencia total. Aterrizaje suave. No pierdas de vista el balón.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Vertical jump with ball throw', 'Jump for height and throw the ball upwards simultaneously. Total power. Soft landing. Don''t lose sight of the ball.', 'external'),
('799959de-c667-48d8-95e2-f2436487ff80', 'Zancada con rotación de balón', 25, 28, 240, 1, 'Principiante', 'Realiza una zancada y gira el balón hacia el lado de la pierna adelantada. Coordinación. Espalda erguida. No dejes que la rodilla baile.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Lunge with Medicine Ball Rotation', 'Perform a lunge and rotate the ball toward the side of the front leg. Cue: keep your torso tall. Common mistake: letting the front knee wobble.', 'external'),
('79aec148-b057-4598-aa7c-537ae69ac7da', 'Slam de martillo en postura escalonada', 25, 6, 1, 1, 'Principiante', 'Con un pie delante del otro, golpea un neumatico con un martillo pesado usando un movimiento de arco completo, activando el core y los hombros.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Hammer slam in staggered stance', 'With one foot in front of the other, hit a tire with a heavy hammer using a full arc motion, activating your core and shoulders.', 'bodyweight');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('79c85823-3ebb-440f-acdd-c6e4dc8defc8', 'Curl bíceps invertido barra', 100, 17, 116, 1, 'Intermedio', 'Flexiona barra palmas abajo. Objetivo: antebrazo. Cue: agarre firme. Error: mucho peso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Barbell Inverted Biceps Curl', 'Flex bar palms down. Target: forearm. Cue: firm grip. Common mistake: too much weight.', 'external'),
('79c97c65-7378-4ebf-bb5d-ce96d1696f83', 'Battle ropes figure 8', 6, 25, 256, 24, 'Intermedio', 'Crea patrones en forma de ocho con las cuerdas. Requiere coordinación y control del movimiento. Puede hacerse vertical u horizontalmente. Mantén el patrón amplio y fluido para máxima efectividad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Ropes Figure-8', 'Create figure-eight patterns with the ropes. It requires coordination and control. It can be done vertically or horizontally. Keep the pattern wide and fluid for maximum effectiveness.', 'external'),
('79f46dda-fde0-40f1-bc77-da8d9d41cddd', 'Peso muerto rumano en Landmine', 55, 29, 116, 1, 'Principiante', 'De pie frente al extremo de la barra, inclina el torso hacia adelante empujando la cadera atrás para trabajar los isquiotibiales con un peso guiado.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Landmine Romanian Deadlift', 'Stand facing the loaded end of the bar and hinge your torso forward, pushing your hips back to work the hamstrings with a guided load.', 'external'),
('7a0552b2-63c8-49b9-86ee-38729674818c', 'Press de hombros a una mano en Landmine', 6, 2, 116, 1, 'Intermedio', 'Sujeta el extremo de la barra sobre un hombro y presiona hacia adelante y arriba en arco siguiendo la trayectoria natural de la barra.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'One Hand Shoulder Press in Landmine', 'Hold the end of the bar over one shoulder and press forward and up in an arc following the natural path of the bar.', 'external'),
('7a0ebb8b-9b67-4e38-b6a5-1b7ca9c873a2', 'Press Z alterno (Seesaw) con Kettlebell', 6, 25, 281, 1, 'Avanzado', 'Sentado en el suelo, realiza un press alterno continuo (uno sube, otro baja) manteniendo el tronco rígido y sin arquear la espalda.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternate Z Press (seesaw) with Kettlebell', 'Sitting on the floor, perform a continuous alternating press (one goes up, the other goes down) keeping your torso rigid and without arching your back.', 'external'),
('7a141405-d610-4b5e-a14f-df97883b115c', 'Power Snatch a una mano con mancuerna', 29, 6, 81, 1, 'Intermedio', 'Lleva una mancuerna desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, usando la potencia de las piernas.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Power Snatch with Dumbbell', 'Lift a dumbbell from the floor to overhead in a single explosive movement, using the power of your legs.', 'external'),
('7a21316c-9d02-43bf-b544-f594aaf3cb41', 'Press Z alterno con Kettlebell', 6, 25, 281, 1, 'Avanzado', 'Sentado en el suelo con piernas en V, realiza press de hombros alternando brazos, manteniendo el torso perfectamente vertical.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternate Z Press with Kettlebell', 'Sitting on the floor with legs in a V, perform shoulder presses alternating arms, keeping your torso perfectly vertical.', 'external'),
('7a653e30-eb21-4f60-9137-aef96df16655', 'Superman', 71, 29, 1, 1, 'Principiante', 'Túmbate boca abajo con brazos extendidos al frente. Simultáneamente eleva el pecho, brazos y piernas del suelo contrayendo la espalda baja y glúteos. Mantén la posición por un segundo mirando al suelo para no hiperextender el cuello. Desciende controladamente y repite.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Superman', 'Lie face down with your arms extended in front of you. Lift your chest, arms, and legs off the floor at the same time by contracting your posterior chain.', 'bodyweight'),
('7a68eea8-6138-4fb1-9df6-c9c681d0626d', 'Remo a una mano a press rotacional en Landmine', 6, 2, 116, 1, 'Intermedio', 'Rema la barra hacia tu costado y, en un movimiento fluido, gira el cuerpo para terminar presionando la carga sobre la cabeza.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-hand row to rotational press in Landmine', 'Row the bar to your side and, in one fluid movement, twist your body to finish by pressing the load overhead.', 'external'),
('7a8f22e0-f24f-43fd-9c36-4daf6cf4a350', 'Press de pecho en máquina', 1, 2, 186, 1, 'Principiante', 'Sentado, empuja los agarres hacia adelante. Control total. Cue: mantén escápulas retraídas contra el banco. Error: despegar hombros al empujar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Machine Chest Press', 'Sitting, push your grips forward. Full control. Cue: keep scapulae retracted against the bench. Common mistake: taking shoulders off when pushing.', 'external'),
('7acb3a77-e350-4d26-beb7-c29f635077de', 'Remo Pendlay a una mano con Kettlebell', 71, 17, 281, 1, 'Intermedio', 'Con el torso paralelo al suelo, levanta explosivamente la pesa rusa desde el suelo hacia la cadera y regrésala a una parada muerta.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Pendlay kettlebell Row', 'With your torso parallel to the floor, explosively lift the kettlebell from the floor toward your hips and return to a dead stop.', 'external'),
('7adcb5d1-2898-47c8-826c-87010b5c9ade', 'Remo prono con mancuernas', 71, 17, 81, 1, 'Intermedio', 'Acuéstate boca abajo en un banco plano o ligeramente inclinado. Rema las mancuernas hacia arriba contrayendo la espalda.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Dumbbell Prone Row', 'Lie face down on a flat or slightly inclined bench. Row the dumbbells up by contracting your back.', 'external'),
('7ae257a3-bf9c-46b6-b40c-5c395c0e1ed7', 'Rodamiento lateral', 25, NULL, 271, 1, 'Avanzado', 'Rueda en ángulo diagonal de 45 grados hacia cada lado. Enfatiza oblicuos mientras mantiene trabajo del recto abdominal. Controla el retorno al centro. Mantén caderas cuadradas para maximizar el trabajo lateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Side bearing', 'Roll at a 45-degree diagonal angle to each side. Emphasizes obliques while maintaining rectus abdominis work. Control the return to the center. Keep hips square to maximize lateral work.', 'external'),
('7aeb3023-7574-4328-811e-70527cad2b97', 'Swing un brazo', 29, 25, 281, 1, 'Avanzado', 'Swing con una sola mano aumentando el desafío anti-rotación. Permite mayor rango de movimiento. El brazo libre puede estar extendido para balance. Alterna manos cada serie o dentro de la serie.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Arm Swing', 'Perform a swing with one hand to increase the anti-rotation challenge. It allows a greater range of motion. The free arm can stay extended for balance. Alternate hands each set or within the set.', 'external'),
('7bcfdcdf-17c6-4da6-b4b7-b7caec119318', 'Plancha lateral con pierna elevada', 37, 25, 1, 24, 'Intermedio', 'En plancha lateral, sube y baja la pierna superior. Estabilidad y fuerza. Cadera alta. No dejes caer el cuerpo adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Side Plank with Leg Raise', 'In a side plank, raise and lower the top leg under control. Builds stability and strength. Keep your hips high. Do not let your body fall forward.', 'bodyweight'),
('7bdb28a2-b0a1-4740-8a9d-b27d42182c8f', 'Face Pull con cable', 6, 71, 151, 1, 'Principiante', 'De pie frente a la polea alta con cuerda, tira de los extremos hacia la cara separando las manos y rotando los hombros externamente.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Wired Face Pull', 'Standing in front of the high rope cable, pull the ends toward your face by spreading your hands apart and externally rotating your shoulders.', 'external'),
('7bdfb502-306e-4382-9198-07cda9fa6863', 'Aperturas inclinadas 30 grados', 1, 6, 81, 1, 'Intermedio', 'Abre brazos en banco inclinado suave. Cue: codos flexionados. Error: chocar pesas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', '30 Degree Inclined Openings', 'Perform the movement on a low incline bench. Cue: elbows bent. Common mistake: colliding weights.', 'external'),
('7bedcfcd-ac74-4ae3-b9dd-0cb9189bdde6', 'Remo un brazo cable', 16, 25, 151, 1, 'Avanzado', 'Remo unilateral permitiendo rotación controlada del torso. Más funcional que remo estricto. La rotación debe venir del core, no de impulso. Excelente para deportes de raqueta y artes marciales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I row one arm cable', 'Unilateral row allowing controlled rotation of the torso. More functional than strict rowing. The rotation should come from the core, not momentum. Excellent for racket sports and martial arts.', 'external'),
('7c043ada-815d-4b19-b7cf-f218dc0bbdaa', 'Posición L en anillas', 25, NULL, 1, 24, 'Avanzado', 'Mantén posición de L-sit en anillas. La inestabilidad añade dificultad significativa comparado con paralelas. Requiere fuerza de core y estabilización de hombros. Progresa desde L-sit en paralelas o suelo primero.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'L position on rings', 'Maintain L-sit position on rings. Instability adds significant difficulty compared to parallel. Requires core strength and shoulder stabilization. Progress from L-sit on parallel bars or floor first.', 'bodyweight'),
('7c39058e-4149-45e4-bfba-8a78a82e9679', 'Woodchoppers cable', 25, NULL, 151, 1, 'Intermedio', 'Con polea alta o baja, realiza un movimiento diagonal de rotación como si cortaras leña. Involucra todo el core con énfasis en oblicuos. Mantén los brazos relativamente extendidos y rota desde el torso, no solo los brazos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Woodchoppers', 'Using a high or low cable, perform a diagonal rotational movement as if chopping wood. It works the entire core with an emphasis on the obliques. Keep your arms relatively extended and rotate from the torso, not just the arms.', 'external'),
('7c7a058e-2e5f-4420-80f1-0ff6585363f0', 'Sentadilla hack', 28, 29, 186, 1, 'Intermedio', 'En la máquina hack, con la espalda apoyada en el respaldo inclinado, realiza sentadillas. Esta posición reduce el estrés en la espalda baja mientras mantiene alta activación de cuádriceps. Varía la posición de pies para diferentes énfasis.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hack Squat', 'On the hack machine, with your back resting on the inclined backrest, perform squats. This position reduces stress on the lower back while maintaining high quadriceps activation. Vary foot position for different emphasis.', 'external'),
('7c7facbf-3e32-463d-9552-e159344a1e1d', 'Power Clean a Press de hombros con barra', 13, 6, 116, 1, 'Avanzado', 'Realiza una cargada de potencia (Clean) para llevar la barra a los hombros y termina con un press militar por encima de la cabeza.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Power Clean to Barbell Shoulder Press', 'Perform a power clean (Clean) to bring the bar to your shoulders and finish with an overhead military press.', 'external'),
('7c937659-1b65-4230-8254-23c8ccbe1fb0', 'Crunch en polea alta', 25, NULL, 151, 1, 'Intermedio', 'De rodillas, sujeta la cuerda tras la nuca y flexiona el torso hacia el suelo. Objetivo: abdominales con carga. Cue: exhala al bajar y aprieta el core. Error común: tirar del cable con los brazos.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'High Cable Crunch', 'On your knees, hold the rope behind your neck and bend your torso toward the floor. Target: abs under load. Cue: exhale on the way down and tighten your core. Common mistake: pulling the cable with your arms.', 'external'),
('7c94e492-8027-4aae-880d-df2688abcbb3', 'Peso muerto mancuernas', 55, 29, 81, 1, 'Intermedio', 'Con una mancuerna en cada mano frente a los muslos, inclínate desde las caderas manteniendo la espalda recta y las rodillas ligeramente flexionadas. Desciende las mancuernas cerca de las piernas hasta sentir estiramiento en isquiotibiales. Vuelve arriba contrayendo glúteos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Deadlift', 'Hold a dumbbell in each hand in front of your thighs, hinge at the hips while keeping your back straight and your knees slightly bent, and lower the dumbbells close to your legs until you feel a stretch in your hamstrings. Return by contracting your glutes.', 'external'),
('7cb2c054-3696-42f2-a684-53306b4d53f1', 'Sentadilla trasera Sumo con barra', 29, 313, 116, 1, 'Principiante', 'Realiza una sentadilla con la barra tras la nuca y una apertura de pies ancha, enfatizando el trabajo en los aductores y glúteos.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Barbell Sumo Back Squat', 'Perform a squat with the bar behind the neck and open your feet wide, emphasizing work on the adductors and glutes.', 'external'),
('7ccb4d55-1b09-40ca-8a59-e2861ef05d0b', 'Sentadilla cosaca con kettlebell', 28, 313, 281, 1, 'Intermedio', 'Con la pesa al pecho, desciende hacia un lado manteniendo la otra pierna estirada y el talón en el suelo. Objetivo: fuerza unilateral y movilidad de cadera. Cues: pecho alto y rodilla alineada con el pie. Error común: levantar el talón de la pierna de apoyo.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Cossack Squat with Kettlebell', 'With the weight on your chest, lower yourself to one side, keeping your other leg straight and your heel on the floor. Target: unilateral strength and hip mobility. Cue: chest high and knee in line with the foot. Common mistake: lifting the heel of the supporting leg.', 'external'),
('7cea55ec-6545-4d2d-9f4a-332694fcaa21', 'TRX Sentadilla a una pierna (Pistol)', 28, 29, 216, 1, 'Intermedio', 'Sujeta los agarres para equilibrio y realiza una sentadilla profunda con una pierna. Espalda recta. Rodilla alineada. No despegues el talón del suelo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Single-Leg Squat (Pistol)', 'Hold the handles for balance and perform a deep single-leg squat. Keep your back straight, your knee aligned, and your heel on the floor.', 'mixed'),
('7d18da46-6ed1-4a3a-b92f-19d26c630d09', 'Remo en polea baja agarre V', 71, 17, 151, 1, 'Principiante', 'Tira del agarre hacia el abdomen sentado. Cue: espalda recta, codos atrás. Error: balancear el torso.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'V Grip Low Cable Row', 'Pull the grip towards the sitting abs. Cue: back straight, elbows back. Common mistake: swinging the torso.', 'external'),
('7d2dc762-7636-42b6-80db-a484add05d1c', 'Thruster alterno a una mano en Landmine', 28, 6, 116, 1, 'Intermedio', 'Realiza una sentadilla sosteniendo el extremo de la barra con una mano y, al subir, presiónala sobre la cabeza, alternando brazos en cada repetición.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Alternating Single-Arm Landmine Thruster', 'Perform a squat while holding the end of the bar with one hand and press it overhead as you stand up, alternating arms on each repetition.', 'external'),
('7d887ccc-ea95-479b-bc19-3992b3139a5f', 'Pallof press cable', 25, NULL, 151, 1, 'Intermedio', 'De pie perpendicular al cable a la altura del pecho, extiende los brazos al frente resistiendo la rotación. Es un ejercicio anti-rotación que fortalece el core de manera funcional. Mantén la posición extendida 2-3 segundos antes de volver.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pallof press cable', 'Standing perpendicular to the cable at chest height, extend your arms in front of you resisting rotation. It is an anti-rotation exercise that functionally strengthens the core. Hold the extended position for 2-3 seconds before returning.', 'external'),
('7dbe994b-b905-4a78-b706-b8e07ef9ec11', 'Push Jerk alterno con mancuernas', 6, 28, 81, 1, 'Avanzado', 'Alterna el movimiento de jerk sobre la cabeza con mancuernas, combinando potencia explosiva y estabilidad unilateral.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Alternating Dumbbell Push Jerk', 'Alternate the overhead jerk movement with dumbbells, combining explosive power and unilateral stability.', 'external'),
('7e1a76a7-3ee3-4cdd-99cb-ab8ff78984af', 'Elevación de pierna lateral tumbado', 37, 29, 1, 1, 'Principiante', 'Tumbado de lado, eleva la pierna superior sin rotar la cadera hacia arriba. Objetivo: abductores y glúteo medio. Cues: punta del pie mirando al frente. Error común: girar la punta del pie hacia el techo.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Lying Side Leg Raise', 'Lying on your side, raise your top leg without rotating your hips upward. Target: abductors and glutes medius. Cues: tip of the foot looking forward. Common mistake: turning the toe towards the ceiling.', 'bodyweight'),
('7e2136ba-837d-49fe-8b90-7f86789dd408', 'Press de banca Seesaw con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado en el banco, alterna el press de dos Kettlebells invertidas, exigiendo un control extremo del agarre y la estabilidad de hombros.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Seesaw Bench Press with Double kettlebell Bottoms Up', 'Lying on the bench, alternate pressing two inverted kettlebells, demanding extreme grip control and shoulder stability.', 'external'),
('7ea0aa64-6216-4e41-8380-62611d2212bb', 'Sentadilla Front Rack con mancuerna a una mano', 28, 29, 81, 1, 'Principiante', 'Sostén una mancuerna sobre un hombro (posición de rack) y realiza una sentadilla profunda, resistiendo la carga asimétrica.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Front Rack Squat with One-Handed Dumbbell', 'Hold a dumbbell over one shoulder (rack position) and perform a deep squat, resisting the asymmetrical load.', 'external'),
('7ebc2744-710b-4ef0-9db6-a7e84b22fb72', 'Full Planche en paralelas', 25, 6, 1, 24, 'Avanzado', 'Sostén el cuerpo completamente horizontal y paralelo al suelo sobre las paralelas, apoyado solo en las manos con los brazos bloqueados.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Full Planche in parallel', 'Hold your body completely horizontal and parallel to the ground on the parallel bars, supported only by your hands with your arms locked.', 'bodyweight'),
('7efd11a1-1f6c-420d-a0a5-591588cfcca0', 'Push Up diamante', 2, 1, 1, 1, 'Intermedio', 'En posición de flexión, junta las manos formando un diamante con índices y pulgares. Baja el pecho hacia las manos manteniendo los codos pegados al cuerpo.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Diamond Push Up', 'In a push-up position, bring your hands together forming a diamond with index fingers and thumbs. Lower your chest towards your hands, keeping your elbows close to your body.', 'mixed'),
('7fca143d-e31b-4ca0-8cce-3067a40df7c8', 'Remo en punta con barra (T-Bar Row)', 71, 17, 116, 1, 'Intermedio', 'Con un extremo de la barra anclado, sujeta el otro extremo con un agarre en V y tira hacia tu pecho. Objetivo: densidad de espalda. Cue: espalda plana siempre. Error: dar tirones con la espalda baja para subir.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'T-bar Row', 'With one end of the bar anchored, hold the other end with a V-grip and pull toward your chest. Target: back density. Cue: flat back always. Common mistake: pulling with the lower back to go up.', 'external'),
('7fd10d5e-9761-4d7e-8b67-155fc527148e', 'Press inclinado con barra 30-45 grados', 1, 6, 116, 1, 'Principiante', 'Press de pecho en banco inclinado con barra. Cue: barra a parte alta pecho. Error: bajar al cuello.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Incline Barbell Press 30-45 Degrees', 'Incline bench chest press with barbell. Cue: bar to upper chest. Common mistake: go down to the neck.', 'external'),
('7ffac95d-e282-4db0-9b2f-0be42484918c', 'Thruster Cosaco alterno con Kettlebell doble', 6, 28, 281, 1, 'Avanzado', 'Sentadilla lateral profunda alternada con press de Kettlebells sobre la cabeza, combinando maxima movilidad y potencia vertical.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Alternating Cossack Double Kettlebell Thruster', 'Perform alternating deep Cossack squats with overhead kettlebell presses, combining high mobility with vertical power.', 'external'),
('8000b248-ad8b-4af4-9d53-7f866a11eb72', 'Crunches piernas elevadas', 25, NULL, 1, 1, 'Principiante', 'Piernas a 90 grados, eleva hombros. Cue: lumbar contra el suelo. Error: tirar del cuello.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Crunches with Elevated Legs', 'Legs at 90 degrees, raise shoulders. Cue: lumbar against the floor. Common mistake: pulling the collar.', 'bodyweight'),
('800f81e6-1b5f-41d7-824e-28ecc8ad6858', 'Empuje cadera con barra', 29, 55, 116, 1, 'Avanzado', 'Hip thrust con barra pesada para máxima sobrecarga. Usa pad para comodidad. El banco debe estar a la altura de los omóplatos. Pausa en la contracción máxima. Uno de los mejores ejercicios para desarrollo de glúteos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell hip thrust', 'Hip thrust with heavy bar for maximum overload. Use pad for comfort. The bench should be at shoulder blade height. Pause in maximum contraction. One of the best exercises for glute development.', 'external'),
('802f1714-6e1a-415a-b94e-558edb8e2a86', 'Maltese', 6, 1, 1, 24, 'Avanzado', 'Variación extrema del planche con brazos completamente extendidos lateralmente formando una cruz. Considerado uno de los elementos más difíciles en gimnasia. Requiere fuerza sobrehumana en hombros y años de preparación específica.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Maltese', 'Extreme variation of the planche with arms fully extended laterally forming a cross. Considered one of the most difficult elements in gymnastics. It requires superhuman shoulder strength and years of specific preparation.', 'bodyweight'),
('802f2689-7499-488e-acb9-f8d69679f728', 'Flexión de brazos con toque de hombro', 1, 25, 1, 1, 'Intermedio', 'Realiza una flexión y, al subir, toca el hombro opuesto con una mano manteniendo la estabilidad. Objetivo: core y pectoral. Cue: no balancees la cadera al tocar el hombro. Error: elevar demasiado el glúteo.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Push-up with Shoulder Touch', 'Perform a push-up and, when going up, touch the opposite shoulder with one hand while maintaining stability. Target: core and chest. Cue: don''t swing your hips when touching the shoulder. Common mistake: raising the glutes too much.', 'mixed'),
('806727d5-048b-4629-8a79-0ddcb0c9ab40', 'Remo bajo máquina', 16, 17, 186, 1, 'Principiante', 'Variación de remo con trayectoria más horizontal. Puede ser sentado o de pie inclinado según el diseño. Trabaja la espalda desde un ángulo diferente al remo alto. Mantén el pecho elevado y los omóplatos activos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rowing Under Machine', 'Rowing variation with a more horizontal trajectory. It can be seated or standing inclined depending on the design. Work your back from a different angle than the high row. Keep your chest raised and shoulder blades active.', 'external'),
('80a77509-1a10-46c3-b63b-6d16e25a5130', 'Turkish Sit Up con Kettlebell doble', 25, 6, 281, 1, 'Intermedio', 'Realiza un sit up manteniendo dos Kettlebells extendidas verticalmente sobre el pecho, exigiendo un gran control abdominal.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Turkish Sit-Up', 'Perform a sit-up while keeping two kettlebells extended vertically over your chest, demanding a high level of abdominal control.', 'external'),
('80ad72c7-0936-40e1-b918-92177809dff3', 'Woodchoppers balón', 25, NULL, 240, 1, 'Intermedio', 'Movimiento diagonal de arriba hacia abajo simulando cortar leña. Comienza con el balón sobre un hombro y llévalo diagonalmente hacia la cadera opuesta. Involucra todo el core con énfasis en oblicuos. Mantén los brazos extendidos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Medicine Ball Woodchoppers', 'Perform a diagonal movement from high to low as if chopping wood. Start with the ball over one shoulder and bring it diagonally toward the opposite hip. It works the entire core with an emphasis on the obliques. Keep your arms extended.', 'external'),
('80b40d0a-a5a1-492f-9af5-847243aefdc9', 'Hip thrust', 29, 55, 1, 1, 'Intermedio', 'Apoya la parte superior de la espalda en un banco con los pies firmemente plantados en el suelo. Desde esta posición elevada, desciende las caderas y luego empuja explosivamente hacia arriba contrayendo los glúteos. En la posición superior, el torso debe estar paralelo al suelo. Mantén la barbilla hacia el pecho.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip Thrust', 'Rest your upper back on a bench with your feet firmly planted on the floor. From this raised position, lower your hips and then explosively push up by contracting your glutes. In the top position, the torso should be parallel to the floor. Keep your chin toward your chest.', 'mixed'),
('80c1aad1-1252-465e-8b1c-3c831de76e34', 'Shrugs mancuernas', 71, NULL, 81, 1, 'Principiante', 'Con una mancuerna pesada en cada mano a los lados, eleva los hombros hacia las orejas lo más alto posible. Mantén la contracción por un segundo y desciende controladamente. Evita rotar los hombros; el movimiento debe ser puramente vertical.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Shrugs', 'With a heavy dumbbell in each hand at your sides, raise your shoulders toward your ears as high as possible. Hold the contraction for a second and lower yourself under control. Avoid rotating your shoulders; the movement must be purely vertical.', 'external'),
('80c307e9-0a07-4802-9e6d-04dac1329e0a', 'Zancada lateral agarre bajo en Landmine', 28, 29, 116, 1, 'Intermedio', 'Sujeta el extremo de la barra Landmine a una altura baja y realiza una zancada lateral profunda, manteniendo la espalda recta y el core activado.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Lateral stride low grip on Landmine', 'Hold the end of the Landmine bar at a low height and take a deep lateral stride, keeping your back straight and your core activated.', 'external'),
('80c8a232-2fc3-4cee-96aa-f1ae76908612', 'Pullover con maza', 71, 6, 81, 1, 'Principiante', 'Realiza un movimiento de pullover llevando la maza por encima de la cabeza y regresando al pecho, enfocando el trabajo en el dorsal ancho.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Pullover with mace', 'Perform a pullover movement by bringing the club above your head and returning to your chest, focusing the work on the latissimus dorsi.', 'external'),
('80caeae6-9d7d-4f95-b041-dbae7e4fe0aa', 'Step Up contralateral Front Rack con Kettlebell a una mano Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Sujeta una Kettlebell invertida en el pecho y sube al banco con la pierna contraria, estabilizando la carga inestable.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Single-Kettlebell Bottoms-Up Front Rack Step-up', 'Hold an upside-down kettlebell at the chest and step onto the bench with the opposite leg, stabilizing the unstable load throughout the movement.', 'external'),
('80dc05db-9582-47ff-b65e-5cf7b9cf48a5', 'Press banca agarre cerrado', 2, 1, 116, 1, 'Avanzado', 'Press con manos separadas al ancho de hombros o menos. Transfiere el énfasis a los tríceps. Los codos deben mantenerse más pegados al cuerpo. Cuidado con las muñecas. Excelente constructor de tríceps para mejorar el lockout del press regular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Close Grip Bench Press', 'Press with hands shoulder width apart or less. Transfer the emphasis to the triceps. The elbows should be kept closer to the body. Be careful with the dolls. Excellent triceps builder to improve the lockout of the regular press.', 'external'),
('81085ac1-f964-42bf-874f-5f13b9cd4383', 'Hip thrust barra', 29, 55, 116, 1, 'Intermedio', 'Con la parte superior de la espalda apoyada en un banco y la barra sobre las caderas (usa almohadilla), empuja las caderas hacia arriba hasta que el torso esté paralelo al suelo. Aprieta fuertemente los glúteos en la parte superior. Desciende controladamente sin tocar el suelo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip Thrust Bar', 'With your upper back supported by a bench and the barbell on your hips (use a pad), push your hips up until your torso is parallel to the floor. Tightly squeeze your glutes at the top. Descend in a controlled manner without touching the ground.', 'external'),
('8136213c-a08c-4703-924a-c2cc4c8544a0', 'Hang Squat Clean a Thruster con barra', 13, 6, 116, 1, 'Avanzado', 'Desde posicion colgada, carga la barra en sentadilla profunda y aprovecha la subida para presionar la barra sobre la cabeza en un thruster.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Hang Squat Clean to Thruster with Barbell', 'From a hanging position, load the bar in a deep squat and take advantage of the rise to press the bar overhead in a thruster.', 'external'),
('8149e643-0025-42f0-8241-b91410ba1e67', 'Salto vertical asistido banda', 28, NULL, 61, 1, 'Intermedio', 'Salta con una banda anclada arriba que te ayuda a subir. Enfoque en la velocidad de despegue. Cue: despegue instantáneo. Error común: depender demasiado de la banda.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Band Assisted Vertical Jump', 'Jump with a band anchored above that helps you climb. Focus on takeoff speed. Cue: instant takeoff. Common mistake: depending too much on the band.', 'assisted'),
('8153da50-80c9-4259-ab57-f74464a49c70', 'Peso muerto cable', 55, 29, 151, 1, 'Intermedio', 'Con polea baja y barra recta, realiza el movimiento de peso muerto. El cable cambia el vector de resistencia comparado con la barra libre. Mantén la espalda recta y empuja las caderas hacia atrás. Útil para aprender el patrón de movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Deadlift', 'With a low cable and straight bar, perform the deadlift movement. The cable changes the resistance vector compared to the free bar. Keep your back straight and push your hips back. Useful for learning movement pattern.', 'external'),
('815dd95e-5bee-4279-bbab-b10b3ffce48d', 'Remo bajo unilateral rotación core', 71, 17, 151, 1, 'Intermedio', 'Rema y rota tronco leve al estirar. Cue: controla giro. Error: tirones lumbares.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Single-Arm Low Row with Core Rotation', 'Row and rotate your torso slightly as you reach forward. Cue: control the rotation. Common mistake: straining your lower back.', 'external'),
('819a6dd7-eefc-42d4-8e48-9f18299258b7', 'Press pecho máquina sentado', 1, 2, 186, 1, 'Principiante', 'Empuja agarres máquina. Objetivo: pectoral. Cue: espalda pegada. Error: despegar hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Machine Chest Press', 'Press the machine handles forward. Target: chest. Cue: keep your back against the pad. Common mistake: letting your shoulders roll forward.', 'external'),
('81a8db34-ea1e-496f-9f5e-a853d66a285f', 'Squat Clean con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Lleva dos Kettlebells desde el suelo hasta los hombros de forma explosiva, recibiendo el peso en una posición de sentadilla profunda.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Double kettlebell Squat Clean', 'Bring two kettlebells from the floor to your shoulders explosively, receiving the weight in a deep squat position.', 'external'),
('81c85cf8-f78b-4df2-99e6-c1cbc11af3cb', 'Crunches con piernas elevadas a 90 grados', 25, NULL, 1, 1, 'Principiante', 'Tumbado con piernas en el aire, eleva los hombros apretando el abdomen. Objetivo: recto abdominal superior. Cue: mira al techo para no tirar del cuello. Error común: separar la zona lumbar del suelo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Crunches with Legs Raised to 90 Degrees', 'Lying with legs in the air, raise your shoulders, squeezing your abs. Target: upper rectus abdominis. Cue: look at the ceiling to avoid pulling on your neck. Common mistake: separating the lower back from the floor.', 'bodyweight'),
('81e937d6-6493-438f-8ddb-9f0251099ad6', 'Atomic push up TRX', 1, 25, 216, 1, 'Avanzado', 'Combina una flexión con un crunch con los pies en TRX. Realiza una flexión y al subir lleva las rodillas hacia el pecho. Ejercicio muy completo que trabaja pecho, tríceps y core intensamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Atomic Push-Up', 'Perform a push-up with your feet in the TRX straps and then drive your knees toward your chest as you come up. This is a very complete exercise for the chest, triceps, and core.', 'mixed'),
('81f6aba7-ab6f-4ccc-bfff-f73e3d54a841', 'Press de hombros sentado con barra', 6, 2, 116, 1, 'Intermedio', 'Siéntate en un banco con respaldo. Baja la barra hasta la barbilla y presiona verticalmente hasta estirar los brazos.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Seated Barbell Shoulder Press', 'Sit on a bench with a backrest. Lower the bar to your chin and press vertically until your arms are straight.', 'external'),
('82296623-8248-4ba2-8bf3-10c875064b98', 'Saltos talón a glúteo con salto vertical', 55, 64, 1, 1, 'Principiante', 'Salta y lleva los talones a los glúteos de forma explosiva. Mejora la velocidad de recuperación de pierna. Espalda recta. No te inclines hacia adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Heel-to-glute jumps with vertical jump', 'Jump and bring your heels to your glutes explosively. Improves leg recovery speed. Straight back. Don''t lean forward.', 'bodyweight'),
('82417703-75ba-4307-950b-5fa0b31ef61e', 'Donkey kicks', 29, NULL, 1, 1, 'Principiante', 'Desde cuadrupedia, mantén la rodilla flexionada a 90 grados y eleva la pierna hacia atrás y arriba, como si empujaras el techo con la planta del pie. Contrae el glúteo en la parte superior del movimiento. Mantén la espalda neutra y evita arquearla excesivamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Donkey kicks', 'From all fours, keep your knee bent at 90 degrees and raise your leg back and up, as if you were pushing against the ceiling with the sole of your foot. Contract your glute at the top of the movement. Keep your back neutral and avoid arching it excessively.', 'bodyweight'),
('827a548e-1cc0-4d6b-83ea-6476c30c754b', 'Puente de glúteo a una pierna con pie en Fitball', 29, 55, 290, 1, 'Avanzado', 'Acuéstate con un pie sobre el Fitball. Eleva la cadera usando esa pierna mientras equilibras el balón inestable y la otra pierna en el aire.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'One-leg glute bridge with foot on Stability Ball', 'Lie down with one foot on the stability ball. Raise your hips using that leg while balancing the unstable ball and the other leg in the air.', 'bodyweight'),
('827e5b52-6117-4548-9e0e-39206ec60a72', 'Peso muerto con una sola pierna (sin peso)', 55, 29, 1, 1, 'Principiante', 'Mantén el equilibrio en una pierna y baja el torso mientras la otra pierna se extiende atrás. Objetivo: equilibrio y cadena posterior. Cue: mantén la espalda plana. Error: girar la cadera hacia afuera.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Single Leg Deadlift (no Weight)', 'Balance on one leg and lower your torso while the other leg extends behind you. Target: balance and posterior chain. Cue: keep your back flat. Common mistake: turning your hips outward.', 'bodyweight'),
('829ab4e3-f95c-4f31-9f50-b03dfeda3739', 'Complejo mancuernas', 13, NULL, 81, 1, 'Avanzado', 'Serie de 4-6 ejercicios realizados sin soltar las mancuernas. Ejemplo: deadlift, row, clean, press, squat, lunge. Todas las reps de un ejercicio antes de pasar al siguiente. Brutal para acondicionamiento. Elige peso apropiado para ejercicio más débil.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell complex', 'Series of 4-6 exercises performed without releasing the dumbbells. Example: deadlift, row, clean, press, squat, lunge. All reps of one exercise before moving on to the next. Brutal for conditioning. Choose appropriate weight for weaker exercise.', 'external'),
('82c8c093-a32d-4561-afe4-8646f8e16084', 'Curl de bíceps con banda pisada', 17, NULL, 61, 1, 'Principiante', 'Pisa la banda y flexiona brazos. Resistencia variable. Codos pegados. No muevas las muñecas.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Biceps curl with tread band', 'Step on the band and flex your arms. Variable resistance. Elbows stuck together. Don''t move your wrists.', 'external'),
('82f3ee55-ffe4-45ba-8554-d4657691380e', 'Oblique crunch TRX', 25, NULL, 216, 1, 'Intermedio', 'Similar al crunch pero llevando las rodillas hacia un lado, alternando. Trabaja intensamente los oblicuos. Mantén el torso estable y evita rotar excesivamente las caderas durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Oblique crunch TRX', 'Similar to the crunch but taking the knees to the side, alternating. Work the obliques intensely. Keep your torso stable and avoid excessively rotating your hips during the movement.', 'bodyweight'),
('83258c8b-dcba-4525-94e1-703825d47467', 'Press declinado con mancuernas', 1, 2, 81, 1, 'Intermedio', 'Press en banco declinado con mancuernas. Objetivo: fibras inferiores. Cue: controla el descenso. Error: chocar pesas.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Decline Dumbbell Press', 'Decline bench press with dumbbells. Target: lower fibers. Cue: controls the descent. Common mistake: colliding weights.', 'external'),
('835cbcfd-6484-4ea9-af91-848725fa695a', 'Reverse fly cable', 6, 71, 151, 1, 'Intermedio', 'Con cables cruzados o en máquina específica, realiza aperturas posteriores para deltoides posterior. Mantén los brazos ligeramente flexionados y enfócate en juntar los omóplatos al final. Excelente para mejorar la postura y equilibrar el desarrollo del hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Reverse fly cable', 'With crossed cables or a specific machine, perform posterior openings for the posterior deltoid. Keep your arms slightly bent and focus on bringing your shoulder blades together at the end. Excellent for improving posture and balancing shoulder development.', 'external'),
('83a247ca-748a-4ce4-a300-0b5aedc56f28', 'Sentadilla Búlgara con mancuernas rodilla sobre punta del pie', 28, 29, 81, 1, 'Intermedio', 'Realiza una sentadilla búlgara con mancuernas a los lados permitiendo que la rodilla delantera sobrepase el pie para cargar el cuadriceps.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bulgarian squat with dumbbells knee on toe', 'Perform a Bulgarian squat with dumbbells at your sides, allowing the front knee to go over the foot to load the quadriceps.', 'external'),
('83a554dd-0279-4602-807e-891d99176692', 'Press de suelo con barra', 1, 2, 116, 1, 'Principiante', 'Tumbado en el suelo, baja la barra hasta que los tríceps toquen el suelo y luego presiona explosivamente hacia arriba.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Barbell Floor Press', 'Lying on the floor, lower the bar until your triceps touch the floor and then explosively press up.', 'external'),
('84163055-1c04-4c45-a20b-8b6eccb2bf4d', 'Sentadilla sumo con kettlebell', 29, 313, 281, 1, 'Principiante', 'Pies muy anchos y puntas hacia afuera, sujeta la pesa abajo y baja en sentadilla profunda. Objetivo: aductores y glúteo. Cue: mantén las rodillas alineadas con los pies. Error: redondear la espalda lumbar.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Sumo Squat with Kettlebell', 'Feet very wide and toes outward, hold the weight down and lower yourself into a deep squat. Target: adductors and glutes. Cue: keep your knees in line with your feet. Common mistake: rounding the lumbar back.', 'external'),
('84383691-c1f4-449e-80ce-def20ac0f998', 'Rollout de rodillas en anillas', 25, 6, 1, 1, 'Intermedio', 'De rodillas, sujeta las anillas y desliza los brazos hacia adelante extendiendo el cuerpo bajo control, regresando mediante la fuerza abdominal.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Ring Knee Rollout', 'On your knees, hold the rings and slide your arms forward, extending your body under control, returning using abdominal strength.', 'bodyweight'),
('845dde79-265e-443f-a1c7-5b61bfa81ab7', 'Press Pallof rotacional dinámico', 25, 6, 151, 1, 'Avanzado', 'Extiende cable y gira levemente resistiendo. Cue: core bloqueado. Error: mover cadera.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Dynamic Rotational Pallof Press', 'Extend cable and twist slightly, resisting. Cue: locked core. Common mistake: move hip.', 'external'),
('8464fafe-5ff2-465e-ab5e-884a022c0e66', 'Turkish Sit Up con mancuerna a una mano', 25, 6, 81, 1, 'Intermedio', 'Acuéstate con un brazo extendido sujetando una mancuerna. Realiza un sit up manteniendo el brazo perfectamente vertical en todo momento.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Single-Arm Dumbbell Turkish Sit-Up', 'Lie down holding a dumbbell with one arm extended. Perform a sit-up while keeping that arm perfectly vertical throughout the movement.', 'external'),
('848832dd-64b5-404b-bc31-1e366ef9e293', 'Peso muerto rumano a una pierna con barra', 55, 71, 116, 1, 'Intermedio', 'Sostén la barra y baja el torso hacia adelante mientras elevas una pierna hacia atrás, manteniendo el equilibrio sobre la pierna de apoyo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Romanian Single Leg Barbell Deadlift', 'Hold the bar and lower your torso forward as you raise one leg back, balancing on your supporting leg.', 'external'),
('8493dd78-6a41-451b-9db2-6abfe34158eb', 'Abductor sentado banda', 37, 29, 61, 1, 'Principiante', 'Separa rodillas con banda sentado. Objetivo: glúteo medio. Cue: pecho alto. Error: cerrar rápido.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Band Seated Abductor', 'Separate your knees against the band while seated. Target: glute medius. Cue: keep your chest up. Common mistake: bringing your knees back together too quickly.', 'external'),
('84dc0a1e-bdc6-486f-9342-b54de8e703a5', 'Remo búlgaro en anillas', 71, 17, 1, 1, 'Intermedio', 'Realiza un remo en anillas con un agarre más ancho y los codos flexionados hacia los lados para enfocar el trabajo en la parte superior de la espalda y deltoides posteriores.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Bulgarian ring rowing', 'Perform a ring row with a wider grip and elbows bent to the sides to focus the work on the upper back and rear deltoids.', 'bodyweight'),
('8503bcdc-0cf8-4932-8cbf-89407b276c8a', 'Movilidad tobillo-cadera', 28, 29, 1, 24, 'Principiante', 'Realiza una secuencia de movilidad enfocada en tobillo y cadera, trabajando rangos controlados para mejorar la posición de sentadilla, zancada y carrera.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Ankle and Hip Mobility', 'Perform a mobility sequence focused on the ankle and hip, working through controlled ranges to improve squat, lunge, and running positions.', 'bodyweight'),
('850b353a-d122-4699-8788-704eac0d47ed', 'Elevaciones laterales cable unilateral', 6, NULL, 151, 1, 'Intermedio', 'Eleva el cable lateralmente con un solo brazo. Cue: hombro abajo. Error: usar trapecio excesivamente.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Unilateral Cable Side Raises', 'Raise the cable laterally with a single arm. Cue: shoulder down. Common mistake: using trapeze excessively.', 'external'),
('850b5321-886c-413d-9345-e27d167e4543', 'Pull-through polea baja cadera', 29, 55, 151, 1, 'Intermedio', 'Tira cuerda entre piernas de espaldas. Cue: espalda plana. Error: tirar con brazos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Pull-through Low Hip Pulley', 'Pull rope between your legs on your back. Cue: flat back. Common mistake: pulling with arms.', 'external'),
('852ff93e-15ec-4aef-a616-1894ffe0891e', 'Saltos pogo', 64, 309, 1, 1, 'Intermedio', 'Rebotes rápidos con mínima flexión de rodilla para trabajar rigidez de tobillo y reactividad del pie.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Pogo Jumps', 'Fast rebounds with minimal knee flexion to work on ankle stiffness and foot reactivity.', 'bodyweight'),
('8543650d-836a-4e2b-bb3c-051d573d303d', 'Push Up ancho en paralelas', 1, 6, 1, 1, 'Intermedio', 'Coloca las manos en las paralelas más ancho que los hombros. Baja el pecho profundamente para estirar el pectoral antes de empujar hacia arriba.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Wide Push Up in parallel bars', 'Place your hands on the parallel lines wider than your shoulders. Lower your chest deeply to stretch your chest before pushing up.', 'mixed'),
('85443804-57fd-4294-aa59-0ba93020ea7e', 'Elevación de piernas tumbado', 25, NULL, 1, 1, 'Principiante', 'Acuéstate boca arriba con las manos bajo los glúteos. Manteniendo las piernas rectas y juntas, levántalas hasta que estén verticales y bájalas lentamente sin tocar el suelo.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Lying leg raises', 'Lie on your back with your hands under your buttocks. Keeping your legs straight and together, raise them until they are vertical and lower them slowly without touching the floor.', 'bodyweight'),
('854c05c7-dc3c-488b-b8fe-c75735e104f9', 'Extensión de tríceps Overhead con barra Z', 2, NULL, 116, 1, 'Principiante', 'De pie, sostén una barra Z con los brazos extendidos sobre la cabeza. Baja la barra detrás de la cabeza doblando los codos y luego extiende.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Z-Bar Overhead Triceps Extension', 'Standing, hold a Z-bar with your arms extended overhead. Lower the bar behind your head by bending your elbows and then extend.', 'external'),
('85537bfe-d628-449f-be49-70640e47bb79', 'Peso muerto un brazo', 55, 71, 116, 1, 'Avanzado', 'Peso muerto sujetando la barra con una sola mano en el centro. Desafío extremo de agarre y estabilización anti-rotación. Usa menos peso. Alterna manos. Excelente para fuerza funcional y del core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Arm Deadlift', 'Perform a deadlift holding the bar with one hand in the center. It is an extreme grip and anti-rotation stability challenge. Use less weight. Alternate hands. Excellent for functional strength and core work.', 'external'),
('85625cf9-e586-4307-8eda-dc226856d5f5', 'Spider Curl agarre Crush con mancuernas', 17, 100, 81, 1, 'Intermedio', 'Apoyado en banco inclinado, presiona dos mancuernas una contra la otra mientras realizas el curl para aumentar la activacion muscular.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Spider Curl with Crush Grip Dumbbells', 'Leaning on an incline bench, press two dumbbells together while curling to increase muscle activation.', 'external'),
('85652945-2e8c-4313-aafc-ba63baa71ccd', 'Press Overhead Seesaw con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Presiona una Kettlebell hacia arriba mientras bajas la otra simultáneamente de forma continua, creando un movimiento de balancín constante.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Press Overhead Seesaw with Double kettlebell', 'Press one kettlebell up while lowering the other simultaneously continuously, creating a constant rocking motion.', 'external'),
('857190a0-3899-403a-9a30-d7e885668518', 'Press de banca declinado agarre cerrado con barra', 2, 1, 116, 1, 'Principiante', 'Realiza un press de banca en un banco declinado con las manos juntas en la barra, enfocando el trabajo en la parte inferior del pectoral y el triceps.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Barbell Close Grip Decline Bench Press', 'Perform a bench press on a decline bench with your hands together on the bar, focusing the work on the lower pectorals and triceps.', 'external'),
('85ada012-58ae-44d9-b04b-43744b0c7fc9', 'Zancada lateral Overhead con barra y Slider', 28, 6, 116, 1, 'Avanzado', 'Sostén una barra sobre la cabeza con brazos bloqueados. Coloca un pie sobre un slider y deslízalo lateralmente bajando en una zancada profunda, manteniendo la barra estable arriba.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Overhead lateral stride with bar and slider', 'Hold a barbell over your head with locked arms. Place one foot on a slider and slide it sideways down in a deep stride, keeping the bar steady at the top.', 'external'),
('863148d4-9367-4764-b637-78350be42c87', 'Single leg slam', 25, 29, 240, 1, 'Intermedio', 'Slam ball realizado sobre una pierna. Aumenta el desafío de equilibrio y la activación del core. Alterna las piernas o completa series por lado. Mantén la rodilla de apoyo ligeramente flexionada.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single leg slam', 'Slam ball performed on one leg. Increases balance challenge and core activation. Alternate legs or complete sets per side. Keep your supporting knee slightly bent.', 'external'),
('8650ff35-6c95-4a4b-9ab5-99dd72df0737', 'Rotaciones laterales con Indian Club doble', 6, NULL, 81, 1, 'Principiante', 'Realiza círculos laterales controlados con ambos Indian Clubs para mejorar la movilidad y salud de la articulación del hombro.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Lateral rotations with double Indian Club', 'Perform controlled lateral circles with both Indian Clubs to improve shoulder joint mobility and health.', 'external'),
('868d3148-9062-42fb-8716-62838ffcbf35', 'Peso muerto rumano a una pierna contralateral con Kettlebell', 55, 29, 281, 1, 'Intermedio', 'Realiza un peso muerto rumano a una pierna sosteniendo la Kettlebell con la mano opuesta a la pierna de apoyo, aumentando el reto de estabilidad cruzada.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Contralateral Single Leg Romanian Deadlift with Kettlebell', 'Perform a single-leg Romanian deadlift holding the kettlebell with the opposite hand to the supporting leg, increasing the cross-stability challenge.', 'external'),
('869b66e7-9c59-448a-a727-7453e81953b3', 'Rotación interna hombro cable', 6, NULL, 151, 1, 'Principiante', 'Similar a la rotación externa pero rotando hacia adentro cruzando el cuerpo. Trabaja los rotadores internos del hombro. Mantén el codo fijo al costado y usa resistencia apropiada para mantener el control durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Internal rotation shoulder cable', 'Similar to external rotation but rotating inward across the body. Works the internal rotators of the shoulder. Keep your elbow fixed to your side and use appropriate resistance to maintain control throughout the movement.', 'external'),
('86ae9fa6-d634-4b17-874b-d0ba4fdf74e2', 'Escaladores lentos', 25, 6, 1, 24, 'Principiante', 'Lleva rodilla a codo manteniendo la contracción abdominal 2 seg. Cue: máxima tensión. Error: mover la cadera arriba.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Slow Climbers', 'Bring knee to elbow, maintaining abdominal contraction for 2 sec. Cue: maintain maximum tension. Common mistake: letting your hips rise too much.', 'bodyweight'),
('86b53421-8eb6-4232-b598-b8c00da0d4da', 'Step Up Overhead contralateral con Kettlebell a una mano Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sube al banco con la pierna opuesta a la mano que sostiene una Kettlebell invertida sobre la cabeza, trabajando la estabilidad cruzada.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Single-Kettlebell Bottoms-Up Overhead Step-up', 'Step onto the bench with the leg opposite the hand holding an upside-down kettlebell overhead, training balance and shoulder stability.', 'external'),
('86b9deb1-0e62-4351-a6cc-b71b6e210cfd', 'Muscle up TRX', 16, 1, 216, 1, 'Avanzado', 'Versión modificada del muscle up usando TRX. La inclinación del cuerpo determina la dificultad. Permite practicar la transición de tracción a empuje. Progresión hacia muscle up en barra o anillas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Muscle up TRX', 'Modified version of the muscle up using TRX. The inclination of the body determines the difficulty. Allows you to practice the transition from pulling to pushing. Progression towards muscle up on bar or rings.', 'bodyweight'),
('86e7360f-fbf2-4375-8ecd-39d4e8371cf3', 'Sentadilla Búlgara Front Rack rodilla sobre punta del pie', 28, 29, 116, 1, 'Intermedio', 'Realiza una sentadilla split con el pie elevado y la barra en posicion de rack frontal, permitiendo que la rodilla delantera sobrepase los dedos del pie bajo control.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bulgarian Squat Front Rack Knee on Toe', 'Perform a split squat with your foot raised and the bar in a front rack position, allowing your front knee to pass over your toes under control.', 'external'),
('86e7591d-b617-48b4-953a-19567e812960', 'Remo máquina un brazo apoyo pecho', 71, 17, 186, 1, 'Principiante', 'Tira de un agarre en máquina. Cue: estira hombro. Error: rotar tronco.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Rowing Machine One Arm Chest Support', 'Pull a machine grip. Cue: stretch your shoulder. Common mistake: rotate torso.', 'external'),
('87210fa7-ee0e-4573-8792-2825779bc3c8', 'Press Arnold', NULL, 2, 81, 1, 'Intermedio', 'Sentado con mancuernas, inicia con palmas mirando hacia ti. Al subir rota las mancuernas hasta que las palmas miren al frente. Baja controlado invirtiendo la rotación.', FALSE, NULL, '2025-12-11T19:27:04.572597+00:00', 'Press Arnold', 'Seated with dumbbells, start with palms facing you. As you go up, rotate the dumbbells until your palms are facing forward. Controlled lowering by reversing rotation.', 'external'),
('873f16cf-f086-40e7-b8c5-2bb0b8d20b6c', 'Crunches manos pies elevados verticales', 25, NULL, 1, 1, 'Principiante', 'Eleva hombros buscando tocar pies en aire. Cue: lumbar al suelo. Error: tirar cuello.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Vertical Crunches with Hands and Feet Elevated', 'Raise your shoulders trying to touch your feet in the air. Cue: lumbar toward the floor. Common mistake: pulling neck.', 'bodyweight'),
('877e0a86-3940-4c51-a22e-171cad638547', 'Crunch oblicuo con pies en Fitball', 25, NULL, 290, 1, 'Intermedio', 'Acuéstate en el suelo con los talones sobre el Fitball. Coloca una mano detrás de la cabeza y eleva el torso girando para llevar el codo hacia la rodilla opuesta.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Oblique crunch with feet on Stability Ball', 'Lie on the floor with your heels on the Stability Ball. Place one hand behind your head and raise your torso, twisting to bring your elbow toward the opposite knee.', 'bodyweight'),
('87d276ea-24f4-415d-936c-a1d4fd1ad188', 'Burpee con salto 180 grados', 13, 25, 1, 1, 'Avanzado', 'Realiza un burpee y termina con un salto girando media vuelta en el aire. Mejora la orientación y coordinación. Cue: aterriza amortiguando con rodillas. Error común: marearse al girar sin un punto fijo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee with 180 Degree Jump', 'Perform a burpee and finish with a jump twisting half a turn in the air. Improves orientation and coordination. Cue: land softly by bending your knees. Common mistake: getting dizzy when turning without a fixed point.', 'bodyweight'),
('87e7039f-c765-4acd-9af1-da467b87c35c', 'Squat bosu', 28, 29, 298, 1, 'Intermedio', 'Sentadillas de pie sobre el lado redondo del bosu. Desafía el equilibrio y la propiocepción mientras fortalece las piernas. Comienza con sentadillas parciales y progresa. Mantén la vista al frente y el core activado para estabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'BOSU Squat', 'Standing squats on the round side of the bosu. Challenges balance and proprioception while strengthening the legs. Start with partial squats and work your way up. Keep your eyes forward and core engaged for stability.', 'bodyweight'),
('87e9e4c7-e091-4dcd-a8b7-a441eb736f51', 'Patada de tríceps en polea', 2, NULL, 151, 1, 'Intermedio', 'Torso inclinado, extiende el brazo atrás. Aislamiento total. Brazo paralelo al suelo. No muevas el hombro.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Cable triceps kick', 'Tilted torso, extend your arm behind you. Total isolation. Arm parallel to the ground. Don''t move your shoulder.', 'external'),
('87eb0c00-1983-49a5-8609-4b54a13fb513', 'Sentadilla Búlgara Front Rack con barra', 28, 29, 116, 1, 'Intermedio', 'Con un pie elevado en banco, sujeta la barra en posicion de rack frontal sobre los hombros y realiza una sentadilla split profunda.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Front Rack Squat with Barbell', 'With one foot raised on the bench, hold the bar in a front rack position on your shoulders and perform a deep split squat.', 'external'),
('87f1ea96-c5f8-4af7-991e-4bc16d9358ad', 'Bodyweight Kneeling Forearm Plank', 25, 6, 1, 24, 'Principiante', 'Apoya los antebrazos y las rodillas en el suelo. Mantén el cuerpo en línea recta desde la cabeza hasta las rodillas, activando el abdomen y evitando que la cadera caiga.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Kneeling Forearm Plank', 'Rest your forearms and knees on the floor. Keep your body in a straight line from head to knees, activating your abs and preventing your hips from falling.', 'bodyweight'),
('882f4efc-ac86-478f-8af8-35688e94f442', 'Lanzamiento granny toss', 13, 6, 240, 1, 'Principiante', 'Lanza el balón hacia arriba lo más alto posible desde una posición de sentadilla. Potencia total del cuerpo. Cue: mirada en el balón para recibirlo. Error común: redondear la espalda al recoger el balón del suelo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Granny Toss Toss', 'Throw the ball up as high as possible from a squat position. Total body power. Cue: look at the ball to receive it. Common mistake: rounding your back when picking up the ball from the ground.', 'external'),
('88b476d9-6f6e-4437-8cb3-e31d7b6b379d', 'Elevaciones laterales', 6, NULL, 81, 1, 'Principiante', 'Eleva mancuernas lateralmente hasta la altura de los hombros. Objetivo: deltoides lateral. Cue: vierte agua al subir. Error común: elevar el peso por encima de la línea de los hombros.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Side Raises', 'Raise dumbbells laterally to shoulder height. Target: lateral deltoid. Cue: pour water on the way up. Common mistake: raising the weight above the shoulder line.', 'external'),
('88e2d177-d4d2-4939-a21f-ace8214cad3a', 'Sentadilla jump', 28, 29, 1, 1, 'Intermedio', 'Realiza una sentadilla normal y al subir, explota hacia arriba en un salto vertical máximo. Aterriza suavemente amortiguando con las rodillas flexionadas y continúa inmediatamente con la siguiente repetición. Este ejercicio desarrolla potencia explosiva en las piernas y mejora la capacidad atlética.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Jump squat', 'Perform a normal squat and as you rise, explode upward into a maximum vertical jump. Land softly with your knees bent and continue immediately with the next repetition. This exercise develops explosive power in the legs and improves athletic ability.', 'mixed'),
('891181ff-0a97-403b-b9eb-6be1f8e2548e', 'Side to Side Swing con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'Balancea la Kettlebell de un lado al otro por delante del cuerpo en un arco lateral, desafiando la estabilidad rotacional del core.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Side to Side Swing with One-Handed kettlebell', 'Swing the kettlebell from side to side in front of the body in a lateral arc, challenging the rotational stability of the core.', 'external'),
('8913568c-fb05-4cc1-80ca-d778c9363a9d', 'Curl de isquiotibiales a una pierna en Fitball', 55, 29, 290, 1, 'Intermedio', 'Realiza un curl de isquiotibiales sobre el Fitball usando solo una pierna, manteniendo la otra elevada para aumentar la intensidad.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'One-leg Hamstring Curl on Stability Ball', 'Perform a hamstring curl on the Stability Ball using only one leg, keeping the other raised to increase intensity.', 'bodyweight'),
('891b642b-0be8-475d-8fd3-a2de72aca974', 'Movilidad de hombro y dorsal', 6, 16, 1, 24, 'Principiante', 'Realiza una secuencia de movilidad enfocada en hombro y dorsal, buscando mejorar el rango de movimiento sin dolor y manteniendo una respiración controlada.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Shoulder and Lat Mobility', 'Perform a mobility sequence focused on the shoulder and lats, aiming to improve range of motion without pain while maintaining controlled breathing.', 'bodyweight'),
('89224e66-7c98-4c84-b39e-063d569f345f', 'Extensiones de tríceps en polea con barra recta', 2, NULL, 151, 1, 'Principiante', 'Empuja la barra hacia abajo bloqueando los codos al final del movimiento. Objetivo: tríceps. Cue: mantén los codos pegados a los costados. Error: mover los brazos desde el hombro.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Cable Triceps Extensions with Straight Bar', 'Push the bar down, locking your elbows at the end of the movement. Target: triceps. Cue: keep your elbows close to your sides. Common mistake: moving the arms from the shoulder.', 'external'),
('89287df9-6bf0-43f9-a702-9b990492c651', 'Jalón unilateral polea alta', 16, 17, 151, 1, 'Intermedio', 'Tira estribo a hombro. Objetivo: dorsal aislado. Cue: codo al bolsillo. Error: rotar torso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Unilateral High Cable Pull', 'Pull stirrup to shoulder. Target: isolated dorsal. Cue: elbow to pocket. Common mistake: rotate torso.', 'external'),
('89388b2f-4a25-4d6c-8980-4d0edc263fd6', 'Extensión nuca mancuerna un brazo', 2, NULL, 81, 1, 'Principiante', 'Baja pesa tras nuca a una mano. Cue: codo al techo. Error: mover brazo lateral.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'One Arm Dumbbell Neck Extension', 'Lower the weight behind your neck in one hand. Cue: elbow to the ceiling. Common mistake: move side arm.', 'external'),
('8945dd2d-1e28-4ac0-8580-8b85a5a37849', 'Press Overhead contralateral medio arrodillado con Kettlebell', 6, 2, 281, 1, 'Intermedio', 'En posicion de caballero, presiona la pesa sobre la cabeza con el brazo opuesto a la pierna delantera, retando la estabilidad del torso.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Contralateral Half-Kneeling Kettlebell Overhead Press', 'In a half-kneeling position, press the dumbbell overhead with the arm opposite the front leg, challenging the stability of the torso.', 'external'),
('895c8c8f-a898-4706-b033-ccdbb2abb90d', 'Dominadas archer', 16, 17, 1, 1, 'Avanzado', 'Dominadas dirigiendo la mayor parte del peso hacia un brazo mientras el otro asiste mínimamente. Excelente progresión hacia dominadas a un brazo. Alterna lados o completa series por lado. Mantén el brazo de asistencia lo más recto posible.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Archer pull-ups', 'Pull-ups directing most of the weight towards one arm while the other assists minimally. Excellent progression towards one-arm pull-ups. Alternate sides or complete sets per side. Keep the assist arm as straight as possible.', 'mixed'),
('899e00b1-86be-4d57-82b7-b15548cba3c9', 'Swing doble kettlebell', 29, 55, 281, 1, 'Avanzado', 'Swing con dos kettlebells simultáneamente. Requiere mayor fuerza y estabilización. Las kettlebells deben moverse sincronizadas. Más ancho de pies que swing simple. Progresa desde dominar swing simple perfectamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Double Kettlebell Swing', 'Perform swings with two kettlebells at the same time. It requires greater strength and stabilization. The kettlebells should move in sync. Use a wider stance than for a single swing. Progress only after mastering the single swing.', 'external'),
('89dbe6cb-467a-437a-83b8-be91543c4b47', 'Superman brazos estirados mirada suelo', 71, 29, 1, 1, 'Principiante', 'Eleva pecho y piernas boca abajo. Cue: mira abajo. Error: tirones cuello.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Superman Arms Extended, Eyes Down', 'Lift your chest and legs while lying face down. Cue: look down. Common mistake: jerking the neck.', 'bodyweight'),
('8a2e8cb2-0d8c-4fd9-b5dd-12a48ded6521', 'Paseo del granjero con mancuernas', 13, 100, 81, 24, 'Principiante', 'Camina cargando pesas a los lados. Cue: pasos cortos y firmes. Error: encoger hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Dumbbell Farmer''s Walk', 'Walk carrying weights at your sides. Cue: short, firm steps. Common mistake: shrugging your shoulders.', 'external'),
('8a36134e-d2cd-42a0-b27c-59c40c9cf2b9', 'Rotación externa hombro banda', 6, NULL, 61, 1, 'Principiante', 'Con el codo pegado al costado y flexionado a 90 grados, sujeta la banda y rota el antebrazo hacia afuera contra la resistencia. Mantén el codo inmóvil durante todo el movimiento. Esencial para la salud del manguito rotador y prevención de lesiones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'External rotation shoulder band', 'With your elbow close to your side and bent at 90 degrees, hold the band and rotate your forearm outward against the resistance. Keep your elbow still throughout the movement. Essential for rotator cuff health and injury prevention.', 'external'),
('8a4b0a01-0a1d-4af5-bdfc-ba926c4adf93', 'One arm push ups', 1, 2, 1, 1, 'Avanzado', 'Realiza flexiones utilizando solo un brazo mientras el otro se mantiene detrás de la espalda. Requiere fuerza excepcional y estabilización del core. Los pies deben estar más separados que en flexiones normales para mantener el equilibrio. Desciende controladamente evitando la rotación del torso.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm push ups', 'Perform push-ups using only one arm while the other remains behind your back. Requires exceptional strength and core stabilization. Your feet should be farther apart than in normal push-ups to maintain balance. Descend in a controlled manner, avoiding rotation of the torso.', 'mixed'),
('8a71d4eb-3612-4345-8632-583a46eafd35', 'Flexión pliométrica cruzada', 1, 2, 1, 1, 'Avanzado', 'En el aire, cruza las manos antes de volver a la posición de apoyo. Coordinación extrema de tren superior. Cue: despegue violento. Error común: no abrir las manos a tiempo al aterrizar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Cross Plyometric Push-up', 'In the air, cross your hands before returning to the support position. Extreme upper body coordination. Cue: violent takeoff. Common mistake: not opening your hands in time when landing.', 'mixed'),
('8a8a47c9-4098-4eee-9aa9-04813b9a4a24', 'Step up con mancuerna', 28, 29, 81, 1, 'Principiante', 'Sube a un banco o plataforma apoyando un pie y empuja hasta extender la pierna, ayudándote con una mancuerna en cada mano o según la variante utilizada. Baja de forma controlada y alterna piernas.', FALSE, NULL, '2026-05-08T12:05:31.655419+00:00', 'Dumbbell Step Up', 'Step onto a bench or platform with one foot and drive up until the leg is extended, using dumbbells according to the variation performed. Lower under control and alternate legs.', 'external'),
('8a8cfb7a-89ab-4d5a-981e-3aa113e140f6', 'Zancadas alternas rápidas', 28, 29, 1, 1, 'Principiante', 'Cambio rápido de piernas en zancada. Cue: mantén el equilibrio. Error: no bajar la rodilla trasera.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Alternate Fast Strides', 'Quick change of legs in stride. Cue: keep your balance. Common mistake: Do not lower the back knee.', 'bodyweight'),
('8a9bf5ba-1b43-460b-89d6-672c650cc2c7', 'Sentadilla', 28, 29, 1, 1, 'Principiante', 'Flexiona rodillas y cadera bajando el cuerpo con el torso erguido. Mantén los talones apoyados y las rodillas alineadas con los pies.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Squat', 'Bend your knees and hips, lowering your body with your torso upright. Keep your heels planted and your knees in line with your feet.', 'mixed'),
('8ab1ef0e-6397-481e-83e9-1c9f7317668f', 'Sentadilla Ciclista con Kettlebell doble (Front Rack)', 28, 29, 281, 1, 'Principiante', 'Con los talones elevados sobre una cuña y Kettlebells en posicion rack, realiza una sentadilla profunda enfatizando el trabajo de los cuadriceps.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Double Kettlebell Cycle Squat (front Rack)', 'With your heels raised on a wedge and kettlebells in a rack position, perform a deep squat emphasizing the work of the quadriceps.', 'external'),
('8afbbc66-5a77-47d2-aff9-cc5f73365a02', 'Escaladores (Mountain Climbers)', 25, 6, 1, 24, 'Principiante', 'En plancha, lleva rodillas al pecho alternando rápidamente. Cue: espalda plana como una tabla. Error: rebotar la cadera hacia arriba.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Climbers (mountain Climbers)', 'In a plank, bring your knees to your chest, alternating quickly. Cue: keep your back flat like a board. Common mistake: bouncing your hips up.', 'bodyweight'),
('8aff49a5-d3eb-427d-8428-d9c805b6a141', 'Saltos laterales', 29, 37, 1, 1, 'Avanzado', 'Salta lateralmente de una pierna a la otra buscando distancia. Cue: aterriza con estabilidad. Error: colapso de rodilla.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Side Jumps', 'Jump laterally from one leg to the other looking for distance. Cue: land with stability. Common mistake: knee collapse.', 'bodyweight'),
('8b0f1632-eb8a-44d7-b9a3-2a0cfb24df25', 'Plank slam', 25, 6, 240, 1, 'Avanzado', 'Desde plancha alta, toma el balón con una mano y golpéalo contra el suelo alternando lados. Requiere estabilidad excepcional del core. Mantén las caderas quietas mientras realizas el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank slam', 'From a high plank, take the ball with one hand and hit it against the ground, alternating sides. Requires exceptional core stability. Keep your hips still as you perform the movement.', 'external'),
('8b2cbec1-5803-4c71-bc17-67cd0218b02c', 'Leg Curl sentado pies flexionados', 55, NULL, 186, 1, 'Principiante', 'Flexiona rodillas sentado. Cue: pies activos. Error: levantar glúteo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Seated Leg Curl Feet Flexed', 'Bend your knees while sitting. Cue: active feet. Common mistake: glute lift.', 'external'),
('8b352ca2-34aa-4d9a-b72f-5143d0a524b4', 'Swing con Kettlebell', 29, 55, 281, 1, 'Principiante', 'Balancea la pesa rusa entre las piernas y utiliza un empuje explosivo de cadera para elevarla hasta la altura del pecho.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Kettlebell Swing', 'Swing the kettlebell between your legs and use an explosive hip drive to raise it to chest height.', 'external'),
('8b68041a-219d-41c8-b5ef-049d10ed0306', 'Decline roll out', 25, NULL, 271, 1, 'Avanzado', 'Roll out con las rodillas o pies elevados en un banco. Aumenta significativamente la dificultad al cambiar el ángulo. Requiere mayor fuerza y estabilidad. Progresa gradualmente aumentando la altura.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Decline Roll Out', 'Roll out with knees or feet elevated on a bench. Significantly increases the difficulty when changing the angle. Requires greater strength and stability. Gradually progress by increasing height.', 'external'),
('8b827ed8-eb0e-4411-977e-4208f4ad08ec', 'Fondos en anillas', 2, 1, 1, 1, 'Avanzado', 'Fondos en anillas gimnásticas con máxima inestabilidad. Significativamente más difícil que en paralelas. Mantén las anillas pegadas al cuerpo. Comienza con negativas y asistencias. Desarrolla estabilizadores del hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Ring bottoms', 'Dips on gymnastic rings with maximum instability. Significantly more difficult than parallel. Keep the rings close to your body. It starts with denials and assists. Develops shoulder stabilizers.', 'mixed'),
('8b860ad9-2741-4f68-9ffa-107406e3c610', 'Curl doble bíceps en polea', 17, NULL, 151, 1, 'Intermedio', 'Brazos en cruz, flexiona hacia las sienes. Cue: codos altos y fijos. Error: mover los codos hacia adelante o abajo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Double Biceps Cable Curl', 'Arms crossed, bend towards the temples. Cue: high, steady elbows. Common mistake: moving your elbows forward or down.', 'external'),
('8bd48f5f-cd86-4566-a567-2085f9425b7f', 'Giros rusos con disco', 25, 71, 81, 1, 'Principiante', 'Gira el torso con peso de lado a lado sentado. Cue: espalda recta. Error: mover solo los brazos.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Russian Twists with Disc', 'Twist your torso with weight from side to side while sitting. Cue: straight back. Common mistake: move only your arms.', 'external'),
('8bdafdc6-bbbb-4c72-a9de-fbf5858e37ea', 'Press hombros barra agarre estrecho', 6, 2, 116, 1, 'Intermedio', 'Press militar con manos juntas para tríceps. Cue: codos hacia adelante. Error: arquear la lumbar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Close Grip Bar Shoulder Press', 'Military press with joined hands for triceps. Cue: elbows forward. Common mistake: arching the lower back.', 'external'),
('8be68853-8a81-44f1-a827-e0d9a1707b48', 'Pájaros banco inclinado', 6, 71, 81, 1, 'Intermedio', 'Pecho en banco, eleva pesas lateralmente. Objetivo: deltoides posterior. Cue: codos fuera. Error: juntar escápulas.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Tilted Bench Birds', 'Chest bench, raise weights laterally. Target: posterior deltoid. Cue: elbows out. Common mistake: putting shoulder blades together.', 'external'),
('8bfcbfdb-97f4-4abe-b497-2125bb20a7d3', 'Meadows Row landmine', 71, 6, 116, 1, 'Intermedio', 'Rema a un brazo con extremo de barra landmine de lado. Cue: codo hacia afuera. Error: rotar cadera.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Meadows Row Landmine', 'One arm row with side landmine bar end. Cue: elbow out. Common mistake: rotate hip.', 'external'),
('8c109722-6763-46d9-9fde-a4d76cff5716', 'Russian Twist con pies elevados y Slam Ball', 25, NULL, 240, 1, 'Intermedio', 'Con los pies en el aire, gira el torso de lado a lado tocando el suelo con el balón medicinal pesado para trabajar los oblicuos.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Russian Twist with raised feet and Slam Ball', 'With your feet in the air, twist your torso from side to side touching the floor with the heavy medicine ball to work your obliques.', 'external'),
('8c2108b5-5406-42ab-a7c1-a95a0af8a940', 'Flexiones con manos anchas estables', 1, 6, 1, 1, 'Principiante', 'Manos más allá de la anchura de hombros, baja el pecho al suelo. Objetivo: énfasis en pectoral externo. Cue: codos a 45 grados. Error común: permitir que la cadera se hunda.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Push-ups with Stable Wide Hands', 'Hands beyond shoulder width, lower your chest to the floor. Target: emphasis on external chest. Cue: elbows at 45 degrees. Common mistake: allowing the hip to withoutk.', 'mixed'),
('8c47ba13-df4a-4e1b-9ca0-34cc2440c23c', 'L-Sit a Tuck Planche en paralelas', 25, 6, 1, 1, 'Avanzado', 'Realiza la transición dinámica desde una posición de L-Sit hasta una Tuck Planche, manteniendo siempre los brazos bloqueados y el core en máxima tensión.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'L-Sit a Tuck Planche in Parallels', 'Perform the dynamic transition from an L-Sit position to a Tuck Planche, always keeping your arms locked and your core in maximum tension.', 'bodyweight'),
('8c7697c2-5fb8-4a8f-9f9f-aa04fc2e1d28', 'Salto vertical rodilla a codo', 25, 28, 1, 1, 'Avanzado', 'Salta y lleva una rodilla hacia el codo opuesto en el aire. Dinamismo de core. Cue: giro rápido del torso. Error común: no saltar lo suficiente para el toque.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Knee to Elbow Vertical Jump', 'Jump and bring one knee to the opposite elbow in the air. core dynamism. Cue: rapid twist of the torso. Common mistake: not jumping enough for the touch.', 'bodyweight'),
('8c9bd24d-6132-4590-adea-2bcc0ddaac5a', 'Press Cubano a una mano con mancuerna', 6, 2, 81, 1, 'Intermedio', 'De pie, realiza un remo vertical, rota externamente el hombro 90 grados y termina con un press militar. Invierte el movimiento.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-Handed Cuban Press with Dumbbell', 'Standing, perform an upright row, externally rotate your shoulder 90 degrees, and finish with a military press. Reverse the movement.', 'external'),
('8cd8aeb3-dbc1-4b99-9e06-afb4265d69e2', 'Zancada reverencia salto', 29, 28, 1, 1, 'Avanzado', 'Zancadas cruzadas (curtsy lunges) alternando con saltos explosivos. Trabaja glúteos desde múltiples ángulos con componente pliométrico. Requiere coordinación y equilibrio excepcionales. Mantén el torso erguido durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stride bow jump', 'Cross strides (curtsy lunges) alternating with explosive jumps. It works gluteals from multiple angles with a plyometric component. He requires exceptional coordination and balance. Keep your torso upright during the movement.', 'mixed'),
('8cd8c30a-311b-4a3b-889a-e040763ebb50', 'Sentadilla patinadora en TRX', 28, 29, 216, 1, 'Principiante', 'Usa el TRX como soporte mientras realizas una sentadilla patinadora, llevando la rodilla libre hacia el suelo por detrás del talón de apoyo.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'TRX skate squat', 'Use the TRX as support while performing a skating squat, bringing your free knee toward the ground behind the supporting heel.', 'mixed'),
('8d4d6e06-f086-4cf1-af91-b9ab560779b3', 'Elevación de rodillas colgado en barra', 25, 37, 1, 1, 'Intermedio', 'Colgado de barra, lleva las rodillas hacia el pecho de forma controlada. Objetivo: fuerza abdominal inferior. Cue: no te balancees. Error común: usar el impulso de las piernas para realizar el movimiento.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Bar Hanging Knee Raise', 'Hanging from a bar, bring your knees towards your chest in a controlled manner. Target: lower abdominal strength. Cue: don''t swing. Common mistake: using the momentum of your legs to perform the movement.', 'bodyweight'),
('8d62e416-119b-473d-bcd5-2f29586e7c40', 'Press Overhead medio arrodillado alterno con mancuernas', 6, 2, 81, 1, 'Intermedio', 'En posicion de caballero, alterna el press de hombros con mancuernas, lo que incrementa la demanda de estabilidad lateral del core.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Alternating Half Kneeling Overhead Press with Dumbbells', 'In a half-kneeling position, alternate the shoulder press with dumbbells, which increases the demand for lateral stability of the core.', 'external'),
('8da952f7-083f-4811-a812-94c2c941fc91', 'Curl barra Z de pie', 17, 100, 116, 1, 'Principiante', 'Realiza un curl de bíceps de pie con barra Z. Mantén los codos cerca del cuerpo, eleva la barra de forma controlada y evita balancear el tronco.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Standing EZ-Bar Curl', 'Perform a standing EZ-bar biceps curl. Keep the elbows close to the body, curl the bar under control, and avoid swinging the torso.', 'external'),
('8e46fb66-169d-4d4d-9d22-e052aa917f93', 'Remo en anillas', 71, 17, 1, 1, 'Principiante', 'Sujeta las anillas e inclina el cuerpo hacia atrás. Manteniendo el cuerpo alineado, tira del pecho hacia las anillas y regresa a la posición inicial extendiendo los brazos.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Ring rowing', 'Hold the rings and lean your body back. Keeping your body aligned, pull your chest toward the rings and return to the starting position by extending your arms.', 'bodyweight'),
('8e4b9f4a-758a-40a0-9c02-21a54233e897', 'Typewriter pull ups', 16, 17, 1, 1, 'Avanzado', 'Realiza una dominada y en la posición superior, desplázate lateralmente llevando la barbilla de una mano a la otra manteniendo la altura. Es como escribir en una máquina de escribir en la barra. Requiere fuerza isométrica excepcional y control del movimiento lateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Typewriter Pull Ups', 'Perform a pull-up and, in the top position, move laterally so your chin travels from one hand to the other while staying at the same height. It is like typing on the bar. It requires exceptional isometric strength and lateral control.', 'mixed'),
('8e611e2f-c9d7-4873-b83b-909449f7a724', 'Zancada posterior cable', 28, 29, 151, 1, 'Avanzado', 'Zancadas hacia atrás con resistencia de cable frontal. Añade componente de estabilización anterior. Mantén torso erguido resistiendo la tracción del cable. Excelente para atletas que necesitan desaceleración.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable rear stride', 'Stride backwards with front cable resistance. Adds anterior stabilization component. Keep your torso upright by resisting cable pull. Excellent for athletes who need deceleration.', 'external'),
('8ecda888-e899-447f-b281-2b2b9860f82b', 'Step Up Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Sube a un banco sosteniendo dos pesas rusas en el pecho (front rack), manteniendo los codos arriba y el torso erguido.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Double Kettlebell Front Rack Step-up', 'Step onto a bench while holding two kettlebells in the front rack position, keeping your elbows high and your torso upright.', 'external'),
('8ee3d6c9-ef70-48b1-afab-f95e7ec8a74b', 'Battle ropes ondas un brazo', 6, 25, 256, 24, 'Principiante', 'Ondas brazo solo. Objetivo: hombro/resistencia. Cue: core bloqueado. Error: rotar torso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Single-Arm Battle Rope Waves', 'single arm waves. Target: shoulder endurance. Cue: locked core. Common mistake: rotate torso.', 'external'),
('8f05d372-8d09-4bf0-83ad-13d109d13994', 'Plank frontal a una mano con pies elevados sobre Fitball', 25, 6, 290, 24, 'Avanzado', 'Apoya un antebrazo en el suelo y coloca ambos pies sobre el Fitball inestable mientras mantienes la plancha con un solo apoyo de brazo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Single-Arm Front Plank with Feet Elevated on Stability Ball', 'Place one forearm on the floor and place both feet on the unstable stability ball while holding the plank with just one arm support.', 'bodyweight'),
('8ffa287b-b5f5-425b-88f3-aa00211c023d', 'Zancada caminando con barra tras nuca', 28, 29, 116, 1, 'Intermedio', 'Camina realizando zancadas con una barra apoyada sobre los trapecios, manteniendo el equilibrio y el core activado en cada paso.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Walking Back Squat Lunge', 'Walk forward performing lunges with a barbell resting across your upper traps, maintaining your balance and keeping your core engaged on every step.', 'external'),
('900a8049-24e8-4661-82b5-45635303906a', 'Press Overhead Seesaw medio arrodillado con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'En posición de caballero, alterna el press de hombros con dos Kettlebells en un movimiento rítmico, desafiando el equilibrio del torso.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Double kettlebell Half Kneeling Overhead Seesaw Press', 'In a half-kneeling position, alternate the shoulder press with two kettlebells in a rhythmic movement, challenging the balance of the torso.', 'external'),
('9022dbe3-a937-4fd8-9e52-5e346371a5eb', 'Sentadilla a banco', 28, 29, 1, 1, 'Principiante', 'Baja la cadera como en una sentadilla normal hasta que tus glúteos toquen ligeramente el banco y vuelve a subir inmediatamente.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Bench Squat', 'Lower your hips as in a normal squat until your glutes lightly touch the bench and immediately go back up.', 'mixed'),
('9041bfc4-8d4a-4a10-9ff7-17338f5da966', 'Extensión de tríceps tras nuca sentado', 2, NULL, 81, 1, 'Principiante', 'Sujeta una mancuerna con ambas manos y bájala tras la cabeza. Codos cerrados. Espalda recta. No arquees la zona lumbar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Seated back neck triceps extension', 'Hold a dumbbell with both hands and lower it behind your head. Elbows closed. Straight back. Do not arch your lower back.', 'external'),
('9047bce5-d1f6-43ea-b68f-6e10ed4cbdfc', 'Thruster con Kettlebell doble', 28, 6, 281, 1, 'Intermedio', 'Sujeta dos Kettlebells en rack, baja en sentadilla profunda y aprovecha la inercia de la subida para presionar ambas pesas al techo.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Double Kettlebell Thruster', 'Hold two kettlebells in the rack position, descend into a deep squat, and use the upward momentum to press both weights overhead.', 'external'),
('906149cb-71a7-4a62-8194-fc5b24c977a5', 'Fondos lastrados', 2, 1, 1, 1, 'Avanzado', 'Fondos en paralelas con lastre para pectoral y tríceps, controlando profundidad y evitando colapsar hombros.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Weighted bottoms', 'Parallel dips with weight for pectorals and triceps, controlling depth and avoiding collapsing shoulders.', 'mixed'),
('909f416c-70af-440d-9534-f7c08ee91279', 'Patada de tríceps con mancuerna', 2, NULL, 81, 1, 'Principiante', 'Torso inclinado, extiende el brazo hacia atrás manteniendo el codo fijo. Objetivo: aislamiento de la cabeza lateral del tríceps. Cue: bloquea el brazo arriba 1 segundo. Error común: balancear la mancuerna como un péndulo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Dumbbell Triceps Kick', 'Inclined torso, extend your arm backwards, keeping your elbow fixed. Target: isolation of the lateral head of the triceps. Cue: lock arm up for 1 second. Common mistake: swinging the dumbbell like a pendulum.', 'external'),
('90b18419-e8d7-4d9d-b642-3df05d63a754', 'Lanzamiento rotacional con paso', 25, 6, 240, 1, 'Intermedio', 'Realiza un paso hacia adelante mientras lanzas el balón lateralmente contra una pared. Potencia dinámica. Cue: pivota el pie trasero. Error común: arrastrar el pie trasero en lugar de pivotar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Rotational Step Throw', 'Take a step forward while throwing the ball laterally against a wall. Dynamic power. Cue: pivot the back foot. Common mistake: dragging the back foot instead of pivoting.', 'external'),
('90dc3775-8b77-45b9-984f-b182e38ff669', 'Parallette Push Up', 1, 2, 1, 1, 'Intermedio', 'Agarra las paralelas y coloca el cuerpo en posición de plancha. Baja el pecho más allá del nivel de las manos para un mayor rango de movimiento, luego empuja hacia arriba hasta extender los brazos.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Parallette Push Up', 'Grab the parallel bars and place your body in a plank position. Lower your chest past the level of your hands for a greater range of motion, then push up until your arms are extended.', 'mixed'),
('912357f1-43c1-4b44-9b4e-2f153cbdec01', 'Peso muerto con piernas semi-rígidas', 55, 71, 116, 1, 'Intermedio', 'Baja la barra rozando las piernas con las rodillas casi bloqueadas (mínima flexión). Objetivo: estiramiento máximo de isquiotibiales. Cue: lleva la cadera muy atrás. Error común: redondear la zona lumbar al bajar.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Deadlift with Semi-rigid Legs', 'Lower the bar, rubbing your legs with your knees almost locked (minimal flexion). Target: maximum hamstring stretch. Cue: bring your hips very far back. Common mistake: rounding the lower back when lowering.', 'external'),
('91259ef7-b72a-4003-88b7-252e1145f221', 'Dislocaciones alternas de hombro con banda elástica', 6, NULL, 61, 1, 'Principiante', 'Realiza el movimiento de dislocacion de hombro pasando los brazos de forma alterna sobre la cabeza para mejorar la movilidad articular.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Alternate shoulder dislocations with elastic band', 'Perform the shoulder dislocation movement by passing your arms alternately over your head to improve joint mobility.', 'external'),
('914e0ff0-dbd2-4db8-817c-f2b64f6ef5e5', 'Goblet squat kettlebell', 28, 29, 281, 1, 'Principiante', 'Sostén la kettlebell contra el pecho con ambas manos como un cáliz. Realiza sentadillas manteniendo el torso erguido. La posición del peso ayuda a mantener mejor postura. Excelente para aprender la técnica correcta de sentadilla.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Goblet squat kettlebell', 'Hold the kettlebell against your chest with both hands like a goblet. Perform squats while keeping your torso upright. The position of the weight helps maintain better posture. Excellent for learning correct squat technique.', 'external'),
('9163316e-0fb9-45a8-b46b-fb5116f2817d', 'Salto de profundidad lateral', 37, 28, 1, 1, 'Avanzado', 'Cae de un cajón y salta lateralmente de forma inmediata sobre un obstáculo. Mejora la absorción de fuerza y redirección. Cue: contacto mínimo con el suelo. Error común: dejar que la rodilla se hunda hacia adentro.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Depth Jump', 'Fall off a box and immediately jump laterally over an obstacle. Improves force absorption and redirection. Cue: minimal contact with the ground. Common mistake: letting the knee withoutk inward.', 'bodyweight'),
('91919c61-0c5a-421e-bda1-d13b89c02723', 'Peso muerto maleta con Kettlebell a una mano', 71, 55, 281, 1, 'Principiante', 'Levanta la Kettlebell del suelo con una mano a un costado del cuerpo, manteniendo la espalda recta y evitando inclinaciones laterales.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Suitcase deadlift with one-hand kettlebell', 'Lift the kettlebell off the floor with one hand at the side of your body, keeping your back straight and avoiding lateral tilts.', 'external'),
('91a3e724-3f96-4745-a947-7637c28aa343', 'Plank bosu', 25, 6, 298, 24, 'Intermedio', 'Plancha con antebrazos o manos sobre el bosu. La inestabilidad multiplica la activación del core. Puede hacerse con el lado redondo hacia arriba o abajo según el nivel. Resiste activamente el movimiento manteniendo el cuerpo alineado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank bosu', 'Plank with forearms or hands on the bosu. Instability multiplies core activation. It can be made with the round side up or down depending on the level. Actively resist movement by keeping your body aligned.', 'bodyweight'),
('925d3517-b417-4350-af4f-3f42263db8dd', 'Puente de glúteo isométrico con extensión alterna', 29, 55, 1, 1, 'Intermedio', 'Mantén la posición alta del puente de glúteo. Sin bajar la cadera, extiende una pierna hacia adelante, regresa y cambia de pierna alternativamente.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Isometric glute bridge with alternating extension', 'Maintain the high glute bridge position. Without lowering your hips, extend one leg forward, return and switch legs alternately.', 'mixed'),
('92a1bb97-9eb3-48ee-937a-613b801c9c8c', 'Remo búlgaro en anillas con pies elevados', 71, 17, 1, 1, 'Intermedio', 'Realiza un remo en anillas con pies elevados y codos abiertos hacia afuera para enfatizar el deltoides posterior y la parte alta de la espalda.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Ring Row with Elevated Feet', 'Perform a ring row with your feet raised and elbows spread out to emphasize the rear deltoids and upper back.', 'bodyweight'),
('92a77dc9-fbda-4686-ba6f-3bff28509a67', 'Sentadilla pistol TRX', 28, 29, 216, 1, 'Avanzado', 'Sentadilla a una pierna usando TRX para asistencia mínima. Permite aprender el patrón de movimiento con apoyo. Reduce gradualmente la dependencia del TRX. Mantén el talón plantado y la rodilla alineada.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX pistol squat', 'One leg squat using TRX for minimal assistance. Allows you to learn the movement pattern with support. Gradually reduce dependence on TRX. Keep your heel planted and your knee aligned.', 'assisted'),
('92d8153d-4d04-4ddc-9049-05e9dfa9355f', 'Around the World medio arrodillado con captura alta', 25, 6, 281, 1, 'Intermedio', 'Arrodillado en posicion de caballero, pasa la pesa rusa alrededor de tu cintura intercambiandola de mano y realizando una captura alta frente al pecho.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Half-Kneeling Around the World with High Catch', 'Kneeling in a half-kneeling position, pass the kettlebell around your waist, exchanging hands and performing a high catch in front of your chest.', 'external'),
('932d05ca-0d5a-4b50-9f01-600d45649f1d', 'Remo unilateral en polea alta', 16, 17, 151, 1, 'Intermedio', 'De rodillas o sentado, tira de un estribo hacia el hombro con un solo brazo. Objetivo: dorsal aislado. Cue: codo hacia el bolsillo lateral. Error común: rotar el tronco excesivamente hacia la polea.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Unilateral High Cable Row', 'Kneeling or sitting, pull a stirrup toward your shoulder with one arm. Target: isolated dorsal. Cue: elbow towards side pocket. Common mistake: rotating the torso excessively towards the cable.', 'external'),
('93391b55-2840-4f1e-a7b2-06032e1e04ea', 'Press de banca inclinado agarre cerrado con barra Z', 2, 1, 116, 1, 'Principiante', 'Tumbado en un banco inclinado, sujeta la barra Z con un agarre estrecho. Baja la barra hacia la parte superior del pecho flexionando los codos y extiende los brazos con fuerza para trabajar el triceps.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Close Grip Incline Bench Press with Z Bar', 'Lying on an incline bench, hold the Z-bar with a close grip. Lower the bar towards the upper part of the chest by bending the elbows and extend the arms strongly to work the triceps.', 'external'),
('937cfd17-7edf-4252-9ce2-0518ae2c6a22', 'Sentadilla anderson', 28, 29, 116, 1, 'Avanzado', 'Similar a sentadilla desde pines pero comenzando desde la posición más baja posible. Nombrada por Paul Anderson. Desarrolla fuerza absoluta desde posición desfavorable. Progresa subiendo gradualmente los pines.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Anderson squat', 'Similar to squat from pins but starting from the lowest position possible. Named after Paul Anderson. Develop absolute strength from an unfavorable position. Progress by gradually moving up the pins.', 'external'),
('93991735-524f-4c21-ae48-c68691ace3c6', 'Molino de viento mancuernas', 25, 6, 81, 1, 'Avanzado', 'Con una mancuerna extendida sobre la cabeza, realiza una flexión lateral controlada tocando el suelo con la mano libre mientras mantienes la vista en la mancuerna. Requiere gran flexibilidad en caderas y isquiotibiales, además de estabilidad del hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Windmill', 'With one dumbbell extended overhead, perform a controlled lateral bend by touching the floor with your free hand while keeping your eyes on the dumbbell. This exercise requires good hip and hamstring flexibility as well as shoulder stability.', 'external'),
('93c92e31-f5a5-4c3d-82bd-fd9ec3623f45', 'Remo con barra inclinado', 71, 17, 116, 1, 'Intermedio', 'Torso a 45 grados, tira de la barra hacia el ombligo retrayendo escápulas. Cue: codos hacia atrás. Error: erguirse durante la serie por fatiga.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Bent-over Barbell Row', 'torso at 45 degrees, pull the bar towards the navel, retracting the scapulae. Cue: elbows back. Common mistake: standing up during the set due to fatigue.', 'external'),
('93d593fe-5f88-48ab-98e1-7984b1aa5573', 'Curl bíceps cable', 17, NULL, 151, 1, 'Principiante', 'Con la polea baja y una barra recta o EZ, realiza curls manteniendo los codos fijos a los costados. El cable proporciona tensión constante durante todo el rango de movimiento, incluso en la posición superior donde las mancuernas pierden tensión.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Biceps Curl', 'With the low cable and a straight or EZ bar, perform curls while keeping your elbows fixed to your sides. The cable provides constant tension throughout the entire range of motion, even in the top position where the dumbbells lose tension.', 'external'),
('94532bf8-78b3-48c6-bc53-6ce891ae72cb', 'Slam lateral de balón', 25, 6, 240, 1, 'Principiante', 'Lanza el balón medicinal contra el suelo a tu lado sin rotar el tronco excesivamente. Fuerza explosiva de oblicuos. Cue: brazos estirados al inicio. Error común: dejar que el balón golpee tus pies.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Ball Slam', 'Throw the medicine ball against the ground next to you without rotating your torso excessively. Explosive oblique strength. Cue: arms stretched at the start. Common mistake: letting the ball hit your feet.', 'external'),
('94918148-fce8-4f27-8db3-ebd801227d1e', 'Ring Plank', 25, 6, 1, 24, 'Intermedio', 'Realiza una plancha apoyando las manos o antebrazos en las anillas, resistiendo la inestabilidad de las mismas para activar el core.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Ring Plank', 'Perform a plank resting your hands or forearms on the rings, resisting their instability to activate the core.', 'bodyweight'),
('94d50791-9be5-4b1b-a58e-5140a37b2945', 'Sentadilla con salto', 28, 29, 1, 1, 'Intermedio', 'Sentadilla explosiva despegando del suelo. Cue: aterriza con las puntas. Error: aterrizaje rígido.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Jump Squat', 'Explosive squat taking off from the ground. Cue: land on your toes. Common mistake: hard landing.', 'mixed'),
('94e36f1b-d510-4077-b67a-c8543af81b98', 'Circle roll out', 25, NULL, 271, 1, 'Avanzado', 'Realiza círculos completos con la rueda en lugar de líneas rectas. Extremadamente desafiante para el core. Comienza con círculos pequeños y aumenta gradualmente. Alterna direcciones para trabajo equilibrado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Circle Roll Out', 'Make complete circles with the wheel instead of straight lines. Extremely challenging for the core. Start with small circles and gradually increase. Alternate directions for balanced work.', 'external'),
('9501ecb2-c1a7-4079-b1e2-8a86221fdedb', 'Escapular Pull Up en anillas', 71, 17, 1, 1, 'Intermedio', 'Cuelgate de las anillas y realiza pequeñas elevaciones activando solo las escapulas, manteniendo los brazos completamente rectos.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Scapular Pull Up in Rings', 'Hang from the rings and perform small lifts, activating only the shoulder blades, keeping your arms completely straight.', 'mixed'),
('950a0386-b819-42de-ac51-c45e160e72fe', 'Press pecho polea pie un pie delante', 1, 2, 151, 1, 'Principiante', 'Empuja cables al frente de pie. Cue: base estable. Error: inclinar torso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Foot Pulley Chest Press, One Foot Forward', 'Push cables to the front while standing. Cue: stable base. Common mistake: tilt torso.', 'external'),
('9513a12c-f28b-41b3-8086-8c81c6f806df', 'Elevación Lu sentado con discos', 6, NULL, 81, 1, 'Intermedio', 'Sentado, realiza una elevacion lateral completa con discos o mancuernas ligeras hasta que se toquen sobre la cabeza, enfatizando el deltoides lateral.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Seated Lu Lift with Plates', 'Seated, perform a full lateral raise with plates or light dumbbells until they touch overhead, emphasizing the lateral deltoid.', 'external'),
('95141383-8fee-45c8-8390-c8aec1caf43f', 'Salto de rana', 29, 28, 1, 1, 'Intermedio', 'Salto largo partiendo de una sentadilla profunda y terminando en sentadilla. Potencia de extensión de cadera. Cue: brazos hacia adelante al saltar. Error común: redondear la espalda baja al aterrizar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Frog Jump', 'Long jump starting from a deep squat and ending in a squat. Hip extension power. Cue: arms forward when jumping. Common mistake: rounding the lower back when landing.', 'mixed'),
('95479d10-865d-4c33-87cb-b12f36d36d1f', 'Thruster barra', 6, 28, 116, 1, 'Intermedio', 'Combina una sentadilla frontal con un press de hombros en un movimiento fluido continuo. Desciende en sentadilla frontal y al subir usa el impulso para presionar la barra sobre la cabeza. Excelente ejercicio metabólico que desarrolla potencia y resistencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Thruster', 'Combine a front squat with an overhead press in one continuous movement. Lower into a front squat and use the upward drive to press the bar overhead. This is an excellent metabolic exercise for power and endurance.', 'external'),
('954c2c21-a706-47f7-9d49-8f15cedb23cd', 'Cable Rope Staggered Stance High to Low Chop', 25, NULL, 151, 1, 'Intermedio', 'De pie con un pie delante del otro, tira del cable desde arriba cruzando el cuerpo hacia abajo, usando el core para rotar.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Cable Rope Staggered Stance High to Low Chop', 'Standing with one foot in front of the other, pull the cable from above across your body and down, using your core to rotate.', 'external'),
('955bc951-fc8b-4700-bade-f83d4ca51d75', 'Hollow Body Hold', 25, NULL, 1, 24, 'Intermedio', 'Acuéstate boca arriba y presiona la espalda baja contra el suelo. Levanta las piernas y los hombros simultáneamente, formando una banana con el cuerpo. Mantén la posición.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Hollow Body Hold', 'Lie on your back and press your lower back into the floor. Raise your legs and shoulders simultaneously, forming a banana with your body. Hold the position.', 'bodyweight'),
('95c584f4-8d23-42d8-8432-f6337e28d47f', 'Rueda abdominal rodillas', 25, 71, 271, 1, 'Intermedio', 'Desliza la rueda adelante manteniendo el abdomen contraído y vuelve. Core potente. Espalda neutra. No dejes caer la cadera al suelo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Ab Wheel Knees', 'Slide the wheel forward, keeping your abs contracted, and return. Powerful core. Neutral back. Don''t let your hips fall toward the floor.', 'external'),
('95e48c8f-c33f-4b85-9bec-02cfed8a9d42', 'Remo unilateral con mancuerna', 71, 17, 81, 1, 'Principiante', 'Un pie y mano en banco, tira de la mancuerna hacia la cadera con el otro brazo. Cue: espalda paralela al suelo. Error: girar el tronco al tirar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Unilateral Dumbbell Row', 'One foot and hand on the bench, pull the dumbbell toward your hip with the other arm. Cue: back parallel to the floor. Common mistake: turning the torso when pulling.', 'external'),
('962de55a-b673-4af2-a974-eebab72506f9', 'Step Up contralateral Front Rack con Kettlebell a una mano', 28, 29, 281, 1, 'Intermedio', 'Sostén la Kettlebell en posición de rack en un hombro y sube al banco con la pierna opuesta, manteniendo el core firme.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Single-Kettlebell Front Rack Step-up', 'Hold the kettlebell in the front rack position and step onto the bench with the opposite leg, keeping your core tight.', 'external'),
('964d2ac3-2309-4c1a-89ed-93b965f52082', 'Press Militar Sentado', NULL, 2, 81, 1, 'Intermedio', 'Sentado con la espalda apoyada en un banco, empuja la barra desde la altura de los hombros hasta extender casi por completo los codos. Mantén el core firme y evita arquear la zona lumbar.', FALSE, NULL, '2025-12-11T19:27:04.572597+00:00', 'Seated Military Press', 'Sitting with your back supported on a bench, push the bar from shoulder height until your elbows are almost fully extended. Keep your core firm and avoid arching your lower back.', 'external'),
('9658419f-7220-42f2-a9bc-4ecdea7a0cfd', 'Reverse curl barra', 100, 17, 116, 1, 'Principiante', 'Realiza curls con agarre prono (palmas hacia abajo). Este agarre enfatiza el trabajo del braquiorradial y los extensores del antebrazo. Usa menos peso que en el curl tradicional y mantén las muñecas firmes durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Reverse curl bar', 'Perform curls with an overhand grip (palms facing down). This grip emphasizes the work of the brachioradialis and the extensors of the forearm. Use less weight than in traditional curls and keep your wrists firm throughout the movement.', 'external'),
('965b6ed5-1cd0-4758-96d4-8bdacd418418', 'Push Press en postura escalonada con barra', 6, 2, 116, 1, 'Intermedio', 'Con un pie ligeramente adelantado, utiliza un impulso explosivo de piernas para empujar la barra desde los hombros hasta sobre la cabeza.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Push Press in a staggered stance with a barbell', 'With one foot slightly forward, use an explosive leg drive to push the bar from your shoulders to overhead.', 'external'),
('966e89d2-e321-4750-b1b0-d827348ed647', 'Zancada trasera corporal', 28, 29, 1, 1, 'Principiante', 'Da un paso atrás bajando la rodilla hacia el suelo y vuelve al centro. Objetivo: fuerza de piernas y estabilidad. Cue: rodilla delantera a 90 grados. Error común: golpear la rodilla trasera contra el suelo.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Rear Body Stride', 'Take a step back by lowering your knee to the floor and return to the center. Target: leg strength and stability. Cue: front knee at 90 degrees. Common mistake: Hitting the back knee against the ground.', 'bodyweight'),
('966f7f92-74de-44b0-b47b-ae9d6ecadaa5', 'Lanzamiento balón espaldas', 25, 6, 240, 1, 'Avanzado', 'Lanza el balón hacia adelante girando el cuerpo rápidamente 180 grados. Coordinación rotacional extrema. Cue: gira sobre un eje central. Error común: lanzamiento inestable por falta de equilibrio.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Throwing the Ball Backwards', 'Throw the ball forward by quickly turning your body 180 degrees. Extreme rotational coordination. Cue: rotates on a central axis. Common mistake: unstable launch due to lack of balance.', 'external'),
('96779fa3-fc27-42a8-8a6e-0076f6b8e048', 'Curl excéntrico de isquiotibiales con Slider', 55, 29, 1, 1, 'Intermedio', 'En posicion de puente de gluteo, desliza los talones lentamente hacia adelante sobre los sliders controlando el descenso hasta estirar las piernas.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Eccentric Hamstring Curl with Slider', 'In a gluteal bridge position, slide your heels slowly forward on the sliders, controlling the descent until your legs are straight.', 'bodyweight'),
('967927e1-35da-4b8f-8e2b-b8f4be2eb9a0', 'Battle ropes spirals', 6, 25, 256, 24, 'Intermedio', 'Realiza movimientos circulares con ambas cuerdas, hacia adentro o hacia afuera. Trabaja los hombros desde diferentes ángulos. Mantén los círculos amplios y controlados. El core debe mantenerse estable.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Spirals', 'Make circular movements with both ropes, inwards or outwards. Work your shoulders from different angles. Keep the circles wide and controlled. The core must remain stable.', 'external'),
('96858e3a-4495-4398-9a28-bfcc380fbc91', 'Rotación de cadera con cable', 29, NULL, 151, 1, 'Intermedio', 'De pie de lado a la polea. Con la pierna exterior estirada, realiza un movimiento de barrido circular o rotacional cruzando el cuerpo.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Hip Rotation', 'Stand sideways to the cable. With your outside leg straight, perform a circular or rotational sweeping motion across your body.', 'external'),
('969c8f3e-3ce6-43bd-ab22-4099ae4514be', 'Front Lever circular en anillas', 25, 16, 1, 1, 'Avanzado', 'Manten la posicion de Front Lever y realiza movimientos circulares controlados con el cuerpo para desafiar la estabilidad del core y dorsales.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Circular Front Lever in Rings', 'Maintain the Front Lever position and perform controlled circular movements with the body to challenge the stability of the core and lats.', 'bodyweight'),
('96a63078-7500-491b-9cf5-53be6cd1be2d', 'Caminata de oso', 13, 6, 1, 24, 'Principiante', 'Desplazamiento a cuatro patas con rodillas cerca del suelo. Estabilidad total. Core activo. No levantes mucho la cadera.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Bear Walk', 'Moving on all fours with knees close to the ground. Total stability. Active core. Don''t raise your hips too much.', 'bodyweight'),
('96d09d0e-e5a3-4a00-a851-e8c8d3d5d663', 'Jalón pecho agarre neutro', 16, 17, 151, 1, 'Intermedio', 'Realiza un jalón al pecho con agarre neutro. Lleva el agarre hacia la parte alta del pecho manteniendo el torso estable y controlando la subida.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Neutral Grip Lat Pulldown', 'Perform a neutral grip lat pulldown. Pull the handle toward the upper chest while keeping the torso stable and controlling the return.', 'external'),
('973ddb94-aa99-4ffe-83bc-a65031b765d4', 'Salto pogo adelante y atrás', 64, 309, 1, 1, 'Principiante', 'Saltos cortos rápidos cruzando una línea adelante y atrás. Objetivo: rapidez de pies. Cue: mirada al frente, no al suelo. Error común: apoyar el talón en cada salto.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Pogo Jump Back and Forth', 'Quick short jumps crossing a line back and forth. Target: quickness of feet. Cue: look forward, not at the ground. Common mistake: placing your heel on each jump.', 'bodyweight'),
('9748ff89-4439-4a75-8a3e-812ac4aed475', 'Cable Pull Through arrodillado', 29, 55, 151, 1, 'Principiante', 'Arrodillado de espaldas a la polea, sujeta la cuerda entre las piernas. Flexiona la cadera y luego extiende con fuerza apretando los gluteos.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Cable Pull Through Kneeling', 'Kneeling with your back to the cable, hold the rope between your legs. Flex your hips and then extend them strongly, squeezing your glutes.', 'external'),
('974aea91-b2cb-4742-aac1-ca6e9ad96aaa', 'Shrugs cable', 71, NULL, 151, 1, 'Principiante', 'Con polea baja o cables laterales, realiza elevaciones de hombros. El cable permite diferentes ángulos de resistencia comparado con mancuernas o barra. Mantén la contracción superior y evita rotar los hombros. Desarrolla los trapecios superiores.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Shrugs', 'Using a low cable or lateral cables, perform shoulder raises. The cable allows for different angles of resistance compared to dumbbells or barbells. Maintain the upper contraction and avoid rotating your shoulders. Develops the upper trapezius.', 'external'),
('97534af0-5725-42f6-b565-463ed7b34feb', 'Remo en polea baja con cuerda', 71, 17, 151, 1, 'Principiante', 'Sentado, tira de la cuerda hacia el abdomen abriendo los extremos al final. Objetivo: espalda alta y retractores. Cues: saca pecho y retrae escápulas. Error común: realizar tirones con la zona lumbar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Low Cable Row with Rope', 'Sitting, pull the rope towards your abs, opening the ends at the end. Target: upper back and retractors. Cue: chest out and retract scapulae. Common mistake: pulling with the lower back.', 'external'),
('97aed981-75e7-424d-b29e-fc6a9aaa99e6', 'Prensa piernas', 28, 29, 186, 1, 'Principiante', 'Sentado o tumbado en la máquina, empuja la plataforma extendiendo las piernas. No bloquees completamente las rodillas en la extensión. La posición de los pies determina el énfasis muscular: más alto para glúteos, más bajo para cuádriceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Leg press', 'Sitting or lying on the machine, push the platform by extending your legs. Do not completely lock your knees in extension. The position of the feet determines the muscular emphasis: higher for glutes, lower for quads.', 'external'),
('97bb6d1c-1dff-4790-9598-099d3a7a286b', 'Salto en profundidad', 28, 29, 1, 1, 'Avanzado', 'Déjate caer desde una altura y al aterrizar realiza inmediatamente un salto vertical máximo. Entrena el ciclo estiramiento-acortamiento. Método pliométrico avanzado. Comienza con alturas bajas (30-40cm) y progresa cuidadosamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Depth jump', 'Drop from a height and upon landing immediately make a maximum vertical jump. Train the stretch-shortening cycle. Advanced plyometric method. Start with low heights (30-40cm) and progress carefully.', 'bodyweight'),
('97d51b34-c363-4e55-b7e0-b379b10458db', 'Spider Curl con mancuernas', 17, NULL, 81, 1, 'Intermedio', 'Pecho apoyado en banco inclinado mirando hacia abajo, deja colgar los brazos y flexiona las pesas. Objetivo: aislamiento extremo del bíceps. Cues: codos perpendiculares al suelo. Error común: balancear las mancuernas para ganar inercia.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Dumbbell Spider Curl', 'Chest resting on an inclined bench looking down, let your arms hang and flex the weights. Target: extreme isolation of the biceps. Cue: elbows perpendicular toward the floor. Common mistake: swinging the dumbbells to gain inertia.', 'external'),
('97f16f44-fda0-4df6-b180-41af4f5e1e68', 'Giros rusos battle ropes', 25, 6, 256, 24, 'Intermedio', 'Sentado con las cuerdas, realiza giros rusos moviendo las cuerdas de lado a lado. El peso y la inercia de las cuerdas aumentan significativamente la dificultad. Mantén los pies elevados para mayor intensidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Russian Twists Battle Ropes', 'Sitting on the ropes, perform Russian twists by moving the ropes from side to side. The weight and inertia of the ropes significantly increase the difficulty. Keep your feet raised for greater intensity.', 'external'),
('97ff3b1e-2c90-44ad-8bac-eb400fc217b0', 'Remo mancuerna sierra', 16, 17, 81, 1, 'Intermedio', 'Remo con ligero balanceo pendular. Objetivo: dorsal inferior. Cue: estira total abajo. Error: rotar tronco.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Rowing Dumbbell Saw', 'Rowing with slight pendulum swing. Target: lower dorsal. Cue: full stretch down. Common mistake: rotate torso.', 'external'),
('9806d84d-ea57-4660-aee3-228cb3164e09', 'Extensión de espalda fitball', 71, NULL, 290, 1, 'Principiante', 'Tumbado boca abajo sobre la fitball con la pelvis apoyada, realiza extensiones de espalda. Permite un rango de movimiento natural y seguro. Evita hiperextender. Puedes cruzar los brazos sobre el pecho o extenderlos para mayor dificultad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stability Ball Back Extension', 'Lying face down on the stability ball with your pelvis supported, perform back extensions. Allows a natural and safe range of motion. Avoid hyperextending. You can cross your arms over your chest or extend them for greater difficulty.', 'bodyweight'),
('9890e657-a04a-4590-ae7a-59ca73768efc', 'Flexión Dive Bomber en paralelas', 1, 2, 1, 1, 'Intermedio', 'Desde posicion de V invertida en paralelas, baja el pecho en arco hacia adelante y sube extendiendo los brazos, imitando el vuelo de un bombardero.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Dive Bomber push-up on parallel bars', 'From an inverted V position in parallel, lower your chest in an arc forward and rise by extending your arms, imitating the flight of a bomber.', 'mixed'),
('98df1db4-63a0-4f78-8a65-8c136b32353a', 'Flexión a una mano en TRX', 1, 25, 216, 1, 'Intermedio', 'Sujeta una sola correa de TRX e inclina el cuerpo para realizar una flexion con un solo brazo, desafiando la estabilidad total del core.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'One-handed push-up on TRX', 'Hold a single TRX strap and tilt your body to perform a one-arm push-up, challenging total core stability.', 'mixed'),
('98f4e7b1-8b36-42ce-a964-53106c90accd', 'Salto pogo con pies cruzados', 64, 309, 1, 1, 'Principiante', 'Saltos pogo rápidos cruzando un pie por delante del otro alternadamente. Cue: agilidad de pies. Error común: tropiezos por falta de coordinación.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Pogo Jump with Crossed Feet', 'Quick pogo jumps crossing one foot in front of the other alternately. Cue: foot agility. Common mistake: stumbling due to lack of coordination.', 'bodyweight'),
('99446b69-b554-4f05-8ed6-594e8e8e2248', 'Dominadas con peso', 16, 17, 1, 1, 'Avanzado', 'Dominadas con peso adicional usando cinturón, chaleco o mancuerna entre pies. Permite sobrecarga progresiva cuando el peso corporal no es suficiente. Mantén técnica estricta. Progresa gradualmente con el peso añadido.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Weighted pull-ups', 'Pull-ups with additional weight using a belt, vest or dumbbell between your feet. Allows progressive overload when body weight is not enough. Maintain strict technique. Progress gradually with added weight.', 'external'),
('9948fd28-6cb9-422a-9032-79e57c0edd5a', 'Step up explosivo con rodilla', 28, 25, 1, 1, 'Intermedio', 'Sube explosivamente a un banco y eleva la rodilla contraria alto al final. Potencia unilateral. Cue: empuja con el talón del pie apoyado. Error común: impulsarse con la pierna de atrás.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Explosive Step-up with Knee Drive', 'Step explosively onto a bench and drive the opposite knee high at the top. Builds unilateral power. Cue: push through the heel of the lead leg.', 'mixed'),
('9960e4d4-06e5-4cc0-98b9-540d176a1479', 'Puente de glúteo con abducción y Miniband', 29, 37, 61, 1, 'Intermedio', 'Realiza un puente de glúteo con una banda sobre las rodillas. En la posición alta, separa las rodillas (abducción), ciérralas y luego baja la cadera.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Glute bridge with abduction and Mini Band', 'Perform a glute bridge with a band on your knees. In the high position, spread your knees (abduction), close them, and then lower your hips.', 'external'),
('998bef50-7f2c-43c9-b473-bd684ead792f', 'Dominadas kipping', 16, 17, 1, 1, 'Avanzado', 'Dominadas usando impulso del cuerpo (balanceo) para completar más repeticiones. Popular en CrossFit. Permite mayor volumen pero con menos tensión muscular por repetición. Requiere técnica específica para evitar lesiones. No sustituye dominadas estrictas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kipping pull-ups', 'Pull-ups using body momentum (swing) to complete more repetitions. Popular in CrossFit. Allows greater volume but with less muscle tension per repetition. Requires specific technique to avoid injuries. It is not a substitute for strict pull-ups.', 'mixed'),
('99cd6755-ce51-4f9c-973a-9eeb2af70831', 'Sentadilla velocidad', 28, 29, 116, 1, 'Avanzado', 'Sentadillas con 50-60% del máximo enfocándose en velocidad explosiva. Método Westside. Desarrolla potencia y velocidad. 8-12 series de 2-3 reps con descansos cortos. Mantén aceleración máxima en todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Speed Squat', 'Squats with 50-60% of maximum focusing on explosive speed. Westside Method. Develop power and speed. 8-12 sets of 2-3 reps with short rests. Maintain maximum acceleration throughout the movement.', 'external'),
('99d43b23-5a0f-4ad1-8446-98d45c15d076', 'Thruster Cosaco con Kettlebell doble', 6, 28, 281, 1, 'Avanzado', 'Realiza una sentadilla cosaca lateral profunda con Kettlebells en rack y presionalas sobre la cabeza al volver a la posicion central.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Cossack Double Kettlebell Thruster', 'Perform a deep lateral Cossack squat with kettlebells in the rack position and press them overhead as you return to the center.', 'external'),
('99db6791-8329-444f-9df8-d279b70f9536', 'Curl de isquiotibiales de pie a una pierna con cable', 55, NULL, 151, 1, 'Principiante', 'De pie frente a la polea, flexiona una pierna hacia atrás llevando el talón al glúteo contra la resistencia del cable.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Standing Single Leg Cable Hamstring Curl', 'Standing in front of the cable, bend one leg back, bringing your heel to your buttocks against the resistance of the cable.', 'external'),
('99f2b634-aff6-4b37-b666-3f6a158e1cff', 'Press Sots alterno con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Desde la sentadilla profunda, alterna el brazo que presiona las Kettlebells sobre la cabeza manteniendo el tronco vertical.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Alternating Double kettlebell Press Sots', 'From the deep squat, alternate the arm that presses the kettlebells overhead, keeping the torso vertical.', 'external'),
('99fea4c6-0f40-4fd8-92e1-aa6da5808009', 'Aperturas con mancuernas en banco plano', 1, NULL, 81, 1, 'Principiante', 'Abre los brazos lateralmente con mancuernas y junta arriba. Objetivo: estiramiento y aislamiento pectoral. Cues: codos semiflexionados. Error común: bajar tanto que estires el hombro en exceso.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Flat Bench Dumbbell Flyes', 'Open your arms laterally with dumbbells and join them above. Target: stretching and chest isolation. Cue: slightly bent elbows. Common mistake: lowering yourself so much that you overstretch your shoulder.', 'external'),
('9a2c1874-448b-4500-88b0-ff1b96c54861', 'Skips laterales dinámicos', 37, 13, 1, 1, 'Principiante', 'Desplazamiento lateral elevando rodillas y coordinando brazos. Mejora la agilidad y movilidad de cadera. Pecho alto. No cruces los pies.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Dynamic Side Skips', 'Lateral movement, raising knees and coordinating arms. Improves agility and hip mobility. High chest. Don''t cross your feet.', 'bodyweight'),
('9a31cb3e-7b7e-4031-96c6-1a6ea8461f2e', 'Curl inclinado con mancuerna', 17, NULL, 81, 1, 'Intermedio', 'Sentado en banco inclinado a 45 grados, flexiona las mancuernas. Objetivo: estiramiento máximo del bíceps. Cue: mantén los codos apuntando al suelo. Error común: mover los hombros hacia adelante.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Incline Dumbbell Curl', 'Sitting on a bench inclined at 45 degrees, flex the dumbbells. Target: maximum biceps stretch. Cue: keep your elbows pointed at the ground. Common mistake: moving your shoulders forward.', 'external'),
('9a5f7013-2cc4-41df-8411-052042bae214', 'Peso muerto desde bloques (Block Pull)', 71, 55, 116, 1, 'Principiante', 'Realiza un peso muerto iniciando con los discos de la barra sobre bloques elevados para reducir el recorrido y enfocar la espalda.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Deadlift From Blocks (block Pull)', 'Perform a deadlift starting with the barbell plates on raised blocks to reduce the travel and focus on the back.', 'external'),
('9a670088-4c55-4184-abb0-acffca82441b', 'Flexión pliométrica palmada aérea', 1, 6, 1, 1, 'Avanzado', 'Flexión explosiva con palmada frente a la cara. Requiere velocidad de manos. Cue: empuje de hombros explosivo. Error común: desalineación del cuello por mirar las manos.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Aerial Clap Plyometric Push-up', 'Explosive push-up with clap in front of the face. Requires hand speed. Cue: explosive shoulder thrust. Common mistake: neck misalignment from looking at your hands.', 'mixed'),
('9a6f308f-3572-45cd-a444-354f8d84214d', 'Elevación de piernas colgado', 25, 37, 1, 1, 'Avanzado', 'Colgado de barra, eleva piernas estiradas hasta 90 grados o más. Cue: no te balancees. Error: usar el impulso para subir las piernas.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Hanging Leg Raise', 'Hanging from a bar, it raises straight legs up to 90 degrees or more. Cue: don''t swing. Common mistake: using momentum to raise your legs.', 'bodyweight'),
('9ab80d37-1c2f-4809-8fbf-d8c343bd39ca', 'Curl bíceps kettlebells', 17, NULL, 281, 1, 'Principiante', 'Flexiona dos pesas rusas. Objetivo: bíceps. Cue: agarre firme. Error: balanceo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Kettlebell Biceps Curl', 'Flex two kettlebells. Target: biceps. Cue: firm grip. Common mistake: swinging.', 'external'),
('9ad935ab-7d89-4247-8da4-411da8f4b419', 'Flexiones espartanas', 1, 2, 1, 1, 'Avanzado', 'Realiza una flexión explosiva y en el aire cambia la posición de las manos, alternando entre una mano adelantada y otra atrasada. Requiere potencia explosiva y coordinación. Aterriza suavemente y continúa con el siguiente cambio. Este ejercicio desarrolla potencia y agilidad en el tren superior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Spartan push-ups', 'Perform an explosive push-up and in the air change the position of your hands, alternating between a forward hand and a back hand. Requires explosive power and coordination. Land softly and continue with the next change. This exercise develops power and agility in the upper body.', 'mixed'),
('9ade28f5-cb6a-4bf5-9113-6a13af98571b', 'Caminata lateral con Miniband (Pies)', 29, 37, 61, 1, 'Intermedio', 'Con la banda alrededor de los pies (empeines). Mantén las piernas separadas y camina lateralmente, maximizando la activación del glúteo medio.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Lateral walk with Mini Band (Feet)', 'With the band around the feet (insteps). Keep your legs apart and walk laterally, maximizing glutes medius activation.', 'external'),
('9ae5a3e0-4145-49c8-ad0d-3fb543985d73', 'Pasos laterales con banda', 37, 29, 61, 1, 'Principiante', 'Desplazamiento lateral manteniendo tensión en la banda. Activación de glúteo medio. Rodillas fuera. No arrastres los pies.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Side steps with band', 'Lateral movement maintaining tension in the band. Gluteus medius activation. Knees out. Don''t drag your feet.', 'external'),
('9af6046f-4627-4ab7-a176-5e1aae2f84fa', 'Sentadilla de copa (Goblet Squat)', 28, 25, 81, 1, 'Principiante', 'Sujeta una mancuerna o pesa rusa al pecho y baja en sentadilla. Cue: codos tocan cara interna de rodillas. Error: despegar talones.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Goblet Squat', 'Hold a dumbbell or kettlebell to your chest and lower yourself into a squat. Cue: elbows touch the inside of the knees. Common mistake: taking off heels.', 'external'),
('9b417bf1-a679-4d89-9f9f-04e8b83174b7', 'Chest press balón medicinal', 1, 2, 240, 1, 'Intermedio', 'De pie frente a una pared, lanza el balón con fuerza desde el pecho y recíbelo al rebotar. El movimiento explosivo desarrolla potencia en el pectoral. Mantén el core activado y usa todo el cuerpo en el lanzamiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Chest press medicine ball', 'Standing in front of a wall, throw the ball hard from your chest and catch it as it bounces. The explosive movement develops power in the pectoral muscles. Keep your core engaged and use your entire body in the throw.', 'external'),
('9b4d3dc7-7123-4377-847f-226b26cdd0ef', 'Remo rotacional cable', 16, 25, 151, 1, 'Avanzado', 'Combina remo con rotación completa del torso. Movimiento altamente funcional para deportes. Comienza de lado al cable y termina mirando hacia él. Control total del movimiento. Potencia desde caderas y core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Rotational Rowing', 'Combines rowing with full torso rotation. Highly functional movement for sports. Start with your side facing the cable and end up facing it. Full control of movement. Power from hips and core.', 'external'),
('9b51a52a-c188-4fec-bbdb-5d2026b81d5f', 'Caminata Front Rack con Kettlebell a una mano', 25, 6, 281, 1, 'Principiante', 'Camina manteniendo una pesa rusa en posición de rack sobre un hombro, activando fuertemente los oblicuos para evitar que el peso incline el torso lateralmente.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Front Rack Walk with One-Handed Kettlebell', 'Walk while holding a kettlebell in a rack position on one shoulder, strongly activating the obliques to prevent the weight from tilting the torso laterally.', 'external'),
('9b55b358-c13c-46fd-bdd4-d2b9e9c83f6f', 'Remo unilateral en polea baja', 16, 17, 151, 1, 'Principiante', 'Sentado, rema a un solo brazo buscando máximo estiramiento. Objetivo: dorsal aislado. Cue: estira total el dorsal al volver. Error común: rotar el torso excesivamente.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Unilateral Low Cable Row', 'Seated, row with one arm seeking maximum stretch. Target: isolated dorsal. Cue: fully stretch the dorsal when returning. Common mistake: rotating the torso excessively.', 'external'),
('9b87652d-64d1-4c92-82fa-b12e60900b30', 'Burpee con salto de estrella', 13, 64, 1, 1, 'Intermedio', 'Realiza un burpee y termina el salto vertical abriendo brazos y piernas en el aire. Alta demanda metabólica. Cue: vuelve a cerrar piernas antes de aterrizar. Error común: aterrizar con las piernas rígidas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee with Star Jump', 'Perform a burpee and finish the vertical jump by opening your arms and legs in the air. High metabolic demand. Cue: close your legs again before landing. Common mistake: landing with stiff legs.', 'bodyweight'),
('9b9a528f-7374-4f51-9d67-a3c3a6034a6e', 'Crunches inversos', 25, NULL, 1, 1, 'Principiante', 'Tumbado, eleva la cadera del suelo llevando las rodillas hacia el pecho. Objetivo: recto abdominal inferior. Cues: lumbar pegada al inicio. Error común: usar excesivo balanceo de piernas.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Reverse Crunches', 'Lying down, raise your hips off the ground, bringing your knees toward your chest. Target: lower rectus abdominis. Cue: lumbar stuck at the beginning. Common mistake: using excessive leg swing.', 'bodyweight'),
('9bb808c0-e2b9-462d-8cf6-fdfcb65af36e', 'Monster Walk con Miniband (Muslos)', 37, 29, 61, 1, 'Principiante', 'Con una banda sobre las rodillas, da pasos hacia adelante y afuera en diagonal, manteniendo las rodillas separadas y la cadera baja.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Monster Walk with Mini Band (Thighs)', 'With a band over your knees, step forward and out diagonally, keeping your knees apart and your hips low.', 'external'),
('9bbf9765-50b7-491a-85be-d733254eb9be', 'Crunches abdominales', 25, NULL, 1, 1, 'Principiante', 'Tumbado, eleva solo los hombros del suelo apretando el abdomen. Cue: mira al techo, no tires del cuello. Error: levantar la zona lumbar del suelo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Abdominal Crunches', 'Lying down, raise only your shoulders off the ground, squeezing your abs. Cue: look at the ceiling, don''t pull on your neck. Common mistake: lifting your lower back off the floor.', 'bodyweight'),
('9beef3cf-d8f2-4504-8e4d-5063a399d73c', 'Sentadilla con salto (Jump Squat)', 28, 64, 1, 1, 'Intermedio', 'Realiza una sentadilla y termina con un salto vertical máximo. Objetivo: potencia explosiva. Cue: aterriza con las puntas para amortiguar. Error común: aterrizar con las piernas rígidas.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Jump Squat', 'Perform a squat and finish with a maximum vertical jump. Target: explosive power. Cue: land on your toes to cushion. Common mistake: landing with stiff legs.', 'mixed'),
('9c010d07-c688-4339-8e00-447401b3db17', 'Salto longitud giro 90', 29, 37, 1, 1, 'Avanzado', 'Salta hacia adelante y gira 90 grados en el aire para aterrizar de lado. Cue: controla el aterrizaje lateral. Error común: perder el equilibrio lateral al caer.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Long Jump Turn 90', 'Jump forward and turn 90 degrees in the air to land on your side. Cue: control the side landing. Common mistake: losing lateral balance when falling.', 'bodyweight');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('9c03a7fb-ff28-4159-8265-0664c7c70594', 'Curl de bíceps a una mano en TRX', 17, 25, 216, 1, 'Intermedio', 'Sujeta una sola correa de TRX e inclina el cuerpo. Realiza el curl flexionando el codo hacia tu frente trabajando la estabilidad unilateral.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'TRX One-Handed Biceps Curl', 'Hold a single TRX strap and tilt your body. Perform the curl by bending your elbow towards your forehead, working on unilateral stability.', 'bodyweight'),
('9c64f789-02d6-4112-9b4c-d9d0af801449', 'Sentadilla con Fitball en pared', 28, 29, 290, 1, 'Principiante', 'Coloca un Fitball entre tu espalda y la pared. Realiza una sentadilla deslizando el balón mientras bajas, manteniendo el torso erguido.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Squat with Stability Ball on the wall', 'Place a stability ball between your back and the wall. Perform a squat sliding the ball as you go down, keeping your torso upright.', 'bodyweight'),
('9c7949f6-7d94-4f28-9929-1da712cf41b1', 'Pájaros con mancuernas', 6, 71, 81, 1, 'Intermedio', 'Torso inclinado paralelo al suelo, eleva mancuernas lateralmente. Objetivo: deltoides posterior y romboides. Cue: imagina que empujas con los codos hacia afuera. Error común: juntar las escápulas demasiado rápido restando trabajo al hombro.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Dumbbell Birds', 'torso inclined parallel to the floor, raise dumbbells laterally. Target: posterior deltoid and rhomboid. Cue: imagine pushing out with your elbows. Common mistake: bringing the scapulae together too quickly, taking work off the shoulder.', 'external'),
('9c8949e6-c173-43d2-be00-961d01d98b6b', 'Remo sentado cable', 16, 17, 151, 1, 'Principiante', 'Sentado con los pies en los soportes, tira del agarre hacia el abdomen manteniendo la espalda recta. Permite un ligero movimiento del torso pero evita el balanceo excesivo. Aprieta los omóplatos al final del movimiento para máxima contracción.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Seated Row', 'Sitting with your feet on the supports, pull the grip towards your abs, keeping your back straight. Allows slight movement of the torso but prevents excessive rocking. Squeeze your shoulder blades at the end of the movement for maximum contraction.', 'external'),
('9c8c31a4-dab2-4622-ac6a-e6dfa8585100', 'Elevación de talones a una pierna', 64, 309, 1, 1, 'Principiante', 'En el borde de un escalón, elévate sobre un solo pie y desciende lo máximo posible. Objetivo: fuerza del gemelo. Cue: movimiento lento y controlado. Error: rebotar en la parte inferior del movimiento.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'One Leg Heel Raise', 'At the edge of a step, rise on one foot and go down as far as possible. Target: calf strength. Cue: slow, controlled movement. Common mistake: bouncing at the bottom of the movement.', 'mixed'),
('9cea5a00-8e09-4376-8b37-4bfd7821f399', 'Glute bridge', 29, NULL, 1, 1, 'Principiante', 'Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo cerca de los glúteos. Eleva las caderas contrayendo los glúteos hasta formar una línea recta desde las rodillas hasta los hombros. Mantén la posición superior apretando los glúteos y desciende controladamente sin tocar el suelo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Glute bridge', 'Lie on your back with your knees bent and your feet flat on the floor near your buttocks. Raise your hips by contracting your glutes until you form a straight line from your knees to your shoulders. Maintain the upper position by squeezing your glutes and descend controlledly without touching the ground.', 'mixed'),
('9d3c31f8-4a76-4a3a-97f4-55772f51605d', 'Roll out single arm', 25, NULL, 271, 1, 'Avanzado', 'Roll out usando solo un brazo en la rueda. Requiere fuerza anti-rotación excepcional. Comienza con rangos muy cortos. El brazo libre puede estar en la espalda o extendido para equilibrio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Roll out single arm', 'Roll out using only one arm on the wheel. Requires exceptional anti-rotation strength. Start with very short ranges. The free arm can be at the back or extended for balance.', 'external'),
('9d474e23-bf06-4d61-8e9d-5346977ee14a', 'Plancha comando cadera quieta', 25, 6, 1, 24, 'Intermedio', 'Pasa de antebrazos a manos. Cue: cadera fija. Error: balancear cuerpo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Plank Up-Down with Still Hips', 'Pasa de antearms a hands. Cue: hip fija. Common mistake: balancear body.', 'bodyweight'),
('9d4e44bb-6938-4e1a-8cc4-8b744511b92d', 'Gusanos (Inchworms)', 25, 71, 1, 1, 'Principiante', 'Desde pie, baja las manos al suelo y camina con ellas hasta posición de plancha, luego camina con los pies hacia las manos. Objetivo: core y flexibilidad. Cue: mantén las rodillas lo más rectas posible. Error: dejar caer la cadera en la plancha.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Inchworms', 'From standing, lower your hands to the floor and walk with them to a plank position, then walk with your feet towards your hands. Target: core and flexibility. Cue: keep your knees as straight as possible. Common mistake: dropping your hips into the plank.', 'bodyweight'),
('9d9a7469-5e0a-42bb-b2d8-ebaa3292fbf9', 'Flexión en T', 1, 6, 1, 1, 'Intermedio', 'Realiza una flexión y al subir rota el cuerpo hacia un lado elevando un brazo hacia el techo. Objetivo: fuerza de empuje y equilibrio. Cues: mantén el cuerpo recto en todo momento. Error común: perder el control del hombro de apoyo al rotar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'T Push-Up', 'Perform a push-up and, as you come up, rotate your body to one side and raise one arm toward the ceiling. Target: pressing strength and balance. Cue: keep your body straight throughout. Common mistake: losing control of the supporting shoulder during the rotation.', 'mixed'),
('9dd106d2-614e-4cc2-bdf3-ba142ed1504e', 'Tornado battle ropes', 25, 6, 256, 24, 'Avanzado', 'Movimiento circular continuo con ambas cuerdas creando un patrón de tornado. Requiere coordinación y resistencia excepcionales. El movimiento debe ser fluido y controlado. Alterna direcciones periódicamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Tornado Battle Ropes', 'Move both ropes in a continuous circular pattern to create a tornado effect. This requires exceptional coordination and endurance. Keep the motion fluid and controlled, and change directions periodically.', 'external'),
('9e091ca5-2662-4741-b8e1-d06e20fb90e6', 'Squat Clean a Thruster con barra', 13, 6, 116, 1, 'Avanzado', 'Lleva la barra desde el suelo a los hombros en sentadilla completa y usa el impulso de la subida para realizar un press vertical sobre la cabeza.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Barbell Squat Clean to Thruster', 'Bring the bar from the floor to your shoulders in a full squat and use the momentum of the rise to perform a vertical overhead press.', 'external'),
('9e204716-a368-471f-82f5-c1d44c34a541', 'Press militar con barra sentado', 6, 2, 116, 1, 'Intermedio', 'Empuja la barra sobre la cabeza sin impulso de piernas. Fuerza pura. Core apretado. No arquees la espalda al final.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Seated Barbell Military Press', 'Push the bar overhead without leg push. Pure strength. Tight core. Don''t arch your back at the end.', 'external'),
('9e43cc32-2fa4-4bbe-8de5-0221be4bc924', 'Plank to roll out', 25, NULL, 271, 1, 'Intermedio', 'Comienza en plancha con manos en la rueda y realiza pequeños rodamientos. Combina isométrico con movimiento. Mantén las caderas bajas y evita arquear la espalda. Excelente para desarrollar control.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Plank to roll out', 'Start in plank with hands on the wheel and perform small rolls. Combines isometric with movement. Keep your hips low and avoid arching your back. Excellent for developing control.', 'external'),
('9e4f9374-7729-45fc-970d-718dedbc6ca8', 'Press pecho con banda', 1, 6, 61, 1, 'Principiante', 'Ancla la banda detrás de ti a la altura del pecho. Sujeta los extremos y realiza un movimiento de press hacia adelante, extendiendo completamente los brazos. La resistencia de la banda proporciona tensión constante, especialmente en la fase final del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Chest press with band', 'Anchor the band behind you at chest height. Hold the ends and perform a forward pressing movement, fully extending your arms. The resistance of the band provides constant tension, especially in the final phase of the movement.', 'external'),
('9e5cf242-153e-45ad-b5a9-88e17582f09a', 'Flexiones en anillas', 1, 2, 1, 1, 'Avanzado', 'Flexiones con manos en anillas bajas. La inestabilidad multiplica la dificultad y activación muscular. Comienza con anillas más altas para menor dificultad. Mantén las anillas quietas durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Ring push-ups', 'Push-ups with hands in low rings. Instability multiplies difficulty and muscle activation. Start with higher rings for less difficulty. Keep the rings still during the movement.', 'mixed'),
('9e87364a-12ae-4aad-ada3-922f01b22129', 'Press hombros mancuernas', 6, 2, 81, 1, 'Principiante', 'Sentado o de pie, con una mancuerna en cada mano a la altura de los hombros, presiona hacia arriba hasta extender completamente los brazos. Mantén el core activado para estabilizar la columna. Desciende controladamente hasta que los codos formen 90 grados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell shoulder press', 'Sitting or standing, with a dumbbell in each hand at shoulder height, press up until your arms are fully extended. Keep your core engaged to stabilize your spine. Descend controlledly until your elbows form 90 degrees.', 'external'),
('9e9197e5-4805-488f-a6d8-45eac66521f5', 'Curl de bíceps predicador con barra Z', 17, NULL, 116, 1, 'Intermedio', 'Apoya los brazos en el banco predicador y flexiona la barra Z. Objetivo: aislamiento del bíceps braquial. Cues: estira el brazo totalmente abajo. Error común: levantar los codos del soporte.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Z-bar Preacher Biceps Curl', 'Rest your arms on the preacher bench and flex the Z bar. Target: isolation of the biceps brachii. Cue: stretch your arm completely down. Common mistake: lifting your elbows off the support.', 'external'),
('9eb370e1-e734-4d95-aaf4-39a909f29ff8', 'Elevación talones prensa puntas', 64, 309, 186, 1, 'Principiante', 'Empuja plataforma solo con puntas. Cue: rango total. Error: rodillas bloqueadas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Heel Lift Toe Press', 'Push platform only with toes. Cue: full range. Common mistake: locked knees.', 'external'),
('9eb8d5be-f445-4a71-ac12-636bc0766c6d', 'Salto pogo lateral', 64, 309, 1, 1, 'Intermedio', 'Salta de lado a lado rápidamente sobre una línea imaginaria. Mantén los tobillos rígidos y el tiempo de contacto con el suelo al mínimo. Objetivo: reactividad del tobillo. Cue: rebota sobre las puntas, no apoyes talones. Error común: flexionar demasiado las rodillas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Pogo Jump', 'Jump from side to side quickly over an imaginary line. Keep ankles stiff and ground contact time to a minimum. Target: ankle reactivity. Cue: bounce on your toes, don''t put your heels down. Common mistake: bending your knees too much.', 'bodyweight'),
('9eba3286-c1c2-4058-83f2-bbce205f702f', 'Aperturas en banco inclinado con mancuernas', 1, 6, 81, 1, 'Intermedio', 'En banco a 45 grados, abre los brazos lateralmente con mancuernas y cierra al centro. Objetivo: aislamiento del pectoral superior. Cue: imagina que abrazas un cilindro gigante. Error común: bajar las pesas excesivamente estirando de más el hombro.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Incline Bench Flyes with Dumbbells', 'On a 45-degree bench, open your arms laterally with dumbbells and close them in the center. Target: isolation of the upper chest. Cue: imagine you''re hugging a giant cylinder. Common mistake: lowering the weights excessively by overstretching the shoulder.', 'external'),
('9ecf5c23-1770-4000-9cac-ba45dff35de8', 'Curl isquios fitball', 55, NULL, 290, 1, 'Intermedio', 'Tumbado con talones sobre la fitball, eleva las caderas y flexiona las rodillas rodando la pelota hacia los glúteos. Mantén las caderas elevadas durante todo el movimiento. La inestabilidad aumenta significativamente la dificultad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stability Ball Hamstring Curl', 'Lying with your heels on the stability ball, raise your hips and bend your knees, rolling the ball towards your buttocks. Keep your hips raised throughout the movement. Instability significantly increases the difficulty.', 'bodyweight'),
('9efa252e-ae26-4b61-bc36-7485f5af2a8a', 'Remo renegado doble con mancuernas', 71, 25, 81, 1, 'Intermedio', 'Desde posicion de plancha sobre mancuernas, rema una pesa hacia tu cadera mientras estabilizas el cuerpo con el otro brazo y el core, alternando lados.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Dumbbell Double Renegade Row', 'From a dumbbell plank position, row a dumbbell toward your hip while stabilizing your body with your other arm and core, alternating sides.', 'external'),
('9f2369ba-7e5c-4f8a-ad1d-59eb3cde8b45', 'Sentadilla Ciclista con Kettlebell doble Bottoms Up (Front Rack)', 28, 29, 281, 1, 'Intermedio', 'Realiza una sentadilla ciclista con los talones elevados sujetando dos Kettlebells invertidas en posicion de rack frontal.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bottoms Up Double Kettlebell Cycle Squat (front Rack)', 'Perform a bicycle squat with your heels raised holding two inverted kettlebells in a front rack position.', 'external'),
('9f32f085-3dc5-4593-a04c-fd2f91c849d4', 'Colgado pasivo a una mano en barra', 100, 71, 1, 1, 'Avanzado', 'Cuélgate de una barra fija usando solo una mano. Mantén la posición para desarrollar fuerza de agarre extrema y salud escapular.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Passive hanging with one hand on a bar', 'Hang from a fixed bar using only one hand. Hold the position to develop extreme grip strength and scapular health.', 'bodyweight'),
('9f403e30-eaea-4104-ba78-fc992d42955c', 'Curl femoral sentado', 55, NULL, 186, 1, 'Principiante', 'Sentado con las piernas extendidas, flexiona las rodillas contra la resistencia. Esta posición proporciona un estiramiento diferente del isquiotibial comparado con la versión tumbada. Mantén la espalda apoyada durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Seated Femoral Curl', 'Sitting with your legs extended, bend your knees against resistance. This position provides a different hamstring stretch compared to the lying version. Keep your back supported throughout the movement.', 'external'),
('9f515786-ab34-4604-94c8-8254d0b49e68', 'Step Up con Kettlebell doble (Maleta)', 28, 29, 281, 1, 'Principiante', 'Sube a un banco sosteniendo dos Kettlebells a los lados del cuerpo, empujando con la pierna delantera hasta la extensión completa.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Suitcase Step-up', 'Step onto a bench while holding two kettlebells at your sides, driving through the lead leg until you are fully upright.', 'external'),
('9f85734e-3932-46f4-af46-9855f2b2baf6', 'Hamstring sliders', 55, 29, 1, 1, 'Intermedio', 'Tumbado boca arriba con los talones sobre una superficie deslizante, eleva la cadera y extiende las piernas de forma controlada. Flexiona las rodillas para volver activando los isquiotibiales.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Hamstring Sliders', 'Lie on your back with your heels on a sliding surface, lift the hips, and extend the legs under control. Bend the knees to return while engaging the hamstrings.', 'bodyweight'),
('9fcd1862-d321-4ef4-b395-e65941199062', 'Dominadas agarre prono estricto', 16, 17, 1, 1, 'Intermedio', 'Sube hasta pasar la barbilla con palmas al frente. Cue: pecho a la barra. Error: usar balanceo.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Strict Prone Grip Pull-ups', 'Go up to pass the chin with palms in front. Cue: chest to bar. Common mistake: use balancing.', 'mixed'),
('9fe3e1b5-9a2c-4c2f-a618-585df5d36218', 'Saltos de amplitud lateral', 29, 37, 1, 1, 'Intermedio', 'Salta lateralmente buscando la máxima distancia posible. Potencia en el plano frontal. Aterrizaje estable. No dejes que la rodilla se hunda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Side Amplitude Jumps', 'Jump laterally aiming for maximum distance. Builds power in the frontal plane. Land in a stable position and do not let your knees collapse inward.', 'bodyweight'),
('9fffabe0-920f-4315-9f64-a586616ca367', 'Peso muerto rígido barra', 55, 71, 116, 1, 'Intermedio', 'Baja barra rodillas casi bloqueadas. Objetivo: estirar isquios. Cue: cadera atrás. Error: curvar lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Barbell Stiff-Leg Deadlift', 'Lower the bar with your knees almost locked. Target: hamstring stretch. Cue: push your hips back. Common mistake: rounding your lower back.', 'external'),
('a0411742-b6dd-4edc-b98b-09cdc9d4f22e', 'Salto patinador con mancuerna', 29, 37, 81, 1, 'Avanzado', 'Salto de patinador sosteniendo una mancuerna ligera en el pecho. Potencia lastrada. Cue: controla la inercia del peso. Error común: balancear la mancuerna lejos del pecho.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Dumbbell Skater Jump', 'Skater jump holding a light dumbbell on your chest. Ballasted power. Cue: controls the inertia of the weight. Common mistake: swinging the dumbbell away from your chest.', 'external'),
('a044db64-26e5-4ed1-879e-c5abeff7e893', 'Sentadilla Split con barra', 28, 29, 116, 1, 'Intermedio', 'Mantén los pies en posición de zancada y baja la rodilla trasera hacia el suelo con la barra en hombros. Objetivo: hipertrofia unilateral. Cues: baja de forma vertical y mantén la espalda neutra. Error común: inclinar el torso demasiado adelante.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Barbell Split Squat', 'Keep your feet in a lunge position and lower your back knee toward the floor with the bar on your shoulders. Target: unilateral hypertrophy. Cue: go down vertically and keep your back neutral. Common mistake: leaning your torso too far forward.', 'external'),
('a04b552e-902b-48c3-8357-2cffdd4b9024', 'Swing medio arrodillado con Kettlebell a una mano', 25, 29, 281, 1, 'Intermedio', 'Desde posicion de caballero, realiza un swing lateral corto, forzando al core a estabilizar el tronco sin la ayuda de la bipedestacion.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Half-Kneeling Single-Arm Kettlebell Swing', 'From a half-kneeling position, perform a short lateral swing, forcing your core to stabilize the trunk without help from a standing stance.', 'external'),
('a0b62d9f-107c-468c-99e6-c296a971f8c6', 'Flujo kettlebell', 13, NULL, 281, 24, 'Avanzado', 'Secuencia continua de movimientos sin pausas: swing, clean, press, squat, etc. Crea tu propio flujo o sigue secuencias establecidas. Excelente acondicionamiento metabólico. La técnica no debe comprometerse por la fatiga.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Flow', 'Continuous sequence of movements without pauses: swing, clean, press, squat, etc. Create your own flow or follow established sequences. Excellent metabolic conditioning. Technique should not be compromised by fatigue.', 'external'),
('a0b7f536-49fa-4d21-b6e9-7aa4c8cb1dcd', 'Salto en Sentadilla Split Búlgara', 28, 29, 1, 1, 'Intermedio', 'Con un pie elevado atrás, realiza una sentadilla split y salta de forma explosiva con la pierna delantera.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Bulgarian Split Squat Jump', 'With one foot raised behind you, perform a split squat and jump explosively with your front leg.', 'mixed'),
('a109bae6-f172-44e5-be4a-c20ddb5c3e13', 'Remo vertical con barra', 6, 71, 116, 1, 'Principiante', 'Eleva la barra pegada al torso hasta la altura del pecho subiendo los codos por encima de las muñecas. Objetivo: deltoides lateral y trapecio. Cue: no des tirones con la espalda. Error común: subir la barra demasiado cerca del cuello de forma brusca.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Barbell Upright Row', 'Raise the bar close to your torso to chest height, raising your elbows above your wrists. Target: lateral deltoid and trapezius. Cue: don''t jerk with your back. Common mistake: raising the bar too close to the neck abruptly.', 'external'),
('a1167d6c-7b40-437a-ab05-617fc75dc7df', 'Fondos entre bancos tríceps', 2, 1, 1, 1, 'Principiante', 'Manos en un banco y pies en otro, baja y sube. Potencia de tríceps. Pecho alto. No bajes más allá del ángulo recto.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Dips between triceps benches', 'Hands on one bench and feet on another, go down and up. Triceps power. High chest. Do not go down further than the right angle.', 'mixed'),
('a1ad8b55-236f-439b-a08e-83d47fa2df48', 'Devil Press alterno a una mano con mancuerna', 13, 6, 81, 1, 'Avanzado', 'Realiza un Burpee con una mano en una mancuerna. Al levantarte, eleva esa mancuerna sobre la cabeza y cambia de mano en la siguiente repetición.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternate One-Handed Dumbbell Devil Press', 'Perform a Burpee with one hand on a dumbbell. As you stand up, raise that dumbbell overhead and switch hands on the next rep.', 'external'),
('a1aed24e-0cd5-4c5c-9128-d8e1b0c8400f', 'Bodyweight Glute Bridge', 29, 55, 1, 1, 'Principiante', 'Acuéstate boca arriba con las rodillas dobladas y los pies planos en el suelo. Levanta las caderas hacia el techo apretando los glúteos hasta que el cuerpo forme una línea recta desde los hombros hasta las rodillas. Baja lentamente.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Glute Bridge', 'Lie on your back with your knees bent and feet flat on the floor. Raise your hips toward the ceiling, squeezing your glutes until your body forms a straight line from your shoulders to your knees. Go down slowly.', 'mixed'),
('a1b24c36-0b71-4911-ac6a-8ae2ae313501', 'Salto valla rebote doble', 64, 309, 1, 1, 'Intermedio', 'Salta una valla y realiza un pequeño rebote rápido antes del siguiente salto. Mejora el timing. Cue: rebote elástico. Error común: rebote demasiado alto que quita energía.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Double Rebound Hurdle Jump', 'Jump over a fence and do a quick little bounce before the next jump. Improve timing. Cue: springy bounce. Common mistake: bouncing too high which saps energy.', 'bodyweight'),
('a1dcdd52-62d4-45a1-b6ff-c64c309c8607', 'Pike Pushups elevados', 6, 2, 1, 1, 'Intermedio', 'Pies en banco en posición de V invertida, baja la frente hacia el suelo. Objetivo: fuerza de hombros. Cue: codos hacia atrás en diagonal. Error común: abrir los codos hacia afuera lateralmente.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Pike Push-Ups with Elevated Feet', 'With your feet on a bench in an inverted V position, lower your forehead toward the floor. Target: shoulder strength. Cue: keep your elbows back on a diagonal path. Common mistake: flaring your elbows out to the sides.', 'mixed'),
('a1effa06-508a-4002-9960-a4d3c75a5d28', 'Press de banca inclinado con barra', 1, 6, 116, 1, 'Intermedio', 'En un banco inclinado (30-45 grados), baja la barra a la parte superior del pecho y empuja hacia arriba para trabajar el pectoral superior.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Incline Barbell Bench Press', 'On an incline bench (30-45 degrees), lower the bar to your upper chest and push up to work your upper chest.', 'external'),
('a225fd6f-7478-4cbf-a45f-4e66863f2c04', 'Single Arm Cable Half Kneeling Contralateral Shoulder External Rotation 90 Degrees', 6, NULL, 151, 1, 'Principiante', 'Arrodíllate de lado a la polea. Con el brazo exterior elevado a 90 grados, rota el hombro hacia atrás tirando del cable, manteniendo el codo alineado con el hombro.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Single Arm Cable Half Kneeling Contralateral Shoulder External Rotation 90 Degrees', 'Kneel sideways to the cable. With your outside arm raised to 90 degrees, rotate your shoulder back by pulling on the cable, keeping your elbow in line with your shoulder.', 'external'),
('a2271c65-170c-4e2d-84d3-23dd480652e4', 'Zottman curl barra', 17, 100, 116, 1, 'Intermedio', 'Aunque tradicionalmente se hace con mancuernas, puedes simular el movimiento con barra realizando la fase concéntrica con agarre supino y cambiando a prono para la excéntrica. Trabaja bíceps en la subida y braquiorradial en la bajada.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Zottman Curl', 'Although it is traditionally performed with dumbbells, you can simulate the movement with a barbell by using a supinated grip during the concentric phase and a pronated grip during the eccentric phase. It works the biceps on the way up and the brachioradialis on the way down.', 'external'),
('a2287b32-51a9-4210-b2ab-a02c8759924a', 'Sentadilla mancuernas', 28, 29, 81, 1, 'Principiante', 'Sujeta una mancuerna en cada mano a los lados del cuerpo. Realiza una sentadilla normal manteniendo las mancuernas colgando naturalmente. Esta variación es más cómoda para principiantes que la sentadilla con barra y permite un centro de gravedad más bajo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Squat', 'Hold a dumbbell in each hand at the sides of your body. Perform a normal squat, keeping the dumbbells hanging naturally. This variation is more comfortable for beginners than the barbell squat and allows for a lower center of gravity.', 'external'),
('a22e5e04-123d-4a58-ba3a-41c2173af6f1', 'Extensión tríceps TRX', 2, NULL, 216, 1, 'Intermedio', 'Inclinado hacia adelante con brazos extendidos sobre la cabeza, flexiona los codos llevando las manos hacia la cabeza. Mantén los codos fijos y el cuerpo recto. Cuanto más inclinado, mayor dificultad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Triceps Extension', 'Leaning forward with arms extended above your head, bend your elbows, bringing your hands towards your head. Keep your elbows fixed and your body straight. The steeper the slope, the greater the difficulty.', 'bodyweight'),
('a2316ed6-f94a-4eef-b91a-3ca70febf032', 'Press guillotina', 1, 6, 116, 1, 'Avanzado', 'Baja barra al cuello agarre ancho. Objetivo: fibras superiores pecho. Cue: codos abiertos. Error: exceso peso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Guillotine Press', 'Low neck bar with wide grip. Target: upper chest fibers. Cue: elbows open. Common mistake: excess weight.', 'external'),
('a23da5c7-3181-4073-9a6a-1295f2539c54', 'Elevación de talones en máquina de prensa', 64, 309, 186, 1, 'Principiante', 'Empuja plataforma solo con puntas. Objetivo: gemelos. Cues: rango total. Error común: rodillas bloqueadas.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Heel Lift on Press Machine', 'Push platform only with toes. Target: twins. Cue: total range. Common mistake: locked knees.', 'external'),
('a267e7a0-fc3c-4c09-8db5-e794132992b2', 'Saltos alternados battle ropes', 13, NULL, 256, 24, 'Avanzado', 'Saltos alternando piernas (como correr en el sitio saltando) mientras mantienes ondas. Extremadamente demandante cardiovascularmente. Coordina el ritmo de saltos con las ondas. Mantén core activado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Alternate battle rope jumps', 'Jumps alternating legs (like running in place and jumping) while maintaining waves. Extremely cardiovascular demanding. Coordinate the rhythm of jumps with the waves. Keep core activated.', 'external'),
('a27ec17d-a0e5-49c7-a5de-7d7c1442d9e0', 'Bicycle Crunch con Miniband', 25, NULL, 61, 1, 'Intermedio', 'Coloca una Miniband alrededor de los pies. Realiza el movimiento de bicicleta, llevando el codo a la rodilla contraria mientras extiendes la otra pierna contra la resistencia de la banda.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Bicycle Crunch with Mini Band', 'Place a Mini Band around your feet. Perform the bicycle movement, bringing your elbow to the opposite knee while extending the other leg against the resistance of the band.', 'external'),
('a2bf7f52-15f6-4d87-b515-f785ff075af9', 'V-Ups alternos', 25, 28, 1, 1, 'Intermedio', 'Toca pie contrario con mano contraria elevando torso y pierna. Cue: coordinación y control. Error: doblar la rodilla al subir.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Alternating V-Ups', 'Touch the opposite foot with the opposite hand while lifting your torso and leg. Cue: focus on coordination and control. Common mistake: bending the knee on the way up.', 'bodyweight'),
('a2f1afea-431b-4bed-a796-c161c3dddf7a', 'Salto de valla frontal', 28, 64, 1, 1, 'Intermedio', 'Salta hacia adelante sobre una valla con pies juntos. Enfocado en la potencia de salto vertical y traslación. Cue: eleva rodillas alto. Error común: aterrizar con el pie plano o los talones.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Forward Hurdle Jump', 'Jump forward over a hurdle with your feet together. Focus on vertical jump and forward propulsion. Cue: drive your knees up. Common mistake: landing flat-footed or on your heels.', 'bodyweight'),
('a305909a-f75f-47d2-a5d2-55f0d0ee30f8', 'Sentadilla barra seguridad', 28, 29, 116, 1, 'Avanzado', 'Sentadilla usando barra de seguridad (SSB) con manijas. Cambia el centro de gravedad haciendo el ejercicio más desafiante. Más cómodo para hombros con problemas. Excelente variación para prevenir adaptación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Safety bar squat', 'Squat using safety bar (SSB) with handles. Change the center of gravity making the exercise more challenging. More comfortable for problem shoulders. Excellent variation to prevent adaptation.', 'external'),
('a30d146d-d8ce-452a-a922-2ec19530a4cb', 'Sóleo', 309, 64, 186, 1, 'Intermedio', 'Trabajo específico del sóleo (gemelo profundo), normalmente con rodilla flexionada, para resistencia del tobillo y carrera.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Soleus', 'Specific work on the soleus (deep gastrocnemius), normally with the knee flexed, for ankle resistance and running.', 'external'),
('a343c8b0-07ad-46aa-ab83-52298ee2ac89', 'Curl bíceps con barra Z agarre supino', 17, 100, 116, 1, 'Principiante', 'Flexiona barra Z para proteger muñecas. Cue: rango completo. Error: usar impulso de piernas.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Supine Grip Z-bar Biceps Curl', 'Flex Z bar to protect wrists. Cue: full range. Common mistake: using leg drive.', 'external'),
('a352f541-28e9-460d-b91c-d49b62e7b139', 'Salto pogo talones al glúteo', 55, 64, 1, 1, 'Intermedio', 'Salta rápidamente sobre puntas de pies llevando talones a glúteos en cada rebote. Cue: rodillas apuntan al suelo. Error común: doblar la cadera hacia adelante.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Pogo Jump Heels to Glute', 'Jump quickly on your toes, bringing your heels to your glutes with each bounce. Cue: knees point to the floor. Common mistake: bending the hips forward.', 'bodyweight'),
('a3601251-435f-4b9b-9a6c-0a6065756428', 'Windmill con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'Con una Kettlebell sobre la cabeza y pies anchos, inclina el torso lateralmente hacia el pie libre manteniendo la vista en la pesa.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Single-Arm Kettlebell Windmill', 'With one kettlebell overhead and a wide stance, hinge your torso sideways toward the free foot while keeping your eyes on the weight.', 'external'),
('a3affb5a-ed3e-4e2f-8970-035ce871675a', 'Monster Walk con banda elástica', 29, 37, 61, 24, 'Principiante', 'Banda en rodillas o tobillos, camina hacia adelante y atrás manteniendo las rodillas hacia afuera en media sentadilla. Objetivo: glúteo medio. Cue: no dejes que la banda junte tus rodillas. Error: arrastrar los pies.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Monster Walk with Elastic Band', 'Band on knees or ankles, walk back and forth keeping knees outward in a half squat. Target: glutes medius. Cue: don''t let the band bring your knees together. Common mistake: dragging your feet.', 'external'),
('a3bc0818-cd0d-4c20-a49a-9e2e980bc6af', 'Cargada barra', 13, NULL, 116, 1, 'Avanzado', 'Levantamiento olímpico que lleva la barra desde el suelo hasta los hombros en un movimiento explosivo. Requiere técnica perfecta: primera tracción hasta las rodillas, segunda tracción explosiva con extensión triple (tobillos, rodillas, caderas), y recepción en sentadilla frontal parcial.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Loaded Bar', 'Olympic lift that brings the bar from the floor to the shoulders in an explosive movement. It requires perfect technique: first pull to the knees, second explosive pull with triple extension (ankles, knees, hips), and reception in partial front squat.', 'external'),
('a3d74d5f-9e27-4580-8a6e-e4e9c02c6651', 'Crunch sobre Fitball', 25, NULL, 290, 1, 'Principiante', 'Acuéstate con la espalda baja apoyada en el Fitball y los pies firmes en el suelo. Realiza un encogimiento abdominal (crunch) elevando los hombros.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Crunch on Stability Ball', 'Lie down with your lower back supported by the Stability Ball and your feet firmly on the floor. Perform an abdominal crunch (crunch) by raising your shoulders.', 'bodyweight'),
('a4031669-49c8-4b9d-bf83-867abdf76800', 'Abducción cadera con banda', 37, NULL, 61, 1, 'Principiante', 'De pie con la banda alrededor de los tobillos, apóyate ligeramente para mantener el equilibrio. Eleva lateralmente una pierna manteniéndola recta, resistiendo la tensión de la banda. Mantén el torso erguido y evita inclinarte hacia el lado opuesto.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Band Hip Abduction', 'Standing with the band around your ankles, lean lightly for balance. Raise one leg laterally, keeping it straight, resisting the tension of the band. Keep your torso upright and avoid leaning to the opposite side.', 'external'),
('a40d064f-7784-4577-9db7-a4398973998c', 'Curl concentrado con mancuerna', 17, NULL, 81, 1, 'Principiante', 'Sentado, apoya el codo en la cara interna del muslo y flexiona la pesa. Objetivo: aislamiento del bíceps. Cue: brazo totalmente vertical. Error común: usar el hombro para ayudar al inicio del movimiento.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Concentrated Dumbbell Curl', 'Sitting, rest your elbow on the inner thigh and flex the weight. Target: isolation of the biceps. Cue: fully vertical arm. Common mistake: using the shoulder to help start the movement.', 'external'),
('a41e92a4-14fc-4dc6-9e48-1d5604b855e3', 'Nórdico inverso', 28, NULL, 1, 1, 'Intermedio', 'De rodillas en el suelo, inclina el torso hacia atrás manteniendo el cuerpo recto desde las rodillas a los hombros, estirando los cuádriceps.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse Nordic', 'Kneeling on the floor, lean your torso back, keeping your body straight from your knees to your shoulders, stretching your quads.', 'bodyweight'),
('a4358eba-56f1-4cc5-92a2-a36f5c97db8f', 'Sprawl battle ropes', 13, NULL, 256, 1, 'Avanzado', 'Combina sprawls (burpee sin flexión) con ondas de battle ropes. Realiza ondas, suelta las cuerdas, sprawl, vuelve a tomar las cuerdas y repite. Ejercicio metabólico extremo. Mantén transiciones rápidas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Sprawl battle ropes', 'Combine sprawls (burpee without flexion) with battle rope waves. Make waves, release the ropes, sprawl, take the ropes again and repeat. Extreme metabolic exercise. Keep transitions quick.', 'external'),
('a44d2d3c-73f4-46ac-a22b-3833c1b4cc44', 'Hip thrust cable', 29, 55, 151, 1, 'Intermedio', 'Con cable anclado bajo y posicionado sobre las caderas, realiza empujes de cadera. El cable proporciona resistencia horizontal única comparada con la barra. Aprieta fuertemente los glúteos en la parte superior del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip Thrust Cable', 'With cable anchored low and positioned over your hips, perform hip thrusts. The cable provides unique horizontal resistance compared to the bar. Tightly squeeze your glutes at the top of the movement.', 'external'),
('a4f1c955-4217-48e0-9a3d-90c80a3fc0aa', 'Sentadilla con pausa', 28, 29, 116, 1, 'Avanzado', 'Sentadilla con pausa de 2-3 segundos en la posición más baja. Elimina rebote y aumenta tiempo bajo tensión. Mejora fuerza en la salida del hoyo. Común en powerlifting. Mantén tensión durante la pausa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Squat with pause', 'Squat with pause of 2-3 seconds in the lowest position. Eliminates rebound and increases time under tension. Improves strength when exiting the hole. Common in powerlifting. Maintain tension during the pause.', 'external'),
('a505742f-3194-45f4-ab39-a8eeab63ce86', 'Trepar cuerda', 16, 17, 1, 1, 'Avanzado', 'Sube por una cuerda vertical usando técnica de pies para asistencia. Ejercicio funcional completo que desarrolla fuerza de agarre excepcional. Aprende técnica de seguridad apropiada. Comienza con cuerdas más gruesas y progresa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rope Climb', 'Climb a vertical rope using your feet for assistance. This full-body functional exercise develops exceptional grip strength. Learn proper safety technique and start with thicker ropes before progressing.', 'bodyweight'),
('a52c6338-af2b-4194-848c-cbd584557853', 'Burpee salto sobre balón', 13, 28, 240, 1, 'Intermedio', 'Haz un burpee y termina saltando lateralmente sobre un balón medicinal. Precisión y potencia. Cue: no pierdas de vista el balón al saltar. Error común: tropezar con el balón.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee Jump on Ball', 'Do a burpee and finish by jumping laterally on a medicine ball. Precision and power. Cue: don''t lose sight of the ball when jumping. Common mistake: tripping over the ball.', 'external'),
('a54f9978-4e4b-4819-afe0-d4e9dc5ecccc', 'Flexión Dive Bomber', 1, 2, 1, 1, 'Intermedio', 'Comienza en posicion de V invertida, baja el pecho rozando el suelo y termina extendiendo los brazos con la mirada al frente.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Dive Bomber Push-Up', 'Start in an inverted V position, lower your chest close to the floor in a sweeping motion, and finish by extending your arms with your chest lifted forward.', 'mixed'),
('a5542633-edc2-43b8-8d92-eed234edf54c', 'Curl bayesian en polea', 17, NULL, 151, 1, 'Intermedio', 'Realiza el curl de bíceps en polea colocándote de espaldas al punto de anclaje para mantener tensión en todo el recorrido. Flexiona el codo de forma controlada y evita balancear el cuerpo.', FALSE, NULL, '2026-05-14T14:43:02.696631+00:00', 'Bayesian Cable Curl', 'Perform the biceps curl on a cable while standing with your back to the anchor point to keep tension throughout the range of motion. Flex the elbow under control and avoid swinging the body.', 'external'),
('a59cc0dc-3ddb-42fb-945a-30cb335fa27b', 'Elevaciones laterales banco de lado inclinado', 6, NULL, 81, 1, 'Intermedio', 'Tumbado lateral en banco, eleva pesa. Cue: tensión máxima inicial. Error: rotar hombro.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Incline Side Bench Side Raises', 'Lying sideways on bench, raise weight. Cue: initial maintain maximum tension. Common mistake: rotate shoulder.', 'external'),
('a5a144b4-c372-4065-acfd-c6231957c6d5', 'Sentadilla Búlgara Goblet con Kettlebell (Horn Grip) Bottoms Up', 28, 29, 281, 1, 'Intermedio', 'Realiza una sentadilla búlgara sujetando la pesa rusa invertida por los cuernos frente al pecho, retando equilibrio y estabilidad.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Goblet Squat with Kettlebell (horn Grip) Bottoms Up', 'Perform a Bulgarian squat holding the inverted kettlebell by the horns in front of your chest, challenging balance and stability.', 'external'),
('a5b0ac04-2cbf-4b9c-9be1-f3c71159362b', 'Sentadilla Ciclista con Kettlebell Bottoms Up (Front Rack)', 28, 29, 281, 1, 'Intermedio', 'Sujeta una Kettlebell invertida en posicion rack sobre un hombro y realiza una sentadilla ciclista con los talones elevados.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Cycle Squat with Bottoms-Up Kettlebell (front Rack)', 'Hold an inverted kettlebell in a rack position over one shoulder and perform a bicycle squat with your heels raised.', 'external'),
('a5da9a59-51ea-42f0-aeea-b85b0a8ea401', 'Press de banca con agarre inverso', 1, 2, 116, 1, 'Avanzado', 'Sujeta la barra con las palmas mirando hacia tu cara (supinadas). Objetivo: mayor activación del pectoral superior y tríceps. Cues: agarre seguro y muñecas rectas. Error común: usar un peso excesivo que comprometa la seguridad de las muñecas.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Reverse Grip Bench Press', 'Hold the bar with your palms facing your face (supinated). Target: greater activation of the upper chest and triceps. Cue: secure grip and straight wrists. Common mistake: using excessive weight that compromises the safety of the dolls.', 'external'),
('a67a3bff-b643-41b5-9195-d8f278d50ca0', 'Press inclinado máquina', 1, 6, 186, 1, 'Principiante', 'En máquina con respaldo inclinado, realiza el press enfocando el pectoral superior. La trayectoria guiada permite concentrarse en el movimiento sin preocuparse por la estabilización. Ajusta el asiento para alineación correcta.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Incline press machine', 'On a machine with an inclined backrest, perform the press focusing on the upper pectoral. The guided trajectory allows you to focus on movement without worrying about stabilization. Adjust the seat for correct alignment.', 'external'),
('a68da7d6-bd74-49fc-a270-845233dff09f', 'Curl Predicador con cable en Fitball', 17, NULL, 151, 1, 'Intermedio', 'Apoya los tríceps sobre un Fitball. Usa una polea baja para realizar curls, utilizando el balón como soporte similar a un banco predicador.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Preacher Curl on Stability Ball', 'Support your triceps on a Stability Ball. Use a low cable to perform curls, using the ball as support similar to a preacher bench.', 'external'),
('a6cbf030-eda2-4958-9c48-758910fa8de9', 'Zancada caminando', 28, 29, 1, 1, 'Principiante', 'Da pasos largos hacia adelante bajando la cadera hasta que ambas rodillas formen un ángulo de 90 grados, avanzando continuamente.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Walking Lunge', 'Take long steps forward, lowering your hips until both knees form 90-degree angles while moving continuously.', 'mixed'),
('a6e0aa3a-9148-4322-8ceb-d1cbcaf60672', 'Sentadilla Búlgara Overhead rodilla sobre punta del pie', 28, 6, 116, 1, 'Avanzado', 'Sostén la barra bloqueada sobre la cabeza mientras realizas una sentadilla split con el pie elevado, llevando la rodilla delantera intencionalmente sobre los dedos del pie.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bulgarian Overhead Squat Knee on Toe', 'Hold the bar locked overhead as you perform a split squat with your foot raised, intentionally bringing your front knee over your toes.', 'external'),
('a6f2487b-f321-4f43-b528-1cc08f679145', 'Remo supino barra', 17, 16, 116, 1, 'Intermedio', 'Realiza el remo inclinado con agarre supino (palmas hacia arriba). Esta variación permite mayor participación del bíceps y puede ser más cómoda para las muñecas. Tira hacia el abdomen inferior manteniendo los codos pegados al cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Supine Bar Row', 'Perform the bent-over row with an underhand grip (palms facing up). This variation allows for greater participation of the biceps and may be more comfortable for the wrists. Pull towards your lower abs, keeping your elbows close to your body.', 'external'),
('a70fa606-7a15-4ecc-96e7-c376b80046a9', 'Zancada estática barra', 28, 29, 116, 1, 'Principiante', 'Split squat barra hombros. Objetivo: cuádriceps. Cue: torso vertical. Error: rodilla sobrepasa pie.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Barbell Split Squat', 'Perform a split squat with the bar on your shoulders. Target: quadriceps. Cue: keep your torso vertical. Common mistake: letting the knee travel too far over the foot.', 'external'),
('a714552d-f7e3-4311-ae29-6735bf5f3bca', 'Zancada caminando Zombie con barra', 28, 29, 116, 1, 'Avanzado', 'Camina realizando zancadas con la barra apoyada en los deltoides frontales y los brazos estirados hacia adelante (sin manos), desafiando el equilibrio.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Walking Zombie Barbell Lunge', 'Walk forward performing lunges with the barbell resting on the front delts and your arms extended straight ahead without using your hands, challenging your balance.', 'external'),
('a74951c6-00a4-43d9-a4f8-db6bab96c406', 'Extensiones lumbares en suelo', 71, 29, 1, 1, 'Principiante', 'Eleva solo el pecho manteniendo pies en suelo. Cue: mira al suelo. Error: tirones bruscos con el cuello.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Lumbar Extensions on the Floor', 'Raise only your chest, keeping your feet on the ground. Cue: look at the ground. Common mistake: sudden jerks with the neck.', 'bodyweight'),
('a79fda5e-026e-43f0-9a0e-69aa0b5e3d94', 'Front Lever a una pierna en anillas', 25, 16, 1, 24, 'Avanzado', 'Ejecuta un Front Lever con una pierna completamente estirada y la otra encogida hacia el pecho, alternando para equilibrar la fuerza.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Front Lever on one leg on rings', 'Perform a Front Lever with one leg fully extended and the other drawn toward the chest, alternating to balance the force.', 'bodyweight'),
('a7c9726b-f332-4de7-b66c-18d36abefdde', 'Remo al cuello con barra', 6, 71, 116, 1, 'Principiante', 'Tira de la barra pegada al cuerpo hacia el mentón elevando los codos. Objetivo: deltoides y trapecio. Cues: codos por encima de las muñecas. Error común: realizar tirones bruscos con la zona lumbar.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Barbell Neck Row', 'Pull the bar close to your body towards your chin, raising your elbows. Target: deltoids and trapezius. Cue: elbows above wrists. Common mistake: making sudden jerks with the lower back.', 'external'),
('a7f25b5e-8eb0-40fe-bffc-6dc90bd6373d', 'Abducción de cadera con cable', 37, 29, 151, 1, 'Principiante', 'De pie de lado a la polea baja, sujeta el tobillo más alejado a la máquina. Manteniendo la pierna recta, levántala lateralmente alejándola del cuerpo y regresa controladamente.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Hip Abduction', 'Standing sideways to the low pulley, hold your farthest ankle to the machine. Keeping your leg straight, lift it laterally away from your body and return under control.', 'external'),
('a81696c9-77ff-46be-90fa-d1011c61a427', 'Flexión pliométrica diamante', 2, 1, 1, 1, 'Avanzado', 'Realiza flexión en diamante y empuja para que las manos despeguen del suelo. Potencia pura de tríceps. Cue: manos bajo el esternón. Error común: arquear la espalda baja por falta de fuerza.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Diamond Plyometric Push-up', 'Perform diamond push-ups and push so that your hands leave the ground. Pure triceps power. Cue: hands under the breastbone. Common mistake: arching the lower back due to lack of strength.', 'mixed'),
('a83046cb-2cab-4aee-81ca-04e606b6fc4b', 'Salto con rodillas al pecho', 28, 25, 1, 1, 'Avanzado', 'Salta verticalmente y lleva las rodillas hacia el pecho rápidamente en el aire. Aterriza y repite. Objetivo: potencia explosiva y velocidad de cadera. Cue: aterriza con las puntas para absorber impacto. Error común: inclinar la espalda hacia atrás en el aire.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Jump with Knees to Chest', 'Jump vertically and bring your knees toward your chest quickly in the air. Land and repeat. Target: explosive power and hip speed. Cue: land on your toes to absorb impact. Common mistake: leaning your back back in the air.', 'bodyweight'),
('a83c3bea-c9d6-4c67-94fa-a5cbc3cf181d', 'Sentadilla Ciclista Overhead con Kettlebell a una mano', 28, 6, 281, 1, 'Intermedio', 'Eleva los talones y mantén una Kettlebell bloqueada sobre la cabeza mientras realizas una sentadilla profunda.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Cycling Overhead Squat with One-Handed kettlebell', 'Raise your heels and hold a kettlebell locked overhead while performing a deep squat.', 'external'),
('a84cfde7-6f51-4665-9df9-05825cd77371', 'Rotación interna hombro banda', 6, NULL, 61, 1, 'Principiante', 'Similar a la rotación externa pero rotando el antebrazo hacia adentro cruzando el cuerpo. Mantén el codo pegado al costado y flexionado a 90 grados. Complementa el trabajo de rotación externa para un desarrollo equilibrado del manguito rotador.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Internal rotation shoulder band', 'Similar to external rotation but rotating the forearm inward across the body. Keep your elbow close to your side and bent at 90 degrees. Complements external rotation work for balanced development of the rotator cuff.', 'external'),
('a8639ad6-325b-4efd-a3d8-8596a2e363fe', 'Flexiones sobre balón medicinal', 1, 2, 240, 1, 'Avanzado', 'Realiza flexiones con una mano sobre el balón y otra en el suelo. Inestabilidad de hombro. Cuerpo recto. No dejes caer el pecho al balón.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Medicine ball push-ups', 'Perform push-ups with one hand on the ball and the other on the floor. Shoulder instability. Straight body. Don''t let your chest drop to the ball.', 'external'),
('a88b0722-76a0-4db9-ab04-b7709c7caadd', 'Pantorrillas de pie máquina', 64, NULL, 186, 1, 'Principiante', 'De pie con los hombros bajo las almohadillas, elévate sobre las puntas de los pies. La posición de piernas extendidas enfatiza el gemelo. Mantén el movimiento controlado y busca el máximo rango de movimiento posible.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Standing Calves Machine', 'Standing with your shoulders under the pads, rise onto the balls of your feet. The extended leg position emphasizes the gastrocnemius. Keep the movement controlled and aim for the maximum range of motion possible.', 'external'),
('a88b5521-b5ee-47bd-bcd1-b0107d3c0ff1', 'Elevaciones laterales de hombro', 6, NULL, 81, 1, 'Principiante', 'Eleva mancuernas a los lados hasta la altura de los hombros con codos semiflexionados. Cue: vierte agua de una jarra al subir. Error: subir por encima de los hombros.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Side Shoulder Raises', 'Raise dumbbells to your sides to shoulder height with elbows semi-bent. Cue: pouring water from a jug on the way up. Common mistake: rise above the shoulders.', 'external'),
('a8996200-38eb-4300-984d-bc9ec11b4524', 'TRX Abductores suelo', 37, 25, 216, 1, 'Intermedio', 'Abre/cierra piernas TRX tumbado. Objetivo: abductores. Cue: core firme. Error: tirones.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX Hip Abductors', 'Open and close your legs while lying down with your feet in the TRX straps. Target: hip abductors. Cue: keep your core braced. Common mistake: using jerky movements.', 'bodyweight'),
('a8acfa2e-34f3-4d4c-b99c-2620b8d3885e', 'Sentadilla búlgara asistida con manos', 28, 29, 1, 1, 'Principiante', 'Con un pie atrasado en un banco, realiza una sentadilla apoyándote en un soporte lateral con las manos para mejorar el equilibrio.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Hand Assisted Bulgarian Squat', 'With one foot back on a bench, perform a squat using lateral support with your hands to improve balance.', 'assisted'),
('a8af4f2b-ef08-4253-a131-3c0e8781ea09', 'Ab wheel rollout', 25, 71, 271, 1, 'Intermedio', 'Desliza la rueda hacia adelante desde rodillas. Cue: core muy apretado. Error: dejar caer la cadera.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Ab Wheel Rollout', 'Slide the wheel forward from your knees. Cue: very tight core. Common mistake: dropping your hips.', 'bodyweight'),
('a8c141ef-3274-4686-8e9c-0f0a77d11870', 'Press de banca guillotina', 1, 6, 116, 1, 'Avanzado', 'Baja la barra hacia la base del cuello con agarre ancho. Objetivo: fibras superiores del pecho. Cue: codos muy abiertos. Error común: usar demasiado peso sin control (peligroso para hombros).', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Guillotine Bench Press', 'Lower the bar toward the base of your neck with a wide grip. Target: upper fibers of your chest. Cue: elbows wide open. Common mistake: using too much weight without control (dangerous for shoulders).', 'external'),
('a8da5c66-8efe-48cc-881a-add3ec45e411', 'Step Up con mancuernas (Maleta)', 28, 29, 81, 1, 'Principiante', 'Sube a un cajón o banco apoyando toda la planta del pie. Sostén las mancuernas a los lados y empuja con la pierna delantera hasta extenderte.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Dumbbell Suitcase Step-up', 'Step onto a box or bench with your whole foot planted. Hold the dumbbells at your sides and drive through the lead leg to stand tall.', 'external'),
('a8f79f3d-a400-4294-97b3-a14ac0d9e201', 'Extensión de tríceps en banco inclinado con barra Z', 2, NULL, 116, 1, 'Principiante', 'Tumbado en un banco inclinado, baja la barra Z hacia la frente flexionando los codos y luego extiende los brazos completamente para trabajar el triceps.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Z-Bar Incline Bench Triceps Extension', 'Lying on an incline bench, lower the Z bar toward your forehead by bending your elbows, then extend your arms fully to work your triceps.', 'external'),
('a8fd38db-bda3-4af5-8343-e20608a01297', 'Press Z con Kettlebell doble', 6, 25, 281, 1, 'Avanzado', 'Siéntate en el suelo con las piernas estiradas en V. Sin apoyo en la espalda, realiza un press de hombros con dos pesas rusas.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double kettlebell Z Press', 'Sit on the floor with your legs extended in a V. Without support on your back, perform a shoulder press with two kettlebells.', 'external'),
('a8fe1fde-7b55-4ec5-ad99-a0fd59ebf0aa', 'Glúteo máquina', 29, NULL, 186, 1, 'Principiante', 'En máquina específica para glúteos, realiza extensiones de cadera. Puede ser de pie o en cuadrupedia según el diseño. Enfócate en la contracción del glúteo sin arquear excesivamente la espalda. Mantén el core activado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Glute Machine', 'On a specific machine for glutes, perform hip extensions. It can be standing or quadruped depending on the design. Focus on contracting your glutes without excessively arching your back. Keep your core activated.', 'external'),
('a90d5a22-3943-4421-ab70-b9b5a7abbaf9', 'Zancada inversa contralateral con Slider y Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sostén una pesa rusa invertida (fondo arriba) en una mano y desliza hacia atrás la pierna del lado opuesto usando un slider.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse contralateral stride with Slider and Kettlebell Bottoms Up', 'Hold an inverted (bottom up) kettlebell in one hand and slide back the leg on the opposite side using a slider.', 'external'),
('a9248bb3-4cba-497f-9411-4e42e619f9ab', 'Peso muerto Trap Bar', 29, 71, 116, 1, 'Principiante', 'Levanta la barra hexagonal usando las asas superiores. Cue: saca pecho y espalda plana. Error: rodillas hacia adentro.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Trap Bar Deadlift', 'Lift the hex bar using the top handles. Cue: chest out and back flat. Common mistake: knees inward.', 'external'),
('a93e7021-2fa7-490b-a5de-bb2165d4f168', 'TRX Flexión de pecho con pies elevados', 1, 25, 216, 1, 'Avanzado', 'Pies en los agarres, realiza flexiones en el suelo. Inestabilidad máxima. Cuerpo recto. No dejes que la zona lumbar se hunda.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Push-Up with Elevated Feet', 'Place your feet in the straps and perform push-ups on the floor. This creates maximum instability. Keep your body straight and do not let your lower back sag.', 'mixed'),
('a95496db-9d14-4bd0-b9d7-87fa5388752b', 'Remo inclinado agarre inverso con barra', 71, 17, 116, 1, 'Principiante', 'Inclinado hacia adelante, sujeta la barra con palmas hacia arriba y tirala hacia el ombligo manteniendo la espalda recta.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Reverse Grip Barbell Bent-Over Row', 'Leaning forward, hold the bar with your palms facing up and pull it toward your navel, keeping your back straight.', 'external'),
('a95c8cdd-8ffb-4ac9-b83b-370434071f0e', 'Remo invertido con barra', 71, 17, 116, 1, 'Principiante', 'Sujeta una barra fija desde abajo con el cuerpo recto y los talones apoyados. Tira del pecho hacia la barra contrayendo las escápulas y baja con control.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Inverted barbell row', 'Hold a fixed bar from below with your body straight and heels supported. Pull your chest towards the bar by contracting your scapulae and lower yourself with control.', 'external'),
('a98b5da4-5712-4058-a9a4-c71718c39d91', 'Press Pallof con banda elástica', 25, 6, 61, 1, 'Principiante', 'Sujeta la banda frente al pecho lateralmente al anclaje y extiéndela resistiendo la rotación, activando profundamente el core.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Pallof Press with elastic band', 'Hold the band in front of the chest laterally to the anchor and extend it resisting rotation, deeply activating the core.', 'external'),
('a9aa5ddc-d604-42d7-a841-0373f2ee291a', 'Roll out rodillas', 25, NULL, 271, 1, 'Principiante', 'Versión básica del roll out desde rodillas. Ideal para principiantes. Comienza con rangos cortos y progresa gradualmente. Mantén los brazos rectos y evita arquear la espalda baja. Respira controladamente durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Roll out knees', 'Basic version of the roll out from knees. Ideal for beginners. Start with short ranges and progress gradually. Keep your arms straight and avoid arching your lower back. Breathe controlledly during movement.', 'external'),
('a9d3698d-4d8f-4d5b-a977-0bb52acc608c', 'Battle Ropes Ondas alternas', 6, 17, 256, 24, 'Principiante', 'Mueve las cuerdas arriba y abajo de forma alterna lo más rápido posible. Mantén sentadilla parcial. Core firme. No muevas el tronco.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Battle Ropes Alternating Waves', 'Move the ropes up and down alternately as quickly as possible. Maintain partial squat. Firm core. Don''t move your torso.', 'external'),
('aa233c17-781f-433a-903d-51bf9607d87a', 'Rollout de pie con rueda abdominal', 25, 6, 271, 1, 'Avanzado', 'Desde una posicion de pie, desplaza la rueda hacia adelante extendiendo el cuerpo por completo hasta quedar cerca del suelo y regresa usando la fuerza del core.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Standing rollout with ab wheel', 'From a standing position, roll the wheel forward by fully extending your body until you are close toward the floor and return using core strength.', 'external'),
('aa2c81c4-7430-4a94-93cd-181f6049680c', 'Press Pallof medio arrodillado con cable', 25, 6, 151, 1, 'Principiante', 'En posicion de caballero lateral a la polea, sujeta el mando frente al pecho y extiende los brazos hacia adelante resistiendo la fuerza lateral del cable sin rotar el torso.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Half Kneeling Cable Pallof Press', 'In a half-kneeling position lateral to the pulley, hold the control in front of your chest and extend your arms forward resisting the lateral force of the cable without rotating your torso.', 'external'),
('aa2f3490-5f25-4536-a852-514f70c3e18c', 'Ring Dip a Press de cuerpo recto a parada de manos', 6, 2, 1, 1, 'Avanzado', 'Realiza un fondo en anillas y utiliza la fuerza de empuje para elevar el cuerpo estirado hasta alcanzar la posicion vertical de parada de manos.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Ring Dip to Straight Body Press to Handstand', 'Perform a ring dip and use the pushing force to raise the stretched body until reaching the vertical handstand position.', 'mixed'),
('aa3a6d28-80ba-4b65-ba0e-8ac84288a34d', 'Plancha frontal toques laterales', 25, 37, 1, 1, 'Intermedio', 'Saca pie lateral en plancha. Objetivo: estabilidad core. Cue: cadera quieta. Error: elevar glúteo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Front Plank Lateral Taps', 'From a plank position, tap one foot out to the side and return, alternating sides. Target: core stability. Cue: keep your hips quiet. Common mistake: lifting your glutes.', 'bodyweight'),
('aa47071d-faaa-4d89-9b44-1c266868070a', 'Sentadilla trasera con barra baja', 29, 55, 116, 1, 'Intermedio', 'Coloca la barra sobre los deltoides posteriores. Inclina el torso ligeramente hacia adelante mientras bajas la cadera, maximizando la palanca de la cadena posterior.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Low Bar Back Squat', 'Place the bar over your rear deltoids. Lean your torso forward slightly as you lower your hips, maximizing posterior chain leverage.', 'external'),
('aa9dceb3-c91b-4b88-adee-5559fe0f8c4d', 'Press Overhead alterno (Seesaw) con Kettlebell', 6, 25, 281, 1, 'Intermedio', 'Presiona una pesa rusa hacia arriba mientras bajas la otra simultáneamente, creando un movimiento constante de sube y baja.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Alternate Overhead Press (seesaw) with Kettlebell', 'Press one kettlebell up while lowering the other simultaneously, creating a constant up-and-down motion.', 'external'),
('aaaafb0f-a04f-4f25-912c-8632b2511d2c', 'Escaladores cruzados veloces', 25, 6, 1, 24, 'Intermedio', 'Lleva la rodilla hacia el codo opuesto rápidamente. Cardio y core. Espalda plana. No eleves el glúteo demasiado.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Fast cross climbers', 'Quickly bring your knee toward the opposite elbow. Cardio and core. Flat back. Don''t raise your glutes too much.', 'bodyweight'),
('aab7f0e7-2192-42b7-9187-6a1af87a61ff', 'Remo al mentón con mancuernas', 6, 71, 81, 1, 'Principiante', 'Eleva mancuernas pegadas al cuerpo hasta el pecho subiendo codos. Cue: codos por encima de muñecas. Error: encoger trapecios excesivamente.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dumbbell Chin Row', 'Raise dumbbells close to your body up to your chest, raising your elbows. Cue: elbows above wrists. Common mistake: shrinking trapezius excessively.', 'external'),
('aabc4438-1f04-4298-a1fa-f5db55d7b513', 'Plate Otis Up', 25, 6, 81, 1, 'Principiante', 'Tumbado boca arriba, realiza un sit up manteniendo un disco extendido sobre el pecho con ambos brazos bloqueados durante el movimiento.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Plate Otis Up', 'Lying on your back, perform a sit-up, keeping a disc extended over your chest with both arms locked during the movement.', 'external'),
('ab2363ff-8569-4c31-b430-f3b7615df839', 'Aperturas de pecho en anillas', 1, 6, 1, 1, 'Intermedio', 'Desde posicion de plancha en anillas, abre los brazos lateralmente con un ligero doblez en los codos y vuelve a cerrarlos frente al pecho.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ring Chest Fly', 'From a ring plank position, open your arms laterally with a slight bend in the elbows and close them again in front of your chest.', 'bodyweight'),
('ab5ec1e6-bc2e-478f-9d05-8c8c9a8af793', 'Elevaciones laterales con banda', 6, NULL, 61, 1, 'Principiante', 'Pisa el centro de la banda y sujeta los extremos a los lados. Eleva los brazos lateralmente hasta la altura de los hombros manteniendo una ligera flexión en los codos. Controla el descenso resistiendo la tensión de la banda. Excelente para el deltoides medio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Band Lateral Raises', 'Step on the center of the band and hold the ends to the sides. Raise your arms laterally to shoulder height, maintaining a slight bend in the elbows. Controls descent by resisting the tension of the band. Excellent for the middle deltoid.', 'external'),
('ab74bea9-8ff1-4e26-895e-a827418b529a', 'Remo landmine', 16, 25, 116, 1, 'Avanzado', 'Remo con barra en landmine. Permite diferentes ángulos y agarres. Versión en T-bar row es popular. El ángulo único proporciona un estímulo diferente. Mantén el core apretado para proteger la espalda baja.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Landmine Rowing', 'Landmine barbell row. Allows different angles and grips. T-bar row version is popular. The unique angle provides a different stimulus. Keep your core tight to protect your lower back.', 'external'),
('abe52b0d-a0d3-44b1-8806-d2e944ab335b', 'Copenhagen Plank con rodilla doblada', 313, 25, 1, 24, 'Principiante', 'Version simplificada de la Copenhagen Plank apoyando la rodilla superior en el banco en lugar del pie para reducir el brazo de palanca.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Copenhagen Plank with bent knee', 'Simplified version of the Copenhagen Plank by placing the top knee on the bench instead of the foot to reduce the leverage arm.', 'bodyweight'),
('abe5cf82-c5c2-482c-bde5-376eaedbd0f0', 'Jumping jacks', 13, NULL, 1, 1, 'Principiante', 'Comienza de pie con pies juntos y brazos a los lados. Salta abriendo las piernas más allá del ancho de los hombros mientras elevas los brazos por encima de la cabeza. Salta nuevamente para volver a la posición inicial. Mantén un ritmo constante y aterriza suavemente en las puntas de los pies.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Jumping jacks', 'Start standing with feet together and arms at your sides. Jump opening your legs wider than shoulder width while raising your arms above your head. Jump again to return to the starting position. Keep a steady pace and land softly on the balls of your feet.', 'bodyweight'),
('abfa13e9-da19-440d-a944-bec43cd800a9', 'Elevación de piernas estiradas en suelo', 25, NULL, 1, 1, 'Principiante', 'Tumbado boca arriba, eleva las piernas juntas hasta los 90 grados y baja sin tocar el suelo. Objetivo: abdominal inferior. Cue: mantén la zona lumbar pegada al suelo. Error: arquear la espalda al bajar las piernas.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Straight Leg Raises on the Floor', 'Lying on your back, raise your legs together to 90 degrees and lower yourself without touching the ground. Target: lower abdominal. Cue: keep your lower back close to the floor. Common mistake: arching your back when lowering your legs.', 'bodyweight'),
('ac35c27a-f91d-4b67-9697-d9862ebad9b4', 'Grip Full Planche en anillas', 25, 6, 1, 24, 'Avanzado', 'Manten el cuerpo horizontal en anillas utilizando un agarre falso o profundo para mejorar el torque y control de la posicion plana.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Full Planche Grip on Rings', 'Keep your body horizontal on rings using a false or deep grip to improve torque and control of the flat position.', 'bodyweight'),
('ac5453c9-472d-4992-a77f-ed6639406205', 'Clean a Thruster con Kettlebell doble', 6, 28, 281, 1, 'Intermedio', 'Realiza una cargada explosiva seguida inmediatamente de una sentadilla profunda y un press vertical al subir, en un solo movimiento fluido.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Clean a Thruster with Double Kettlebell', 'Perform an explosive clean followed immediately by a deep squat and a vertical press on the way up, in one fluid movement.', 'external'),
('ac5b65d8-cebb-4f84-9a2f-e0170069de2d', 'Press de hombros con barra (Overhead Press)', 6, 2, 116, 1, 'Intermedio', 'De pie, empuja la barra desde los hombros hasta estirar los brazos por encima de la cabeza, manteniendo el core firme y sin impulsarte con las piernas.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Barbell Shoulder Press (Overhead Press)', 'Standing, push the bar from your shoulders until you extend your arms above your head, keeping your core firm and without pushing yourself with your legs.', 'external'),
('ad3dcb00-27cd-4808-9504-9222d0afade2', 'Extensión de cuádriceps en máquina', 28, NULL, 186, 1, 'Principiante', 'Sentado, extiende las rodillas contra el rodillo. Aislamiento puro de cuádriceps. Cue: mantén el glúteo pegado al asiento. Error: bloquear rodillas bruscamente.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Quadriceps Extension on Machine', 'Sit on the machine and extend your knees against the roller. Target: pure quadriceps isolation. Cue: keep your hips firmly against the seat. Common mistake: locking the knees abruptly.', 'external'),
('ad7672c6-6aa4-4b3a-a0fe-75813cd8c07e', 'Dead Bug con banda elástica', 25, NULL, 61, 1, 'Principiante', 'Realiza el movimiento de Dead Bug mientras sujetas una banda elástica con las manos, aumentando la tensión sobre el core.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Dead Bug with elastic band', 'Perform the Dead Bug movement while holding an elastic band in your hands, increasing tension on the core.', 'external'),
('ad7d782b-aa3d-4b08-be1a-5f2881cfd392', 'Burpee sobre barra frontal', 13, 28, 116, 1, 'Intermedio', 'Realiza un burpee y salta hacia adelante sobre una barra. Cue: salto a dos pies simultáneos. Error común: dudar ante la barra por miedo al tropiezo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee on Front Bar', 'Perform a burpee and jump forward on a bar. Cue: jump on two feet simultaneously. Common mistake: hesitating before the bar for fear of tripping.', 'external'),
('ad815d25-aeae-4769-be50-d1669457ae39', 'Curl de isquiotibiales en banco prono', 55, NULL, 151, 1, 'Principiante', 'Tumbado boca abajo en un banco, flexiona las rodillas tirando de la resistencia del cable hacia los glúteos.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Prone bench hamstring curl', 'Lying face down on a bench, bend your knees, pulling the resistance of the cable toward your glutes.', 'external'),
('adf8c325-c948-40c2-b468-3f3ecc788d5c', 'Sentadilla Búlgara Overhead con Kettlebell doble rodilla sobre dedos', 28, 6, 281, 1, 'Avanzado', 'Sostén dos Kettlebells sobre la cabeza y realiza una sentadilla split llevando la rodilla delantera sobre los dedos del pie.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Bulgarian Overhead Squat with kettlebell Double Knee on Toes', 'Hold two kettlebells overhead and perform a split squat bringing your front knee over your toes.', 'external'),
('ae16bf2a-bd23-4cce-8e1e-726c09ae9987', 'Curl Zottman con mancuernas', 17, 100, 81, 1, 'Intermedio', 'Realiza un curl de bíceps normal (palmas arriba) y, en el punto máximo, gira las palmas hacia abajo para descender lentamente. Objetivo: bíceps y antebrazos. Cue: baja el peso de forma muy controlada. Error: usar el impulso del cuerpo para subir.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Dumbbell Zottman Curl', 'Perform a regular biceps curl (palms up) and at the peak, turn your palms down to slowly lower yourself. Target: biceps and forearms. Cue: lower the weight in a very controlled way. Common mistake: using body momentum to go up.', 'external'),
('ae194258-6a86-4fa3-8b6b-f53b0b8bcf65', 'Salto al cajón sentado', 28, 29, 1, 1, 'Intermedio', 'Siéntate en un banco, levántate y salta inmediatamente a un cajón. Elimina el pre-estiramiento para enfocar en potencia pura. Cue: explosión total al despegar del banco. Error común: dudar en el despegue.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Sitting Box Jump', 'Sit on a bench, stand up and immediately jump onto a box. Eliminate pre-stretch to focus on pure power. Cue: total explosion upon taking off from the bench. Common mistake: hesitating on takeoff.', 'bodyweight'),
('ae6553fe-1ea9-4fae-8ec4-b8d8c0cf3a31', 'Thruster Ciclista alterno con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza el movimiento de thruster ciclista con dos pesas rusas invertidas, alternando el press vertical en cada subida de la sentadilla.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Alternating Cyclist Double Bottoms-Up Kettlebell Thruster', 'Perform the cyclist thruster movement with two upside-down kettlebells, alternating the overhead press on each ascent from the squat.', 'external'),
('af30d16b-e088-40da-84c4-541b4b705aef', 'Extensión tríceps polea unilateral', 2, NULL, 151, 1, 'Intermedio', 'Extensión con un solo brazo en polea. Objetivo: corregir asimetrías. Cue: hombro estable. Error: impulso torso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Unilateral Cable Triceps Extension', 'single arm cable extension. Target: correct asymmetries. Cue: stable shoulder. Common mistake: torso impulse.', 'external'),
('afa814ea-ef1d-449d-8c4c-e34c4deb84ba', 'Ring Dip a parada de manos', 6, 2, 1, 1, 'Avanzado', 'Ejecuta un fondo en anillas y, de forma explosiva y fluida, transiciona hasta quedar en posición vertical de parada de manos.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Ring Dip to handstand', 'Perform a ring dip and explosively and fluidly transition to a vertical handstand position.', 'mixed'),
('afac3a9e-39c1-4970-866b-434e4a919409', 'Peso muerto sumo con barra', 29, 313, 116, 1, 'Intermedio', 'Pies muy anchos, agarre por dentro de las piernas. Mayor énfasis en aductores y glúteo. Cue: espalda vertical. Error: dejar que las rodillas se cierren.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Sumo Deadlift', 'Very wide feet, grip on the inside of the legs. Greater emphasis on adductors and glutes. Cue: vertical back. Common mistake: letting your knees close.', 'external'),
('afc12594-f822-4006-852d-257fdd6a7093', 'Sentadilla fitball', 28, 29, 290, 1, 'Principiante', 'Coloca la fitball entre tu espalda baja y la pared. Desciende en sentadilla mientras la pelota rueda por tu espalda. Proporciona soporte y feedback propioceptivo. Ideal para principiantes o rehabilitación. Mantén los pies adelantados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stability Ball Squat', 'Place the stability ball between your lower back and the wall. Lower yourself into a squat while the letting the ball roll across your back. Provides proprioceptive support and feedback. Ideal for beginners or rehabilitation. Keep your feet forward.', 'bodyweight'),
('afc233fb-768c-429b-9279-78ce2dd37888', 'Press hombros Smith frontal sentado', 6, 2, 186, 1, 'Principiante', 'Press militar guiado sentado. Cue: codos adelantados. Error: arquear lumbar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Seated Front Smith Machine Shoulder Press', 'Seated shoulder press on the Smith machine. Cue: keep your elbows slightly forward. Common mistake: arching your lower back.', 'external'),
('afd09ab9-fb4b-4f32-aabe-a3b428b74848', 'Remo con barra agarre ancho al pecho', 71, 6, 116, 1, 'Intermedio', 'Torso inclinado, agarre muy ancho, tira hacia el esternón. Cue: codos hacia afuera. Error: encoger hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Row with Wide Grip Bar to the Chest', 'Inclined torso, very wide grip, pull towards the sternum. Cue: elbows out. Common mistake: shrugging your shoulders.', 'external'),
('aff2132a-6f25-4982-a406-b24f89fa1fa6', 'Elevaciones laterales con mancuernas', 6, NULL, 81, 1, 'Intermedio', 'Elevación lateral para deltoide medio, con técnica estricta y sin balanceos para maximizar estímulo en hombro.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Dumbbell Lateral Raises', 'Lateral raise for middle deltoid, with strict technique and without swings to maximize shoulder stimulation.', 'external'),
('b00126cc-0d6f-4e7b-a7f7-6b3ed3999dbf', 'Press Overhead rotacional con Kettlebell a una mano', 6, 2, 281, 1, 'Intermedio', 'Presiona la Kettlebell sobre la cabeza mientras rotas el torso y pivoteas sobre el pie, integrando la potencia de todo el cuerpo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Rotational Overhead Press with One-Handed kettlebell', 'Press the kettlebell overhead while rotating your torso and pivoting on your foot, integrating the power of your entire body.', 'external'),
('b0059384-31bb-47f2-8883-05abf4fef020', 'Encogimientos hombros prensa', 71, 6, 186, 1, 'Intermedio', 'Eleva hombros en plataforma prensa. Cue: brazos rectos. Error: doblar codos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Shoulder Press Shrugs', 'Raise shoulders on press platform. Cue: straight arms. Common mistake: bending elbows.', 'external'),
('b006f9af-0012-4083-9fd6-6602cec3082d', 'Plank lateral en anillas', 25, 6, 1, 24, 'Avanzado', 'Realiza una plancha lateral apoyando un brazo en la anilla inestable, manteniendo la cadera alta y el cuerpo alineado.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Lateral ring plank', 'Perform a side plank resting one arm on the unstable ring, keeping your hips high and your body aligned.', 'bodyweight'),
('b00928ef-5864-43b3-a32c-d57c87c2ef0d', 'Curl bíceps barra recta', 17, 100, 116, 1, 'Principiante', 'Flexiona barra con palmas arriba. Objetivo: masa bíceps. Cue: codos fijos. Error: mover hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Straight Bar Biceps Curl', 'Flex bar with palms up. Target: biceps mass. Cue: keep your elbows fixed. Common mistake: move shoulders.', 'external'),
('b01a038c-c417-4314-8e0f-830d079bb42e', 'Remo medio a una mano en TRX', 71, 17, 216, 1, 'Intermedio', 'Sostén una sola correa de TRX, inclina tu cuerpo hacia atrás y tira del torso hacia arriba manteniendo el codo cerca de las costillas.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Medium one-hand row on TRX', 'Holding a single TRX strap, lean your body back and pull your torso up, keeping your elbow close to your ribs.', 'bodyweight'),
('b0356314-8248-4be9-a448-162b97f6de4e', 'Cable Rope Half Kneeling High to Low Chop', 25, NULL, 151, 1, 'Intermedio', 'De rodillas, tira de la cuerda desde una posición alta cruzando el cuerpo hacia la cadera opuesta, rotando el torso y manteniendo los brazos semi-rectos.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Cable Rope Half Kneeling High to Low Chop', 'From your knees, pull the rope from a high position crossing your body towards the opposite hip, rotating your torso and keeping your arms semi-straight.', 'external'),
('b063235c-c00c-4f99-8688-04e884765afb', 'Squat Clean Front Rack con Kettlebell doble Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Realiza una cargada recibiendo dos Kettlebells invertidas en posicion rack mientras bajas a una sentadilla profunda.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Squat Clean Front Rack with Double kettlebell Bottoms Up', 'Perform a clean receiving two kettlebells inverted in a rack position while lowering into a deep squat.', 'external'),
('b0b9ae59-54b3-4e3a-8cc6-94415304ac58', 'Remo Pendlay con mancuernas', 71, 17, 81, 1, 'Intermedio', 'Con el torso paralelo al suelo, rema las mancuernas desde el suelo (pausa muerta) hasta el torso en cada repetición.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Dumbbell Pendlay Row', 'With your torso parallel to the floor, row the dumbbells from the floor (dead pause) to your torso on each repetition.', 'external'),
('b13c0209-559d-4e70-bfb5-d34a93e9e8f7', 'Ring Hanging Oblique Knee Raise', 25, 100, 1, 1, 'Intermedio', 'Cuélgate de las anillas. Levanta las rodillas hacia un lado del pecho, girando la cadera para activar los oblicuos. Alterna los lados en cada repetición.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Hanging Oblique Knee Raise', 'Hang on the rings. Raise your knees to the side of your chest, rotating your hips to activate your obliques. Alternate sides with each repetition.', 'bodyweight'),
('b13dce93-0ed4-4294-b88d-ab25a803a6be', 'Swing exterior con Kettlebell doble', 29, 6, 281, 1, 'Intermedio', 'Balancea dos pesas rusas por fuera de las piernas, requiriendo una postura mas estrecha y un gran control de la trayectoria de los brazos.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double Kettlebell Outside Swing', 'Swing two kettlebells outside your legs, which requires a narrower stance and precise control of the arm path.', 'external'),
('b155a5e0-bbc1-47f1-ada2-3e198feb7ba7', 'Zancada lateral explosiva banda', 37, NULL, 61, 1, 'Avanzado', 'Realiza zancadas laterales resistidas por banda, buscando un salto potente al centro. Cue: resiste el tirón lateral de la banda. Error común: que la banda te desequilibre al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Explosive Side Stride Band', 'He makes lateral strides resisted by band, looking for a powerful jump to the center. Cue: resists lateral tugging of the band. Common mistake: The band unbalances you when jumping.', 'external'),
('b166f733-60d1-49b2-9464-7ef72559a9fb', 'Zancada caminando Overhead con mancuernas', 28, 29, 81, 1, 'Intermedio', 'Camina realizando zancadas mientras sostienes dos mancuernas bloqueadas sobre la cabeza, exigiendo estabilidad en hombros y core.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Walking Overhead Dumbbell Lunge', 'Walk forward performing lunges while holding two dumbbells locked out overhead, demanding strong shoulder and core stability.', 'external'),
('b182b147-302d-4248-b0ea-af4444767c90', 'Remo Shotgun a una mano con cable', 71, 17, 151, 1, 'Intermedio', 'En posición de zancada, rema con el cable desde abajo mientras rotas ligeramente el torso, como si cargaras una escopeta.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-Handed Shotgun Rower with Cable', 'In a lunge position, row with the cable from the bottom while rotating your torso slightly, as if loading a shotgun.', 'external'),
('b1b06547-d549-45b5-a2e5-ada20e1be2b9', 'Pull over con mancuerna codos bloqueados', 16, 1, 81, 1, 'Intermedio', 'Realiza un pull over con mancuerna manteniendo los codos casi bloqueados. Lleva la mancuerna por detrás de la cabeza de forma controlada y vuelve activando dorsal y pecho.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Straight-Arm Dumbbell Pullover', 'Perform a straight-arm dumbbell pullover while keeping the elbows almost locked. Move the dumbbell behind the head under control and return by engaging the lats and chest.', 'external'),
('b1cf23f5-4728-49b9-a370-244aa92051ec', 'Hollow Body Hold con Kettlebell doble', 25, NULL, 281, 24, 'Intermedio', 'Mantén la posición de Hollow Body sosteniendo una Kettlebell en cada mano, ya sea contra el pecho o con brazos extendidos, aumentando la intensidad.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Hollow Body Hold with Double Kettlebell', 'Maintain the Hollow Body position holding a kettlebell in each hand, either against your chest or with your arms extended, increasing the intensity.', 'external'),
('b1ebab9f-5c46-4daf-8694-af7a3a8bcb7f', 'Zancadas caminando con mancuernas', 28, 29, 81, 1, 'Intermedio', 'Realiza zancadas caminando con mancuernas. Da pasos largos y controlados, baja hasta una profundidad cómoda y empuja con la pierna delantera para avanzar.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Dumbbell Walking Lunges', 'Perform dumbbell walking lunges. Take long controlled steps, lower to a comfortable depth, and push through the front leg to move forward.', 'external'),
('b21e300a-a049-46c2-a05e-f2b34ae06910', 'Sentadilla Hack en máquina', 28, 29, 186, 1, 'Intermedio', 'Sentadilla apoyado en plataforma inclinada. Cue: pies a media altura, baja profundo. Error: bloquear rodillas al subir.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Hack Squat on Machine', 'Squat supported on inclined platform. Cue: feet mid-height, low deep. Common mistake: blocking knees when going up.', 'external'),
('b2279338-89c0-497e-a410-1e0aaec994c5', 'Bent Arm Press Handstand', 6, 2, 1, 1, 'Avanzado', 'Desde una posición de trípode o tuck, empuja el cuerpo hasta quedar en parada de manos vertical manteniendo los brazos flexionados al inicio.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Bent Arm Press Handstand', 'From a tripod or tuck position, push your body until you are in a vertical handstand, keeping your arms bent at the beginning.', 'bodyweight'),
('b239667d-5739-4f7f-9051-d96d56fc3131', 'Aductor fitball sentado', 313, NULL, 290, 1, 'Principiante', 'Aprieta fitball entre rodillas sentado. Objetivo: aductores. Cue: aprieta 2 seg. Error: espalda curva.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Stability Ball Adductor', 'Squeeze a stability ball between your knees while seated. Target: adductors. Cue: squeeze for 2 seconds. Common mistake: rounding your back.', 'bodyweight'),
('b27a3a64-8c04-4206-bed6-8f275cb41415', 'Press militar con barra de pie', 6, 2, 116, 1, 'Intermedio', 'Empuja barra sobre cabeza sin impulso de piernas. Cue: glúteos apretados. Error: arquear espalda.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Standing Barbell Military Press', 'Push bar overhead without leg drive. Cue: tight glutes. Common mistake: arching your back.', 'external'),
('b2930805-b797-43dd-a013-7aa9c2e5c30d', 'Turkish Get Up con Kettlebell a una mano Bottoms Up', 25, 6, 281, 1, 'Avanzado', 'Realiza el levantamiento turco completo manteniendo la Kettlebell invertida sobre la cabeza, requiriendo un control de estabilidad total.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Bottoms-Up Single-Arm Kettlebell Turkish Get-Up', 'Perform the full Turkish get-up while keeping the kettlebell upside down overhead, requiring total stability and control.', 'external'),
('b2a37538-fd04-4429-b06e-9bdbf3ae689f', 'Remo bajo unilateral en polea', 16, 17, 151, 1, 'Principiante', 'Remo sentado con un solo brazo. Enfoque en dorsal. Espalda recta. No rotes el tronco al estirar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Unilateral low cable row', 'One-arm seated row. Focus on dorsal. Straight back. Do not rotate the torso when stretching.', 'external'),
('b2e59bfb-e463-4eb3-a8a6-33dea036ecc0', 'Hefesto', 16, 17, 1, 1, 'Avanzado', 'Desde colgado en barra, realiza una dominada invertida llevando el cuerpo por detrás de la barra hasta quedar en apoyo. Movimiento extremadamente avanzado que combina fuerza de tracción con transición compleja. Requiere movilidad de hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hephaestus', 'From hanging on a bar, perform an inverted pull-up, bringing your body behind the bar until you are supported. Extremely advanced movement that combines pulling force with complex transition. Requires shoulder mobility.', 'mixed'),
('b2ed93e0-5764-4a65-b970-325190842424', 'Floor Press mancuernas', 1, 2, 81, 1, 'Principiante', 'Press en suelo con mancuernas. Objetivo: pecho y tríceps. Cue: lumbar apoyada. Error: despegar espalda.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Dumbbell Floor Press', 'Dumbbell floor press. Target: chest and triceps. Cue: lumbar supported. Common mistake: take off back.', 'external'),
('b2f60df6-167a-4a77-b742-5e8504073640', 'Press Z en Landmine a una mano', 6, 25, 116, 1, 'Intermedio', 'Sentado en el suelo sin apoyo, presiona la barra Landmine sobre la cabeza, lo que elimina el impulso de las piernas y aisla el hombro.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Z Press on Landmine One-Handed', 'Sitting on the floor without support, press the Landmine bar overhead, which eliminates leg drive and isolates the shoulder.', 'external'),
('b2fc76e9-c1a4-4f30-b640-1b640712dbe0', 'Extensión tríceps sobre cabeza cable', 2, NULL, 151, 1, 'Intermedio', 'De espaldas a la polea baja, sostén la cuerda sobre la cabeza con los codos apuntando hacia adelante. Extiende los codos manteniendo los brazos superiores inmóviles. Esta posición enfatiza la cabeza larga del tríceps y proporciona un estiramiento máximo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Overhead Triceps Extension', 'With your back to the low cable, hold the rope overhead with your elbows pointing forward. Extend your elbows while keeping your upper arms motionless. This position emphasizes the long head of the triceps and provides a maximum stretch.', 'external'),
('b31aba5f-6d65-4cdd-9e3b-69b8c29825e4', 'Press hombros sentado barra', 6, 2, 116, 1, 'Intermedio', 'Empuja barra sobre cabeza sentado. Objetivo: fuerza deltoides. Cue: core firme. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Barbell Shoulder Press', 'Seated overhead bar press. Target: deltoid strength. Cue: firm core. Common mistake: arching your lower back.', 'external'),
('b34a008a-5e98-4908-9b48-b2b7cb519669', 'Elevación de talones estricta', 64, 309, 1, 1, 'Principiante', 'Eleva los talones buscando máxima altura. Fuerza de gemelos. Rodillas estiradas. No te balancees adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Strict heel raise', 'Raise your heels seeking maximum height. Twin strength. Knees stretched. Don''t swing forward.', 'mixed'),
('b3b9861b-6254-4954-8e92-15f194e90834', 'Extensión de tríceps Overhead con cuerda en polea', 2, NULL, 151, 1, 'Principiante', 'De espaldas a la polea, sostén la cuerda sobre la cabeza. Extiende los brazos hacia adelante y arriba, separando los extremos de la cuerda al final.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Overhead Triceps Extension with Pulley Rope', 'With your back to the cable, hold the rope overhead. Extend your arms forward and up, separating the ends of the rope at the end.', 'external'),
('b3c9e725-8804-490b-864e-5450902e1565', 'Snatch con Kettlebell a una mano', 6, 71, 281, 1, 'Intermedio', 'Lleva la Kettlebell desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, bloqueando el brazo en el tope.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Handed kettlebell Snatch', 'Bring the kettlebell from the floor to overhead in a single explosive movement, locking your arm at the top.', 'external'),
('b3dc82d2-66cd-437b-902d-3625a787908e', 'Remo invertido supinado', 71, 17, 1, 1, 'Principiante', 'Remo en barra baja palmas hacia ti. Objetivo: espalda/bíceps. Cue: cuerpo tabla. Error: hundir cadera.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Supinated Inverted Row', 'Low bar row palms towards you. Target: back and biceps. Cue: table body. Common mistake: sinking hip.', 'bodyweight'),
('b3e12dc1-301b-46b1-b2b8-860ceb706e30', 'Press Overhead sentado agarre inverso con barra Z', 6, 2, 116, 1, 'Intermedio', 'Sentado con apoyo lumbar, realiza un press de hombros con agarre supino en barra Z, manteniendo los codos hacia adelante.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Seated Overhead Press Reverse Grip with Z Bar', 'Seated with lumbar support, perform a Z-bar supine grip shoulder press, keeping your elbows forward.', 'external'),
('b3fa7877-7540-4c22-9469-a3652178c611', 'Kettlebell Clean and Press', 6, 29, 281, 1, 'Intermedio', 'Lleva la pesa al hombro (clean) y luego elévala (press). Movimiento fluido. Espalda recta. No arquees la espalda al empujar.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Clean and Press', 'Bring the weight to your shoulder (clean) and then raise it (press). Fluid movement. Straight back. Don''t arch your back when pushing.', 'external'),
('b400cdb3-5123-4eae-852a-9968dbe90c73', 'Good morning con banda', 55, 71, 61, 1, 'Intermedio', 'Pisa la banda y coloca el otro extremo detrás del cuello sobre los trapecios. Con las rodillas ligeramente flexionadas, inclínate hacia adelante desde las caderas manteniendo la espalda recta. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales contra la resistencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Banded Good Morning', 'Step on the band and place the other end behind your neck across your traps. With your knees slightly bent, hinge forward at the hips while keeping your back straight. Return to the starting position by contracting your glutes and hamstrings against the band’s resistance.', 'external'),
('b434af88-04ff-4688-8bda-c7a79cd02cf5', 'Frog Pump con mancuerna', 29, NULL, 81, 1, 'Intermedio', 'En posición de mariposa tumbado (pies juntos), coloca una mancuerna sobre la pelvis y eleva las caderas activando los glúteos.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Frog Pump with Dumbbell', 'In a lying butterfly position (feet together), place a dumbbell over your pelvis and raise your hips, activating your glutes.', 'external'),
('b474e56f-abf3-44ce-8cf8-60bd5713e208', 'Single Leg Out Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Ejecuta un back lever con una pierna estirada y la otra encogida hacia el pecho, alternando para ganar fuerza simetrica.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Single Leg Out Back Lever on rings', 'Perform a back lever with one leg straight and the other drawn towards the chest, alternating to gain symmetrical strength.', 'bodyweight'),
('b47728ba-9026-46e4-a4a8-e4a704fbe955', 'Press de bandera frontal con maza', 6, 2, 81, 1, 'Intermedio', 'Sostén la maza verticalmente frente a ti y presiona hacia adelante extendiendo los brazos, resistiendo la palanca del peso.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Mace front flag press', 'Hold the club vertically in front of you and press forward by extending your arms, resisting the leverage of the weight.', 'external'),
('b47e4bb9-62f5-4796-a0c0-20dbdfca0139', 'Flexiones fitball', 1, 2, 290, 1, 'Intermedio', 'Flexiones con manos sobre la fitball o pies elevados en ella. La inestabilidad requiere mayor activación de estabilizadores. Con manos en la pelota trabajas más el core, con pies enfatizas pectoral superior. Controla el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Stability Ball Push-ups', 'Push-ups with hands on the stability ball or feet raised on it. Instability requires greater activation of stabilizers. With hands on the ball you work more on the core, with feet you emphasize the upper chest. control movement.', 'bodyweight'),
('b47f3ccd-569a-4df0-962d-ed0021e6e67a', 'Thruster Ciclista con barra', 28, 6, 116, 1, 'Intermedio', 'Con talones elevados, realiza una sentadilla profunda y aprovecha la subida explosiva para realizar un press militar sobre la cabeza en un solo movimiento.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Cyclist Barbell Thruster', 'With your heels elevated, perform a deep squat and use the explosive ascent to drive the bar overhead in one smooth motion.', 'external'),
('b4b11683-d20a-4f4a-8ed8-5468bc8c4f10', 'Press hombros TRX', 6, 2, 216, 1, 'Intermedio', 'En posición de pike (V invertida) con manos en las correas, realiza press verticales. Similar a flexiones pike pero con la inestabilidad añadida del TRX. Excelente para desarrollar fuerza en hombros y estabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Shoulder Press', 'In a pike position (inverted V) with hands on the straps, perform vertical presses. Similar to pike push-ups but with the added instability of the TRX. Excellent for developing shoulder strength and stability.', 'mixed'),
('b4be2f53-14fd-46ad-ad5d-e5c7a8bc70af', 'Sentadilla Pistola Front Rack con Kettlebell doble Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Sentadilla a una pierna con Kettlebells invertidas en rack frontal, requiriendo un control motor absoluto para evitar la caida del peso.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Front Rack Pistol Squat with Double kettlebell Bottoms Up', 'One-leg squat with inverted kettlebells in a front rack, requiring absolute motor control to avoid the weight falling.', 'external'),
('b4bfcd1f-732d-486a-b430-f88c5dfa9d6d', 'Sentadilla libre', 28, 29, 1, 1, 'Principiante', 'Coloca los pies al ancho de los hombros con las puntas ligeramente hacia afuera. Desciende flexionando rodillas y caderas simultáneamente, manteniendo la espalda recta y el pecho erguido. Baja hasta que los muslos estén paralelos al suelo o según tu flexibilidad. Empuja con los talones para volver a la posición inicial.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Free squat', 'Place your feet shoulder-width apart with your toes slightly outward. Descend by bending your knees and hips simultaneously, keeping your back straight and your chest up. Lower yourself until your thighs are parallel to the floor or depending on your flexibility. Push through your heels to return to the starting position.', 'mixed'),
('b4eaf17f-39c6-44d3-8a71-2ac8fb283c33', 'Curl martillo alterno', 17, 100, 81, 1, 'Principiante', 'Flexiona una mancuerna a la vez con agarre neutro (palmas enfrentadas). Objetivo: braquial y braquiorradial. Cue: mantén el codo fijo al costado. Error común: rotar la muñeca durante el movimiento.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Alternating Hammer Curl', 'Flex one dumbbell at a time with a neutral grip (palms facing each other). Target: brachialis and brachioradialis. Cue: keep your elbow fixed at your side. Common mistake: rotating the wrist during the movement.', 'external'),
('b5058ca6-f9cc-4f74-8f5f-9e9d2c7be060', 'TRX Aperturas de pecho', 1, 6, 216, 1, 'Avanzado', 'Inclinado hacia adelante, abre los brazos lateralmente con ligera flexión de codo y cierra. Control total. Cuerpo en bloque. No dejes caer la pelvis.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Chest Fly', 'Lean forward and open your arms out to the sides with a slight bend in the elbows, then bring them back together. Stay in full control, keep your body in one line, and do not let your hips drop.', 'bodyweight'),
('b512551f-c998-40fe-8889-617b4f582f64', 'Curl de bíceps sentado con cable', 17, NULL, 151, 1, 'Principiante', 'Siéntate frente a una polea baja con una barra corta. Apoya los codos en las rodillas o mantenlos fijos a los lados y realiza el curl.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Cable Seated Biceps Curl', 'Sit facing a low cable with a short bar. Rest your elbows on your knees or keep them fixed at your sides and perform the curl.', 'external'),
('b525fca2-0d56-4363-acf9-25dc79eea17b', 'TRX Y-Fly', 71, 6, 216, 1, 'Intermedio', 'Eleva brazos en Y inclinado atrás. Objetivo: deltoide posterior. Cues: brazos rectos. Error común: encoger hombros.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'TRX Y Fly', 'Raise your arms into a Y shape while leaning back. Target: rear delts. Cue: keep your arms straight. Common mistake: shrugging your shoulders.', 'bodyweight'),
('b568d66b-b81d-46bb-a191-dfd7b7d2c5a0', 'Jump squat TRX', 28, 29, 216, 1, 'Intermedio', 'Sujetando las correas, realiza sentadillas con salto. El TRX proporciona estabilidad y permite ajustar la intensidad del salto. Aterriza suavemente y usa las correas para mantener el equilibrio y la postura correcta.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Jump squat TRX', 'Holding the straps, perform jump squats. The TRX provides stability and allows you to adjust the intensity of the jump. Land softly and use the straps to maintain balance and correct posture.', 'mixed'),
('b5b99869-3db7-45da-a522-11360e11ac10', 'Curl de bíceps offset agarre inverso con maza', 100, 17, 81, 1, 'Principiante', 'Sujeta la maza con las palmas hacia abajo de forma asimétrica y realiza el curl para trabajar antebrazos y bíceps.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Reverse Grip Offset Biceps Curl with Mace', 'Hold the club with your palms facing down asymmetrically and perform the curl to work your forearms and biceps.', 'external'),
('b5c9b192-96f8-48e2-93d8-81015276d04b', 'Pallof press', 25, 6, 151, 1, 'Intermedio', 'Realiza un Pallof press con cable o banda. Desde una posición lateral al punto de anclaje, empuja las manos al frente y resiste la rotación del tronco durante todo el movimiento.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Pallof Press', 'Perform a Pallof press with a cable or band. From a sideways position to the anchor point, press the hands forward and resist trunk rotation throughout the movement.', 'external'),
('b5d2f448-a0c9-4ae2-8c3e-4c17a07df9f3', 'Battle Ropes Ondas en plancha lateral', 25, 6, 256, 24, 'Avanzado', 'En plancha lateral, mueve la cuerda con la mano libre. Estabilidad de core extrema. Cuerpo recto. No dejes caer la cadera al suelo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Battle Ropes Side Plank Waves', 'In side plank, move the rope with your free hand. Extreme core stability. Straight body. Don''t let your hips fall to the ground.', 'external'),
('b5d92170-717d-4f51-8e87-c2d807b1475e', 'High Pull con Kettlebell doble', 6, 71, 281, 1, 'Intermedio', 'Desde el suelo, tira de dos Kettlebells hacia arriba mediante una extension explosiva de cadera hasta que los codos queden altos.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double Kettlebell High Pull', 'From the floor, pull two kettlebells upward using an explosive hip extension until your elbows are high.', 'external'),
('b5ea9a9a-bf43-4fc8-8fab-89da72b05b03', 'Curl bíceps TRX', 17, NULL, 216, 1, 'Intermedio', 'Inclinado hacia atrás con brazos extendidos, realiza curls llevando las manos hacia la frente. Mantén los codos elevados y fijos. La inestabilidad del TRX añade un componente de estabilización al ejercicio tradicional.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Biceps Curl', 'Leaning back with arms extended, perform curls, bringing your hands toward your forehead. Keep your elbows raised and fixed. The instability of the TRX adds a stabilization component to traditional exercise.', 'bodyweight'),
('b6166551-06ac-446d-9260-fd85383071ed', 'Wall sit', 28, 29, 1, 24, 'Principiante', 'Apoya la espalda contra una pared y deslízate hacia abajo hasta que los muslos estén paralelos al suelo, formando un ángulo de 90 grados en las rodillas. Mantén esta posición isométrica con el peso en los talones. Los brazos pueden estar cruzados o extendidos al frente. Excelente para resistencia muscular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Wall Sit', 'Stand with your back against a wall and slide down until your thighs are parallel to the floor, forming 90-degree angles at the knees. Hold this isometric position with your weight in your heels. Your arms can be crossed or extended in front. Excellent for muscular endurance.', 'bodyweight'),
('b622b2b3-3b5b-4885-ba3c-040d42260024', 'Power Snatch con barra', 13, 6, 116, 1, 'Avanzado', 'Lleva la barra desde el suelo hasta por encima de la cabeza con brazos extendidos en un solo movimiento explosivo, recibiéndola en media sentadilla.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Power Snatch with bar', 'Bring the bar from the floor to overhead with extended arms in a single explosive movement, receiving it in a half squat.', 'external'),
('b62c171d-11bb-47c1-80b2-c2a51c1d133c', 'Remo inclinado a una mano con Kettlebell', 71, 17, 281, 1, 'Intermedio', 'Apoya una mano y rodilla en un banco. Con la espalda plana, rema la pesa rusa hacia la cadera manteniendo el codo cerca del cuerpo.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-Handed kettlebell Bent-Over Row', 'Place one hand and knee on a bench. With a flat back, row the kettlebell toward your hips, keeping your elbow close to your body.', 'external'),
('b6398c46-1c48-43c8-b05a-c10102289bce', 'Push Up en plancha completa en paralelas', 1, 6, 1, 1, 'Avanzado', 'Realiza una flexion de brazos manteniendo el cuerpo totalmente horizontal y paralelo al suelo, apoyado solo en las manos.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Push Up in full plank in parallel', 'Perform a push-up keeping your body completely horizontal and parallel to the ground, supported only by your hands.', 'mixed'),
('b657da31-e10a-42e9-bce9-245317b6f8da', 'Cruces superiores cable', 1, NULL, 151, 1, 'Intermedio', 'Con las poleas en posición alta, realiza el cruce llevando las manos hacia abajo y al centro. Esta variación enfatiza la porción inferior del pectoral. Mantén el torso ligeramente inclinado hacia adelante para mejor estabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Top Crossovers', 'With the cables in a high position, perform the crossover by bringing your hands down and to the center. This variation emphasizes the lower portion of the pectoral. Keep your torso slightly tilted forward for better stability.', 'external'),
('b65ec17c-8df4-4eaf-83f2-8df6e4b6106a', 'Flutter Kicks', 25, 28, 1, 24, 'Principiante', 'Pequeños movimientos arriba y abajo de piernas a pocos cm del suelo. Cue: manos bajo el glúteo para apoyo. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Flutter Kicks', 'Small movements up and down the legs a few cm from the ground. Cue: hands under the glute for support. Common mistake: arching your lower back.', 'bodyweight'),
('b692df19-5525-4d64-9abf-4c668d3ed302', 'Saltos laterales (Lateral bounds)', 29, 37, 1, 1, 'Avanzado', 'Salta lateralmente de una pierna a la otra buscando máxima distancia y estabilidad. Objetivo: potencia lateral. Cue: clava el aterrizaje con la rodilla alineada. Error común: dejar que la rodilla se hunda hacia adentro.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Side Jumps (side Bounds)', 'Jump laterally from one leg to the other seeking maximum distance and stability. Target: lateral power. Cue: stick the landing with your knee aligned. Common mistake: letting the knee withoutk inward.', 'bodyweight'),
('b6c82820-f0df-42f9-9634-8b5c0dbfba2a', 'Press Sots con Kettlebell a una mano', 6, 2, 281, 1, 'Intermedio', 'Realiza un press de hombros completo mientras te mantienes en la posicion mas profunda de una sentadilla, exigiendo movilidad extrema.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'One-Handed kettlebell Press Sots', 'Perform a full shoulder press while staying in the deepest position of a squat, demanding extreme mobility.', 'external'),
('b6e615a4-af8d-43af-b15b-c278c3d65a38', 'Caminata de oso estricta', 13, 6, 1, 24, 'Intermedio', 'Desplázate a cuatro patas con las rodillas a milímetros del suelo. Objetivo: estabilidad total del core. Cue: espalda plana como una mesa. Error común: elevar la cadera hacia arriba.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Strict Bear Walk', 'Move on all fours with your knees millimeters off the ground. Target: total core stability. Cue: flat back like a table. Common mistake: raising your hips upward.', 'bodyweight'),
('b70bc7cb-e725-44bf-8ce7-0a0c7ba28ef1', 'Peso muerto Sumo con Kettlebell', 71, 29, 281, 1, 'Principiante', 'Con una apertura de pies ancha, sujeta la Kettlebell con ambas manos y levántala extendiendo cadera y rodillas con la espalda neutra.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Sumo Deadlift with Kettlebell', 'With your feet wide, hold the kettlebell with both hands and lift it by extending your hips and knees with a neutral back.', 'external'),
('b728b144-8a3b-41d2-b39b-493b1a2ff46f', 'Press hombros con banda pisada', 6, 2, 61, 1, 'Principiante', 'Empuja la banda sobre la cabeza. Cue: brazos totalmente estirados. Error: arquear la espalda.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Shoulder Press with Tread Band', 'Push the band over your head. Cue: arms fully stretched. Common mistake: arching your back.', 'external'),
('b782aed9-e0c6-446d-a203-4df54c19addc', 'Peso muerto desde bloques bajos', 71, 55, 116, 1, 'Intermedio', 'Barra elevada 10-15cm del suelo. Enfoca en la fase media del tirón. Cue: espalda neutra. Error: redondear la espalda alta.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Deadlift From Low Blocks', 'Bar raised 10-15cm from the ground. Focus on the middle phase of the pull. Cue: neutral back. Common mistake: rounding the upper back.', 'external'),
('b786aa4f-e65e-4c83-a038-cf53174b3606', 'Burpee golpeo balón medicinal', 13, NULL, 240, 1, 'Avanzado', 'Burpee completo finalizando con slam ball. Uno de los ejercicios más demandantes metabólicamente. Mantén la técnica a pesar de la fatiga. El slam debe ser explosivo incluso cuando estés cansado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Burpee medicine ball slam', 'Complete burpee ending with slam ball. One of the most metabolically demanding exercises. Maintain technique despite fatigue. The slam should be explosive even when you are tired.', 'external'),
('b7992707-04da-4663-9b3c-34b85dd81097', 'Press California', 2, 1, 116, 1, 'Avanzado', 'Inicia como un press francés pero permite que la barra se desplace hacia la parte inferior del pecho al subir, convirtiéndose en un press de banca estrecho. Objetivo: sobrecarga de tríceps. Cues: controla el descenso hacia la frente y explota al subir. Error común: usar excesivo impulso de hombros.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Press California', 'It starts as a French press but allows the bar to move toward the lower chest as it rises, becoming a narrow bench press. Objective: triceps overload. Cues: controls the descent towards the forehead and explodes when rising. Common mistake: using excessive shoulder thrust.', 'external'),
('b79f1028-e31d-4a0a-aa9f-2564d20edf4f', 'Lanzamiento lateral rebote', 25, 6, 240, 1, 'Intermedio', 'Lanza el balón al suelo lateralmente y recógelo rápidamente al rebotar. Potencia de core. Cue: usa el golpe de cadera. Error común: encorvar la espalda al recibir el balón.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side Bounce Throw', 'Throw the ball to the ground laterally and quickly catch it as it bounces. core power. Cue: use the hip snap. Common mistake: hunching your back when receiving the ball.', 'external'),
('b826fdb7-c753-424b-9eff-0df1491fb3eb', 'Arrancada con mancuerna (Snatch)', 13, 6, 81, 1, 'Intermedio', 'De un tirón desde el suelo lleva la mancuerna sobre la cabeza. Cue: mantén la pesa cerca del cuerpo. Error: arquear la espalda al inicio.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dumbbell Snatch', 'With one pull from the floor, bring the dumbbell over your head. Cue: keep the weight close to the body. Common mistake: arching your back at the beginning.', 'external'),
('b885162e-0e50-4141-bccf-8849a2dcad00', 'Push Press alterno con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Utiliza un ligero impulso de las piernas para ayudar a presionar las pesas rusas alternativamente sobre la cabeza, manteniendo el control en la bajada.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Double kettlebell Alternating Push Press', 'Use a slight push from your legs to help press the kettlebells alternately overhead, maintaining control on the way down.', 'external'),
('b8a0be53-3432-4d93-980b-dd5d2836e8f1', 'Battle ropes squat', 28, 6, 256, 24, 'Intermedio', 'Mantén las ondas mientras realizas sentadillas. Puedes hacer sentadillas estáticas manteniendo la posición o dinámicas. La combinación aumenta significativamente la demanda metabólica. Mantén la técnica en ambos movimientos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle rope squat', 'Hold the waves while performing squats. You can do static squats while maintaining the position or dynamic squats. The combination significantly increases metabolic demand. Maintain technique in both movements.', 'external'),
('b8ab3461-8c39-45a5-8082-b0230ed4ab26', 'Snatch con Kettlebell doble', 29, 6, 281, 1, 'Avanzado', 'Eleva dos Kettlebells desde entre las piernas hasta por encima de la cabeza en un solo arco continuo y explosivo.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double kettlebell Snatch', 'Raise two kettlebells from between your legs to overhead in a single continuous, explosive arc.', 'external'),
('b8b0a653-ada9-455a-af3e-d58689f04d75', 'Single leg glute bridge', 29, NULL, 1, 1, 'Intermedio', 'Desde la posición de puente glúteo, extiende una pierna manteniéndola alineada con el muslo de la pierna de apoyo. Eleva las caderas usando solo una pierna, manteniendo la pelvis nivelada. Este ejercicio unilateral aumenta significativamente la intensidad y mejora el equilibrio muscular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single leg glute bridge', 'From the glute bridge position, extend one leg keeping it aligned with the thigh of the supporting leg. Raise your hips using only one leg, keeping your pelvis level. This unilateral exercise significantly increases intensity and improves muscle balance.', 'mixed'),
('b8de6335-0aee-4886-8248-570eb6ca45eb', 'Curl concentrado sentado', 17, NULL, 81, 1, 'Principiante', 'Sentado, apoya el codo contra el interior del muslo y flexiona la mancuerna. Objetivo: pico del bíceps. Cue: controla el descenso del peso. Error común: balancear el hombro para facilitar la flexión.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Seated Concentrated Curl', 'Sitting, rest your elbow against the inside of your thigh and flex the dumbbell. Target: peak of the biceps. Cue: controls the decrease in weight. Common mistake: rocking the shoulder to facilitate flexion.', 'external'),
('b913b3db-3196-4579-9d12-42a137e214b3', 'Caminata de granjero con mancuernas (Farmers Walk)', 100, 13, 81, 1, 'Principiante', 'Camina sosteniendo una mancuerna pesada en cada mano a los costados. Mantén la espalda recta, hombros atrás y core tenso.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Farmers Walk with Dumbbells', 'Walk holding a heavy dumbbell in each hand at your sides. Keep your back straight, shoulders back and core tight.', 'external'),
('b9223791-877a-41db-89ac-fd4ec765d399', 'Golpeo explosivo balón medicinal', 25, 6, 240, 1, 'Avanzado', 'Slam ball con máxima velocidad y potencia. Eleva el balón completamente sobre la cabeza con extensión total del cuerpo. Golpea con toda la fuerza usando core y brazos. Recoge inmediatamente y repite sin pausa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Explosive medicine ball hit', 'Slam ball with maximum speed and power. Raise the ball completely over your head with full body extension. Hit with full force using core and arms. Pick up immediately and repeat without pause.', 'external'),
('b93c2d1d-8623-4cfe-8d25-70f865ed94bc', 'Patada glúteo lateral polea estribo', 37, 29, 151, 1, 'Principiante', 'Aleja pierna lateral en polea. Cue: cuerpo erguido. Error: usar impulso.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Stirrup Cable Side Gluteal Kick', 'Move lateral leg out in cable. Cue: body upright. Common mistake: use boost.', 'external'),
('b94ff634-f0cf-4254-b943-9549e25174f3', 'Sentadilla overhead estricta', 13, 6, 116, 1, 'Avanzado', 'Sentadilla con barra bloqueada sobre la cabeza. Movilidad máxima. Cue: empuja la barra al techo. Error: brazos flojos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Overhead Squat', 'Locked overhead barbell squat. Maximum mobility. Cue: push the bar to the ceiling. Common mistake: loose arms.', 'external'),
('b953c811-a6f3-4081-853d-6638dbaf5677', 'Zancada lateral con mancuerna', 29, 313, 81, 1, 'Principiante', 'Sujeta la pesa estilo goblet y desplázate lateralmente. Cue: cadera atrás al bajar. Error: rodilla sobrepasa excesivamente el pie.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dumbbell Side Stride', 'Hold the goblet-style weight and move sideways. Cue: hip back when going down. Common mistake: knee excessively exceeds the foot.', 'external'),
('b9beeb5b-8ce0-441f-813c-c3b7b8ebb0be', 'Dragon Flag', 25, 71, 1, 1, 'Avanzado', 'Tumbado, agarra un punto fijo tras la cabeza y eleva todo el cuerpo apoyado solo en hombros. Cue: cuerpo rígido. Error: doblar la cadera durante el movimiento.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Dragon Flag', 'Lying down, grab a fixed point behind your head and raise your entire body, supported only by your shoulders. Cue: rigid body. Common mistake: bending the hips during the movement.', 'bodyweight'),
('ba023b53-2606-496e-96d1-23d742a7c89c', 'Zancada pliométrica con banda', 28, NULL, 61, 1, 'Intermedio', 'Zancadas con salto resistidas por una banda elástica anclada al suelo o cintura. Potencia resistida. Cue: espalda neutra a pesar del tirón. Error común: perder la alineación de la rodilla delantera.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Stride with Band', 'Jump strides resisted by an elastic band anchored to the floor or waist. Power withstood. Cue: neutral back despite the pull. Common mistake: losing Front Knee Alignment.', 'external'),
('ba0b94eb-02f2-4c47-a837-195df129abfb', 'Sentadilla zercher', 28, 25, 116, 1, 'Avanzado', 'Sentadilla sosteniendo la barra en el pliegue de los codos. Posición incómoda pero efectiva. Gran activación del core y postura más vertical. Usa almohadilla o toalla. Nombrada por Ed Zercher.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Zercher squat', 'Squat holding the bar in the bend of the elbows. Uncomfortable but effective position. Great core activation and more upright posture. Use a pad or towel. Named by Ed Zercher.', 'external'),
('ba4034b9-6fbb-4962-8faa-0c15c18734d4', 'Rodamiento con banda', 25, NULL, 271, 1, 'Avanzado', 'Roll out con banda elástica anclada detrás proporcionando resistencia adicional. La banda hace más difícil la extensión y puede asistir o resistir el retorno. Permite sobrecarga progresiva del ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bearing with band', 'Roll out with elastic band anchored behind providing additional resistance. The band makes extension more difficult and can assist or resist return. Allows progressive exercise overload.', 'external'),
('ba4919d0-3b4a-4b8a-9a43-ef08afeb7e51', 'Zancada pliométrica rápida', 28, 64, 1, 1, 'Avanzado', 'Zancadas con salto buscando la máxima velocidad de cambio de piernas, no altura. Cue: pies rápidos. Error común: falta de rango en la zancada.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Fast Plyometric Stride', 'Jumping strides looking for maximum leg-changing speed, not height. Cue: fast feet. Common error: Lack of range in stride.', 'bodyweight'),
('ba6107c6-1ae0-4232-97df-7fade6f5101f', 'Extensión tríceps kettlebell nuca', 2, NULL, 281, 1, 'Principiante', 'Baja pesa rusa tras cabeza. Objetivo: tríceps. Cue: codos cerrados. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Kettlebell Neck Triceps Extension', 'Lower the kettlebell behind your head. Target: triceps. Cue: keep your elbows close in. Common mistake: arching your lower back.', 'external'),
('ba62b473-3524-4eec-a4d0-b8c06110a339', 'Rotary torso máquina', 25, NULL, 186, 1, 'Principiante', 'Sentado con el torso fijo, rota la parte inferior del cuerpo o viceversa según el diseño. Trabaja los oblicuos de forma controlada. Evita usar impulso y mantén el movimiento suave y controlado en ambas direcciones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rotary Torso Machine', 'Sitting with your torso fixed, rotate your lower body or vice versa depending on the design. Work the obliques in a controlled way. Avoid using momentum and keep the movement smooth and controlled in both directions.', 'external'),
('ba648d11-3cf0-47ae-b419-287be9518a7b', 'Superman brazos cruz', 71, 29, 1, 1, 'Principiante', 'Eleva pecho/piernas brazos lados. Objetivo: espalda/lumbar. Cue: mira suelo. Error: cuello atrás.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Superman Arms Crossed', 'Lift your chest and legs off the floor with your arms out to the sides. Target: back and lower back. Cue: look toward the floor. Common mistake: throwing your neck back.', 'bodyweight'),
('ba65bbf0-2d16-4b8a-8f6e-7572e1a19fff', 'Step Up Front Rack con Kettlebell doble Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Sube al banco con dos Kettlebells invertidas en posición rack, lo que requiere un control excepcional del agarre y la estabilidad.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double Kettlebell Bottoms-Up Front Rack Step-up', 'Step onto the bench with two upside-down kettlebells in the front rack position, demanding exceptional grip control and upper-body stability.', 'external'),
('ba6e2736-bab8-416d-8569-78cc1d71959d', 'Extensión tríceps mancuernas', 2, NULL, 81, 1, 'Principiante', 'Sentado o de pie, sujeta una mancuerna con ambas manos sobre la cabeza. Desciende la mancuerna por detrás de la cabeza flexionando los codos, manteniendo los brazos superiores inmóviles. Extiende hasta la posición inicial contrayendo los tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell triceps extension', 'Sitting or standing, hold a dumbbell with both hands above your head. Lower the dumbbell behind your head by bending your elbows, keeping your upper arms motionless. Extend to the starting position by contracting the triceps.', 'external'),
('baa9d468-4730-450a-baa0-cb7b1c396a40', 'Press pecho TRX', 1, 6, 216, 1, 'Intermedio', 'De pie inclinado hacia adelante con las manos en las correas, realiza un movimiento de press. Cuanto más inclinado estés, mayor será la dificultad. La inestabilidad del TRX aumenta la activación muscular estabilizadora.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX chest press', 'Standing leaning forward with your hands on the straps, perform a pressing movement. The more inclined you are, the greater the difficulty. TRX instability increases stabilizing muscle activation.', 'bodyweight'),
('baea5396-0244-4229-81ef-0ad6e8d3c98b', 'Elevaciones frontales con banda', 6, NULL, 61, 1, 'Principiante', 'Pisa la banda y sujeta los extremos frente a los muslos. Eleva los brazos al frente hasta la altura de los hombros manteniendo los brazos rectos o con ligera flexión. Desciende controladamente. Trabaja principalmente el deltoides anterior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Band Front Raises', 'Step on the band and hold the ends in front of your thighs. Raise your arms in front of you to shoulder height, keeping your arms straight or slightly bent. Controlled descent. It mainly works the anterior deltoid.', 'external'),
('baec9299-6704-41cb-9d8b-8101ee9f3f62', 'Turkish Sit Up con barra a una mano', 25, 6, 116, 1, 'Avanzado', 'Realiza un sit up con una barra bloqueada en una mano, desafiando el equilibrio y la fuerza de agarre de forma extrema.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Single-Arm Barbell Turkish Sit-Up', 'Perform a sit-up while keeping a barbell locked out in one hand, creating an extreme balance and grip-strength challenge.', 'external'),
('bb1ea030-6410-49ee-ba84-73585cafb9de', 'Floor Press con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado en el suelo, presiona dos Kettlebells invertidas (fondo arriba), lo que requiere una enorme fuerza de agarre y estabilidad de hombros.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Floor Press with Double Kettlebell Bottoms Up', 'Lying on the floor, press two inverted kettlebells (bottom up), which requires enormous grip strength and shoulder stability.', 'external'),
('bb69636d-acb1-4422-b6c2-c24b128e708b', 'Curl de bíceps agarre inverso en TRX', 17, 100, 216, 1, 'Principiante', 'Sujeta el TRX con las palmas hacia abajo. Inclina el cuerpo y realiza un curl flexionando los codos hacia tu frente, trabajando bíceps y antebrazo.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Reverse Grip Biceps Curl on TRX', 'Hold the TRX with your palms facing down. Tilt your body and perform a curl by bending your elbows towards your forehead, working your biceps and forearm.', 'bodyweight'),
('bb8de0b1-931a-487f-a779-55f358b785cf', 'Jalón al pecho agarre supino', 16, 17, 186, 1, 'Principiante', 'Tira barra palmas hacia ti. Objetivo: dorsales y bíceps. Cues: codos hacia abajo. Error común: balancear el torso.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Supine Grip Chest Pull', 'Throw bar claps towards you. Target: lats and biceps. Cue: elbows down. Common mistake: swinging your torso.', 'external'),
('bb97632b-efe1-470d-afa6-5ab9fbcbeefa', 'Press banca agarre ancho', 1, 6, 116, 1, 'Intermedio', 'Press banca manos muy separadas. Objetivo: pecho externo. Cue: codos fuera. Error: falta control.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Wide Grip Bench Press', 'Bench press hands wide apart. Target: external chest. Cue: elbows out. Common mistake: lack of control.', 'external'),
('bbbb258e-2b06-4725-a35c-41202aa7db3f', 'Press banca mancuernas', 1, 2, 81, 1, 'Intermedio', 'Túmbate en un banco plano con una mancuerna en cada mano a los lados del pecho. Presiona las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Desciende controladamente llevando los codos ligeramente hacia afuera. Permite mayor rango de movimiento que la barra.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell bench press', 'Lie on a flat bench with a dumbbell in each hand on the sides of your chest. Press the dumbbells up until your arms are fully extended. Descend controlledly, bringing your elbows slightly outward. Allows greater range of motion than the bar.', 'external'),
('bbbe02f3-527e-4901-80eb-694994c8b216', 'Triple salto desde parado', 29, 28, 1, 1, 'Avanzado', 'Realiza tres saltos largos consecutivos sin detenerte. Maximiza la elasticidad muscular. Cue: usa los brazos rítmicamente. Error común: frenar la inercia entre el segundo y tercer salto.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Standing Triple Jump', 'Perform three consecutive broad jumps without stopping. Maximize elastic rebound. Cue: use your arms rhythmically. Common mistake: losing momentum between the second and third jump.', 'bodyweight'),
('bc50fbbb-74a4-42d6-a1d4-f41c0602f6b8', 'Press de hombros rotacional alterno con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Presiona las pesas rusas alternativamente sobre la cabeza mientras rotas el torso y pivoteas sobre el pie del lado que empuja para un movimiento dinámico.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Double kettlebell Alternating Rotational Shoulder Press', 'Press the kettlebells alternately overhead while rotating your torso and pivoting on the foot on the pushing side for a dynamic movement.', 'external'),
('bc7cd25c-bbba-47b4-88d0-e5d8e8c81197', 'Face pull sentado polea alta espalda', 6, 71, 151, 1, 'Principiante', 'Tira cuerda a cara sentado. Cue: pulgares atrás. Error: adelantar cabeza.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Face Pull Seated High Back Cable', 'Pull rope to face seated. Cue: thumbs back. Common mistake: forward head.', 'external'),
('bc9468f9-e95b-4c75-ba50-2fa18493dff2', 'Single leg deadlift', 55, 29, 1, 1, 'Intermedio', 'De pie sobre una pierna, inclínate hacia adelante desde las caderas mientras extiendes la pierna libre hacia atrás, manteniendo ambas lo más rectas posible. Desciende hasta que el torso esté paralelo al suelo. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales. Mantén las caderas cuadradas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Leg Deadlift', 'Stand on one leg and hinge forward from the hips while extending the free leg behind you, keeping both legs as straight as possible. Lower until your torso is parallel to the floor, then return to the starting position by contracting your glutes and hamstrings. Keep your hips square.', 'bodyweight'),
('bcbd047c-2e6a-4c34-8043-30d159680a34', 'Aperturas con mancuernas en suelo', 1, 2, 81, 1, 'Principiante', 'Tumbado en el suelo, realiza press de pecho. El suelo limita el rango protegiendo el hombro. Codos tocan suelo suave. No rebotes.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Dumbbell flyes on the floor', 'Lie on the floor and perform a dumbbell fly with a limited range of motion. The floor protects the shoulders by stopping the descent. Lower under control and avoid bouncing your elbows off the floor.', 'external'),
('bcc0c83a-c086-46fc-9320-cb4be8a162af', 'Step-down', 28, 29, 1, 1, 'Intermedio', 'Step-down controlado seguido de aceleración corta para estabilidad unilateral y transferencia a carrera/sprint.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Step-down', 'Controlled step-down followed by a short acceleration drill to build unilateral stability and transfer to running or sprinting.', 'bodyweight'),
('bd06a08a-bfbd-4f62-9bcb-a975a43a1250', 'Split Jerk con Kettlebell a una mano', 6, 28, 281, 1, 'Intermedio', 'Lanza la pesa sobre la cabeza mediante un impulso explosivo de piernas y recibela en posicion de zancada dividida (split).', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Split Jerk with One-Handed kettlebell', 'Throw the weight overhead using an explosive leg drive and receive it in a split lunge position.', 'external'),
('bd18829a-db12-4927-9d13-a51cae65666c', 'Sentadilla Overhead en equilibrio sobre dedos a una mano', 28, 64, 116, 1, 'Avanzado', 'Sentadilla profunda sobre las puntas de los pies manteniendo una barra bloqueada sobre la cabeza con un solo brazo, un reto extremo de movilidad.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Overhead squat balanced on fingers on one hand', 'Deep squat on the balls of your feet while keeping a barbell locked overhead with one arm, an extreme mobility challenge.', 'external'),
('bd58fe26-177c-41d6-9a0b-720f1e8aa837', 'Handstand Push Up', 6, 2, 1, 1, 'Avanzado', 'Desde la posición vertical de parada de manos, flexiona los brazos para bajar el cuerpo y extiende con fuerza para volver arriba sin apoyo externo.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Handstand Push Up', 'From the upright handstand position, flex your arms to lower your body and extend strongly to return up without external support.', 'mixed'),
('bd5a9a94-6653-46d0-9efb-8dbda494e83d', 'Elevaciones laterales por detrás en cable', 6, NULL, 151, 1, 'Intermedio', 'Eleva el cable lateralmente con el brazo pasando por detrás del cuerpo. Objetivo: mayor tensión en el estiramiento del hombro. Cue: controla la bajada. Error común: usar excesivo impulso del tronco.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Side Raises From Behind on Cable', 'Raise the cable laterally with your arm passing behind your body. Objective: increased tension in the shoulder stretch. Cue: controls the descent. Common mistake: using excessive torso momentum.', 'external'),
('bd668150-c4d6-4f0f-a563-dfc698a6ac63', 'Frog Pump con Miniband', 29, NULL, 61, 1, 'Principiante', 'Con una banda sobre las rodillas y plantas de los pies juntas, eleva la cadera apretando los gluteos con fuerza.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Frog Pump with Mini Band', 'With a band on your knees and soles of your feet together, raise your hips by squeezing your buttocks tightly.', 'external'),
('bd698c53-cc9d-40bc-bac6-b9fcf6ffb4a8', 'Curl bíceps barra', 17, NULL, 116, 1, 'Principiante', 'De pie con la barra agarrada con las palmas hacia arriba al ancho de los hombros, flexiona los codos llevando la barra hacia los hombros. Mantén los codos fijos a los costados y evita balancear el cuerpo. Controla especialmente la fase excéntrica del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar bicep curl', 'Standing with the bar gripped with your palms facing up shoulder-width apart, bend your elbows bringing the bar toward your shoulders. Keep your elbows fixed to your sides and avoid rocking your body. It especially controls the eccentric phase of the movement.', 'external');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('bd8b1d39-7219-43ac-8be1-3d79bf42aaf6', 'Sentadilla frontal con mancuernas (Front Rack)', 28, 29, 81, 1, 'Principiante', 'Realiza una sentadilla profunda sosteniendo dos mancuernas sobre tus hombros, manteniendo los codos en alto y la espalda neutra.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Front squat with dumbbells (Front Rack)', 'Perform a deep squat holding two dumbbells over your shoulders, keeping your elbows high and your back neutral.', 'external'),
('bdd80b37-db95-4af8-a6cb-15b4fa60dde1', 'Battle ropes power slam', 6, 25, 256, 24, 'Intermedio', 'Slams con máxima potencia elevando las cuerdas lo más alto posible. Involucra todo el cuerpo en cada repetición. Usa las piernas para generar impulso desde abajo. Mantén un ritmo explosivo constante.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Power Slams', 'Slams with maximum power raising the ropes as high as possible. Involve your entire body in each repetition. Use your legs to generate momentum from below. Maintain a constant explosive rhythm.', 'external'),
('bdf56f04-4970-4ef2-b213-568c26ae1260', 'Plancha en anillas a una mano', 25, 6, 1, 24, 'Avanzado', 'Mantén la posicion de plancha apoyado en una sola anilla, lo que requiere una enorme fuerza de core y estabilidad de hombro.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Single-Arm Plank on Rings', 'Hold a plank position while supported on a single ring, which requires exceptional core strength and shoulder stability.', 'bodyweight'),
('bdf9c1b4-a14e-4cfd-b997-eac4a80fef6e', 'Pájaros polea alta Cross-over posterior', 6, 71, 151, 1, 'Intermedio', 'Cruza cables desde arriba atrás. Cue: aprieta deltoide posterior. Error: encoger hombros.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Birds High Pulley Rear Cross-over', 'Cross cables from top to back. Cue: rear deltoid squeeze. Common mistake: shrugging your shoulders.', 'external'),
('be2e088a-0ad4-4ac9-a5a5-e1d353c95508', 'Sprinter start TRX', 28, 29, 216, 1, 'Intermedio', 'Simula la posición de salida de un velocista con una pierna adelante y otra atrás en la correa. Alterna explosivamente las piernas. Desarrolla potencia unilateral y mejora la coordinación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Sprinter start TRX', 'Simulates the starting position of a sprinter with one leg forward and one leg back on the strap. Explosively alternate your legs. Develops unilateral power and improves coordination.', 'bodyweight'),
('be4a99a8-f772-47b1-bb03-d47dc6a826c4', 'Salto pogo a una pierna', 64, 29, 1, 1, 'Avanzado', 'Rebotes rápidos sobre un solo pie buscando mínima estancia en el suelo. Mejora la estabilidad del tobillo y la potencia reactiva unilateral. Cue: mantén la rodilla casi bloqueada, empuja con el antepié. Error común: dejar que el talón colapse contra el suelo.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'One Leg Pogo Jump', 'Quick rebounds on one foot seeking a minimum stay on the ground. Improves ankle stability and unilateral reactive power. Cue: keep knee almost locked, push off with forefoot. Common mistake: letting the heel collapse toward the floor.', 'bodyweight'),
('be5577b8-d3ef-4904-81b0-1075869cf147', 'Dead Hang a Front Lever Pull Up en anillas', 71, 17, 1, 1, 'Avanzado', 'Colgado de las anillas, tira del cuerpo hasta posicion de Front Lever y realiza una dominada manteniendo el cuerpo paralelo al suelo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Dead Hang a Front Lever Pull Up on rings', 'Hanging from the rings, pull your body to a Front Lever position and perform a pull-up keeping your body parallel to the ground.', 'mixed'),
('be6bb02b-7900-4d3f-a753-6b673bc73fdf', 'Clean a Press Overhead con Kettlebell a una mano', 6, 2, 281, 1, 'Intermedio', 'Realiza un clean para llevar la pesa al hombro y, sin pausa, presiónala verticalmente hasta estirar el brazo por completo.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Clean a Press Overhead with One-Handed Kettlebell', 'Perform a clean to bring the weight to your shoulder and, without pausing, press it vertically until your arm is completely stretched.', 'external'),
('bead711b-684c-40a7-b0af-06d988047bdc', 'Puente glúteo mancuerna pelvis', 29, 55, 81, 1, 'Principiante', 'Eleva cadera con pesa en pelvis. Cue: aprieta arriba 2s. Error: arquear lumbar.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Gluteal Dumbbell Pelvis Bridge', 'Raise hips with a weight in the pelvis. Cue: press up 2s. Common mistake: arching your lower back.', 'external'),
('beaf2a73-3e10-4144-9d85-d39a9aec4fee', 'Curl femoral pie unilateral', 55, 29, 186, 1, 'Principiante', 'Flexiona pierna en máquina vertical. Objetivo: isquios aislados. Cue: muslo pegado. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Single-Leg Standing Leg Curl', 'Curl one leg on the standing machine. Target: isolated hamstrings. Cue: keep your thigh fixed. Common mistake: arching your lower back.', 'external'),
('bed5aff6-9774-46f3-ac68-4f524abead2c', 'Contractor pectorales máquina', 1, NULL, 186, 1, 'Principiante', 'Sentado con los brazos abiertos, junta los brazos o almohadillas frente al pecho. También conocido como pec deck. Proporciona aislamiento efectivo del pectoral. Mantén los codos ligeramente flexionados y controla el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pectoral Contractor Machine', 'Sitting with your arms open, bring your arms or pads together in front of your chest. Also known as pec deck. Provides effective isolation of the pectoral. Keep your elbows slightly bent and control the movement.', 'external'),
('bed878f2-10b8-46e7-bb60-783db8629cde', 'Avión de cadera asistido en pared', 29, 37, 1, 1, 'Intermedio', 'Apoyado en la pared para equilibrio, inclina el torso a una pierna y rota la pelvis abriendo y cerrando la cadera sobre el femur de apoyo.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Wall Assisted Hip Plane', 'Leaning on the wall for balance, lean your torso on one leg and rotate your pelvis by opening and closing your hips on the supporting femur.', 'assisted'),
('bf0edc97-6dea-4c45-aba6-ee183178ff2d', 'Tactical Snatch con Kettlebell a una mano', 29, 6, 281, 1, 'Avanzado', 'Un snatch explosivo donde se intercambia la Kettlebell de mano entre las piernas durante la fase de descenso antes del siguiente balanceo.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Tactical Snatch with Kettlebell Single-arm', 'An explosive snatch in which the kettlebell is passed from one hand to the other between the legs during the descent before the next swing.', 'external'),
('bf2aa58d-2926-493a-ae1a-c3f9bd4452d4', 'Salto vertical alcance pared', 28, 6, 1, 1, 'Principiante', 'Salta intentando tocar el punto más alto posible en una pared. Motivación visual de altura. Cue: estira el brazo de alcance. Error común: aterrizar con los talones.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Wall Reach Vertical Jump', 'Jump trying to touch the highest possible point on a wall. Visual height motivation. Cue: stretch your reach arm. Common mistake: landing on your heels.', 'bodyweight'),
('bf525e5d-cf73-4cd8-a34e-4c7e21d3e54b', 'Thruster Ciclista a una mano con Kettlebell', 28, 6, 281, 1, 'Intermedio', 'Con los talones elevados, realiza una sentadilla profunda con una Kettlebell en posicion rack y sube explosivamente terminando con un press sobre la cabeza con un solo brazo.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Cyclist Single-Arm Kettlebell Thruster', 'With your heels elevated, perform a deep squat with a kettlebell in the rack position and drive up explosively into a one-arm overhead press.', 'external'),
('bf5c5a0f-6f3b-47a4-a3b6-9f9cbddb7da0', 'Hip thrust máquina', 29, 55, 186, 1, 'Intermedio', 'En máquina específica de hip thrust, realiza empujes de cadera con resistencia controlada. Más cómodo y seguro que la versión con barra. Aprieta fuertemente los glúteos en la parte superior y controla el descenso.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Hip Thrust Machine', 'On a specific hip thrust machine, perform hip thrusts with controlled resistance. More comfortable and safer than the version with a bar. Tightly squeeze your glutes at the top and control the descent.', 'external'),
('bf7f7dae-8872-4e46-93ef-7a9ad3f5efd9', 'Remo Pendlay con barra Trap', 71, 17, 116, 1, 'Intermedio', 'Con el torso paralelo al suelo, levanta la barra Trap de forma explosiva desde el suelo hasta el abdomen en cada repeticion.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Pendlay Row with Trap Bar', 'With your torso parallel to the floor, lift the trap bar explosively from the floor to your abs with each repetition.', 'external'),
('bf82ab3d-335c-43f5-a3a6-1121bd28e2df', 'Bodyweight Alternating Heel Taps', 25, NULL, 1, 1, 'Principiante', 'Acuéstate boca arriba con las rodillas dobladas. Levanta ligeramente los hombros del suelo y flexiona el torso lateralmente para tocar el talón derecho con la mano derecha, luego repite con el lado izquierdo.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Alternating Heel Taps', 'Lie on your back with your knees bent. Lift your shoulders slightly off the floor and flex your torso laterally to touch your right heel with your right hand, then repeat on the left side.', 'bodyweight'),
('bf91c915-e439-4247-bd87-42cd450df70f', 'Wall roll out', 25, NULL, 271, 1, 'Intermedio', 'Rueda verticalmente contra una pared. Buena progresión hacia el roll out completo. Permite ajustar la dificultad según la distancia a la pared. Mantén el cuerpo recto y controla el descenso.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Wall Roll Out', 'Roll vertically against a wall. This is a good progression toward a full rollout and lets you adjust the difficulty based on your distance from the wall. Keep your body straight and control the descent.', 'external'),
('bfa4cee9-30e4-41ef-89ce-3fcbdf9d691e', 'Swing en forma de corazón con Indian Club', 6, 100, 1, 1, 'Principiante', 'Realiza movimientos circulares fluidos con el Indian Club alrededor de los hombros describiendo una trayectoria en forma de corazón para mejorar la movilidad.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Indian Club Heart-Shaped Swing', 'Perform smooth circular movements with the Indian club around your shoulders in a heart-shaped path to improve mobility.', 'bodyweight'),
('bfb3a0f2-1038-4244-bddf-9a92b948989a', 'Press de banca declinado a una mano con Kettlebell Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado en banco declinado, presiona una Kettlebell invertida con una mano, exigiendo un control extremo de estabilidad.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-handed Decline Bench Press with Bottoms-Up Kettlebell', 'Lying on a decline bench, press an inverted kettlebell with one hand, demanding extreme stability control.', 'external'),
('c021ebe1-d0a2-4fb2-a23f-70f48ebf74d3', 'Sentadilla Goblet mancuerna pausa fondo', 28, 25, 81, 1, 'Principiante', 'Mantén sentadilla con pesa al pecho 3s abajo. Cue: codos en rodillas. Error: despegar talón.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Goblet Squat Dumbbell Pause Background', 'Maintain squat with dumbbell to your chest for 3 seconds below. Cue: elbows on knees. Common mistake: take off heel.', 'external'),
('c0285eca-a940-42bd-a18b-ca0a2a8cc079', 'Curl de bíceps agarre inverso con barra recta en cable', 17, 100, 151, 1, 'Principiante', 'Frente a la polea baja, agarra la barra recta con las palmas hacia abajo y realiza el curl para enfatizar el braquial y los antebrazos.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Cable Straight Bar Reverse Grip Biceps Curl', 'Facing the low cable, grab the straight bar with your palms facing down and perform the curl to emphasize the brachialis and forearms.', 'external'),
('c0309550-fa25-4c33-9642-012d026945d6', 'Ring Handstand a Elbow Lever a Handstand', 6, 2, 1, 1, 'Avanzado', 'Desde parada de manos en anillas, baja controladamente hasta un apoyo de codos (elbow lever) y vuelve a presionar con fuerza hasta la vertical.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Ring Handstand to Elbow Lever to Handstand', 'From a handstand in rings, lower yourself controlledly to an elbow lever and press hard again to the vertical.', 'bodyweight'),
('c04093cd-3518-4cb6-8555-ed356d0a1a07', 'Bodyweight Standing Walkout Plank', 25, 6, 1, 1, 'Intermedio', 'Desde una posición de pie, inclínate y camina con las manos hacia adelante hasta llegar a una posición de plancha alta. Mantén un segundo y camina con las manos de vuelta hacia los pies.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Standing Walkout Plank', 'From a standing position, bend over and walk your hands forward until you reach a high plank position. Hold for a second and walk your hands back toward your feet.', 'bodyweight'),
('c05a2a8a-2fb4-452c-b7a6-6d7d942e5820', 'Curl femoral de pie', 55, NULL, 186, 1, 'Principiante', 'De pie en la máquina, flexiona una rodilla por vez llevando el talón hacia el glúteo. Mantén el muslo de la pierna que trabaja apoyado en el soporte. Esta versión unilateral permite mayor concentración en cada pierna.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Standing femoral curl', 'Standing on the machine, bend one knee at a time, bringing your heel toward your glute. Keep the thigh of the working leg supported by the support. This unilateral version allows greater concentration on each leg.', 'external'),
('c0cac239-3989-4498-b5bb-6375476b50bf', 'Clamshell lateral con Miniband', 29, 37, 61, 1, 'Principiante', 'Acuéstate de lado con las rodillas dobladas y una banda sobre ellas. Manteniendo los pies juntos, abre la rodilla superior como una almeja.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Side Clamshell with Mini Band', 'Lie on your side with your knees bent and a band over them. Keeping your feet together, open your top knee like a clam.', 'external'),
('c0f036be-51ae-4be4-b790-4791e57a7383', 'Half Lay Front Lever en anillas', 25, 16, 1, 24, 'Avanzado', 'Mantén el cuerpo paralelo al suelo con los brazos rectos y las caderas extendidas, pero con las rodillas flexionadas a 90 grados.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Half Lay Front Lever in Rings', 'Keep your body parallel to the ground with your arms straight and your hips extended, but with your knees bent at 90 degrees.', 'bodyweight'),
('c12392bf-ce74-40d3-aa96-6276b3e56447', 'L-Sit a parada de manos en paralelas', 6, 25, 1, 1, 'Avanzado', 'Desde la posición de L-Sit en las paralelas, eleva las caderas y transiciona el cuerpo hasta quedar en posición vertical de parada de manos.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'L-Sit to parallel handstand', 'From the L-Sit position on the parallel bars, raise your hips and transition your body into a vertical handstand position.', 'bodyweight'),
('c131683f-b93c-4c5e-acb2-edd36b955b5c', 'TRX Extensión cadera', 29, 55, 216, 1, 'Intermedio', 'Eleva cadera talones TRX. Objetivo: glúteo/isquios. Cue: aprieta arriba. Error: arquear lumbar.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX Hip Extension', 'Lift your hips with your heels in the TRX straps. Target: glutes and hamstrings. Cue: squeeze at the top. Common mistake: arching the lower back.', 'bodyweight'),
('c17befe1-cd25-4598-b364-a8df135eb59a', 'Cable Kneeling Crunch', 25, NULL, 151, 1, 'Principiante', 'Arrodíllate frente a una polea alta sosteniendo la cuerda detrás de la cabeza. Contrae el abdomen para llevar los codos hacia las rodillas, redondeando la espalda.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Cable Kneeling Crunch', 'Kneel in front of a high cable holding the rope behind your head. Contract your abs to bring your elbows toward your knees, rounding your back.', 'external'),
('c1c4645d-8f3b-45e4-b973-0d7f71a2176e', 'Press de banca declinado alterno con Kettlebell doble Bottoms Up', 1, 2, 281, 1, 'Avanzado', 'Tumbado en banco declinado, presiona las Kettlebells invertidas de forma alterna, manteniendo una estable arriba mientras la otra desciende.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double kettlebell Alternating Decline Bench Press Bottoms Up', 'Lying on a decline bench, press the inverted kettlebells alternately, keeping one stable on top while the other lowers.', 'external'),
('c2142817-284f-4b9a-96ac-2872a1ac97e8', 'Sentadilla overhead TRX', 28, 6, 216, 1, 'Avanzado', 'Sentadilla manteniendo los brazos extendidos sobre la cabeza con TRX. Desafía la movilidad de hombros y tobillos. Las correas proporcionan feedback propioceptivo. Mantén tensión constante en las correas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX overhead squat', 'Squat keeping arms extended overhead with TRX. Challenges shoulder and ankle mobility. The straps provide proprioceptive feedback. Maintain constant tension on the straps.', 'mixed'),
('c22863d1-60c5-4943-b8f4-2a7745eaab58', 'Puente de glúteo con barra', 29, 55, 116, 1, 'Principiante', 'Tumbado con rodillas dobladas y barra sobre la pelvis, eleva la cadera contrayendo los glúteos hasta alinear rodillas y hombros.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Barbell Glute Bridge', 'Lying down with knees bent and barbell over your pelvis, raise your hips by contracting your glutes until your knees and shoulders are aligned.', 'external'),
('c243f09f-120d-4c22-a4ac-12f0007d3c92', 'Knee Tuck a una pierna con Fitball', 25, 6, 290, 1, 'Avanzado', 'En posición de plancha con un pie en el Fitball y el otro en el aire. Lleva la rodilla de la pierna apoyada hacia el pecho rodando el balón y regresa.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Knee Tuck on one leg with Stability Ball', 'In a plank position with one foot on the Stability Ball and the other in the air. Bring the knee of the supported leg towards the chest, rolling the ball and return.', 'bodyweight'),
('c2767892-6235-468d-b6e4-2629feabdfb3', 'Extensión tríceps polea cuerda', 2, NULL, 151, 1, 'Principiante', 'Tira cuerda abajo abriendo extremos. Objetivo: tríceps lateral. Cue: codos pegados. Error: adelantar hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Triceps Cable Rope Extension', 'Pull rope down, opening ends. Target: lateral triceps. Cue: elbows stuck together. Common mistake: putting your shoulders forward.', 'external'),
('c2a2aa84-493a-454c-9ab2-968b2695b3b8', 'Puente de glúteo a una pierna con pie elevado', 29, 55, 1, 1, 'Intermedio', 'Acuéstate con un pie apoyado en un banco o cajón. Eleva la cadera empujando con ese pie, manteniendo la otra pierna en el aire.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'One-leg Glute Bridge with Elevated Foot', 'Lie down with one foot resting on a bench or box. Raise your hips by pushing with that foot, keeping the other leg in the air.', 'mixed'),
('c2e77bcb-539c-4e68-b6f4-e3e19ef8e64f', 'Press Pallof', 25, 6, 151, 24, 'Principiante', 'Resiste la rotación del cable extendiendo los brazos al frente de forma isométrica. Objetivo: anti-rotación del core. Cue: pies clavados al suelo. Error común: permitir que el cable mueva tu tronco.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Press Pallof', 'Resist the rotation of the cable by extending your arms in front of you isometrically. Target: anti-core rotation. Cue: feet planted firmly. Common mistake: allowing the cable to move your torso.', 'external'),
('c2f43563-991e-4f50-b25b-238ce06d9b57', 'Press de banca convencional', 1, 2, 116, 1, 'Principiante', 'Tumbado en banco plano, baja la barra al pecho y empuja hacia arriba. Mantén los pies apoyados y una ligera curva lumbar. Cue: retrae las escápulas. Error: rebotar la barra en el pecho.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Conventional Bench Press', 'Lying on a flat bench, lower the bar to your chest and push up. Keep your feet supported and a slight lumbar curve. Cue: retract the scapulae. Common mistake: bouncing the bar off your chest.', 'external'),
('c321ed30-27db-4804-9f85-42ce6bc0c9f6', 'Encogimientos hombros sentado mancuernas estricto', 71, 6, 81, 1, 'Principiante', 'Eleva los hombros hacia las orejas sentado para eliminar el impulso de piernas. Cue: no dobles los codos al subir. Error: rotar los hombros en círculos arriba.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Seated Dumbbell Shrugs', 'Raise your shoulders toward your ears while sitting to eliminate leg drive. Cue: don''t bend your elbows when going up. Common mistake: rotating the shoulders in circles above.', 'external'),
('c3db4ee4-5668-4639-beb2-87903535cdbb', 'Aperturas inclinadas en polea alta', 1, 6, 151, 1, 'Intermedio', 'Junta poleas frente al pecho superior en banco inclinado. Cue: codos fijos. Error: encoger hombros.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Inclined Openings in High Pulley', 'Bring the cable handles together in front of your upper chest on an incline bench. Cue: keep your elbows fixed. Common mistake: shrugging your shoulders.', 'external'),
('c3eb6dea-7238-47af-b255-69f11215fbf2', 'Kettlebell Overhead Squat', 28, 6, 281, 1, 'Avanzado', 'Sentadilla manteniendo la pesa con un brazo totalmente extendido sobre la cabeza. Movilidad máxima. Pecho alto. No dejes que el brazo caiga adelante.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Overhead Squat', 'Squat holding the weight with one arm fully extended above the head. Maximum mobility. High chest. Don''t let your arm fall forward.', 'external'),
('c3f4ea47-5af4-4d66-971b-f77fb69ab4b7', 'Press francés con mancuernas', 2, NULL, 81, 1, 'Intermedio', 'Tumbado, baja las mancuernas a los lados de las orejas flexionando codos. Cue: codos apuntando al techo. Error: mover los brazos desde el hombro.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'French Press with Dumbbells', 'Lying down, lower the dumbbells to the sides of your ears, bending your elbows. Cue: elbows pointing to the ceiling. Common mistake: moving the arms from the shoulder.', 'external'),
('c3fe5e2b-1722-4256-ab2c-357b90ad3c93', 'Curl de muñeca con barra', 100, NULL, 116, 1, 'Principiante', 'Apoya antebrazos en banco y flexiona muñecas con las palmas hacia arriba. Objetivo: flexores de muñeca. Cue: rango de movimiento completo. Error común: levantar los antebrazos del banco.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Barbell Wrist Curl', 'Rest your forearms on a bench and flex your wrists with your palms facing up. Target: wrist flexors. Cue: full range of motion. Common mistake: lifting your forearms off the bench.', 'external'),
('c4196719-8b09-4904-9c13-7381ea2b8a09', 'Zancadas caminando overhead', 28, 6, 81, 1, 'Avanzado', 'Zancadas caminando con mancuernas sostenidas sobre la cabeza. Combina fuerza de piernas con estabilidad de hombros y core. Mantén los brazos bloqueados verticalmente. Requiere excelente movilidad y control.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Overhead Walking Strides', 'Walking lunges with dumbbells held overhead. This combines leg strength with shoulder and core stability. Keep your arms locked out vertically. It requires excellent mobility and control.', 'external'),
('c465da2d-567d-4fbe-9ffb-20df10703e3c', 'Sentadilla sumo con barra', 29, 313, 116, 1, 'Intermedio', 'Pies anchos, barra en trapecio, baja en sentadilla profunda. Objetivo: aductores y glúteo. Cue: rodillas alineadas con puntas. Error común: levantar talones del suelo.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Barbell Sumo Squat', 'Wide feet, trapeze bar, low deep squat. Target: adductors and glute. Cue: knees aligned with toes. Common mistake: lifting heels off the ground.', 'external'),
('c49ef3a4-f8de-4c4f-a8ca-721f23a15658', 'Fondos entre bancos', 2, 1, 1, 1, 'Principiante', 'Baja la cadera apoyado en el borde de un banco con las manos tras de ti. Objetivo: fuerza de tríceps. Cue: codos apuntando hacia atrás. Error común: dejar que los hombros se encojan.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Interbank Funds', 'Lower your hips while leaning on the edge of a bench with your hands behind you. Target: triceps strength. Cue: elbows pointing back. Common mistake: letting your shoulders shrug.', 'bodyweight'),
('c4b87b70-7a77-4833-a5d4-b6327ffa2a8c', 'Zancada inversa contralateral Slider y mancuerna Front Rack', 28, 29, 81, 1, 'Intermedio', 'Sostén una mancuerna en un hombro y desliza hacia atrás la pierna del lado opuesto usando un slider.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse stride contralateral Slider and dumbbell Front Rack', 'Hold a dumbbell on one shoulder and slide back the leg on the opposite side using a slider.', 'external'),
('c4caaf1b-6a42-49b0-b6be-873264bf727f', 'Sentadilla trasera con barra alta', 28, 29, 116, 1, 'Principiante', 'Coloca la barra sobre los trapecios. Baja la cadera manteniendo el torso lo mas vertical posible y las rodillas alineadas con los pies, luego sube con fuerza.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'High Bar Back Squat', 'Place the bar on the traps. Lower your hips, keeping your torso as vertical as possible and your knees in line with your feet, then go up forcefully.', 'external'),
('c4fdc8b5-84c3-4220-9dd4-ad2788e00770', 'Hip Thrust sobre Fitball con mancuerna', 29, 55, 81, 1, 'Intermedio', 'Realiza un Hip Thrust con la espalda en el Fitball, sosteniendo una mancuerna sobre las caderas para añadir carga al movimiento.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Hip Thrust on Stability Ball with dumbbell', 'Perform a Hip Thrust with your back on the Stability Ball, holding a dumbbell on your hips to add load to the movement.', 'external'),
('c50be416-af7c-4c55-a067-1166e4116b1b', 'Thruster kettlebell', 6, 28, 281, 1, 'Intermedio', 'Combina una sentadilla frontal con press en un movimiento fluido. Desde la posición de rack, desciende en sentadilla y al subir usa el impulso para presionar sobre la cabeza. Ejercicio metabólico intenso que trabaja todo el cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Thruster', 'Combine a front squat with an overhead press in one fluid movement. From the rack position, descend into a squat and use the upward drive to press overhead. This is an intense metabolic full-body exercise.', 'external'),
('c51036d2-95cf-403b-bf5a-d3d54e190287', 'Woodchopper en polea alta', 25, 71, 151, 1, 'Intermedio', 'Diagonal descendente cruzando el cuerpo. Potencia rotacional. Core bloqueado. No muevas las caderas excesivamente.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'High Cable Woodchopper', 'Perform a descending diagonal motion across your body. Target: rotational power. Cue: brace your core. Common mistake: moving your hips too much.', 'external'),
('c57287da-2a66-4a37-8e40-d7e39aad8d46', 'Press Z con barra', 6, 25, 116, 1, 'Intermedio', 'Realiza un press militar sentado en el suelo con piernas extendidas, exigiendo una postura perfecta de la columna y fuerza de core.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Barbell Z Press', 'Perform a military press seated on the floor with legs extended, demanding perfect spinal posture and core strength.', 'external'),
('c59521c2-67a0-458c-bc05-eef90fee7d25', 'Plancha lateral isométrica', 25, 6, 1, 24, 'Principiante', 'Apoyado en un antebrazo de lado, mantén la cadera elevada formando una línea. Objetivo: oblicuos. Cue: pecho abierto. Error común: dejar que la cadera caiga hacia el suelo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Isometric Side Plank', 'Support yourself on one forearm and keep your hips raised in a straight line. Target: obliques. Cue: keep your chest open. Common mistake: letting your hips drop toward the floor.', 'bodyweight'),
('c5f554d8-508e-47aa-849a-f6693ae427cc', 'Extensión de tríceps tras nuca polea', 2, NULL, 151, 1, 'Intermedio', 'De espaldas a la polea, extiende los brazos sobre la cabeza. Cue: codos pegados a las orejas. Error: abrir los codos lateralmente.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Triceps Extension Behind Neck Cable', 'With your back to the cable, extend your arms overhead. Cue: elbows close to the ears. Common mistake: opening the elbows laterally.', 'external'),
('c607c999-17e2-42e3-9afa-ff1f06a66d24', 'Jalón al pecho agarre neutro', 16, 17, 186, 1, 'Principiante', 'Tira de la barra al pecho con palmas enfrentadas. Cue: saca pecho al bajar. Error: balancear torso.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Neutral Grip Chest Pull', 'Pull the bar to your chest with palms facing each other. Cue: stick out your chest on the way down. Common mistake: swing torso.', 'external'),
('c6455069-74d5-4e26-a51b-37138de47517', 'Flexiones declinadas controladas', 1, 2, 1, 1, 'Intermedio', 'Pies en banco o superficie elevada, realiza flexiones en el suelo. Objetivo: pectoral superior y deltoides. Cue: core bloqueado. Error común: dejar caer la cabeza al bajar.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Controlled Decline Push-ups', 'Feet on a bench or raised surface, perform push-ups on the floor. Target: upper chest and deltoids. Cue: locked core. Common mistake: dropping your head when going down.', 'mixed'),
('c6505688-fb83-4364-8c21-3f1e5031eaad', 'Curl de bíceps en polea con cuerda', 17, 100, 151, 1, 'Principiante', 'Flexiona y abre los extremos arriba para mayor contracción. Tensión constante. Codos fijos. No te balancees.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Rope Pulley Biceps Curl', 'Flex and open the ends above for greater contraction. Constant tension. Fixed elbows. Don''t swing.', 'external'),
('c66946c3-b7c1-4068-8a8c-4b2101e40aaf', 'Sentadilla Hack con barra', 28, 55, 116, 1, 'Intermedio', 'Realiza una sentadilla sujetando la barra por detrás de tus piernas, justo bajo los glúteos. Objetivo: aislamiento de cuádriceps. Cues: pecho alto y mirada al frente. Error común: redondear la espalda para alcanzar la barra.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Barbell Hack Squat', 'Perform a squat holding the bar behind your legs, just under your glutes. Target: quadriceps isolation. Cue: chest up and look forward. Common mistake: rounding your back to reach the bar.', 'external'),
('c6849be8-2c68-48aa-b765-52ccbca7e019', 'Sentadilla salto TRX', 28, 29, 216, 1, 'Avanzado', 'Sentadillas con salto asistidas por TRX permitiendo mayor explosividad. Las correas ayudan en el aterrizaje y permiten saltos más altos. Mantén tensión en las correas durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Squat Jump', 'TRX-assisted jump squats allowing greater explosiveness. The straps aid in landing and allow for higher jumps. Maintain tension on the straps throughout the movement.', 'assisted'),
('c6b31e41-876c-47f8-91a9-9de2895247c2', 'Curl de isquiotibiales con Slider', 55, 29, 1, 1, 'Intermedio', 'En posición de puente, desliza los talones sobre sliders alejándolos del cuerpo y vuelve a recogerlos contrayendo fuertemente los isquiotibiales.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Slider Hamstring Curl', 'From a bridge position, slide your heels away from your body on sliders and pull them back by strongly contracting your hamstrings.', 'bodyweight'),
('c6edda6c-cd40-41fa-bab9-21578619660e', 'Single Arm Dumbbell Seated Shoulder External Rotation', 6, NULL, 81, 1, 'Principiante', 'Siéntate con el codo apoyado sobre la rodilla doblada a 90 grados. Rota el antebrazo hacia arriba y atrás manteniendo el codo fijo, luego baja controlado.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Single Arm Dumbbell Seated Shoulder External Rotation', 'Sit with your elbow resting on your knee bent at 90 degrees. Rotate your forearm up and back, keeping your elbow fixed, then lower yourself under control.', 'external'),
('c6fd042f-9291-4ba1-82ae-91ee03b2c042', 'Aperturas inversas a una pierna en TRX', 6, 71, 216, 1, 'Intermedio', 'Mantén el equilibrio sobre una pierna mientras abres los brazos hacia atrás en el TRX para trabajar los deltoides posteriores.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Reverse one leg splits in TRX', 'Balance on one leg as you open your arms back in the TRX to work your rear delts.', 'bodyweight'),
('c712407a-bc78-4c47-ae64-ee8f874cce90', 'Inside Pullover con maza a una mano', 71, 6, 81, 1, 'Principiante', 'Lleva la maza desde el hombro opuesto cruzando por delante del torso hacia la vertical, trabajando la movilidad y fuerza del hombro.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Inside Pullover with one-handed mace', 'Bring the club from the opposite shoulder, crossing in front of the torso towards the vertical, working on the mobility and strength of the shoulder.', 'external'),
('c73cfd26-ba38-4da8-bed1-97e7fe6d55fc', 'Remo en anillas con pies elevados', 71, 17, 1, 1, 'Intermedio', 'Sujeta las anillas con los talones apoyados en un banco. Tira del pecho hacia las anillas manteniendo el cuerpo en una linea horizontal rigida.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ring row with raised feet', 'Hold the rings with your heels resting on a bench. Pull your chest towards the rings, keeping your body in a rigid horizontal line.', 'bodyweight'),
('c7661a20-d734-4c3f-956b-8b29dba5efb1', 'Pullover con barra recta en cable', 71, 2, 151, 1, 'Principiante', 'De pie frente a la polea alta, con brazos rectos, baja la barra hacia los muslos utilizando los dorsales y controlando el retorno.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Pullover with straight cable bar', 'Standing in front of the high pulley, with straight arms, lower the bar towards your thighs using your lats and controlling the return.', 'external'),
('c7ac1d34-acaf-4003-b87a-9afcd07092db', 'Abducción cadera cable', 37, NULL, 151, 1, 'Principiante', 'Con tobillera en polea baja, realiza abducciones laterales de cadera. Mantén el torso erguido y evita inclinarte hacia el lado opuesto. El cable proporciona resistencia constante para el glúteo medio y menor. Controla el movimiento en ambas direcciones.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Hip Abduction', 'With a low pulley ankle cuff, perform lateral hip abductions. Keep your torso upright and avoid leaning to the opposite side. The cable provides constant resistance for the glute medius and minimus. Control the movement in both directions.', 'external'),
('c7edc792-e0e7-4983-ad4e-bd448abef46b', 'Curl martillo cuerda', 17, 100, 151, 1, 'Principiante', 'Realiza un curl martillo en polea con cuerda. Mantén los codos cerca del cuerpo, tira de la cuerda de forma controlada y aprieta al final del movimiento.', FALSE, NULL, '2026-05-14T14:43:02.696631+00:00', 'Rope Hammer Curl', 'Perform a hammer curl on a cable machine using a rope attachment. Keep your elbows close to the body, pull the rope under control, and squeeze at the end of the movement.', 'external'),
('c8202aac-4150-4ad2-a96e-2df185b0239a', 'Barra de brazo kettlebell', 6, NULL, 281, 1, 'Avanzado', 'Tumbado lateral, lleva la kettlebell desde el suelo hasta brazo extendido vertical. Ejercicio de movilidad y estabilidad del hombro. Componente del levantamiento turco. Mantén el brazo perpendicular al suelo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Arm Bar', 'Lying on your side, move the kettlebell from the floor to a vertical arm position. This exercise improves shoulder mobility and stability. It is part of the Turkish get-up. Keep your arm perpendicular to the ground.', 'external'),
('c8345bb6-20f9-4240-936a-0adb9895b5aa', 'Cargada kettlebell', 6, 28, 281, 1, 'Avanzado', 'Lleva la kettlebell desde el suelo hasta la posición de rack (hombro) en un movimiento explosivo. Requiere coordinación y timing. La kettlebell debe rotar alrededor de la muñeca, no golpear el antebrazo. Base para movimientos más complejos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Loaded kettlebell', 'Bring the kettlebell from the floor to the rack (shoulder) position in an explosive movement. Requires coordination and timing. The kettlebell should rotate around the wrist, not hit the forearm. Base for more complex movements.', 'external'),
('c88b27d3-2084-4c20-b18d-e1243c858cdc', 'Sentadilla Overhead con Kettlebell a una mano', 28, 6, 281, 1, 'Intermedio', 'Mantén una Kettlebell bloqueada sobre la cabeza con un brazo y realiza una sentadilla profunda con control del equilibrio y core.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Handed kettlebell Overhead Squat', 'Hold a kettlebell locked overhead with one arm and perform a deep squat with balance and core control.', 'external'),
('c8cd64d8-1d74-4d71-9e62-f142133f659e', 'Hamstring curl TRX', 55, NULL, 216, 1, 'Intermedio', 'Tumbado boca arriba con talones en las correas, eleva las caderas y flexiona las rodillas llevando los talones hacia los glúteos. Mantén las caderas elevadas durante todo el movimiento. Excelente para isquiotibiales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Hamstring Curl', 'Lying face up with your heels in the straps, raise your hips and bend your knees, bringing your heels toward your glutes. Keep your hips elevated throughout the movement. Excellent for the hamstrings.', 'bodyweight'),
('c9175294-669d-4424-b4f6-002a0bf52963', 'Windmill medio arrodillado con Kettlebell a una mano', 25, 6, 281, 1, 'Intermedio', 'En posicion de caballero con la pesa bloqueada sobre la cabeza, inclina el torso hasta tocar el suelo con la mano libre para ganar movilidad.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Half-Kneeling Single-Arm Kettlebell Windmill', 'In a half-kneeling position with the weight locked overhead, hinge your torso until you touch the floor with your free hand to improve mobility.', 'external'),
('c9369285-07c9-4c01-b2a6-6447a3c1f611', 'Zancada reloj (Around the clock)', 28, 29, 1, 1, 'Intermedio', 'Realiza una zancada al frente, una lateral y una trasera con la misma pierna siguiendo las agujas del reloj. Objetivo: estabilidad multiplanar. Cues: mantén el core activo para evitar desequilibrios. Error común: dar pasos demasiado cortos que comprometan la rodilla.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Clock Stride (around the Clock)', 'Make a stride to the front, side and back with the same leg in a clockwise manner. Target: Multi-planar stability. Cue: Keep the core active to avoid imbalances. Common mistake: Taking too short steps that compromise the knee.', 'bodyweight'),
('c93c403e-d91d-4dbc-898b-c8fca126614c', 'Remo inclinado con barra Trap', 71, 17, 116, 1, 'Principiante', 'Sujeta la barra Trap por las asas laterales inclinando el torso. Tira del peso hacia la cadera manteniendo la espalda recta.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Trap Bar Bent Over Row', 'Hold the trap bar by the side handles, tilting your torso. Pull the weight toward your hips, keeping your back straight.', 'external'),
('c94d9821-9660-48c6-8ab1-5a3c4eb4d11e', 'Press de banca con barra', 1, 2, 116, 1, 'Principiante', 'Tumbado en banco plano, baja la barra al pecho y empuja hacia arriba. Objetivo: fuerza de empuje pectoral. Cue: retrae las escápulas y pies en el suelo. Error común: rebotar la barra en el pecho.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Barbell Bench Press', 'Lying on a flat bench, lower the bar to your chest and push up. Target: chest push strength. Cue: retract your scapulae and feet into the ground. Common mistake: bouncing the bar off your chest.', 'external'),
('c958ea0a-58df-4564-90f1-225a4adade00', 'Plancha con elevación de brazo frontal', 25, 6, 1, 24, 'Intermedio', 'En plancha frontal, eleva un brazo totalmente estirado al frente sin mover el cuerpo. Objetivo: estabilidad anti-rotacional. Cues: pies anchos para mayor base. Error común: rotar el cuerpo al levantar el brazo.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Plank with Front Arm Raise', 'In a front plank, raise one fully extended arm in front of you without moving your body. Target: anti-rotational stability. Cue: keep your feet wide for a larger base. Common mistake: rotating your body as you raise the arm.', 'bodyweight'),
('c95c271c-ec9f-4b36-9eba-0d0dc31b27a6', 'Pullover mancuernas', 1, 16, 81, 1, 'Intermedio', 'Túmbate perpendicular al banco con solo los hombros apoyados. Sujeta una mancuerna con ambas manos sobre el pecho. Desciende la mancuerna por detrás de la cabeza en arco manteniendo los brazos semi-extendidos. Vuelve a la posición inicial activando pecho y dorsales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell pullover', 'Lie perpendicular to the bench with only your shoulders supported. Hold a dumbbell with both hands on your chest. Lower the dumbbell behind your head in an arc, keeping your arms semi-extended. Return to the starting position activating chest and dorsals.', 'external'),
('c973e606-491e-4def-945b-e760251b8719', 'Crab walk', 2, 6, 1, 1, 'Intermedio', 'Siéntate con las manos detrás apoyadas en el suelo y eleva las caderas. Camina hacia atrás o los lados moviendo manos y pies coordinadamente. Mantén las caderas elevadas durante todo el movimiento. Fortalece tríceps, hombros y core mientras mejora la movilidad de hombros.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Crab Walk', 'Sit with your hands behind you on the floor and raise your hips. Walk backwards or to the sides moving hands and feet in coordination. Keep your hips raised throughout the movement. Strengthens triceps, shoulders and core while improving shoulder mobility.', 'bodyweight'),
('c99bee43-fc7e-4158-870e-f2181665cd2b', 'Press militar de pie', 6, 2, 116, 1, 'Intermedio', 'Empuja la barra desde el pecho hasta bloquear sobre la cabeza sin ayuda de piernas. Cue: aprieta glúteos y abdomen. Error: balanceo del cuerpo para subir el peso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Standing Military Press', 'Push the bar from your chest until you lock it overhead without the help of your legs. Cue: tighten glutes and abs. Common mistake: swinging the body to raise the weight.', 'external'),
('c9b26220-c57e-4261-aa73-9998f8a50902', 'Pull apart con banda', 71, 6, 61, 1, 'Principiante', 'Sujeta la banda con ambas manos frente al pecho, brazos extendidos. Separa las manos estirando la banda mientras llevas los omóplatos hacia atrás. Mantén los brazos paralelos al suelo durante todo el movimiento. Fortalece la espalda alta y mejora la postura.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pull apart with band', 'Hold the band with both hands in front of your chest, arms extended. Separate your hands by stretching the band while pulling your shoulder blades back. Keep your arms parallel to the floor throughout the movement. Strengthens the upper back and improves posture.', 'external'),
('c9c8931f-c2b1-44c4-a840-2312bd65aae6', 'Flexión pliométrica sobre fitball', 1, 25, 290, 1, 'Avanzado', 'Flexión con pies en fitball y manos en suelo, empujando explosivamente. Alta demanda de core. Cue: aprieta glúteos para estabilizar la bola. Error común: arquear la lumbar excesivamente.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Plyometric Push-up on Stability Ball', 'Flexion with feet on a stability ball and hands on the floor, pushing explosively. High demand for core. Cue: squeeze your glutes to stabilize the ball. Common mistake: arching the lower back excessively.', 'bodyweight'),
('c9d1f0e1-cd67-43b2-87e4-5c9fb33d3f00', 'Peso muerto convencional', 55, 71, 116, 1, 'Intermedio', 'Barra en el suelo, agarre a la anchura de hombros, levanta la carga extendiendo cadera y rodillas. Cue: barra pegada a las tibias. Error: redondear la espalda lumbar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Conventional Deadlift', 'Bar on the floor, shoulder-width grip, lift the load by extending your hips and knees. Cue: bar attached to the shins. Common mistake: rounding the lumbar back.', 'external'),
('c9f4522c-8c61-43eb-a490-765c68cf7bba', 'Skin the Cat en anillas', 71, 25, 1, 1, 'Intermedio', 'Colgado de las anillas, gira el cuerpo hacia atras pasando las piernas entre los brazos hasta quedar en estiramiento maximo de hombros.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Skin the Cat in Rings', 'Hanging from the rings, turn your body backwards, passing your legs between your arms until your shoulders are fully stretched.', 'bodyweight'),
('ca2b9b88-15b3-46fa-be24-daddb077f104', 'Hollow Body Hold con mancuerna (Agarre Crush)', 25, 1, 81, 24, 'Avanzado', 'En posición de Hollow Body (espalda baja pegada al suelo, extremidades elevadas), sostén una mancuerna con ambas manos presionándola contra el pecho o extendida sobre la cabeza.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Hollow Body Hold with Dumbbell (crush Grip)', 'In a Hollow Body position (low back flat on the floor, limbs elevated), hold a dumbbell with both hands, pressing it against your chest or extended overhead.', 'external'),
('ca4db067-9c1c-4c47-8885-a1039bd7456d', 'Clapping push ups', 1, 2, 1, 1, 'Avanzado', 'Realiza una flexión explosiva empujando con suficiente fuerza para despegar las manos del suelo. En el aire, da una palmada rápida antes de aterrizar suavemente con las manos para amortiguar y continuar con la siguiente repetición. Desarrolla potencia explosiva del tren superior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Clapping push ups', 'Perform an explosive push-up, pushing with enough force to lift your hands off the ground. In the air, give a quick clap before landing softly with your hands to cushion and continue with the next repetition. Develops explosive power of the upper body.', 'mixed'),
('ca65d717-0c11-4376-8794-3c5b6998feb5', 'Kettlebell Russian Twist', 25, 71, 281, 1, 'Principiante', 'Sentado, gira el torso con la pesa de lado a lado. Enfoque en oblicuos. Espalda recta. No muevas excesivamente las piernas.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Russian Twist', 'Sitting, rotate your torso with the dumbbell from side to side. Focus on obliques. Straight back. Don''t move your legs excessively.', 'external'),
('caa04bd0-90d8-428b-bebe-0341253570ef', 'Step up mancuernas brazos estirados', 28, 29, 81, 1, 'Principiante', 'Sube banco con pesas a los lados. Cue: empuja pierna arriba. Error: saltar con pie suelo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Straight-arm Dumbbell Step-up', 'Step onto the bench holding dumbbells at your sides with your arms straight. Cue: drive through the lead leg. Common mistake: jumping off the trailing foot.', 'external'),
('caa38799-6bca-408a-a323-34c7d0e36d7f', 'Aducción de cadera en Side Plank con banda', 313, 25, 61, 1, 'Intermedio', 'En posición de plancha lateral con una banda elástica enganchada a la pierna superior, eleva la pierna inferior para trabajar el aductor contra resistencia.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Hip adduction in Side Plank with band', 'In a side plank position with an elastic band hooked to your top leg, raise your bottom leg to work the adductor against resistance.', 'external'),
('cabfdbfd-c69d-447d-90fb-40af707d59d9', 'Salto lateral alterno sobre banco', 29, 28, 1, 1, 'Principiante', 'Salta de lado a lado sobre un banco o linea imaginaria, aterrizando de forma suave y alternando la pierna de apoyo.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Alternating lateral jump on bench', 'Jump from side to side on a bench or imaginary line, landing softly and alternating the supporting leg.', 'bodyweight'),
('cac38166-59fb-4b9d-8385-65b195443d3b', 'Sentadilla patinadora asistida con manos', 28, 29, 1, 1, 'Principiante', 'Baja en sentadilla sobre una sola pierna utilizando las manos en un soporte lateral para facilitar el equilibrio y la profundidad.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Hand-assisted skate squat', 'Lower yourself into a single-leg squat using your hands on a lateral support to facilitate balance and depth.', 'assisted'),
('cac45c3a-c429-42e6-817e-e08e0e1b4a3b', 'Burpee con rodillas al pecho', 13, 25, 1, 1, 'Avanzado', 'Burpee que finaliza con un salto llevando rodillas al pecho. Máxima intensidad cardiovascular y de potencia. Cue: absorbe el impacto suavemente. Error común: encorvarse demasiado al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee with Knees to Chest', 'Burpee that ends with a jump bringing your knees to your chest. Maximum cardiovascular and power intensity. Cue: absorb the impact gently. Common mistake: slouching too much when jumping.', 'bodyweight'),
('cae23db5-0e30-4b27-9343-380e8a0b4f7c', 'Hiperextensión inversa con rodilla doblada', 29, 71, 1, 1, 'Principiante', 'Apoyado en un banco o superficie elevada, eleva las piernas con las rodillas flexionadas para aislar el trabajo en los gluteos y la espalda baja.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Reverse Hyperextension with Bent Knee', 'Leaning on a bench or raised surface, raise your legs with your knees bent to isolate the work on your glutes and lower back.', 'bodyweight'),
('caf2a77c-2e6f-4d7b-93ff-1133c4762e3b', 'Caminata lateral con Miniband (Muslos)', 29, 37, 61, 1, 'Principiante', 'De pie con una banda sobre las rodillas y en media sentadilla. Da pasos laterales manteniendo la tensión constante en la banda sin juntar las rodillas.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Lateral walk with Mini Band (Thighs)', 'Stand with a band over your knees and in a half squat. Take lateral steps while maintaining constant tension on the band without bringing your knees together.', 'external'),
('caf6d35d-a366-4435-bdc4-8a602e27376e', 'Curl Martillo', 17, 100, 81, 1, 'Principiante', 'Agarre neutro (palmas enfrentadas), flexiona la mancuerna. Trabaja braquial y braquiorradial. Cue: codos pegados al costado. Error: balancear el torso para subir.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Hammer Curl', 'Neutral grip (palms facing each other), flex the dumbbell. Works brachial and brachioradialis. Cue: elbows tucked to the side. Common mistake: swing your torso to go up.', 'external'),
('cb41822b-dd1c-45c5-b2ab-ce94584cb842', 'Thruster con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Realiza una sentadilla profunda y presiona dos Kettlebells invertidas sobre la cabeza de forma explosiva al subir.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double Bottoms-Up Kettlebell Thruster', 'Perform a deep squat and explosively press two upside-down kettlebells overhead as you stand up.', 'external'),
('cb7893c3-6f7b-42e0-98d5-b1a2bee2de04', 'Cruce de poleas bajas', 1, 6, 151, 1, 'Intermedio', 'Desde abajo, junta las manos frente al pecho. Enfoque en pectoral superior. Codos semiflexionados. No uses el impulso del cuerpo.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Low cable crossover', 'From below, bring your hands together in front of your chest. Focus on upper pectoral. Semiflexed elbows. Don''t use body momentum.', 'external'),
('cb8aaf91-eaea-4e9f-aad3-dff4c382451a', 'Peso muerto detenido con barra', 71, 55, 116, 1, 'Intermedio', 'Realiza un peso muerto deteniendo la barra durante un segundo justo debajo de la rodilla antes de completar la extensión de cadera, mejorando el control en el punto crítico.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Barbell Standing Deadlift', 'Perform a deadlift by stopping the bar for one second just below the knee before completing hip extension, improving control at the critical point.', 'external'),
('cb8e5597-3b7a-40cf-87da-d772d259970d', 'Sentadilla Pin parcial', 28, 29, 116, 1, 'Avanzado', 'Sentadilla desde soportes en el rango medio del movimiento. Cue: parada total en cada repetición. Error: rebotar en los soportes.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Partial Pin Squat', 'Squat from supports in the middle range of motion. Cue: full stop on each repetition. Common mistake: bouncing off supports.', 'external'),
('cb8fe49e-994e-4c4c-81d3-310dfd862dce', 'Push Jerk con mancuernas', 6, 28, 81, 1, 'Avanzado', 'Lleva las mancuernas sobre la cabeza mediante un impulso de piernas y una recepcion rapida en media sentadilla con brazos bloqueados.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Dumbbell Push Jerk', 'Bring the dumbbells overhead using a leg drive and a quick half-squat reception with locked arms.', 'external'),
('cb9a77d9-ca8e-451e-8e29-d5ce204f38b2', 'Split Jerk con Kettlebell doble', 6, 28, 281, 1, 'Intermedio', 'Lanza las pesas sobre la cabeza mediante un impulso de piernas, recibiéndolas con brazos bloqueados y una pierna adelantada.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double kettlebell Split Jerk', 'Throw the weights overhead using a leg drive, receiving them with locked arms and one leg forward.', 'external'),
('cb9efa67-0049-4454-830b-fe82a20fcf87', 'Levantamiento turco mancuernas', 13, NULL, 81, 1, 'Avanzado', 'Desde posición tumbada con una mancuerna extendida sobre la cabeza, levántate hasta ponerte de pie manteniendo siempre el brazo extendido verticalmente. Invierte el movimiento para volver al suelo. Requiere movilidad, estabilidad y coordinación excepcionales.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Turkish Dumbbell Lift', 'From a lying position with a dumbbell extended overhead, rise to a standing position, always keeping your arm extended vertically. Reverse the movement to return to the ground. Requires exceptional mobility, stability and coordination.', 'external'),
('cbbc128c-28f2-415f-b61e-10524c885c72', 'Bicicleta estática', 13, 28, 186, 1, 'Principiante', 'Pedaleo suave 3 minutos para elevar temperatura corporal y preparar piernas sin impacto.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Stationary Bike', 'Gentle pedaling for 3 minutes to raise body temperature and prepare legs without impact.', 'external'),
('cbcba4da-f5d1-45f2-850b-e7e5d0a7a146', 'Turkish Sit Up con barra', 25, 6, 116, 1, 'Intermedio', 'Realiza un sit up manteniendo una barra cargada bloqueada verticalmente sobre el pecho, exigiendo un control de estabilidad superior.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Barbell Turkish Sit-Up', 'Perform a sit-up while keeping a loaded barbell locked vertically over your chest, demanding a high level of stability control.', 'external'),
('cbd83948-95b2-48dc-ade3-90d2642b5f69', 'Gemelos prensa', 64, NULL, 186, 1, 'Principiante', 'En la prensa de piernas, coloca solo las puntas de los pies en la parte inferior de la plataforma. Realiza flexiones plantares empujando con las puntas. Permite usar cargas pesadas de forma segura para el desarrollo de pantorrillas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Press cufflinks', 'In the leg press, place only the balls of your feet on the bottom of the platform. Perform plantar flexions by pushing with your toes. Allows heavy loads to be used safely for calf development.', 'external'),
('cbdb9922-40f5-4863-a2c6-d95b388acd1b', 'Cha Cha 3 vías con Miniband', 29, NULL, 61, 1, 'Intermedio', 'Con banda en tobillos y posición atlética. Da pasos rápidos y pequeños: diagonal adelante, lateral y diagonal atrás, manteniendo tensión.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Cha Cha 3-way with Mini Band', 'With ankle band and athletic position. Take quick, small steps: diagonally forward, laterally and diagonally backwards, maintaining tension.', 'external'),
('cbfe1466-b517-43a6-baac-df945d0b6cc8', 'Buenos días con barra', 55, 71, 116, 1, 'Avanzado', 'Barra en hombros, inclina el torso adelante con piernas casi rectas. Cadena posterior. Espalda muy plana. No bajes si la espalda se curva.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Barbell Good Morning', 'Bar on shoulders, lean your torso forward with almost straight legs. Posterior chain. Very flat back. Don''t go down if your back curves.', 'external'),
('cc02226f-d15a-4127-9721-1e99eb88b0ac', 'Hip Thrust a una pierna con Miniband', 29, 55, 61, 1, 'Intermedio', 'Con una banda sobre las rodillas, realiza un empuje de cadera apoyado en una sola pierna para maximizar la activacion del gluteo.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Hip Thrust on one leg with Mini Band', 'With a band on your knees, perform a single-leg hip thrust to maximize glute activation.', 'external'),
('cc71c081-8316-44ef-8ad8-474dc7d68f35', 'Crunch en cable arrodillado', 25, NULL, 151, 1, 'Intermedio', 'Crunch en polea arrodillado para abdominales, flexionando la columna de forma controlada sin tirar con brazos.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Kneeling cable crunch', 'Kneeling cable crunch for abs, flexing the spine in a controlled manner without pulling with your arms.', 'external'),
('cc7b1e07-34c7-47aa-8f64-95edb4066dcc', 'Rebote de tobillo unilateral', 64, 309, 1, 1, 'Intermedio', 'Rebota sobre la punta de un solo pie con la rodilla casi bloqueada. Mejora la rigidez del tobillo. Cue: rebota como un resorte. No flexiones mucho la rodilla.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Unilateral Ankle Rebound', 'Bounce on the ball of one foot with the knee almost locked. Improves ankle stiffness. Cue: bounces like a spring. Don''t bend your knee too much.', 'bodyweight'),
('cc9b5f99-6532-46cd-af10-4c427ffcfd69', 'Manmakers', 13, 71, 81, 1, 'Avanzado', 'Burpee con mancuernas, remo en cada brazo, press de hombros y sentadilla. Cue: control absoluto del core. Error: usar pesos que no puedas controlar en el press.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Manmakers', 'Burpee with dumbbells, row in each arm, shoulder press and squat. Cue: absolute control of the core. Common mistake: using weights that you cannot control in the press.', 'external'),
('ccc79c23-50db-4be7-aeb8-17cce0de6eed', 'Salto pogo cadera rotada', 25, 64, 1, 1, 'Intermedio', 'Saltos pogo girando las caderas de lado a lado manteniendo el pecho al frente. Agilidad rotacional. Cue: rotación rápida de pies. Error común: girar los hombros también.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Rotated Hip Pogo Jump', 'Pogo jumps by turning your hips from side to side while keeping your chest in front. Rotational agility. Cue: rapid foot rotation. Common mistake: turning your shoulders too much.', 'bodyweight'),
('ccda659d-7961-4242-b9fc-f9814a7e21f4', 'Straddle L-Sit en paralelas', 25, 2, 1, 24, 'Avanzado', 'Sostente en las paralelas con las piernas abiertas en forma de V y levantadas paralelas al suelo, manteniendo el cuerpo bloqueado.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Straddle L-Sit on Parallel Bars', 'Support yourself on the parallel bars with your legs raised straight out in a straddle, keeping your body stable and your arms locked.', 'bodyweight'),
('cd52169c-5ceb-4107-bfc5-b3ede3a950e6', 'Squat Snatch a una mano con mancuerna', 28, 29, 81, 1, 'Avanzado', 'Realiza un Snatch explosivo pero recibe la mancuerna en una posicion de sentadilla profunda antes de ponerte de pie.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Squat Snatch with Dumbbell', 'Perform an Explosive Snatch but receive the dumbbell in a deep squat position before standing up.', 'external'),
('cd6de5e6-f88b-4c8a-bc82-19b69bf5aa29', 'Overhead throw', 6, 25, 240, 1, 'Intermedio', 'Lanzamiento por encima de la cabeza como saque de banda en fútbol. Puede ser hacia adelante o hacia atrás. Involucra todo el cuerpo en el movimiento. Excelente para desarrollar potencia en la cadena posterior.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Overhead Throw', 'Overhead throw as a throw-in in soccer. It can be forward or backward. Involves the whole body in the movement. Excellent for developing power in the posterior chain.', 'external'),
('cd8a032c-5e47-45c4-84c2-9eea4208ffe9', 'Kettlebell Arm Bar a una mano', 6, NULL, 281, 1, 'Intermedio', 'Tumbado, sostén una Kettlebell bloqueada sobre el hombro y rueda el cuerpo hacia el lado opuesto, trabajando la estabilidad escapular.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'One-Handed Kettlebell Arm Bar', 'Lying down, hold a locked kettlebell over your shoulder and roll your body to the opposite side, working on scapular stability.', 'external'),
('cdea1c3e-dd43-43a8-b1da-abc22a1257a6', 'Salto pogo diagonal unilateral', 64, 37, 1, 1, 'Avanzado', 'Saltos pogo rápidos en diagonal sobre una sola pierna. Agilidad y potencia reactiva extrema. Cue: mantén el tobillo fuerte. Error común: pérdida de trayectoria diagonal.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Unilateral Diagonal Pogo Jump', 'Quick diagonal pogo jumps on one leg. Agility and extreme reactive power. Cue: keep your ankle strong. Common error: diagonal path loss.', 'bodyweight'),
('cdf7aa49-c794-433e-bc9c-6a37107fe843', 'Face pull con banda', 6, 71, 61, 1, 'Principiante', 'Ancla la banda a la altura de la cara. Tira de los extremos hacia tu cara separando las manos al acercarse, como si fueras a hacer una doble flexión de bíceps. Enfócate en llevar los codos hacia atrás y apretar los omóplatos. Excelente para la salud del hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Face pull with band', 'Anchor the band at face height. Pull the ends toward your face, spreading your hands apart as you approach, as if you were going to do a double bicep curl. Focus on bringing your elbows back and squeezing your shoulder blades. Excellent for shoulder health.', 'external'),
('ce1b6232-e6ba-452e-988e-7cef4014550f', 'Plancha invertida', 71, 29, 1, 24, 'Intermedio', 'Apoyo en talones y manos de espaldas al suelo, mantén cuerpo recto. Cue: empuja la cadera hacia arriba. Error: dejar caer la pelvis.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Reverse Plank', 'Support yourself on your heels and hands with your back facing the floor, keeping your body straight. Cue: push your hips up. Common mistake: letting your pelvis drop.', 'bodyweight'),
('ce2a4fd3-8565-4bb7-8007-6d428cb2c006', 'Sentadilla Pistola a cajón Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Sostén dos Kettlebells en posición rack. Realiza una sentadilla a una pierna bajando hasta tocar ligeramente un cajón y vuelve a subir manteniendo el equilibrio.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Front Rack Box Pistol Squat with Double kettlebell', 'Hold two kettlebells in a rack position. Perform a one-leg squat, going down until you lightly touch a box and go back up while maintaining balance.', 'external'),
('ce2bdf11-6f3b-49a2-b267-ff646ba8e738', 'Rodamiento una pierna', 25, NULL, 271, 1, 'Avanzado', 'Roll out manteniendo una pierna elevada del suelo. Añade componente de equilibrio y aumenta la activación del core. Comienza desde rodillas con una pierna extendida. Alterna piernas para trabajo equilibrado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One Leg Rolling', 'Roll out keeping one leg raised off the ground. Adds balance component and increases core activation. Start from your knees with one leg extended. Alternate legs for balanced work.', 'external'),
('ce35d826-1a54-47ec-bf32-4fab8249b5e8', 'Wall ball', 28, 6, 240, 1, 'Intermedio', 'Realiza una sentadilla sosteniendo el balón frente al pecho, y al subir lánzalo hacia un objetivo alto en la pared. Recíbelo y continúa con la siguiente repetición. Ejercicio metabólico completo muy usado en CrossFit.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Wall Ball', 'Perform a squat while holding the ball in front of your chest and, as you stand up, throw it toward a high target on the wall. Catch it and continue into the next repetition. This is a complete metabolic exercise widely used in CrossFit.', 'external'),
('ce74e73c-8db8-46ed-bc9d-989b5f4f7602', 'Russian Twist con pies elevados y Balón medicinal', 25, NULL, 240, 1, 'Intermedio', 'Mantén los pies sin tocar el suelo y gira el torso sujetando un balón medicinal, llevándolo de un costado al otro bajo control.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Russian Twist with raised feet and Medicine Ball', 'Keep your feet off the ground and twist your torso holding a medicine ball, moving it from one side to the other under control.', 'external'),
('ce80c510-2fd3-4e75-a56d-a83925f724f2', 'Peso muerto una pierna cable', 55, 29, 151, 1, 'Avanzado', 'RDL unilateral con cable bajo. La resistencia horizontal del cable añade componente de estabilización único. Excelente para equilibrio y propiocepción. Mantén cadera de la pierna de trabajo hacia atrás.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Leg Cable Deadlift', 'Single-leg RDL with a low cable. The cable’s horizontal resistance adds a unique stabilization component. Excellent for balance and proprioception. Keep the hip of the working leg back.', 'external'),
('ce9e9b23-ba59-4c9b-ad95-787a426c1163', 'Elevaciones de pantorrilla', 64, NULL, 1, 1, 'Principiante', 'De pie con los pies al ancho de las caderas, elévate sobre las puntas de los pies contrayendo los gemelos al máximo. Mantén la posición superior por un segundo y desciende controladamente sin que los talones toquen completamente el suelo. Puedes realizarlo en un escalón para mayor rango de movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Calf Raises', 'Standing with your feet hip-width apart, rise on the balls of your feet, contracting your calves as much as possible. Hold the top position for a second and descend controlledly without your heels completely touching the ground. You can do it on a step for greater range of motion.', 'mixed'),
('ced898b0-5381-4371-b713-2ed7adbf32c8', 'Flexiones cerradas', 2, 1, 1, 1, 'Intermedio', 'Flexiones manos ancho hombros codos pegados. Objetivo: tríceps. Cue: roza costados. Error: abrir codos.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Closed Push-ups', 'Push-ups hands wide shoulders elbows together. Target: triceps. Cue: rubs sides. Common mistake: open elbows.', 'mixed'),
('cf3b38a4-f312-4354-96f9-9a6bc21df0d0', 'Press banca barra', 1, 2, 116, 1, 'Intermedio', 'Túmbate en banco plano con los pies firmemente plantados. Agarra la barra con las manos más separadas que el ancho de los hombros. Desciende la barra controladamente hasta tocar ligeramente el pecho y presiona explosivamente hasta la extensión completa. Mantén los omóplatos retraídos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar bench press', 'Lie on a flat bench with your feet firmly planted. Grip the bar with your hands wider than shoulder width apart. Lower the bar under control until it lightly touches your chest and press explosively to full extension. Keep your shoulder blades retracted.', 'external'),
('cf3b3907-2892-45e3-aadd-e849008fdfe8', 'Zancadas mancuernas', 28, 29, 81, 1, 'Intermedio', 'Con una mancuerna en cada mano a los lados, realiza zancadas manteniendo el torso erguido. El peso adicional aumenta la intensidad del ejercicio y desafía más el equilibrio. Puedes realizar zancadas estáticas, alternadas o caminando.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Lunges', 'With one dumbbell in each hand at your sides, perform lunges while keeping your torso upright. The added weight increases the intensity of the exercise and challenges your balance more. You can do them as stationary, alternating, or walking lunges.', 'external'),
('cf5bd36f-7f48-4d31-a636-7c862ed46e97', 'Extensiones de tríceps en TRX', 2, 25, 216, 1, 'Intermedio', 'Inclinado hacia adelante sujetando el TRX, flexiona codos para llevar las manos a la frente y extiende. Objetivo: tríceps. Cue: codos siempre apuntando adelante. Error: arquear la espalda baja.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'TRX Triceps Extensions', 'Lean forward while holding the TRX handles, bend your elbows to bring your hands toward your forehead, and then extend back out. Target: triceps. Cue: keep your elbows pointing forward. Common mistake: arching the lower back.', 'bodyweight'),
('cf9095c2-23e7-400a-ac43-ca373a432ca2', 'Press Z con agarre aplastante y mancuernas', 6, 2, 81, 1, 'Intermedio', 'Siéntate en el suelo con las piernas extendidas en V. Sostén una mancuerna con ambas manos presionándola contra el pecho y empújala verticalmente sobre la cabeza sin apoyar la espalda.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Z Press with Crushing Grip and Dumbbells', 'Sit on the floor with your legs extended in a V. Hold a dumbbell with both hands, pressing it against your chest, and push it vertically over your head without supporting your back.', 'external'),
('cfca28d9-82b7-414c-bdfb-ac76e8627d8e', 'Bodyweight Seated Ab Circles', 25, NULL, 1, 1, 'Principiante', 'Siéntate en el suelo con las manos apoyadas atrás y las piernas levantadas. Dibuja círculos grandes en el aire con ambos pies juntos, manteniendo el control desde el abdomen.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Seated Ab Circles', 'Sit on the floor with your hands behind you and your legs raised. Draw large circles in the air with both feet together, maintaining control from your abs.', 'bodyweight'),
('cfe4db42-291a-43c5-9b5b-efc66fead217', 'Salto al cajón lastrado', 28, 29, 81, 1, 'Avanzado', 'Salta a un cajón con chaleco o mancuernas. Máxima potencia explosiva. Cue: aterriza con suavidad extrema. Error común: usar demasiado peso que comprometa la altura.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Weighted Box Jump', 'Jump onto a box with a vest or dumbbells. Maximum explosive power. Cue: lands extremely softly. Common mistake: using too much weight that compromises height.', 'external'),
('cfec5336-d5ab-424e-80de-4cc29e51342f', 'Remo Pendlay alterno con mancuerna a una mano', 71, 17, 81, 1, 'Principiante', 'Con el torso paralelo al suelo, rema una mancuerna desde el suelo hasta el costado mientras la otra descansa, alternando brazos.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Hand Alternate Dumbbell Pendlay Row', 'With your torso parallel to the floor, row one dumbbell from the floor to your side while the other rests, alternating arms.', 'external'),
('d03556f4-9f18-4b8c-b45d-d91b13bd6848', 'Dislocaciones de hombro con banda elástica', 6, 71, 61, 1, 'Principiante', 'Sujeta la banda con un agarre ancho y pásala sobre tu cabeza hacia la espalda y de regreso, manteniendo los brazos rectos para ganar movilidad.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Elastic Band Shoulder Dislocations', 'Hold the band with a wide grip and pass it over your head to your back and back, keeping your arms straight to gain mobility.', 'external'),
('d056d3a0-07ad-4a63-9534-741039c5c63f', 'Zancada posterior battle ropes', 28, 6, 256, 24, 'Avanzado', 'Zancadas hacia atrás mientras mantienes ondas constantes. Coordinación desafiante entre tren superior e inferior. Mantén el torso erguido y las ondas consistentes. Alterna piernas manteniendo el ritmo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rear stride battle ropes', 'Stride backwards while maintaining steady waves. Challenging coordination between upper and lower body. Keep your torso upright and waves consistent. Alternate legs while keeping pace.', 'external'),
('d076c1c3-db7b-4e3d-a680-7d3c6fbbc950', 'Dominadas neutras', 16, 17, 1, 1, 'Intermedio', 'Utiliza barras paralelas o agarres neutros donde las palmas se miran entre sí. Esta posición es más natural para las muñecas y permite un trabajo equilibrado entre dorsales y bíceps. Eleva el cuerpo manteniendo los codos cerca del torso y desciende controladamente hasta la extensión completa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Neutral pull-ups', 'Use parallel bars or neutral grips where your palms face each other. This position is more natural for the wrists and allows balanced work between the lats and biceps. Raise your body, keeping your elbows close to your torso, and lower yourself controlled to full extension.', 'mixed'),
('d09f5ade-8587-4362-b44e-a5ba7e60ce52', 'Crunch TRX', 25, NULL, 216, 1, 'Intermedio', 'En plancha con pies en las correas, lleva las rodillas hacia el pecho realizando una flexión de cadera y columna. La inestabilidad del TRX intensifica el trabajo abdominal. Controla el retorno a la posición inicial.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Crunch', 'In a plank with feet on the straps, bring your knees towards your chest, flexing your hips and spine. The instability of the TRX intensifies abdominal work. Controls the return to the initial position.', 'bodyweight'),
('d0d6afab-af7d-4738-9136-510e8c5abebd', 'Sóleo sentado barra', 309, 64, 116, 1, 'Principiante', 'Barra en muslos sentado, eleva talones. Objetivo: sóleo. Cue: rango completo. Error: rango corto.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Seated Barbell Soleus Raise', 'With the bar resting across your thighs in a seated position, raise your heels. Target: soleus. Cue: use a full range of motion. Common mistake: using a short range.', 'external'),
('d0fc4110-985d-4f9c-a2f1-804ecb870b25', 'Ring Hanging Leg Raise', 25, 100, 1, 1, 'Avanzado', 'Cuélgate de las anillas. Manteniendo las piernas rectas y juntas, elévalas hasta que estén paralelas al suelo o más alto, usando la fuerza abdominal.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Hanging Leg Raise', 'Hang on the rings. Keeping your legs straight and together, raise them until they are parallel to the floor or higher, using abdominal strength.', 'bodyweight'),
('d12d829d-6b09-48f2-a57e-49d0ec96f2c8', 'Remo polea baja agarre neutro', 71, 16, 151, 1, 'Intermedio', 'Realiza un remo en polea baja con agarre neutro. Tira del agarre hacia el abdomen manteniendo la espalda estable y controla la fase de vuelta.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Neutral Grip Seated Cable Row', 'Perform a neutral grip seated cable row. Pull the handle toward the abdomen while keeping the back stable and control the return phase.', 'external'),
('d1b9bf3a-70bc-4845-87b5-a036eacfa72e', 'Flexiones archer', 1, 2, 1, 1, 'Avanzado', 'Comienza con las manos muy separadas, más anchas que los hombros. Al descender, dirige el peso corporal hacia un brazo mientras el otro se extiende lateralmente. Alterna el lado de trabajo en cada repetición o completa series por lado. Este ejercicio es una progresión hacia las flexiones a un brazo y requiere gran fuerza unilateral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Archer Push-ups', 'Start with your hands wide apart, wider than your shoulders. As you descend, direct your body weight toward one arm while the other extends laterally. Alternate working side each rep or complete sets per side. This exercise is a progression towards one-arm push-ups and requires great unilateral strength.', 'mixed'),
('d205ca05-20e0-497c-8e84-ad86d125250c', 'Hollow Body Flutter Kicks con Kettlebell a una mano', 25, NULL, 281, 1, 'Intermedio', 'En posicion de Hollow Body, sostén una pesa rusa sobre el pecho con una mano y realiza patadas de aleteo para trabajar el core.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Hollow Body Flutter Kicks with One-Handed Kettlebell', 'In Hollow Body position, hold a kettlebell across your chest with one hand and perform flutter kicks to work your core.', 'external'),
('d20b8f1b-fcbc-4206-842f-04cd579df5e7', 'Hollow Body Rock', 25, NULL, 1, 1, 'Intermedio', 'En posicion de Hollow Body (lumbares pegadas al suelo, extremidades elevadas), balanceate como una cuna manteniendo la tension abdominal constante.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Hollow Body Rock', 'In a Hollow Body position (lumbars close to the floor, limbs raised), swing like a cradle, maintaining constant abdominal tension.', 'bodyweight'),
('d20f418f-7140-4c79-b887-e119d4076da0', 'Sentadilla Overhead con Kettlebell a una mano Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Mantén una Kettlebell invertida sobre la cabeza con el brazo bloqueado mientras realizas una sentadilla profunda, exigiendo máxima concentración y equilibrio.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-Handed kettlebell Overhead Squat Bottoms Up', 'Hold an inverted kettlebell overhead with your arm locked while performing a deep squat, demanding maximum concentration and balance.', 'external'),
('d21295a3-5988-4881-ba94-f6af36a502fd', 'Spider Curl con cable y barra recta', 17, NULL, 151, 1, 'Principiante', 'Boca abajo en un banco inclinado frente a la polea, realiza un curl con barra recta permitiendo que los brazos cuelguen verticalmente.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Spider Curl with cable and straight bar', 'Face down on an incline bench in front of the cable, perform a straight barbell curl allowing your arms to hang vertically.', 'external'),
('d2844d02-68cf-48a6-b0c4-81380c502537', 'Paseo de maleta (Suitcase Carry)', 25, 13, 81, 24, 'Principiante', 'Camina una distancia cargando una mancuerna pesada en un solo lado del cuerpo. Objetivo: estabilidad anti-lateral del core. Cues: mantén los hombros nivelados y no permitas que el peso te incline. Error común: inclinar el torso hacia el lado opuesto a la carga.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Suitcase Carry', 'Walk a distance carrying a heavy dumbbell on one side of your body. Target: anti-lateral stability of the core. Cue: Keep your shoulders level and don''t let the weight tilt you. Common mistake: leaning your torso away from the load.', 'external'),
('d28b4f5d-ea14-462a-bc88-13fb010e14f8', 'Sentadilla Ciclista Overhead con Kettlebell doble', 28, 6, 281, 1, 'Intermedio', 'Realiza una sentadilla ciclista manteniendo dos Kettlebells bloqueadas sobre la cabeza, exigiendo movilidad de tobillo y hombro.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Double kettlebell Overhead Cycle Squat', 'Perform a bicycle squat while keeping two kettlebells locked above your head, requiring ankle and shoulder mobility.', 'external'),
('d2a24096-fea4-4d19-a58a-e8d6ea47027f', 'Pike Pushups', 6, 2, 1, 1, 'Intermedio', 'En V invertida, baja la cabeza hacia el suelo entre las manos. Progresión para hombros. Cue: codos hacia atrás. Error: apoyar la parte superior de la cabeza.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Pike Push-ups', 'From an inverted V position, lower your head toward the floor between your hands. It is a progression for shoulder strength. Cue: keep your elbows back. Common mistake: placing the top of your head on the floor.', 'mixed'),
('d2de6f75-39ab-4b5c-a682-5889501b4a4b', 'Curl martillo cable', 17, 100, 151, 1, 'Principiante', 'Usando un agarre de cuerda en polea baja, realiza curls manteniendo las palmas enfrentadas. Este agarre neutro trabaja el braquial y braquiorradial además del bíceps. Mantén las muñecas firmes y los codos pegados al cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Hammer Curl', 'Using a low cable rope grip, perform curls while keeping your palms facing each other. This neutral grip works the brachialis and brachioradialis in addition to the biceps. Keep your wrists firm and your elbows close to your body.', 'external'),
('d2fa82d7-b9af-4dbc-a705-b073f7f9dbfb', 'Burpee con salto de valla', 13, 64, 1, 1, 'Avanzado', 'Realiza un burpee y termina saltando frontalmente sobre una valla. Cue: máxima altura de salto tras el burpee. Error común: falta de energía para superar la valla.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Burpee with Hurdle Jump', 'Perform a burpee and finish with a front jump over a fence. Cue: maximum jump height after the burpee. Common mistake: lack of energy to overcome the fence.', 'bodyweight'),
('d304a89f-9df1-4f49-a775-4da158b55edc', 'Encogimientos de hombros con mancuernas', 71, 6, 81, 1, 'Principiante', 'Eleva los hombros hacia las orejas manteniendo brazos rectos. Enfoque en trapecio. Cabeza recta. No rotes los hombros al subir.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Dumbbell Shrugs', 'Raise your shoulders towards your ears, keeping your arms straight. Focus on trapezoid. Straight head. Do not rotate your shoulders when going up.', 'external'),
('d3402384-6c36-4188-9de2-3e35cd6fdeb4', 'Paseo del granjero (Farmer Carry)', 13, 100, 81, 24, 'Principiante', 'Camina una distancia cargando mancuernas pesadas a los lados. Objetivo: fuerza de agarre y estabilidad total. Cue: pasos cortos y firmes. Error común: encoger los hombros hacia arriba.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Farmer Carry', 'Walk a distance carrying heavy dumbbells at your sides. Target: grip strength and total stability. Cue: short, firm steps. Common mistake: shrugging your shoulders up.', 'external'),
('d350c24e-b886-42d4-908f-da675fffbd6f', 'Salto vertical sentadilla profunda', 28, 29, 1, 1, 'Intermedio', 'Salta y al aterrizar baja inmediatamente a una sentadilla profunda controlada. Cue: clava los talones al aterrizar. Error común: rodillas colapsadas al amortiguar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump Deep Squat', 'Jump and upon landing immediately lower yourself into a controlled deep squat. Cue: dig your heels in as you land. Common mistake: knees collapsing when cushioning.', 'mixed'),
('d390c896-e1b7-454d-8aa0-4e083b7f089e', 'Jalón al pecho neutro', 16, 17, 186, 1, 'Principiante', 'Tira de la barra hacia el pecho con palmas enfrentadas (agarre neutro). Objetivo: amplitud dorsal. Cue: codos hacia abajo. Error común: balancear el torso hacia atrás para ayudar.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Neutral Chest Pull', 'Pull the bar toward your chest with palms facing each other (neutral grip). Target: dorsal width. Cue: elbows down. Common mistake: Swinging your torso back to help.', 'external'),
('d39f2d8e-008a-40a2-829c-cad334e4ebbc', 'Remo en polea baja sentado', 71, 17, 151, 1, 'Principiante', 'Tira del agarre hacia el abdomen manteniendo la espalda recta. Cue: retracción escapular previa. Error: encorvar la espalda al estirar brazos.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Seated Low Pulley Row', 'Pull the grip towards your abs, keeping your back straight. Cue: prior scapular retraction. Common mistake: hunching your back when stretching your arms.', 'external'),
('d43d143f-f82a-4039-8963-ab0643c7eac8', 'Flexiones archer TRX', 1, 2, 216, 1, 'Avanzado', 'Flexiones dirigiendo el peso hacia un brazo con pies en TRX. Combina el desafío unilateral con inestabilidad. Progresión avanzada hacia flexiones a un brazo. Controla la velocidad del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Archer TRX push-ups', 'Push-ups directing the weight towards one arm with feet in TRX. It combines unilateral defiance with instability. Advanced progression towards one-arm push-ups. Control the speed of movement.', 'mixed'),
('d4623027-a223-4c6f-af94-133c4105ae1a', 'Clean alterno con Kettlebell a una mano', 29, 71, 281, 1, 'Intermedio', 'Lleva la Kettlebell desde el suelo hasta la posicion de rack, alternando el brazo en cada repeticion mediante un movimiento fluido de cadera.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Alternate Clean with One-Handed Kettlebell', 'Bring the kettlebell from the floor to the rack position, alternating your arm on each repetition using a fluid hip movement.', 'external'),
('d46ed7f4-cbb3-49b9-b25a-665d23a78aa3', 'Sentadilla Split Overhead contralateral rodilla sobre punta del pie', 28, 6, 81, 1, 'Avanzado', 'Realiza una sentadilla split con mancuerna sobre la cabeza en el lado opuesto, permitiendo que la rodilla delantera avance sobre los dedos del pie.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Overhead Split Squat with Knee Over Toe', 'Perform an overhead dumbbell split squat on the opposite side, allowing your front knee to come over your toes.', 'external'),
('d4758898-438c-4bad-b2ea-d4fc94a3a3b0', 'Leñador con mancuerna lateral', 25, 6, 81, 1, 'Intermedio', 'Movimiento diagonal de abajo a arriba con mancuerna. Cue: pivota pie. Error: arquear lumbar.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Side Dumbbell Lumberjack', 'Diagonal movement from bottom to top with dumbbell. Cue: pivot foot. Common mistake: arching your lower back.', 'external'),
('d4a077ae-51ba-414c-b800-d8db094bacf1', 'Dragon Flag estricto', 25, 71, 1, 1, 'Avanzado', 'Tumbado, agarra un punto fijo tras la cabeza y eleva todo el cuerpo en línea recta apoyado solo en hombros. Objetivo: fuerza abdominal extrema. Cues: cuerpo rígido como una viga. Error común: doblar la cadera al subir o bajar.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Strict Dragon Flag', 'Lying down, grab a fixed point behind your head and raise your entire body in a straight line supported only by your shoulders. Target: extreme abdominal strength. Cue: rigid body like a beam. Common mistake: bending the hips when going up or down.', 'bodyweight'),
('d4a806c3-39fa-4065-b182-c524b23179b5', 'Remo con banda elástica sentado', 71, 17, 61, 1, 'Principiante', 'Sentado con piernas estiradas, rodea los pies con la banda y tira de los extremos hacia tu abdomen. Objetivo: espalda media. Cue: saca pecho y retrae escápulas. Error: encoger los hombros hacia arriba.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Seated Band Row', 'Sitting with your legs straight, wrap the band around your feet and pull the ends toward your abs. Target: mid back. Cue: stick out your chest and retract your scapulae. Common mistake: shrugging your shoulders up.', 'external'),
('d4bc3ae1-131e-420e-a9ff-c7c88ea92394', 'Patada de glúteo medio en cable', 29, 37, 151, 1, 'Intermedio', 'Con el estribo en el tobillo, desplaza la pierna hacia atrás y ligeramente hacia afuera. Objetivo: glúteo mayor y medio. Cues: no arquees la espalda baja. Error común: usar el impulso del tronco para mover el peso.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Cable Glute Medius Kick', 'With the stirrup at the ankle, move the leg back and slightly outward. Target: glutes maximus and medius. Cue: don''t arch your lower back. Common mistake: using torso momentum to move weight.', 'external'),
('d4d52eda-120f-4a3f-9051-19d7c6ad66dc', 'Split Clean a Split Jerk a una mano en Landmine', 13, 6, 116, 1, 'Avanzado', 'Realiza una cargada explosiva a una mano seguida de un envión recibiendo el peso en posición de zancada (split), utilizando una barra Landmine.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Split Clean to Split Jerk to one hand in Landmine', 'Perform an explosive clean with one hand followed by a clean and jerk receiving the weight in a lunge position (split), using a Landmine bar.', 'external'),
('d4d8f878-6daf-4727-a7ae-e38c534dfa85', 'Remo un brazo TRX', 16, 25, 216, 1, 'Avanzado', 'Remo unilateral que maximiza la inestabilidad. Requiere fuerza anti-rotación significativa del core. Permite mayor rango de movimiento que remo bilateral. Mantén caderas y hombros cuadrados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I row one arm TRX', 'Unilateral rowing that maximizes instability. Requires significant anti-rotation core strength. Allows greater range of motion than bilateral rowing. Keep hips and shoulders square.', 'bodyweight'),
('d4eb09d3-0aa3-4b34-ae4a-97897fa30a70', 'Sentadilla isométrica pared', 28, NULL, 1, 24, 'Principiante', 'Espalda apoyada, rodillas a 90 grados, mantén la posición. Resistencia muscular. Espalda plana. No apoyes las manos en los muslos.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Isometric wall squat', 'Back supported, knees at 90 degrees, maintain position. Muscular resistance. Flat back. Don''t rest your hands on your thighs.', 'mixed'),
('d4fbb1e2-3903-42bb-8c52-cacb1d7392f8', 'Flexión en anillas', 1, 2, 1, 1, 'Intermedio', 'Realiza flexiones sujetando las anillas cerca del suelo, lo que añade un componente de inestabilidad que activa intensamente el pecho y el core.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Ring Push-Up', 'Perform push-ups holding the rings close to the floor, which adds a component of instability that intensely activates the chest and core.', 'mixed'),
('d5073fde-69bc-4c5b-b974-42d2731f9fc7', 'Reverse crunch', 25, 13, 1, 1, 'Principiante', 'Realiza un reverse crunch tumbado boca arriba. Lleva las rodillas hacia el pecho elevando ligeramente la pelvis y controla la bajada sin arquear la zona lumbar.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Reverse Crunch', 'Perform a reverse crunch lying on your back. Bring the knees toward the chest while slightly lifting the pelvis and control the lowering phase without arching the lower back.', 'bodyweight'),
('d52949fc-5116-4a59-a3a9-291625bf4f87', 'Squat jump con caída controlada', 28, 29, 1, 1, 'Intermedio', 'Realiza un salto desde posición de sentadilla y aterriza de forma controlada, absorbiendo el impacto con cadera, rodillas y tobillos alineados.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Squat Jump with Controlled Landing', 'Perform a jump from a squat position and land under control, absorbing impact with the hips, knees, and ankles aligned.', 'mixed'),
('d5680a67-71ba-41c3-b87b-f32d2e4e11a2', 'Zancada lateral con Slider y Kettlebell (Maleta)', 28, 29, 281, 1, 'Principiante', 'Sostén dos Kettlebells a los lados y desliza un pie lateralmente sobre un slider, bajando la cadera mientras la otra pierna permanece recta.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Lateral stride with Slider and Kettlebell (Suitcase)', 'Hold two kettlebells to the sides and slide one foot sideways over a slider, lowering the hip while the other leg remains straight.', 'external'),
('d5a8809a-ff94-4108-9b5c-9ea633c115b8', 'Elevaciones frontales barra recta', 6, NULL, 116, 1, 'Principiante', 'Eleva barra al frente. Objetivo: deltoide anterior. Cue: no usar cadera. Error: arquear espalda.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Straight Bar Front Raises', 'Raise bar in front. Target: anterior deltoid. Cue: don''t use hip. Common mistake: arching your back.', 'external'),
('d5b2af46-a4ed-4b3c-9971-c897eb45b195', 'Remo prono alterno con Kettlebell doble', 71, 17, 281, 1, 'Principiante', 'Tumbado boca abajo, rima las pesas rusas de forma alternada hacia la cadera, manteniendo el torso estable y evitando rotaciones innecesarias.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double kettlebell Alternating Prone Row', 'Lying face down, swing the kettlebells alternately toward your hips, keeping your torso stable and avoiding unnecessary rotations.', 'external'),
('d5bd933e-b570-4ede-acf4-b9f3a0e64aa7', 'Giro ruso (Russian Twist)', 25, 71, 1, 1, 'Principiante', 'Sentado con pies en aire, gira el torso de lado a lado con un peso. Objetivo: fuerza de los oblicuos. Cue: gira los hombros, no solo los brazos. Error común: encorvar excesivamente la espalda.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Russian Twist', 'Sitting with your feet in the air, rotate your torso from side to side with a weight. Target: oblique strength. Cue: rotate your shoulders, not just your arms. Common mistake: excessively hunching your back.', 'bodyweight'),
('d5d9da31-3414-4235-a97d-b3ca99eb71a2', 'Single leg squat TRX', 28, 29, 216, 1, 'Avanzado', 'Sentadilla a una pierna asistida con TRX. Las correas proporcionan el apoyo necesario para mantener el equilibrio mientras trabajas en el patrón de movimiento. Progresión hacia la sentadilla pistol completa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single leg squat TRX', 'TRX assisted single leg squat. The straps provide the support needed to maintain balance while working on the movement pattern. Progression towards the full pistol squat.', 'assisted'),
('d61a09a4-e0f9-45f7-8e33-64fa312c79c5', 'Elevaciones laterales en polea', 6, NULL, 151, 1, 'Intermedio', 'Eleva el cable lateralmente por detrás del cuerpo para mayor tensión. Control de bajada. Hombro bajo. No uses el trapecio excesivamente.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Cable Lateral Raises', 'Raise the cable laterally behind the body for added tension. Descent control. Low shoulder. Don''t use the trapeze excessively.', 'external'),
('d647a097-fc37-4394-acdb-314df0b50ba6', 'Wrist curl barra', 100, NULL, 116, 1, 'Principiante', 'Sentado con los antebrazos apoyados en los muslos o un banco, realiza flexiones de muñeca con la barra. Puedes hacerlo con agarre supino para flexores o prono para extensores. Permite que la barra ruede hasta los dedos para mayor rango de movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Wrist Curl', 'Seated with your forearms resting on your thighs or a bench, perform wrist curls with the barbell. You can do them with an underhand grip for the flexors or an overhand grip for the extensors. Let the bar roll toward your fingers for a greater range of motion.', 'external'),
('d64b749b-6234-41fa-9f0b-5d681fd6e289', 'Press Z Seesaw con Kettlebell doble Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'Sentado en el suelo, alterna el press vertical de dos Kettlebells invertidas en movimiento de balancín, eliminando todo impulso.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Press Z Seesaw with Double kettlebell Bottoms Up', 'Sitting on the floor, alternate the vertical press of two inverted kettlebells in a rocking motion, eliminating all momentum.', 'external'),
('d6663af4-0b56-48fb-a7d8-7a7404d35569', 'Lanzamiento pecho una pierna', 1, 29, 240, 1, 'Avanzado', 'Lanza el balón medicinal de pecho mientras te mantienes en equilibrio sobre una sola pierna. Estabilidad extrema. Cue: core muy apretado. Error común: perder el equilibrio antes del lanzamiento.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'One Leg Chest Throw', 'Throw the medicine ball while standing on one leg. Extreme stability. Cue: very tight core. Common mistake: losing balance before launching.', 'external'),
('d67e21a3-9354-4861-84f3-74b41bcde6ac', 'Curl bíceps unilateral polea baja', 17, NULL, 151, 1, 'Principiante', 'Flexiona cable a un brazo. Cue: codo fijo. Error: balancear cuerpo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Unilateral Low Cable Biceps Curl', 'Cable flex with one arm. Cue: fixed elbow. Common mistake: balance body.', 'external'),
('d6801b6f-dbb9-46aa-aaf5-5aa872d52a95', 'Superman alterno', 71, 29, 1, 1, 'Principiante', 'Tumbado boca abajo, eleva brazo derecho y pierna izquierda simultáneamente, alterna lados. Objetivo: fortalecimiento lumbar y coordinación. Cues: mira hacia el suelo. Error común: realizar tirones bruscos con el cuello.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Alternating Superman', 'Lie face down and raise your right arm and left leg at the same time, then alternate sides. Target: lower back and posterior chain.', 'bodyweight'),
('d69f1b2e-f6e2-4c6b-8d73-895a86fc3263', 'Press Arnold con mancuernas', 6, 2, 81, 1, 'Intermedio', 'Press con rotación tipo Arnold para trabajar hombro con gran rango, controlando la rotación y la estabilidad escapular.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Dumbbell Arnold Press', 'Press with Arnold-type rotation to work shoulder with great range, controlling rotation and scapular stability.', 'external'),
('d6a89985-9d91-4801-abb4-a32a98d9481f', 'Curl bíceps máquina apoyo', 17, NULL, 186, 1, 'Principiante', 'Flexiona brazos apoyados en máquina. Cue: rango total. Error: no estirar del todo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Supported Machine Biceps Curl', 'Curl your arms while supported on the machine. Cue: use a full range of motion. Common mistake: not fully extending at the bottom.', 'external'),
('d6dfcd47-1602-429d-b6ff-53e52cee37ea', 'Remo apoyado en banco con mancuernas', 71, 17, 81, 1, 'Principiante', 'Boca abajo en banco inclinado a 45 grados, rema con las mancuernas hacia la cadera. Objetivo: espalda media sin carga lumbar. Cue: junta las escápulas arriba. Error común: despegar el pecho del banco.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Dumbbell Bench Row', 'Face down on a 45-degree incline bench, row with the dumbbells toward your hips. Target: middle back without lumbar load. Cue: bring your shoulder blades together above. Common mistake: lifting your chest off the bench.', 'external'),
('d6e5fb5a-048d-4eee-841c-9922dd7673a4', 'Press Overhead con barra Z', 6, 2, 116, 1, 'Principiante', 'Empuja la barra Z desde los hombros hasta bloquear los brazos por encima de la cabeza, manteniendo el core estable y la espalda recta.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Overhead Press with Z Bar', 'Push the Z bar from your shoulders until you lock your arms above your head, keeping your core stable and your back straight.', 'external'),
('d6f5b866-98e6-4cf7-83ff-3735df800be5', 'Tríceps barra V nuca cable inclinado', 2, NULL, 151, 1, 'Intermedio', 'Inclinado adelante, extiende cable tras nuca. Cue: codos cerrados. Error: arquear espalda.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Incline Cable Behind-the-Head V-Bar Triceps Extension', 'Lean forward and extend the cable behind your head using a V-bar attachment. Cue: keep your elbows tucked in. Common mistake: arching your back.', 'external'),
('d6f64112-35b8-482e-807c-7e20bf4b5bfe', 'Remo Landmine a una mano', 71, 17, 116, 1, 'Intermedio', 'De pie junto a la barra Landmine, inclina el torso y agarra el extremo de la barra. Tira del codo hacia atrás activando el dorsal.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'One-handed Landmine rower', 'Standing next to the Landmine bar, bend your torso and grab the end of the bar. Pull your elbow back, activating your dorsal.', 'external'),
('d6f92005-3cb7-4dce-904a-194fdb3a83b6', 'Sentadilla cosaca Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Intermedio', 'Sentadilla lateral profunda con dos pesas rusas en el pecho (front rack), enfocando el esfuerzo en los aductores y la estabilidad del tronco.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Front Rack Cossack Squat with Double kettlebell', 'Deep lateral squat with two kettlebells on the chest (front rack), focusing the effort on the adductors and torso stability.', 'external'),
('d709615b-cf3d-4e71-96f5-6377f3bbf0c5', 'Aductores en polea baja', 313, 25, 151, 1, 'Principiante', 'De lado a la polea, cruza la pierna por delante. Fuerza interna. Cuerpo erguido. No inclines el torso lateralmente.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Adductors in low pulley', 'Standing sideways to the pulley, cross your leg in front of you. Internal strength. Upright body. Do not tilt your torso laterally.', 'external'),
('d7c98411-b30f-4a3d-9ba5-082861c89166', 'Remo mentón polea baja', 6, 71, 151, 1, 'Principiante', 'Tira barra al mentón codos altos. Objetivo: deltoides. Cue: barra cerca cuerpo. Error: tirones.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Low Cable Chin Row', 'Pull bar to the chin with high elbows. Target: deltoid. Cue: bar close to body. Common mistake: jerks.', 'external'),
('d839306f-d3dc-47ea-8345-d15f06fa9c2f', 'Tríceps Pushdown', 2, NULL, 151, 1, 'Principiante', 'Empuja la polea hacia abajo bloqueando codos. Objetivo: aislamiento de tríceps. Cue: codos pegados a los costados. Error común: inclinar el torso sobre la barra.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Triceps Pushdown', 'Push the cable down while keeping your elbows locked at your sides. Target: triceps isolation. Cue: keep your elbows close to your torso. Common mistake: leaning your torso over the bar.', 'external'),
('d839527d-ca24-4505-b12b-15f170d3a884', 'Kettlebell Windmill', 25, 6, 281, 1, 'Avanzado', 'Pesa arriba, inclina el torso lateralmente para tocar el pie opuesto. Mejora flexibilidad y estabilidad. Mira la pesa siempre. No dobles la rodilla superior.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Kettlebell Windmill', 'Weight up, tilt your torso sideways to touch the opposite foot. Improves flexibility and stability. Always look at the weight. Do not bend your top knee.', 'external'),
('d84538df-3915-4bab-89f9-834e6d43ba71', 'Sentadilla Ciclista Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'El nivel maximo de estabilidad: realiza una sentadilla ciclista con dos Kettlebells invertidas sostenidas sobre la cabeza.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Double kettlebell Bottoms Up Overhead Cycle Squat', 'Maximum level of stability: Perform a bicycle squat with two inverted kettlebells held overhead.', 'external'),
('d86aa0bf-db5e-4734-a6f1-4ec524b08306', 'Remo prono alterno en banco inclinado con Kettlebell doble', 71, 17, 281, 1, 'Intermedio', 'Boca abajo en un banco inclinado, rema las Kettlebells alternativamente hacia tu cadera manteniendo el pecho apoyado y la espalda neutra.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double kettlebell Incline Bench Alternating Prone Row', 'Face down on an incline bench, row the kettlebells alternately toward your hips, keeping your chest supported and your back neutral.', 'external'),
('d895c492-7ed5-4f87-b480-014fa7e3a1d4', 'Rebotes pogo rápidos', 64, 309, 1, 1, 'Intermedio', 'Saltos cortos y rápidos de tobillo minimizando el contacto con el suelo. Cue: rodillas casi bloqueadas. Error: apoyar el talón.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Fast Pogo Bounces', 'Short, quick ankle jumps minimizing contact with the ground. Cue: knees almost locked. Common mistake: heel support.', 'bodyweight'),
('d8acd8cc-9abe-42b4-94fc-8d7259896526', 'Crunch oblicuo sobre Fitball', 25, NULL, 290, 1, 'Principiante', 'Apoya la zona lumbar en el Fitball y realiza una flexion abdominal lateral para llevar el hombro hacia la cadera opuesta.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Oblique crunch on Stability Ball', 'Support your lower back on the Stability Ball and perform a lateral abdominal flexion to bring your shoulder towards the opposite hip.', 'bodyweight'),
('d8b103b5-bda0-412f-858f-226736521490', 'Sentadilla Búlgara Overhead contralateral con mancuerna', 28, 6, 81, 1, 'Avanzado', 'Con un pie elevado atrás, sostén una mancuerna bloqueada sobre la cabeza con el brazo opuesto a la pierna delantera y realiza la sentadilla.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Overhead Bulgarian Split Squat with Dumbbell', 'With one foot raised behind you, hold a dumbbell locked overhead with the arm opposite your front leg and perform the squat.', 'external'),
('d945a5f3-2c23-4c75-b3f1-796b4d77bf5d', 'Aperturas de pecho en máquina (Pec Deck)', 1, 6, 186, 1, 'Principiante', 'Sentado, junta los agarres frente al pecho manteniendo una ligera flexión de codos. Objetivo: aislamiento de pectoral. Cue: aprieta al centro 1 segundo. Error: permitir que los hombros se adelanten al cerrar.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Machine Chest Openings (pec Deck)', 'Sitting, bring your grips together in front of your chest, maintaining a slight bend in your elbows. Target: chest isolation. Cue: press to the center for 1 second. Common mistake: Allowing the shoulders to come forward when closing.', 'external'),
('d95dfcbb-8a5b-4d98-80e6-e3effad229ff', 'Elevaciones laterales inclinado', 6, NULL, 81, 1, 'Intermedio', 'Elevación lateral con el torso inclinado para enfocar deltoide medio con más tensión y menos impulso.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Incline lateral raises', 'Side raise with tilted torso to target middle deltoid with more tension and less momentum.', 'external'),
('d967860d-f7d9-496f-af1d-b69e1db717e4', 'Face pull TRX', 6, 71, 216, 1, 'Intermedio', 'Tira de las correas hacia la cara separando las manos al acercarse. Excelente para deltoides posterior y salud del hombro. Mantén los codos altos y enfócate en la rotación externa de hombros al final del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Face pull TRX', 'Pull the straps towards your face, spreading your hands as you approach. Excellent for posterior deltoid and shoulder health. Keep your elbows high and focus on shoulder external rotation at the end of the movement.', 'bodyweight'),
('d9ca90bc-f940-4ae2-b261-07637f2f39ce', 'Floor Press con Puente de Glúteo y mancuernas', 1, 29, 81, 1, 'Intermedio', 'Mantén la posición alta de un puente de glúteo mientras realizas un press de pecho con mancuernas desde el suelo.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Floor Press with Glute Bridge and dumbbells', 'Hold the high position of a glute bridge while performing a dumbbell chest press from the floor.', 'external'),
('d9f65da1-4e22-4131-8235-33022687c7ca', 'Step Up Overhead contralateral con Kettlebell a una mano', 28, 6, 281, 1, 'Avanzado', 'Con una Kettlebell bloqueada sobre la cabeza, sube al banco con la pierna opuesta al brazo que carga el peso.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Single-Kettlebell Overhead Step-up', 'With one kettlebell locked out overhead, step onto the bench with the leg opposite the loaded arm.', 'external'),
('da01a117-eff6-40c8-b91e-0f6a082ec346', 'Sentadilla cosaca alterna Overhead con Kettlebell doble', 28, 6, 281, 1, 'Avanzado', 'Realiza sentadillas laterales profundas manteniendo dos pesas rusas bloqueadas sobre la cabeza, combinando movilidad y estabilidad lateral.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Alternate Cossack Squat Overhead with Double kettlebell', 'Perform deep lateral squats while keeping two kettlebells locked overhead, combining mobility and lateral stability.', 'external'),
('da045b6f-677d-40be-9e94-bba060595f79', 'Jalón al pecho agarre estrecho supinado', 16, 17, 186, 1, 'Intermedio', 'Sentado, tira de la barra hacia el pecho con palmas mirando hacia ti y manos juntas. Objetivo: dorsales y bíceps. Cue: tira con los codos hacia abajo. Error: balancear el torso hacia atrás excesivamente.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Supinated Narrow Grip Chest Pull', 'Seated, pull the bar toward your chest with palms facing you and hands together. Target: lats and biceps. Cue: pull down with your elbows. Common mistake: swinging the torso back excessively.', 'external'),
('da119959-60cf-4990-b88b-9a512751b953', 'Sentadilla búlgara kettlebell', 28, 29, 281, 1, 'Intermedio', 'Split búlgaro pesa rusa al pecho. Objetivo: unilateral. Cue: pie trasero relajado. Error: inclinar mucho.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Bulgarian Kettlebell Squat', 'Bulgarian kettlebell chest split. Target: unilateral. Cue: back foot relaxed. Common mistake: tilt too much.', 'external'),
('da3ec6bd-7ad3-4cd4-a47e-aeabcd7b9e94', 'Levantamiento turco con barra de un solo brazo', 25, 6, 116, 1, 'Avanzado', 'Realiza el levantamiento turco completo utilizando una barra larga en lugar de una pesa rusa, lo que exige un control de la estabilidad y el equilibrio del brazo extremadamente alto.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Turkish One-Arm Barbell Lift', 'Perform the full Turkish getup using a long barbell instead of a kettlebell, which requires extremely high arm balance and stability control.', 'external'),
('da46aac8-0c61-45d7-afb7-d648c152f59f', 'Curl con barra Z', 17, 100, 116, 1, 'Intermedio', 'Curl de bíceps con barra Z para flexión de codo con agarre cómodo, controlando balanceo y rango completo.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Z Bar Curl', 'Z-bar biceps curl for elbow flexion with comfortable grip, controlling swing and full range.', 'external'),
('da4e7188-77f2-45c5-aac9-88cefbe14840', 'Peso muerto deficitario', 55, 29, 116, 1, 'Avanzado', 'Peso muerto desde plataforma elevada de 5-10cm aumentando el rango de movimiento. Fortalece la porción inicial del levantamiento. Requiere mayor movilidad y fuerza. Progresa gradualmente con la altura del déficit.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Deficient Deadlift', 'Deadlift from a 5-10cm elevated platform increasing the range of motion. Strengthens the initial portion of the lift. Requires greater mobility and strength. It progresses gradually with the height of the deficit.', 'external'),
('dad2da33-19f0-446d-a95a-c07bf79a0187', 'Curl femoral de pie en máquina', 55, 29, 186, 1, 'Principiante', 'Flexiona una pierna hacia el glúteo en la máquina vertical. Objetivo: aislamiento unilateral de isquios. Cue: mantén el muslo pegado al soporte. Error común: arquear la espalda lumbar para compensar la carga.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Standing Leg Curl Machine', 'Curl one leg toward your glute on the standing machine. Target: unilateral hamstring isolation. Cue: keep your thigh against the pad. Common mistake: arching your lower back to compensate for the load.', 'external'),
('dad96e23-2536-406d-bf22-212e10cfe803', 'Sentadilla trasera barra', 28, 29, 116, 1, 'Intermedio', 'Con la barra apoyada en los trapecios superiores (posición alta) o posteriores (posición baja), desciende controladamente hasta que los muslos estén paralelos al suelo o según tu movilidad. Mantén las rodillas alineadas con los pies y el pecho erguido. Empuja desde los talones para subir.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell back squat', 'With the bar supported on the upper trapezius (high position) or rear (low position), lower yourself controlledly until the thighs are parallel to the floor or according to your mobility. Keep your knees in line with your feet and your chest up. Push from your heels to go up.', 'external'),
('daf0928e-afb3-4806-8611-d99df36c7a77', 'Remo barra apoyo frente', 71, 17, 116, 1, 'Intermedio', 'Rema con la frente apoyada en soporte para no mover el cuerpo. Cue: espalda plana. Error: despegar la frente.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Rowing Bar Front Support', 'Row with your forehead resting on a support so as not to move your body. Cue: flat back. Common mistake: taking off the forehead.', 'external'),
('db195625-0792-445a-ad5b-946488eebf99', 'Curl martillo cruzado pecho', 17, 100, 81, 1, 'Intermedio', 'Flexiona mancuerna hacia hombro opuesto. Objetivo: braquial. Cue: roza el cuerpo. Error: girar torso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Chest Cross Hammer Curl', 'Bend dumbbell towards opposite shoulder. Target: brachialis. Cue: skims the body. Common mistake: twist torso.', 'external'),
('db2cf571-749d-49ee-85c4-bef8cc992dce', 'Candlestick Roll Up a Tuck Jump', 13, 29, 1, 1, 'Intermedio', 'Rueda hacia atrás sobre la espalda, toma impulso para ponerte de pie sin manos y salta explosivamente llevando rodillas al pecho.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Candlestick Roll Up a Tuck Jump', 'Roll back on your back, push yourself to stand without hands and jump explosively bringing your knees to your chest.', 'bodyweight'),
('db363b46-6810-4212-9aae-4db76537c840', 'Saltos de valla a una pierna', 29, 64, 1, 1, 'Avanzado', 'Salta vallas bajas de forma consecutiva con un solo pie. Potencia reactiva. Mantén el equilibrio. No toques las vallas con el pie.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'One leg hurdle jumps', 'Jump low hurdles consecutively on one foot. Reactive power. Keep your balance. Don''t touch the fences with your foot.', 'bodyweight'),
('db3aff51-26ed-4732-a0c5-b0237efcf731', 'Press tras nuca barra', 6, 2, 116, 1, 'Avanzado', 'Con la barra apoyada en los trapecios, presiona verticalmente por detrás de la cabeza. Desciende solo hasta la altura de las orejas para proteger los hombros. Requiere buena movilidad de hombros; no recomendado para todos debido al riesgo de lesión.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Press behind the bar', 'With the bar resting on your traps, press vertically behind your head. Go down only to the height of your ears to protect your shoulders. Requires good shoulder mobility; Not recommended for everyone due to risk of injury.', 'external'),
('db3eb616-db89-4cf1-9abf-8586580b4084', 'Extensión de tríceps en polea con cuerda', 2, NULL, 151, 1, 'Principiante', 'Tira de la cuerda hacia abajo separando los extremos al final. Objetivo: tríceps lateral. Cue: codos fijos a costados. Error común: adelantar hombros por exceso de carga.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Cable Triceps Extension with Rope', 'Pull the rope down, separating the ends at the end. Target: lateral triceps. Cue: elbows fixed at sides. Common mistake: putting your shoulders forward due to excess load.', 'external'),
('db423a97-bf42-4aab-adb9-94cdc464e6e2', 'Tijeras de piernas', 25, 28, 1, 24, 'Principiante', 'Tumbado, cruza las piernas una sobre otra alternadamente a pocos cm del suelo. Cue: lumbar pegada al suelo. Error: arquear la espalda baja.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Scissor Kicks', 'Lie on your back and cross your legs over each other alternately a few centimeters off the floor. Cue: keep your lower back pressed into the floor. Common mistake: arching your lower back.', 'bodyweight'),
('db516847-e150-4497-a613-6f8eeb6897fd', 'Single Arm Dumbbell Turkish Get Up', 13, 6, 81, 1, 'Avanzado', 'Acuéstate con una mancuerna en alto. Levántate paso a paso hasta estar de pie, manteniendo siempre el brazo extendido y la vista en la pesa, luego invierte el movimiento.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Single Arm Dumbbell Turkish Get Up', 'Lie down with a dumbbell raised. Rise step by step until you are standing, always keeping your arm extended and your eyes on the weight, then reverse the movement.', 'external'),
('db61bcfd-4d39-4a77-b7b5-43e9264cd47c', 'Extensión de tríceps tras nuca con barra Z', 2, NULL, 116, 1, 'Intermedio', 'Sujeta la barra Z sobre la cabeza y bájala flexionando codos hacia la nuca. Objetivo: cabeza larga del tríceps. Cue: mantén los codos apuntando hacia arriba. Error común: arquear la espalda lumbar excesivamente.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Behind-the-neck Triceps Extension with Z Bar', 'Hold the Z bar above your head and lower it by bending your elbows towards the back of your neck. Target: long head of the triceps. Cue: keep your elbows pointing up. Common mistake: arching the lumbar back excessively.', 'external'),
('db8c1c14-64ae-4374-b0bc-744b7cdbd659', 'Press Sots con Kettlebell doble', 6, 2, 281, 1, 'Intermedio', 'Sentado en lo mas profundo de una sentadilla, presiona dos Kettlebells sobre la cabeza, exigiendo gran movilidad articular.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Press Sots with Double kettlebell', 'Sitting deep in a squat, press two kettlebells overhead, demanding great joint mobility.', 'external'),
('dbcd0ecd-8629-4dac-87c6-8341ae96d4d1', 'Movilidad de tobillo', 13, NULL, 1, 1, 'Principiante', 'Trabajo de movilidad del tobillo para mejorar dorsiflexión y control en sentadillas, saltos y carrera.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Ankle mobility', 'Ankle mobility work to improve dorsiflexion and control in squats, jumps and running.', 'mixed'),
('dbe70b82-d95d-4d31-9f2e-e57fa1b64939', 'Step Up Front Rack con barra', 28, 29, 116, 1, 'Intermedio', 'Realiza un escalon sobre banco con la barra en posicion de rack frontal, manteniendo los codos altos y el torso vertical.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Front Rack Barbell Step-up', 'Perform a step-up onto a bench with the barbell in the front rack position, keeping your elbows high and your torso upright.', 'external'),
('dc09b508-e034-43e6-b99d-59366ef11c6b', 'TRX Y-Deltoid Fly', 71, 6, 216, 1, 'Intermedio', 'Eleva brazos en Y inclinado TRX. Objetivo: deltoide posterior/espalda alta. Cue: brazos rectos. Error: encoger hombros.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'TRX Y Deltoid Fly', 'Raise your arms into a Y shape while leaning back on the TRX straps. Target: rear delts and upper back. Cue: keep your arms straight. Common mistake: shrugging your shoulders.', 'bodyweight'),
('dc1d6565-39c8-4574-9209-8e12b3e7df70', 'Flexiones pike', 6, 2, 1, 1, 'Intermedio', 'Adopta una posición en V invertida con las caderas elevadas y las manos y pies en el suelo. Desciende la cabeza hacia el suelo entre las manos flexionando los codos, luego empuja para volver a la posición inicial. Este ejercicio simula un press militar invertido y es excelente para desarrollar fuerza en los deltoides.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pike Push-ups', 'Assume an inverted V position with your hips raised and your hands and feet on the floor. Lower your head toward the floor between your hands, bending your elbows, then push back to the starting position. This exercise simulates an inverted military press and is excellent for developing deltoid strength.', 'mixed'),
('dc214d43-1ec2-4679-97c6-bea4d96c067f', 'Archer squats', 28, 29, 1, 1, 'Avanzado', 'Adopta una postura muy amplia y desciende hacia un lado manteniendo la mayor parte del peso en esa pierna mientras la otra permanece semi-extendida. Es una progresión hacia la sentadilla pistol que permite trabajar cada pierna con mayor intensidad mientras mantiene algo de asistencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Archer squats', 'Adopt a very wide stance and lower yourself to one side, keeping most of your weight on that leg while the other remains semi-extended. It is a progression towards the pistol squat that allows you to work each leg with greater intensity while maintaining some assistance.', 'mixed'),
('dc65566c-d215-498f-9912-4501b502c13d', 'Zancada lateral con mancuernas (Maleta)', 28, 29, 81, 1, 'Principiante', 'Sostén las mancuernas a los lados y da un paso amplio lateral, flexionando la rodilla de la pierna que desplazas mientras mantienes la otra recta.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Dumbbell Side Stride (Suitcase)', 'Hold the dumbbells to the sides and take a wide lateral step, flexing the knee of the leg you move while keeping the other straight.', 'external'),
('dce2e47c-1f63-49f2-ad28-359bf23e3672', 'Arranque kettlebell', 6, 29, 281, 1, 'Avanzado', 'Lleva la kettlebell desde el suelo hasta sobre la cabeza en un movimiento continuo explosivo. Combina swing con press en un solo movimiento fluido. Requiere técnica perfecta para evitar lesiones. Desarrolla potencia total del cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Snatch', 'Bring the kettlebell from the floor to overhead in one continuous explosive movement. Combine swing with press in one fluid movement. Requires perfect technique to avoid injuries. Develops total body power.', 'external'),
('dd081b6b-5456-4b28-acbf-c2c374d58301', 'Push Jerk a una mano con mancuerna', 6, 28, 81, 1, 'Avanzado', 'Ejecuta un jerk explosivo con un solo brazo utilizando las piernas para elevar la mancuerna y estabilizar el cuerpo en la recepcion.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'One Hand Dumbbell Push Jerk', 'Perform an explosive one-arm jerk using your legs to raisete the dumbbell and stabilize your body on the landing.', 'external'),
('dd0f8497-bd08-43d2-8787-f4b2670e6011', 'Remo inclinado mancuernas', 16, 17, 81, 1, 'Principiante', 'Inclínate hacia adelante con la espalda recta y las rodillas ligeramente flexionadas. Con una mancuerna en cada mano, tira hacia el abdomen llevando los codos hacia atrás. Aprieta los omóplatos en la parte superior del movimiento. Mantén el core activado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Incline Row', 'Lean forward with your back straight and knees slightly bent. With a dumbbell in each hand, pull towards your abs, bringing your elbows back. Squeeze your shoulder blades at the top of the movement. Keep your core activated.', 'external'),
('dd39fc68-da94-4522-ae21-bfac84bf9fff', 'Sentadilla pistol con peso', 28, 29, 81, 1, 'Avanzado', 'Sentadilla pistol sosteniendo mancuerna(s). El peso adicional aumenta la dificultad pero puede ayudar con el balance como contrapeso. Comienza con peso ligero al frente. Mantén control total en el descenso.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Weighted pistol squat', 'Pistol squat holding dumbbell(s). The additional weight increases the difficulty but can help with balance as a counterbalance. Start with light weight in front. Maintain full control on the descent.', 'external'),
('dd3c5b34-a517-4ae4-a4ee-eca64b20d1df', 'Sentadilla barra baja', 29, 71, 116, 1, 'Intermedio', 'Barra en deltoide posterior. Objetivo: cadena posterior. Cue: cadera atrás. Error: caer pecho.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Low Bar Squat', 'Rear deltoid bar. Target: posterior chain. Cue: hip back. Common mistake: chest drop.', 'external'),
('dd517abe-2b71-4433-99a3-fd586510dcd9', 'Sentadilla Búlgara ipsilateral Maleta con Kettlebell a una mano', 28, 29, 281, 1, 'Intermedio', 'Sentadilla split con pie elevado sosteniendo la pesa rusa a un costado con la mano del mismo lado que la pierna de apoyo.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Ipsilateral Single-Arm Suitcase Bulgarian Split Squat with Kettlebell', 'Split squat with raised foot holding the kettlebell at your side with your hand on the same side as your supporting leg.', 'external'),
('ddcbd442-a801-4ca3-a6e3-ac03afd4d56f', 'Extensión tríceps máquina', 2, NULL, 186, 1, 'Principiante', 'Sentado o de pie según el diseño, extiende los codos contra la resistencia. Puede ser con brazos sobre la cabeza o a los lados. La trayectoria fija permite concentrarse en la contracción del tríceps sin preocuparse por la estabilización.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Triceps extension machine', 'Sitting or standing depending on the design, extend your elbows against the resistance. It can be with arms above the head or at the sides. The fixed trajectory allows you to focus on triceps contraction without worrying about stabilization.', 'external'),
('ddd08599-7d60-414f-86d6-f60095d0f00a', 'Thruster Ciclista alterno a una mano en Landmine', 28, 6, 116, 1, 'Intermedio', 'Realiza un thruster en landmine con talones elevados, alternando el brazo que empuja el peso en cada fase ascendente de la sentadilla.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Alternating Cyclist Single-Arm Landmine Thruster', 'Perform a landmine thruster with your heels elevated, alternating the arm that drives the weight on each ascent from the squat.', 'external'),
('ddd85b92-d5fe-456b-b80c-e8eeca32f6e5', 'Sentadilla Ciclista con barra tras nuca', 28, 29, 116, 1, 'Intermedio', 'Con los talones elevados sobre una cuña y la barra en los trapecios, realiza una sentadilla profunda enfocando el trabajo en los cuadriceps.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Cycling Squat with Bar Behind the Neck', 'With your heels raised on a wedge and the bar on your traps, perform a deep squat focusing on the quadriceps.', 'external'),
('ddd8e776-9e30-44ec-b636-341786ca994c', 'Salto de estrella', 13, 64, 1, 1, 'Principiante', 'Salta verticalmente extendiendo brazos y piernas en el aire formando una X. Aterriza con pies juntos. Mejora la coordinación. Cue: extensión total en el punto más alto. Error común: aterrizar con piernas abiertas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Star Jump', 'Jump vertically, extending your arms and legs in the air forming an X. Land with your feet together. Improves coordination. Cue: full extension at highest point. Common mistake: landing with legs open.', 'bodyweight'),
('ddd96f77-0207-4fd6-86c7-2590ac372895', 'L-Sit en anillas', 25, 2, 1, 24, 'Avanzado', 'Sostente en las anillas con los brazos bloqueados y eleva las piernas rectas frente a ti hasta formar un angulo de 90 grados.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'L-Sit on rings', 'Hold on to the rings with your arms locked and raise your legs straight in front of you until they form a 90-degree angle.', 'bodyweight'),
('ddf6a529-0e9f-4ce2-ac40-41995d4e299d', 'Remo unilateral con banda', 71, 17, 61, 1, 'Principiante', 'Pisa banda y tira hacia atrás. Cue: codo hacia el bolsillo. Error: girar el torso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Unilateral Row with Band', 'Step on the band and pull back. Cue: elbow to pocket. Common mistake: twisting the torso.', 'external'),
('de18a83d-18f3-425a-aaa8-8ed503ce7823', 'Flexión con toque de hombro alterno en paralelas', 1, 2, 1, 1, 'Intermedio', 'Realiza una flexion sobre paralelas y, al subir, toca el hombro opuesto con una mano manteniendo la estabilidad del cuerpo sobre un solo apoyo.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Parallel Bar Push-Up with Alternating Shoulder Tap', 'Perform a push-up on parallel bars and, as you come up, tap the opposite shoulder with one hand while maintaining full-body stability on a single support.', 'mixed'),
('de5d5755-9fe4-4b9d-a6fe-8d1823f2a72d', 'Squat Clean a Split Jerk con barra', 13, 6, 116, 1, 'Avanzado', 'Realiza una cargada recibiendo la barra en sentadilla completa y termina con un envion dividiendo las piernas para estabilidad.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Squat Clean to Split Jerk with Barbell', 'Perform a clean, receiving the bar in a full squat and finish with a clean and jerk, splitting your legs for stability.', 'external'),
('de887dc9-59bb-4d00-820a-f6ab9bf27cbd', 'Rodamiento declinado', 25, NULL, 271, 1, 'Avanzado', 'Roll out con rodillas o pies elevados en banco o caja. El ángulo declinado aumenta significativamente la dificultad. Comienza con elevaciones pequeñas y progresa. Mantén control total en ambas fases.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Declined Bearing', 'Roll out with knees or feet raised on a bench or box. The declined angle significantly increases the difficulty. Start with small lifts and work your way up. Maintain full control in both phases.', 'external'),
('de99e662-a345-4685-b786-4b97aa0410e2', 'Battle ropes jumping jacks', 13, NULL, 256, 24, 'Intermedio', 'Realiza jumping jacks mientras mantienes las cuerdas en movimiento. Coordina el movimiento de piernas con las ondas de las cuerdas. Ejercicio cardiovascular intenso que trabaja todo el cuerpo simultáneamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Jumping Jacks', 'Perform jumping jacks while keeping the ropes moving. Coordinate the movement of your legs with the waves of the ropes. Intense cardiovascular exercise that works the entire body simultaneously.', 'external'),
('de9f0204-e44f-49b9-bbd1-6badeb38ea5b', 'Elevaciones de piernas en banco plano', 25, 28, 1, 1, 'Intermedio', 'Tumbado boca arriba en un banco plano, sujeta los bordes tras la cabeza o a los lados. Eleva las piernas juntas y estiradas hasta la vertical y bájalas controladamente sin arquear la zona lumbar. Objetivo: zona inferior del recto abdominal. Cue: pega la espalda baja al banco durante todo el recorrido. Error común: dejar que la espalda se arquee al bajar las piernas.', FALSE, NULL, '2026-01-16T11:20:07.528383+00:00', 'Flat Bench Leg Raises', 'Lying face up on a flat bench, hold the edges behind your head or at your sides. Raise your legs together and straight until vertical and lower them controlledly without arching your lower back. Target: lower area of ​​the rectus abdominis. Cue: stick your lower back to the bench throughout the entire movement. Common mistake: letting your back arch when lowering your legs.', 'bodyweight'),
('dec218db-d9e7-403a-99b8-e8bc5b98eeea', 'Salto al cajón (Box Jump)', 28, 29, 1, 1, 'Intermedio', 'Salta de forma explosiva sobre un cajón y aterriza suavemente en posición de sentadilla. Objetivo: potencia del tren inferior. Cue: rodillas hacia afuera al caer. Error común: aterrizar ruidosamente con los pies planos.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Box Jump', 'Jump explosively onto a box and land softly in a squat position. Target: lower body power. Cue: knees out as you land. Common mistake: landing loudly with flat feet.', 'mixed'),
('ded51457-6f1c-4b07-a2bc-6c9b9839cdef', 'Face Pull a Overhead Press en TRX', 6, 71, 216, 1, 'Avanzado', 'Realiza un Face Pull en TRX, rota los brazos hacia arriba en posición de Y (press) manteniendo la tensión, y regresa controlado.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Face Pull an Overhead Press on TRX', 'Perform a Face Pull in TRX, rotate your arms upward in a Y position (press) maintaining tension, and return controlled.', 'bodyweight'),
('ded73726-3183-4289-838b-71234f02830b', 'Salto de longitud caída unilateral', 29, 28, 1, 1, 'Avanzado', 'Salta hacia adelante con ambos pies pero aterriza y estabiliza sobre uno solo. Mejora la frenada excéntrica. Cue: clava la rodilla sin que baile. Error común: aterrizaje rígido que daña la rodilla.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Unilateral Drop Long Jump', 'Jump forward with both feet but land and stabilize on only one. Improves eccentric braking. Cue: drive your knee in without it dancing. Common mistake: stiff landing that damages the knee.', 'bodyweight'),
('dee1372d-8418-462c-9e04-8034f960e341', 'Flexiones con manos anchas', 1, 6, 1, 1, 'Principiante', 'Manos más allá de la anchura de hombros. Mayor énfasis en pectoral. Cue: pecho al suelo. Error: codos demasiado abiertos a 90 grados.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Push-ups with Wide Hands', 'Hands beyond shoulder width. Greater emphasis on chest. Cue: chest to the floor. Common mistake: elbows too open at 90 degrees.', 'mixed'),
('df29eefb-3b95-49b2-8d2f-f235f4551d36', 'Salto patinador banda rodillas', 37, 29, 61, 1, 'Avanzado', 'Saltos de patinador con banda en rodillas para activar glúteo medio lateralmente. Cue: rodilla hacia afuera siempre. Error común: que la banda cierre las rodillas al caer.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Skater Jump Band Knees', 'Skater jumps with band on knees to activate glute medius laterally. Cue: knee out always. Common mistake: the band closing the knees when falling.', 'external'),
('df55a42d-8b8a-4e29-8cbb-a55e5713e1d2', 'RDL unilateral mancuerna equilibrio', 55, 29, 81, 1, 'Intermedio', 'Baja pesa a pie apoyo elevando pierna atrás. Cue: espalda plana. Error: tambaleo lateral.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Rdl Unilateral Dumbbell Balance', 'Lower weight on foot support by raising leg behind. Cue: flat back. Common mistake: lateral wobble.', 'external'),
('df9308a7-0b4e-4658-978a-624f6ff0c018', 'Tirón alto kettlebell', 6, 71, 281, 1, 'Intermedio', 'Similar al swing pero tirando activamente con el brazo hasta la altura del hombro. El codo debe subir primero, como un remo alto explosivo. Desarrolla potencia en la espalda alta y hombros. Mantén la kettlebell cerca del cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell High Pull', 'Similar to a swing, but actively pull with the arm until the kettlebell reaches shoulder height. The elbow should lead the movement, like in an explosive high pull. It develops power in the upper back and shoulders. Keep the kettlebell close to your body.', 'external'),
('df94d7f7-6816-464b-8326-6e627bf1ef7d', 'Remo Pendlay con Kettlebell doble', 71, 17, 281, 1, 'Intermedio', 'Con el torso paralelo al suelo, levanta explosivamente dos pesas rusas desde el suelo y regrésalas a una parada completa en cada repetición.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double kettlebell Pendlay Row', 'With your torso parallel to the floor, explosively lift two kettlebells off the floor and return them to a full stop on each rep.', 'external'),
('dfa2e7a2-181e-4ba8-b84b-5ac74d70d6bd', 'Remo prono con barra', 71, 17, 116, 1, 'Intermedio', 'Acuéstate boca abajo en un banco alto. Agarra la barra del suelo y rema hacia el banco aislando la espalda sin usar impulso.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Barbell Prone Row', 'Lie face down on a high bench. Grab the bar from the floor and row towards the bench isolating your back without using momentum.', 'external');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('e0065fd6-b8a6-4325-97a5-99f0b7508ba8', 'Clean doble a Zancada inversa alterna Front Rack con Kettlebell', 28, 29, 281, 1, 'Intermedio', 'Lleva dos Kettlebells a posicion de rack y alterna zancadas hacia atras, manteniendo el torso erguido y los codos altos.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Double Clean to Alternating Reverse Lunge Front Rack with Kettlebell', 'Hold two kettlebells in a rack position and alternate strides backwards, keeping your torso upright and your elbows high.', 'external'),
('e0318239-bb47-4bb6-89c6-82deb48025cf', 'Battle ropes ondas alternas rítmicas', 6, 17, 256, 24, 'Principiante', 'Mueve cuerdas arriba y abajo alternando brazos rápidamente. Objetivo: resistencia cardiovascular. Cue: mantén sentadilla parcial. Error común: mover el tronco en lugar de solo brazos.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Rhythmic Alternating Battle Rope Waves', 'Move ropes up and down, alternating arms quickly. Target: cardiovascular resistance. Cue: hold partial squat. Common mistake: moving your torso instead of just your arms.', 'external'),
('e0512d89-b89f-4e47-94ea-b81a3eed7700', 'Zancada búlgara mancuernas costados', 28, 29, 81, 1, 'Intermedio', 'Pie en banco, pesas a los lados. Cue: baja vertical. Error: rodilla pase mucho pie.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Bulgarian Split Squat with Dumbbells at Sides', 'Keep your rear foot on a bench and hold the dumbbells at your sides. Cue: lower straight down. Common mistake: letting the knee travel too far past the foot.', 'external'),
('e05abb5f-beec-4e9d-8359-48607e06cbd1', 'Ring Eccentric Pull Up', 71, 17, 1, 1, 'Principiante', 'Salta o ayúdate para subir a la posición superior del Pull Up en anillas. Baja el cuerpo muy lentamente (3-5 segundos) hasta extender los brazos por completo.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Eccentric Pull Up', 'Jump or help yourself to the top position of the Ring Pull Up. Lower your body very slowly (3-5 seconds) until your arms are fully extended.', 'mixed'),
('e08b2481-e531-4aa4-8a9d-a28b00cd7592', 'Pike sobre Fitball', 25, 6, 290, 1, 'Avanzado', 'Con los pies sobre el Fitball y manos en el suelo (plancha), eleva las caderas hacia arriba rodando el balón hacia ti con las piernas rectas hasta quedar casi vertical.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Pike on Stability Ball', 'With your feet on the stability ball and your hands on the floor in a plank, raise your hips by rolling the ball toward you with straight legs until you are nearly vertical.', 'bodyweight'),
('e0e010c1-4104-428c-9847-4b4ae9f8e3ee', 'Curl femoral acostado en máquina', 55, 29, 186, 1, 'Principiante', 'Flexiona piernas boca abajo en máquina. Objetivo: isquiotibiales. Cues: cadera pegada al banco. Error común: levantar la pelvis al flexionar.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Lying Leg Curl Machine', 'Lying face down on the machine, bend your legs. Target: hamstrings. Cue: keep your hips glued to the bench. Common mistake: lifting the pelvis as you curl.', 'external'),
('e0f845e4-026d-48fd-a0be-3f05411cb733', 'Sentadilla Búlgara con Kettlebell doble (Maleta)', 28, 29, 281, 1, 'Intermedio', 'Sujeta dos Kettlebells a los costados (posicion maleta) con un pie elevado en un banco. Baja la cadera verticalmente manteniendo el torso erguido.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Squat with Double Kettlebell (suitcase)', 'Hold two kettlebells at your sides (suitcase position) with one foot raised on a bench. Lower your hips vertically, keeping your torso upright.', 'external'),
('e10bfa0c-cc24-4e7f-918f-e6583bd8203c', 'Puente de glúteo con banda', 29, 37, 61, 1, 'Principiante', 'Eleva la cadera con banda sobre rodillas empujando hacia afuera. Cue: aprieta glúteos arriba. Error: arquear la zona lumbar en exceso.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Glute Bridge with Band', 'Raise your hips with a band on your knees, pushing outwards. Cue: squeeze glutes up. Common mistake: arching the lower back excessively.', 'external'),
('e133947f-975e-45c5-bd49-6a69f5c1cd4a', 'Salto de peso muerto rumano a una pierna', 55, 29, 1, 1, 'Avanzado', 'Inclínate en un peso muerto rumano a una pierna y, de forma explosiva, salta verticalmente usando solo esa pierna. Aterriza con equilibrio.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Romanian one leg deadlift jump', 'Lean into a one-leg Romanian deadlift and explosively jump vertically using only that leg. Land with balance.', 'bodyweight'),
('e1520e3c-9e04-4114-ac40-cc881ad20916', 'Golpeo un brazo balón medicinal', 25, 6, 240, 1, 'Avanzado', 'Slam ball usando solo un brazo. Requiere mayor estabilización del core para resistir rotación. Comienza con balón más ligero. Alterna brazos. Mantén el torso estable durante el movimiento explosivo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I hit a medicine ball arm', 'Slam ball using only one arm. Requires greater core stabilization to resist rotation. Start with a lighter ball. Alternate arms. Keep your torso stable during the explosive movement.', 'external'),
('e152bcea-c94e-4fc8-8eb2-971eb4243cba', 'Dominadas en L', 16, 25, 1, 1, 'Avanzado', 'Dominadas manteniendo las piernas extendidas horizontalmente formando una L. Combina fuerza de tracción con isométrico de core extremo. Requiere flexibilidad en isquiotibiales. Una de las variaciones más difíciles de dominadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'L-Sit Pull-Up', 'Perform pull-ups while keeping your legs extended horizontally in an L position. This combines pulling strength with a demanding core isometric. It also requires hamstring flexibility.', 'mixed'),
('e1678318-3724-4619-a52c-2b8cf30ee5c0', 'Lanzamiento rotacional sentado', 25, 1, 240, 1, 'Intermedio', 'Sentado en el suelo con piernas estiradas, lanza el balón lateralmente. Aísla completamente el core. Cue: gira desde la cintura. Error común: flexionar los codos en exceso.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Seated Rotational Throw', 'Sitting on the floor with straight legs, throw the ball laterally. Completely isolate the core. Cue: twist from the waist. Common mistake: bending the elbows excessively.', 'external'),
('e1a95d69-4602-4eea-be79-65f79e4ae4c6', 'Tuck Jump', 28, 13, 1, 1, 'Intermedio', 'Salta verticalmente con potencia y lleva ambas rodillas hacia el pecho en el aire, aterrizando de forma suave y controlada.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Tuck Jump', 'Jump vertically with power and drive both knees toward your chest in the air, landing softly and under control.', 'bodyweight'),
('e2906a5f-2ef4-45a6-b12e-586a9b1281fe', 'Sóleo sentado en máquina específica', 309, 64, 186, 1, 'Principiante', 'Eleva talones con rodillas flexionadas contra el soporte. Objetivo: fuerza del sóleo. Cue: rango de movimiento total. Error común: rebotar el peso.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Seated Soleus Machine Raise', 'Raise your heels with your knees bent against the pad. Target: soleus strength. Cue: use a full range of motion. Common mistake: bouncing the weight.', 'external'),
('e2918a21-058c-47b7-9291-d2022bffc4d9', 'Abducción de cadera en cuadrupedia con cable', 37, 29, 151, 1, 'Principiante', 'En cuatro puntos lateral a la polea, sujeta el cable a la pierna exterior y elevala lateralmente para trabajar el gluteo medio.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Quadruped Cable Hip Abduction', 'In four points lateral to the pulley, hold the cable to the outside leg and raise it laterally to work the glute medius.', 'external'),
('e29735fb-352d-4467-a285-3aa124ab9208', 'Push Up en plancha straddle en paralelas', 1, 6, 1, 1, 'Avanzado', 'Realiza una flexion en posicion de plancha horizontal con las piernas abiertas en V para facilitar el equilibrio del peso corporal.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Push Up in parallel straddle plank', 'Perform a push-up in a horizontal plank position with your legs open in a V to facilitate the balance of your body weight.', 'mixed'),
('e29f7821-8d69-4c30-8cbd-7d916f20fab6', 'Press Cubano con mancuernas', 6, 2, 81, 1, 'Intermedio', 'De pie con mancuernas: sube codos (remo), rota antebrazos arriba (espantapájaros) y empuja al techo (press). Baja invirtiendo los pasos.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Cuban Press with dumbbells', 'Standing with dumbbells: raise elbows (row), rotate forearms up (scarecrow) and push to the ceiling (press). Go down reversing the steps.', 'external'),
('e2adc7f5-ff6f-4d81-a59c-1517feb17afc', 'Pullover con maza a una mano', 71, 6, 81, 1, 'Intermedio', 'Tumbado boca arriba, lleva la maza con un brazo desde detrás de la cabeza hasta la vertical sobre el pecho, manteniendo el brazo casi estirado.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'One-Handed Mace Pullover', 'Lying on your back, carry the club with one arm from behind your head to vertically on your chest, keeping your arm almost straight.', 'external'),
('e2b64ca6-6ceb-4b9a-a82f-0f0399213f42', 'Prensa pies parte superior', 29, 55, 186, 1, 'Intermedio', 'Pies arriba en plataforma. Cue: empuja talones. Error: levantar coxis.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Press Feet Top', 'Feet up on platform. Cue: push heels. Common mistake: lifting tailbone.', 'external'),
('e2d5796a-1e8e-444b-b29a-ee843f68ffa2', 'Sentadilla frontal Kettlebell doble Bottoms Up', 28, 29, 281, 1, 'Avanzado', 'Realiza una sentadilla profunda sujetando dos Kettlebells invertidas en posicion rack, exigiendo un control total de la estabilidad.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Front Squat Double kettlebell Bottoms Up', 'Perform a deep squat holding two inverted kettlebells in a rack position, demanding total control of stability.', 'external'),
('e2e7487a-5bcd-4e81-b712-dd76e29e9c97', 'Sentadilla cosaca alterna agarre bajo en Landmine', 28, 29, 116, 1, 'Intermedio', 'Realiza una sentadilla lateral profunda sujetando la barra Landmine a una altura baja, manteniendo el torso estable y la pierna extendida recta.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Cossack Squat Alternate Low Grip in Landmine', 'Perform a deep lateral squat holding the Landmine bar at a low height, keeping your torso stable and your extended leg straight.', 'external'),
('e2f304bd-7459-42ad-9986-6af581504910', 'Cruces pectorales cable', 1, NULL, 151, 1, 'Intermedio', 'Con las poleas a la altura del pecho, realiza un movimiento de abrazo juntando las manos frente al pecho. Mantén los brazos ligeramente flexionados durante todo el movimiento. La tensión constante del cable maximiza la activación del pectoral.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable pectoral crosses', 'With the cables at chest height, perform a hugging movement by joining your hands in front of your chest. Keep your arms slightly bent throughout the movement. The constant cable tension maximizes pectoral activation.', 'external'),
('e30f9bde-0b94-4aea-9a2d-8cbbb68805dc', 'Rotación externa hombro cable', 6, NULL, 151, 1, 'Principiante', 'Con el codo pegado al costado y flexionado a 90 grados, rota el antebrazo hacia afuera contra la resistencia del cable. Fundamental para la salud del manguito rotador. Mantén el codo inmóvil y usa peso ligero con control perfecto.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Shoulder External Rotation', 'With your elbow against your side and flexed to 90 degrees, rotate your forearm outward against the resistance of the cable. Fundamental for the health of the rotator cuff. Keep your elbow still and use light weight with perfect control.', 'external'),
('e3336cbf-5b6a-4871-8142-2e9b03da4de7', 'Press Overhead de rodillas a una mano con Kettlebell', 6, 2, 281, 1, 'Intermedio', 'Arrodillado sobre ambas piernas, presiona la pesa rusa sobre la cabeza con un solo brazo, estabilizando el tronco para evitar inclinaciones.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'One-hand Kneeling Overhead Press with Kettlebell', 'Kneeling on both legs, press the kettlebell overhead with one arm, stabilizing your torso to prevent tilting.', 'external'),
('e33daa15-4720-483b-a225-fc7b3389f2f3', 'Extensión tríceps con banda', 2, NULL, 61, 1, 'Principiante', 'Sujeta un extremo de la banda sobre tu cabeza con un brazo flexionado. Con la otra mano, tira del otro extremo extendiendo el codo completamente. Mantén el brazo superior inmóvil y paralelo al suelo. La banda proporciona resistencia continua durante la extensión.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Triceps extension with band', 'Hold one end of the band over your head with one arm bent. With your other hand, pull on the other end, extending your elbow fully. Keep your upper arm still and parallel to the ground. The band provides continuous resistance during the extension.', 'external'),
('e33f2fd9-5cdf-4797-b1c8-6aebf12ddf2d', 'Sentadilla frontal barra', 28, 25, 116, 1, 'Avanzado', 'Con la barra apoyada en los deltoides anteriores y los codos elevados, realiza la sentadilla manteniendo el torso más vertical que en la sentadilla trasera. Requiere mayor movilidad de muñecas y tobillos. Enfatiza más los cuádriceps y exige mayor activación del core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Front Squat', 'With the bar resting on your front deltoids and your elbows raised, perform the squat while keeping your torso more vertical than in the back squat. Requires greater mobility of the wrists and ankles. It emphasizes the quadriceps more and requires greater activation of the core.', 'external'),
('e35f8ed7-b889-4dc8-a91f-009d47b4c7aa', 'Sentadilla Pistola Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Avanzado', 'Realiza una sentadilla a una pierna con dos Kettlebells en posicion rack. El ejercicio de pierna mas demandante tecnicamente con pesas rusas.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Front Rack Pistol Squat with Double kettlebell', 'Perform a one-leg squat with two kettlebells in a rack position. The most technically demanding leg exercise with kettlebells.', 'external'),
('e36305eb-2393-4b28-a2e5-59c93b9588b9', 'Superman extensiones', 71, 29, 1, 1, 'Principiante', 'Boca abajo, eleva brazos y piernas simultáneamente. Cadena posterior. Movimiento suave. No des tirones bruscos con el cuello.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Superman Extensions', 'Lie face down and lift your arms and legs at the same time. Targets the posterior chain. Use a smooth movement and avoid jerking your neck.', 'bodyweight'),
('e363ac88-ea44-4b70-9a93-e159ae15cf2e', 'Lanzamiento overhead de balón', 55, 29, 240, 1, 'Intermedio', 'Lanza el balón medicinal hacia atrás sobre tu cabeza con un movimiento explosivo de cadera. Objetivo: potencia de la cadena posterior. Cue: extiende la cadera con fuerza. Error común: usar demasiado los brazos y poco las piernas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Overhead Ball Throw', 'Throw the medicine ball back over your head with an explosive hip movement. Target: Posterior chain power. Cue: extend your hips forcefully. Common mistake: using your arms too much and your legs too little.', 'external'),
('e36f95d1-58d2-4655-958b-7de26cba2bbc', 'Salto de patinador con resistencia de banda', 37, 29, 61, 1, 'Intermedio', 'Realiza saltos laterales de lado a lado con una banda elástica anclada a la cintura que te atraiga hacia el origen del anclaje.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Skater jump with resistance band', 'Perform lateral jumps from side to side with an elastic band anchored at your waist that draws you towards the origin of the anchor.', 'external'),
('e38f4199-1c38-4682-a964-fe0483f5d3a4', 'Curl de bíceps en polea baja', 17, 100, 151, 1, 'Principiante', 'Flexiona los codos tirando del cable de la polea baja. Objetivo: tensión constante en el bíceps. Cue: codos fijos a los costados. Error común: mover los hombros hacia adelante al subir.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Low Cable Biceps Curl', 'Bend your elbows by pulling on the low cable cable. Target: constant tension on the biceps. Cue: elbows fixed at the sides. Common mistake: moving your shoulders forward when going up.', 'external'),
('e3da6e23-2ef7-4ec3-ab96-3ead69569bbb', 'Curl predicador mancuerna estricto', 17, NULL, 81, 1, 'Principiante', 'Flexiona pesa con brazo apoyado en banco. Cue: estira total. Error: levantar codo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Dumbbell Preacher Curl', 'Flex dumbbell with arm resting on bench. Cue: full stretch. Common mistake: raise elbow.', 'external'),
('e416939b-82bf-4b95-af69-f9b35758f90d', 'Remo sentado con banda', 71, 17, 61, 1, 'Principiante', 'Sentado, piernas estiradas, rodea pies con banda y rema. Espalda recta. Retrae escápulas. No subas los hombros.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Band Seated Row', 'Sitting, legs straight, wrap your feet with a band and row. Straight back. Retract scapulae. Don''t raise your shoulders.', 'external'),
('e43572ab-e8ee-4284-ad89-c75f97e273a5', 'Elevaciones frontales con disco', 6, NULL, 116, 1, 'Principiante', 'Sujeta disco y eleva al frente. Objetivo: deltoides anterior. Cue: no balancear. Error: arquear espalda.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Front Disc Raises', 'Holds disc and raises to the front. Target: anterior deltoid. Cue: don''t swing. Common mistake: arching your back.', 'external'),
('e4596505-5dce-4fe8-8ef3-049ad1c3a9b0', 'Sentadilla búlgara', 28, 29, 81, 1, 'Intermedio', 'Un pie elevado en banco tras de ti, baja con la pierna delantera hasta que el muslo sea paralelo al suelo. Cue: tronco ligeramente inclinado. Error: que la rodilla colapse hacia adentro.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Bulgarian Squat', 'One foot elevated on the bench behind you, lower your front leg until your thigh is parallel to the floor. Cue: slightly inclined torso. Error: the knee collapsing inward.', 'external'),
('e47b3926-77ac-4f3b-bac7-5aa166743097', 'Curl bíceps con banda', 17, NULL, 61, 1, 'Principiante', 'Pisa el centro de la banda y sujeta los extremos con las palmas hacia arriba. Realiza flexiones de codo manteniendo los codos pegados a los costados. La resistencia progresiva de la banda hace que el ejercicio sea más desafiante en la parte superior del movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Band biceps curl', 'Step on the center of the band and hold the ends with your palms facing up. Perform elbow curls keeping your elbows close to your sides. The progressive resistance of the band makes the exercise more challenging at the top of the movement.', 'external'),
('e47ea76a-6eb4-43cd-9570-9e4871bcc5f3', 'Turkish Sit Up en Landmine a una mano', 25, 6, 116, 1, 'Intermedio', 'Realiza un sit up sujetando el extremo de la barra Landmine con un brazo extendido, desafiando la estabilidad del core y el hombro.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Single-Arm Landmine Turkish Sit-Up', 'Perform a sit-up while holding the end of the landmine bar with one arm extended, challenging core and shoulder stability.', 'external'),
('e4e7fdbf-b0a5-47af-87e3-91ee017da993', 'TRX Remo bajo estricto', 71, 17, 216, 1, 'Principiante', 'Tira agarres a costillas TRX. Objetivo: espalda. Cue: codos pegados. Error: hundir cadera.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Strict Low TRX Row', 'Pull the TRX handles toward your ribs. Target: back. Cue: keep your elbows close to your body. Common mistake: letting your hips sag.', 'bodyweight'),
('e50c6346-ad5c-4c85-88dd-647ab22e94ed', 'Arranque barra', 13, NULL, 116, 1, 'Avanzado', 'El más técnico de los levantamientos olímpicos. Lleva la barra desde el suelo hasta sobre la cabeza en un solo movimiento continuo con agarre amplio. Requiere movilidad excepcional, coordinación perfecta y años de práctica para dominar la técnica correctamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Barbell Snatch', 'The most technical of the Olympic lifts. Bring the barbell from the floor to overhead in one continuous movement with a wide grip. It requires exceptional mobility, perfect coordination, and years of practice to master.', 'external'),
('e51b23ae-f2cc-46e7-a9c3-911a1b817214', 'Press de banca declinado con barra', 1, 2, 116, 1, 'Intermedio', 'Tumbado en banco declinado, baja la barra a la parte inferior del pecho y empuja. Objetivo: fibras inferiores del pectoral. Cue: pies bien anclados. Error común: bajar la barra hacia el cuello.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Barbell Decline Bench Press', 'Lying on a decline bench, lower the bar to your lower chest and push. Target: lower fibers of your chestis. Cue: feet well anchored. Common mistake: lowering the bar towards the neck.', 'external'),
('e52667e3-614c-496e-8fb1-5ddccfbea51e', 'Push Jerk a una mano con Kettlebell Bottoms Up', 6, 28, 281, 1, 'Avanzado', 'Lanza una Kettlebell invertida sobre la cabeza y métete debajo flexionando rodillas, un reto maximo de estabilidad y potencia.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Single-Arm Bottoms-Up Kettlebell Push Jerk', 'Drive the inverted kettlebell overhead and move under it by bending your knees. This is a demanding stability and power exercise.', 'external'),
('e565695e-e291-49a1-81d5-0d5743f12097', 'Fingertip push ups', 1, 100, 1, 1, 'Avanzado', 'Realiza flexiones apoyándote únicamente en las puntas de los dedos en lugar de las palmas. Fortalece significativamente los dedos, manos y antebrazos. Comienza con pocas repeticiones para evitar lesiones y progresa gradualmente. Mantén los dedos firmes y arqueados.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Fingertip push ups', 'Perform push-ups using only your fingertips instead of your palms. Significantly strengthens fingers, hands and forearms. Start with low repetitions to avoid injuries and progress gradually. Keep your fingers firm and arched.', 'mixed'),
('e58a7dca-ba19-4fb7-b254-375cc3892674', 'Peso muerto Sumo con Kettlebell doble', 71, 29, 281, 1, 'Principiante', 'Con los pies mas anchos que los hombros, levanta dos Kettlebells desde el suelo extendiendo cadera y rodillas con la espalda neutra.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Double Kettlebell Sumo Deadlift', 'With your feet wider than your shoulders, lift two kettlebells from the floor, extending your hips and knees with a neutral back.', 'external'),
('e59c73a0-fe58-4e6a-9e99-eed0083ad556', 'Swing en postura escalonada alterno con Kettlebell a una mano', 29, 25, 281, 1, 'Intermedio', 'Swing unilateral en postura escalonada alternando el brazo y la posicion de los pies de forma ritmica y coordinada.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Alternating Single-Arm Kettlebell Swing in Staggered Stance', 'Perform a unilateral swing in a staggered stance while alternating the arm and foot position in a coordinated rhythm.', 'external'),
('e6271a88-e47d-40da-b4b6-237dd5554d10', 'Upright row cable', 6, 71, 151, 1, 'Intermedio', 'Con polea baja y barra recta, realiza remo vertical llevando la barra hacia el mentón con los codos elevados. El cable proporciona tensión constante. Ten cuidado con la posición de las muñecas y no eleves demasiado si tienes problemas de hombro.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Upright Row', 'Using a low cable and a straight bar, perform an upright row by pulling the bar toward your chin with your elbows lifted. The cable provides constant tension. Be mindful of your wrist position and avoid raising too high if you have shoulder issues.', 'external'),
('e66415a8-ac1e-460d-b85e-6ab6e46bb152', 'Prensa piernas unilateral estricta', 28, 29, 186, 1, 'Intermedio', 'Empuja plataforma con un pie. Cue: rodilla alineada. Error: bloquear rodilla.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Unilateral Leg Press', 'Push platform with one foot. Cue: knee aligned. Common mistake: lock knee.', 'external'),
('e6adafbc-b80e-479e-aced-5ce2008bb4c6', 'Sentadilla Front Rack con Kettlebell doble', 28, 29, 281, 1, 'Principiante', 'Realiza una sentadilla profunda con dos Kettlebells apoyadas en los antebrazos y hombros, manteniendo los codos en alto y torso recto.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Double kettlebell Front Rack Squat', 'Perform a deep squat with two kettlebells resting on your forearms and shoulders, keeping your elbows high and your torso straight.', 'external'),
('e6cee733-ba4a-4344-8b8c-f873d8ebf8a1', 'Press hombros alterno mancuerna', 6, 2, 81, 1, 'Principiante', 'Empuja una pesa alternando brazos. Objetivo: unilateral. Cue: torso estable. Error: inclinar cuerpo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Dumbbell Alternating Shoulder Press', 'Push a weight alternating arms. Target: unilateral. Cue: stable torso. Common mistake: tilt body.', 'external'),
('e6d2735a-f52d-4a43-adbe-4976ba31fb59', 'Clean a Sentadilla Front Rack con Kettlebell doble Bottoms Up', 29, 28, 281, 1, 'Avanzado', 'Realiza una cargada recibiendo dos Kettlebells invertidas en posicion rack y baja inmediatamente a una sentadilla profunda.', FALSE, NULL, '2026-02-02T16:08:01.829521+00:00', 'Clean a Front Rack Squat with Double Kettlebell Bottoms Up', 'Perform a clean receiving two kettlebells inverted in a rack position and immediately lower yourself into a deep squat.', 'external'),
('e6d2ff3b-cc81-4f46-9e20-578f8b4414ad', 'V-Sit en paralelas', 25, 2, 1, 24, 'Avanzado', 'Sostente sobre las paralelas y eleva las piernas rectas por encima de la cadera formando una V, manteniendo la tensión isométrica.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'V-Sit on Parallel Bars', 'Support yourself on the parallel bars and raise your straight legs above hip level to form a V, maintaining isometric tension.', 'bodyweight'),
('e6ee753a-255f-451a-a611-9306bfc3c832', 'Zancada inversa Overhead contralateral Slider Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sostén una pesa rusa invertida sobre la cabeza. Desliza la pierna opuesta hacia atrás usando un slider, estabilizando hombro y torso.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse stride Overhead contralateral Slider Kettlebell Bottoms Up', 'Hold an inverted kettlebell over your head. Slide the opposite leg back using a slider, stabilizing shoulder and torso.', 'external'),
('e6f0fe51-5c66-4c3a-8a90-92bb10008b1e', 'Handstand Push Up en paralelas', 6, 2, 1, 1, 'Avanzado', 'En posición vertical sobre las paralelas, flexiona los brazos hasta que la cabeza baje entre las barras y empuja explosivamente hasta extender los brazos.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Handstand Push Up on parallel bars', 'In a vertical position on the parallel bars, flex your arms until your head drops between the bars and push explosively until your arms are extended.', 'mixed'),
('e6fd18ff-0cf7-4cba-92bd-0b4388cefe20', 'Zancada atrás con barra', 28, 29, 116, 1, 'Intermedio', 'Barra en hombros, da un paso atrás y baja. Estabilidad. Torso erguido. No dejes que la rodilla delantera colapse.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Barbell Reverse Lunge', 'With the bar on your shoulders, step back and lower under control. Target: stability. Cue: keep your torso upright. Common mistake: letting the front knee collapse inward.', 'external'),
('e77b7398-8d9a-4b76-99d5-eb73b00d9646', 'Press Cubano sentado con mancuerna', 6, 2, 81, 1, 'Intermedio', 'Sentado, realiza un remo vertical, rota el hombro externamente y luego presiona la mancuerna sobre la cabeza. Invierte el movimiento.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Seated Cuban Press with Dumbbell', 'Seated, perform an upright row, externally rotate your shoulder, and then press the dumbbell overhead. Reverse the movement.', 'external'),
('e7a2a94a-c617-469b-a821-087414c38340', 'Sentadilla Cosaca alterna con barra tras nuca', 28, 29, 116, 1, 'Avanzado', 'Con la barra en los hombros, realiza una sentadilla lateral profunda hacia un lado manteniendo la otra pierna estirada, y alterna.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Cossack squat alternating with bar behind the neck', 'With the bar on your shoulders, perform a deep lateral squat to one side, keeping the other leg straight, and alternate.', 'external'),
('e7b2696f-306f-4ea2-9fe2-8989897706ca', 'Saltos B (B-Skips)', 55, 29, 1, 1, 'Avanzado', 'Similar al salto A, pero extiende la pierna hacia adelante antes de traccionar el pie hacia atrás contra el suelo. Mejora la zancada. Espalda neutra. Evita movimientos bruscos.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'B-Skips', 'Similar to the A jump, but extend the leg forward before pulling the foot back against the ground. Improves stride. Neutral back. Avoid sudden movements.', 'bodyweight'),
('e7e31213-33b4-4804-adca-ef06e6d2db2a', 'Slam de poder con cuerda de batalla', 25, 6, 256, 1, 'Principiante', 'Eleva ambos extremos de la cuerda sobre la cabeza y golpealos contra el suelo con maxima potencia utilizando todo el cuerpo.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Battle Rope Power Slam', 'Raise both ends of the rope over your head and hit them against the ground with maximum power using your entire body.', 'external'),
('e7ec3810-2ac1-4bf7-932b-f2b10ef7d8f1', 'Sentadilla con kettlebells en posición de rack', 28, 29, 281, 1, 'Intermedio', 'Sostén dos pesas rusas contra los hombros y baja en sentadilla profunda. Objetivo: cuádriceps y estabilidad de core. Cues: torso muy vertical. Error común: permitir que el peso te incline hacia adelante.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Squat with Kettlebells in Rack Position', 'Hold two kettlebells against your shoulders and lower yourself into a deep squat. Target: quadriceps and core stability. Cue: very vertical torso. Common mistake: allowing the weight to lean you forward.', 'external'),
('e8243342-d98b-48b8-8d30-38bc51bd7cca', 'Levantamiento turco kettlebell', 13, NULL, 281, 1, 'Avanzado', 'Desde posición tumbada con kettlebell extendida, levántate hasta ponerte de pie siguiendo una secuencia específica de movimientos. Requiere movilidad, estabilidad y coordinación. Uno de los ejercicios más completos que existen. Practica sin peso primero.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Turkish Kettlebell Lift', 'From a lying position with an extended kettlebell, rise to a standing position following a specific sequence of movements. Requires mobility, stability and coordination. One of the most complete exercises that exist. Practice without weight first.', 'external'),
('e837b997-43a4-4b2e-b1a7-5d60645bc19f', 'Hip Dips plancha lateral', 25, 6, 1, 1, 'Intermedio', 'Baja y sube cadera en plancha lateral. Objetivo: oblicuos. Cue: movimiento vertical. Error: rotar hombro.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Hip Dips Side Plank', 'Lower and raise your hips in a side plank. Target: obliques. Cue: vertical movement. Common mistake: rotate shoulder.', 'mixed'),
('e873c22e-3a65-44bd-be5c-963dc6ae7989', 'Sentado en V', 25, NULL, 1, 24, 'Avanzado', 'Mantén el equilibrio sentado solo sobre los glúteos con piernas y torso elevados formando una V. Brazos extendidos paralelos a las piernas. Requiere fuerza excepcional del core y flexibilidad. Progresa desde versiones con rodillas flexionadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Sitting in V', 'Maintain balance sitting only on your buttocks with legs and torso raised forming a V. Arms extended parallel to the legs. Requires exceptional core strength and flexibility. Progress from versions with bent knees.', 'bodyweight'),
('e87460b7-4267-4740-a788-6f02d5bb5d81', 'Dead bug pesado', 25, 13, 81, 1, 'Intermedio', 'Dead bug con carga para estabilidad lumbo-pélvica, manteniendo la zona lumbar pegada y controlando respiración.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Heavy dead bug', 'Dead bug with load for lumbo-pelvic stability, keeping the lumbar area tight and controlling breathing.', 'external'),
('e8983e2a-bd9b-4e74-8be3-4666e8f35388', 'Flexiones parada de manos profundas', 6, 2, 1, 1, 'Avanzado', 'Flexiones en parada de manos usando paralelas o bloques para mayor rango de movimiento. Permite descender la cabeza por debajo del nivel de las manos. Aumenta significativamente la dificultad y el desarrollo muscular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Deep Handstand Pushups', 'Handstand push-ups using parallel bars or blocks for greater range of motion. It allows the head to be lowered below the level of the hands. Significantly increases difficulty and muscle development.', 'mixed'),
('e8b3c6ba-4a7c-43cb-bc45-911a36cc14c6', 'Dead Clean a Push Press con Kettlebell doble', 6, NULL, 281, 1, 'Intermedio', 'Lleva dos Kettlebells desde el suelo hasta los hombros de forma explosiva y, sin pausa, lánzalas sobre la cabeza usando el impulso de las piernas.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Dead Clean a Push Press with Double Kettlebell', 'Explosively lift two kettlebells from the floor to your shoulders and, without pausing, throw them overhead using the momentum of your legs.', 'external'),
('e8c3ca63-a844-49f1-aae9-dad1e79767c5', 'Tuck Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Cuélgate de las anillas y mantén el cuerpo paralelo al suelo boca abajo con las rodillas encogidas hacia el pecho.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Tuck Back Lever on Rings', 'Hang from the rings and hold your body parallel to the floor face down with your knees tucked toward your chest.', 'bodyweight'),
('e8e43ffb-6aa0-404b-b223-4fab9e173376', 'Manna', 25, 6, 1, 24, 'Avanzado', 'Progresión extrema del V-sit donde las caderas se elevan por encima del nivel de las manos. Una de las habilidades más difíciles de calistenia. Requiere compresión y fuerza excepcionales. Solo alcanzable tras años de preparación específica.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Manna', 'Extreme V-sit progression where the hips are raised above the level of the hands. One of the most difficult calisthenics skills. Requires exceptional compression and strength. Only achievable after years of specific preparation.', 'bodyweight'),
('e8f02a03-600d-46f3-8b38-e510da9837f3', 'Sóleo con rodilla flexionada', 309, 64, 1, 1, 'Principiante', 'Realiza elevaciones de sóleo con la rodilla flexionada. Mantén la rodilla doblada para enfatizar el sóleo y eleva el talón de forma controlada.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Bent-Knee Soleus Raise', 'Perform bent-knee soleus raises. Keep the knee bent to emphasize the soleus and lift the heel under control.', 'mixed'),
('e92b3390-fd1e-4683-89f4-3ff3c6538e4e', 'Sentadilla con barra', 28, 29, 116, 1, 'Avanzado', 'Sentadilla trasera con barra para fuerza de piernas, manteniendo brace abdominal, rodillas alineadas y profundidad consistente.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Barbell squat', 'Barbell back squat for leg strength, maintaining abdominal brace, knees aligned and consistent depth.', 'external'),
('e966fd7a-3be5-4fba-a8f4-83e20d6e9cb1', 'Snatch a Zancada inversa Overhead contralateral con Kettlebell', 28, 29, 281, 1, 'Avanzado', 'Realiza un snatch y, manteniendo la pesa bloqueada arriba, ejecuta una zancada atras con la pierna opuesta al brazo de carga.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Contralateral Overhead Reverse Lunge from Snatch with Kettlebell', 'Perform a snatch and, keeping the weight locked above, perform a lunge back with the leg opposite the carrying arm.', 'external'),
('e9873691-3d69-45ba-83f1-ad9222b2fe86', 'Press inclinado con barra', 1, 2, 116, 1, 'Avanzado', 'Press inclinado con barra para priorizar pectoral superior y deltoide anterior, manteniendo escápulas retraídas y controlando la bajada.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Incline Barbell Press', 'Incline barbell press to prioritize the upper pectoral and anterior deltoid, keeping the scapulae retracted and controlling the descent.', 'external'),
('e9c99ac9-dabc-44b1-a041-ca131f3f0155', 'Flexión pliométrica arquera', 1, 2, 1, 1, 'Avanzado', 'En cada flexión explosiva, cambia el peso hacia un brazo mientras el otro se extiende lateralmente. Potencia unilateral de empuje. Cue: cuerpo rígido como una tabla. Error común: rotar la cadera hacia un lado.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Archery Plyometric Push-up', 'In each explosive push-up, shift your weight to one arm while the other extends laterally. Unilateral thrust power. Cue: rigid body like a board. Common mistake: rotating the hip to one side.', 'mixed'),
('e9fdc582-66f4-4d4d-8861-2f14e6cdbcef', 'Pike Pushups pies elevados', 6, 2, 1, 1, 'Avanzado', 'Flexión hombro pies en banco. Objetivo: fuerza hombro. Cue: frente ante manos. Error: arquear espalda.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Pike Push-Ups with Feet Elevated', 'Perform the movement with your feet on a bench to emphasize the shoulders. Target: shoulder strength. Cue: bring your forehead in front of your hands. Common mistake: arching your back.', 'mixed'),
('ea2859d2-3275-4d6d-9f22-2527fc51c8fa', 'Remo TRX', 16, 17, 216, 1, 'Principiante', 'Inclinado hacia atrás sujetando las correas, tira del cuerpo hacia las manos. Ajusta el ángulo del cuerpo para modificar la dificultad. Mantén el cuerpo recto como una tabla y aprieta los omóplatos al final.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX rower', 'Leaning back holding the straps, pull the body towards the hands. Adjust the body angle to modify the difficulty. Keep your body straight like a board and squeeze your shoulder blades together at the end.', 'bodyweight'),
('ea2b760c-a78b-4028-a739-549a87ade2e9', 'Remo con mancuernas en banco inclinado', 71, 17, 81, 1, 'Intermedio', 'Pecho apoyado en banco a 45 grados, rema con ambas mancuernas. Aísla espalda. Cabeza apoyada. No levantes el pecho del banco.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Incline Bench Dumbbell Row', 'Chest resting on a bench at 45 degrees, row with both dumbbells. Isolates back. Supported head. Don''t lift your chest off the bench.', 'external'),
('ea8892f9-4aee-4256-98f7-bd7a80e61b26', 'Remo bajo a una mano en TRX', 71, 17, 216, 1, 'Principiante', 'Sostén una correa de TRX con una mano. Inclínate hacia atrás y tira del cuerpo hacia arriba llevando el codo pegado a las costillas.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'One-Handed Low Row on TRX', 'Hold a TRX strap with one hand. Lean back and pull your body up, keeping your elbow close to your ribs.', 'bodyweight'),
('eaaeaa88-f499-4ed3-8c40-1913486122b9', 'Sentadilla cosaca alterna Goblet en Landmine', 28, 29, 116, 1, 'Intermedio', 'Sujeta el extremo de la barra Landmine frente al pecho. Realiza desplazamientos laterales profundos alternando piernas para trabajar aductores.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Goblet Alternating Cossack Squat in Landmine', 'Hold the end of the Landmine bar in front of your chest. Perform deep lateral movements alternating legs to work adductors.', 'external'),
('eae757a9-5c76-4281-90c4-ea1b6ddfe16e', 'Muscle ups', 16, 1, 1, 1, 'Avanzado', 'Comienza con una dominada explosiva que te permita elevar el pecho por encima de la barra. En el punto más alto, realiza una transición rápida rotando las muñecas y empujando hacia abajo para terminar en posición de fondo. Requiere fuerza explosiva, técnica y coordinación perfecta entre tracción y empuje.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Muscle Ups', 'Start with an explosive pull-up that allows you to raise your chest above the bar. At the highest point, make a quick transition by rotating your wrists and pushing down to finish in the bottom position. It requires explosive strength, technique and perfect coordination between pulling and pushing.', 'mixed'),
('eaedc357-6d80-48ff-b217-f701c944d0da', 'Marcha cable', 25, NULL, 151, 24, 'Avanzado', 'Marcha en el sitio sosteniendo cable en posición de Pallof press. Combina anti-rotación con estabilización dinámica. Levanta rodillas alto manteniendo torso estable. Intensidad brutal para el core.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable walking', 'March in place holding cable in Pallof press position. Combines anti-rotation with dynamic stabilization. Raise your knees high while keeping your torso stable. Brutal intensity for the core.', 'external'),
('eafb0f43-d1d8-4741-98e1-cccfcccf2752', 'Press de bandera frontal alterno con Clubbell', 6, 2, 81, 1, 'Intermedio', 'Sostén dos mazas frente al pecho. Extiende un brazo hacia adelante manteniendo la maza vertical y el core estable para resistir la palanca, luego alterna.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Alternating Front Flag Press with Clubbell', 'Hold two clubs in front of your chest. Extend one arm forward, keeping the club vertical and core stable to resist the leverage, then alternate.', 'external'),
('eafb5c18-430d-4114-abd0-54ef06d12527', 'Pulldown máquina', 16, 17, 186, 1, 'Principiante', 'Similar al jalón con cable pero en máquina de placas. Tira hacia abajo hasta el pecho manteniendo el torso estable. Algunas máquinas permiten agarre independiente para cada brazo. Excelente para principiantes que no pueden hacer dominadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Pulldown machine', 'Similar to the cable pull but on a plate machine. Pull down to your chest, keeping your torso stable. Some machines allow independent grip for each arm. Great for beginners who can''t do pull-ups.', 'external'),
('eb014b78-1f49-46db-bf40-915d72e9a93f', 'Straddle Planche en anillas', 25, 6, 1, 24, 'Avanzado', 'Posicion de plancha horizontal en anillas con las piernas abiertas, un ejercicio de gimnasia de alto nivel por la inestabilidad añadida.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Straddle Planche on Rings', 'Hold a horizontal planche on the rings with your legs opened in a straddle, a high-level gymnastics movement due to the instability of the rings.', 'bodyweight'),
('eb1f902a-7566-4cc4-b500-5f66412d78c1', 'Rodamiento desde pared', 25, NULL, 271, 1, 'Avanzado', 'Roll out vertical contra una pared. Buena progresión para roll out de pie. Comienza con pies cerca de la pared y aléjate gradualmente. Mantén el cuerpo en línea recta durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bearing from wall', 'Vertical roll out against a wall. Good progression for standing roll out. Start with your feet close to the wall and gradually move away. Keep your body in a straight line throughout the movement.', 'external'),
('eb2c88e6-6a58-4615-8c3d-f721299129db', 'Remo Yates supinado', 71, 17, 116, 1, 'Intermedio', 'Remo inclinado con palmas hacia arriba a 45 grados. Enfoca dorsal inferior. Cue: tira hacia el ombligo. Error: usar balanceo de piernas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Supinated Yachting Rower', 'Bent-over row with palms facing up at 45 degrees. Lower dorsal focus. Cue: pull towards the navel. Common mistake: using leg swing.', 'external'),
('eb376635-4a4b-4a0e-b60f-d6455cd9e928', 'Remo bajo cable', 16, 17, 151, 1, 'Principiante', 'Con la polea en posición baja, realiza el remo tirando hacia el abdomen inferior. Esta variación permite un ángulo diferente de tracción que puede ser más cómodo para algunos. Mantén el core activado y evita el impulso excesivo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rowing Under Cable', 'With the pulley in a low position, perform the row by pulling towards the lower abs. This variation allows for a different angle of pull that may be more comfortable for some. Keep your core activated and avoid excessive momentum.', 'external'),
('eb4ad2ad-5b0d-49d3-8ca6-496e27a2f2a2', 'Curl de bíceps en polea alta unilateral', 17, NULL, 151, 1, 'Intermedio', 'De lado a la polea alta, flexiona el brazo llevando el agarre hacia la oreja. Objetivo: pico del bíceps. Cues: codo alto y fijo en el aire. Error común: bajar el codo durante la flexión.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Unilateral High Cable Biceps Curl', 'From your side to the high cable, flex your arm, bringing your grip towards your ear. Target: peak of the biceps. Cue: elbow high and fixed in the air. Common mistake: lowering the elbow during flexion.', 'external'),
('eb5041bc-c0f3-4a86-be45-21b1b8774a96', 'Salto horizontal una pierna', 28, 29, 1, 1, 'Avanzado', 'Salto hacia adelante máximo con una sola pierna. Prueba clásica de potencia unilateral. Aterriza con la misma pierna manteniendo el equilibrio. Mide la distancia para trackear progreso. Fundamental para muchos deportes.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One leg horizontal jump', 'Maximum forward jump with one leg. Classic unilateral power test. Land on the same leg while maintaining balance. Measure distance to track progress. Fundamental for many sports.', 'bodyweight'),
('eb93f9fc-65e2-4285-a5c6-1572962a6def', 'Spider Curl con barra Z', 17, NULL, 116, 1, 'Intermedio', 'Apoya el pecho en un banco inclinado. Con los brazos colgando, usa una barra Z para hacer curl, manteniendo la parte superior del brazo inmóvil.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Spider Curl with Z Bar', 'Rest your chest on an inclined bench. With your arms hanging, use a Z bar to curl, keeping your upper arm still.', 'external'),
('eb959c2a-80e8-4160-81e0-f42fa4220d99', 'Remo Pendlay con mancuerna a una mano', 71, 17, 81, 1, 'Principiante', 'Con el torso paralelo al suelo, rema una mancuerna desde una parada muerta en el suelo hasta tu costado, alternando brazos.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-Handed Pendlay Dumbbell Row', 'With your torso parallel to the floor, row a dumbbell from a dead stop on the floor to your side, alternating arms.', 'external'),
('eb9cc845-bc9c-41dc-849d-a7a010759e4b', 'Step-down controlado', 28, 29, 1, 1, 'Intermedio', 'Realiza un step-down bajando desde un cajón o escalón de forma lenta y controlada. Mantén la rodilla alineada con el pie y evita que la pelvis caiga.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Controlled Step-Down', 'Perform a controlled step-down from a box or step. Keep the knee aligned with the foot and prevent the pelvis from dropping.', 'mixed'),
('ebda3a92-dd1f-47b5-9ca9-ff9b4d82b9bd', 'Zancadas laterales', 29, 28, 1, 1, 'Principiante', 'Da un paso amplio hacia un lado, flexionando la rodilla de ese lado mientras mantienes la pierna opuesta extendida. Desciende empujando las caderas hacia atrás y manteniendo el pecho erguido. Empuja con el talón para volver al centro. Trabaja la movilidad lateral y fortalece glúteos y abductores.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lateral Lunges', 'Take a wide step to one side, bending the knee on that side while keeping the opposite leg extended. Lower by pushing your hips back and keeping your chest up. Push through the heel to return to center. It works lateral mobility and strengthens the glutes and abductors.', 'mixed'),
('ebdcf6fd-2f23-4860-a8af-38c43e288ee5', 'Step-up lateral mancuernas', 29, 37, 81, 1, 'Intermedio', 'Sube al cajón de lado. Objetivo: glúteo medio. Cue: rodilla estable. Error: saltar con pie suelo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Side Dumbbell Step-up', 'Step onto the box from the side. Target: glute medius. Cue: keep the knee stable. Common mistake: pushing off the foot on the floor.', 'external'),
('ebe03021-94b4-4a3d-85b8-e33513d791a8', 'Tibial raises', 64, 309, 1, 1, 'Principiante', 'Realiza elevaciones tibiales apoyando los talones y elevando la punta de los pies hacia la espinilla. Controla la bajada y mantén la tensión en la parte anterior de la pierna.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Tibialis Raises', 'Perform tibialis raises by keeping the heels supported and lifting the toes toward the shin. Control the lowering phase and keep tension in the front of the lower leg.', 'bodyweight'),
('ebf41762-888e-45fd-a054-a609c6e7846c', 'Patada tríceps mancuernas', 2, NULL, 81, 1, 'Principiante', 'Inclínate hacia adelante con una mancuerna en cada mano. Mantén los brazos superiores paralelos al suelo y extiende los antebrazos hacia atrás hasta que los brazos estén completamente rectos. Mantén la contracción un segundo antes de volver a flexionar.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Triceps Kick', 'Lean forward with a dumbbell in each hand. Keep your upper arms parallel toward the floor and extend your forearms back until your arms are completely straight. Hold the contraction for a second before flexing again.', 'external'),
('ec019c78-ac40-4e1f-beb6-bd019bd62b49', 'Pike con Slider', 25, 6, 1, 1, 'Avanzado', 'En posición de plancha con los pies en sliders, mantén las piernas rectas y eleva las caderas hacia el techo deslizando los pies hacia las manos, formando una V invertida.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Pike with Slider', 'Start in a plank position with your feet on sliders, keep your legs straight, and raise your hips toward the ceiling as you slide your feet toward your hands, forming an inverted V.', 'bodyweight'),
('ec11f129-3722-4194-86b2-0c369f29aa84', 'Dominadas con banda', 16, 17, 61, 1, 'Principiante', 'Usa banda para asistir subida. Objetivo: progresión dominada. Cue: controla bajada. Error: soltar rápido.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Band Pull-ups', 'Use band to assist climb. Target: mastered progression. Cue: controls descent. Common mistake: quick release.', 'assisted'),
('ec284c3e-e3a3-42c0-986d-33258ba7bae9', 'Press Seesaw de rodillas con Kettlebell doble', 6, 2, 281, 1, 'Avanzado', 'Arrodillado, presiona una Kettlebell mientras bajas la otra simultáneamente en un movimiento fluido de sube y baja (balancín).', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Double kettlebell Kneeling Seesaw Press', 'Kneeling, press one kettlebell while lowering the other simultaneously in a fluid see-saw motion.', 'external'),
('ec39be67-665e-4c3a-90f1-0363a3838c62', 'Stability Ball Stir the Pot', 25, 6, 290, 1, 'Intermedio', 'Colócate en posición de plancha con los antebrazos sobre el Fitball. Manteniendo el cuerpo rígido, haz círculos pequeños con los codos moviendo el balón, como si removieras una olla.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball Stir the Pot', 'Get into a plank position with your forearms on the stability ball. Keeping your body rigid, make small circles with your forearms without moving your hips.', 'bodyweight'),
('ec483a2c-e446-420c-adea-1970b3f195f9', 'Press de banca con mancuernas plano', 1, 2, 81, 1, 'Principiante', 'Baja mancuernas al pecho y empuja en banco plano. Cue: controla el descenso. Error: chocar pesas.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'Flat Dumbbell Bench Press', 'Lower dumbbells to your chest and push up on a flat bench. Cue: controls the descent. Common mistake: colliding weights.', 'external'),
('ec5a5c9e-ea28-4d76-b4de-5a81883bd31e', 'Sentadilla cossack salto', 28, 37, 1, 1, 'Avanzado', 'Transición explosiva entre sentadillas cossack alternando lados con un salto. Requiere movilidad, fuerza y potencia. Excelente para deportes que requieren cambios de dirección rápidos. Mantén el control en los aterrizajes.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cossack jump squat', 'Explosive transition between Cossack squats alternating sides with a jump. It requires mobility, strength and power. Excellent for sports that require quick changes of direction. Maintain control on landings.', 'mixed'),
('ec970e83-b7de-4ab0-a7e1-5cdb6e8f3c46', 'Straddle Back Lever en anillas', 25, 71, 1, 24, 'Avanzado', 'Posicion de back lever manteniendo las piernas estiradas y abiertas en V para reducir el brazo de palanca y facilitar el control.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Straddle Back Lever on Rings', 'Hold a back lever position on the rings with your legs straight and opened in a straddle to reduce the lever length and make the exercise slightly easier.', 'bodyweight'),
('ece06644-976f-4340-8d0b-271b92717f24', 'Mountain climber TRX', 25, 6, 216, 1, 'Intermedio', 'Con los pies en las correas en posición de plancha, alterna llevando las rodillas hacia el pecho. La inestabilidad del TRX aumenta significativamente el trabajo del core. Mantén las caderas bajas y el movimiento controlado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Mountain climber TRX', 'With your feet in the straps in a plank position, alternate bringing your knees toward your chest. The instability of the TRX significantly increases the work of the core. Keep your hips low and your movement controlled.', 'bodyweight'),
('ed0526f3-e02b-4ef4-862a-9748c3d3ec47', 'Inchworm', 13, NULL, 1, 1, 'Intermedio', 'Desde posición de pie, inclínate hacia adelante colocando las manos en el suelo. Camina con las manos hacia adelante hasta llegar a posición de plancha. Realiza una flexión opcional, luego camina con los pies hacia las manos manteniendo las piernas lo más rectas posible. Incorpórate y repite.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Inchworm', 'From a standing position, lean forward with your hands on the floor. Walk your hands forward until you reach a plank position. Perform an optional push-up, then walk your feet toward your hands, keeping your legs as straight as possible. Sit up and repeat.', 'mixed'),
('ed054b1e-1313-4a59-9ae8-617f7351d846', 'Press Militar con barra', 6, 2, 116, 1, 'Intermedio', 'Empuja la barra sobre la cabeza estando de pie sin ayuda de piernas. Objetivo: fuerza pura de hombros. Cue: aprieta glúteos y core. Error común: arquear la espalda lumbar al final.', FALSE, NULL, '2026-01-16T12:32:55.307484+00:00', 'Military Press with Bar', 'Push the bar overhead while standing without the help of your legs. Target: pure shoulder strength. Cue: squeeze glutes and core. Common mistake: arching the lower back at the end.', 'external'),
('ed202210-1374-427e-8caa-4179c261217c', 'Step Up ipsilateral con Kettlebell a una mano (Maleta)', 28, 29, 281, 1, 'Intermedio', 'Sube al banco con la pierna del mismo lado en el que sostienes la Kettlebell a un costado, manteniendo el torso perfectamente erguido.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Ipsilateral Single-Kettlebell Suitcase Step-up', 'Step onto the bench with the leg on the same side as the kettlebell held at your side, keeping your torso stable throughout the movement.', 'external'),
('ed305319-32d1-4561-89da-d1116e91f3b7', 'Press un brazo TRX', 1, 25, 216, 1, 'Avanzado', 'Press unilateral con máxima inestabilidad. Requiere fuerza y control excepcionales. El brazo libre puede estar extendido para balance. Progresa desde press bilateral dominando primero el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX arm press', 'Unilateral press with maximum instability. Requires exceptional strength and control. The free arm may be extended for balance. Progress from bilateral press by first mastering the movement.', 'bodyweight'),
('ed3fad39-3fdd-4c9e-b9b8-7527105771f5', 'TRX Elevación en Y', 71, 6, 216, 1, 'Principiante', 'Inclinado atrás, eleva los brazos extendidos formando una Y. Enfoca en espalda alta. Brazos rectos. No encojas los hombros.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'TRX Y Raise', 'Lean back and raise your straight arms into a Y shape. Focus on the upper back, keep your arms straight, and do not shrug your shoulders.', 'bodyweight'),
('ed66cc61-2858-410b-8bea-bb5fc4ee013a', 'Salto de valla a una pierna frontal', 29, 55, 1, 1, 'Avanzado', 'Salta hacia adelante sobre vallas bajas con una sola pierna. Potencia y coordinación. Cue: impulsa con los brazos. Error común: arrastrar el pie por falta de elevación.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Single-Leg Forward Hurdle Jump', 'Jump forward over low hurdles on one leg. Builds power and coordination. Cue: use your arms to help drive the jump. Common mistake: dragging your foot because of limited knee lift.', 'bodyweight'),
('ed9031ae-1e4d-46ff-a5ca-b0ab508372da', 'Press de pecho unilateral en cable', 1, 25, 151, 1, 'Intermedio', 'Empuja un solo estribo de polea al frente mientras mantienes el cuerpo estable. Objetivo: pectoral y anti-rotación. Cues: pies bien anclados. Error común: permitir que el cable gire tu tronco al volver.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Unilateral Cable Chest Press', 'Push a single pulley stirrup in front while keeping your body stable. Target: chest and anti-rotation. Cue: feet well anchored. Common mistake: allowing the cable to rotate your torso when returning.', 'external'),
('edb496e5-ac61-4bd0-8426-72816ba7c403', 'Press Z alterno con mancuernas', 6, 25, 81, 1, 'Intermedio', 'Sentado en el suelo con piernas en V, realiza press de hombros alternando los brazos de forma continua sin apoyo en la espalda.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Dumbbell Alternating Z Press', 'Sitting on the floor with legs in a V, perform shoulder presses, alternating your arms continuously without support on your back.', 'external'),
('edbba395-700d-48df-a1b7-a4ef6e3d8be4', 'Thrusters mancuernas', 6, 28, 81, 1, 'Intermedio', 'Combina una sentadilla frontal con un press de hombros en un movimiento fluido. Desciende en sentadilla con las mancuernas a la altura de los hombros, y al subir usa el impulso para presionar las mancuernas sobre la cabeza. Excelente ejercicio metabólico de cuerpo completo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dumbbell Thrusters', 'Combine a front squat with an overhead press in one fluid movement. Descend with the dumbbells at shoulder height and use the upward drive to press them overhead. This is an excellent full-body metabolic exercise.', 'external'),
('ee20197b-8737-4ed5-bdcc-bc863ce41f5a', 'Flexiones inclinadas', 1, 6, 1, 1, 'Principiante', 'Coloca las manos sobre una superficie elevada como un banco, escalón o barra. Mantén el cuerpo recto y desciende el pecho hacia la superficie elevada. Esta variación reduce la carga de peso corporal, haciéndola ideal para principiantes o como ejercicio de calentamiento. Cuanto más alta sea la superficie, más fácil será el ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Incline Push-ups', 'Place your hands on an raised surface such as a bench, step, or bar. Keep your body straight and lower your chest toward the raised surface. This variation reduces the body weight load, making it ideal for beginners or as a warm-up exercise. The higher the surface, the easier the exercise will be.', 'mixed'),
('ee41cbff-f09a-4d78-a50b-748df47ee439', 'Snatch unilateral con kettlebell', 13, 29, 281, 1, 'Avanzado', 'Lleva la pesa desde el suelo hasta encima de la cabeza en un solo movimiento explosivo. Objetivo: potencia de cadera. Cues: estira el brazo cerca de la oreja. Error común: golpear el antebrazo con la pesa al bloquear.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Unilateral Kettlebell Snatch', 'Bring the weight from the floor to overhead in a single explosive movement. Target: hip power. Cue: Stretch your arm near your ear. Common mistake: hitting the forearm with the weight when blocking.', 'external'),
('ee5dcab4-6645-4a22-8ff9-8ee04f7bc466', 'Ondas dobles battle ropes', 6, 25, 256, 24, 'Avanzado', 'Ambas cuerdas suben y bajan simultáneamente con máxima amplitud. Requiere mayor potencia que ondas alternadas. Usa todo el cuerpo para generar las ondas, no solo brazos. Mantén ritmo constante.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Ropes Double Waves', 'Both ropes rise and fall simultaneously with maximum amplitude. This requires more power than alternating waves. Use your whole body to generate the waves, not just your arms. Maintain a steady rhythm.', 'external'),
('ef01c596-306b-4d7a-b29c-1a2cf2739d23', 'Dead Clean con Kettlebell a una mano', 29, 6, 281, 1, 'Intermedio', 'Lleva la pesa rusa desde el suelo hasta la posicion rack en un solo movimiento explosivo de cadera, evitando que la pesa golpee el antebrazo.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Dead Clean with One-Handed Kettlebell', 'Bring the kettlebell from the floor to the rack position in a single explosive hip movement, avoiding the weight from hitting the forearm.', 'external'),
('ef0539f8-c30d-4754-8d5c-903d790b54f3', 'Zancada trasera con mancuernas', 28, 29, 81, 1, 'Principiante', 'Sujeta mancuernas a los lados y da un paso atrás bajando la rodilla trasera hacia el suelo. Objetivo: fuerza de piernas. Cue: mantén el torso erguido. Error: dejar que la rodilla delantera sobrepase demasiado el pie.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Rear Dumbbell Stride', 'Hold dumbbells to the sides and step back by lowering your back knee to the floor. Target: leg strength. Cue: keep your torso upright. Common mistake: Let the front knee overshoot the foot too much.', 'external'),
('ef547e82-d621-4a6c-9e80-d93958388df0', 'Sentadilla Ciclista Overhead con barra', 28, 6, 116, 1, 'Avanzado', 'Con talones elevados, realiza una sentadilla profunda manteniendo la barra bloqueada sobre la cabeza, exigiendo movilidad y equilibrio total.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'Cycling Overhead Squat with Barbell', 'With heels raised, perform a deep squat keeping the bar locked overhead, demanding total mobility and balance.', 'external'),
('ef64612c-9103-4fbf-89be-040d15d67a3a', 'Zancada inversa con Slider y Kettlebell doble (Maleta)', 28, 29, 281, 1, 'Intermedio', 'Sostén dos pesas rusas a los lados (estilo maleta). Coloca un pie sobre un slider y deslízalo hacia atrás en una zancada profunda, manteniendo el torso erguido, luego regresa.', FALSE, NULL, '2026-02-02T13:02:01.826349+00:00', 'Reverse stride with Slider and Double Kettlebell (Suitcase)', 'Hold two kettlebells on the sides (suitcase style). Place one foot on a slider and slide it back in a deep stride, keeping your torso upright, then return.', 'external'),
('ef7e6d17-a917-4944-a01e-2de9c773d4f6', 'Sentadilla Búlgara con mancuernas (Maleta)', 28, 29, 81, 1, 'Intermedio', 'Sostén dos mancuernas a los costados con un pie elevado en un banco tras de ti. Baja la cadera verticalmente y vuelve a subir.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Bulgarian Squat with Dumbbells (suitcase)', 'Hold two dumbbells at your sides with one foot raised on a bench behind you. Lower your hips vertically and raise them again.', 'external'),
('ef85345b-3f46-4367-b5d7-569395c72523', 'Crunch abdominal polea alta', 25, NULL, 151, 1, 'Intermedio', 'De rodillas, flexiona torso hacia abajo con cuerda. Cue: exhala al bajar. Error: tirar con los brazos.', FALSE, NULL, '2026-01-16T10:17:19.866423+00:00', 'High Cable Abdominal Crunch', 'On your knees, bend your torso down with a rope. Cue: exhale on the way down. Common mistake: pulling with your arms.', 'external'),
('efa07710-1799-4acf-91e6-1de0936a6843', 'Aperturas planas mancuerna', 1, NULL, 81, 1, 'Principiante', 'Abre brazos banco plano. Objetivo: estiramiento pecho. Cue: codos semiflexionados. Error: bajar mucho.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Flat Dumbbell Fly', 'Lie on a flat bench, open your arms with a slight bend in the elbows, and bring the dumbbells back together above your chest. Target: chest stretch. Cue: keep a soft bend in the elbows. Common mistake: going too low.', 'external'),
('efc3abf8-3677-4316-b333-5d1333f3abe8', 'Lunge twist', 28, 25, 240, 1, 'Intermedio', 'Realiza zancadas mientras rotas el torso hacia el lado de la pierna adelantada sosteniendo el balón. Combina fuerza de piernas con rotación del core. Mantén el balón alejado del cuerpo para mayor desafío.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Lunge Twist', 'Perform lunges while rotating your torso toward the side of your lead leg holding the ball. Combines leg strength with core rotation. Keep the ball away from your body for added challenge.', 'external'),
('efdde8cf-3c20-4a2c-9479-e025d66c057c', 'Bear crawl', 6, 25, 1, 1, 'Intermedio', 'Comienza en cuadrupedia con las rodillas elevadas a pocos centímetros del suelo. Avanza moviendo simultáneamente la mano derecha con el pie izquierdo, luego la mano izquierda con el pie derecho. Mantén la espalda plana y el core activado. Este ejercicio mejora la coordinación y fortalece todo el cuerpo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bear Crawl', 'Start on all fours with your knees elevated a few centimeters off the ground. Move forward by simultaneously moving your right hand with your left foot, then your left hand with your right foot. Keep your back flat and core activated. This exercise improves coordination and strengthens the entire body.', 'bodyweight'),
('f0002672-31db-4dfb-8990-8fa511eb60f9', 'Press Pallof medio arrodillado con banda', 25, 6, 61, 1, 'Principiante', 'Realiza el press Pallof en posición de caballero, lo que aumenta el reto sobre la estabilidad de la pelvis y el torso.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Banded Half Kneeling Pallof Press', 'Perform the Pallof press in a half-kneeling position, which increases the challenge on the stability of the pelvis and torso.', 'external'),
('f0245033-a2c1-40f0-ae62-2d446d8c5290', 'Victorian', 6, 25, 1, 24, 'Avanzado', 'Variación del planche donde las piernas se extienden hacia adelante en lugar de hacia atrás. Aún más difícil que el planche tradicional debido al brazo de palanca desfavorable. Solo alcanzable por atletas de élite con años de entrenamiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Victorian', 'A planche variation where the legs extend forward instead of backward. It is even harder than a traditional planche because of the unfavorable lever arm. Only elite athletes with years of training can achieve it.', 'bodyweight'),
('f0a950ac-6a26-4b15-a03e-658a9ae659a1', 'Remo Meadows en Landmine', 71, 17, 116, 1, 'Intermedio', 'De pie perpendicular a la barra Landmine. Agarra el extremo grueso con una mano y rema llevando el codo hacia afuera y arriba.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Landmine Meadows Row', 'Stand perpendicular to the landmine bar, grab the thick end with one hand, and row it upward and outward.', 'external'),
('f0f95377-a307-4805-bea1-e76f8d40312b', 'Plank a una mano en TRX', 25, 6, 216, 24, 'Avanzado', 'En posición de plancha con una mano en el estribo del TRX, mantén el cuerpo alineado resistiendo la inestabilidad de la suspensión.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'One-Handed Plank on TRX', 'In a plank position with one hand on the footpeg of the TRX, keep your body aligned while resisting suspension instability.', 'bodyweight'),
('f0ffdd26-67cd-43ed-a9cd-0d5fd948dac7', 'Swing en postura escalonada con Kettlebell a una mano', 29, 55, 281, 1, 'Intermedio', 'Realiza un swing unilateral con un pie ligeramente retrasado (postura de split), lo que aumenta la demanda de estabilidad en la pierna delantera.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Single-Arm Kettlebell Swing in Staggered Stance', 'Perform a unilateral swing with one foot slightly staggered back, which increases the stability demand on the front leg.', 'external'),
('f128dd5f-e5f7-461f-8578-7f535c0cd11d', 'Puente glúteo unilateral pausa 2s', 29, 55, 1, 1, 'Principiante', 'Eleva cadera a un pie y mantén. Cue: cadera alineada. Error: caer de lado.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Unilateral Gluteal Bridge Pause 2s', 'Raise your hips to one foot and hold. Cue: hip aligned. Common mistake: falling sideways.', 'bodyweight'),
('f132c788-0a63-4ecd-9e1e-00a6a1a6bb90', 'Jalón al pecho unilateral', 16, 17, 186, 1, 'Intermedio', 'Tira de una sola palanca en máquina. Objetivo: corregir asimetrías. Cues: aprieta el dorsal. Error común: inclinar mucho el cuerpo.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Unilateral Chest Pull', 'Pull a single lever on machine. Target: correct asymmetries. Cue: squeeze your dorsal. Common mistake: leaning your body too much.', 'external'),
('f1468a2c-b686-4570-90f1-63b344c5a05a', 'Plancha comando', 25, 6, 1, 24, 'Intermedio', 'Pasa de apoyo de antebrazos a manos alternativamente. Estabilidad y brazos. Cadera quieta. No balancees el cuerpo de lado.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Commando Plank', 'Alternate between forearm support and hand support. Target: stability and arm strength. Cue: keep your hips still. Common mistake: rocking your body side to side.', 'bodyweight'),
('f14b9e08-e88b-4a37-ae3e-6337dd11de15', 'Bird Dog alterno', 25, 71, 1, 1, 'Principiante', 'En cuadrupedia, extiende brazo y pierna contraria manteniendo el equilibrio. Objetivo: estabilidad lumbopélvica. Cue: no permitas que la cadera rote. Error común: arquear la espalda excesivamente al estirar.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Bird Dog Alternate', 'On all fours, extend your opposite arm and leg while maintaining balance. Target: lumbopelvic stability. Cue: don''t allow the hip to rotate. Common mistake: arching your back excessively when stretching.', 'bodyweight'),
('f169d0fc-fbae-45ae-95d9-be1922b2104c', 'Sentadilla postura amplia', 29, 28, 116, 1, 'Avanzado', 'Sentadilla con pies muy separados y puntas hacia afuera. Estilo powerlifting. Enfatiza glúteos y aductores. Permite mover más peso en algunos levantadores. Requiere buena movilidad de caderas. Rodillas siguen la línea de los pies.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Wide stance squat', 'Squat with feet wide apart and toes facing out. Powerlifting style. Emphasizes glutes and adductors. Allows more weight to be moved for some lifters. Requires good hip mobility. Knees follow the line of the feet.', 'external'),
('f16fbeb6-5856-4331-a2a5-819caa064e39', 'Bird Dog estático', 25, 71, 1, 24, 'Principiante', 'En cuadrupedia, extiende brazo y pierna contraria. Cue: espalda neutra, no rotes cadera. Error: levantar brazo y pierna demasiado rompiendo la línea.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Static Bird Dog', 'On all fours, extend the opposite arm and leg. Cue: neutral back, don''t rotate hips. Common mistake: raising arm and leg too much, breaking the line.', 'bodyweight'),
('f1807a41-4e49-4d7c-a777-d6b9f5b84bfc', 'Sentadilla bosu semiesfera', 28, 29, 298, 1, 'Intermedio', 'Sentadilla sobre lado azul bosu. Objetivo: estabilidad. Cue: mirada frente. Error: rodillas dentro.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Semi-sphere BOSU Squat', 'BOSU blue side squat. Target: stability. Cue: look ahead. Common mistake: knees inside.', 'bodyweight'),
('f1938154-8cf4-42f1-a031-74ba48626606', 'Tuck Planche en paralelas', 25, 6, 1, 24, 'Avanzado', 'Sostén tu peso sobre las paralelas con los brazos bloqueados y eleva las rodillas hacia el pecho manteniendo la espalda paralela al suelo.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Tuck Planche on Parallettes', 'Support your body on the parallettes with your arms locked and pull your knees toward your chest while keeping your back parallel to the floor.', 'bodyweight'),
('f193aa17-015a-4102-bba9-f4be51a3495a', 'Sentadilla Búlgara Overhead con Kettlebell doble Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sentadilla split con pie elevado y Kettlebells invertidas bloqueadas arriba, llevando la rodilla delantera sobre los dedos.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Bulgarian Overhead Squat with Double Bottoms-Up Kettlebell', 'Split squat with raised foot and inverted kettlebells locked above, bringing the front knee over the toes.', 'external'),
('f195be9a-a21a-430e-b9c0-9fe7821e4540', 'Board Press triple tabla', 1, 2, 116, 1, 'Intermedio', 'Press banca con tres tablas sobre el pecho para limitar rango. Cue: controla el contacto. Error: hundir las tablas.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Three-Board Press', 'Perform a bench press with three boards on your chest to limit the range of motion. Cue: control the contact with the boards. Common mistake: letting the boards sink or shift.', 'external'),
('f1a28ce8-8867-42a5-a1a9-591a2f813cdd', 'Press cerrado barra', 2, 1, 116, 1, 'Intermedio', 'Realiza un press de banca con agarre cerrado (manos separadas al ancho de los hombros o menos). Desciende la barra hacia la parte inferior del pecho manteniendo los codos cerca del cuerpo. Esta variación enfatiza significativamente los tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Closed bar press', 'Perform a close-grip bench press (hands shoulder-width apart or less). Lower the bar toward your lower chest, keeping your elbows close to your body. This variation significantly emphasizes the triceps.', 'external'),
('f1c377e7-b87d-4b97-b502-433c6f93593f', 'Peso muerto rumano con barra', 55, 29, 116, 1, 'Intermedio', 'Baja la barra rozando piernas con rodillas semi-rígidas hasta sentir estiramiento en isquios. Cue: cadera hacia atrás. Error: curvar la espalda alta.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Romanian Deadlift', 'Lower the bar along your legs with a slight knee bend until you feel a stretch in your hamstrings. Cue: push your hips back. Common mistake: rounding your upper back.', 'external'),
('f1dd0223-7608-4e13-acda-0f93de8a02aa', 'Dominadas pronas (Pull-ups)', 16, 17, 1, 1, 'Intermedio', 'Cuélgate de una barra con palmas al frente y tira hasta que la barbilla pase la barra. Cue: pecho a la barra. Error: usar excesivo impulso de piernas.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Prone Chin-ups (pull-ups)', 'Hang from a bar with your palms in front of you and pull until your chin passes the bar. Cue: chest to bar. Common mistake: using excessive leg drive.', 'mixed'),
('f1e58a46-9266-468e-9830-5af6525910ff', 'Extensión de tríceps agarre inverso a una mano', 2, NULL, 151, 1, 'Principiante', 'Frente a la polea, agarra el mango con la palma hacia arriba (supino). Extiende el brazo hacia abajo aislando el tríceps.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'One Hand Reverse Grip Triceps Extension', 'Facing the cable, grip the handle with your palm facing up (supine). Extend your arm downward, isolating your triceps.', 'external'),
('f23fda48-ca02-4963-b94e-df35956f8804', 'Press Klokov', 6, 2, 116, 1, 'Avanzado', 'Press de hombros con barra tras nuca utilizando un agarre muy ancho (tipo arranque). Objetivo: fuerza de hombros y movilidad escapular. Cues: espalda neutra y core firme. Error común: realizar movimientos bruscos que estresen la articulación del hombro.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Press Klokov', 'Barbell shoulder press behind the neck using a very wide grip (snatch type). Target: shoulder strength and scapular mobility. Cue: neutral back and firm core. Common mistake: making sudden movements that stress the shoulder joint.', 'external'),
('f26ae56c-9f5d-44c1-8e34-ef1752674ab9', 'Stability Ball Russian Twist', 25, NULL, 290, 1, 'Intermedio', 'Apoya la parte superior de la espalda sobre el Fitball, con los pies planos en el suelo y las caderas elevadas. Junta las manos sobre el pecho y gira el torso hacia un lado y luego hacia el otro, manteniendo la estabilidad de las caderas.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Stability Ball Russian Twist', 'Rest your upper back on the stability ball, with your feet flat on the floor and your hips raised. Clasp your hands on your chest and turn your torso to one side and then the other, maintaining stability in your hips.', 'bodyweight'),
('f2a683fa-fb42-4e66-9425-88351a721394', 'Devil Press', 13, 6, 81, 1, 'Avanzado', 'Burpee con mancuernas seguido de un snatch doble desde el suelo. Cue: movimiento fluido, espalda neutra. Error: redondear la espalda al levantar del suelo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Devil Press', 'Dumbbell burpee followed by a double snatch from the floor. Cue: fluid movement, neutral back. Common mistake: rounding your back when lifting off the ground.', 'external'),
('f3181314-81f9-401a-8870-726f7288c4b1', 'Push Jerk a una mano con Kettlebell', 6, 28, 281, 1, 'Avanzado', 'Usa el impulso de las piernas para elevar la pesa rusa, luego flexiona las rodillas de nuevo para recibir el peso con el brazo estirado (Lockout).', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One Hand kettlebell Push Jerk', 'Use the momentum of your legs to raise the kettlebell, then bend your knees again to receive the weight with your arm straight (Lockout).', 'external'),
('f3194bef-ebdf-4389-a33c-47fa3a628cf9', 'Stalder Press a parada de manos en paralelas', 6, 25, 1, 1, 'Avanzado', 'Desde un L-Sit sentado con piernas abiertas (straddle), presiona el cuerpo hacia arriba con brazos rectos hasta la vertical.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Stalder Press to Handstand on Parallettes', 'From a seated straddle L-sit, press your body upward with straight arms until you reach a handstand on the parallettes.', 'bodyweight'),
('f3335c32-0c4e-4b54-a882-d6fd836da2e0', 'Squat Clean con barra', 28, 29, 116, 1, 'Avanzado', 'Lleva la barra desde el suelo hasta los hombros de forma explosiva y recíbela en una posición de sentadilla profunda antes de subir.', FALSE, NULL, '2026-02-02T14:58:19.299215+00:00', 'Barbell Squat Clean', 'Explosively bring the bar from the floor to your shoulders and receive it into a deep squat position before coming up.', 'external'),
('f37a35a9-8ddb-48cd-99cc-84ec6aa03938', 'Bodyweight Flutter Kicks', 25, 28, 1, 1, 'Principiante', 'Acuéstate boca arriba con las manos bajo los glúteos. Levanta ambas piernas ligeramente del suelo y realiza movimientos alternos de patada pequeña y rápida sin tocar el suelo.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Flutter Kicks', 'Lie on your back with your hands under your buttocks. Raise both legs slightly off the ground and perform alternating small, quick kick movements without touching the ground.', 'bodyweight'),
('f382f928-be54-49b1-b596-0330389ead8e', 'Trepar cuerda sin piernas', 16, 17, 1, 1, 'Avanzado', 'Trepa usando solo los brazos con las piernas extendidas sin tocar la cuerda. Requiere fuerza de tracción y agarre excepcionales. Una de las demostraciones más impresionantes de fuerza del tren superior. Progresa con trepa asistida.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Legless Rope Climb', 'Climb using only your arms, keeping your legs extended without touching the rope. This demands exceptional pulling and grip strength. Progress from assisted rope climbs.', 'bodyweight'),
('f385ad4b-1538-44f4-91ba-74fd9ab34e11', 'Step Up contralateral con Kettlebell a una mano (Maleta)', 28, 29, 281, 1, 'Intermedio', 'Sube al banco con una pierna mientras sostienes la Kettlebell en la mano opuesta (estilo maleta), desafiando la estabilidad lateral.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Contralateral Single-Kettlebell Suitcase Step-up', 'Step onto the bench with one leg while holding the kettlebell in the opposite hand in a suitcase position, challenging lateral stability.', 'external'),
('f39b4645-2c11-4420-9885-5bc215caccfb', 'Y-pull TRX', 16, 6, 216, 1, 'Intermedio', 'Desde posición inclinada, tira formando una Y con los brazos. Trabaja la espalda desde un ángulo diferente y activa más los deltoides posteriores. Mantén los brazos rectos o ligeramente flexionados durante el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'TRX Y-Pull', 'From an inclined position, pull into a Y shape with your arms. It works the back from a different angle and increases activation of the rear delts. Keep your arms straight or slightly bent throughout the movement.', 'bodyweight'),
('f3a71764-2c8b-4bc5-bfa6-fad41b0c32df', 'Burpee una pierna TRX', 13, NULL, 216, 1, 'Avanzado', 'Burpee con una pierna en la correa del TRX. Aumenta dramáticamente la dificultad y el trabajo de estabilización. Alterna piernas. Mantén el movimiento fluido a pesar de la inestabilidad.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Burpee one leg TRX', 'Burpee with one leg on the TRX strap. Dramatically increases difficulty and stabilization work. Alternate legs. Maintain fluid movement despite instability.', 'bodyweight'),
('f3bb80af-25d9-4d55-b8b6-4cc038fc2650', 'Bodyweight Alternating Lateral Kick Through', 25, 6, 1, 1, 'Intermedio', 'Desde posición de cuadrupedia con rodillas elevadas, gira el cuerpo y patea con una pierna por debajo del cuerpo hacia el lado opuesto mientras levantas la mano contraria.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Alternating Lateral Kick Through', 'From a quadruped position with knees raised, turn your body and kick one leg under your body to the opposite side while raising your opposite hand.', 'bodyweight'),
('f3e59401-47ef-4c47-9b20-86036f25b4d0', 'Russian twist balón medicinal', 25, 71, 240, 1, 'Principiante', 'Gira balón lado a lado sentado. Objetivo: oblicuos. Cue: pies aire. Error: mover solo brazos.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Russian Twist Medicine Ball', 'Roll the ball side to side while sitting. Target: obliques. Cue: feet air. Common mistake: move only arms.', 'external'),
('f3ea1b6f-d689-46e8-af5c-46172a3cbada', 'Remo prono en banco inclinado con mancuernas', 71, 17, 81, 1, 'Principiante', 'Acuéstate boca abajo en un banco inclinado. Rema ambas mancuernas hacia arriba apretando la espalda, sin usar impulso de la espalda baja.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'Prone Incline Bench Dumbbell Row', 'Lie face down on an incline bench. Row both dumbbells up, squeezing your back, without using lower back momentum.', 'external'),
('f413d7ac-ffe3-4e76-bccf-5d77fdf654e5', 'Curl bíceps polea barra recta estricto', 17, NULL, 151, 1, 'Principiante', 'Flexiona barra en polea baja. Cue: tensión constante. Error: balanceo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Strict Straight Bar Cable Biceps Curl', 'Flex bar on low cable. Cue: constant tension. Common mistake: swinging.', 'external'),
('f448af64-0e5f-430b-ad4a-f2ef2c4d7bd9', 'Salto lateral de bosu a suelo', 29, 37, 298, 1, 'Avanzado', 'Salta lateralmente desde el lado plano de un bosu hacia el suelo y estabiliza. Control de impacto inestable. Cue: clava el aterrizaje. Error común: dejar que el bosu se mueva al saltar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Side BOSU Jump Toward the Floor', 'Jump laterally from the flat side of a bosu toward the ground and stabilize. Unstable impact control. Cue: nail the landing. Common mistake: letting the bosu move when jumping.', 'bodyweight'),
('f4525288-45a4-4684-a400-21a4ee4b7bbc', 'Ring Hanging L Sit Flutter Kicks', 25, 28, 1, 1, 'Avanzado', 'Cuélgate de las anillas y levanta las piernas rectas hasta formar una L. Mantén esa posición mientras realizas patadas de aleteo (Flutter Kicks) con las piernas.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Ring Hanging L Sit Flutter Kicks', 'Hang from the rings and raise your legs straight to form an L. Hold this position while performing flutter kicks with your legs.', 'bodyweight'),
('f464fde1-09fd-457f-9fa5-65cafd1720ab', 'Zancada inversa ipsilateral con Slider y Kettlebell (Front Rack)', 28, 29, 281, 1, 'Intermedio', 'Sostén la pesa rusa en posición de rack y desliza hacia atrás la pierna del mismo lado usando un slider para un reto de equilibrio extremo.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Reverse ipsilateral stride with Slider and Kettlebell (Front Rack)', 'Hold the kettlebell in a rack position and slide back the leg on the same side using a slider for an extreme balance challenge.', 'external'),
('f4897226-6dea-40af-978f-8777c23e7784', 'Remo inclinado en banco', 16, 17, 116, 1, 'Avanzado', 'Remo con el pecho apoyado en banco inclinado. Elimina el impulso y protege la espalda baja. Permite mayor concentración en la contracción. El banco debe estar a 30-45 grados. Deja que los brazos cuelguen completamente.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bent over bench row', 'Row with the chest supported on an inclined bench. Eliminates momentum and protects the lower back. Allows greater concentration in contraction. The bench should be at 30-45 degrees. Let your arms hang completely.', 'external'),
('f4a92ac7-192d-4e71-baed-41c3d63e9e62', 'Palanca posterior', 16, 1, 1, 24, 'Avanzado', 'Similar a la palanca frontal pero mirando hacia arriba. Considerada más difícil que la frontal. Requiere fuerza y flexibilidad excepcionales en hombros. Progresa cuidadosamente para evitar lesiones. Domina la palanca frontal primero.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Rear lever', 'Similar to the front lever but facing upwards. Considered more difficult than the frontal one. Requires exceptional shoulder strength and flexibility. Progress carefully to avoid injury. Master the front lever first.', 'bodyweight'),
('f4a9daaf-2f19-4291-b2fc-554d315149f6', 'Zancada Zercher estática', 28, 25, 116, 1, 'Avanzado', 'Zancada con barra en el pliegue de codos. Cue: barra pegada al pecho. Error: inclinar el torso hacia adelante.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Static Zercher Stride', 'Stride with bar at the elbow fold. Cue: bar attached to your chest. Common mistake: Tilt torso forward.', 'external'),
('f4e33d20-32bb-499b-9a48-2cfa4f800497', 'Press Overhead de rodillas con Kettlebell doble', 6, 25, 281, 1, 'Intermedio', 'Arrodillado sobre ambas rodillas (Tall Kneeling), realiza un press de hombros con dos pesas rusas, exigiendo mayor estabilidad del core.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Double kettlebell Kneeling Overhead Press', 'Kneeling on both knees (Tall Kneeling), perform a shoulder press with two kettlebells, demanding greater core stability.', 'external'),
('f4f08874-1e91-44ad-83a0-a7b809aaf34c', 'Prensa de piernas 45 grados', 28, 29, 186, 1, 'Principiante', 'Empuja la plataforma con los pies a la anchura de hombros. Cue: no bloquees rodillas al extender. Error: bajar tanto que se levante el coxis.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', '45 Degree Leg Press', 'Push the platform with your feet to shoulder width apart. Cue: don''t lock knees when extending. Common mistake: going down so much that the tailbone rises.', 'external'),
('f51abd12-dab8-4e2a-9bc9-4594e26a0dc1', 'Parada de manos a un brazo', 6, 25, 1, 24, 'Avanzado', 'Equilibrio invertido sostenido por una sola mano. Requiere fuerza excepcional, equilibrio perfecto y años de práctica. Progresa dominando primero la parada de manos a dos brazos perfectamente. El control del core es fundamental.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'One arm handstand', 'Inverted balance held by one hand. It requires exceptional strength, perfect balance and years of practice. Progress by first mastering the two-arm handstand perfectly. Core control is essential.', 'bodyweight'),
('f563ca40-104d-457b-850f-ed22775e863a', 'Horizontal Woodchopper cable oblicuos', 25, 71, 151, 1, 'Intermedio', 'Tira cable de lado a lado. Cue: pivota pie. Error: mover solo brazos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Horizontal Woodchopper Oblique Cable', 'Pull cable from side to side. Cue: pivot foot. Common mistake: move only arms.', 'external'),
('f5710907-e29d-4c26-bd52-b330dddbe71f', 'Sentadilla 1 y 1/4', 28, 29, 1, 1, 'Avanzado', 'Baja, sube un poco, baja y sube total. Objetivo: tiempo tensión. Cue: control rebote. Error: mala postura.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Squat 1 and 1/4', 'Go down, go up a little, go down and go up completely. Target: time tension. Cue: bounce control. Common mistake: bad posture.', 'mixed'),
('f58d3fe0-4ecd-4103-a60a-59fe37e24ba7', 'Encogimientos polea baja barra trapecios', 71, 6, 151, 1, 'Principiante', 'Eleva hombros con cable al frente. Cue: no rotes hombros. Error: doblar codos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Trapeze Bar Low Cable Shrugs', 'Raise shoulders with cable in front. Cue: don''t rotate shoulders. Common mistake: bending elbows.', 'external'),
('f5914370-0521-4772-b8bb-3fbf97a1e8c8', 'Pull de Front Lever a colgado invertido en anillas', 25, 16, 1, 1, 'Avanzado', 'Desde la posicion de Front Lever, tira con fuerza de las anillas para elevar el cuerpo hasta quedar completamente invertido boca abajo.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Front Lever Pull to hanging inverted on rings', 'From the Front Lever position, pull firmly on the rings to raise the body until it is completely inverted face down.', 'bodyweight'),
('f5ff2119-41af-4377-a4f9-a93e76eb2f08', 'Toques talón suelo', 25, NULL, 1, 1, 'Principiante', 'Tumbado toca talones alternos. Objetivo: oblicuos. Cue: aprieta abdomen. Error: tirar cuello.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Heel Touches', 'Lie on your back and alternately reach for your heels. Target: obliques. Cue: brace your abs. Common mistake: pulling on your neck.', 'bodyweight'),
('f619950e-9cdb-4194-928a-564bb5e73147', 'L-Sit a Bent Arm Press Handstand en paralelas', 6, 2, 1, 1, 'Avanzado', 'Desde un L-Sit en paralelas, transiciona las piernas hacia atrás y arriba empujando el torso hasta llegar a la parada de manos vertical.', FALSE, NULL, '2026-02-02T16:00:29.164763+00:00', 'L-Sit a Bent Arm Press Handstand in Parallels', 'From a parallel L-Sit, transition your legs back and up by pushing your torso until you reach a vertical handstand.', 'bodyweight'),
('f648f3ec-fbd9-443e-ad75-4d7a0459eb00', 'Inverted Iron Cross en anillas', 71, 6, 1, 24, 'Avanzado', 'Manten el cuerpo invertido verticalmente mientras extiendes los brazos lateralmente en cruz, una variante extrema de fuerza en anillas.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Inverted Iron Cross on rings', 'Keep your body inverted vertically while extending your arms laterally in a cross, an extreme variant of ring strength.', 'bodyweight'),
('f65ee455-5923-40db-8da5-5d64064202f3', 'Plancha Spiderman', 25, 6, 1, 1, 'Intermedio', 'En posición de plancha o flexión, lleva la rodilla hacia el codo del mismo lado por fuera del cuerpo. Objetivo: oblicuos y core. Cue: mantén la cadera baja. Error: elevar el glúteo para facilitar el movimiento.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Plank Spiderman', 'From a plank or push-up position, bring your knee toward the elbow on the same side, outside the body. Target: obliques and core. Cue: keep your hips low. Common mistake: raising your glutes to make the movement easier.', 'mixed'),
('f66f6aff-0f29-4665-a7e7-1564a0320e6a', 'Plancha frontal en Fitball', 25, 6, 290, 24, 'Intermedio', 'Mantén plancha con antebrazos en fitball inestable. Objetivo: estabilidad profunda core. Cue: aprieta glúteos. Error común: que la bola se aleje demasiado del cuerpo.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Front Plank on Stability Ball', 'Hold a plank with your forearms on an unstable stability ball. Target: deep core stability. Cue: brace your glutes. Common mistake: letting the ball move too far away from your body.', 'bodyweight'),
('f6bfb695-7253-41eb-ba44-3fed0984cca6', 'Bodyweight Copenhagen Plank Knee to Elbow', 313, 25, 1, 1, 'Avanzado', 'En posición de Plank lateral con la pierna superior apoyada en un banco, lleva la rodilla de la pierna inferior hacia el codo, manteniendo la cadera alta.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Bodyweight Copenhagen Plank Knee to Elbow', 'In a Side Plank position with your top leg resting on a bench, bring the knee of your bottom leg toward your elbow, keeping your hips high.', 'bodyweight'),
('f6e5b2e8-db14-4e41-8f40-b4fd4445d582', 'Salto pogo en zigzag', 64, 309, 1, 1, 'Principiante', 'Pequeños saltos rápidos sobre puntas de pies moviéndote lateralmente hacia adelante. Agilidad. Cue: mantén pies juntos. Error común: flexionar demasiado las caderas.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Zigzag Pogo Jump', 'Small quick jumps on tiptoe moving laterally forward. Agility. Cue: keep feet together. Common mistake: flexing your hips too much.', 'bodyweight'),
('f7a34a44-9d02-44bd-9f19-c9affbcbcc1f', 'Peso muerto convencional con barra', 71, 55, 116, 1, 'Principiante', 'Levanta la barra desde el suelo manteniendo la espalda neutra, extendiendo rodillas y cadera simultáneamente hasta quedar erguido.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Conventional Barbell Deadlift', 'Lift the bar from the floor, keeping your back neutral, extending your knees and hips simultaneously until you are standing tall.', 'external'),
('f7a67add-c76d-4994-8f7e-ae94f8fc5a59', 'Zancada inversa ipsilateral con Slider y Kettlebell Bottoms Up', 28, 6, 281, 1, 'Avanzado', 'Sostén una pesa rusa invertida en una mano y desliza hacia atrás la pierna del mismo lado usando un slider, desafiando la estabilidad total.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Reverse ipsilateral stride with Slider and Kettlebell Bottoms Up', 'Hold an inverted kettlebell in one hand and slide back the leg on the same side using a slider, challenging total stability.', 'external'),
('f7ae92b4-5450-4a81-a145-d6fac4ece98b', 'Press de hombros contralateral medio arrodillado en Landmine', 6, 2, 116, 1, 'Intermedio', 'En posicion de caballero, presiona la barra Landmine con el brazo opuesto a la rodilla adelantada, trabajando la estabilidad cruzada.', FALSE, NULL, '2026-02-02T17:37:50.678067+00:00', 'Contralateral Half-Kneeling Landmine Shoulder Press', 'In a half-kneeling position, press the Landmine bar with the arm opposite the front knee, working on crossed stability.', 'external'),
('f7e4ee4f-8d92-4493-b0c5-2233b503f22e', 'Salto vertical reactivo con banda', 28, 29, 61, 1, 'Intermedio', 'Salta verticalmente con una banda elástica tirando de ti hacia abajo. Aumenta la velocidad de reclutamiento. Cue: máxima extensión de tobillo. Error común: dejar que la banda te encorve.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Reactive Vertical Jump with Band', 'Jump vertically with an elastic band pulling yourself down. Increases recruitment speed. Cue: maximum ankle extension. Common mistake: letting the band make you slouch.', 'external'),
('f80b064a-a6e1-47fa-bc87-19d658f3b163', 'Extensión de cuádriceps con banda', 28, NULL, 61, 1, 'Principiante', 'Sentado, extiende la rodilla contra la resistencia de una banda elástica anclada atrás. Objetivo: aislamiento del cuádriceps. Cues: mantén la espalda recta. Error común: realizar el movimiento con excesiva rapidez sin control.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Quadriceps Extension with Band', 'Sitting, extend your knee against the resistance of an elastic band anchored behind you. Target: isolation of the quadriceps. Cue: keep your back straight. Common mistake: performing the movement too quickly without control.', 'external'),
('f845a294-b8b9-49f0-b3e5-b7d482e49f4c', 'Sentadilla Búlgara Front Rack con Kettlebell doble Bottoms Up', 28, 29, 281, 1, 'Intermedio', 'Realiza una sentadilla split con el pie trasero elevado en un banco mientras sostienes dos Kettlebells invertidas en posicion de rack sobre el pecho.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Bulgarian Front Rack Squat with Double Bottoms-Up Kettlebell', 'Perform a split squat with your back foot raised on a bench while holding two inverted kettlebells in a rack position on your chest.', 'external'),
('f84a4a04-1c3f-4301-b2df-16d3ef760156', 'Battle ropes slams', 6, 25, 256, 24, 'Intermedio', 'Eleva ambas cuerdas sobre la cabeza y golpéalas contra el suelo con fuerza máxima. Usa todo el cuerpo en el movimiento, no solo los brazos. Mantén un ritmo constante y explosivo. Excelente para desarrollar potencia.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Battle Rope Slams', 'Raise both ropes overhead and hit them against the ground with maximum force. Use your entire body in the movement, not just your arms. Maintain a constant and explosive rhythm. Excellent for developing power.', 'external'),
('f86dad4c-2dd7-43a4-8719-59fdf34e59df', 'Carga maleta', 25, 100, 81, 1, 'Avanzado', 'Camina sosteniendo peso solo en un lado como una maleta pesada. Máximo desafío anti-flexión lateral del core. Mantén hombros nivelados y postura erguida. Cambia de lado a mitad de distancia o en series separadas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Suitcase load', 'Walks holding weight only on one side like a heavy suitcase. Maximum anti-lateral flexion challenge of the core. Maintain level shoulders and upright posture. Switch sides halfway through or in separate sets.', 'external'),
('f8974e50-d2ff-43c9-938b-9045d76e8535', 'Battle ropes single arm', 6, 25, 256, 24, 'Intermedio', 'Ondas con un solo brazo mientras el otro descansa o se mantiene estático. Permite trabajar unilateralmente y con mayor intensidad por brazo. Alterna los brazos en intervalos. Mantén la postura estable.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Single-Arm Battle Rope Waves', 'Waves with one arm while the other rests or remains static. It allows you to work unilaterally and with greater intensity per arm. Alternate arms at intervals. Keep your posture stable.', 'external'),
('f8cf4c0c-6440-4934-a7d1-d86f9a0832fd', 'Step Up alterno Front Rack con mancuernas', 28, 29, 81, 1, 'Intermedio', 'Sube al banco sosteniendo las mancuernas a la altura de los hombros (front rack). Alterna la pierna que lidera el movimiento.', FALSE, NULL, '2026-02-02T14:49:18.13947+00:00', 'Alternating Front Rack Dumbbell Step-up', 'Step onto the box while holding the dumbbells at shoulder height in the front rack position. Alternate the leading leg on each rep.', 'external'),
('f8ec8185-07be-4191-8564-9b2066cf079e', 'Cruce de poleas (enfocado pectoral superior)', 1, 6, 151, 1, 'Intermedio', 'Poleas en posición baja, junta manos frente a la cara. Objetivo: haz clavicular del pectoral. Cue: codos semiflexionados. Error común: encoger hombros al subir.', FALSE, NULL, '2026-01-16T12:30:52.089601+00:00', 'Pulley Crossover (upper Pectoral Focus)', 'Pulleys in low position, bring your hands together in front of face. Target: clavicular bundle of your chestis. Cue: semi-flexed elbows. Common mistake: shrugging shoulders when climbing.', 'external'),
('f8f8c8db-102e-4795-b806-9f6249fff95e', 'Peso muerto a una pierna', 55, 29, 81, 1, 'Intermedio', 'Realiza un peso muerto a una pierna inclinando el tronco desde la cadera mientras la pierna libre se desplaza hacia atrás. Mantén la espalda neutra y vuelve activando glúteo e isquios.', FALSE, NULL, '2026-04-30T14:20:39.77297+00:00', 'Single-Leg Romanian Deadlift', 'Perform a single-leg Romanian deadlift by hinging at the hip while the free leg moves backward. Keep the back neutral and return by engaging the glutes and hamstrings.', 'mixed'),
('f9054898-a3fd-489f-9239-9da1bed52007', 'Curl de bíceps sentado con mancuernas', 17, NULL, 81, 1, 'Principiante', 'Sentado con espalda apoyada, flexiona las mancuernas alternativamente o a la vez. Objetivo: bíceps. Cue: codos fijos al costado del cuerpo. Error: balancear el tronco para subir el peso.', FALSE, NULL, '2025-12-22T20:21:57.362585+00:00', 'Seated Dumbbell Biceps Curl', 'Sitting with your back supported, flex the dumbbells alternately or at the same time. Target: biceps. Cue: elbows fixed to the side of the body. Common mistake: swinging the torso to increase the weight.', 'external'),
('f90f1a5f-6ec3-4b42-a15d-3d17372d74b9', 'Curl de bíceps agarre de cuernos con Kettlebell', 17, 100, 281, 1, 'Principiante', 'De pie, sujeta la pesa rusa por los cuernos laterales. Realiza curls de bíceps manteniendo los codos pegados a las costillas.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Kettlebell Horn Grip Biceps Curl', 'Standing, hold the kettlebell by the side horns. Perform bicep curls keeping your elbows close to your ribs.', 'external'),
('f9274a29-b3ba-464c-8a0d-68f5f3a80732', 'Máquina de abductores', 37, 29, 186, 1, 'Principiante', 'Abre piernas sentado contra resistencia. Objetivo: glúteo medio. Cues: espalda en respaldo. Error común: inclinarse adelante para ayudar.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Abductor Machine', 'Spread your legs sitting against resistance. Target: glutes medius. Cue: back to backrest. Common mistake: leaning forward to help.', 'external'),
('f927b171-8cc1-48d4-a556-258fe3bc0038', 'Calf raises single leg', 64, NULL, 1, 1, 'Intermedio', 'De pie sobre una pierna, elévate sobre la punta del pie lo más alto posible contrayendo el gemelo. Mantén el equilibrio sin apoyar la pierna libre. Desciende lentamente para maximizar el tiempo bajo tensión. Puedes sujetarte ligeramente para mantener el equilibrio si es necesario.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Calf raises single leg', 'Standing on one leg, rise on the balls of your feet as high as possible by contracting your calf. Maintain your balance without supporting your free leg. Descend slowly to maximize time under tension. You can hold on lightly for balance if necessary.', 'mixed'),
('f9349e5d-8606-4904-aa0e-f5686cdcb172', 'Peso muerto barra', 55, 29, 116, 1, 'Avanzado', 'Con la barra en el suelo, agárrala con las manos fuera de las piernas. Mantén la espalda recta, el pecho elevado y tira de la barra pegada al cuerpo hasta la extensión completa de caderas. Es uno de los ejercicios más completos para desarrollar fuerza total.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Bar Deadlift', 'With the bar on the floor, grab it with your hands outside your legs. Keep your back straight, chest raised, and pull the bar close to your body until your hips are fully extended. It is one of the most complete exercises to develop total strength.', 'external'),
('f9413669-385c-4c6a-8f4b-47fb47ab8345', 'Press landmine', 6, 25, 116, 1, 'Avanzado', 'Press con barra anclada en landmine. El arco de movimiento es más natural para el hombro. Puede hacerse unilateral o bilateral, de rodillas o de pie. Excelente para quienes tienen limitaciones en press overhead tradicional.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Press landmine', 'Press with bar anchored in landmine. The arc of motion is more natural for the shoulder. It can be done unilateral or bilateral, kneeling or standing. Excellent for those who have limitations in traditional overhead pressing.', 'external'),
('f95ed1d1-847a-4896-a4f5-85870bacebcc', 'Salto pogo circular', 64, 25, 1, 1, 'Intermedio', 'Saltos pogo rápidos mientras rotas el cuerpo en un círculo pequeño. Mejora la agilidad de los pies y el equilibrio dinámico. Cue: tobillos tensos. Error común: hacer círculos demasiado grandes perdiendo rapidez.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Circular Pogo Jump', 'Quick pogo jumps while rotating your body in a small circle. Improves foot agility and dynamic balance. Cue: tight ankles. Common mistake: making circles that are too large, losing speed.', 'bodyweight'),
('f9759f4d-7399-4efe-8a96-c671a3bccd37', 'Remo en cable sentado', 71, 17, 151, 1, 'Intermedio', 'Remo sentado en polea para espalda, enfatizando retracción escapular y control del torso sin balanceo.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Seated Cable Row', 'Seated cable row for back, emphasizing scapular retraction and torso control without rocking.', 'external'),
('f9a04ae3-ab31-475a-bbb7-db728864a1a5', 'Sentadilla matrix', 28, 29, 1, 1, 'Avanzado', 'Sentadilla con inclinación posterior extrema del torso, casi paralelo al suelo. Requiere fuerza y flexibilidad excepcionales en tobillos y caderas. Popularizada por la película Matrix. Comienza con inclinaciones menores y progresa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Matrix squat', 'Squat with extreme posterior inclination of the torso, almost parallel to the ground. Requires exceptional strength and flexibility in the ankles and hips. Popularized by the movie Matrix. Start with smaller inclines and work your way up.', 'mixed'),
('f9afdbea-415c-4176-9b9b-1cef274c575b', 'Sentadilla con barra tras nuca', 28, 29, 116, 1, 'Principiante', 'Barra sobre los trapecios, baja la cadera manteniendo el torso estable y sube. Cue: rodillas hacia afuera. Error: levantar los talones del suelo.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Barbell Squat Behind the Neck', 'Bar on the traps, lower the hips keeping the torso stable and go up. Cue: knees out. Common mistake: lifting your heels off the ground.', 'external'),
('f9b0f414-ad7d-4c9f-be60-6155714ebbc1', 'Sentadilla overhead con barra', 13, 6, 116, 1, 'Avanzado', 'Realiza una sentadilla con la barra bloqueada sobre la cabeza con agarre ancho. Objetivo: movilidad total y potencia. Cues: empuja la barra hacia el techo constantemente. Error común: perder la verticalidad de la barra dejándola caer hacia adelante.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Barbell Overhead Squat', 'Perform a squat with the barbell locked overhead with a wide grip. Target: total mobility and power. Cue: Push the bar towards the ceiling constantly. Common mistake: losing the verticality of the bar by letting it fall forward.', 'external'),
('f9e344ad-ea50-4a86-9ab9-3e0e74784638', 'Sentadilla Ciclista con Kettlebell Bottoms Up (Horn)', 28, 29, 281, 1, 'Intermedio', 'Eleva talones y sujeta la Kettlebell invertida por los cuernos frente al pecho para un mayor desafio de estabilidad durante la sentadilla.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Bottoms-Up Kettlebell Cycle Squat (horn)', 'Raise your heels and hold the inverted kettlebell by the horns in front of your chest for a greater stability challenge during the squat.', 'external'),
('f9fadfe5-4c0a-43ce-98af-c334b796100b', 'Sit-ups completos', 25, 28, 1, 1, 'Principiante', 'Incorporación completa desde tumbado hasta tocar los pies. Objetivo: recto abdominal y flexores de cadera. Cue: baja vértebra a vértebra de forma controlada. Error común: despegar los pies del suelo para subir.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Complete Sit-ups', 'Complete incorporation from lying down to touching the feet. Target: rectus abdominis and hip flexors. Cue: lower vertebra by vertebra in a controlled manner. Common mistake: taking your feet off the ground to climb.', 'mixed'),
('fa31bc9f-a993-49df-8cbd-d15ddd8f62d1', 'Jalón supino estrecho bíceps', 16, 17, 186, 1, 'Principiante', 'Tira al pecho palmas hacia ti. Cue: codos abajo. Error: balanceo.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Tight Biceps Supine Pulldown', 'Throw your palms towards your chest. Cue: elbows down. Common mistake: swinging.', 'external'),
('fa37fe81-f3d0-4beb-b130-35dfb7ffe440', 'Step up con salto unilateral', 28, 64, 1, 1, 'Intermedio', 'Sube al banco y salta lo más alto posible aterrizando sobre el mismo pie. Potencia unilateral. Cue: rodilla estable. Error común: aterrizar sobre el borde del banco.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Single-Leg Jump Step-up', 'Step onto the bench and jump as high as possible, landing on the same leg. Builds unilateral power. Cue: keep the knee stable. Common mistake: collapsing inward on landing.', 'mixed'),
('fa4179b0-c88a-4528-8fe0-f07812aa5fa9', 'Elevaciones frontales banco inclinado', 6, NULL, 81, 1, 'Intermedio', 'Pecho en banco, eleva pesas al frente. Objetivo: deltoides anterior aislado. Cue: controla bajada. Error: usar impulso.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Incline Bench Front Raises', 'Chest on bench, raise weights in front. Target: isolated anterior deltoid. Cue: controls descent. Common mistake: use boost.', 'external'),
('fa7b096d-323a-422a-a019-1a54876493b2', 'Curl de muñeca invertido con barra', 100, NULL, 116, 1, 'Principiante', 'Apoya antebrazos y eleva el dorso de la mano con palmas hacia abajo. Objetivo: extensores de muñeca. Cue: controla la bajada del peso. Error común: usar el hombro para dar impulso.', FALSE, NULL, '2026-01-16T12:43:08.400112+00:00', 'Barbell Inverted Wrist Curl', 'Support your forearms and raise the back of your hand with palms facing down. Target: wrist extensors. Cue: controls the weight loss. Common mistake: using your shoulder to give momentum.', 'external'),
('fa894b36-7ab2-4ac4-871b-8c35f4a6ee6f', 'Jalones cerrados al pecho', 16, 17, 151, 1, 'Intermedio', 'Realiza un jalón al pecho con agarre cerrado. Lleva el agarre hacia la parte alta del pecho manteniendo el torso estable y controlando la subida.', FALSE, NULL, '2026-04-30T14:28:13.180249+00:00', 'Close-Grip Lat Pulldown', 'Perform a close-grip lat pulldown. Pull the handle toward the upper chest while keeping the torso stable and controlling the return.', 'external'),
('faa7e564-04d0-4cf1-b337-343669a3ec81', 'Salto vertical desde arrodillado', 29, 28, 1, 1, 'Avanzado', 'Desde posición de rodillas, realiza un golpe de cadera explosivo para caer de pie en sentadilla. Requiere gran potencia de glúteo. Cue: balancea los brazos para impulsarte. Error común: usar las manos en el suelo para subir.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Vertical Jump From Kneeling', 'From a kneeling position, perform an explosive hip thrust to land standing in a squat. Requires great gluteal power. Cue: swing your arms to propel yourself. Common mistake: using your hands on the ground to climb.', 'mixed'),
('fabde350-b639-4130-a4f5-0e2cebd3dbc9', 'Lanzamiento estilo saque de banda', 2, 16, 240, 1, 'Principiante', 'Lanza el balón medicinal desde detrás de la cabeza hacia adelante con fuerza. Objetivo: potencia de tríceps y serrato. Cue: pies bien anclados. Error común: soltar el balón demasiado tarde.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Throw-in Style Throw', 'Throw the medicine ball from behind your head forward with force. Objective: triceps and serratus power. Cue: feet well anchored. Common mistake: releasing the ball too late.', 'external'),
('fadfbf5a-5e7d-4a90-b7af-d01ee06b47fe', 'Straddle Front Lever en anillas', 25, 16, 1, 24, 'Avanzado', 'Posicion de Front Lever manteniendo el cuerpo paralelo al suelo con los brazos rectos y las piernas estiradas y abiertas en forma de V.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Straddle Front Lever on Rings', 'Hold a front lever on the rings with your body parallel to the floor, arms straight, and legs extended in a straddle position.', 'bodyweight'),
('fae6ff9f-28ef-4c2d-bbe8-2ae642b7bad9', 'Elevación de talón isométrica en prensa unilateral', 64, 309, 186, 1, 'Avanzado', 'Trabajo de gemelo en prensa a una pierna con contracción isométrica para fuerza del tobillo y prevención en carrera.', FALSE, NULL, '2025-12-22T19:37:20.410826+00:00', 'Unilateral Press Isometric Heel Raise', 'Calf work in one-leg press with isometric contraction for ankle strength and running prevention.', 'external'),
('fb22eca9-c390-439b-976d-43414f73b42d', 'Peso muerto jefferson', 55, 29, 116, 1, 'Avanzado', 'Peso muerto con la barra entre las piernas, un pie adelante y otro atrás. Trabaja el cuerpo de forma asimétrica. Reduce estrés en espalda baja. Alterna la posición de pies. Poco común pero efectivo.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Jefferson Deadlift', 'Deadlift with the bar between your legs, one foot forward and one foot back. Work the body asymmetrically. Reduces stress on the lower back. Alternate foot position. Uncommon but effective.', 'external'),
('fb242680-dcc6-4f6a-b36c-d66604e9d590', 'Peso muerto landmine', 55, 29, 116, 1, 'Avanzado', 'Peso muerto con un extremo de la barra anclado en landmine o esquina. Permite un arco de movimiento único. Más amigable para la espalda baja. Puede hacerse con agarre paralelo usando accesorio o perpendicular.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Landmine Deadlift', 'Deadlift with one end of the bar anchored in landmine or corner. Allows a unique arc of motion. More friendly to the lower back. It can be done with parallel grip using accessory or perpendicular.', 'external'),
('fb48f12a-83b9-4039-a90c-0e0eae7be43b', 'Landmine Press unilateral', 6, 2, 116, 1, 'Intermedio', 'Barra anclada en una esquina, empuja desde el hombro hacia adelante y arriba. Cue: inclínate ligeramente hacia la barra. Error: rotar el tronco al empujar.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'One-sided Landmine Press', 'Bar anchored in a corner, push from the shoulder forward and up. Cue: lean slightly towards the bar. Common mistake: rotating the torso when pushing.', 'external'),
('fb5b656e-4b18-4118-a83e-f3a86b76a84c', 'Clean con Kettlebell a una mano', 29, 6, 281, 1, 'Intermedio', 'Lleva la Kettlebell desde el suelo hasta la posición de rack en un movimiento fluido, rotando la pesa alrededor del antebrazo con suavidad.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-Handed Kettlebell Clean', 'Bring the kettlebell from the floor to the rack position in one fluid motion, rotating the weight around your forearm gently.', 'external'),
('fb623f32-873d-45df-9615-9c1551f1e9b1', 'Push Press a una mano con Kettlebell', 6, 28, 281, 1, 'Intermedio', 'Flexiona ligeramente las rodillas y usa el impulso de las piernas para lanzar una pesa rusa sobre la cabeza, terminando con brazo estirado.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'One-Handed kettlebell Push Press', 'Bend your knees slightly and use the momentum of your legs to throw a kettlebell overhead, ending with your arm straight.', 'external'),
('fba67106-35e7-4485-818d-823e8bddc892', 'Espiral un brazo battle ropes', 6, 25, 256, 24, 'Avanzado', 'Movimientos circulares con una sola cuerda mientras la otra descansa o realiza otro patrón. Permite mayor intensidad por brazo y trabajo unilateral. Mantén el core estable para resistir rotación.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Spiral one arm battle ropes', 'Circular movements with a single rope while the other rests or performs another pattern. Allows greater intensity per arm and unilateral work. Keep your core stable to resist rotation.', 'external'),
('fbc4ea2d-d739-49f5-8e44-70255f781618', 'Power pull TRX', 16, 17, 216, 1, 'Intermedio', 'Remo unilateral con rotación del torso. Combina tracción con rotación para un trabajo más funcional. Excelente para deportes que requieren movimientos de tracción con rotación. Mantén el core activado.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Power pull TRX', 'Unilateral row with torso rotation. Combines traction with rotation for a more functional work. Excellent for sports that require pulling movements with rotation. Keep your core activated.', 'bodyweight'),
('fbc82fbd-d57a-478b-8fd0-e72a78e8b66a', 'Pantorrillas sentado máquina', 309, NULL, 186, 1, 'Principiante', 'Sentado con las rodillas flexionadas a 90 grados, realiza elevaciones de talones. Esta posición enfatiza el sóleo más que el gemelo. Realiza el movimiento completo desde el estiramiento máximo hasta la contracción completa.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Seated calves machine', 'Sitting with your knees bent at 90 degrees, perform heel raises. This position emphasizes the soleus more than the gastrocnemius. Perform the complete movement from maximum stretch to full contraction.', 'external'),
('fbe5f913-9d48-4a03-9e2e-b0f3e6219d52', 'Golpeo overhead battle ropes', 6, 25, 256, 24, 'Avanzado', 'Slams desde posición completamente extendida sobre la cabeza. Máxima potencia y rango de movimiento. Involucra extensión de todo el cuerpo. Los slams deben ser explosivos y continuos.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'I hit overhead battle ropes', 'Slams from a fully extended position overhead. Maximum power and range of motion. Involves extension of the entire body. Slams must be explosive and continuous.', 'external'),
('fc0ba832-704a-4453-91b1-d96976a8a98a', 'Lanzamiento rotacional a pared inclinado', 25, 6, 240, 1, 'Intermedio', 'Lanzamiento de balón medicinal lateral con el torso inclinado hacia adelante. Objetivo: oblicuos y potencia rotacional. Cue: espalda plana. Error común: arquear la lumbar.', FALSE, NULL, '2025-12-22T20:01:28.444599+00:00', 'Rotational Incline Wall Throw', 'Lateral medicine ball throw with the torso leaning forward. Target: obliques and rotational power. Cue: flat back. Common mistake: arching the lower back.', 'external'),
('fc2bd73a-7c20-4a49-ae8c-4c0ab37fcb8e', 'Dominadas supinas (Chin-ups)', 17, 16, 1, 1, 'Principiante', 'Agarre con palmas hacia ti, tira hasta pasar la barbilla. Mayor énfasis en bíceps. Cue: codos hacia abajo. Error: no completar el rango de movimiento inferior.', FALSE, NULL, '2025-12-22T20:15:50.006237+00:00', 'Supine Chin-ups', 'Grip with palms facing you, pull past the chin. Greater emphasis on biceps. Cue: elbows down. Common mistake: Not completing the lower range of motion.', 'mixed'),
('fc44b253-a3e0-41b1-b0a9-8667bfba61b2', 'Sentadilla Ciclista con Kettlebell a una mano (Maleta)', 28, 29, 281, 1, 'Principiante', 'Con talones elevados, realiza una sentadilla profunda sosteniendo una sola pesa rusa en un lado del cuerpo para desafiar la estabilidad lateral.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Cycling Squat with One-handed Kettlebell (suitcase)', 'With heels raised, perform a deep squat holding a single kettlebell on one side of the body to challenge lateral stability.', 'external'),
('fc4f0c5b-6933-4e48-b73b-d0977e2d22c8', 'Curl concentrado pie inclinado', 17, NULL, 81, 1, 'Intermedio', 'Flexiona bíceps inclinado sin apoyo. Cue: brazo cuelga vertical. Error: balancear hombro.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Incline Standing Concentrated Curl', 'Incline bicep curls without support. Cue: arm hangs vertical. Common mistake: shoulder swing.', 'external'),
('fcaf1c4d-0348-4f1b-904c-f08530381e22', 'Sentadilla Goblet con Kettlebell', 28, 29, 281, 1, 'Principiante', 'Sujeta la Kettlebell por los cuernos frente al pecho y realiza una sentadilla profunda manteniendo el torso erguido y talones apoyados.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Kettlebell Goblet Squat', 'Hold the kettlebell by the horns in front of your chest and perform a deep squat, keeping your torso upright and heels supported.', 'external'),
('fcb5f2a7-fd48-466b-b9eb-416f30c0adc5', 'Press de banca a una mano con Kettlebell Bottoms Up', 1, 2, 281, 1, 'Intermedio', 'Tumbado boca arriba, presiona una sola Kettlebell invertida hacia el techo, exigiendo máximo control del antebrazo y hombro.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'One-handed Bench Press with Bottoms-Up Kettlebell', 'Lying on your back, press a single inverted kettlebell toward the ceiling, demanding maximum forearm and shoulder control.', 'external'),
('fcb9b007-a2d9-4c42-82b8-03b2fe875a4c', 'Sentadilla camarón completa', 28, 29, 1, 1, 'Avanzado', 'Sentadilla unilateral sujetando el pie de la pierna libre detrás con ambas manos. Requiere gran flexibilidad en cuádriceps y fuerza unilateral. El equilibrio es extremadamente desafiante. Progresa desde versiones asistidas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Complete shrimp squat', 'Unilateral squat holding the foot of the free leg behind with both hands. Requires great flexibility in the quadriceps and unilateral strength. Balance is extremely challenging. Progress from assisted versions.', 'mixed'),
('fcba4e19-514a-4567-be2b-0446c2c0dbd4', 'Burpee', 13, 1, 1, 1, 'Intermedio', 'Desde de pie, agáchate, lanza pies atrás a plancha, haz una flexión, recoge pies y salta verticalmente.', FALSE, NULL, '2026-02-02T13:33:05.856042+00:00', 'Burpee', 'From a standing position, squat down, throw your feet back into a plank, do a push-up, pick your feet up and jump vertically.', 'mixed'),
('fce243ef-b793-4a26-8ff5-221e7b186023', 'Flexión isquio cable', 55, NULL, 151, 1, 'Principiante', 'Tumbado boca abajo o de pie con tobillera en polea baja, flexiona la rodilla llevando el talón hacia el glúteo. Mantén la cadera extendida y evita arquear la espalda. El cable proporciona resistencia uniforme durante todo el movimiento.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Cable Leg Curl', 'Lie face down or stand with an ankle strap attached to a low cable and bend your knee to bring your heel toward your glutes. Keep your hips extended and avoid arching your back. The cable provides even resistance throughout the movement.', 'external'),
('fd21f275-b16f-424c-a144-65e8f6bcb15e', 'Dominadas agarre neutro', 16, 17, 1, 1, 'Intermedio', 'Sube en barras paralelas. Objetivo: espalda y bíceps. Cue: junta escápulas. Error: rango parcial.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Neutral Grip Pull-ups', 'Climb parallel bars. Target: back and biceps. Cue: bring your shoulder blades together. Common mistake: partial range.', 'mixed'),
('fd54fc0b-7123-4217-bda1-f4b0cc455261', 'Sprint slam', 28, 25, 240, 1, 'Avanzado', 'Corre hacia el balón, recógelo y realiza un slam explosivo. Combina velocidad con potencia. Puede hacerse en distancias cortas o como parte de un circuito. Mantén la intensidad alta durante todo el ejercicio.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Sprint Slam', 'Run towards the ball, pick it up and perform an explosive slam. Combine speed with power. It can be done over short distances or as part of a circuit. Keep the intensity high throughout the exercise.', 'external'),
('fd5becb4-0d27-4848-9ead-986338b3046e', 'Clean a Zancada inversa contralateral Front Rack con Kettlebell', 28, 29, 281, 1, 'Intermedio', 'Realiza una cargada al hombro y ejecuta una zancada atras con la pierna del lado opuesto a la pesa rusa.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Clean to Contralateral Front Rack Reverse Lunge with Kettlebell', 'Perform a shoulder clean and perform a back lunge with the leg on the opposite side of the kettlebell.', 'external'),
('fd6b3a86-1b09-483c-8b47-24a109d71e4a', 'Outside Clean con Kettlebell doble', 29, 71, 281, 1, 'Intermedio', 'Carga dos Kettlebells hacia los hombros balanceandolas por fuera de las piernas, manteniendo los codos pegados al cuerpo al recibir el peso.', FALSE, NULL, '2026-02-02T16:04:23.097212+00:00', 'Outside Clean with Double Kettlebell', 'Carry two kettlebells towards your shoulders, swinging them outside your legs, keeping your elbows close to your body as you receive the weight.', 'external'),
('fd6bdc39-476a-4eab-b28a-d084290e9cc8', 'Sentadilla Búlgara contralateral Front Rack con Kettlebell Bottoms Up', 28, 29, 281, 1, 'Intermedio', 'Con un pie elevado, sostén una Kettlebell invertida en el hombro opuesto a la pierna delantera. Baja en sentadilla split trabajando la estabilidad cruzada.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Contralateral Front Rack Bottoms-Up Bulgarian Split Squat with Kettlebell', 'With one foot raised, hold an inverted kettlebell on the shoulder opposite your front leg. Lower into a split squat working on crossed stability.', 'external'),
('fd80efb1-b201-4381-b410-1b65ad383188', 'Flexión con alcance de rodillas alterno sobre Slider', 1, 2, 1, 1, 'Intermedio', 'Ejecuta flexiones de rodillas alternando el brazo que se desliza hacia adelante en cada repeticion para trabajar la estabilidad del core.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Alternating Knee Reach Push-Up on Slider', 'Perform knee curls alternating the arm that slides forward with each repetition to work on core stability.', 'bodyweight'),
('fdb9cf74-ed8b-470b-82ea-78649c614419', 'Hang Power Clean con barra', 29, 55, 116, 1, 'Intermedio', 'Iniciando con la barra sobre las rodillas, realiza una extension explosiva de cadera para llevar la barra a los hombros en posicion de media sentadilla.', FALSE, NULL, '2026-02-02T15:20:57.453982+00:00', 'Hang Power Clean with bar', 'Starting with the bar on your knees, perform an explosive hip extension to bring the bar to your shoulders in a half-squat position.', 'external'),
('fdcc8382-bfd9-455d-a3d3-f420ee948ada', 'Peso muerto maleta con mancuerna a una mano', 71, 55, 81, 1, 'Intermedio', 'Realiza un peso muerto convencional sosteniendo una mancuerna solo en un lado. Evita que el torso se incline lateralmente.', FALSE, NULL, '2026-02-02T13:37:05.054376+00:00', 'Suitcase deadlift with one-hand dumbbell', 'Perform a conventional deadlift holding a dumbbell on one side only. Prevents the torso from leaning laterally.', 'external'),
('fde505f4-367f-44f0-a9f2-e4828cbf9fbc', 'Tuck Front Lever en anillas', 25, 16, 1, 24, 'Avanzado', 'Cuelgate de las anillas y eleva el cuerpo hasta quedar paralelo al suelo con las rodillas encogidas hacia el pecho y los brazos completamente rectos.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'Tuck Front Lever on Rings', 'Hang from the rings and raise your body until it is parallel to the floor with your knees tucked toward your chest and your arms fully straight.', 'bodyweight'),
('fdf15a5a-1d9a-4cf9-91bd-c7b44cbe865e', 'Suspension Lateral Knee Tuck', 25, 6, 216, 1, 'Intermedio', 'En posición de plancha con pies en TRX, lleva ambas rodillas hacia un codo para trabajar los oblicuos, regresa al centro y repite hacia el otro lado.', FALSE, NULL, '2026-02-02T12:41:44.70854+00:00', 'Suspension Side Knee Tuck', 'In a plank position with your feet in the TRX, bring both knees toward one elbow to work the obliques, return to the center, and repeat to the other side.', 'bodyweight'),
('fe21e489-f5de-4fec-a4af-39fd55e3da72', 'Dips máquina', 2, 1, 186, 1, 'Principiante', 'Fondos asistidos en máquina que reduce el peso corporal. Ideal para principiantes que no pueden hacer fondos libres. Ajusta la asistencia progresivamente. Inclínate hacia adelante para más énfasis en pecho o mantente vertical para tríceps.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Dips machine', 'Machine-assisted dips that reduce body weight. Ideal for beginners who can''t do free dips. Adjust assistance progressively. Lean forward for more emphasis on chest or stay vertical for triceps.', 'assisted'),
('fe5bf426-e843-4d5c-84c6-2774cca86457', 'Step Up ipsilateral Front Rack con Kettlebell a una mano Bottoms Up', 28, 100, 281, 1, 'Avanzado', 'Sube al banco con la pierna del mismo lado que la Kettlebell invertida sostenida en rack, exigiendo máximo control unilateral.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Ipsilateral Single-Kettlebell Bottoms-Up Front Rack Step-up', 'Step onto the bench with the leg on the same side as the upside-down kettlebell held in the rack position, requiring maximum unilateral control.', 'external'),
('fe879db0-8615-434f-8d9d-be049a7ffc5d', 'Curl bíceps sentado alterno', 17, NULL, 81, 1, 'Principiante', 'Flexiona mancuernas alternando brazos. Objetivo: bíceps. Cue: gira palma al subir. Error: balanceo.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Alternating Seated Biceps Curl', 'Curl the dumbbells alternately. Target: biceps. Cue: rotate your palm upward as you lift. Common mistake: swinging.', 'external'),
('fe98f5c9-181b-4bf8-a196-af3ae2be2d2d', 'Curl de bíceps concentrado', 17, NULL, 81, 1, 'Principiante', 'Sentado, codo apoyado en el muslo interno, flexiona la mancuerna. Aislamiento máximo. Control total. No uses el cuerpo para balancear.', FALSE, NULL, '2025-12-22T20:11:04.093175+00:00', 'Concentrated biceps curl', 'Sitting, elbow resting on your inner thigh, flex the dumbbell. Maximum insulation. Full control. Don''t use your body to balance.', 'external'),
('fea0fa90-9b6d-415f-b7ad-c63bf9d1bacd', 'Tuck L-Sit en paralelas', 25, 2, 1, 24, 'Intermedio', 'Sostente sobre las barras paralelas con los brazos estirados y eleva las rodillas hacia el pecho manteniendo la posicion de forma isometrica.', FALSE, NULL, '2026-02-02T15:01:57.762415+00:00', 'Tuck L-Sit on Parallel Bars', 'Support yourself on the parallel bars with your arms straight and lift your knees toward your chest while holding the isometric position.', 'bodyweight'),
('feb19895-c99f-47f4-98b4-d72854019689', 'Peso muerto rumano con Kettlebell doble', 55, 29, 281, 1, 'Principiante', 'Con una pesa en cada mano, inclina el torso hacia adelante empujando la cadera atrás con las rodillas semi-flexionadas hasta sentir estiramiento en los isquios.', FALSE, NULL, '2026-02-02T15:44:18.337829+00:00', 'Double Kettlebell Romanian Deadlift', 'Hold a kettlebell in each hand and hinge your torso forward, pushing your hips back with your knees slightly bent until you feel a stretch in your hamstrings.', 'external'),
('feda3b21-a7ad-45c1-b65d-5dc8551e94ea', 'Remo en máquina con apoyo de pecho', 71, 17, 186, 1, 'Principiante', 'Tira de los agarres con el pecho en soporte. Objetivo: espalda media. Cues: estira hombro al bajar. Error común: rotar el torso.', FALSE, NULL, '2026-01-16T12:40:12.96782+00:00', 'Rowing Machine with Chest Support', 'Pull on the grips with your chest supported. Target: mid back. Cue: stretch your shoulder when going down. Common mistake: rotating the torso.', 'external'),
('ff135d58-59dc-4ba4-85ed-e3af7255add8', 'Skullcrushers mancuernas', 2, NULL, 81, 1, 'Intermedio', 'Baja mancuernas a orejas tumbado. Objetivo: tríceps. Cue: codos al techo. Error: mover hombro.', FALSE, NULL, '2025-12-22T21:03:09.273728+00:00', 'Skullcrushers Dumbbells', 'Lower dumbbells to your ears while lying down. Target: triceps. Cue: elbows toward the ceiling. Common mistake: move shoulder.', 'external'),
('ff39db0a-6b4b-41a7-93bd-a9bce3387aa7', 'Press kettlebell', 6, 2, 281, 1, 'Intermedio', 'Desde la posición de rack, presiona la kettlebell sobre la cabeza. El diseño único de la kettlebell desafía la estabilización. Mantén el core activado y evita arquear la espalda. Puede hacerse estricto o con impulso de piernas.', FALSE, NULL, '2025-12-04T18:39:29.854044+00:00', 'Kettlebell Press', 'From the rack position, press the kettlebell overhead. The kettlebell''s unique design challenges stabilization. Keep your core activated and avoid arching your back. It can be done strictly or with leg drive.', 'external'),
('ff4ab808-e066-4777-ba72-03e2d6cab229', 'Sentadilla Búlgara asistida rodilla sobre punta del pie', 28, 29, 1, 1, 'Principiante', 'Sentadilla split con pie elevado ayudado por las manos, permitiendo que la rodilla delantera sobrepase los dedos para ganar movilidad.', FALSE, NULL, '2026-02-02T15:58:13.681079+00:00', 'Assisted Knee-On-Toe Bulgarian Squat', 'Split squat with raised foot supported by the hands, allowing the front knee to go over the fingers to gain mobility.', 'assisted'),
('ff615b5d-fac5-478f-8f73-037102efd52c', 'Press de banca agarre inverso con barra', 1, 2, 116, 1, 'Intermedio', 'Acuéstate en el banco y sujeta la barra con las palmas mirando hacia tu cara. Presiona hacia arriba enfocando el pectoral superior.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Reverse Grip Barbell Bench Press', 'Lie on the bench and hold the bar with your palms facing your face. Press up focusing on the upper pectoral.', 'external'),
('ffdc9db6-4471-4c1b-b540-e606a2267c4c', 'Press de banca con banda (Resistencia acomodada)', 1, 2, 116, 1, 'Avanzado', 'Realiza press de banca con bandas elásticas sujetas a la barra para aumentar la tensión al subir. Objetivo: fuerza de bloqueo. Cues: barra estable y core firme. Error común: dejar que la banda tire de la barra lateralmente.', FALSE, NULL, '2026-01-16T12:36:02.345066+00:00', 'Band Bench Press (accommodated Resistance)', 'Perform bench presses with elastic bands attached to the bar to increase tension when going up. Target: blocking force. Cue: stable bar and firm core. Common mistake: letting the band pull the bar laterally.', 'external');
INSERT INTO public."exercises" ("id", "base_name_es", "primary_muscle_id", "secondary_muscle_id", "equipment_id", "exercise_type_id", "difficulty", "description_es", "is_custom", "owner_user_id", "created_at", "base_name_en", "description_en", "load_type") VALUES
('ffe57f8a-9530-4e24-9dc5-668edb8f54a3', 'Alrededor del mundo a una pierna con Kettlebell', 25, 29, 281, 1, 'Intermedio', 'De pie sobre una sola pierna, pasa la Kettlebell alrededor de tu cintura de una mano a otra manteniendo el equilibrio del cuerpo.', FALSE, NULL, '2026-02-02T15:38:02.433639+00:00', 'Single-Leg Kettlebell Around the World', 'Stand on one leg and pass the kettlebell around your waist from one hand to the other while maintaining your balance.', 'external'),
('ffe7ffcf-6287-40fe-bc95-a5528de8f074', 'Pike Pushups frente manos', 6, 2, 1, 1, 'Intermedio', 'Flexión en V. Cue: baja frente ante manos. Error: codos muy abiertos.', FALSE, NULL, '2026-01-16T12:27:33.081279+00:00', 'Pike Push-ups Frente Manos', 'Perform the push-up in a V position. Cue: lower your forehead in front of your hands. Common mistake: letting your elbows flare too wide.', 'mixed'),
('fff3e543-33c4-4d4e-85be-f03bb5c608fb', 'Press Overhead Seesaw con Kettlebell doble Bottoms Up', 6, 2, 281, 1, 'Intermedio', 'Alterna el press de dos Kettlebells invertidas sobre la cabeza en un movimiento fluido, requiriendo un control absoluto de estabilidad.', FALSE, NULL, '2026-02-02T17:44:36.818237+00:00', 'Press Overhead Seesaw with Double kettlebell Bottoms Up', 'Alternate pressing two inverted kettlebells overhead in a fluid movement, requiring absolute stability control.', 'external'),
('fffc4caf-dc49-4617-b611-13fd90c479d9', 'Rollout de rodillas con barra a una mano', 25, 6, 116, 1, 'Avanzado', 'De rodillas, sujeta la barra con una sola mano y deslizala hacia adelante extendiendo el core, regresando luego a la posicion inicial.', FALSE, NULL, '2026-02-02T15:32:54.171355+00:00', 'One-Handed Kneeling Barbell Rollout', 'On your knees, hold the bar with one hand and slide it forward, extending your core, then returning to the starting position.', 'external'),
('ffff1c4e-19bf-4089-92d6-bf2a81bb7a87', 'Curl de bíceps alto con cable a una mano', 17, NULL, 151, 1, 'Principiante', 'De pie de lado a una polea alta. Con el brazo extendido lateralmente, flexiona el codo para llevar la mano hacia la oreja, manteniendo el codo alto.', FALSE, NULL, '2026-02-02T13:09:18.630316+00:00', 'One Hand Cable High Bicep Curl', 'Stand sideways to a high cable. With your arm extended laterally, bend your elbow to bring your hand up to your ear, keeping your elbow high.', 'external');
